window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["diyanet"]=[[{"n":1,"t":"Bismillâhirrahmânirrahîm."},{"n":"2-4","t":"Hamd, Âlemlerin Rabbi, Rahmân, Rahîm, hesap ve ceza gününün (ahiret gününün) mâliki Allah’a mahsustur."},{"n":5,"t":"(Allahım!) Yalnız sana ibadet ederiz ve yalnız senden yardım dileriz."},{"n":"6-7","t":"Bizi doğru yola, kendilerine nimet verdiklerinin yoluna ilet; gazaba uğrayanlarınkine ve sapıklarınkine değil."}],[{"n":1,"t":"Elif Lâm Mîm."},{"n":2,"t":"Bu, kendisinde şüphe olmayan kitaptır. Allah’a karşı gelmekten sakınanlar için yol göstericidir."},{"n":3,"t":"Onlar gaybe inanırlar, namazı dosdoğru kılarlar, kendilerine rızık olarak verdiğimizden de Allah yolunda harcarlar."},{"n":4,"t":"Onlar sana indirilene de, senden önce indirilenlere de inanırlar. Ahirete de kesin olarak inanırlar."},{"n":5,"t":"İşte onlar Rab’lerinden (gelen) bir doğru yol üzeredirler ve kurtuluşa erenler de işte onlardır."},{"n":6,"t":"Küfre saplananlara gelince, onları uyarsan da, uyarmasan da, onlar için birdir, inanmazlar."},{"n":7,"t":"Allah, onların kalplerini ve kulaklarını mühürlemiştir. Gözleri üzerinde de bir perde vardır. Onlar için büyük bir azap vardır."},{"n":8,"t":"İnsanlardan, inanmadıkları hâlde, \"Allah’a ve ahiret gününe inandık\" diyenler de vardır."},{"n":9,"t":"Bunlar Allah’ı ve mü’minleri aldatmaya çalışırlar. Oysa sadece kendilerini aldatırlar da farkında değillerdir."},{"n":10,"t":"Kalplerinde münafıklıktan kaynaklanan bir hastalık vardır. Allah da onların hastalıklarını artırmıştır. Söyledikleri yalana karşılık da onlara elem dolu bir azap vardır."},{"n":11,"t":"Bunlara, \"Yeryüzünde fesat çıkarmayın\" denildiğinde, \"Biz ancak ıslah edicileriz!\" derler."},{"n":12,"t":"İyi bilin ki, onlar bozguncuların ta kendileridir. Fakat farkında değillerdir."},{"n":13,"t":"Onlara, \"İnsanların inandıkları gibi siz de inanın\" denildiğinde ise, \"Biz de akılsızlar gibi iman mı edelim?\" derler. İyi bilin ki, asıl akılsızlar kendileridir, fakat bilmezler."},{"n":14,"t":"İman edenlerle karşılaştıkları zaman, \"İnandık\" derler. Fakat şeytanlarıyla (münafık dostlarıyla) yalnız kaldıkları zaman, \"Şüphesiz, biz sizinle beraberiz. Biz ancak onlarla alay ediyoruz\" derler."},{"n":15,"t":"Gerçekte Allah onlarla alay eder (alaylarından dolayı onları cezalandırır); azgınlıkları içinde bocalayıp dururlarken onlara mühlet verir."},{"n":16,"t":"İşte onlar, hidayete karşılık sapıklığı satın almış kimselerdir. Bu yüzden alışverişleri onlara kâr getirmemiş ve (sonuçta) doğru yolu bulamamışlardır."},{"n":17,"t":"Onların durumu, (geceleyin) ateş yakan kimsenin durumuna benzer: Ateş tam çevresini aydınlattığı sırada Allah ışıklarını yok ediverir de onları göremez bir şekilde karanlıklar içinde bırakıverir."},{"n":18,"t":"Onlar, sağırdırlar, dilsizdirler, kördürler. Artık (hakka) dönmezler."},{"n":19,"t":"Yahut onların durumu, gökten yoğun karanlıklar içinde gök gürültüsü ve şimşekle sağanak hâlinde boşanan yağmura tutulmuş kimselerin durumu gibidir. Ölüm korkusuyla, yıldırım seslerinden parmaklarını kulaklarına tıkarlar. Oysa Allah, kâfirleri çepeçevre kuşatmıştır."},{"n":20,"t":"Şimşek neredeyse gözlerini alıverecek. Önlerini her aydınlatışında ışığında yürürler. Karanlık çökünce dikilip kalırlar. Allah dileseydi, elbette onların işitme ve görme duyularını giderirdi. Şüphesiz Allah, her şeye hakkıyla gücü yetendir."},{"n":21,"t":"Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize ibadet edin ki, Allah’a karşı gelmekten sakınasınız."},{"n":22,"t":"O, yeri sizin için döşek, göğü de bina yapan, gökten su indirip onunla size rızık olarak çeşitli ürünler çıkarandır. Öyleyse siz de bile bile Allah’a ortaklar koşmayın."},{"n":23,"t":"Eğer kulumuza (Muhammed’e) indirdiğimiz (Kur’an) hakkında şüphede iseniz, haydin onun benzeri bir sûre getirin ve eğer doğru söyleyenler iseniz, Allah’tan başka şahitlerinizi çağırın (ve bunu ispat edin)."},{"n":24,"t":"Eğer, yapamazsanız -ki hiçbir zaman yapamayacaksınız- o hâlde yakıtı insanlarla taşlar olan ateşten sakının. O ateş kâfirler için hazırlanmıştır."},{"n":25,"t":"İman edip salih ameller işleyenlere, kendileri için; içinden ırmaklar akan cennetler olduğunu müjdele. Cennetlerin meyvelerinden kendilerine her rızık verilişinde, \"Bu (tıpkı) daha önce (dünyada iken) bize verilen rızık!\" diyecekler. Hâlbuki bu rızık onlara (dünyadakine) benzer olarak verilmiştir. Onlar için orada tertemiz eşler de vardır. Onlar orada ebedî kalacaklardır."},{"n":26,"t":"Allah, bir sivrisineği, ondan daha da ötesi bir varlığı örnek olarak vermekten çekinmez. İman edenler onun, Rablerinden (gelen) bir gerçek olduğunu bilirler. Küfre saplananlar ise, \"Allah, örnek olarak bununla neyi kastetmiştir?\" derler. (Allah) onunla birçoklarını saptırır, birçoklarını da doğru yola iletir. Onunla ancak fasıkları saptırır."},{"n":27,"t":"Onlar, Allah’a verdikleri sözü, pekiştirilmesinden sonra bozan, Allah’ın korunmasını emrettiği bağları (iman, akrabalık, beşerî ve ahlâkî bütün ilişkileri) koparan ve yeryüzünde bozgunculuk yapan kimselerdir. İşte onlar ziyana uğrayanların ta kendileridir."},{"n":28,"t":"Siz cansız (henüz yok) iken sizi dirilten (dünyaya getiren) Allah’ı nasıl inkâr ediyorsunuz? Sonra sizleri öldürecek, sonra yine diriltecektir. En sonunda O’na döndürüleceksiniz."},{"n":29,"t":"O, yeryüzünde olanların hepsini sizin için yaratan, sonra göğe yönelip onları yedi gök hâlinde düzenleyendir. O, her şeyi hakkıyla bilendir."},{"n":30,"t":"Hani, Rabbin meleklere, \"Ben yeryüzünde bir halife yaratacağım\" demişti. Onlar, \"Orada bozgunculuk yapacak, kan dökecek birini mi yaratacaksın? Oysa biz sana hamdederek daima seni tesbih ve takdis ediyoruz.\" demişler. Allah da, \"Ben sizin bilmediğinizi bilirim\" demişti."},{"n":31,"t":"Allah, Âdem’e bütün varlıkların isimlerini öğretti. Sonra onları meleklere göstererek, \"Eğer doğru söyleyenler iseniz, haydi bana bunların isimlerini bildirin\" dedi."},{"n":32,"t":"Melekler, \"Seni bütün eksikliklerden uzak tutarız. Senin bize öğrettiklerinden başka bizim hiçbir bilgimiz yoktur. Şüphesiz her şeyi hakkıyla bilen, her şeyi hikmetle yapan sensin\" dediler."},{"n":33,"t":"Allah, şöyle dedi: \"Ey Âdem! Onlara bunların isimlerini söyle.\" Âdem, meleklere onların isimlerini bildirince Allah, \"Size, göklerin ve yerin gaybını şüphesiz ki ben bilirim, yine açığa vurduklarınızı da, gizli tuttuklarınızı da ben bilirim demedim mi?\" dedi."},{"n":34,"t":"Hani meleklere, \"Âdem için saygı ile eğilin\" demiştik de İblis hariç bütün melekler hemen saygı ile eğilmişler, İblis (bundan) kaçınmış, büyüklük taslamış ve kâfirlerden olmuştu."},{"n":35,"t":"Dedik ki: \"Ey Âdem! Sen ve eşin cennete yerleşin. Orada dilediğiniz gibi bol bol yiyin, ama şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz.\""},{"n":36,"t":"Derken, şeytan ayaklarını oradan kaydırdı. Onları içinde bulundukları konumdan çıkardı. Bunun üzerine biz de, \"Birbirinize düşman olarak inin. Sizin için yeryüzünde belli bir süre barınak ve yararlanma vardır\" dedik."},{"n":37,"t":"Derken, Âdem (vahy yoluyla) Rabbinden birtakım kelimeler aldı, (onlarla amel edip Rabb’ine yalvardı. O da) bunun üzerine tövbesini kabul etti. Şüphesiz O, tövbeleri çok kabul edendir, çok bağışlayandır."},{"n":38,"t":"\"İnin oradan (cennetten) hepiniz. Tarafımdan size bir yol gösterici (peygamber) gelir de kim ona uyarsa, onlar için herhangi bir korku yoktur, onlar üzülmeyeceklerdir\" dedik."},{"n":39,"t":"İnkâr edenler ve âyetlerimizi yalanlayanlara gelince, işte bunlar cehennemliktir. Onlar orada ebedî kalacaklardır."},{"n":40,"t":"Ey İsrailoğulları! Size verdiğim nimeti hatırlayın. Bana verdiğiniz sözü yerine getirin ki ben de size verdiğim sözü yerine getireyim. Yalnız benden korkun."},{"n":41,"t":"Elinizdeki Tevrat’ı tasdik edici olarak indirdiğimize (Kur’an’a) iman edin. Onu inkâr edenlerin ilki olmayın. Âyetlerimi az bir karşılığa değişmeyin ve bana karşı gelmekten sakının."},{"n":42,"t":"Hakkı batılla karıştırıp da bile bile hakkı gizlemeyin."},{"n":43,"t":"Namazı kılın, zekâtı verin. Rükû edenlerle birlikte siz de rükû edin."},{"n":44,"t":"Siz Kitab’ı (Tevrat’ı) okuyup durduğunuz hâlde, kendinizi unutup başkalarına iyiliği mi emrediyorsunuz? (Yaptığınızın çirkinliğini) anlamıyor musunuz?"},{"n":45,"t":"Sabrederek ve namaz kılarak (Allah’tan) yardım dileyin. Şüphesiz namaz, Allah’a derinden saygı duyanlardan başkasına ağır gelir."},{"n":46,"t":"Onlar, Rablerine kavuşacaklarını ve gerçekten O’na döneceklerini çok iyi bilirler."},{"n":47,"t":"Ey İsrailoğulları! Size verdiğim nimetimi ve (bir zamanlar) sizi cümle âleme üstün kıldığımı hatırlayın."},{"n":48,"t":"Öyle bir günden sakının ki, o gün hiç kimse bir başkası adına bir şey ödeyemez. Hiçbir kimseden herhangi bir şefaat kabul olunmaz, fidye alınmaz. Onlara yardım da edilmez."},{"n":49,"t":"Hani, sizi azabın en kötüsüne uğratan, kadınlarınızı sağ bırakıp, oğullarınızı boğazlayan Firavun ailesinden kurtarmıştık. Bunda, size Rabbinizden (gelen) büyük bir imtihan vardı."},{"n":50,"t":"Hani, sizin için denizi yarmış, sizi kurtarmış, gözlerinizin önünde Firavun ailesini suda boğmuştuk."},{"n":51,"t":"Hani, biz Mûsâ ile kırk gece için sözleşmiştik. Sizler ise onun ardından (kendinize) zulmederek bir buzağıyı tanrı edinmiştiniz."},{"n":52,"t":"Sonra bunun ardından şükredesiniz diye sizi affetmiştik."},{"n":53,"t":"Hani, doğru yolu tutasınız diye Mûsâ’ya Kitab’ı (Tevrat’ı) ve Furkan’ı vermiştik."},{"n":54,"t":"Mûsâ, kavmine dedi ki: \"Ey kavmim! Sizler, buzağıyı ilâh edinmekle kendinize yazık ettiniz. Gelin yaratıcınıza tövbe edin de nefislerinizi öldürün (kendinizi düzeltin). Bu, Yaratıcınız katında sizin için daha iyidir. Böylece Allah da onların tövbesini kabul etti. Çünkü O, tövbeleri çok kabul edendir, çok merhametlidir.\""},{"n":55,"t":"Hani siz, \"Ey Mûsâ! Biz Allah’ı açıktan açığa görmedikçe sana asla inanmayız\" demiştiniz. Bunun üzerine siz bakıp dururken sizi yıldırım çarpmıştı."},{"n":56,"t":"Sonra, şükredesiniz diye ölümünüzün ardından sizi tekrar dirilttik."},{"n":57,"t":"Bulutu üstünüze gölge yaptık. Size, kudret helvası ile bıldırcın indirdik. \"Verdiğimiz rızıkların iyi ve güzel olanlarından yiyin\" (dedik). Onlar (verdiğimiz nimetlere nankörlük etmekle) bize zulmetmediler, fakat kendilerine zulmediyorlardı."},{"n":58,"t":"Hani, \"Şu memlekete girin. Orada dilediğiniz gibi, bol bol yiyin. Kapısından eğilerek tevazu ile girin ve \"hıtta!\" (Ya Rabbi, bizi affet) deyin ki, biz de sizin hatalarınızı bağışlayalım. İyilik edenlere ise daha da fazlasını vereceğiz\" demiştik."},{"n":59,"t":"Derken, onların içindeki zalimler, sözü kendilerine söylenenden başka şekle soktular. Biz de haktan ayrılmaları sebebiyle, o zalimlere gökten bir azap indirdik."},{"n":60,"t":"Hani, Mûsâ kavmi için su dilemişti. Biz de, \"Asanı kayaya vur\" demiştik, böylece kayadan on iki pınar fışkırmış, her boy kendi su alacağı pınarı bilmişti. \"Allah’ın rızkından yiyin, için. Yalnız, yeryüzünde bozgunculuk yaparak fesat çıkarmayın\" demiştik."},{"n":61,"t":"Hani, \"Ey Mûsâ! Biz bir çeşit yemeğe asla katlanamayız. O hâlde, bizim için Rabbine yalvar da, o bize yerden biten sebze, kabak, sarımsak, mercimek, soğan versin\" demiştiniz. O da size, \"İyi olanı düşük olanla değiştirmek mi istiyorsunuz? Öyle ise inin şehre! İstedikleriniz orada var\" demişti. Böylece zillet ve yoksulluk onları kapladı. Onlar, Allah’ın gazabına uğradılar. Bunun sebebi, onların; Allah’ın âyetlerini inkâr ediyor, peygamberleri de haksız yere öldürüyor olmaları idi. Bütün bunların sebebi ise, isyan etmek ve aşırı gitmekte oluşlarıydı."},{"n":62,"t":"Şüphesiz, inananlar (Müslümanlar) ile Yahudiler, Hıristiyanlar ve Sâbiîlerden (her bir grubun kendi şeriatında) \"Allah’a ve ahiret gününe inanan ve salih ameller işleyenler için Rableri katında mükâfat vardır; onlar korkuya uğramayacaklar, mahzun da olmayacaklardır\" (diye hükmedilmiştir)."},{"n":63,"t":"Hani, (Tevrat ile amel edeceğinize dair) sizden sağlam bir söz almış, Tûr dağını da tepenize dikmiş ve \"Sakınasınız diye, size verdiğimiz Kitab’ı sıkı tutun, onun içindekileri düşünün (gafil olmayın)\" demiştik."},{"n":64,"t":"Bundan sonra yine yüz çevirdiniz. Allah’ın bol nimeti ve merhameti olmasaydı, herhâlde ziyana uğrayanlardan olurdunuz."},{"n":65,"t":"Şüphesiz siz, içinizden Cumartesi yasağını çiğneyenleri bilirsiniz. Biz onlara, \"Aşağılık maymunlar olun\" demiştik."},{"n":66,"t":"Biz bunu, hem onu görenlere, hem de sonra geleceklere bir ibret ve Allah’a karşı gelmekten sakınanlara da bir öğüt kıldık."},{"n":67,"t":"Hani Mûsâ kavmine, \"Allah, size bir sığır kesmenizi emrediyor\" demişti. Onlar da, \"Sen bizimle eğleniyor musun?\" demişlerdi. Mûsâ, \"Kendini bilmez cahillerden olmaktan Allah’a sığınırım\" demişti."},{"n":68,"t":"\"Bizim için Rabbine dua et de onun nasıl bir sığır olduğunu bize açıklasın.\" dediler. Mûsâ şöyle dedi: \"Rabbim diyor ki: O, ne yaşlı, ne körpe, ikisi arası bir sığırdır. Haydi, emrolunduğunuz işi yapın.\""},{"n":69,"t":"Onlar, \"Bizim için Rabbine dua et de, rengi neymiş? açıklasın\" dediler. Mûsâ şöyle dedi: \"Rabbim diyor ki, o, sapsarı; rengi, bakanların içini açan bir sığırdır\" dedi."},{"n":70,"t":"\"Bizim için Rabbine dua et de onun nasıl bir sığır olduğunu bize açıklasın. Çünkü sığırlar, bizce, birbirlerine benzemektedir. Ama Allah dilerse elbet buluruz\" dediler."},{"n":71,"t":"Mûsâ şöyle dedi: \"Rabbim diyor ki; o, çift sürmek, ekin sulamak için boyunduruğa vurulmamış, kusursuz, hiç alacası olmayan bir sığırdır.\" Onlar, \"İşte, şimdi tam doğrusunu bildirdin\" dediler. Nihayet o sığırı kestiler. Neredeyse bunu yapmayacaklardı."},{"n":72,"t":"Hani, bir kimseyi öldürmüştünüz de suçu birbirinizin üstüne atmıştınız. Hâlbuki Allah, gizlemekte olduğunuzu ortaya çıkaracaktı."},{"n":73,"t":"\"Sığırın bir parçası ile öldürülene vurun\" dedik. (Denileni yaptılar ve ölü dirildi.) İşte, Allah ölüleri böyle diriltir, düşünesiniz diye mucizelerini de size böyle gösterir."},{"n":74,"t":"Sonra bunun ardından kalpleriniz yine katılaştı; taş gibi, hatta daha katı oldu. Çünkü taş vardır ki, içinden ırmaklar fışkırır. Taş vardır ki yarılır da içinden sular çıkar. Taş da vardır ki, Allah korkusuyla (yerinden kopup) düşer. Allah, yaptıklarınızdan hiçbir zaman habersiz değildir."},{"n":75,"t":"Şimdi, bunların size inanacaklarını mı umuyorsunuz? Oysa içlerinden birtakımı, Allah’ın kelamını dinler, iyice anladıktan sonra, onu bile bile tahrif ederlerdi."},{"n":76,"t":"Onlar iman edenlerle karşılaşınca, \"İman ettik\" derler. Birbirleriyle baş başa kaldıklarında da şöyle derler: \"Rabbinizin huzurunda delil olarak kullanıp sizi sustursunlar diye mi, Allah’ın (Tevrat’ta) size bildirdiklerini onlara söylüyorsunuz? (Bu kadarcık şeye) akıl erdiremiyor musunuz?\""},{"n":77,"t":"Onlar bilmiyorlar mı ki, Allah onların gizli tuttuklarını da bilir, açığa vurduklarını da."},{"n":78,"t":"Bunların bir de ümmî takımı vardır; Kitab’ı (Tevrat’ı) bilmezler. Onların bütün bildikleri bir sürü kuruntulardır. Onlar sadece zanda bulunurlar."},{"n":79,"t":"Vay o kimselere ki, elleriyle Kitab’ı yazarlar, sonra da onu az bir karşılığa değişmek için, \"Bu, Allah’ın katındandır\" derler. Vay ellerinin yazdıklarından ötürü onların hâline! Vay kazandıklarından dolayı onların hâline!"},{"n":80,"t":"Bir de dediler ki: \"Bize ateş, sayılı birkaç günden başka asla dokunmayacaktır.\" Sen onlara de ki: \"Siz bunun için Allah’tan söz mü aldınız? -Eğer böyle ise, Allah verdiği sözden dönmez-. Yoksa siz Allah’a karşı bilemeyeceğiniz şeyleri mi söylüyorsunuz?\""},{"n":81,"t":"Evet, kötülük işleyip suçu benliğini kaplamış (ve böylece şirke düşmüş) olan kimseler var ya, işte onlar cehennemliklerdir. Onlar orada ebedî kalacaklardır."},{"n":82,"t":"İman edip salih ameller işleyenler ise cennetliklerdir. Onlar orada ebedî kalacaklardır."},{"n":83,"t":"Hani, biz İsrailoğulları’ndan, \"Allah’tan başkasına ibadet etmeyeceksiniz, anne babaya, yakınlara, yetimlere, yoksullara iyilik edeceksiniz, herkese güzel sözler söyleyeceksiniz, namazı kılacaksınız, zekâtı vereceksiniz\" diye söz almıştık. Sonra pek azınız hariç, yüz çevirerek sözünüzden döndünüz."},{"n":84,"t":"Hani, \"Birbirinizin kanını dökmeyeceksiniz, birbirinizi yurtlarınızdan çıkarmayacaksınız\" diye de sizden kesin söz almıştık. Sonra bunu böylece kabul etmiştiniz. Kendiniz de buna hâlâ şahitlik etmektesiniz."},{"n":85,"t":"Ama siz, birbirinizi öldüren, içinizden bir kesime karşı kötülük ve zulümde yardımlaşarak; size haram olduğu hâlde onları yurtlarından çıkaran, size esir olarak geldiklerinde ise, fidye verip kendilerini kurtaran kimselersiniz. Yoksa siz Kitab’ın (Tevrat’ın) bir kısmına inanıp, bir kısmını inkâr mı ediyorsunuz? Artık sizden bunu yapanın cezası, dünya hayatında rezil olmaktan başka bir şey değildir. Kıyamet gününde ise onlar azabın en şiddetlisine uğratılırlar. Çünkü Allah, yaptıklarınızdan habersiz değildir."},{"n":86,"t":"Onlar, ahireti verip dünya hayatını satın alan kimselerdir. Artık bunlardan azap hiç hafifletilmez. Onlara yardım da edilmez."},{"n":87,"t":"Andolsun, Mûsâ’ya Kitab’ı (Tevrat’ı) verdik. Ondan sonra ard arda peygamberler gönderdik. Meryem oğlu İsa’ya mucizeler verdik. Onu Ruhu’l-Kudüs (Cebrail) ile destekledik. Size herhangi bir peygamber, hoşunuza gitmeyen bir şey getirdikçe, kibirlenip (onların) bir kısmını yalanlayıp bir kısmını da öldürmediniz mi?"},{"n":88,"t":"\"Kalplerimiz muhafazalıdır\" dediler. Öyle değil. İnkârları sebebiyle Allah onları lânetlemiştir. Bu yüzden pek az iman ederler."},{"n":89,"t":"Kendilerine ellerindekini (Tevrat’ı) tasdik eden bir kitap (Kur’an) gelince onu inkâr ettiler. Oysa, daha önce (bu kitabı getirecek peygamber ile) inkârcılara (Arap müşriklerine) karşı yardım istiyorlardı. (Tevrat’tan) tanıyıp bildikleri (bu peygamber) kendilerine gelince ise onu inkâr ettiler. Allah’ın lâneti inkârcıların üzerine olsun."},{"n":90,"t":"Karşılığında nefislerini sattıkları şeyi kıskançlıkları sebebiyle Allah’ın, kullarından dilediğine lütfuyla indirdiği vahyi inkâr etmeleri ne kötüdür! Bu yüzden gazap üstüne gazaba uğradılar. İnkâr edenlere alçaltıcı bir azap vardır."},{"n":91,"t":"Onlara, \"Allah’ın indirdiğine (Kur’an’a) iman edin\" denilince, \"Biz sadece bize indirilene (Tevrat’a) inanırız\" deyip, ondan sonra geleni (Kur’an’ı) inkâr ederler. Hâlbuki o, ellerinde bulunanı (Tevrat’ı) tasdik eden hak bir kitaptır. De ki: \"Eğer inanan kimseler idiyseniz, daha önce niçin Allah’ın peygamberlerini öldürüyordunuz?\""},{"n":92,"t":"Andolsun, Mûsâ size açık mucizeler getirmişti de, arkasından sizler nefislerinize zulüm ederek buzağıyı ilâh edinmiştiniz."},{"n":93,"t":"Hani, Tûr’u tepenize dikerek sizden söz almıştık, \"Size verdiğimiz Kitab’a sımsıkı sarılın; ona kulak verin\" demiştik. Onlar, \"Dinledik, karşı geldik\" demişlerdi. İnkârları yüzünden buzağı sevgisi onların kalplerine sindirilmişti. Onlara de ki: (Tevrat’a beslediğinizi iddia ettiğiniz) imanınızın size emrettiği şey ne kötüdür, eğer inanan kimselerseniz!"},{"n":94,"t":"De ki: \"Eğer (iddia ettiğiniz gibi) Allah katındaki ahiret yurdu (cennet) diğer insanlar için değil de, yalnız sizinse ve doğru söyleyenler iseniz haydi ölümü temenni edin!\""},{"n":95,"t":"Fakat kendi elleriyle önceden yaptıkları işler yüzünden ölümü hiçbir zaman temenni edemezler. Allah, o zalimleri hakkıyla bilendir."},{"n":96,"t":"Andolsun, sen onların, yaşamaya, bütün insanlardan; hatta Allah’a ortak koşanlardan bile daha düşkün olduklarını görürsün. Onların her biri bin yıl yaşamak ister. Hâlbuki uzun yaşamak, onları azaptan kurtaracak değildir. Allah, onların bütün işlediklerini görür."},{"n":97,"t":"De ki: \"Her kim Cebrail’e düşman ise, bilsin ki o, Allah’ın izni ile Kur’an’ı; önceki kitapları doğrulayıcı, mü’minler için de bir hidayet rehberi ve müjde verici olarak senin kalbine indirmiştir.\""},{"n":98,"t":"Her kim Allah’a, meleklerine, peygamberlerine, Cebrail’e ve Mîkâil’e düşman olursa bilsin ki, Allah da inkâr edenlerin düşmanıdır."},{"n":99,"t":"Andolsun, biz sana apaçık âyetler indirdik. Bunları ancak fasıklar inkâr eder."},{"n":100,"t":"Onlar ne zaman bir antlaşma yaptılarsa, içlerinden birtakımı o antlaşmayı bozmadı mı? Zaten onların çoğu iman etmez."},{"n":101,"t":"Onlara, Allah katından ellerinde bulunan Kitab’ı (Tevrat’ı) doğrulayıcı bir peygamber gelince, kendilerine kitap verilenlerden bir kısmı, sanki bilmiyorlarmış gibi Allah’ın Kitab’ını (Tevrat’ı) arkalarına attılar."},{"n":102,"t":"\"Süleyman’ın hükümranlığı hakkında şeytanların (ve şeytan tıynetli insanların) uydurdukları yalanların ardına düştüler. Oysa Süleyman (büyü yaparak) küfre girmedi. Fakat şeytanlar, insanlara sihri ve (özellikle de) Babil’deki Hârût ve Mârût adlı iki meleğe ilham edilen (sihr)i öğretmek suretiyle küfre girdiler. Hâlbuki o iki melek, \"Biz ancak imtihan için gönderilmiş birer meleğiz. (Sihri caiz görüp de) sakın küfre girme\" demedikçe, kimseye (sihir) öğretmiyorlardı. Böylece (insanlar) onlardan kişi ile karısını birbirinden ayıracakları sihri öğreniyorlardı. Hâlbuki onlar, Allah’ın izni olmadıkça o sihirle hiç kimseye zarar veremezlerdi. (Onlar böyle yaparak) kendilerine zarar veren, fayda getirmeyen şeyleri öğreniyorlardı. Andolsun, onu satın alanın ahirette bir nasibi olmadığını biliyorlardı. Kendilerini karşılığında sattıkları şey ne kötüdür! Keşke bilselerdi!"},{"n":103,"t":"Eğer onlar iman edip Allah’ın emirlerine karşı gelmekten sakınmış olsalardı, Allah katında kazanacakları sevap kendileri için daha hayırlı olacaktı. Keşke bilselerdi!"},{"n":104,"t":"Ey iman edenler! \"Râ’inâ (bizi gözet)\" demeyin, \"unzurnâ (bize bak)\" deyin ve dinleyin. Kâfirler için acıklı bir azap vardır."},{"n":105,"t":"Ne Kitab ehlinden inkâr edenler ve ne de Allah’a ortak koşanlar, Rabbinizden size bir iyilik gelmesini isterler. Oysa Allah, rahmetini dilediğine tahsis eder. Allah, büyük lütuf sahibidir."},{"n":106,"t":"Biz herhangi bir âyetin hükmünü yürürlükten kaldırır veya onu unutturur (ya da ertelersek), yerine daha hayırlısını veya mislini getiririz. Allah’ın gücünün her şeye hakkıyla yettiğini bilmez misin?"},{"n":107,"t":"Bilmez misin ki, göklerin ve yerin hükümranlığı Allah’ındır. Sizin için Allah’tan başka ne bir dost, ne de bir yardımcı vardır."},{"n":108,"t":"Yoksa daha önce Mûsâ’nın sorguya çekildiği gibi, siz de peygamberinizi sorguya çekmek mi istiyorsunuz? Her kim imanı küfre değişirse, o artık doğru yoldan sapmış olur."},{"n":109,"t":"Kitap ehlinden birçoğu, hak kendilerine belirdikten sonra dahi, içlerindeki kıskançlıktan ötürü sizi, imanınızdan sonra küfre döndürmek isterler. Siz şimdilik, Allah onlar hakkındaki emrini getirinceye kadar affedin, hoşgörün. Şüphesiz Allah, gücü her şeye hakkıyla yetendir."},{"n":110,"t":"Namazı dosdoğru kılın, zekâtı verin. Kendiniz için her ne iyilik işlemiş olursanız, Allah katında onu bulursunuz. Şüphesiz Allah bütün yaptıklarınızı görür."},{"n":111,"t":"Bir de; \"Yahudi ve Hıristiyanlardan başkası Cennet’e girmeyecek\" dediler. Bu, onların kuruntuları! De ki: \"Eğer doğru söyleyenler iseniz (iddianızı ispat edecek) delilinizi getirin.\""},{"n":112,"t":"Hayır, öyle değil! Kim \"ihsan\" derecesine yükselerek özünü Allah’a teslim ederse, onun mükâfatı Rabbinin katındadır. Artık onlara korku yoktur, onlar üzülmeyeceklerdir."},{"n":113,"t":"Yahudiler, \"Hıristiyanlar bir temel üzerinde değiller\" dediler. Hıristiyanlar da, \"Yahudiler bir temel üzerinde değiller\" dediler. Oysa hepsi Kitab’ı okuyorlar. (Kitab’ı) bilmeyenler de tıpkı bunların söyledikleri gibi demişti. Artık onların aralarında uyuşamadıkları davada, kıyamet gününde hükmü Allah verecektir."},{"n":114,"t":"Allah’ın mescitlerinde onun adının anılmasını yasak eden ve onların yıkılması için çalışandan kim daha zalimdir. Böyleleri oralara (eğer girerlerse) ancak korka korka girebilmelidirler. Bunlar için dünyada rezillik, ahirette de büyük bir azap vardır."},{"n":115,"t":"Doğu da, Batı da (tüm yeryüzü) Allah’ındır. Nereye dönerseniz Allah’ın yüzü işte oradadır. Şüphesiz Allah, lütfu geniş olandır, hakkıyla bilendir."},{"n":116,"t":"\"Allah, çocuk edindi\" dediler. O, bundan uzaktır. Hayır! Göklerdeki ve yerdeki her şey Allah’ındır. Hepsi O’na boyun eğmiştir."},{"n":117,"t":"O, gökleri ve yeri örneksiz yaratandır. Bir işe hükmetti mi ona sadece \"ol\" der, o da hemen oluverir."},{"n":118,"t":"Bilmeyenler, \"Allah bizimle konuşsa, ya da bize bir mucize gelse ya!\" derler. Bunlardan öncekiler de tıpkı böyle, bunların dedikleri gibi demişti. Onların kalpleri (anlayışları) birbirine benziyor. Biz âyetleri, kesin olarak inanacak bir toplum için açıkladık."},{"n":119,"t":"Şüphesiz biz seni hak ile; müjdeleyici ve uyarıcı olarak gönderdik. Sen cehennemlik olanlardan sorumlu tutulacak değilsin."},{"n":120,"t":"Sen dinlerine uymadıkça, ne Yahudiler ve ne de Hıristiyanlar asla senden razı olmazlar. De ki: \"Allah’ın yolu asıl doğru yoldur.\" Sana gelen ilimden sonra, eğer onların arzu ve keyiflerine uyacak olursan, bilmiş ol ki, Allah’tan sana ne bir dost, ne bir yardımcı vardır."},{"n":121,"t":"Kendilerine kitab verdiğimiz kimseler, onu gereği gibi okurlar. İşte bunlar ona inanırlar. Onu inkâr edenlere gelince, işte onlar ziyana uğrayanların ta kendileridir."},{"n":122,"t":"Ey İsrailoğulları! Size verdiğim nimetimi ve (bir zamanlar) sizi cümle âleme üstün tuttuğumu hatırlayın."},{"n":123,"t":"Kimsenin kimse namına bir şey ödemeyeceği, hiç kimseden fidye alınmayacağı, kimseye şefaatin (aracılığın) yarar sağlamayacağı ve hiç kimsenin hiçbir taraftan yardım göremeyeceği günden sakının."},{"n":124,"t":"Bir zaman Rabbi İbrahim’i birtakım emirlerle sınamış, İbrahim onların hepsini yerine getirmiş de Rabbi şöyle buyurmuştu: \"Ben seni insanlara önder yapacağım.\" İbrahim de, \"Soyumdan da (önderler yap, ya Rabbi!)\" demişti. Bunun üzerine Rabbi, \"Benim ahdim (verdiğim söz) zalimleri kapsamaz\" demişti."},{"n":125,"t":"Hani, biz Kâbe’yi insanlara toplantı ve güven yeri kılmıştık. Siz de Makam-ı İbrahim’den kendinize bir namaz yeri edinin. İbrahim ve İsmail’e şöyle emretmiştik: \"Tavaf edenler, kendini ibadete verenler, rükû ve secde edenler için evimi (Kâbe’yi) tertemiz tutun.\""},{"n":126,"t":"Hani İbrahim, \"Rabbim! Bu şehri güvenli bir şehir kıl. Halkından Allah’a ve ahiret gününe iman edenleri her türlü ürünle rızıklandır\" demişti. Allah da, \"İnkâr edeni bile az bir süre, (bu geçici kısa hayatta) rızıklandırır; sonra onu cehennem azabına girmek zorunda bırakırım. Ne kötü varılacak yerdir orası!\" demişti."},{"n":127,"t":"Hani İbrahim, İsmail ile birlikte evin (Kâbe’nin) temellerini yükseltiyor, \"Ey Rabbimiz! Bizden kabul buyur! Şüphesiz sen hakkıyla işitensin, hakkıyla bilensin\" diyorlardı."},{"n":128,"t":"\"Rabbimiz! Bizi sana teslim olmuş kimseler kıl. Soyumuzdan da sana teslim olmuş bir ümmet kıl. Bize ibadet yerlerini ve ilkelerini göster. Tövbemizi kabul et. Çünkü sen, tövbeleri çok kabul edensin, çok merhametli olansın.\""},{"n":129,"t":"\"Rabbimiz! İçlerinden onlara bir peygamber gönder; onlara âyetlerini okusun, kitabı ve hikmeti öğretsin ve onları her kötülükten arındırsın. Şüphesiz, sen mutlak güç sahibisin, hüküm ve hikmet sahibisin.\""},{"n":130,"t":"Kendini bilmeyenden başka İbrahim’in dininden kim yüz çevirir? Andolsun, biz İbrahim’i bu dünyada seçkin kıldık. Şüphesiz o ahirette de iyilerdendir."},{"n":131,"t":"Rabbi ona \"Teslim ol\" dediğinde, \"Âlemlerin Rabbine teslim oldum\" demişti."},{"n":132,"t":"İbrahim, bunu kendi oğullarına da vasiyet etti, Yakub da öyle: \"Oğullarım! Allah, sizin için bu dini (İslâm’ı) seçti. Siz de ancak müslümanlar olarak ölün\" dedi."},{"n":133,"t":"Yoksa siz Yakub’un, ölüm döşeğinde iken çocuklarına, \"Benden sonra kime ibadet edeceksiniz?\" dediği, onların da, \"Senin ilâhına ve ataların İbrahim, İsmail ve İshak’ın ilâhı olan tek bir ilâha ibadet edeceğiz; bizler O’na boyun eğmiş müslümanlarız.\" dedikleri zaman orada hazır mı bulunuyordunuz?"},{"n":134,"t":"Onlar gelip geçmiş bir ümmettir. Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorumlu tutulacak değilsiniz."},{"n":135,"t":"(Yahudiler) \"Yahudi olun\" ve (Hıristiyanlar da) \"Hıristiyan olun ki doğru yolu bulasınız\" dediler. De ki: \"Hayır, hakka yönelen İbrahim’in dinine uyarız. O, Allah’a ortak koşanlardan değildi.\""},{"n":136,"t":"Deyin ki: \"Biz Allah’a, bize indirilene (Kur’an’a), İbrahim, İsmail, İshak, Yakub ve Yakuboğullarına indirilene, Mûsâ ve İsa’ya verilen (Tevrat ve İncil) ile bütün diğer peygamberlere Rab’lerinden verilene iman ettik. Onlardan hiçbirini diğerinden ayırt etmeyiz ve biz ona teslim olmuş kimseleriz.\""},{"n":137,"t":"Eğer onlar böyle sizin iman ettiğiniz gibi iman ederlerse, gerçekten doğru yolu bulmuş olurlar; yüz çevirirlerse onlar elbette derin bir ayrılığa düşmüş olurlar. Allah, onlara karşı seni koruyacaktır. O, hakkıyla işitendir, hakkıyla bilendir."},{"n":138,"t":"\"Biz, Allah’ın boyasıyla boyanmışızdır. Boyası Allah’ınkinden daha güzel olan kimdir? Biz ona ibadet edenleriz\" (deyin)."},{"n":139,"t":"Onlara de ki: \"Allah hakkında mı bizimle tartışıp duruyorsunuz? Hâlbuki O, bizim de Rabbimiz, sizin de Rabbinizdir. Bizim işlediklerimiz bize, sizin işledikleriniz size aittir. Biz O’na gönülden bağlanmış kimseleriz.\""},{"n":140,"t":"Yoksa siz, \"İbrahim de, İsmail de, İshak da, Yakub ile Yakuboğulları da yahudi, ya da hıristiyan idiler\" mi diyorsunuz? De ki: \"Sizler mi daha iyi bilirsiniz, yoksa Allah mı?\" Allah tarafından kendisine ulaşan bir gerçeği gizleyen kimseden daha zalim kimdir? Allah, yaptıklarınızdan habersiz değildir."},{"n":141,"t":"Onlar gelip geçmiş bir ümmettir. Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorumlu tutulacak değilsiniz."},{"n":142,"t":"Birtakım kendini bilmez insanlar, \"Onları (müslümanları) yönelmekte oldukları kıbleden çeviren nedir?\" diyecekler. De ki: \"Doğu da, Batı da Allah’ındır. Allah, dilediği kimseyi doğru yola iletir.\""},{"n":143,"t":"Böylece, sizler insanlara birer şahit (ve örnek) olasınız ve Peygamber de size bir şahit (ve örnek) olsun diye sizi orta bir ümmet yaptık. Her ne kadar Allah’ın doğru yolu gösterdiği kimselerden başkasına ağır gelse de biz, yönelmekte olduğun ciheti ancak; Resûl’e tabi olanlarla, gerisin geriye dönecekleri ayırd edelim diye kıble yaptık. Allah, imanınızı boşa çıkaracak değildir. Şüphesiz Allah, insanlara çok şefkatli ve çok merhametlidir."},{"n":144,"t":"(Ey Muhammed!) Biz senin çok defa yüzünü göğe doğru çevirip durduğunu (vahiy beklediğini) görüyoruz. (Merak etme) elbette seni, hoşnut olacağın kıbleye çevireceğiz. (Bundan böyle), yüzünü Mescid-i Haram yönüne çevir. (Ey Müslümanlar!) Siz de nerede olursanız olun, (namazda) yüzünüzü hep onun yönüne çevirin. Şüphesiz kendilerine kitap verilenler, bunun Rabblerinden (gelen) bir gerçek olduğunu elbette bilirler. Allah, onların yaptıklarından habersiz değildir."},{"n":145,"t":"Andolsun, sen kendilerine kitap verilenlere her türlü mucizeyi getirsen de, onlar yine senin kıblene uymazlar. Sen de onların kıblesine uyacak değilsin. Onlar birbirlerinin kıblesine de uymazlar. Andolsun, eğer sana gelen bunca ilimden sonra onların arzu ve keyiflerine uyacak olursan, o takdirde sen de mutlaka zalimlerden olursun."},{"n":146,"t":"Kendilerine kitap verdiklerimiz onu (Peygamberi) oğullarını tanıdıkları gibi tanırlar. Böyle iken içlerinden birtakımı bile bile gerçeği gizlerler."},{"n":147,"t":"Hak (ancak) Rabbindendir. Artık, sakın şüpheye düşenlerden olma!"},{"n":148,"t":"Herkesin yöneldiği bir yön vardır. Haydi, hep hayırlara koşun, yarışın! Nerede olsanız Allah hepinizi bir araya getirir. Şüphesiz, Allah’ın gücü her şeye hakkıyla yeter."},{"n":149,"t":"(Ey Muhammed!) Nereden yola çıkarsan çık, (namazda) Mescid-i Haram’a doğru dön. Bu, elbette Rabbinden gelen gerçek bir emirdir. Allah, sizin işlediklerinizden asla habersiz değildir."},{"n":150,"t":"(Ey Muhammed!) Nereden yola çıkarsan çık, yüzünü Mescid-i Haram’a doğru çevir. (Ey mü’minler!) Siz de nerede olursanız olun, yüzünüzü Mescid-i Haram’a doğru çevirin ki, zalimlerin dışındaki insanların elinde (size karşı) bir koz olmasın. Zalimlerden korkmayın, benden korkun. Böylece size nimetlerimi tamamlayayım ve doğru yolu bulasınız."},{"n":151,"t":"Nitekim kendi aranızdan, size âyetlerimizi okuyan, sizi her kötülükten arındıran, size kitap ve hikmeti öğreten, ayrıca bilmediklerinizi de öğreten bir peygamber gönderdik."},{"n":152,"t":"Öyleyse yalnız beni anın ki ben de sizi anayım. Bana şükredin, sakın nankörlük etmeyin."},{"n":153,"t":"Ey iman edenler! Sabrederek ve namaz kılarak Allah’tan yardım dileyin. Şüphe yok ki, Allah sabredenlerle beraberdir."},{"n":154,"t":"Allah yolunda öldürülenlere \"ölüler\" demeyin. Hayır, onlar diridirler. Ancak siz bunu bilemezsiniz."},{"n":155,"t":"Andolsun ki sizi biraz korku ve açlıkla, bir de mallar, canlar ve ürünlerden eksilterek deneriz. Sabredenleri müjdele."},{"n":156,"t":"Onlar; başlarına bir musibet gelince, \"Biz şüphesiz (her şeyimizle) Allah’a aidiz ve şüphesiz O’na döneceğiz\" derler."},{"n":157,"t":"İşte Rableri katından rahmet ve merhamet onlaradır. Doğru yola ulaştırılmış olanlar da işte bunlardır."},{"n":158,"t":"Şüphesiz Safa ile Merve, Allah’ın (dininin) nişanelerindendir. Onun için her kim hac ve umre niyetiyle Kâbe’yi ziyaret eder ve onları da tavaf ederse, bunda bir günah yoktur. Her kim de gönlünden koparak bir hayır işlerse, şüphesiz Allah onu bilir, karşılığını verir."},{"n":159,"t":"İndirdiğimiz apaçık delilleri ve hidayeti Kitap’ta açıklamamızdan sonra onları gizleyenler var ya, işte onlara hem Allah lânet eder, hem de bütün lânet etme konumunda olanlar lânet eder."},{"n":160,"t":"Ancak tövbe edip durumlarını düzeltenler ve gerçeği açıkça ortaya koyanlar (lânetlenmekten) kurtulmuşlardır. Çünkü ben onların tövbelerini kabul ederim. Zira ben tövbeleri çok kabul edenim, çok merhamet edenim."},{"n":161,"t":"Fakat âyetlerimizi inkâr etmiş ve kâfir olarak ölmüşlere gelince, işte Allah’ın, meleklerin ve bütün insanların lâneti onların üstünedir."},{"n":162,"t":"Onlar ebedî olarak lânet içinde kalırlar. Artık ne kendilerinden azap hafifletilir, ne de yüzlerine bakılır."},{"n":163,"t":"Sizin ilâhınız bir tek ilâhtır. O’ndan başka ilâh yoktur. O, Rahmân’dır, Rahîm’dir."},{"n":164,"t":"Şüphesiz, göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelişinde, insanlara yarar sağlayacak şeylerle denizde seyreden gemilerde, Allah’ın gökyüzünden indirip kendisiyle ölmüş toprağı dirilttiği yağmurda, yeryüzünde her çeşit canlıyı yaymasında, rüzgârları ve gökle yer arasındaki emre amade bulutları evirip çevirmesinde elbette düşünen bir topluluk için deliller vardır."},{"n":165,"t":"İnsanlar arasında Allah’ı bırakıp da O’na ortak koşanlar vardır. Onları, Allah’ı severcesine severler. Mü’minlerin Allah’a olan sevgisi daha güçlü bir sevgidir. Zulmedenler azaba uğrayacakları zaman bütün kuvvetin Allah’ın olduğunu ve Allah’ın azabının pek şiddetli olduğunu bir bilselerdi!"},{"n":166,"t":"Kendilerine uyulanlar o gün azabı görünce, kendilerine uyanlardan uzaklaşacaklar, aralarındaki bütün bağlar kopacaktır."},{"n":167,"t":"Uyanlar şöyle derler: \"Keşke dünyaya bir dönüşümüz olsaydı da onların şimdi bizden uzaklaştıkları gibi, biz de onlardan uzaklaşsaydık.\" Böylece Allah, onlara işledikleri fiilleri pişmanlık kaynağı olarak gösterir. Onlar ateşten çıkacak da değillerdir."},{"n":168,"t":"Ey insanlar! Yeryüzündeki şeylerin helâl ve temiz olanlarından yiyin! Şeytanın izinden yürümeyin. Çünkü o sizin için apaçık bir düşmandır."},{"n":169,"t":"O, size ancak kötülüğü, hayâsızlığı ve Allah’a karşı bilmediğiniz şeyleri söylemenizi emreder."},{"n":170,"t":"Onlara, \"Allah’ın indirdiğine uyun!\" denildiğinde, \"Hayır, biz, atalarımızı üzerinde bulduğumuz (yol)a uyarız!\" derler. Peki ama, ataları bir şey anlamayan, doğru yolu bulamayan kimseler olsalar da mı (onların yoluna uyacaklar)?"},{"n":171,"t":"İnkâr edenleri imana çağıran (peygamber) ile inkâr edenlerin durumu, bağırıp çağırmadan başka bir şey duymayan hayvanlara seslenen (çoban) ile hayvanların durumu gibidir. Onlar sağırdırlar, dilsizdirler, kördürler. Bundan dolayı anlamazlar."},{"n":172,"t":"Ey iman edenler! Eğer siz ancak Allah’a kulluk ediyorsanız, size verdiğimiz rızıkların iyi ve temizlerinden yiyin ve Allah’a şükredin."},{"n":173,"t":"Allah, size ancak leş, kan, domuz eti ve Allah’tan başkası adına kesileni haram kıldı. Ama kim mecbur olur da, istismar etmeksizin ve zaruret ölçüsünü aşmaksızın yemek zorunda kalırsa, ona günah yoktur. Şüphesiz, Allah çok bağışlayandır, çok merhamet edendir."},{"n":174,"t":"Allah’ın indirdiği kitaptan bir kısmını gizleyip onu az bir bedel ile değişenler (var ya); işte onlar karınlarına ateşten başka bir şey doldurmuyorlar. Kıyamet günü Allah, onlarla ne konuşacak, ne de onları arıtacaktır. Onlar için elem dolu bir azap vardır."},{"n":175,"t":"İşte bunlar hidayeti verip sapıklığı, bağışlanmayı verip azabı satın alanlardır. Onlar ateşe karşı ne kadar da dayanıklıdırlar(!)"},{"n":176,"t":"Bu (azab) da, Allah’ın, Kitab’ı hak olarak indirmiş olması (ve onların bunu inkâr etmesi) sebebiyledir. Kitap konusunda anlaşmazlığa düşenler ise derin bir ayrılık içindedirler."},{"n":177,"t":"İyilik, yüzlerinizi doğu ve batı taraflarına çevirmeniz(den ibaret) değildir. Asıl iyilik, Allah’a, ahiret gününe, meleklere, kitap ve peygamberlere iman edenlerin; mala olan sevgilerine rağmen, onu yakınlara, yetimlere, yoksullara, yolda kalmışa, (ihtiyacından dolayı) isteyene ve (özgürlükleri için) kölelere verenlerin; namazı dosdoğru kılan, zekâtı veren, antlaşma yaptıklarında sözlerini yerine getirenlerin ve zorda, hastalıkta ve savaşın kızıştığı zamanlarda (direnip) sabredenlerin tutum ve davranışlarıdır. İşte bunlar, doğru olanlardır. İşte bunlar, Allah’a karşı gelmekten sakınanların ta kendileridir."},{"n":178,"t":"Ey iman edenler! Öldürülenler hakkında size kısas farz kılındı. Hüre karşı hür, köleye karşı köle, kadına karşı kadın kısas edilir. Ancak öldüren kimse, kardeşi (öldürülenin vârisi, velisi) tarafından affedilirse, aklın ve dinin gereklerine uygun yol izlemek ve güzellikle diyet ödemek gerekir. Bu, Rabbinizden bir hafifletme ve rahmettir. Bundan sonra tecavüzde bulunana elem dolu bir azap vardır."},{"n":179,"t":"Ey akıl sahipleri! Kısasta sizin için hayat vardır. Umulur ki (bu hükme uyarak) korunursunuz."},{"n":180,"t":"Sizden birinize ölüm gelip çattığı zaman, eğer geride bir hayır (mal) bırakmışsa, anaya, babaya ve yakın akrabaya meşru bir tarzda vasiyette bulunması -Allah’a karşı gelmekten sakınanlar üzerinde bir hak olarak- size farz kılındı."},{"n":181,"t":"Her kim işittikten sonra vasiyeti değiştirirse, günahı ancak onu değiştirenlerin boynunadır. Şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir."},{"n":182,"t":"Vasiyet edenin hataya meyletmesinden ve günaha girmesinden korkan bir kimse, (tarafların) aralarını düzeltirse ona hiçbir günah yoktur. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir."},{"n":183,"t":"Ey iman edenler! Allah’a karşı gelmekten sakınmanız için oruç, sizden öncekilere farz kılındığı gibi, size de farz kılındı."},{"n":184,"t":"Oruç, sayılı günlerdedir. Sizden kim hasta, ya da yolculukta olursa, tutamadığı günler sayısınca başka günlerde tutar. Oruca gücü yetmeyenler ise bir yoksul doyumu fidye verir. Bununla birlikte, gönülden kim bir iyilik yaparsa (mesela fidyeyi fazla verirse) o kendisi için daha hayırlıdır. Eğer bilirseniz oruç tutmanız sizin için daha hayırlıdır."},{"n":185,"t":"(O sayılı günler), insanlar için bir hidayet rehberi, doğru yolun ve hak ile batılı birbirinden ayırmanın apaçık delilleri olarak Kur’an’ın kendisinde indirildiği Ramazan ayıdır. Öyle ise içinizden kim bu aya ulaşırsa, onu oruçla geçirsin. Kim de hasta veya yolcu olursa, tutamadığı günler sayısınca başka günlerde tutsun. Allah, size kolaylık diler, zorluk dilemez. Bu da sayıyı tamamlamanız ve hidayete ulaştırmasına karşılık Allah’ı yüceltmeniz ve şükretmeniz içindir."},{"n":186,"t":"Kullarım, beni senden sorarlarsa, (bilsinler ki), gerçekten ben (onlara çok) yakınım. Bana dua edince, dua edenin duasına cevap veririm. O hâlde, doğru yolu bulmaları için benim davetime uysunlar, bana iman etsinler."},{"n":187,"t":"Oruç gecesinde kadınlarınıza yaklaşmak size helâl kılındı. Onlar, size örtüdürler, siz de onlara örtüsünüz. Allah, (Ramazan gecelerinde hanımlarınıza yaklaşarak) kendinize zulmetmekte olduğunuzu bildi de tövbenizi kabul edip sizi affetti. Artık eşlerinize yaklaşın ve Allah’ın sizin için yazıp takdir etmiş olduğu şeyi arayın. Şafağın aydınlığı gecenin karanlığından ayırt edilinceye (tan yeri ağarıncaya) kadar yiyin, için. Sonra da akşama kadar orucu tam tutun. Bununla birlikte siz mescitlerde itikâfta iken eşlerinize yaklaşmayın. Bunlar, Allah’ın koyduğu sınırlardır. Bu sınırlara yaklaşmayın. Allah, kendine karşı gelmekten sakınsınlar diye, âyetlerini insanlara böylece açıklar."},{"n":188,"t":"Aranızda birbirinizin mallarını haksız yere yemeyin. İnsanların mallarından bir kısmını bile bile günaha girerek yemek için onları hâkimlere (rüşvet olarak) vermeyin."},{"n":189,"t":"Sana, hilâlleri soruyorlar. De ki: \"Onlar, insanlar ve hac için vakit ölçüleridir. İyilik, evlere arkalarından girmeniz değildir. Ama iyi davranış, takva sahibi (Allah’a karşı gelmekten sakınan) insanın davranışıdır. Evlere kapılarından girin. Allah’a karşı gelmekten sakının ki kurtuluşa eresiniz."},{"n":190,"t":"Sizinle savaşanlara karşı Allah yolunda siz de savaşın. Ancak aşırı gitmeyin. Çünkü Allah aşırı gidenleri sevmez."},{"n":191,"t":"Onları nerede yakalarsanız öldürün. Sizi çıkardıkları yerden (Mekke’den) siz de onları çıkarın. Zulüm ve baskı, adam öldürmekten daha ağırdır. Yalnız, Mescid-i Haram yanında, onlar sizinle savaşmadıkça, siz de onlarla savaşmayın. Sizinle savaşırlarsa (siz de onlarla savaşın) onları öldürün. Kâfirlerin cezası böyledir."},{"n":192,"t":"Eğer onlar (savaştan ve küfürden) vazgeçerlerse, (şunu iyi bilin ki) Allah çok bağışlayandır, çok merhamet edendir."},{"n":193,"t":"Hiçbir zulüm ve baskı kalmayıncaya ve din yalnız Allah’ın oluncaya kadar onlarla savaşın. Onlar savaşmaya son verecek olurlarsa, artık düşmanlık yalnız zalimlere karşıdır."},{"n":194,"t":"Haram ay, haram aya karşılıktır. Hürmetler (saygı gösterilmesi gereken şeyler) kısas kuralına tabidir. O hâlde kim size saldırırsa, size saldırdığı gibi siz de ona saldırın, (fakat ileri gitmeyin). Allah’a karşı gelmekten sakının ve bilin ki, Allah kendine karşı gelmekten sakınanlarla beraberdir."},{"n":195,"t":"(Mallarınızı) Allah yolunda harcayın. Kendi kendinizi tehlikeye atmayın. İyilik edin. Şüphesiz Allah iyilik edenleri sever."},{"n":196,"t":"Haccı da, umreyi de Allah için tamamlayın. Eğer (düşman, hastalık ve benzer sebeplerle) engellenmiş olursanız artık size kolay gelen kurbanı gönderin. Bu kurban, yerine varıncaya kadar başlarınızı tıraş etmeyin. İçinizden her kim hastalanır veya başından rahatsız olur (da tıraş olmak zorunda kalır)sa fidye olarak ya oruç tutması, ya sadaka vermesi, ya da kurban kesmesi gerekir. Güvende olduğunuz zaman hacca kadar umreyle faydalanmak isteyen kimse, kolayına gelen kurbanı keser. Kurban bulamayan kimse üçü hacda, yedisi de döndüğünüz zaman (olmak üzere) tam on gün oruç tutar. Bu (durum), ailesi Mescid-i Haram civarında olmayanlar içindir. Allah’a karşı gelmekten sakının ve Allah’ın cezasının çetin olduğunu bilin."},{"n":197,"t":"Hac (ayları), bilinen aylardır. Kim o aylarda hacca başlarsa, artık ona hacda cinsel ilişki, günaha sapmak, kavga etmek yoktur. Siz ne hayır yaparsanız, Allah onu bilir. (Ahiret için) azık toplayın. Kuşkusuz, azığın en hayırlısı takva (Allah’a karşı gelmekten sakınma)dır. Ey akıl sahipleri, bana karşı gelmekten sakının."},{"n":198,"t":"(Hac mevsiminde ticaret yaparak) Rabbinizin lütuf ve keremini istemekte size bir günah yoktur. Arafat’tan ayrılıp (sel gibi Müzdelife’ye) akın ettiğinizde, Meş’ar-i Haram’da Allah’ı zikredin. Onu, size gösterdiği gibi zikredin. Doğrusu siz onun yol göstermesinden önce yolunu şaşırmışlardan idiniz."},{"n":199,"t":"Sonra insanların akın ettiği yerden siz de akın edin ve Allah’tan bağışlanma dileyin. Şüphesiz Allah çok bağışlayandır, çok merhamet edendir."},{"n":200,"t":"Hac ibadetinizi bitirdiğinizde, artık (cahiliye döneminde) atalarınızı andığınız gibi, hatta ondan da kuvvetli bir anışla Allah’ı anın. İnsanlardan, \"Ey Rabbimiz! Bize (vereceğini) bu dünyada ver\" diyenler vardır. Bunların ahirette bir nasibi yoktur."},{"n":201,"t":"Onlardan, \"Rabbimiz! Bize dünyada da iyilik ver, ahirette de iyilik ver ve bizi ateş azabından koru\" diyenler de vardır."},{"n":202,"t":"İşte onlara kazandıklarından bir nasip vardır. Allah, hesabı pek çabuk görendir."},{"n":203,"t":"Sayılı günlerde Allah’ı anın (telbiye ve tekbir getirin). Kim iki gün içinde acele edip (Mina’dan Mekke’ye) dönerse, ona günah yoktur. Kim geri kalırsa, ona da günah yoktur. Bu, Allah’a karşı gelmekten sakınanlar içindir. Allah’a karşı gelmekten sakının ve onun huzurunda toplanacağınızı bilin."},{"n":204,"t":"İnsanlardan öylesi de vardır ki, dünya hayatına ilişkin sözleri senin hoşuna gider. Bir de kalbindekine (Sözünün özüne uyduğuna) Allah’ı şahit tutar. Hâlbuki o, düşmanlıkta en amansız olandır."},{"n":205,"t":"O, (senin yanından) ayrılınca yeryüzünde bozgunculuk yapmağa, ekin ve nesli yok etmeğe çalışır. Allah ise bozgunculuğu sevmez."},{"n":206,"t":"Ona \"Allah’tan kork\" denildiği zaman, gururu onu daha da günaha sürükler. Artık böylesinin hakkından cehennem gelir. O ne kötü yataktır!"},{"n":207,"t":"İnsanlardan öylesi de vardır ki, Allah’ın rızasını kazanmak için kendini feda eder. Allah, kullarına çok şefkatlidir."},{"n":208,"t":"Ey iman edenler! Hepiniz topluca barış ve güvenliğe (İslâm’a) girin. Şeytanın adımlarını izlemeyin. Çünkü o, size apaçık bir düşmandır."},{"n":209,"t":"Size apaçık deliller geldikten sonra, eğer yine de yan çizerseniz, bilin ki Allah, gerçekten mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":210,"t":"Onlar (böyle davranmakla), bulut gölgeleri içinde Allah’ın (azabının) ve meleklerin kendilerine gelmesini ve işin bitirilmesini mi bekliyorlar? Hâlbuki bütün işler Allah’a döndürülür."},{"n":211,"t":"İsrailoğullarına sor; biz onlara nice açık mucizeler verdik. Kendisine geldikten sonra kim Allah’ın nimetini değiştirirse, (bilsin ki) şüphesiz Allah, cezası pek çetin olandır."},{"n":212,"t":"İnkâr edenlere dünya hayatı süslü gösterildi. Onlar iman edenlerle alay etmektedirler. Allah’a karşı gelmekten sakınanlar ise, kıyamet günü bunların üstündedir. Allah, dilediğine hesapsız rızık verir."},{"n":213,"t":"İnsanlar tek bir ümmetti. Allah, müjdeciler ve uyarıcılar olarak peygamberler gönderdi ve beraberlerinde, insanların anlaşmazlığa düştükleri şeyler konusunda, aralarında hüküm vermek üzere kitapları hak olarak indirdi. Kendilerine apaçık âyetler geldikten sonra o konuda ancak; kitap verilenler, aralarındaki kıskançlık yüzünden anlaşmazlığa düştüler. Bunun üzerine Allah iman edenleri, kendi izniyle, onların hakkında ayrılığa düştükleri gerçeğe iletti. Allah, dilediğini doğru yola iletir."},{"n":214,"t":"Yoksa siz, sizden öncekilerin başına gelenler, sizin de başınıza gelmeden cennete gireceğinizi mi sandınız? Peygamber ve onunla beraber mü’minler, \"Allah’ın yardımı ne zaman?\" diyecek kadar darlığa ve zorluğa uğramışlar ve sarsılmışlardı. İyi bilin ki, Allah’ın yardımı pek yakındır."},{"n":215,"t":"Sana Allah yolunda ne harcayacaklarını soruyorlar. De ki: \"Hayır olarak ne harcarsanız o, ana-baba, akraba, yetimler, fakirler ve yolda kalmışlar içindir. Hayır olarak ne yaparsanız, gerçekten Allah onu hakkıyla bilir.\""},{"n":216,"t":"Savaş, hoşunuza gitmediği hâlde, size farz kılındı. Olur ki, bir şey sizin için hayırlı iken, siz onu hoş görmezsiniz. Yine olur ki, bir şey sizin için kötü iken, siz onu seversiniz. Allah bilir, siz bilmezsiniz."},{"n":217,"t":"Sana haram ayda savaşmayı soruyorlar. De ki: \"O ayda savaş büyük bir günahtır. Allah’ın yolundan alıkoymak, onu inkâr etmek, Mescid-i Haram’ın ziyaretine engel olmak ve halkını oradan çıkarmak, Allah katında daha büyük günahtır. Zulüm ve baskı ise adam öldürmekten daha büyüktür. Onlar, güç yetirebilseler, sizi dininizden döndürünceye kadar sizinle savaşmaya devam ederler. Sizden kim dininden döner de kâfir olarak ölürse, öylelerin bütün yapıp ettikleri dünyada da, ahirette de boşa gitmiştir. Bunlar cehennemliklerdir, orada sürekli kalacaklardır."},{"n":218,"t":"İman edenler, hicret edenler, Allah yolunda cihad edenler; şüphesiz bunlar Allah’ın rahmetini umarlar. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":219,"t":"Sana içkiyi ve kumarı sorarlar. De ki: \"Onlarda hem büyük günah, hem de insanlar için (bazı zahirî) yararlar vardır. Ama günahları yararlarından büyüktür.\" Yine sana Allah yolunda ne harcayacaklarını soruyorlar. De ki: \"İhtiyaçtan arta kalanı.\" Allah, size âyetleri böyle açıklıyor ki düşünesiniz."},{"n":220,"t":"Dünya ve ahiret hakkında düşünesiniz, diye böyle yapıyor. Bir de sana yetimleri soruyorlar. De ki: \"Onların durumlarını düzeltmek hayırlıdır. Eğer onlara karışıp (birlikte yaşar)sanız (sakıncası yok). (Onlar da) sizin kardeşlerinizdir. Allah, bozguncuyu yapıcı olandan ayırır. Allah, dileseydi sizi zora sokardı. Şüphesiz Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":221,"t":"İman etmedikleri sürece Allah’a ortak koşan kadınlarla evlenmeyin. Allah’a ortak koşan kadın hoşunuza gitse de, mü’min bir cariye Allah’a ortak koşan bir kadından daha hayırlıdır. İman etmedikleri sürece Allah’a ortak koşan erkeklerle, kadınlarınızı evlendirmeyin. Allah’a ortak koşan hür erkek hoşunuza gitse de; iman eden bir köle, Allah’a ortak koşan bir erkekten daha hayırlıdır. Onlar ateşe çağırırlar, Allah ise izniyle, cennete ve bağışlanmaya çağırır. O, insanlara âyetlerini açıklar ki, öğüt alıp düşünsünler."},{"n":222,"t":"Sana kadınların ay hâlini sorarlar. De ki: \"O bir ezadır (rahatsızlıktır). Ay hâlinde kadınlardan uzak durun. Temizleninceye kadar onlara yaklaşmayın. Temizlendikleri vakit, Allah’ın size emrettiği yerden onlara yaklaşın. Şüphesiz Allah çok tövbe edenleri sever, çok temizlenenleri sever.\""},{"n":223,"t":"Kadınlarınız sizin ekinliğinizdir. Ekinliğinize dilediğiniz biçimde varın. Kendiniz için (geleceğe hazırlık olarak) güzel davranışlar takdim edin. Allah’a karşı gelmekten sakının ve her hâlde onun huzuruna varacağınızı bilin. (Ey Muhammed!) Mü’minleri müjdele."},{"n":224,"t":"İyilik etmemek, takvaya sarılmamak, insanlar arasını ıslah etmemek yolundaki yeminlerinize Allah’ı siper yapmayın. Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":225,"t":"Allah, sizi kasıtsız yeminlerinizden dolayı sorumlu tutmaz, fakat sizi kalplerinizin kazandığı (bile bile yaptığınız) yeminlerden sorumlu tutar. Allah, çok bağışlayandır, halîmdir. (Hemen cezalandırmaz, mühlet verir.)"},{"n":226,"t":"Eşlerine yaklaşmamağa yemin edenler için dört ay bekleme süresi vardır. Eğer (bu süre içinde) dönerlerse, şüphesiz Allah çok bağışlayandır, çok merhamet edendir."},{"n":227,"t":"Eğer (yemin edenler yeminlerinden dönmeyip kadınlarını) boşamaya karar verirlerse (ayrılırlar). Biliniz ki, Allah hakkıyla işitendir, hakkıyla bilendir."},{"n":228,"t":"Boşanmış kadınlar kendi kendilerine üç ay hâli (hayız veya temizlik müddeti) beklerler. Eğer Allah’a ve ahiret gününe inanıyorlarsa, Allah’ın kendi rahimlerinde yarattığını gizlemeleri onlara helâl olmaz. Kocaları bu süre içinde barışmak isterlerse, onları geri almağa daha çok hak sahibidirler. Kadınların, yükümlülükleri kadar meşru hakları vardır. Yalnız erkeklerin kadınlar üzerinde bir derece farkı vardır. Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":229,"t":"(Dönüş yapılabilecek) boşama iki defadır. Sonrası, ya iyilikle geçinmek, ya da güzellikle bırakmaktır. (Evlilikte) tarafların Allah’ın belirlediği ölçüleri koruyamama endişeleri dışında kadınlara verdiklerinizden (boşanma esnasında) bir şeyi geri almanız, sizin için helâl olmaz. Eğer onlar Allah’ın belirlediği ölçüleri gözetmeyecekler diye endişe ederseniz, o zaman kadının (boşanmak için) bedel vermesinde ikisine de günah yoktur. Bunlar Allah’ın koyduğu sınırlardır. Sakın bunları aşmayın. Allah’ın koyduğu sınırları kim aşarsa, onlar zalimlerin ta kendileridir."},{"n":230,"t":"Eğer erkek karısını (üçüncü defa) boşarsa, kadın, onun dışında bir başka kocayla nikâhlanmadıkça ona helâl olmaz. (Bu koca da) onu boşadığı takdirde, onlar (kadın ile ilk kocası) Allah’ın koyduğu ölçüleri gözetebileceklerine inanıyorlarsa tekrar birbirlerine dönüp evlenmelerinde bir günah yoktur. İşte bunlar Allah’ın, anlayan bir toplum için açıkladığı ölçüleridir."},{"n":231,"t":"Kadınları boşadığınız ve onlar da bekleme sürelerini bitirdikleri zaman, ya onları iyilikle tutun yahut iyilikle bırakın. Haklarına tecavüz edip zarar vermek için onları tutmayın. Bunu kim yaparsa kendine zulmetmiş olur. Sakın Allah’ın âyetlerini eğlenceye almayın. Allah’ın üzerinizdeki nimetini, size öğüt vermek için indirdiği Kitab’ı ve hikmeti hatırlayın. Allah’a karşı gelmekten sakının ve bilin ki Allah her şeyi hakkıyla bilendir."},{"n":232,"t":"Kadınları boşadığınız ve onlar da bekleme sürelerini bitirdikleri zaman kendi aralarında aklın ve dinin gereklerine uygun olarak güzellikle anlaştıkları takdirde, eşleriyle (yeniden) evlenmelerine engel olmayın. Bununla içinizden Allah’a ve ahiret gününe iman edenlere öğüt verilmektedir. Bu, sizin için daha hayırlı ve daha temizdir. Allah bilir, siz bilmezsiniz."},{"n":233,"t":"-Emzirmeyi tamamlamak isteyenler için- anneler çocuklarını iki tam yıl emzirirler. Onların (annelerin) yiyeceği, giyeceği, örfe uygun olarak babaya aittir. Hiçbir kimseye gücünün üstünde bir yük ve sorumluluk teklif edilmez. -Hiçbir anne ve hiçbir baba çocuğu sebebiyle zarara uğratılmasın- (Baba ölmüşse) mirasçı da aynı şeyle sorumludur. Eğer (anne ve baba) kendi aralarında danışıp anlaşarak (iki yıl dolmadan) çocuğu sütten kesmek isterlerse, onlara günah yoktur. Eğer çocuklarınızı (bir sütanneye) emzirtmek isterseniz, örfe uygun olarak vereceğiniz ücreti güzelce ödediğiniz takdirde size bir günah yoktur. Allah’a karşı gelmekten sakının ve bilin ki, Allah, yapmakta olduklarınızı hakkıyla görendir."},{"n":234,"t":"İçinizden ölenlerin geride bıraktıkları eşleri, kendi kendilerine dört ay on gün (iddet) beklerler. Sürelerini bitirince artık kendileri için meşru olanı yapmalarında size bir günah yoktur. Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":235,"t":"(Vefat iddeti beklemekte olan) kadınlara kendileri ile evlenmek istediğinizi üstü kapalı olarak anlatmanızda veya bu isteğinizi içinizde saklamanızda sizin için bir günah yoktur. Allah biliyor ki, siz onlara (bunu er geç mutlaka) söyleyeceksiniz. Meşru sözler söylemeniz dışında sakın onlarla gizliden gizliye buluşma yönünde sözleşmeyin. Bekleme müddeti bitinceye kadar da nikâh yapmaya kalkışmayın. Şunu da bilin ki, Allah içinizden geçeni hakkıyla bilir. Onun için Allah’a karşı gelmekten sakının ve yine şunu da bilin ki Allah gerçekten çok bağışlayandır, halîmdir. (Hemen cezalandırmaz, mühlet verir.)"},{"n":236,"t":"Kendilerine el sürmeden ya da mehir belirlemeden kadınları boşarsanız size bir günah yoktur. (Bu durumda) -eli geniş olan gücüne göre, eli dar olan da gücüne göre olmak üzere- onlara, aklın ve dinin gereklerine uygun olarak müt’a verin. Bu, iyilik yapanlar üzerinde bir borçtur."},{"n":237,"t":"Eğer onlara mehir tespit eder de kendilerine el sürmeden boşarsanız, tespit ettiğiniz mehrin yarısı onlarındır. Ancak kadının, ya da nikâh bağı elinde bulunanın (kocanın, paylarından) vazgeçmesi başka. Bununla birlikte (ey erkekler), sizin vazgeçmeniz takvaya (Allah’a karşı gelmekten sakınmaya) daha yakındır. Aranızda iyilik yapmayı da unutmayın. Şüphesiz Allah, yaptıklarınızı hakkıyla görendir."},{"n":238,"t":"Namazlara ve orta namaza devam edin. Allah’a gönülden boyun eğerek namaza durun."},{"n":239,"t":"Eğer (bir tehlikeden) korkarsanız, namazı yaya olarak veya binek üzerinde kılın. Güvenliğe kavuşunca da, Allah’ı, daha önce bilmediğiniz ve onun size öğrettiği şekilde anın (namazı normal vakitlerdeki gibi kılın)."},{"n":240,"t":"İçinizden ölüp geriye dul eşler bırakan erkekler, eşleri için, evden çıkarılmaksızın bir yıla kadar geçimlerinin sağlanmasını vasiyet etsinler. Ama onlar (kendiliklerinden) çıkarlarsa, artık onların meşru biçimde kendileri ile ilgili olarak işlediklerinden dolayı size bir günah yoktur. Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":241,"t":"Boşanmış kadınların örfe göre geçimlerinin sağlanması onların hakkıdır. Bu, Allah’a karşı gelmekten sakınanlar üzerinde bir borçtur."},{"n":242,"t":"Düşünesiniz diye Allah size âyetlerini böyle açıklamaktadır."},{"n":243,"t":"Binlerce kişi oldukları hâlde, ölüm korkusuyla yurtlarını terk edenleri görmedin mi? Allah, onlara \"ölün\" dedi, sonra da onları diriltti. Şüphesiz Allah, insanlara karşı lütuf ve ikram sahibidir. Ama insanların çoğu şükretmezler."},{"n":244,"t":"Allah yolunda savaşın ve bilin ki, şüphesiz Allah hakkıyla işitendir ve hakkıyla bilendir."},{"n":245,"t":"Kimdir Allah’a güzel bir borç verecek o kimse ki, Allah da o borcu kendisine kat kat ödesin. (Rızkı) Allah daraltır ve genişletir. Ancak O’na döndürüleceksiniz."},{"n":246,"t":"Mûsâ’dan sonra İsrailoğullarının ileri gelenlerini görmedin mi (ne yaptılar)? Hani, peygamberlerinden birine, \"Bize bir hükümdar gönder de Allah yolunda savaşalım\" demişlerdi. O, \"Ya üzerinize savaş farz kılındığı hâlde, savaşmayacak olursanız?\" demişti. Onlar, \"Yurdumuzdan çıkarılmış, çocuklarımızdan uzaklaştırılmış olduğumuz hâlde Allah yolunda niye savaşmayalım\" diye cevap vermişlerdi. Ama onlara savaş farz kılınınca içlerinden pek azı hariç, yüz çevirdiler. Allah, zalimleri hakkıyla bilendir."},{"n":247,"t":"Peygamberleri onlara, \"Allah, size Tâlût’u hükümdar olarak gönderdi\" dedi. Onlar, \"O bizim üzerimize nasıl hükümdar olabilir? Biz hükümdarlığa ondan daha lâyığız. Ona zenginlik de verilmemiştir\" dediler. Peygamberleri şöyle dedi: \"Şüphesiz Allah, onu sizin üzerinize (hükümdar) seçti, onun bilgisini ve gücünü artırdı.\" Allah, mülkünü dilediğine verir. Allah, lütfu geniş olandır, hakkıyla bilendir."},{"n":248,"t":"Peygamberleri onlara şöyle dedi: \"Onun hükümdarlığının alameti, size o sandığın gelmesidir. Onda Rabbinizden bir güven duygusu ve huzur ile Mûsâ ailesinin, Hârûn ailesinin geriye bıraktığından kalıntılar vardır. Onu melekler taşımaktadır. Eğer inanmış kimselerseniz, bunda şüphesiz sizin için kesin bir delil vardır.\""},{"n":249,"t":"Tâlût, ordu ile hareket edince, \"Şüphesiz Allah, sizi bir ırmakla imtihan edecektir. Kim ondan içerse benden değildir. Kim onu tatmazsa işte o bendendir. Ancak eliyle bir avuç alan başka.\" dedi. İçlerinden pek azı hariç, hepsi ırmaktan içtiler. Tâlût ve onunla beraber iman edenler ırmağı geçince, (geride kalanlar) \"Bugün bizim Câlût’a ve askerlerine karşı koyacak gücümüz yok.\" dediler. Allah’a kavuşacaklarını kesin olarak bilenler (ırmağı geçenler) ise şu cevabı verdiler: \"Allah’ın izniyle büyük bir topluluğa galip gelen nice küçük topluluklar vardır. Allah, sabredenlerle beraberdir.\""},{"n":250,"t":"(Tâlût’un askerleri) Câlût ve askerleriyle karşı karşıya gelince şöyle dediler: \"Ey Rabbimiz! Üzerimize sabır yağdır, ayaklarımızı sağlam bastır ve şu kâfir kavme karşı bize yardım et.\""},{"n":251,"t":"Derken, Allah’ın izniyle onları bozguna uğrattılar. Davud, Câlût’u öldürdü. Allah, ona (Davud’a) hükümdarlık ve hikmet verdi ve ona dilediğini öğretti. Eğer Allah’ın; insanların bir kısmıyla diğerlerini savması olmasaydı, yeryüzü bozulurdu. Ancak Allah, bütün âlemlere karşı lütuf sahibidir."},{"n":252,"t":"İşte bunlar Allah’ın âyetleridir. Biz onları sana hak olarak okuyoruz. Şüphesiz sen, Allah tarafından gönderilmiş peygamberlerdensin."},{"n":253,"t":"İşte peygamberler! Biz, onların bir kısmını bir kısmına üstün kıldık. İçlerinden, Allah’ın konuştukları vardır. Bir kısmının da derecelerini yükseltmiştir. Meryem oğlu İsa’ya ise açık deliller verdik ve onu Ruhu’l-Kudüs (Cebrail) ile destekledik. Eğer Allah dileseydi, bunların arkasından gelen (millet)ler, kendilerine apaçık deliller geldikten sonra, birbirlerini öldürmezlerdi. Fakat ayrılığa düştüler. Onlardan inananlar da vardı, inkâr edenler de. Yine Allah dileseydi, birbirlerini öldürmezlerdi. Lâkin Allah dilediğini yapar."},{"n":254,"t":"Ey iman edenler! Hiçbir alışverişin, hiçbir dostluğun ve hiçbir şefaatin olmadığı kıyamet günü gelmeden önce, size rızık olarak verdiklerimizden Allah yolunda harcayın. İnkâr edenler ise zalimlerin ta kendileridir."},{"n":255,"t":"Allah, kendisinden başka hiçbir ilâh olmayandır. Diridir, kayyumdur. O’nu ne bir uyuklama tutabilir, ne de bir uyku. Göklerdeki her şey, yerdeki her şey O’nundur. İzni olmaksızın O’nun katında şefaatte bulunacak kimdir? O, kulların önlerindekileri ve arkalarındakileri (yaptıklarını ve yapacaklarını) bilir. Onlar O’nun ilminden, kendisinin dilediği kadarından başka bir şey kavrayamazlar. O’nun kürsüsü, bütün gökleri ve yeri kaplayıp kuşatmıştır. (O, göklere, yere, bütün evrene hükmetmektedir.) Gökleri ve yeri koruyup gözetmek O’na güç gelmez. O, yücedir, büyüktür."},{"n":256,"t":"Dinde zorlama yoktur. Çünkü doğruluk sapıklıktan iyice ayrılmıştır. O hâlde, kim tâğûtu tanımayıp Allah’a inanırsa, kopmak bilmeyen sapasağlam bir kulpa yapışmıştır. Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":257,"t":"Allah, iman edenlerin dostudur. Onları karanlıklardan aydınlığa çıkarır. Kâfirlerin velileri ise tâğûttur. (O da) onları aydınlıktan karanlıklara (sürükleyip) çıkarır. Onlar cehennemliklerdir. Orada ebedî kalırlar."},{"n":258,"t":"Allah, kendisine hükümdarlık verdi diye (şımarıp böbürlenerek) Rabbi hakkında İbrahim ile tartışanı görmedin mi? Hani İbrahim, \"Benim Rabbim diriltir, öldürür.\" demiş; o da, \"Ben de diriltir, öldürürüm\" demişti. (Bunun üzerine) İbrahim, \"Şüphesiz Allah güneşi doğudan getirir, sen de onu batıdan getir\" deyince, kâfir şaşırıp kaldı. Zaten Allah, zalimler topluluğunu hidayete erdirmez."},{"n":259,"t":"Yahut altı üstüne gelmiş (ıpıssız duran) bir şehre uğrayan kimseyi görmedin mi? O, \"Allah, burayı ölümünden sonra nasıl diriltecek (acaba)?\" demişti. Bunun üzerine, Allah onu öldürüp yüzyıl ölü bıraktı, sonra diriltti ve ona sordu: \"Ne kadar (ölü) kaldın?\" O, \"Bir gün veya bir günden daha az kaldım\" diye cevap verdi. Allah, şöyle dedi: \"Hayır, yüz sene kaldın. Böyle iken yiyeceğine ve içeceğine bak, henüz bozulmamış. Bir de eşeğine bak! (Böyle yapmamız) seni insanlara ibret belgesi kılmamız içindir. (Eşeğin) kemikler(in)e de bak, nasıl onları bir araya getiriyor, sonra onlara nasıl et giydiriyoruz?\" Kendisine bütün bunlar apaçık belli olunca, şöyle dedi: \"Şimdi, biliyorum ki; şüphesiz Allah’ın gücü her şeye hakkıyla yeter.\""},{"n":260,"t":"Hani İbrahim, \"Rabbim! Bana ölüleri nasıl dirilttiğini göster\" demişti. (Allah ona) \"İnanmıyor musun?\" deyince, \"Hayır (inandım) ancak kalbimin tatmin olması için\" demişti. \"Öyleyse, dört kuş tut. Onları kendine alıştır. Sonra onları parçalayıp her bir parçasını bir dağın üzerine bırak. Sonra da onları çağır. Sana uçarak gelirler. Bil ki, şüphesiz Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir.\""},{"n":261,"t":"Mallarını Allah yolunda harcayanların durumu, yedi başak bitiren ve her başakta yüz tane bulunan bir tohum gibidir. Allah, dilediğine kat kat verir. Allah, lütfu geniş olandır, hakkıyla bilendir."},{"n":262,"t":"Mallarını Allah yolunda harcayan, sonra da harcadıklarının peşinden (bunları) başa kakmayan ve gönül incitmeyenlerin, Rab’leri katında mükâfatları vardır. Onlar için korku yoktur. Onlar üzülmeyeceklerdir de."},{"n":263,"t":"Güzel bir söz ve bağışlama, peşinden gönül kırma gelen bir sadakadan daha hayırlıdır. Allah, her bakımdan sınırsız zengindir, halîmdir (hemen cezalandırmaz, mühlet verir)."},{"n":264,"t":"Ey iman edenler! Allah’a ve ahiret gününe inanmadığı hâlde insanlara gösteriş olsun diye malını harcayan kimse gibi, sadakalarınızı başa kakmak ve gönül kırmak suretiyle boşa çıkarmayın. Böylesinin durumu, üzerinde biraz toprak bulunan ve maruz kaldığı şiddetli yağmurun kendisini çıplak bıraktığı bir kayanın durumu gibidir. Onlar kazandıklarından hiçbir şey elde edemezler. Allah, kâfirler topluluğunu hidayete erdirmez."},{"n":265,"t":"Allah’ın rızasını kazanmak arzusuyla ve kalben mutmain olarak mallarını Allah yolunda harcayanların durumu, yüksekçe bir yerdeki güzel bir bahçenin durumu gibidir ki, bol yağmur alınca iki kat ürün verir. Bol yağmur almasa bile ona çiseleme yeter. Allah, yaptıklarınızı hakkıyla görendir."},{"n":266,"t":"Herhangi biriniz ister mi ki, içerisinde her türlü meyveye sahip bulunduğu, içinden ırmaklar akan, hurma ve üzüm ağaçlarından oluşan bir bahçesi olsun; himayeye muhtaç çocukları var iken ihtiyarlık gelip kendisine çatsın; derken bağı ateşli (yıldırımlı) bir kasırga vursun da orası yanıversin? Allah, düşünesiniz diye size âyetlerini böyle açıklıyor."},{"n":267,"t":"Ey iman edenler! Kazandıklarınızın iyilerinden ve yerden sizin için çıkardıklarımızdan Allah yolunda harcayın. Kendinizin göz yummadan alıcısı olmayacağınız bayağı şeyleri vermeye kalkışmayın ve bilin ki Allah, her bakımdan zengindir, övülmeye lâyıktır."},{"n":268,"t":"Şeytan sizi fakirlikle korkutur ve size, çirkinliği ve hayâsızlığı emreder. Allah ise size kendi katından mağfiret ve bol nimet va’dediyor. Şüphesiz Allah, lütfu geniş olandır, hakkıyla bilendir."},{"n":269,"t":"Allah, hikmeti dilediğine verir. Kime hikmet verilmişse, şüphesiz ona çokça hayır verilmiş demektir. Bunu ancak akıl sahipleri anlar."},{"n":270,"t":"Allah yolunda her ne harcar veya her ne adarsanız, şüphesiz Allah onu bilir. Zulmedenlerin yardımcıları yoktur."},{"n":271,"t":"Sadakaları açıktan verirseniz ne güzel! Fakat onları gizleyerek fakirlere verirseniz bu, sizin için daha hayırlıdır ve günahlarınızdan bir kısmına da keffaret olur. Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":272,"t":"Onları hidayete erdirmek sana ait değildir. Fakat Allah, dilediğini hidayete erdirir. Hayır olarak ne harcarsanız, kendiniz içindir. Zaten siz ancak Allah’ın rızasını kazanmak için harcarsınız. Hayır olarak her ne harcarsanız -hiç hakkınız yenmeden- karşılığı size tastamam ödenir."},{"n":273,"t":"(Sadakalar) kendilerini Allah yoluna adayan, yeryüzünde dolaşmaya güç yetiremeyen fakirler içindir. İffetlerinden dolayı (dilenmedikleri için), bilmeyen onları zengin sanır. Sen onları yüzlerinden tanırsın. İnsanlardan arsızca (bir şey) istemezler. Siz hayır olarak ne verirseniz, şüphesiz Allah onu bilir."},{"n":274,"t":"Mallarını gece gündüz; gizli ve açık Allah yolunda harcayanlar var ya, onların Rableri katında mükâfatları vardır. Onlara korku yoktur. Onlar mahzun da olacak değillerdir."},{"n":275,"t":"Faiz yiyenler, ancak şeytanın çarptığı kimsenin kalktığı gibi kalkarlar. Bu, onların, \"Alışveriş de faiz gibidir\" demelerinden dolayıdır. Oysa Allah, alışverişi helâl, faizi haram kılmıştır. Bundan böyle kime Rabbinden bir öğüt gelir de (o öğüte uyarak) faizden vazgeçerse, artık önceden aldığı onun olur. Durumu da Allah’a kalmıştır. (Allah, onu affeder.) Kim tekrar (faize) dönerse, işte onlar cehennemliklerdir. Orada ebedî kalacaklardır."},{"n":276,"t":"Allah, faiz malını mahveder, sadakaları ise artırır (bereketlendirir). Allah, hiçbir günahkâr nankörü sevmez."},{"n":277,"t":"Şüphesiz iman edip salih ameller işleyen, namazı dosdoğru kılan ve zekâtı verenlerin mükâfatları Rableri katındadır. Onlara korku yoktur. Onlar mahzun da olmayacaklardır."},{"n":278,"t":"Ey iman edenler! Allah’a karşı gelmekten sakının ve eğer gerçekten iman etmiş kimselerseniz, faizden geriye kalanı bırakın."},{"n":279,"t":"Eğer böyle yapmazsanız, Allah ve Resûlüyle savaşa girdiğinizi bilin. Eğer tövbe edecek olursanız, anaparalarınız sizindir. Böylece siz ne başkalarına haksızlık etmiş olursunuz, ne de başkaları size haksızlık etmiş olur."},{"n":280,"t":"Eğer borçlu darlık içindeyse, ona eli genişleyinceye kadar mühlet verin. Eğer bilirseniz, (borcu) sadaka olarak bağışlamanız, sizin için daha hayırlıdır."},{"n":281,"t":"Öyle bir günden sakının ki, o gün hepiniz Allah’a döndürülüp götürüleceksiniz. Sonra herkese kazandığı amellerin karşılığı verilecek ve onlara asla haksızlık yapılmayacaktır."},{"n":282,"t":"Ey iman edenler! Belli bir süre için birbirinize borçlandığınız zaman bunu yazın. Aranızda bir yazıcı adaletle yazsın. Yazıcı, Allah’ın kendisine öğrettiği şekilde yazmaktan kaçınmasın, (her şeyi olduğu gibi dosdoğru) yazsın. Üzerinde hak olan (borçlu) da yazdırsın ve Rabbi olan Allah’tan korkup sakınsın da borçtan hiçbir şeyi eksik etmesin (hepsini tam yazdırsın). Eğer borçlu, aklı ermeyen, veya zayıf bir kimse ise, ya da yazdıramıyorsa, velisi adaletle yazdırsın. (Bu işleme) şahitliklerine güvendiğiniz iki erkeği; eğer iki erkek olmazsa, bir erkek ve iki kadını şahit tutun. Bu, onlardan biri unutacak olursa, diğerinin ona hatırlatması içindir. Şahitler çağırıldıkları zaman (gelmekten) kaçınmasınlar. Az olsun, çok olsun, borcu süresine kadar yazmaktan usanmayın. Bu, Allah katında adalete daha uygun, şahitlik için daha sağlam, şüpheye düşmemeniz için daha elverişlidir. Yalnız, aranızda hemen alıp verdiğiniz peşin ticaret olursa, onu yazmamanızdan ötürü üzerinize bir günah yoktur. Alışveriş yaptığınız zaman da şahit tutun. Yazana da, şahide de bir zarar verilmesin. Eğer aksini yaparsanız, bu sizin için günahkârca bir davranış olur. Allah’a karşı gelmekten sakının. Allah, size öğretiyor. Allah, her şeyi hakkıyla bilendir."},{"n":283,"t":"Eğer yolculukta olur da bir yazıcı bulamazsanız, o zaman alınmış rehinler yeterlidir. Eğer birbirinize güvenirseniz kendisine güvenilen kimse emanetini (borcunu) ödesin ve Rabbi Allah’tan sakınsın. Bir de şahitliği gizlemeyin. Kim şahitliği gizlerse, şüphesiz onun kalbi günahkârdır. Allah, yaptıklarınızı hakkıyla bilendir."},{"n":284,"t":"Göklerdeki her şey, yerdeki her şey Allah’ındır. İçinizdekini açığa vursanız da, gizleseniz de Allah sizi, onunla sorguya çeker de dilediğini bağışlar, dilediğine azap eder. Allah’ın gücü her şeye hakkıyla yeter."},{"n":285,"t":"Peygamber, Rabbinden kendisine indirilene iman etti, mü’minler de (iman ettiler). Her biri; Allah’a, meleklerine, kitaplarına ve peygamberlerine iman ettiler ve şöyle dediler: \"Onun peygamberlerinden hiçbirini (diğerinden) ayırt etmeyiz.\" Şöyle de dediler: \"İşittik ve itaat ettik. Ey Rabbimiz! Senden bağışlama dileriz. Sonunda dönüş yalnız sanadır.\""},{"n":286,"t":"Allah, bir kimseyi ancak gücünün yettiği şeyle yükümlü kılar. Onun kazandığı iyilik kendi yararına, kötülük de kendi zararınadır. (Şöyle diyerek dua ediniz): \"Ey Rabbimiz! Unutur, ya da yanılırsak bizi sorumlu tutma! Ey Rabbimiz! Bize, bizden öncekilere yüklediğin gibi ağır yük yükleme. Ey Rabbimiz! Bize gücümüzün yetmediği şeyleri yükleme! Bizi affet, bizi bağışla, bize acı! Sen bizim Mevlâmızsın. Kâfirler topluluğuna karşı bize yardım et.\""}],[{"n":1,"t":"Elif Lâm Mîm."},{"n":2,"t":"Allah, kendisinden başka hiçbir ilâh bulunmayandır. Diridir, kayyumdur."},{"n":"3-4","t":"O, sana Kitab’ı hak ve kendisinden öncekileri doğrulayıcı olarak indirdi. O, daha önce Tevrat’ı ve İncil’i insanlar için birer hidayet olarak indirmişti. Furkan’ı da indirdi. Şüphesiz, Allah’ın âyetlerini inkâr edenler için şiddetli bir azap vardır. Allah, mutlak güç sahibidir, intikam sahibidir."},{"n":5,"t":"Şüphesiz yerde ve gökte Allah’a hiçbir şey gizli kalmaz."},{"n":6,"t":"O, sizi rahimlerde, dilediği gibi şekillendirendir. O’ndan başka ilâh yoktur. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":7,"t":"O, sana Kitab’ı indirendir. Onun (Kur’an’ın) bazı âyetleri muhkemdir, onlar kitabın anasıdır. Diğerleri de müteşabihtir. Kalplerinde bir eğrilik olanlar, fitne çıkarmak ve onun olmadık yorumlarını yapmak için müteşabih âyetlerinin ardına düşerler. Oysa onun gerçek manasını ancak Allah bilir. İlimde derinleşmiş olanlar, \"Ona inandık, hepsi Rabbimiz katındandır\" derler. (Bu inceliği) ancak akıl sahipleri düşünüp anlar."},{"n":8,"t":"(Onlar şöyle yakarırlar): \"Rabbimiz! Bizi hidayete erdirdikten sonra kalplerimizi eğriltme. Bize katından bir rahmet bahşet. Şüphesiz sen çok bahşedensin.\""},{"n":9,"t":"\"Rabbimiz! Şüphesiz sen, hakkında şüphe olmayan bir günde insanları toplayacaksın. Şüphesiz Allah va’dinden dönmez.\""},{"n":10,"t":"Şüphesiz, inkâr edenlere, ne malları, ne de evlatları Allah’a karşı hiçbir fayda sağlar. Onlar ateşin yakıtıdırlar."},{"n":11,"t":"(Bunların durumu) Firavun ailesinin ve onlardan öncekilerin durumu gibidir: Âyetlerimizi yalanladılar. Allah da onları günahlarıyla yakaladı. Allah, azabı çok şiddetli olandır."},{"n":12,"t":"İnkâr edenlere de ki: \"Siz mutlaka yenilgiye uğrayacak ve toplanıp cehenneme doldurulacaksınız. Orası ne fena yataktır!\""},{"n":13,"t":"Şüphesiz, karşı karşıya gelen iki toplulukta sizin için bir ibret vardır: Bir topluluk Allah yolunda çarpışıyordu. Öteki ise kâfirdi. (Onları) göz bakışıyla kendilerinin iki katı görüyorlardı. Allah da dilediğini yardımıyla destekliyordu. Basireti olanlar için bunda elbette ibret vardır."},{"n":14,"t":"Kadınlar, oğullar, yük yük altın ve gümüş, salma atlar, davarlar ve ekinler gibi nefsin şiddetle arzuladığı şeyler insana süslü gösterildi. Bunlar dünya hayatının geçimliğidir. Oysa asıl varılacak güzel yer ancak Allah’ın katındadır."},{"n":15,"t":"De ki: \"Size, onlardan daha hayırlısını haber vereyim mi? Allah’a karşı gelmekten sakınanlar için Rableri katında, içinden ırmaklar akan, içinde ebedî kalacakları cennetler, tertemiz eşler ve Allah’ın rızası vardır.\" Allah, kullarını hakkıyla görendir."},{"n":"16-17","t":"(Bunlar), \"Rabbimiz, biz iman ettik. Bizim günahlarımızı bağışla. Bizi ateş azabından koru\" diyenler, sabredenler, doğru olanlar, huzurunda gönülden boyun büküp divan duranlar, Allah yolunda harcayanlar ve seherlerde (Allah’tan) bağışlanma dileyenlerdir."},{"n":18,"t":"Allah, melekler ve ilim sahipleri, ondan başka ilâh olmadığına adaletle şâhitlik ettiler. O’ndan başka ilâh yoktur. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":19,"t":"Şüphesiz Allah katında din İslâm’dır. Kitap verilmiş olanlar, kendilerine ilim geldikten sonra sırf, aralarındaki ihtiras ve aşırılık yüzünden ayrılığa düştüler. Kim Allah’ın âyetlerini inkâr ederse, bilsin ki Allah hesabı çok çabuk görendir."},{"n":20,"t":"Seninle tartışmaya girişirlerse, de ki: \"Ben, bana uyanlarla birlikte kendi özümü Allah’a teslim ettim.\" Kendilerine kitap verilenlere ve ümmîlere de ki: \"Siz de İslâm’ı kabul ettiniz mi?\" Eğer İslâm’a girerlerse hidayete ermiş olurlar. Yok, eğer yüz çevirirlerse sana düşen şey ancak tebliğ etmektir. Allah, kullarını hakkıyla görendir."},{"n":21,"t":"Allah’ın âyetlerini inkâr edenler, Peygamberleri haksız yere öldürenler, insanlardan adaleti emredenleri öldürenler var ya, onları elem dolu bir azap ile müjdele."},{"n":22,"t":"Onlar, amelleri, dünyada da, ahirette de boşa gitmiş kimselerdir. Onların hiç yardımcıları da yoktur."},{"n":23,"t":"Kendilerine Kitap’tan bir pay verilenleri görmüyor musun ki, aralarında hüküm vermesi için Allah’ın Kitabına çağrılıyorlar da sonra içlerinden bir kısmı yüz çevirerek dönüp gidiyor."},{"n":24,"t":"Bunun sebebi, onların, \"Bize, ateş sadece sayılı günlerde dokunacaktır.\" demeleridir. Uydurageldikleri şeyler dinleri konusunda kendilerini aldatmıştır."},{"n":25,"t":"Bakalım, kendilerini o geleceğinde hiç şüphe olmayan gün için bir araya topladığımız ve hiç kimseye haksızlık edilmeden herkese kazandığı tamamen ödendiği vakit, hâlleri nice olacaktır."},{"n":26,"t":"De ki: \"Ey mülkün sahibi olan Allah’ım! Sen mülkü dilediğine verirsin. Dilediğinden de mülkü çeker alırsın. Dilediğini aziz edersin, dilediğini zelil edersin. Hayır senin elindedir. Şüphesiz sen her şeye hakkıyla gücü yetensin.\""},{"n":27,"t":"\"Geceyi gündüze sokarsın, gündüzü geceye sokarsın. Ölüden diriyi çıkarırsın, diriden ölüyü çıkarırsın. Dilediğine de hesapsız rızık verirsin.\""},{"n":28,"t":"Mü’minler, mü’minleri bırakıp inkârcıları dost edinmesin. Kim böyle yaparsa Allah ile bir ilişiği kalmaz. Ancak onlardan (gelebilecek tehlikeden) korunmanız başkadır. Allah, asıl sizi kendisine karşı dikkatli olmanız hakkında uyarmaktadır. Çünkü dönüş Allah’adır."},{"n":29,"t":"De ki: \"İçinizdekini gizleseniz de, açığa vursanız da Allah onu bilir. Göklerdeki her şeyi, yerdeki her şeyi de bilir. Allah, her şeye hakkıyla gücü yetendir.\""},{"n":30,"t":"Herkesin yaptığı iyiliği ve yaptığı kötülüğü hazır bulacağı günde kişi, kötülükleri ile kendi arasında uzak bir mesafe bulunmasını ister. Yine Allah, sizi kendisine karşı dikkatli olmanız hakkında uyarmaktadır. Allah, kullarını çok esirgeyicidir."},{"n":31,"t":"De ki: \"Eğer Allah’ı seviyorsanız bana uyun ki, Allah da sizi sevsin ve günahlarınızı bağışlasın. Çünkü Allah çok bağışlayandır, çok merhamet edendir.\""},{"n":32,"t":"De ki: \"Allah’a ve Peygamber’e itaat edin.\" Eğer yüz çevirirlerse şüphe yok ki Allah kâfirleri sevmez."},{"n":"33-34","t":"Şüphesiz Allah, Âdem’i, Nûh’u, İbrahim ailesini (soyunu) ve İmran ailesini (soyunu) birbirinden gelmiş birer nesil olarak seçip âlemlere üstün kıldı. Allah, her şeyi hakkıyla işitendir, hakkıyla bilendir."},{"n":35,"t":"Hani, İmran’ın karısı, \"Rabbim! Karnımdaki çocuğu sırf sana hizmet etmek üzere adadım. Benden kabul et. Şüphesiz sen hakkıyla işitensin, hakkıyla bilensin\" demişti."},{"n":36,"t":"Onu doğurunca, \"Rabbim!\" dedi, \"Onu kız doğurdum.\" -Oysa Allah, onun ne doğurduğunu daha iyi bilir- \"Erkek, kız gibi değildir. Ona Meryem adını verdim. Onu ve soyunu kovulmuş şeytandan senin korumana bırakıyorum.\""},{"n":37,"t":"Bunun üzerine Rabbi onu güzel bir şekilde kabul buyurdu ve onu güzel bir şekilde yetiştirdi. Zekeriya’yı da onun bakımıyla görevlendirdi. Zekeriya, onun bulunduğu bölmeye her girişinde yanında bir yiyecek bulurdu. \"Meryem! Bu sana nereden geldi?\" derdi. O da \"Bu, Allah katından\" diye cevap verirdi. Zira Allah, dilediğine hesapsız rızık verir."},{"n":38,"t":"Orada Zekeriya Rabbine dua etti: \"Rabbim! Bana katından temiz bir nesil bahşet. Şüphesiz sen duayı hakkıyla işitensin\" dedi."},{"n":39,"t":"Zekeriya mabedde namaz kılarken melekler ona, \"Allah sana, kendisinden gelen bir kelimeyi (İsa’yı) doğrulayıcı, efendi, nefsine hâkim ve salihlerden bir peygamber olarak Yahya’yı müjdeler\" diye seslendiler."},{"n":40,"t":"Zekeriya, \"Ey Rabbim! Bana ihtiyarlık gelip çatmış iken ve karım da kısır iken benim nasıl çocuğum olabilir?\" dedi. Allah, \"Öyledir, ama Allah dilediğini yapar\" dedi."},{"n":41,"t":"Zekeriya, \"Rabbim! (çocuğum olacağına dair) bana bir alâmet ver\" dedi. Allah da şöyle dedi: \"Senin için alâmet, insanlarla üç gün konuşamaman, ancak işaretleşebilmendir. Ayrıca Rabbini çok an, sabah akşam tesbih et.\""},{"n":42,"t":"Hani melekler, \"Ey Meryem! Allah, seni seçti. Seni tertemiz yaptı ve seni dünya kadınlarına üstün kıldı.\""},{"n":43,"t":"\"Ey Meryem! Rabbine divan dur. Secde et ve (O’nun huzurunda) rükû edenlerle beraber rükû et\" demişlerdi."},{"n":44,"t":"(Ey Muhammed!) Bunlar sana vahyettiğimiz gayb haberlerindendir. Meryem’i kim himayesine alıp koruyacak diye kalemlerini (kur’a için) atarlarken sen yanlarında değildin. (Bu konuda) tartışırlarken de yanlarında değildin."},{"n":45,"t":"Hani melekler şöyle demişti: \"Ey Meryem! Allah, seni kendi tarafından bir kelime ile müjdeliyor ki, adı Meryem oğlu İsa Mesih’tir. Dünyada da, ahirette de itibarlı ve Allah’a çok yakın olanlardandır.\""},{"n":46,"t":"\"O, beşikte de, yetişkin çağında da insanlarla konuşacak, salihlerden olacaktır.\""},{"n":47,"t":"(Meryem), \"Ey Rabbim! Bana bir beşer dokunmamışken benim nasıl çocuğum olur?\" dedi. Allah, \"Öyle ama, Allah dilediğini yaratır. O, bir şeyin olmasını dilediğinde ona sadece \"ol\" der, o da hemen oluverir\" dedi."},{"n":48,"t":"Ve Allah ona kitabı, hikmeti, Tevrat ve İncil’i öğretecek."},{"n":49,"t":"Allah, onu İsrailoğullarına bir Peygamber olarak gönderecek (ve o da onlara şöyle diyecek): \"Şüphesiz ben size Rabbinizden bir mucize getirdim. Ben çamurdan kuş şeklinde bir şey yapar, ona üflerim. O da Allah’ın izniyle hemen kuş oluverir. Körü ve alacalıyı iyileştiririm ve Allah’ın izniyle ölüleri diriltirim. Evlerinizde ne yiyip ne biriktirdiğinizi size haber veririm. Eğer mü’minler iseniz bunda sizin için elbette bir ibret vardır.\""},{"n":50,"t":"\"Benden önce gelen Tevrat’ı doğrulayıcı olarak ve size haram kılınan bazı şeyleri helâl kılmak için gönderildim ve Rabbiniz tarafından size bir mucize de getirdim. Artık Allah’a karşı gelmekten sakının ve bana itaat edin.\""},{"n":51,"t":"\"Şüphesiz Allah, benim de Rabbim, sizin de Rabbinizdir. Öyleyse O’na ibadet edin. İşte bu, doğru yoldur.\""},{"n":52,"t":"İsa, onların inkârlarını sezince, \"Allah yolunda yardımcılarım kim?\" dedi. Havariler, \"Biziz Allah yolunun yardımcıları. Allah’a iman ettik. Şahit ol, biz müslümanlarız\" dediler."},{"n":53,"t":"\"Rabbimiz! Senin indirdiğine iman ettik ve Peygamber’e uyduk. Artık bizi (hakikate) şahitlik edenlerle beraber yaz.\""},{"n":54,"t":"Onlar tuzak kurdular. Allah da tuzak kurdu. Allah, tuzak kuranların en hayırlısıdır."},{"n":55,"t":"Hani Allah şöyle buyurmuştu: \"Ey İsa! Şüphesiz, senin hayatına ben son vereceğim. Seni kendime yükselteceğim. Seni inkâr edenlerden kurtararak temizleyeceğim ve sana uyanları kıyamete kadar küfre sapanların üstünde tutacağım. Sonra dönüşünüz yalnızca banadır. Ayrılığa düştüğünüz şeyler hakkında aranızda ben hükmedeceğim.\""},{"n":56,"t":"\"İnkâr edenlere gelince, onlara dünyada da, ahirette de şiddetli bir şekilde azab edeceğim. Onların hiç yardımcıları da olmayacaktır.\""},{"n":57,"t":"\"İman edip salih ameller işleyenlere gelince, Allah onların mükâfatlarını tastamam verecektir. Allah, zalimleri sevmez.\""},{"n":58,"t":"(Ey Muhammed!) Bunu (bildirdiklerimizi) biz sana âyetlerden ve hikmet dolu Kur’an’dan okuyoruz."},{"n":59,"t":"Şüphesiz Allah katında (yaratılışları bakımından) İsa’nın durumu, Âdem’in durumu gibidir: Onu topraktan yarattı. Sonra ona \"ol\" dedi. O da hemen oluverdi."},{"n":60,"t":"Hak Rabbindendir. O hâlde, sakın şüphe edenlerden olma."},{"n":61,"t":"Sana (gerekli) bilgi geldikten sonra artık kim bu konuda seninle tartışacak olursa, de ki: \"Gelin, oğullarımızı ve oğullarınızı, kadınlarımızı ve kadınlarınızı çağıralım. Biz de siz de toplanalım. Sonra gönülden dua edelim de, Allah’ın lânetini (aramızdan) yalan söyleyenlerin üstüne atalım.\""},{"n":62,"t":"Şüphesiz bu (İsa hakkındaki) gerçek kıssadır. Allah’tan başka hiçbir ilâh yoktur. Şüphesiz Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":63,"t":"Eğer yüz çevirirlerse, şüphesiz ki Allah fesat çıkaranları çok iyi bilir."},{"n":64,"t":"De ki: \"Ey kitap ehli! Bizimle sizin aranızda ortak bir söze gelin: Yalnız Allah’a ibadet edelim. O’na hiçbir şeyi ortak koşmayalım. Allah’ı bırakıp da kimimiz kimimizi ilâh edinmesin.\" Eğer onlar yine yüz çevirirlerse, deyin ki: \"Şahit olun, biz müslümanlarız.\""},{"n":65,"t":"Ey kitap ehli! İbrahim hakkında niçin tartışıyorsunuz. Oysa Tevrat da, İncil de ondan sonra indirilmiştir. Siz hiç düşünmüyor musunuz?"},{"n":66,"t":"İşte siz böyle kimselersiniz! Diyelim ki biraz bilginiz olan şey hakkında tartıştınız. Ya hiç bilginiz olmayan şey hakkında niçin tartışıyorsunuz? Allah bilir, siz bilmezsiniz."},{"n":67,"t":"İbrahim, ne Yahudi idi, ne de Hıristiyan. Fakat o, hanif (Allah’ı bir tanıyan, hakka yönelen) bir müslümandı. Allah’a ortak koşanlardan da değildi."},{"n":68,"t":"Şüphesiz, insanların İbrahim’e en yakın olanı, elbette ona uyanlar, bir de bu peygamber (Muhammed) ve mü’minlerdir. Allah da mü’minlerin dostudur."},{"n":69,"t":"Kitap ehlinden bir grup sizi saptırabilmeyi çok arzu etti. Oysa sadece kendilerini saptırıyorlar, fakat farkına varmıyorlar."},{"n":70,"t":"Ey Kitap ehli! (Gerçeğe) şahit olduğunuz hâlde, niçin Allah’ın âyetlerini inkâr ediyorsunuz?"},{"n":71,"t":"Ey Kitap ehli! Niçin hakkı batılla karıştırıyor ve bile bile gerçeği gizliyorsunuz?"},{"n":72,"t":"Kitap ehlinden bir grup, \"Mü’minlere indirilene günün başlangıcında inanın, sonunda da inkâr edin, belki onlar (size bakarak) dönerler\" dedi."},{"n":73,"t":"\"Sizin dininize uyandan başkasına inanmayın\" (dediler). De ki: \"Şüphesiz hidayet, Allah’ın hidayetidir. Birine, size verilenin benzerinin verilmesinden veya Rabbinizin huzurunda aleyhinize deliller getireceklerinden ötürü mü (böyle söylüyorsunuz)?\" De ki: \"Lütuf Allah’ın elindedir. Onu dilediğine verir. Allah, lütfu geniş olandır, hakkıyla bilendir.\""},{"n":74,"t":"O, rahmetini dilediğine has kılar. Allah, büyük lütuf sahibidir."},{"n":75,"t":"\"Kitap ehlinden öylesi vardır ki, ona yüklerle mal emanet etsen, onu sana (eksiksiz) iade eder. Fakat onlardan öylesi de vardır ki, ona bir dinar emanet etsen, tepesine dikilip durmadıkça onu sana iade etmez. Bu da onların, \"Ümmîlere karşı (yaptıklarımızdan) bize vebal yoktur\" demelerinden dolayıdır. Onlar, bile bile Allah’a karşı yalan söylerler."},{"n":76,"t":"Hayır! (Gerçek, onların dediği değil.) Kim sözünü yerine getirir ve Allah’a karşı gelmekten sakınırsa, şüphesiz Allah da sakınanları sever."},{"n":77,"t":"Şüphesiz, Allah’a verdikleri sözü ve yeminlerini az bir karşılığa değişenler var ya, işte onların ahirette bir payı yoktur. Allah, kıyamet günü onlarla konuşmayacak, onlara bakmayacak ve onları temizlemeyecektir. Onlar için elem dolu bir azap vardır."},{"n":78,"t":"Onlardan (Kitap ehlinden) bir grup var ki, Kitab’dan olmadığı hâlde Kitab’dan sanasınız diye (okudukları) Kitap’tanmış gibi dillerini eğip bükerler ve, \"Bu, Allah katındandır\" derler. Hâlbuki o, Allah katından değildir. Bile bile Allah’a karşı yalan söylerler."},{"n":79,"t":"Allah’ın, kendisine Kitab’ı, hükmü (hikmeti) ve peygamberliği verdiği hiçbir insanın, \"Allah’ı bırakıp bana kullar olun\" demesi düşünülemez. Fakat (şöyle öğüt verir:) \"Öğretmekte ve derinlemesine incelemekte olduğunuz Kitap uyarınca rabbânîler (Allah’ın istediği örnek ve dindar kullar) olun.\""},{"n":80,"t":"Onun size, \"Melekleri ve peygamberleri ilâhlar edinin.\" diye emretmesi de düşünülemez. Siz müslüman olduktan sonra, o size hiç inkârı emreder mi?"},{"n":81,"t":"Hani, Allah peygamberlerden, \"Andolsun, size vereceğim her kitap ve hikmetten sonra, elinizdekini doğrulayan bir peygamber geldiğinde, ona mutlaka iman edeceksiniz ve ona mutlaka yardım edeceksiniz\" diye söz almış ve, \"Bunu kabul ettiniz mi; verdiğim bu ağır görevi üstlendiniz mi?\" demişti. Onlar, \"Kabul ettik\" demişlerdi. Allah da, \"Öyleyse şahid olun, ben de sizinle beraber şahit olanlardanım\" demişti."},{"n":82,"t":"Artık bundan sonra kim yüz çevirirse, işte onlar yoldan çıkmışların ta kendileridir."},{"n":83,"t":"Göklerdeki ve yerdeki herkes ister istemez O’na boyun eğmişken ve O’na döndürülüp götürülecekken onlar Allah’ın dininden başkasını mı arıyorlar?"},{"n":84,"t":"De ki: \"Allah’a, bize indirilene (Kur’an’a), İbrahim’e, İsmail’e, İshak’a, Yakub’a ve Yakuboğullarına indirilene, Mûsâ’ya, İsa’ya ve peygamberlere Rablerinden verilene inandık. Onlardan hiçbirini diğerinden ayırt etmeyiz. Biz O’na teslim olanlarız.\""},{"n":85,"t":"Kim İslâm’dan başka bir din ararsa, (bilsin ki o din) ondan kabul edilmeyecek ve o ahirette hüsrana uğrayanlardan olacaktır."},{"n":86,"t":"İman ettikten, Peygamberin hak olduğuna şahitlik ettikten ve kendilerine açık deliller geldikten sonra inkâr eden bir toplumu Allah nasıl doğru yola eriştirir? Allah, zalim toplumu doğru yola iletmez."},{"n":87,"t":"İşte onların cezası; Allah’ın, meleklerin ve bütün insanların lânetinin üzerlerine olmasıdır."},{"n":88,"t":"Onun (lânetin) içinde ebedî kalacaklardır. Onların azabı hafifletilmez, onlara göz açtırılmaz."},{"n":89,"t":"Ancak bundan sonra tövbe edip kendilerini düzeltenler müstesnadır. Şüphesiz Allah çok bağışlayandır, çok merhamet edendir."},{"n":90,"t":"Şüphesiz iman ettikten sonra inkâr eden, sonra da inkârda ileri gidenlerin tövbeleri asla kabul edilmeyecektir. İşte onlar sapıkların ta kendileridir."},{"n":91,"t":"Şüphesiz inkâr edip kâfir olarak ölenler var ya, dünya dolusu altını fidye verseler bile bu, hiçbirisinden asla kabul edilmeyecektir. Onlar için elem dolu bir azap vardır. Onların hiçbir yardımcıları da yoktur."},{"n":92,"t":"Sevdiğiniz şeylerden Allah yolunda harcamadıkça iyiliğe asla erişemezsiniz. Her ne harcarsanız Allah onu bilir."},{"n":93,"t":"Tevrat indirilmeden önce, İsrail’in (Yakub’un) kendisine haram kıldığı dışında, yiyeceklerin hepsi İsrailoğullarına helâl idi. De ki: \"Eğer doğru söyleyenler iseniz, haydi Tevrat’ı getirip okuyun.\""},{"n":94,"t":"Artık bundan sonra Allah’a karşı kim yalan uydurursa, işte onlar zalimlerin ta kendileridir."},{"n":95,"t":"De ki: \"Allah, doğru söylemiştir. Öyle ise hakka yönelen İbrahim’in dinine uyun. O, Allah’a ortak koşanlardan değildi.\""},{"n":96,"t":"Şüphesiz, insanlar için kurulan ilk ibadet evi, elbette Mekke’de, âlemlere rahmet ve hidayet kaynağı olarak kurulan Kâ’be’dir."},{"n":97,"t":"Onda apaçık deliller, Makam-ı İbrahim vardır. Oraya kim girerse, güven içinde olur. Yolculuğuna gücü yetenlerin haccetmesi, Allah’ın insanlar üzerinde bir hakkıdır. Kim inkâr ederse (bu hakkı tanınmazsa), şüphesiz Allah bütün âlemlerden müstağnidir. (Kimseye muhtaç değildir, her şey O’na muhtaçtır.)"},{"n":98,"t":"De ki: \"Ey kitab ehli! Allah, yaptıklarınızı görüp dururken Allah’ın âyetlerini niçin inkâr ediyorsunuz?\""},{"n":99,"t":"De ki: Ey kitap ehli! (Gerçeği) görüp bildiğiniz halde niçin Allah’ın yolunu eğrilterek inananları ondan çevirmeye yelteniyorsunuz? Allah yaptıklarınızdan habersiz değildir."},{"n":100,"t":"Ey iman edenler! Kendilerine kitap verilenlerden herhangi bir gruba uyarsanız, imanınızdan sonra sizi döndürüp kâfir yaparlar."},{"n":101,"t":"Size Allah’ın âyetleri okunup dururken ve Allah’ın Resûlü de aranızda iken dönüp nasıl inkâr edersiniz? Kim Allah’a sımsıkı bağlanırsa, kesinlikle o, doğru yola iletilmiştir."},{"n":102,"t":"Ey iman edenler! Allah’a karşı gelmekten nasıl sakınmak gerekiyorsa, öylece sakının ve siz ancak müslümanlar olarak ölün."},{"n":103,"t":"Hep birlikte Allah’ın ipine (Kur’an’a) sımsıkı sarılın. Parçalanıp bölünmeyin. Allah’ın size olan nimetini hatırlayın. Hani sizler birbirinize düşmanlar idiniz de O, kalplerinizi birleştirmişti. İşte O’nun bu nimeti sayesinde kardeşler olmuştunuz. Yine siz, bir ateş çukurunun tam kenarında idiniz de O sizi oradan kurtarmıştı. İşte Allah size âyetlerini böyle apaçık bildiriyor ki doğru yola eresiniz."},{"n":104,"t":"Sizden, hayra çağıran, iyiliği emreden ve kötülükten men eden bir topluluk bulunsun. İşte kurtuluşa erenler onlardır."},{"n":105,"t":"Kendilerine apaçık deliller geldikten sonra parçalanıp ayrılığa düşenler gibi olmayın. İşte onlar için büyük bir azap vardır."},{"n":106,"t":"O gün bazı yüzler ağarır, bazı yüzler kararır. Yüzleri kararanlara, \"İmanınızdan sonra inkâr ettiniz, öyle mi? Öyle ise inkâr etmenize karşılık azabı tadın\" denilir."},{"n":107,"t":"Yüzleri ağaranlar ise Allah’ın rahmeti içindedirler. Onlar orada ebedî kalacaklardır."},{"n":108,"t":"İşte bunlar Allah’ın, sana hak olarak okuduğumuz âyetleridir. Allah, âlemlere hiç zulüm etmek istemez."},{"n":109,"t":"Göklerdeki her şey, yerdeki her şey Allah’ındır. Bütün işler ancak Allah’a döndürülür."},{"n":110,"t":"Siz, insanlar için çıkarılmış en hayırlı ümmetsiniz. İyiliği emreder, kötülükten men eder ve Allah’a iman edersiniz. Kitap ehli de inansalardı elbette kendileri için hayırlı olurdu. Onlardan iman edenler de var. Ama pek çoğu fasık kimselerdir."},{"n":111,"t":"Onlar size eziyetten başka bir zarar veremezler. Eğer sizinle savaşmaya kalkışsalar, size arkalarını dönüp kaçarlar. Sonra onlara yardım da edilmez."},{"n":112,"t":"Onlar nerede bulunurlarsa bulunsunlar, Allah’ın ve (mü’min) insanların güvencesine sığınmadıkça kendilerini zillet kaplamıştır. Onlar Allah’ın gazabına uğradılar ve yoksulluk onları kapladı. Bunun sebebi onların; Allah’ın âyetlerini inkâr ediyor ve peygamberleri haksız yere öldürüyor olmaları idi. Bütün bunların sebebi ise, isyan etmekte ve (Allah’ın koyduğu) sınırları çiğnemekte oluşları idi."},{"n":113,"t":"Onların (Kitap ehlinin) hepsi bir değildir. Kitap ehli içinde, gece saatlerinde ayakta duran, secdeye kapanarak Allah’ın âyetlerini okuyan bir topluluk da vardır."},{"n":114,"t":"Onlar, Allah’a ve ahiret gününe inanırlar. İyiliği emrederler. Kötülükten men ederler, hayır işlerinde birbirleriyle yarışırlar. İşte onlar salihlerdendir."},{"n":115,"t":"Onlar ne hayır işlerlerse karşılıksız bırakılmayacaklardır. Allah, kendisine karşı gelmekten sakınanları bilir."},{"n":116,"t":"İnkâr edenlerin ne malları ne evlatları, onlara Allah’a karşı bir yarar sağlar. İşte onlar cehennemliktirler. Onlar orada ebedî kalacaklardır."},{"n":117,"t":"Onların bu dünya hayatında harcadıkları malların durumu, kendilerine zulmeden bir topluluğun ekinlerini vurup mahveden kavurucu ve soğuk bir rüzgârın durumu gibidir. Allah, onlara zulmetmedi. Fakat onlar kendi kendilerine zulmediyorlar."},{"n":118,"t":"Ey iman edenler! Sizden olmayanlardan hiçbir sırdaş edinmeyin. Onlar size fenalık etmekten asla geri kalmazlar. Hep sıkıntıya düşmenizi isterler. Onların kinleri konuşmalarından apaçık ortaya çıkmıştır. Kalplerinde gizledikleri ise daha büyüktür. Eğer düşünürseniz size âyetleri açıkladık."},{"n":119,"t":"İşte siz öyle kimselersiniz ki, onları seversiniz; onlar ise, bütün kitaplara iman ettiğiniz hâlde, sizi sevmezler. Onlar sizinle karşılaştıkları zaman \"inandık\" derler. Ama kendi başlarına kaldıklarında, size karşı kinlerinden dolayı parmaklarını ısırırlar. De ki: \"Öfkenizden ölün!\" Şüphesiz Allah, göğüslerin özünü (kalplerde olanı) bilir."},{"n":120,"t":"Size bir iyilik dokunursa, bu onları üzer. Başınıza bir kötülük gelse, ona sevinirler. Eğer siz sabırlı olur, Allah’a karşı gelmekten sakınırsanız, onların hileleri size hiçbir zarar vermez. Çünkü Allah onların işlediklerini kuşatmıştır."},{"n":121,"t":"Hani sen mü’minleri (Uhud’da) savaş mevzilerine yerleştirmek için, sabah erken ailenden (evinden) ayrılmıştın. Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":122,"t":"Hani sizden iki takım (paniğe kapılarak) çözülmeye yüz tutmuştu. Hâlbuki Allah onların yardımcısı idi. Mü’minler, yalnız Allah’a tevekkül etsinler."},{"n":123,"t":"Andolsun, siz son derece güçsüz iken Allah size Bedir’de yardım etmişti. O hâlde Allah’a karşı gelmekten sakının ki şükretmiş olasınız."},{"n":124,"t":"Hani sen mü’minlere, \"Rabbinizin, indirilmiş üç bin melek ile yardım etmesi size yetmez mi?\" diyordun."},{"n":125,"t":"Evet, sabrettiğiniz ve Allah’a karşı gelmekten sakındığınız takdirde; onlar ansızın üzerinize gelseler bile Rabbiniz nişanlı beş bin melekle size yardım eder."},{"n":126,"t":"Allah, bunu size sırf bir müjde olsun ve kalpleriniz bununla yatışsın diye yaptı. Yardım ve zafer ancak mutlak güç sahibi, hüküm ve hikmet sahibi Allah katındadır."},{"n":127,"t":"Bir de Allah bunu, inkâr edenlerden bir kısmını helâk etsin veya perişan etsin de umutsuz olarak dönüp gitsinler diye yaptı."},{"n":128,"t":"Bu işte senin yapacağın bir şey yoktur. Allah, ya tövbelerini kabul edip onları affeder, ya da zalim olduklarından dolayı onlara azap eder."},{"n":129,"t":"Göklerdeki her şey ve yerdeki her şey Allah’ındır. O, dilediğini bağışlar, dilediğine azab eder. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":130,"t":"Ey iman edenler! Kat kat arttırılmış olarak faiz yemeyin. Allah’a karşı gelmekten sakının ki kurtuluşa eresiniz."},{"n":131,"t":"Kâfirler için hazırlanmış ateşten sakının."},{"n":132,"t":"Allah’a ve Peygambere itaat edin ki size merhamet edilsin."},{"n":133,"t":"Rabbinizin bağışına, genişliği göklerle yer arası kadar olan ve Allah’a karşı gelmekten sakınanlar için hazırlanmış bulunan cennete koşun."},{"n":134,"t":"Onlar bollukta ve darlıkta Allah yolunda harcayanlar, öfkelerini yenenler, insanları affedenlerdir. Allah, iyilik edenleri sever."},{"n":135,"t":"Yine onlar, çirkin bir iş yaptıkları, yahut nefislerine zulmettikleri zaman Allah’ı hatırlayıp hemen günahlarının bağışlanmasını isteyenler -ki Allah’tan başka günahları kim bağışlar- ve bile bile işledikleri (günah) üzerinde ısrar etmeyenlerdir."},{"n":136,"t":"İşte onların mükâfatı Rab’leri tarafından bağışlanma ve içinden ırmaklar akan cennetlerdir ki orada ebedî kalacaklardır. (Allah yolunda) çalışanların mükâfatı ne güzeldir!"},{"n":137,"t":"Sizden önce(ki milletlerin başından) nice olaylar gelip geçmiştir. Yeryüzünde gezin dolaşın da yalanlayanların sonunun nasıl olduğunu bir görün."},{"n":138,"t":"Bu (Kur’an), insanlar için bir açıklama, Allah’a karşı gelmekten sakınanlar için bir hidayet ve bir öğüttür."},{"n":139,"t":"Gevşemeyin, hüzünlenmeyin. Eğer (gerçekten) iman etmiş kimseler iseniz üstün olan sizlersiniz."},{"n":140,"t":"Eğer siz (Uhud’da) bir yara aldıysanız, şüphesiz o topluluk da (Müşrikler de Bedir’de) benzeri bir yara almıştı. İşte (iyi veya kötü) günleri insanlar arasında (böyle) döndürür dururuz. (Bazen bir topluma iyi ya da kötü günler gösteririz, bazen öbürüne.) Allah, sizden iman edenleri ayırt etmek, sizden şahitler edinmek için böyle yapar. Allah, zalimleri sevmez."},{"n":141,"t":"Bir de Allah, iman edenleri arındırmak ve küfre sapanları mahvetmek için böyle yapar."},{"n":142,"t":"Yoksa siz; Allah, içinizden cihad edenleri (sınayıp) ayırt etmeden ve yine sabredenleri (sınayıp) ayırt etmeden cennete gireceğinizi mi sandınız?"},{"n":143,"t":"Andolsun, siz ölümle karşılaşmadan önce onu temenni ediyordunuz. İşte onu gördünüz, ama bakıp duruyorsunuz."},{"n":144,"t":"Muhammed, ancak bir peygamberdir. Ondan önce de peygamberler gelip geçmiştir. Şimdi o ölür veya öldürülürse gerisin geriye (eski dininize) mi döneceksiniz? Kim gerisin geriye dönerse, Allah’a hiçbir zarar veremez. Allah, şükredenleri mükâfatlandıracaktır."},{"n":145,"t":"Hiçbir kimse Allah’ın izni olmadan ölmez. Ölüm belirli bir süreye göre yazılmıştır. Kim dünya menfaatini isterse, kendisine ondan veririz. Kim de ahiret mükâfatını isterse, ona da ondan veririz. Biz şükredenleri mükâfatlandıracağız."},{"n":146,"t":"Nice peygamberler var ki, kendileriyle beraber birçok Allah dostu çarpıştı da bunlar Allah yolunda başlarına gelenlerden yılmadılar, zaafa düşmediler, boyun eğmediler. Allah, sabredenleri sever."},{"n":147,"t":"Onların sözleri ancak, \"Rabbimiz! Bizim günahlarımızı ve işimizdeki taşkınlıklarımızı bağışla ve (yolunda) ayaklarımızı sağlam tut. Kâfir topluma karşı bize yardım et\" demekten ibaretti."},{"n":148,"t":"Allah da onlara hem dünya nimetini, hem de ahiretin güzel mükâfatını verdi. Allah, güzel davrananları sever."},{"n":149,"t":"Ey iman edenler! Siz eğer kâfir olanlara uyarsanız sizi gerisin geriye (küfre) çevirirler de büsbütün hüsrana uğrarsınız."},{"n":150,"t":"Hayır! Yalnız Allah yardımcınızdır. O, yardımcıların en hayırlısıdır."},{"n":151,"t":"Hakkında hiçbir delil indirmediği şeyleri Allah’a ortak koştuklarından dolayı; inkâr edenlerin kalplerine korku salacağız. Barınakları da cehennemdir. Zalimlerin kalacakları yer ne kötüdür."},{"n":152,"t":"Andolsun, Allah, izniyle, onları (müşrikleri) kırıp geçirdiğiniz sırada size olan va’dini gerçekleştirdi. Nihayet sevdiğiniz şeyi (zaferi) size gösterdikten sonra, za’f gösterdiniz. (Peygamber’in verdiği) emir konusunda tartıştınız ve emre karşı geldiniz. İçinizden dünyayı isteyenler de vardı, ahireti isteyenler de. Sonra sizi denemek için onlardan yüzünüzü çevirdi. (Kaçıp hezimete uğradınız. Buna rağmen) sizi bağışladı. Allah, mü’minlere karşı çok lütufkârdır."},{"n":153,"t":"Peygamber, arkanızdan sizi çağırırken siz durmadan dağa yukarı kaçıyor, hiç kimseye dönüp bakmıyordunuz. Bundan dolayı Allah, size keder üstüne keder verdi ki, (bu durumlara alışasınız ve daha sonra) elinizden gidene, ve başınıza gelene üzülmeyesiniz. Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":154,"t":"Sonra o kederin ardından (Allah) üzerinize içinizden bir kısmını örtüp bürüyen bir güven, bir uyku indirdi. Bir kısmınız da kendi canlarının kaygısına düşmüştü. Allah’a karşı cahiliye zannı gibi gerçek dışı zanda bulunuyorlar; \"Bu işte bizim hiçbir dahlimiz yok\" diyorlardı. De ki: \"Bütün iş, Allah’ındır.\" Onlar sana açıklayamadıklarını içlerinde saklıyorlar ve diyorlar ki: \"Bu konuda bizim elimizde bir şey olsaydı, burada öldürülmezdik.\" De ki: \"Evlerinizde dahi olsaydınız, üzerlerine öldürülmesi yazılmış bulunanlar mutlaka yatacakları (öldürülecekleri) yerlere çıkıp gideceklerdi. Allah, bunu göğüslerinizdekini denemek, kalplerinizdekini arındırmak için yaptı. Allah, göğüslerin özünü (kalplerde olanı) bilir.\""},{"n":155,"t":"İki topluluğun karşılaştığı gün, içinizden yüz çevirip kaçanları, şeytan ancak yaptıkları bazı hatalardan dolayı yoldan kaydırmak istemişti. Ama yine de Allah onları affetti. Kuşkusuz Allah çok bağışlayandır, halîmdir (hemen cezalandırmaz, mühlet verir)."},{"n":156,"t":"Ey iman edenler! Kardeşleri sefere veya savaşa çıktığında onlar hakkında, \"Onlar bizim yanımızda olsalardı, ölmezlerdi ve öldürülmezlerdi\" diyen inkârcılar gibi olmayın. Allah, bunu (bu düşünceyi) onların kalplerine bir hasret (yarası) olarak koydu. Allah, yaşatır ve öldürür. Allah, yaptıklarınızı görmektedir."},{"n":157,"t":"Andolsun, eğer Allah yolunda öldürülür veya ölürseniz, Allah’ın bağışlaması ve rahmeti onların topladıkları (dünyalıkları)ndan daha hayırlıdır."},{"n":158,"t":"Andolsun, ölseniz de öldürülseniz de, Allah’ın huzurunda toplanacaksınız."},{"n":159,"t":"Allah’ın rahmeti sayesinde sen onlara karşı yumuşak davrandın. Eğer kaba, katı yürekli olsaydın, onlar senin etrafından dağılıp giderlerdi. Artık sen onları affet. Onlar için Allah’tan bağışlama dile. İş konusunda onlarla müşavere et. Bir kere de karar verip azmettin mi, artık Allah’a tevekkül et, (ona dayanıp güven). Şüphesiz Allah, tevekkül edenleri sever."},{"n":160,"t":"Allah size yardım ederse, sizi yenecek yoktur. Eğer sizi yardımsız bırakırsa, ondan sonra size kim yardım edebilir? Mü’minler, ancak Allah’a tevekkül etsinler."},{"n":161,"t":"Hiçbir peygamberin emanete hıyanet etmesi düşünülemez. Kim hıyanet ederse, kıyamet günü, hıyanet ettiği şeyle birlikte gelir. Sonra da hiçbir haksızlığa uğratılmaksızın herkese kazandığının karşılığı tastamam ödenir."},{"n":162,"t":"Allah’ın rızasına uyan kimse, Allah’ın gazabına uğrayan ve varacağı yer cehennem olan kimse gibi midir? O, ne kötü varılacak yerdir!"},{"n":163,"t":"Onlar (insanlar) Allah’ın katında derece derecedirler. Allah, onların yaptıklarını görmektedir."},{"n":164,"t":"Andolsun, Allah, mü’minlere kendi içlerinden; onlara âyetlerini okuyan, onları arıtıp tertemiz yapan, onlara kitab ve hikmeti öğreten bir peygamber göndermekle büyük bir lütufta bulunmuştur. Oysa onlar, daha önce apaçık bir sapıklık içinde idiler."},{"n":165,"t":"Onların (müşriklerin) başına (Bedir’de) iki mislini getirdiğiniz bir musibet (Uhud’da) sizin başınıza geldiğinde, \"Bu, nereden başımıza geldi?\" dediniz, öyle mi? De ki: \"O (musibet), kendinizdendir.\" Şüphesiz Allah’ın gücü her şeye hakkıyla yeter."},{"n":"166-167","t":"İki topluluğun (ordunun) karşılaştığı günde başınıza gelen musibet Allah’ın izniyledir. Bu da mü’minleri ortaya çıkarması ve münafıklık yapanları belli etmesi içindi. Onlara (münafıklara), \"Gelin, Allah yolunda savaşın veya savunmaya geçin\" denildi de onlar, \"Eğer savaşmayı bilseydik, arkanızdan gelirdik\" dediler. Onlar o gün, imandan çok küfre yakın idiler. Ağızlarıyla kalplerinde olmayanı söylüyorlardı. Oysa Allah, içlerinde gizledikleri şeyi çok iyi bilmektedir."},{"n":168,"t":"(Onlar), kendileri oturup kaldıkları hâlde kardeşleri için, \"Eğer bize uysalardı, öldürülmezlerdi\" diyen kimselerdir. De ki: \"Eğer doğru söyleyenler iseniz kendinizden ölümü savın.\""},{"n":"169-170","t":"Allah yolunda öldürülenleri sakın ölüler sanma. Bilakis onlar diridirler, Rableri katında Allah’ın, lütfundan kendilerine verdiği nimetlerin sevincini yaşayarak rızıklandırılmaktadırlar. Arkalarından kendilerine ulaşamayan (henüz şehit olmamış) kimselere de hiçbir korku olmayacağına ve onların üzülmeyeceklerine sevinirler."},{"n":171,"t":"(Şehitler) Allah’ın nimetine, keremine ve Allah’ın, mü’minlerin ecrini zayi etmeyeceğine sevinirler."},{"n":172,"t":"Onlar yaralandıktan sonra Allah’ın ve Peygamberinin davetine uyan kimselerdir. Onlardan güzel davranıp iyilik edenlere ve Allah’a karşı gelmekten sakınanlara büyük bir mükâfat vardır."},{"n":173,"t":"Onlar öyle kimselerdir ki, halk kendilerine, \"İnsanlar size karşı ordu toplamışlar, onlardan korkun\" dediklerinde, bu söz onların imanını artırdı ve \"Allah bize yeter, O ne güzel vekildir!\" dediler."},{"n":174,"t":"Bundan dolayı Allah’tan bir nimet ve lütufla kendilerine hiçbir fenalık dokunmadan geri döndüler ve Allah’ın rızasına uydular. Allah, büyük lütuf sahibidir."},{"n":175,"t":"O şeytan sizi ancak kendi dostlarından korkutuyor. Onlardan korkmayın, eğer mü’min iseniz, benden korkun."},{"n":176,"t":"Küfürde yarışanlar seni üzmesin. Onlar, Allah’a hiçbir şekilde zarar veremezler. Allah, onlara ahirette bir pay vermemek istiyor. Onlar için büyük azap vardır."},{"n":177,"t":"İman karşılığında küfrü satın alanlar Allah’a hiçbir zarar veremezler. Onlar için elem verici bir azap vardır."},{"n":178,"t":"İnkâr edenler, kendilerine vermiş olduğumuz mühletin, sakın kendileri için hayırlı olduğunu sanmasınlar. Biz, onlara ancak günahları artsın diye mühlet veriyoruz. Onlar için alçaltıcı bir azap vardır."},{"n":179,"t":"Allah, pisi temizden ayırıncaya kadar mü’minleri içinde bulunduğunuz şu durumda bırakacak değildir. Allah, size gaybı bildirecek de değildir. Fakat Allah, peygamberlerinden dilediğini seçer (gaybı ona bildirir). O hâlde, Allah’a ve peygamberlerine iman edin. Eğer iman eder ve Allah’a karşı gelmekten sakınırsanız sizin için büyük bir mükâfat vardır."},{"n":180,"t":"Allah’ın kendilerine lütfundan verdiği nimetlerde cimrilik edenler, bunun, kendileri için hayırlı olduğunu sanmasınlar. Hayır! O kendileri için bir şerdir. Cimrilik ettikleri şey kıyamet gününde boyunlarına dolanacaktır. Göklerin ve yerin mirası Allah’ındır. Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":181,"t":"Allah; \"Şüphesiz, Allah fakirdir, biz zenginiz\" diyenlerin sözünü elbette duydu. Onların dediklerini ve haksız yere peygamberleri öldürmelerini yazacağız ve, \"Tadın yangın azabını!\" diyeceğiz."},{"n":182,"t":"\"Bu, kendi ellerinizin (önceden yapıp) gönderdiklerinin karşılığıdır.\" Allah, kullara asla zulmedici değildir."},{"n":183,"t":"Onlar, \"Allah, bize, ateşin yiyeceği bir kurban getirmedikçe hiçbir peygambere inanmamamızı emretti\" dediler. De ki: \"Benden önce size nice peygamberler, açık belgeleri ve sizin dediğiniz şeyi getirdi. Eğer doğru söyleyenler iseniz, niçin onları öldürdünüz?\""},{"n":184,"t":"Eğer seni yalanladılarsa, senden önce açık delilleri, hikmetli sayfaları ve aydınlatıcı kitabı getiren peygamberler de yalanlanmıştı."},{"n":185,"t":"Her canlı ölümü tadacaktır. Ancak kıyamet günü yaptıklarınızın karşılığı size tastamam verilecektir. Kim cehennemden uzaklaştırılıp cennete sokulursa, gerçekten kurtuluşa ermiştir. Dünya hayatı, aldatıcı metadan başka bir şey değildir."},{"n":186,"t":"Andolsun, mallarınız ve canlarınız konusunda imtihana çekileceksiniz. Sizden önce kendilerine kitap verilenlerden ve Allah’a ortak koşanlardan üzücü birçok söz işiteceksiniz. Eğer sabreder ve Allah’a karşı gelmekten sakınırsanız bilin ki, bunlar (yapmaya değer) azmi gerektiren işlerdendir."},{"n":187,"t":"Hani Allah, kendilerine kitap verilenlerden, \"Onu (Kitabı) mutlaka insanlara açıklayacaksınız, onu gizlemeyeceksiniz\" diye sağlam söz almıştı. Fakat onlar verdikleri sözü, arkalarına atıp onu az bir karşılığa değiştiler. Yaptıkları bu alışveriş ne kadar kötüdür!"},{"n":188,"t":"Ettiklerine sevinen ve yapmadıkları şeylerle övülmeyi seven kimselerin, sakın azaptan kurtulacaklarını sanma. Onlar için elem dolu bir azap vardır."},{"n":189,"t":"Göklerin ve yerin hükümranlığı Allah’ındır. Allah, her şeye hakkıyla gücü yetendir."},{"n":190,"t":"Göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelip gidişinde selim akıl sahipleri için elbette ibretler vardır."},{"n":191,"t":"Onlar ayaktayken, otururken ve yanları üzerine yatarken Allah’ı anarlar. Göklerin ve yerin yaratılışı üzerinde düşünürler. \"Rabbimiz! Bunu boş yere yaratmadın, seni eksikliklerden uzak tutarız. Bizi ateş azabından koru\" derler."},{"n":192,"t":"\"Rabbimiz! Sen kimi cehennem ateşine sokarsan, onu rezil etmişsindir. Zalimlerin hiç yardımcıları yoktur.\""},{"n":193,"t":"\"Rabbimiz! Biz, ‘Rabbinize iman edin’ diye imana çağıran bir davetçi işittik, hemen iman ettik. Rabbimiz! Günahlarımızı bağışla. Kötülüklerimizi ört. Canımızı iyilerle beraber al.\""},{"n":194,"t":"\"Rabbimiz! Peygamberlerin aracılığı ile bize va’dettiklerini ver bize. Kıyamet günü bizi rezil etme. Şüphesiz sen, va’dinden dönmezsin.\""},{"n":195,"t":"Rableri, onlara şu karşılığı verdi: \"Ben, erkek olsun, kadın olsun, sizden hiçbir çalışanın amelini zayi etmeyeceğim. Sizler birbirinizdensiniz. Hicret edenler, yurtlarından çıkarılanlar, yolumda eziyet görenler, savaşanlar ve öldürülenlerin de andolsun, günahlarını elbette örteceğim. Allah katından bir mükâfat olmak üzere, onları içinden ırmaklar akan cennetlere koyacağım. Mükâfatın en güzeli Allah katındadır.\""},{"n":196,"t":"Kâfirlerin refah içinde diyar diyar dolaşmaları sakın seni aldatmasın."},{"n":197,"t":"(Onların bu refahı) az bir yararlanmadır. Sonra onların barınağı cehennemdir. Ne kötü bir yataktır orası!"},{"n":198,"t":"Fakat Rablerine karşı gelmekten sakınanlar için, Allah katından bir konaklama yeri olarak, içinde ebedî kalacakları, içinden ırmaklar akan cennetler vardır. Allah katında olan şeyler iyiler için daha hayırlıdır."},{"n":199,"t":"Kitap ehlinden öyleleri var ki, Allah’a, size indirilene ve kendilerine indirilene, Allah’a derinden saygı duyarak inanırlar. Allah’ın âyetlerini az bir değere satmazlar. Onlar var ya, işte onların, Rableri katında mükâfatları vardır. Şüphesiz Allah, hesabı çabuk görendir."},{"n":200,"t":"Ey iman edenler! Sabredin. Sabır yarışında düşmanlarınızı geçin. (Cihat için) hazırlıklı ve uyanık olun ve Allah’a karşı gelmekten sakının ki kurtuluşa eresiniz."}],[{"n":1,"t":"Ey insanlar! Sizi bir tek nefisten yaratan ve ondan da eşini yaratan; ikisinden birçok erkek ve kadın (meydana getirip) yayan Rabbinize karşı gelmekten sakının. Kendisi adına birbirinizden dilekte bulunduğunuz Allah’a karşı gelmekten ve akrabalık bağlarını koparmaktan sakının. Şüphesiz Allah, üzerinizde bir gözetleyicidir."},{"n":2,"t":"Yetimlere mallarını verin. Temizi pis olanla (helâli haramla) değişmeyin. Onların mallarını kendi mallarınıza katıp yemeyin. Çünkü bu, büyük bir günahtır."},{"n":3,"t":"Eğer, (velisi olduğunuz) yetim kızlar (ile evlenip onlar) hakkında adaletsizlik etmekten korkarsanız, (onları değil), size helâl olan (başka) kadınlardan ikişer, üçer, dörder olmak üzere nikâhlayın. Eğer (o kadınlar arasında da) adaletli davranmayacağınızdan korkarsanız, o taktirde bir tane alın veya sahip olduğunuz (cariyeler) ile yetinin. Bu, adaletten ayrılmamanız için daha uygundur."},{"n":4,"t":"Kadınlara mehirlerini (bir görev olarak) gönül hoşluğuyla verin. Eğer kendi istekleriyle o mehrin bir kısmını size bağışlarlarsa, onu da afiyetle yiyin."},{"n":5,"t":"Allah’ın, sizin için geçim kaynağı yaptığı mallarınızı aklı ermezlere vermeyin. O mallarla onları besleyin, giydirin ve onlara güzel söz söyleyin."},{"n":6,"t":"Yetimleri deneyin. Evlenme çağına (buluğa) erdiklerinde, eğer reşid olduklarını görürseniz, mallarını kendilerine verin. Büyüyecekler (ve mallarını geri alacaklar) diye israf ederek ve aceleye getirerek mallarını yemeyin. (Velilerden) kim zengin ise (yetim malından yemeğe) tenezzül etmesin. Kim de fakir ise, aklın ve dinin gereklerine uygun bir biçimde (hizmetinin karşılığı kadar) yesin. Mallarını kendilerine geri verdiğiniz zaman da yanlarında şahit bulundurun. Hesap görücü olarak Allah yeter."},{"n":7,"t":"Ana, baba ve akrabaların (miras olarak) bıraktıklarından erkeklere bir pay vardır. Ana, baba ve akrabaların bıraktıklarından kadınlara da bir pay vardır. Allah, bırakılanın azından da çoğundan da bunları farz kılınmış birer hisse olarak belirlemiştir."},{"n":8,"t":"Miras taksiminde (kendilerine pay düşmeyen) akrabalar, yetimler ve fakirler hazır bulunurlarsa, onlara da maldan bir şeyler verin ve onlara (gönüllerini alacak) güzel sözler söyleyin."},{"n":9,"t":"Kendileri, geriye zayıf çocuklar bıraktıkları takdirde, onlar hakkında endişeye kapılanlar, (yetimler hakkında da) ürperip korksunlar. Allah’a karşı gelmekten sakınsınlar ve doğru söz söylesinler."},{"n":10,"t":"Yetimlerin mallarını haksız yere yiyenler, ancak ve ancak karınlarını doldurasıya ateş yemiş olurlar ve zaten onlar çılgın bir ateşe (cehenneme) gireceklerdir."},{"n":11,"t":"Allah, size, çocuklarınız(ın alacağı miras) hakkında, erkeğe iki dişinin payı kadarını emreder. (Çocuklar sadece) ikiden fazla kız iseler, (ölenin geriye) bıraktığının üçte ikisi onlarındır. Eğer kız bir ise (mirasın) yarısı onundur. Ölenin çocuğu varsa, geriye bıraktığı maldan, ana babasından her birinin altıda bir hissesi vardır. Eğer çocuğu yok da (yalnız) ana babası ona varis oluyorsa, anasına üçte bir düşer. Eğer kardeşleri varsa, anasının hissesi altıda birdir. (Bu paylaştırma, ölenin) yapacağı vasiyetten ya da borcundan sonradır. Babalarınız ve oğullarınızdan, hangisinin size daha faydalı olduğunu bilemezsiniz. Bunlar, Allah tarafından farz kılınmıştır. Şüphesiz Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":12,"t":"Eğer çocukları yoksa, karılarınızın geriye bıraktıklarının yarısı sizindir. Eğer çocukları varsa, bıraktıklarının dörtte biri sizindir. (Bu paylaştırma, ölen karılarınızın) yaptıkları vasiyetlerin yerine getirilmesi, yahut borçlarının ödenmesinden sonradır. Eğer sizin çocuğunuz yoksa, bıraktığınızın dörtte biri onlarındır. Eğer çocuğunuz varsa, bıraktığınızın sekizde biri onlarındır. (Yine bu paylaştırma) yaptığınız vasiyetin yerine getirilmesinden, yahut borçlarınızın ödenmesinden sonradır. Eğer kendisine varis olunan bir erkek veya bir kadının evladı ve babası olmaz ve bir erkek veya bir kız kardeşi bulunursa, ona altıda bir düşer. Eğer (kardeşler) birden fazla olurlarsa, üçte birde ortaktırlar. (Bu paylaştırma varislere) zarar vermeksizin yapılan vasiyetin yerine getirilmesinden, yahut borcun ödenmesinden sonra yapılır. (Bütün bunlar) Allah’ın emridir. Allah, hakkıyla bilendir, halîmdir (hemen cezalandırmaz, mühlet verir.)"},{"n":13,"t":"İşte bu (hükümler) Allah’ın koyduğu sınırlarıdır. Kim Allah’a ve Peygamberine itaat ederse, Allah onu, içinden ırmaklar akan, içinde ebedî kalacakları cennetlere sokar. İşte bu büyük başarıdır."},{"n":14,"t":"Kim de Allah’a ve Peygamberine isyan eder ve O’nun koyduğu sınırları aşarsa, Allah onu ebedî kalacağı cehennem ateşine sokar. Onun için alçaltıcı bir azap vardır."},{"n":15,"t":"Kadınlarınızdan fuhuş (zina) yapanlara karşı içinizden dört şahit getirin. Eğer onlar şahitlik ederlerse, o kadınları ölüm alıp götürünceye veya Allah onlar hakkında bir yol açıncaya kadar kendilerini evlerde tutun (dışarı çıkarmayın)."},{"n":16,"t":"Sizlerden fuhuş (zina) yapanların her ikisini de incitip kınayın. Eğer onlar tövbe edip ıslah olurlarsa, onları incitip kınamaktan vazgeçin. Çünkü Allah, tövbeleri çok kabul edendir, çok merhamet edendir."},{"n":17,"t":"Allah katında (makbul) tövbe, ancak bilmeyerek günah işleyip sonra çok geçmeden tövbe edenlerin tövbesidir. İşte Allah, bunların tövbelerini kabul buyurur. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":18,"t":"Yoksa (makbul) tövbe, kötülükleri (günahları) yapıp yapıp da kendisine ölüm gelip çatınca, \"İşte ben şimdi tövbe ettim\" diyen kimseler ile kâfir olarak ölenlerinki değildir. Bunlar için ahirette elem dolu bir azap hazırlamışızdır."},{"n":19,"t":"Ey iman edenler! Kadınlara zorla mirasçı olmanız size helâl değildir. Açık bir hayâsızlık yapmış olmaları dışında, kendilerine verdiklerinizin bir kısmını onlardan geri almak için onları sıkıştırmayın. Onlarla iyi geçinin. Eğer onlardan hoşlanmadıysanız, olabilir ki, siz bir şeyden hoşlanmazsınız da Allah onda pek çok hayır yaratmış olur."},{"n":20,"t":"Eğer bir eşin yerine başka bir eş almak isterseniz, öbürüne (mehir olarak) yüklerle mal vermiş olsanız dahi ondan hiçbir şeyi geri almayın. İftira ederek ve açık günaha girerek mi verdiğinizi geri alacaksınız?"},{"n":21,"t":"Hem, siz eşlerinizle birleşmiş ve onlar da sizden sağlam bir söz almış iken, onu nasıl (geri) alırsınız?"},{"n":22,"t":"Geçmişte olanlar hariç, artık babalarınızın evlendiği kadınlarla evlenmeyin. Çünkü bu bir hayâsızlık, öfke ve nefret gerektiren bir iştir. Bu, ne kötü bir yoldur."},{"n":23,"t":"Size şunlarla evlenmek haram kılındı: Analarınız, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, erkek kardeş kızları, kız kardeş kızları, sizi emziren sütanneleriniz, süt kız kardeşleriniz, karılarınızın anneleri, kendileriyle zifafa girdiğiniz karılarınızdan olup evlerinizde bulunan üvey kızlarınız, -eğer anneleri ile zifafa girmemişseniz onlarla evlenmenizde size bir günah yoktur- öz oğullarınızın karıları, iki kız kardeşi (nikâh altında) bir araya getirmeniz. Ancak geçenler (önceden yapılan bu tür evlilikler) başka. Şüphesiz Allah çok bağışlayıcıdır, çok merhamet edicidir."},{"n":24,"t":"(Savaş esiri olarak) sahip olduklarınız hariç, evli kadınlar (da size) haram kılındı. (Bunlar) üzerinize Allah’ın emri olarak yazılmıştır. Bunların dışında kalanlar ise, iffetli yaşamak ve zina etmemek şartıyla mallarınızla (mehirlerini verip) istemeniz size helâl kılındı. Onlardan (nikâhlanıp) faydalanmanıza karşılık sabit bir hak olarak kendilerine mehirlerini verin. Mehir belirlendikten sonra, onunla ilgili olarak uzlaştığınız şeyler konusunda size günah yoktur. Şüphesiz ki Allah (her şeyi) hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":25,"t":"Sizden kimin, hür mü’min kadınlarla evlenmeye gücü yetmezse sahip olduğunuz mü’min genç kızlarınızdan (cariyelerinizden) alsın. Allah, sizin imanınızı daha iyi bilir. Hepiniz birbirinizdensiniz. Öyle ise iffetli yaşamaları, zina etmemeleri ve gizli dost tutmamaları hâlinde, sahiplerinin izniyle onlarla evlenin, mehirlerini de güzelce verin. Evlendikten sonra bir fuhuş yaparlarsa, onlara hür kadınların cezasının yarısı uygulanır. Bu (cariye ile evlenme izni), içinizden günaha düşmekten korkanlar içindir. Sabretmeniz ise sizin için daha hayırlıdır. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":26,"t":"Allah, size (hükümlerini) açıklamak, size, sizden öncekilerin yollarını göstermek ve tövbelerinizi kabul etmek istiyor. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":27,"t":"Allah, sizin tövbenizi kabul etmek istiyor. Şehvetlerine uyanlar ise sizin büyük bir sapıklığa düşmenizi istiyorlar."},{"n":28,"t":"Allah, sizden (yükümlülükleri) hafifletmek istiyor. Çünkü insan zayıf yaratılmıştır."},{"n":29,"t":"Ey iman edenler! Mallarınızı aranızda batıl yollarla yemeyin. Ancak karşılıklı rıza ile yapılan ticaretle olursa başka. Kendinizi helâk etmeyin. Şüphesiz Allah, size karşı çok merhametlidir."},{"n":30,"t":"Kim haddi aşarak ve zulmederek bunu yaparsa, onu cehennem ateşine atacağız. Bu, Allah’a pek kolaydır."},{"n":31,"t":"Eğer size yasaklanan (günah)ların büyüklerinden kaçınırsanız, sizin küçük günahlarınızı örteriz ve sizi güzel bir yere koyarız."},{"n":32,"t":"Allah’ın, kiminizi kiminize üstün kılmaya vesile yaptığı şeyleri (haset ederek) arzu edip durmayın. Erkeklere kazandıklarından bir pay vardır. Kadınlara da kazandıklarından bir pay vardır. Allah’tan, O’nun lütfunu isteyin. Şüphesiz Allah, her şeyi hakkıyla bilendir."},{"n":33,"t":"(Erkek ve kadından) her biri için ana-babanın ve akrabanın bıraktıklarından (pay alan) varisler kıldık. Yeminlerinizin bağladığı (ahitleştiğiniz) kimselere de kendi hisselerini verin. Şüphesiz Allah her şeye şahittir."},{"n":34,"t":"Erkekler, kadınların koruyup kollayıcılarıdırlar. Çünkü Allah, insanların kimini kiminden üstün kılmıştır. Bir de erkekler kendi mallarından harcamakta (ve ailenin geçimini sağlamakta)dırlar. İyi kadınlar, itaatkârdırlar. Allah’ın (kendilerini) koruması sayesinde onlar da \"gayb\"ı korurlar. (Evlilik yükümlülüklerini reddederek) başkaldırdıklarını gördüğünüz kadınlara öğüt verin, onları yataklarında yalnız bırakın. (Bunlar fayda vermez de mecbur kalırsanız) onları (hafifçe) dövün. Eğer itaat ederlerse, artık onların aleyhine başka bir yol aramayın. Şüphesiz Allah, çok yücedir, çok büyüktür."},{"n":35,"t":"Eğer karı-kocanın arasının açılmasından endişe ederseniz, erkeğin ailesinden bir hakem, kadının ailesinden bir hakem gönderin. İki taraf (arayı) düzeltmek isterlerse, Allah da onları uzlaştırır. Şüphesiz Allah, hakkıyla bilendir, hakkıyla haberdardır."},{"n":36,"t":"Allah’a ibadet edin ve ona hiçbir şeyi ortak koşmayın. Ana babaya, akrabaya, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolcuya, elinizin altındakilere iyilik edin. Şüphesiz Allah, kibirlenen ve övünen kimseleri sevmez."},{"n":37,"t":"Bunlar cimrilik eden, insanlara da cimriliği emreden ve Allah’ın, lütfundan kendilerine verdiği nimeti gizleyen kimselerdir. Biz de o nankörlere alçaltıcı bir azap hazırlamışızdır."},{"n":38,"t":"Bunlar, mallarını insanlara gösteriş için harcayan, Allah’a ve ahiret gününe de inanmayan kimselerdir. Şeytan kimin arkadaşı olursa, o ne kötü arkadaştır."},{"n":39,"t":"Bunlar, Allah’a ve ahiret gününe iman etselerdi ve Allah’ın verdiği rızıktan (gösterişsiz olarak) harcasalardı, kendilerine ne zarar gelirdi? Allah, onları en iyi bilendir."},{"n":40,"t":"Şüphesiz Allah (hiç kimseye) zerre kadar zulüm etmez. (Yapılan) çok küçük bir iyilik de olsa onun sevabını kat kat arttırır ve kendi katından büyük bir mükâfat verir."},{"n":41,"t":"Her ümmetten bir şahit getirdiğimiz ve seni de onların üzerine bir şahit yaptığımız zaman, bakalım onların hâli nice olacak!."},{"n":42,"t":"O kıyamet günü, Allah’ı inkâr edip Peygamber’e isyan edenler, yer yarılıp içine girmiş olmayı isterler ve Allah’tan hiçbir söz gizleyemezler."},{"n":43,"t":"Ey iman edenler! Sarhoş iken ne söylediğinizi bilinceye kadar, bir de -yolcu olmanız durumu müstesna- cünüp iken yıkanıncaya kadar namaza yaklaşmayın. Eğer hasta olur veya yolculukta bulunursanız, veyahut biriniz abdest bozmaktan gelince ya da eşlerinizle cinsel ilişkide bulunup, su da bulamazsanız o zaman temiz bir toprağa yönelip, (niyet ederek onunla) yüzlerinizi ve ellerinizi meshedin. Şüphesiz Allah, çok affedicidir, çok bağışlayıcıdır."},{"n":44,"t":"Kendilerine Kitap’tan bir nasip verilmiş olanları görmüyor musun? Onlar sapıklığı satın alıyorlar ve sizin de yoldan sapmanızı istiyorlar."},{"n":45,"t":"Allah, sizin düşmanlarınızı çok daha iyi bilir. Allah, dost olarak yeter. Allah, yardımcı olarak da yeter."},{"n":46,"t":"Yahudilerden öyleleri var ki, (kelimeleri yerlerinden kaydırıp) tahrif ederek onları anlamlarından uzaklaştırırlar. Dillerini eğip bükerek ve dine saldırarak \"İşittik, karşı geldik\", \"İşit, işitmez olası!\" \"Râ’inâ\" derler. Hâlbuki onlar, \"İşittik ve itaat ettik; dinle ve bize bak\" deselerdi, bu kendileri için daha hayırlı olurdu. Fakat Allah, küfürleri yüzünden kendilerini lânetlemiştir. Bu yüzden pek az iman ederler."},{"n":47,"t":"Ey kendilerine kitap verilenler! Birtakım yüzleri silip de tersine çevirmeden, yahut cumartesi halkını lânetlediğimiz gibi onları lânetlemeden, yanınızda bulunanı (Tevrat’ı) doğrulayıcı olarak indirdiğimiz bu kitaba (Kur’an’a) iman edin. Allah’ın emri mutlaka yerine gelecektir."},{"n":48,"t":"Şüphesiz Allah, kendisine ortak koşulmasını asla bağışlamaz. Bunun dışında kalan (günah)ları ise dilediği kimseler için bağışlar. Allah’a şirk koşan kimse, şüphesiz büyük bir günah işleyerek iftira etmiş olur."},{"n":49,"t":"Kendilerini temize çıkaranları görmedin mi? Hayır! Allah, dilediğini temize çıkarır ve kendilerine kıl kadar zulmedilmez."},{"n":50,"t":"Bak, Allah’a karşı nasıl yalan uyduruyorlar. Apaçık bir günah olarak bu yeter."},{"n":51,"t":"Kendilerine Kitap’tan bir nasip verilmiş olanları görmüyor musun? Onlar \"cibt\"e ve \"tâğût\"a inanıyorlar. İnkâr edenler için de, \"Bunlar, iman edenlerden daha doğru yoldadır\" diyorlar."},{"n":52,"t":"Onlar, Allah’ın lânet ettiği kimselerdir. Allah, kime lânet ederse, artık ona asla bir yardımcı bulamazsın."},{"n":53,"t":"Yoksa onların hükümranlıkta bir payı mı var? Öyle olsa, insanlara bir zerre bile vermezler."},{"n":54,"t":"Yoksa, insanları; Allah’ın lütfundan kendilerine verdiği şey dolayısıyla kıskanıyorlar mı? Şüphesiz biz, İbrahim ailesine de kitap ve hikmet vermişizdir. Onlara büyük bir hükümranlık da vermiştik."},{"n":55,"t":"Böylece onlardan kimi ona iman etti, kimi de sırt çevirdi. (O iman etmeyenlere) çılgın ateş olarak cehennem yeter."},{"n":56,"t":"Şüphesiz âyetlerimizi inkâr edenleri biz ateşe atacağız. Derileri yanıp döküldükçe, azabı tatmaları için onların derilerini yenileyeceğiz. Şüphesiz Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":57,"t":"İman edip salih ameller işleyenleri ise, içinden ırmaklar akan, içlerinde ebedî kalacakları cennetlere koyacağız. Onlara orada tertemiz eşler vardır. Onları, koyu gölgeler altında bulunduracağız."},{"n":58,"t":"Allah, size, emanetleri mutlaka ehline vermenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emrediyor. Doğrusu Allah, bununla size ne güzel öğüt veriyor! Şüphesiz ki Allah, hakkıyla işitendir, hakkıyla görendir."},{"n":59,"t":"Ey iman edenler! Allah’a itaat edin. Peygamber’e itaat edin ve sizden olan ulu’l-emre (idarecilere) de. Herhangi bir hususta anlaşmazlığa düştüğünüz takdirde, Allah’a ve ahiret gününe gerçekten inanıyorsanız, onu Allah ve Resûlüne arz edin. Bu, daha iyidir, sonuç bakımından da daha güzeldir."},{"n":60,"t":"(Ey Muhammed!) Sana indirilen Kur’an’a ve senden önce indirilene inandıklarını iddia edenleri görmüyor musun? Tâğût’u tanımamaları kendilerine emrolunduğu hâlde, onun önünde muhakeme olmak istiyorlar. Şeytan da onları derin bir sapıklığa düşürmek istiyor."},{"n":61,"t":"Münafıklara, \"Allah’ın indirdiğine (Kur’an’a) ve Peygambere gelin\" dendiği zaman, onların senden büsbütün uzaklaştıklarını görürsün."},{"n":62,"t":"Kendi işledikleri yüzünden başlarına bir musibet geldiği, sonra da \"Biz iyilik etmek ve uzlaştırmaktan başka bir şey istememiştik\" diye Allah’a yemin ederek sana geldikleri zaman hâlleri nasıl olur?"},{"n":63,"t":"Onlar, Allah’ın kalplerindekini bildiği kimselerdir. Öyleyse onlara aldırma. Onlara öğüt ver ve onlara, kendileri hakkında etkili ve güzel söz söyle."},{"n":64,"t":"Biz her peygamberi sırf, Allah’ın izni ile itaat edilmek üzere gönderdik. Eğer onlar kendilerine zulmettikleri zaman sana gelseler de Allah’tan günahlarının bağışlamasını dileseler ve Peygamber de onlara bağışlama dileseydi, elbette Allah’ı tövbeleri çok kabul edici ve çok merhametli bulacaklardı."},{"n":65,"t":"Hayır! Rabbine andolsun ki onlar, aralarında çıkan çekişmeli işlerde seni hakem yapıp, sonra da verdiğin hükme, içlerinde hiçbir sıkıntı duymaksızın, tam bir teslimiyetle boyun eğmedikçe iman etmiş olmazlar."},{"n":66,"t":"Eğer biz onlara, \"Hayatlarınızı feda edin veya yurtlarınızdan çıkın\" diye yazmış olsaydık, içlerinden pek azı hariç, bunu yapmazlardı. Eğer kendilerine verilen öğütleri tutsalardı, elbette haklarında hem daha hayırlı, hem de (imanlarını) daha çok pekiştirici olurdu."},{"n":67,"t":"O zaman kendilerine elbette katımızdan büyük bir mükâfat verirdik."},{"n":68,"t":"Onları elbette doğru yola iletirdik."},{"n":69,"t":"Kim Allah’a ve Peygambere itaat ederse, işte onlar, Allah’ın kendilerine nimet verdiği peygamberlerle, sıddîklarla, şehidlerle ve iyi kimselerle birliktedirler. Bunlar ne güzel arkadaştır."},{"n":70,"t":"Bu lütuf Allah’tandır. Hakkıyla bilen olarak Allah yeter."},{"n":71,"t":"Ey iman edenler! (Düşmana karşı) tedbirinizi alıp, küçük birlikler hâlinde, yahut topluca savaşa gidin."},{"n":72,"t":"Şüphesiz, aranızda öyle kimseler var ki, (onların her biri savaşa gitme konusunda) hakikaten pek ağır davranır. Eğer başınıza bir musibet gelirse, \"Allah, bana lütfetti de onlarla beraber bulunmadım\" der."},{"n":73,"t":"Eğer Allah’tan size bir lütuf (zafer) erişse, bu sefer de; sizinle kendisi arasında hiç tanışıklık yokmuş gibi şöyle der: \"Keşke ben de onlarla beraber olsaydım da büyük bir başarıya (ganimete) ulaşsaydım.\""},{"n":74,"t":"O hâlde, dünya hayatını ahiret hayatı karşılığında satanlar, Allah yolunda savaşsınlar. Kim Allah yolunda savaşır da öldürülür veya galip gelirse, biz ona büyük bir mükâfat vereceğiz."},{"n":75,"t":"Size ne oluyor da, Allah yolunda ve \"Ey Rabbimiz! Bizleri halkı zalim olan şu memleketten çıkar, katından bize bir dost ver, bize katından bir yardımcı ver\" diye yalvarıp duran zayıf ve zavallı erkekler, kadınlar ve çocukların uğrunda savaşa çıkmıyorsunuz?"},{"n":76,"t":"İman edenler, Allah yolunda savaşırlar. İnkâr edenler de tâğût yolunda savaşırlar. O hâlde, siz şeytanın dostlarına karşı savaşın. Şüphesiz şeytanın hilesi zayıftır."},{"n":77,"t":"Daha önce kendilerine, \"(savaşmaktan) ellerinizi çekin, namazı kılın, zekâtı verin\" denilenleri görmedin mi? Üzerlerine savaş yazılınca, hemen içlerinden bir kısmı; insanlardan, Allah’tan korkar gibi, hatta daha çok korkarlar ve \"Rabbimiz! Niçin bize savaş yazdın? Bizi yakın bir zamana kadar erteleseydin ya!\" derler. De ki: \"Dünya geçimliği azdır. Ahiret, Allah’a karşı gelmekten sakınan kimse için daha hayırlıdır. Size kıl kadar haksızlık edilmez.\""},{"n":78,"t":"Nerede olursanız olun, sağlam ve tahkim edilmiş kaleler içinde bulunsanız bile ölüm size ulaşacaktır. Onlara bir iyilik gelirse, \"Bu, Allah’tandır\" derler. Onlara bir kötülük gelirse, \"Bu, senin yüzündendir\" derler. (Ey Muhammed!) De ki: \"Hepsi Allah’tandır.\" Bu topluma ne oluyor ki, neredeyse hiçbir sözü anlamıyorlar!"},{"n":79,"t":"Sana ne iyilik gelirse Allah’tandır. Sana ne kötülük gelirse kendindendir. (Ey Muhammed!) Seni insanlara bir peygamber olarak gönderdik. Şahit olarak Allah yeter."},{"n":80,"t":"Kim peygambere itaat ederse, Allah’a itaat etmiş olur. Kim yüz çevirirse, (bilsin ki) biz seni onlara bekçi göndermedik."},{"n":81,"t":"Sana \"baş üstüne\" derler. Fakat senin yanından çıktıklarında, içlerinden birtakımı, geceleyin; (senin gündüz) söylediklerinin aksini kurarlar. Allah, onların geceleyin kurduklarını yazmaktadır. Sen onlara aldırma. Allah’a tevekkül et. Vekil olarak Allah yeter."},{"n":82,"t":"Hâlâ Kur’an’ı düşünüp anlamaya çalışmıyorlar mı? Eğer o, Allah’tan başkası tarafından (indirilmiş) olsaydı, mutlaka onda birçok çelişki bulurlardı."},{"n":83,"t":"Kendilerine güvenlik (barış) veya korku (savaş) ile ilgili bir haber geldiğinde onu yayarlar. Hâlbuki onu peygambere ve içlerinden yetki sahibi kimselere götürselerdi, elbette bunlardan, onu değerlendirip sonuç (hüküm) çıkarabilecek nitelikte olanları onu anlayıp bilirlerdi. Allah’ın size lütfu ve merhameti olmasaydı, pek azınız hariç, muhakkak şeytana uyardınız."},{"n":84,"t":"(Ey Muhammed!) Artık Allah yolunda savaş! Sen ancak kendinden sorumlusun! Mü’minleri de savaşa teşvik et. Umulur ki Allah inkâr edenlerin gücünü kırar. Allah’ın gücü daha üstündür, cezası daha şiddetlidir."},{"n":85,"t":"Kim güzel bir (işte) aracılık ederse, ona o işin sevabından bir pay vardır. Kim de kötü bir (işte) aracılık ederse, ona da o kötülükten bir pay vardır. Allah’ın her şeye gücü yeter."},{"n":86,"t":"Size bir selâm verildiği zaman, ondan daha güzeliyle veya aynı selâmla karşılık verin. Şüphesiz Allah, her şeyin hesabını gereği gibi yapandır."},{"n":87,"t":"Allah, kendisinden başka hiçbir ilâh olmayandır. Andolsun, sizi kıyamet gününde mutlaka bir araya toplayacaktır. Bunda asla şüphe yoktur. Kimdir sözü Allah’ınkinden daha doğru olan?"},{"n":88,"t":"Size ne oluyor da münafıklar hakkında iki gruba ayrıldınız? Allah, onları yaptıkları işlerden dolayı baş aşağı ederek eski konumlarına (küfre) döndürmüştür. Allah’ın saptırdığını yola getirmek mi istiyorsunuz? Allah kimi saptırırsa, sen onun için asla bir çıkış yolu bulamazsın."},{"n":89,"t":"Arzu ettiler ki kendilerinin küfre saptıkları gibi siz de sapasınız da beraber olasınız. Bu sebeple, onlar Allah yolunda hicret edinceye kadar içlerinden dost edinmeyin. Eğer bundan yüz çevirirlerse, onları yakalayın ve bulduğunuz yerde öldürün. Onlardan ne bir dost edinin, ne de bir yardımcı."},{"n":90,"t":"Ancak sizinle aralarında anlaşma olan bir topluma sığınmış bulunanlar, yahut ne sizinle ne de kendi kavimleriyle savaşmayı içlerine sığdıramayıp (tarafsız olarak) size gelenler başka. Eğer Allah dileseydi, onları size musallat kılardı da sizinle savaşırlardı. Eğer onlar sizden uzak durur, sizinle savaşmayıp size barış teklif ederlerse; Allah, onlara saldırmak için size bir yol (yetki) vermemiştir."},{"n":91,"t":"Diğer birtakım kimselerin de hem sizden emin olmak, hem de kavimlerinden emin olmak istediklerini göreceksin. Bunlar küfre her döndürüldüklerinde ona atılırlar. Eğer bunlar sizden uzak durmazlar, sizinle barış içinde yaşamak istemezler, ellerini savaştan çekmezlerse, onları yakalayın ve onları nerede bulursanız öldürün. İşte bunlara karşı size apaçık bir yetki verdik."},{"n":92,"t":"Bir mü’minin bir mü’mini öldürmesi olacak şey değildir. Ancak yanlışlıkla olması başka. Kim bir mü’mini yanlışlıkla öldürürse, bir mü’min köleyi azad etmesi ve bağışlamadıkları sürece ailesine diyet ödemesi gerekir. (Öldürülen kimse) mü’min olur ve düşmanınız olan bir topluluktan bulunursa, mü’min bir köle azad etmek gerekir. Eğer sizinle kendileri arasında antlaşma bulunan bir topluluktan ise ailesine verilecek bir diyet ve mü’min bir köle azad etmek gerekir. Bunlara imkân bulamayanın, Allah tarafından tövbesinin kabulü için iki ay ard arda oruç tutması gerekir. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":93,"t":"Kim bir mü’mini kasten öldürürse, cezası, içinde ebedî kalacağı cehennemdir. Allah, ona gazap etmiş, lânet etmiş ve onun için büyük bir azap hazırlamıştır."},{"n":94,"t":"Ey iman edenler! Allah yolunda sefere çıktığınız zaman, gerekli araştırmayı yapın. Size selâm veren kimseye, dünya hayatının geçici menfaatine (ganimete) göz dikerek, \"Sen mü’min değilsin\" demeyin. Allah katında pek çok ganimetler vardır. Daha önce siz de öyle idiniz de Allah size lütufta bulundu (müslüman oldunuz). Onun için iyice araştırın. Çünkü Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":"95-96","t":"Mü’minlerden özür sahibi olmaksızın (cihattan geri kalıp) oturanlarla, Allah yolunda mallarıyla, canlarıyla cihad edenler eşit olamazlar. Allah, mallarıyla, canlarıyla cihad edenleri, derece itibariyle, cihattan geri kalanlardan üstün kılmıştır. Gerçi Allah (mü’minlerin) hepsine de en güzel olanı (cenneti) va’detmiştir. Ama mücahitleri büyük bir mükâfat ile kendi katından dereceler, bağışlanma ve rahmet ile cihattan geri kalanlara üstün kılmıştır. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":97,"t":"Kendilerine zulmetmekteler iken meleklerin canlarını aldığı kimseler var ya; melekler onlara şöyle derler: \"Ne durumdaydınız? (Niçin hicret etmediniz?)\" Onlar da, \"Biz yeryüzünde zayıf ve güçsüz kimselerdik\" derler. Melekler, \"Allah’ın arzı geniş değil miydi, orada hicret etseydiniz ya!\" derler. İşte bunların gidecekleri yer cehennemdir. O ne kötü varış yeridir."},{"n":98,"t":"Ancak gerçekten zayıf ve güçsüz olan, çaresiz kalan ve hicret etmeye yol bulamayan erkekler, kadınlar ve çocuklar başkadır."},{"n":99,"t":"Umulur ki, Allah bu kimseleri affeder. Çünkü Allah çok affedicidir, çok bağışlayıcıdır."},{"n":100,"t":"Kim Allah yolunda hicret ederse, yeryüzünde gidecek çok yer de bulur, genişlik de. Kim Allah’a ve Peygamberine hicret etmek amacıyla evinden çıkar da sonra kendisine ölüm yetişirse, şüphesiz onun mükâfatı Allah’a düşer. Allah, çok bağışlayıcıdır, çok merhamet edicidir."},{"n":101,"t":"Yeryüzünde sefere çıktığınız vakit kâfirlerin size saldırmasından korkarsanız, namazı kısaltmanızdan ötürü size bir günah yoktur. Şüphesiz kâfirler sizin apaçık düşmanınızdır."},{"n":102,"t":"(Ey Muhammed!) Cephede sen de onların (mü’minlerin) arasında bulunup da onlara namaz kıldırdığın vakit, içlerinden bir kısmı seninle beraber namaza dursun. Silâhlarını da yanlarına alsınlar. Bunlar secdeye vardıklarında (bir rekât kıldıklarında) arkanıza (düşman karşısına) geçsinler. Sonra o namaz kılmamış olan diğer kısım gelsin, seninle beraber kılsınlar ve ihtiyatlı bulunsunlar, silâhlarını yanlarına alsınlar. İnkâr edenler arzu ederler ki, silâhlarınızdan ve eşyanızdan bir gafil olsanız da size ani bir baskın yapsalar. Yağmurdan zahmet çekerseniz, ya da hasta olursanız, silâhlarınızı bırakmanızda size bir beis yoktur. Bununla birlikte ihtiyatlı olun (tedbirinizi alın). Şüphesiz Allah, inkârcılara alçaltıcı bir azap hazırlamıştır."},{"n":103,"t":"Namazı kıldınız mı, gerek ayakta, gerek otururken ve gerek yan yatarak hep Allah’ı anın. Güvene kavuştunuz mu namazı tam olarak kılın. Çünkü namaz, mü’minlere belirli vakitlere bağlı olarak farz kılınmıştır."},{"n":104,"t":"Düşman topluluğunu izlemekte gevşeklik göstermeyin. Eğer siz acı duyuyorsanız, kuşkusuz onlar da sizin acı duyduğunuz gibi acı duyuyorlar. Üstelik siz Allah’tan onların ümit edemeyecekleri şeyleri umuyorsunuz. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":105,"t":"(Ey Muhammed!) Biz sana Kitab’ı (Kur’an’ı) hak olarak indirdik ki, insanlar arasında Allah’ın sana öğrettikleri ile hüküm veresin. Sakın hainlerin savunucusu olma."},{"n":106,"t":"Allah’tan bağışlama dile. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir."},{"n":107,"t":"Kendilerine hainlik edenleri savunma. Zira Allah, hiçbir haini, hiçbir günahkârı sevmez."},{"n":108,"t":"Bunlar, insanlardan gizlenmeye çalışırlar da Allah’tan gizlenmezler. Hâlbuki Allah, geceleyin, razı olmayacağı sözleri kurarlarken onlarla beraberdir. Allah, onların yaptıklarını (ilmiyle) kuşatmıştır."},{"n":109,"t":"İşte siz öyle kimselersiniz (ki, diyelim) dünya hayatında onları savundunuz. Ya kıyamet günü onları Allah’a karşı kim savunacak, yahut kim onlara vekil olacak?"},{"n":110,"t":"Kim bir kötülük yapar, yahut kendine zulmeder, sonra da Allah’tan bağışlama dilerse, Allah’ı çok bağışlayıcı ve çok merhamet edici bulur."},{"n":111,"t":"Kim bir günah kazanırsa, onu ancak kendi aleyhine kazanmış olur. Allah, her şeyi hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":112,"t":"Kim bir hata işler veya bir günah kazanır da sonra onu bir suçsuzun üzerine atarsa, şüphesiz iftira etmiş, apaçık bir günah yüklenmiş olur."},{"n":113,"t":"(Ey Muhammed!) Eğer Allah’ın sana lütuf ve merhameti olmasaydı, onlardan bir grup seni saptırmaya çalışırdı. Hâlbuki onlar, ancak kendilerini saptırırlar, sana hiçbir zarar veremezler. Allah, sana kitabı (Kur’an’ı) ve hikmeti indirmiş ve sana bilmediğin şeyleri öğretmiştir. Allah’ın sana lütfu çok büyüktür."},{"n":114,"t":"Bir sadaka vermeyi, yahut iyilik yapmayı, yahut da insanların arasını düzeltmeyi emredenleri hariç, onların aralarındaki gizli konuşmaların çoğunda hiçbir hayır yoktur. Kim bunları sırf Allah’ın rızasını kazanmak için yaparsa, biz ona büyük bir mükâfat vereceğiz."},{"n":115,"t":"Kim, kendisine hidayet (doğru yol) besbelli olduktan sonra peygambere karşı çıkar, mü’minlerin yolundan başkasına uyarsa, onu yöneldiği yolda bırakırız ve cehenneme sokarız. Orası ne kötü bir varış yeridir."},{"n":116,"t":"Şüphesiz Allah, kendisine ortak koşulmasını bağışlamaz. Bunun dışındaki günahları, dilediği kimseler için bağışlar. Allah’a ortak koşan, kuşkusuz, derin bir sapıklığa düşmüştür."},{"n":117,"t":"Onlar, Allah’ı bırakıp ancak dişilere tapıyorlar. Hâlbuki (aslında) azgın bir şeytana tapmaktadırlar."},{"n":118,"t":"Allah, o şeytana lânet etti ve o da, \"Andolsun ki senin kullarından elbette belirli bir pay alacağım\" dedi."},{"n":119,"t":"\"Onları mutlaka saptıracağım, mutlaka onları kuruntulara sokacağım ve onlara emredeceğim de (putlara adak için) hayvanların kulaklarını yaracaklar. Yine onlara emredeceğim de Allah’ın yarattığını değiştirecekler.\" Kim Allah’ı bırakıp da şeytanı dost edinirse, şüphesiz o apaçık bir hüsrana düşmüştür."},{"n":120,"t":"Şeytan onlara (birçok) vaadde bulunur ve onları kuruntulara sürükler. Oysa şeytan, ancak aldatmak için onlara vaadde bulunuyor."},{"n":121,"t":"İşte onların barınağı cehennemdir. Ondan bir kaçış yolu bulamazlar."},{"n":122,"t":"İman edip salih ameller işleyenleri de ebedî olarak kalacakları, içlerinden ırmaklar akan cennetlere koyacağız. Allah, gerçek bir vaadde bulunmuştur. Kimdir sözü Allah’ınkinden daha doğru olan?"},{"n":123,"t":"İş, ne sizin kuruntunuza, ne de kitap ehlinin kuruntusuna göredir. Kim kötü bir iş yaparsa, onunla cezalandırılır. O, kendisine Allah’tan başka ne bir dost, ne de bir yardımcı bulabilir."},{"n":124,"t":"Mü’min olarak, erkek veya kadın, her kim salih ameller işlerse, işte onlar cennete girerler ve zerre kadar haksızlığa uğratılmazlar."},{"n":125,"t":"Kimin dini, iyilik yaparak kendini Allah’a teslim eden ve hakka yönelen İbrahim’in dinine tabi olan kimsenin dininden daha güzeldir? Allah, İbrahim’i dost edindi."},{"n":126,"t":"Göklerdeki her şey, yerdeki her şey Allah’ındır. Allah, her şeyi kuşatıcıdır."},{"n":127,"t":"Kadınlar hakkında senden fetva istiyorlar. De ki: \"Onlar hakkında size fetvayı Allah veriyor.\" Kitapta, kendilerine (verilmesi) farz kılınan (miras)ı vermediğiniz ve evlenmek istediğiniz yetim kızlara, zavallı çocuklara ve yetimlere âdil davranmanıza dair, size okunmakta olan âyetler de bunu açıklıyor. Ne hayır yaparsanız, şüphesiz Allah onu bilir."},{"n":128,"t":"Eğer bir kadın kocasının, kendisine kötü davranmasından, yahut yüz çevirmesinden endişe ederse, uzlaşarak aralarını düzeltmelerinde ikisine de bir günah yoktur. Uzlaşmak daha hayırlıdır. Nefisler ise kıskançlığa ve bencil tutkulara hazır (elverişli) kılınmıştır. Eğer iyilik eder ve Allah’a karşı gelmekten sakınırsanız, şüphesiz Allah, yaptıklarınızdan haberdardır."},{"n":129,"t":"Ne kadar uğraşırsanız uğraşın, kadınlar arasında adaleti yerine getiremezsiniz. Öyle ise (birine) büsbütün gönül verip ötekini (kocası hem var, hem yok) askıda kalmış kadın gibi bırakmayın. Eğer arayı düzeltir ve Allah’a karşı gelmekten sakınırsanız, şüphesiz Allah çok bağışlayıcı ve çok merhamet edicidir."},{"n":130,"t":"Eğer ayrılırlarsa, Allah bol lütuf ve nimetiyle onların her birini zengin kılar (başkalarına muhtaç bırakmaz). Allah, lütfu geniş olandır. O, hüküm ve hikmet sahibidir."},{"n":131,"t":"Göklerdeki her şey, yerdeki her şey Allah’ındır. Sizden önce kendilerine kitap verilenlere de, size de \"Allah’a karşı gelmekten sakının\" diye tavsiye ettik. Eğer inkâr ederseniz, (bilin ki) göklerdeki her şey, yerdeki her şey Allah’ındır. Allah, zengindir, övülmeye lâyıktır."},{"n":132,"t":"Göklerdeki her şey, yerdeki her şey Allah’ındır. Vekil olarak Allah yeter."},{"n":133,"t":"Ey insanlar! Allah dilerse sizi yok eder ve başkalarını getirir. Allah, buna hakkıyla gücü yetendir."},{"n":134,"t":"Kim dünya sevabı (nimeti) istiyorsa (bilsin ki), dünya sevabı da, ahiret sevabı da Allah katındadır. Allah, hakkıyla işitendir, hakkıyla görendir."},{"n":135,"t":"Ey iman edenler! Kendiniz, ana babanız ve en yakınlarınızın aleyhine de olsa, Allah için şahitlik yaparak adaleti titizlikle ayakta tutan kimseler olun. (Şahitlik ettikleriniz) zengin veya fakir de olsalar (adaletten ayrılmayın). Çünkü Allah ikisine de daha yakındır. (Onları sizden çok kayırır.) Öyle ise adaleti yerine getirmede nefsinize uymayın. Eğer (şahitlik ederken gerçeği) çarpıtırsanız veya (şahitlikten) çekinirseniz (bilin ki) şüphesiz Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":136,"t":"Ey iman edenler! Allah’a, Peygamberine, Peygamberine indirdiği kitaba ve daha önce indirdiği kitaba iman edin. Kim Allah’ı, meleklerini, kitaplarını, peygamberlerini ve ahiret gününü inkâr ederse, derin bir sapıklığa düşmüş olur."},{"n":137,"t":"İman edip sonra inkâr eden, sonra inanıp tekrar inkâr eden, sonra da inkârlarında ileri gidenler var ya; Allah, onları bağışlayacak da değildir, doğru yola iletecek de değildir."},{"n":138,"t":"Münafıklara, kendileri için elem dolu bir azap olduğunu müjdele."},{"n":139,"t":"Onlar, mü’minleri bırakıp kâfirleri dost edinen kimselerdir. Onların yanında izzet ve şeref mi arıyorlar? Hâlbuki bütün izzet ve şeref Allah’a aittir."},{"n":140,"t":"Oysa Allah size Kitap’ta (Kur’an’da) \"Allah’ın âyetlerinin inkâr edildiğini ve onlarla alay edildiğini işittiğiniz zaman, başka bir söze geçmedikleri müddetçe, onlarla oturmayın, aksi hâlde siz de onlar gibi olursunuz\" diye hüküm indirmiştir. Şüphesiz Allah, münafıkların ve kâfirlerin hepsini cehennemde toplayacaktır."},{"n":141,"t":"Onlar sizi gözetleyip duran kimselerdir. Eğer Allah tarafından size bir fetih (zafer) nasip olursa, \"Biz sizinle beraber değil miydik?\" derler. Şayet kâfirlerin (zaferden) bir payı olursa, \"Size üstünlük sağlayıp sizi mü’minlerden korumadık mı?\" derler. Allah, kıyamet günü aranızda hükmünü verecektir. Allah, mü’minlerin aleyhine kâfirlere hiçbir yol vermeyecektir."},{"n":142,"t":"Münafıklar, Allah’ı aldatmaya çalışırlar. Allah da onların bu çabalarını başlarına geçirir. Onlar, namaza kalktıkları zaman tembel tembel kalkarlar, insanlara gösteriş yaparlar ve Allah’ı pek az anarlar."},{"n":143,"t":"Onlar küfür ile iman arasında bocalayıp dururlar. Ne bunlara (mü’minlere) ne de şunlara (kâfirlere) bağlanırlar. Allah, kimi saptırırsa ona asla bir çıkar yol bulamazsın."},{"n":144,"t":"Ey iman edenler! Mü’minleri bırakıp da kâfirleri dost edinmeyin. Kendi aleyhinize Allah’a apaçık bir delil mi vermek istiyorsunuz?"},{"n":145,"t":"Şüphesiz ki münafıklar, cehennem ateşinin en aşağı tabakasındadırlar. Onlara hiçbir yardımcı da bulamazsın."},{"n":146,"t":"Ancak tövbe edenler, durumlarını düzeltenler, Allah’ın kitabına sarılanlar ve dinlerini Allah’a has kılanlar müstesnadır. Bunlar mü’minlerle beraberdirler. Allah, mü’minlere büyük bir mükâfat verecektir."},{"n":147,"t":"Eğer şükreder ve iman ederseniz, Allah size niye azab etsin ki? Allah, şükrün karşılığını verendir, hakkıyla bilendir."},{"n":148,"t":"Allah, zulme uğrayanın dile getirmesi dışında, çirkin sözün açıklanmasını sevmez. Şüphesiz Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":149,"t":"Bir hayrı açıklar veya gizlerseniz, yahut bir kötülüğü affederseniz (bilin ki), Allah da çok affedicidir, her şeye hakkıyla gücü yetendir."},{"n":"150-151","t":"Şüphesiz, Allah’ı ve peygamberlerini inkâr edenler, Allah’a inanıp peygamberlerine inanmayarak ayrım yapmak isteyenler, \"(Peygamberlerin) kimine inanırız, kimini inkâr ederiz\" diyenler ve böylece bu ikisinin (imanla küfrün) arasında bir yol tutmak isteyenler var ya; işte onlar gerçekten kâfirlerdir. Biz de kâfirlere alçaltıcı bir azap hazırlamışızdır."},{"n":152,"t":"Allah’a ve peygamberlerine iman edenler ve onlardan hiçbirini diğerlerinden ayırmayanlara gelince, işte onlara Allah mükâfatlarını verecektir. Allah, çok bağışlayıcıdır, çok merhamet edicidir."},{"n":153,"t":"Kitap ehli, senden kendilerine gökten bir kitap indirmeni istiyorlar. (Buna şaşma!) Mûsâ’dan, bundan daha büyüğünü istemişler ve \"Allah’ı bize açıkça göster\" demişlerdi. Böylece zulümleri sebebiyle onları yıldırım çarptı. Sonra kendilerine apaçık deliller gelmesinin ardından (tuttular) buzağıyı tanrı edindiler. Biz bunu da affettik ve Mûsâ’ya apaçık bir güç ve yetki verdik."},{"n":154,"t":"Verdikleri sağlam söz(ü yerine getirmemeleri) sebebiyle \"Tûr\"u üzerlerine kaldırdık ve onlara, \"Tevazu ile kapıdan girin\" dedik. Yine onlara, \"Cumartesi (yasakları) konusunda haddi aşmayın\" dedik ve onlardan sağlam bir söz aldık."},{"n":155,"t":"Verdikleri sağlam sözü bozmalarından, Allah’ın âyetlerini inkâr etmelerinden, peygamberleri haksız yere öldürmelerinden ve \"kalplerimiz muhafazalıdır\" demelerinden dolayı (başlarına türlü belâlar verdik. Onların kalpleri muhafazalı değildir), tam aksine inkârları sebebiyle Allah onların kalplerini mühürlemiştir. Artık onlar inanmazlar."},{"n":"156-157","t":"Bir de inkârlarından ve Meryem’e büyük bir iftira atmalarından ve \"Biz Allah’ın peygamberi Meryem oğlu İsa Mesih’i öldürdük\" demelerinden dolayı kalplerini mühürledik. Oysa onu öldürmediler ve asmadılar. Fakat onlara öyle gibi gösterildi. Onun hakkında anlaşmazlığa düşenler, bu konuda kesin bir şüphe içindedirler. O hususta hiçbir bilgileri yoktur. Sadece zanna uyuyorlar. Onu kesin olarak öldürmediler."},{"n":158,"t":"Fakat Allah onu kendisine yükseltmiştir. Allah, üstün ve güçlüdür, hüküm ve hikmet sahibidir."},{"n":159,"t":"Kitab ehlinden hiç kimse yoktur ki ölümünden önce, ona (İsa’ya) iman edecek olmasın. Kıyamet günü, o (İsa) onların aleyhine şahit olacaktır."},{"n":"160-161","t":"Yahudilerin yaptıkları zulüm ve birçok kimseyi Allah yolundan alıkoymaları, kendilerine yasaklanmış olduğu hâlde faiz almaları, insanların mallarını haksız yere yemeleri sebebiyle önceden kendilerine helâl kılınmış temiz ve hoş şeyleri onlara haram kıldık. İçlerinden inkâr edenlere de acı bir azap hazırladık."},{"n":162,"t":"Fakat onlardan ilimde derinleşmiş olanlar ve mü’minler, sana indirilene ve senden önce indirilene iman ederler. O namazı kılanlar, zekâtı verenler, Allah’a ve ahiret gününe inananlar var ya, işte onlara büyük bir mükâfat vereceğiz."},{"n":163,"t":"Biz, Nûh’a ve ondan sonra gelen peygamberlere vahyettiğimiz gibi, sana da vahyettik. İbrahim’e, İsmail’e, İshak’a, Yakub’a, torunlarına, İsa’ya, Eyyüb’e, Yûnus’a, Hârûn’a ve Süleyman’a da vahyetmiştik. Davûd’a da Zebûr vermiştik."},{"n":164,"t":"Daha önce kıssalarını sana anlattığımız peygamberler gönderdik. Anlatmadığımız (nice) peygamberler de gönderdik. Allah, Mûsa ile de doğrudan konuştu."},{"n":165,"t":"Müjdeleyiciler ve uyarıcılar olarak peygamberler gönderdik ki, peygamberlerden sonra insanların Allah’a karşı bir bahaneleri olmasın. Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":166,"t":"Fakat Allah, sana indirdiğini kendi ilmiyle indirmiş olduğuna şahitlik eder. Melekler de buna şahitlik eder. Şahit olarak Allah yeter."},{"n":167,"t":"Şüphesiz inkâr edenler, insanları Allah yolundan alıkoyanlar derin bir sapıklığa düşmüşlerdir."},{"n":168,"t":"Şüphesiz inkâr edenler ve zulmedenler (var ya), Allah onları asla bağışlayacak ve doğru yola iletecek değildir."},{"n":169,"t":"(Allah onları) ancak içinde ebedî kalacakları cehennemin yoluna iletir. Bu ise Allah’a çok kolaydır."},{"n":170,"t":"Ey insanlar! Peygamber size Rabbinizden hakkı (gerçeği) getirdi. O hâlde, kendi iyiliğiniz için iman edin. Eğer inkâr ederseniz bilin ki, göklerdeki her şey, yerdeki her şey Allah’ındır. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":171,"t":"Ey Kitab ehli! Dininizde sınırları aşmayın ve Allah hakkında ancak hakkı söyleyin. Meryem oğlu İsa Mesih, ancak Allah’ın peygamberi, Meryem’e ulaştırdığı (emriyle onda var ettiği) kelimesi ve kendisinden bir ruhtur. Öyleyse Allah’a ve peygamberlerine iman edin, \"(Allah) üçtür\" demeyin. Kendi iyiliğiniz için buna son verin. Allah, ancak bir tek ilâhtır. O, çocuk sahibi olmaktan uzaktır. Göklerdeki her şey, yerdeki her şey O’nundur. Vekil olarak Allah yeter."},{"n":172,"t":"Mesih de, Allah’a yakın melekler de, Allah’a kul olmaktan asla çekinmezler. Kim Allah’a kulluk etmekten çekinir ve büyüklük taslarsa, bilsin ki, O, onların hepsini huzuruna toplayacaktır."},{"n":173,"t":"İman edip salih ameller işleyenlere gelince, (Allah) onların mükâfatlarını eksiksiz ödeyecek ve lütfundan onlara daha da fazlasını verecektir. Allah’a kulluk etmekten çekinenlere ve büyüklük taslayanlara gelince; (Allah) onları elem dolu bir azaba uğratacaktır ve onlar kendilerine Allah’tan başka bir dost ve yardımcı da bulamayacaklardır."},{"n":174,"t":"Ey insanlar! Size Rabbinizden kesin bir delil (Hz. Muhammed) geldi ve size apaçık bir nur (Kur’an) indirdik."},{"n":175,"t":"Allah’a iman edip ona sımsıkı sarılanları ise (Allah), kendisinden bir rahmet ve lütfa kavuşturacak ve onları kendisine varan doğru bir yola iletecektir."},{"n":176,"t":"Senden fetva istiyorlar. De ki: \"Allah, size \"kelâle\" (babasız ve çocuksuz kimse)nin mirası hakkında hükmünü açıklıyor: Çocuğu olmayan bir kişi ölür de kız kardeşi bulunursa, bıraktığı malın yarısı onundur. Eğer kız kardeşi ölür ve çocuğu da bulunmazsa, erkek kardeş ona varis olur. Eğer kız kardeşler iki iseler, (erkek kardeşin) bıraktığının üçte ikisi onlarındır. Eğer kardeşler erkekli kızlı iseler, o zaman (bir) erkeğe, iki kızın hissesi kadar (pay) vardır. Sapmayasınız diye Allah size (hükmünü) açıklıyor. Allah, her şeyi hakkıyla bilendir."}],[{"n":1,"t":"Ey iman edenler! Akitlerinizi yerine getirin. İhramlı iken avlanmayı helâl saymamanız kaydıyla, okunacak (bildirilecek) olanlardan başka hayvanlar, size helâl kılındı. Şüphesiz Allah istediği hükmü verir."},{"n":2,"t":"Ey iman edenler! Allah’ın (koyduğu din) nişanelerine, haram aya, hac kurbanına, (bu kurbanlıklara takılı) gerdanlıklara ve de Rab’lerinden bol nimet ve hoşnutluk isteyerek Kâ’be’ye gelenlere sakın saygısızlık etmeyin. İhramdan çıktığınızda (isterseniz) avlanın. Sizi Mescid-i Haram’dan alıkoydular diye birtakımlarına beslediğiniz kin, sakın ha sizi, haddi aşmaya sürüklemesin. İyilik ve takva (Allah’a karşı gelmekten sakınma) üzere yardımlaşın. Ama günah ve düşmanlık üzere yardımlaşmayın. Allah’a karşı gelmekten sakının. Çünkü Allah’ın cezası çok şiddetlidir."},{"n":3,"t":"Ölmüş hayvan, kan, domuz eti, Allah’tan başkası adına boğazlanan, (henüz canı çıkmamış iken) kestikleriniz hariç; boğulmuş, darbe sonucu ölmüş, yüksekten düşerek ölmüş, boynuzlanarak ölmüş ve yırtıcı hayvan tarafından parçalanmış hayvanlar ile dikili taşlar üzerinde boğazlanan hayvanlar, bir de fal oklarıyla kısmet aramanız size haram kılındı. İşte bütün bunlar fısk (Allah’a itaatten kopmak)tır. Bugün kâfirler dininizden (onu yok etmekten) ümitlerini kestiler. Artık onlardan korkmayın, benden korkun. Bugün sizin için dininizi kemale erdirdim. Size nimetimi tamamladım ve sizin için din olarak İslâm’ı seçtim. Kim şiddetli açlık durumunda zorda kalır, günaha meyletmeksizin (haram etlerden) yerse, şüphesiz ki Allah çok bağışlayıcıdır, çok merhamet edicidir."},{"n":4,"t":"(Ey Muhammed!) Sana, kendilerine nelerin helâl kılındığını soruyorlar. De ki: \"Size temiz ve hoş olan şeyler, bir de Allah’ın size verdiği yeteneklerle eğitip alıştırdığınız avcı hayvanların tuttuğu (avlar) helâl kılındı. Onların sizin için tuttuklarından yiyin. Onu (av için) salarken üzerine Allah’ın adını anın (besmele çekin). Allah’a karşı gelmekten sakının. Şüphesiz Allah, hesabı çabuk görendir."},{"n":5,"t":"Bu gün size temiz ve hoş şeyler helâl kılındı. Kendilerine kitap verilenlerin yiyecekleri size helâl, sizin yiyecekleriniz de onlara helâldir. Mü’min kadınlardan iffetli olanlarla, daha önce kendilerine kitap verilenlerden olan iffetli kadınlar da, mehirlerini vermeniz kaydıyla; evlenmek, zina etmemek ve gizli dost tutmamak üzere size helâldir. Her kim de inanılması gerekenleri inkâr ederse, bütün işlediği boşa gider. Ahirette de o, ziyana uğrayanlardandır."},{"n":6,"t":"Ey iman edenler! Namaza kalkacağınız zaman yüzlerinizi, dirseklere kadar ellerinizi ve -başlarınıza mesh edip- her iki topuğa kadar da ayaklarınızı yıkayın. Eğer cünüp iseniz, iyice yıkanarak temizlenin. Hasta olursanız veya seferde bulunursanız veya biriniz abdest bozmaktan (def-i hacetten) gelir veya kadınlara dokunur (cinsel ilişkide bulunur) da su bulamazsanız, o zaman temiz bir toprağa yönelin. Onunla yüzlerinizi ve ellerinizi meshedin (Teyemmüm edin). Allah, size herhangi bir güçlük çıkarmak istemez. Fakat O, sizi tertemiz yapmak ve üzerinizdeki nimetini tamamlamak ister ki şükredesiniz."},{"n":7,"t":"Allah’ın üzerinizdeki nimetini ve \"işittik, itaat ettik\" dediğinizde ona verdiğiniz ve sizi kendisiyle bağladığı sağlam sözü hatırlayın. Allah’a karşı gelmekten sakının. Şüphesiz Allah, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir."},{"n":8,"t":"Ey iman edenler! Allah için hakkı titizlikle ayakta tutan, adalet ile şahitlik eden kimseler olun. Bir topluma olan kininiz, sakın ha sizi adaletsizliğe itmesin. Âdil olun. Bu, Allah’a karşı gelmekten sakınmaya daha yakındır. Allah’a karşı gelmekten sakının. Şüphesiz Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":9,"t":"Allah, iman edip salih ameller işleyenler hakkında, \"Onlar için bir bağışlama ve büyük bir mükâfat vardır\" diye vaatte bulunmuştur."},{"n":10,"t":"İnkâr edip âyetlerimizi yalanlayanlar var ya; işte onlar cehennemliklerdir."},{"n":11,"t":"Ey iman edenler! Allah’ın size olan nimetini hatırlayın. Hani bir topluluk size el uzatmaya (tecavüze) kalkışmıştı da, Allah (buna engel olmuş) onların ellerini sizden çekmişti. Allah’a karşı gelmekten sakının. Mü’minler yalnız Allah’a tevekkül etsinler."},{"n":12,"t":"Andolsun, Allah İsrailoğullarından sağlam söz almıştı. Onlardan on iki temsilci -başkan- seçmiştik. Allah, şöyle demişti: \"Sizinle beraberim. Andolsun eğer namazı kılar, zekâtı verir ve elçilerime inanır, onları desteklerseniz, (fakirlere gönülden yardımda bulunarak) Allah’a güzel bir borç verirseniz, elbette sizin kötülüklerinizi örterim ve andolsun sizi, içinden ırmaklar akan cennetlere koyarım. Ama bundan sonra sizden kim inkâr ederse, mutlaka o, dümdüz yoldan sapmıştır.\""},{"n":13,"t":"İşte, verdikleri sözlerini bozmaları sebebiyledir ki onları lânetledik, kalplerini de kaskatı kıldık. Kelimeleri yerlerinden kaydırarak (tahrif edip) değiştiriyorlar. Akıllarından çıkarmamaları istenen şeylerden önemli bir kısmını da unuttular. (Ey Muhammed!) İçlerinden pek azı hariç, onların daima bir hainliğini görüyorsun. Yine de sen onları affet ve aldırış etme. Çünkü Allah, iyilik yapanları sever."},{"n":14,"t":"\"Biz hıristiyanız\" diyenlerden de sağlam söz almıştık. Ama onlar da akıllarından çıkarmamaları istenen şeylerden önemli bir kısmını unuttular. Bu sebeple, biz de aralarına kıyamet gününe kadar sürecek düşmanlık ve kini salıverdik. Allah, ne yapmakta olduklarını onlara bildirecek!"},{"n":15,"t":"Ey kitap ehli! Artık size elçimiz (Muhammed) gelmiştir. O, kitabınızdan gizleyip durduğunuz gerçeklerden birçoğunu sizlere açıklıyor, birçoğunu da affediyor. İşte size Allah’tan bir nur ve apaçık bir kitap (Kur’an) gelmiştir."},{"n":16,"t":"Allah, onunla rızası peşinde olanları selâmet yollarına iletir ve onları izniyle, karanlıklardan aydınlığa çıkarıp kendilerini dosdoğru bir yola iletir."},{"n":17,"t":"Andolsun, \"Allah, Meryem oğlu Mesih’tir\", diyenler kesinlikle kâfir oldular. De ki: \"Şâyet Allah, Meryem oğlu Mesih’i, onun anasını ve yeryüzünde olanların hepsini yok etmek istese, Allah’a karşı kim ne yapabilir? Göklerin, yerin ve bunların arasında bulunan her şeyin hükümranlığı Allah’ındır. Dilediğini yaratır. Allah, her şeye hakkıyla gücü yetendir.\""},{"n":18,"t":"(Bir de) yahudiler ve hıristiyanlar, \"Biz Allah’ın oğulları ve sevgili kullarıyız\" dediler. De ki: \"Öyleyse (Allah) size neden günahlarınız sebebiyle azap ediyor? Hayır, siz de O’nun yarattıklarından bir beşersiniz.\" (Allah) dilediğini bağışlar, dilediğine azap eder. Göklerin, yerin ve bunların arasında bulunanların da hükümranlığı Allah’ındır. Dönüş de ancak O’nadır."},{"n":19,"t":"Ey kitap ehli! Peygamberlerin arası kesildiği bir sırada, \"Bize ne müjdeleyici bir peygamber geldi, ne de bir uyarıcı\" demeyesiniz diye, işte size (hakikatı) açıklayan elçimiz (Muhammed) geldi. (Evet,) size bir müjdeleyici ve uyarıcı gelmiştir. Allah, her şeye hakkıyla gücü yetendir."},{"n":20,"t":"Hani Mûsâ, kavmine demişti ki: \"Ey kavmim! Allah’ın, üzerinizdeki nimetini hatırlayın. Hani içinizden peygamberler çıkarmıştı. Sizi hükümdarlar kılmıştı ve (diğer) toplumlardan hiçbirine vermediğini size vermişti.\""},{"n":21,"t":"\"Ey kavmim! Allah’ın size yazdığı kutsal toprağa girin. Sakın ardınıza dönmeyin. Yoksa ziyana uğrayanlar olursunuz.\""},{"n":22,"t":"Dediler ki: \"Ey Mûsâ! O (dediğin) topraklarda gayet güçlü, zorba bir millet var. Onlar oradan çıkmadıkça, biz oraya asla giremeyiz. Eğer oradan çıkarlarsa, biz de gireriz.\""},{"n":23,"t":"Korkanların içinden Allah’ın kendilerine nimet verdiği iki adam şöyle demişti: \"Onların üzerine kapıdan girin. Oraya girdiniz mi artık siz kuşkusuz galiplersiniz. Eğer mü’minler iseniz, yalnızca Allah’a tevekkül edin.\""},{"n":24,"t":"Dediler ki: \"Ey Mûsa! Onlar orada bulundukça, biz oraya asla girmeyeceğiz. Sen ve Rabbin gidin, onlarla savaşın. Biz burada oturacağız.\""},{"n":25,"t":"Mûsa, \"Ey Rabbim! Ben ancak kendime ve kardeşime söz geçirebilirim. Artık bizimle, o yoldan çıkmışların arasını ayır\" dedi."},{"n":26,"t":"Allah, şöyle dedi: \"O hâlde, orası onlara kırk yıl haram kılınmıştır. Bu süre içinde yeryüzünde şaşkın şaşkın dönüp dolaşacaklar. Artık böyle yoldan çıkmış kavme üzülme.\""},{"n":27,"t":"(Ey Muhammed!) Onlara, Âdem’in iki oğlunun haberini gerçek olarak oku. Hani ikisi de birer kurban sunmuşlardı da, birinden kabul edilmiş, ötekinden kabul edilmemişti. Kurbanı kabul edilmeyen, \"Andolsun seni mutlaka öldüreceğim\" demişti. Öteki, \"Allah, ancak kendisine karşı gelmekten sakınanlardan kabul eder\" demişti."},{"n":28,"t":"\"Andolsun! Sen beni öldürmek için elini bana uzatsan da ben seni öldürmek için sana elimi uzatacak değilim. Çünkü ben âlemlerin Rabbi olan Allah’tan korkarım.\""},{"n":29,"t":"\"Ben istiyorum ki, sen benim günahımı da, kendi günahını da yüklenip cehennemliklerden olasın. İşte bu zalimlerin cezasıdır.\""},{"n":30,"t":"Derken nefsi onu kardeşini öldürmeye itti de (nefsine uyarak) onu öldürdü ve böylece ziyan edenlerden oldu."},{"n":31,"t":"Nihayet Allah, ona kardeşinin ölmüş cesedini nasıl örtüp gizleyeceğini göstermek için yeri eşeleyen bir karga gönderdi. \"Yazıklar olsun bana! Şu karga kadar olup da kardeşimin cesedini örtmekten âciz miyim ben?\" dedi. Artık pişmanlık duyanlardan olmuştu."},{"n":32,"t":"Bundan dolayı İsrailoğullarına (Kitap’ta) şunu yazdık: \"Kim, bir insanı, bir can karşılığı veya yeryüzünde bir bozgunculuk çıkarmak karşılığı olmaksızın öldürürse, o sanki bütün insanları öldürmüştür. Her kim de birini (hayatını kurtararak) yaşatırsa, sanki bütün insanları yaşatmıştır. Andolsun ki, onlara resûllerimiz apaçık deliller (mucize ve âyetler) getirdiler. Ama onlardan birçoğu bundan sonra da (hâlâ) yeryüzünde aşırı gitmektedir."},{"n":33,"t":"Allah’a ve Resûlüne savaş açanların ve yeryüzünde bozgunculuk çıkarmaya çalışanların cezası; ancak öldürülmeleri, yahut asılmaları veya ellerinin ve ayaklarının çaprazlama kesilmesi, yahut o yerden sürülmeleridir. Bu cezalar onlar için dünyadaki bir rezilliktir. Ahirette de onlara büyük bir azap vardır."},{"n":34,"t":"Ancak onları ele geçirmenizden önce tövbe edenler bunun dışındadırlar. Artık Allah’ın çok bağışlayıcı, çok merhamet edici olduğunu bilin."},{"n":35,"t":"Ey iman edenler! Allah’a karşı gelmekten sakının, O’na yaklaşmaya vesile arayın ve O’nun yolunda cihad edin ki kurtuluşa eresiniz."},{"n":36,"t":"Şüphesiz yeryüzünde olanların hepsi ve yanında bir o kadarı daha kendilerinin (kâfirlerin) olsa da onu kıyamet gününün azabından kurtulmak için fidye verecek olsalar, onlardan yine kabul edilmez. Onlara elem dolu bir azap vardır."},{"n":37,"t":"Ateşten çıkmak isterler ama ondan çıkabilecek değillerdir. Onlara sürekli bir azap vardır."},{"n":38,"t":"Yaptıklarına bir karşılık ve Allah’tan caydırıcı bir müeyyide olmak üzere hırsız erkek ile hırsız kadının ellerini kesin. Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":39,"t":"Her kim de işlediği zulmünün arkasından tövbe edip durumunu düzeltirse kuşkusuz, Allah onun tövbesini kabul eder. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir."},{"n":40,"t":"Bilmez misin ki, göklerin ve yerin hükümranlığı Allah’a aittir. O, dilediğine azap eder, dilediğini de bağışlar. Allah, her şeye hakkıyla gücü yetendir."},{"n":41,"t":"Ey Peygamber! Kalpten inanmadıkları hâlde, ağızlarıyla \"İnandık\" diyenler (münafıklar) ile Yahudilerden küfürde yarışanlar seni üzmesin. Onlar (Yahudiler) yalan uydurmak için (seni) dinlerler, sana gelmeyen bir topluluk hesabına dinlerler. Kelimelerin (ifade içindeki) yerlerini bildikten sonra yerlerini değiştirir ve şöyle derler: \"Eğer size şu hüküm verilirse, onu tutun. O verilmezse sakının.\" Allah, kimin azaba uğramasını istemişse artık sen onun için asla Allah’a karşı hiçbir şey yapamazsın. Onlar, Allah’ın kalplerini temizlemeyi istemediği kimselerdir. Onlara dünyada bir rüsvaylık, ahirette ise yine onlara büyük bir azap vardır."},{"n":42,"t":"Onlar, yalanı çok dinleyen, haramı çok yiyenlerdir. Eğer sana gelirlerse, ister aralarında hüküm ver, ister onlardan yüz çevir. Onlardan yüz çevirecek olursan, sana asla hiçbir zarar veremezler. Eğer hükmedecek olursan, aralarında adaletle hükmet. Çünkü Allah, âdil davrananları sever."},{"n":43,"t":"Yanlarında, içinde Allah’ın hükmü bulunan Tevrat varken nasıl oluyor da seni hakem yapıyorlar, sonra bunun ardından verdiğin hükümden yüz çeviriyorlar? İşte onlar (kendi kitaplarına da, sana da) inanmış değillerdir."},{"n":44,"t":"Şüphesiz Tevrat’ı biz indirdik. İçinde bir hidayet, bir nur vardır. (Allah’a) teslim olmuş nebiler, onunla yahudilere hüküm verirlerdi. Kendilerini Rabb’e adamış kimseler ile âlimler de öylece hükmederlerdi. Çünkü bunlar Allah’ın kitabını korumakla görevlendirilmişlerdi. Onlar Tevrat’ın hak olduğuna da şahit idiler. Şu hâlde, siz de insanlardan korkmayın, benden korkun ve âyetlerimi az bir karşılığa değişmeyin. Allah’ın indirdiği ile hükmetmeyenler kâfirlerin ta kendileridir."},{"n":45,"t":"Onda (Tevrat’ta) üzerlerine şunu da yazdık: Cana can, göze göz, buruna burun, kulağa kulak, dişe diş kısas edilir. Yaralar da kısasa tabidir. Kim de bu hakkını bağışlar, sadakasına sayarsa o, kendisi için keffaret olur. Allah’ın indirdiği ile hükmetmeyenler, zalimlerin ta kendileridir."},{"n":46,"t":"O peygamberlerin izleri üzere Meryem oğlu İsa’yı, önündeki Tevrat’ı doğrulayıcı olarak gönderdik. Ona, içerisinde hidayet ve nur bulunan, önündeki Tevrat’ı doğrulayan, Allah’a karşı gelmekten sakınanlar için doğru yola iletici ve bir öğüt olarak İncil’i verdik."},{"n":47,"t":"İncil ehli Allah’ın onda indirdiği ile hükmetsin. Allah’ın indirdiği ile hükmetmeyenler, fasıkların ta kendileridir."},{"n":48,"t":"(Ey Muhammed!) Sana da o Kitab’ı (Kur’an’ı) hak, önündeki kitapları doğrulayıcı, onları gözetici olarak indirdik. Artık, Allah’ın indirdiği ile aralarında hükmet ve sana gelen haktan ayrılıp da onların arzularına uyma. Sizden her biriniz için bir şeriat ve bir yol koyduk. Eğer Allah dileseydi, elbette sizi tek bir ümmet yapardı. Fakat verdiği şeylerde sizi imtihan etmek için ümmetlere ayırdı. Öyle ise iyiliklerde yarışın. Hepinizin dönüşü Allah’adır. O zaman anlaşmazlığa düşmüş olduğunuz şeyleri size bildirecektir."},{"n":49,"t":"Aralarında, Allah’ın indirdiği ile hükmet. Onların arzularına uyma ve Allah’ın sana indirdiğinin bir kısmından (Kur’an’ın bazı hükümlerinden) seni şaşırtmalarından sakın. Eğer yüz çevirirlerse, bil ki şüphesiz Allah, bazı günahları sebebiyle onları bir musibete çarptırmak istiyor. İnsanlardan birçoğu muhakkak ki yoldan çıkmışlardır."},{"n":50,"t":"Onlar hâlâ cahiliye devrinin hükmünü mü istiyorlar? Kesin olarak inanacak bir toplum için, kimin hükmü Allah’ınkinden daha güzeldir?"},{"n":51,"t":"Ey inananlar! Yahudi ve hıristiyanları dost edinmeyin. Onlar birbirlerinin dostlarıdırlar. Sizden kim onları dost edinirse, kuşkusuz o da onlardandır. Şüphesiz Allah, zalimler topluluğunu doğruya iletmez."},{"n":52,"t":"İşte kalplerinde bir hastalık (nifak) bulunanların, \"Başımıza bir felaketin gelmesinden korkuyoruz\" diyerek onların arasında koşup durduklarını görürsün. Ama Allah, yakın bir fetih veya katından bir emir getirir ve onlar içlerinde gizledikleri şeye (nifaka) pişman olurlar."},{"n":53,"t":"(O zaman) iman edenler derler ki: \"Sizinle beraber olduklarına dair var güçleriyle Allah’a yemin edenler şunlar mı?\" Bunların çabaları boşa çıkmıştır. Böylece ziyan edenler olmuşlardır."},{"n":54,"t":"Ey iman edenler! Sizden kim dininden dönerse, (bilin ki) Allah onların yerine öyle bir topluluk getirir ki, Allah onları sever, onlar da Allah’ı severler. Onlar mü’minlere karşı alçak gönüllü, kâfirlere karşı güçlü ve onurludurlar. Allah yolunda cihad ederler. (Bu yolda) hiçbir kınayıcının kınamasından da korkmazlar. İşte bu, Allah’ın bir lütfudur. Onu dilediğine verir. Allah, lütfu geniş olandır, hakkıyla bilendir."},{"n":55,"t":"Sizin dostunuz ancak Allah’tır, Resûlüdür ve Allah’ın emirlerine boyun eğerek namazı kılan, zekâtı veren mü’minlerdir."},{"n":56,"t":"Kim Allah’ı, O‘nun peygamberini ve inananları dost edinirse, bilsin ki şüphesiz Allah taraftarları galiplerin ta kendileridir."},{"n":57,"t":"Ey iman edenler! Sizden önce kendilerine kitap verilenlerden dininizi alaya alıp oyuncak edinenleri ve öteki kâfirleri dost edinmeyin. Eğer mü’minler iseniz Allah’a karşı gelmekten sakının."},{"n":58,"t":"Siz namaza çağırdığınız vakit onu alaya alıp eğlence yerine koyuyorlar. Bu, şüphesiz onların akılları ermeyen bir toplum olmalarındandır."},{"n":59,"t":"De ki: \"Ey kitap ehli! Sadece Allah’a, bize indirilene ve daha önce indirilmiş olan (ilâhî kitap)lara inandığımızdan ve çoğunuzun da fasıklar olmasından ötürü bizden hoşlanmıyorsunuz.\""},{"n":60,"t":"De ki: \"Allah katında cezası bundan daha kötü olanları size haber vereyim mi? Onlar, Allah’ın lânetlediği ve gazabına uğrattığı, içlerinden maymunlar ve domuzlar çıkardığı kimseler ile şeytanlara tapan kimselerdir. İşte bunların yeri daha kötüdür ve onlar doğru yoldan daha çok sapmışlardır.\""},{"n":61,"t":"(Yanınıza) küfürle girip yine (yanınızdan) küfürle çıktıkları hâlde, size geldiklerinde \"İnandık\" dediler. Allah, onların saklamakta oldukları şeyi daha iyi bilir."},{"n":62,"t":"Onlardan çoğunun günahta, düşmanlıkta, haram yemede birbirleriyle yarıştıklarını görürsün. Yapmakta oldukları şey ne kötüdür!"},{"n":63,"t":"Bunları, din adamları ve bilginler günah söz söylemekten ve haram yemekten sakındırsalardı ya! Yapmakta oldukları şey ne kötüdür!"},{"n":64,"t":"Bir de Yahudiler, \"Allah’ın eli bağlıdır\" dediler. Söylediklerinden ötürü kendi elleri bağlansın ve lânete uğrasınlar! Hayır, O’nun iki eli de açıktır, dilediği gibi verir. Andolsun, sana Rabbinden indirilen (Kur’an) onlardan birçoğunun azgınlık ve küfrünü artıracaktır. Biz onların arasına kıyamete kadar düşmanlık ve kin saldık. Her ne zaman savaş için bir ateş yakmışlarsa, Allah onu söndürmüştür. Onlar yeryüzünde bozgunculuk çıkarmaya çalışırlar. Allah, bozguncuları sevmez."},{"n":65,"t":"Eğer kitap ehli iman etseler ve Allah’a karşı gelmekten sakınsalardı, muhakkak onların kötülüklerini örterdik ve onları Naim cennetlerine koyardık."},{"n":66,"t":"Eğer onlar Tevrat’ı, İncil’i ve Rableri tarafından kendilerine indirileni (Kur’an’ı) gereğince uygulasalardı, elbette üstlerinden ve ayaklarının altından (bol bol rızık) yiyeceklerdi. Onlardan orta yolu tutan bir zümre vardır. Ama onların birçoğunun yaptığı ne kötüdür!"},{"n":67,"t":"Ey Peygamber! Rabbinden sana indirileni tebliğ et. Eğer bunu yapmazsan, O’nun verdiği peygamberlik görevini yerine getirmemiş olursun. Allah, seni insanlardan korur. Şüphesiz Allah, kâfirler topluluğunu hidayete erdirmeyecektir."},{"n":68,"t":"De ki: \"Ey Kitap ehli! Tevrat’ı, İncil’i ve Rabbinizden size indirileni (Kur’an’ı) uygulamadıkça hiçbir şey üzere değilsiniz.\" Andolsun ki sana Rabbinden indirilen bu Kur’an, onlardan çoğunun taşkınlık ve küfrünü artıracaktır. Öyle ise o kâfirler toplumu için üzülme."},{"n":69,"t":"Şüphesiz inananlar (müslümanlar) ile Yahudiler, Sabiîler ve Hıristiyanlardan (her bir grubun kendi şeriatında) \"Allah’a ve ahiret gününe inanan ve salih ameller işleyenler için hiçbir korku yoktur. Onlar mahzun da olmayacaklardır\" (diye hükmedilmiştir.)"},{"n":70,"t":"Andolsun, İsrailoğullarından sağlam söz almış ve onlara peygamberler göndermiştik. Fakat her ne zaman bir Peygamber, onlara nefislerinin hoşlanmadığı bir hükmü getirdiyse; onlardan bir kısmını yalanladılar, bir kısmını da öldürdüler."},{"n":71,"t":"(Bu yaptıklarında) bir belâ olmayacağını sandılar da kör ve sağır kesildiler. Sonra (tövbe ettiler), Allah da onların tövbesini kabul etti. Sonra yine onlardan çoğu kör ve sağır kesildiler. Allah, onların yaptıklarını hakkıyla görendir."},{"n":72,"t":"Andolsun, \"Allah, Meryem oğlu Mesih’tir\" diyenler kesinlikle kâfir oldu. Oysa Mesih şöyle demişti: \"Ey İsrailoğulları! Yalnız, benim de Rabbim, sizin de Rabbiniz olan Allah’a kulluk edin. Kim Allah’a ortak koşarsa, artık, Allah ona cenneti muhakkak haram kılmıştır. Onun barınağı da ateştir. Zalimler için hiçbir yardımcı yoktur.\""},{"n":73,"t":"Andolsun, \"Allah, üçün üçüncüsüdür\" diyenler kâfir oldu. Hâlbuki bir tek ilâhtan başka hiçbir ilâh yoktur. Eğer dediklerinden vazgeçmezlerse, andolsun onlardan inkâr edenlere elbette, elem dolu bir azap dokunacaktır."},{"n":74,"t":"Hâlâ mı Allah’a tövbe etmezler ve O’ndan bağışlanma istemezler? Allah, çok bağışlayandır, çok merhamet edendir."},{"n":75,"t":"Meryem oğlu Mesih, sadece bir peygamberdir. Ondan önce de nice peygamberler geldi geçti. Onun annesi de dosdoğru bir kadındır. (Nasıl ilâh olabilirler?) İkisi de yemek yerlerdi. Bak, onlara âyetlerimizi nasıl açıklıyoruz. Sonra bak ki, nasıl da (haktan) çevriliyorlar."},{"n":76,"t":"(Ey Muhammed!) De ki: \"Allah’ı bırakıp da, sizin için ne bir zarara ne de bir yarara gücü yeten şeylere mi tapıyorsunuz? Oysa Allah, hakkıyla işitendir, hakkıyla bilendir.\""},{"n":77,"t":"De ki: \"Ey Kitap ehli! Hakkın dışına çıkarak dininizde aşırı gitmeyin. Daha önce sapmış, birçoklarını da saptırmış ve dümdüz yoldan da şaşmış bir milletin arzu ve keyiflerine uymayın.\""},{"n":78,"t":"İsrailoğullarından inkâr edenler, Davud ve Meryem oğlu İsa diliyle lânetlendi. Bu, onların isyan etmeleri ve hadlerini aşıyor olmalarından ötürüydü."},{"n":79,"t":"İşledikleri herhangi bir kötülükten birbirlerini vazgeçirmeye çalışmazlardı. Yapmakta oldukları ne kötüydü!"},{"n":80,"t":"Onlardan birçoğunun inkâr edenleri dost edindiklerini görürsün. Andolsun ki kendileri için önceden (ahirete) gönderdikleri şey; Allah’ın onlara gazap etmesi ne kötüdür! Onlar azap içinde ebedî kalıcıdırlar."},{"n":81,"t":"Eğer Allah’a, Peygamber’e ve ona indirilene (Kur’an’a) inanıyor olsalardı, onları (müşrikleri) dost edinmezlerdi. Fakat onlardan birçoğu fasık kimselerdir."},{"n":82,"t":"(Ey Muhammed!) İman edenlere düşmanlık etmede insanların en şiddetlisinin kesinlikle Yahudiler ile Allah’a ortak koşanlar olduğunu görürsün. Yine onların iman edenlere sevgi bakımından en yakınının da \"Biz hıristiyanlarız\" diyenler olduğunu mutlaka görürsün. Çünkü onların içinde keşişler ve rahipler vardır. Onlar büyüklük de taslamazlar."},{"n":83,"t":"Peygamber’e indirileni (Kur’an’ı) dinledikleri zaman hakkı tanımalarından dolayı gözlerinin yaşla dolup taştığını görürsün. \"Ey Rabbimiz! İnandık. Artık bizi (hakikate) şahitlik edenler (Muhammed’in ümmeti) ile beraber yaz\" derler."},{"n":84,"t":"\"Rabbimizin, bizi salihler topluluğuyla beraber (cennete) koymasını umarken, Allah’a ve bize gelen gerçeğe ne diye inanmayalım?\""},{"n":85,"t":"Dedikleri bu söze karşılık Allah onlara, devamlı kalacakları, içinden ırmaklar akan cennetleri mükâfat olarak verdi. İşte bu, iyilik yapanların mükâfatıdır."},{"n":86,"t":"İnkâr edenlere ve âyetlerimizi yalanlayanlara gelince, işte onlar cehennemliklerdir."},{"n":87,"t":"Ey iman edenler! Allah’ın size helâl kıldığı iyi ve temiz nimetleri (kendinize) haram etmeyin ve (Allah’ın koyduğu) sınırları aşmayın. Çünkü Allah, haddi aşanları sevmez."},{"n":88,"t":"Allah’ın size rızık olarak verdiklerinden helâl, iyi ve temiz olarak yiyin ve kendisine inanmakta olduğunuz Allah’a karşı gelmekten sakının."},{"n":89,"t":"Allah, boş bulunarak ettiğiniz yeminlerle sizi sorumlu tutmaz. Ama bile bile yaptığınız yeminlerle sizi sorumlu tutar. Bu durumda yeminin keffareti, ailenize yedirdiğinizin orta hâllisinden on yoksulu doyurmak, yahut onları giydirmek ya da bir köle azat etmektir. Kim (bu imkânı) bulamazsa, onun keffareti üç gün oruç tutmaktır. İşte yemin ettiğiniz vakit yeminlerinizin keffareti budur. Yeminlerinizi tutun. Allah, size âyetlerini işte böyle açıklıyor ki şükredesiniz."},{"n":90,"t":"Ey iman edenler! (Aklı örten) içki (ve benzeri şeyler), kumar, dikili taşlar ve fal okları ancak, şeytan işi birer pisliktir. Onlardan kaçının ki kurtuluşa eresiniz."},{"n":91,"t":"Şeytan, içki ve kumarla, ancak aranıza düşmanlık ve kin sokmak; sizi Allah’ı anmaktan ve namazdan alıkoymak ister. Artık vazgeçiyor musunuz?"},{"n":92,"t":"Öyleyse Allah’a itaat edin, peygambere itaat edin ve Allah’a karşı gelmekten sakının. Şayet yüz çevirirseniz bilmiş olun ki, elçimize düşen sadece apaçık tebliğdir."},{"n":93,"t":"İman edip salih ameller işleyenlere; Allah’a karşı gelmekten sakındıkları, iman ettikleri ve salih amel işledikleri, sonra Allah’a karşı gelmekten sakındıkları ve iman ettikleri, sonra yine Allah’a karşı gelmekten sakındıkları ve iyilik ettikleri takdirde, daha önce tatmış olduklarından dolayı bir günah yoktur. Allah, iyilik edenleri sever."},{"n":94,"t":"Ey iman edenler! Andolsun, Allah sizleri, ellerinizin ve mızraklarınızın erişebileceği av(lar) ile elbette deneyecek ki, görmediği hâlde kendisinden korkanı ayırıp meydana çıkarsın. Kim bundan (bu açıklamadan) sonra haddini tecavüz ederse, ona elem dolu bir azap vardır."},{"n":95,"t":"Ey iman edenler! İhramlı iken (karada) av hayvanı öldürmeyin. Kim (ihramlı iken) onu kasten öldürürse (kendisine) bir ceza vardır. (Bu ceza), Kâ’be’ye ulaştırılmak üzere, öldürdüğünün dengi olup, içinizden iki âdil kimsenin takdir edeceği bir kurbanlık hayvan; veya yoksulları yedirmek suretiyle keffaret; yahut onun dengi oruç tutmaktır. (Bu) yaptığı işin kötü sonucunu tatması içindir. Allah, geçmiştekileri affetmiştir. Fakat kim bir daha böyle yaparsa, Allah ondan intikam alır. Allah, mutlak güç sahibidir, intikam sahibidir."},{"n":96,"t":"Sizin için de yolcular için de bir geçimlik olmak üzere deniz avı yapmak ve deniz ürünlerini yemek sizlere helâl kılındı. Kara avı ise ihramlı olduğunuz sürece size haram kılındı. Huzurunda toplanacağınız Allah’a karşı gelmekten sakının."},{"n":97,"t":"Allah; Ka’be’yi, o saygıdeğer evi, haram ayı, hac kurbanını ve (bu kurbanlara takılı) gerdanlıkları insanlar(ın din ve dünyaları) için ayakta kalma (ve canlanma) sebebi kıldı. Bunlar, göklerde ve yerde ne varsa hepsini Allah’ın bildiğini ve Allah’ın (zaten) her şeyi hakkıyla bilmekte olduğunu bilmeniz içindir."},{"n":98,"t":"Bilin ki, Allah’ın cezası çetindir ve Allah çok bağışlayandır, çok merhamet edendir."},{"n":99,"t":"Peygamberin üzerine düşen ancak tebliğdir. Allah, sizin açıkladığınızı da, gizlediğinizi de bilir."},{"n":100,"t":"(Ey Muhammed!) De ki: \"Pis ile temiz bir olmaz. Pisin çokluğu hoşuna gitse bile.\" Ey akıl sahipleri! Allah’a karşı gelmekten sakının ki kurtuluşa eresiniz."},{"n":101,"t":"Ey iman edenler! Size açıklandığı takdirde, sizi üzecek olan şeylere dair soru sormayın. Eğer Kur’an indirilirken bunlara dair soru sorarsanız size açıklanır. (Hâlbuki) Allah onları bağışlamıştır. Allah, çok bağışlayandır, halîmdir (hemen cezalandırmaz, mühlet verir.)"},{"n":102,"t":"Sizden önceki bir millet o tür şeyleri sordu da sonra o yüzden kâfir oldu."},{"n":103,"t":"Allah, ne \"Bahîre\", ne \"Sâibe\", ne \"Vasîle\", ne de \"Hâm\" diye bir şey meşru kılmamıştır. Fakat, inkâr edenler Allah’a karşı yalan uyduruyorlar. Zaten çoklarının aklı da ermez."},{"n":104,"t":"Onlara, \"Allah’ın indirdiğine (Kur’an’a) ve Peygamber’e gelin\" denildiğinde onlar, \"Babalarımızı üzerinde bulduğumuz din bize yeter\" derler. Peki ya babaları bir şey bilmiyor ve doğru yolu bulamamış olsalar da mı?"},{"n":105,"t":"Ey iman edenler! Siz kendinizi düzeltin. Siz doğru yolda olursanız, yoldan sapan kimse size zarar veremez. Hepinizin dönüşü Allah’adır. O zaman Allah, size yaptıklarınızı haber verecektir."},{"n":106,"t":"Ey iman edenler! Birinizin ölümü yaklaştığı zaman, vasiyet sırasında aranızda şahitlik (edecek olanlar) sizden adaletli iki kişidir. Yahut; seferde olup da başınıza ölüm musibeti gelirse, sizin dışınızdan başka iki kişi şahitlik eder. Eğer şüphe ederseniz, onları namazdan sonra alıkorsunuz da Allah adına, \"Akraba da olsa, şahitliğimizi hiçbir karşılığa değişmeyiz. Allah için yaptığımız şahitliği gizlemeyiz. Gizlediğimiz takdirde, şüphesiz günahkârlardan oluruz\" diye yemin ederler."},{"n":107,"t":"(Eğer sonradan) o iki kişinin günaha girdikleri (yalan söyledikleri) anlaşılırsa, o zaman, bu öncelikli şahitlerin zarar verdiği kimselerden olan başka iki adam, onların yerine geçer ve \"Allah’a yemin ederiz ki, bizim şahitliğimiz onların şahitliğinden elbette daha gerçektir. Biz hakkı da çiğneyip geçmedik. Çünkü o takdirde, biz elbette zalimlerden oluruz\" diye yemin ederler."},{"n":108,"t":"Bu (usul), şahitliği lâyıkıyla yerine getirmeleri ve yeminlerinden sonra başka yeminlere başvurulacağından endişe etmelerini sağlamak için en uygun çaredir. Allah’a karşı gelmekten sakının ve dinleyin. Allah, fasık toplumu doğruya iletmez."},{"n":109,"t":"Allah’ın, peygamberleri toplayıp \"siz(den sonra davetiniz)e ne derece uyuldu?\" diyeceği, onların da, \"Bizim hiçbir bilgimiz yok. Gaybleri hakkıyla bilen ancak sensin\" diyecekleri günü hatırlayın."},{"n":110,"t":"O gün Allah, şöyle diyecek: \"Ey Meryem oğlu İsa! Senin üzerindeki ve annen üzerindeki nimetimi düşün. Hani, seni Ruhu’l-Kudüs (Cebrail) ile desteklemiştim. Beşikte iken de, yetişkin iken de insanlara konuşuyordun. Hani, sana kitabı, hikmeti, Tevrat’ı, İncil’i de öğretmiştim. Hani iznimle çamurdan kuş şekline benzer bir şey yapıyordun da içine üflüyordun, benim iznimle hemen bir kuş oluyordu. Yine benim iznimle doğuştan körü ve alacalıyı iyileştiriyordun. Hani benim iznimle ölüleri de (hayata) çıkarıyordun. Hani sen, İsrailoğullarına açık mucizeler getirdiğin zaman, ben seni onlardan kurtarmıştım da onlardan inkâr edenler, \"Bu, ancak açık bir büyüdür\" demişlerdi."},{"n":111,"t":"Hani bir de, \"Bana ve Peygamberime iman edin\" diye havarilere ilham etmiştim. Onlar da \"İman ettik. Bizim müslüman olduğumuza sen de şahit ol\" demişlerdi."},{"n":112,"t":"Hani havariler de, \"Ey Meryem oğlu İsa! Rabbin bize gökten bir sofra indirebilir mi?\" demişlerdi. İsa da, \"Eğer mü’minler iseniz, Allah’a karşı gelmekten sakının\" demişti."},{"n":113,"t":"Onlar, \"İstiyoruz ki ondan yiyelim, kalplerimiz yatışsın. Senin bize doğru söylediğini bilelim ve ona, (gözü ile) görmüş şahitlerden olalım\" demişlerdi."},{"n":114,"t":"Meryem oğlu İsa, \"Ey Allahım! Ey Rabbimiz! Bize gökten bir sofra indir ki; önce gelenlerimize (zamanımızdaki dindaşlarımıza) ve sonradan geleceklerimize bir bayram ve senden (gelen) bir mucize olsun. Bizi rızıklandır. Sen rızıklandıranların en hayırlısısın\" dedi."},{"n":115,"t":"Allah da, \"Ben onu size indireceğim. Ama ondan sonra sizden her kim inkâr ederse, artık ben ona kâinatta hiçbir kimseye etmeyeceğim azabı ederim\" demişti."},{"n":116,"t":"Allah, kıyamet günü şöyle diyecek: \"Ey Meryem oğlu İsa! Sen mi insanlara, Allah’ı bırakarak beni ve anamı iki ilâh edinin, dedin?\" İsa da şöyle diyecek: \"Seni bütün eksikliklerden uzak tutarım. Hakkım olmayan bir şeyi söylemem, benim için söz konusu olamaz. Eğer ben onu söylemiş olsaydım, elbette sen bunu bilirdin. Sen benim içimde olanı bilirsin, ama ben sende olanı bilemem. Şüphesiz ki yalnızca sen gaybları hakkıyla bilensin.\""},{"n":117,"t":"\"Ben onlara, sadece bana emrettiğin şeyi söyledim: Benim de Rabbim, sizin de Rabbiniz olan Allah’a kulluk edin (dedim.) Aralarında bulunduğum sürece onlara şahit (ve örnek) idim. Ama beni içlerinden aldığında, artık üzerlerine gözetleyici yalnız sen oldun. Sen, her şeye hakkıyla şahitsin.\""},{"n":118,"t":"\"Eğer onlara azap edersen, şüphe yok ki onlar senin kullarındır. Eğer onları bağışlarsan, yine şüphe yok ki sen mutlak güç sahibisin, hüküm ve hikmet sahibisin."},{"n":119,"t":"Allah, şöyle diyecek: \"Bugün, doğrulara, doğruluklarının yarar sağlayacağı gündür.\" Onlara içinden ırmaklar akan, içinde ebedî kalacakları cennetler vardır. Allah, onlardan razı olmuş, onlar da Allah’tan razı olmuşlardır. İşte bu büyük başarıdır."},{"n":120,"t":"Göklerin, yerin ve bunlardaki her şeyin hükümranlığı yalnızca Allah’ındır. O, her şeye hakkıyla gücü yetendir."}],[{"n":1,"t":"Hamd, gökleri ve yeri yaratan, karanlıkları ve aydınlığı var eden Allah’a mahsustur. Böyle iken inkâr edenler başka şeyleri Rablerine denk tutuyorlar."},{"n":2,"t":"O öyle bir Rab’dır ki, sizi çamurdan yaratmış, sonra (her birinize) bir ecel tayin etmiştir. (Kıyametin kopması için) belirlenmiş bir ecel de O’nun katındadır. Siz ise hâlâ şüphe ediyorsunuz."},{"n":3,"t":"Hâlbuki O, göklerde de Allah’tır, yerde de. Sizin gizlinizi de bilir, açığa vurduğunuzu da. Sizin daha ne kazanacağınızı da bilir."},{"n":4,"t":"Onlara Rablerinin âyetlerinden hiçbir âyet gelmez ki ondan yüz çevirmesinler."},{"n":5,"t":"Nitekim hak (Kur’an) kendilerine gelince onu yalanladılar. Fakat alay ettikleri şeyin haberleri kendilerine ilerde gelecektir."},{"n":6,"t":"Onlardan önce nice nesilleri helâk ettiğimizi görmediler mi? Yeryüzünde size vermediğimiz imkân ve iktidarı onlara vermiştik. Onlara bol bol yağmur yağdırmıştık. Topraklarından nehirler akıttık. Sonra da günahları sebebiyle onları helâk ettik ve arkalarından başka bir nesil var ettik."},{"n":7,"t":"(Ey Muhammed!) Eğer sana kâğıda yazılı bir kitap indirseydik, onlar da elleriyle ona dokunsalardı, yine o inkâr edenler, \"Bu, apaçık büyüden başka bir şey değildir\" diyeceklerdi."},{"n":8,"t":"Bir de dediler ki: \"Ona (açıktan göreceğimiz) bir melek indirilse ya!\" Eğer (öyle) bir melek indirseydik artık iş bitirilmiş olurdu, sonra da kendilerine göz açtırılmazdı. (Hemen helâk edilirlerdi.)"},{"n":9,"t":"Eğer onu (Peygamberi) bir melek kılsaydık yine onu bir adam (suretinde) yapardık ve onları yine içinde bulundukları karmaşaya düşürmüş olurduk."},{"n":10,"t":"(Ey Muhammed!) Andolsun, senden önce de birçok peygamber alaya alınmıştı da onlarla alay edenleri, alay ettikleri şey kuşatıp mahvetmişti."},{"n":11,"t":"De ki: \"Yeryüzünde gezin dolaşın da (Peygamberleri) yalanlayanların sonu nasıl olmuş bir görün.\""},{"n":12,"t":"De ki: \"Şu göklerdekiler ve yerdekiler kimindir?\" \"Allah’ındır\" de. O, merhamet etmeyi kendine gerekli kıldı. Andolsun sizi mutlaka kıyamet gününe toplayacak. Bunda hiç şüphe yok. Kendilerini ziyana uğratanlar var ya, işte onlar inanmazlar."},{"n":13,"t":"Gece ve gündüzde barınan her şey O’nundur. O, hakkıyla işitendir, hakkıyla bilendir."},{"n":14,"t":"De ki: \"Göklerin ve yerin yaratıcısı olan, beslediği hâlde beslenmeye ihtiyacı olmayan Allah’tan başkasını mı dost edineceğim.\" De ki: \"Bana, (Allah’a) teslim olanların ilki olmam emredildi ve sakın Allah’a ortak koşanlardan olma (denildi).\""},{"n":15,"t":"De ki: \"Ben Rabbime isyan edersem gerçekten, büyük bir günün (kıyamet gününün) azabından korkarım.\""},{"n":16,"t":"(O günün azabı) kimden savuşturulursa, gerçekten (Allah) ona acımıştır. İşte bu apaçık kurtuluştur."},{"n":17,"t":"Şayet Allah sana bir zarar dokundursa, bunu O’ndan başka giderecek yoktur. Fakat sana bir hayır dokunduracak olsa onu da kimse gideremez. Bil ki O, her şeye hakkıyla gücü yetendir."},{"n":18,"t":"O, kullarının üstünde mutlak hâkimiyet sahibidir. O, hüküm ve hikmet sahibidir, (her şeyden) hakkıyla haberdardır."},{"n":19,"t":"De ki: \"Şahitlik bakımından hangi şey daha büyüktür?\" De ki: \"Allah benimle sizin aranızda şahittir. İşte bu Kur’an bana, onunla sizi ve eriştiği herkesi uyarayım diye vahyolundu. Gerçekten siz mi Allah ile beraber başka ilâhlar olduğuna şahitlik ediyorsunuz?\" De ki: \"Ben şahitlik etmem.\" De ki: \"O, ancak tek bir ilâhtır ve şüphesiz ben sizin Allah’a ortak koştuğunuz şeylerden uzağım.\""},{"n":20,"t":"Kendilerine kitap verdiklerimiz, onu (Peygamberi) kendi öz oğullarını tanıdıkları gibi tanırlar. Kendilerini ziyana sokanlar var ya, işte onlar inanmazlar."},{"n":21,"t":"Kim Allah’a karşı yalan uydurandan, ya da O’nun âyetlerini yalanlayandan daha zalimdir? Şüphesiz ki, zalimler kurtuluşa eremez."},{"n":22,"t":"Onları tümüyle (mahşere) toplayıp da Allah’a ortak koşanlara, \"Nerede, ilâh olduklarını iddia ettiğiniz ortaklarınız?\" diyeceğimiz günü hatırla."},{"n":23,"t":"Sonunda onların manevraları, \"Rabbimiz Allah’a andolsun ki biz (O’na) ortak koşanlar değildik\" demelerinden başka bir şey olmayacaktır."},{"n":24,"t":"Bak, kendilerine karşı nasıl yalan söylediler ve iftira edip durdukları şeyler (uydurma ilâhları) onları nasıl yüzüstü bırakıp kayboluverdi?"},{"n":25,"t":"İçlerinden, (Kur’an okurken) seni dinleyenler de var. Onu anlamamaları için kalpleri üzerine perdeler (gereriz), kulaklarına ağırlık koyarız. Her türlü mucizeyi görseler de onlara inanmazlar. Hatta tartışmak üzere sana geldiklerinde inkâr edenler, \"Bu (Kur’an) evvelkilerin masallarından başka bir şey değil\" derler."},{"n":26,"t":"Onlar başkalarını ondan (Kur’an’dan) alıkoyarlar, hem de kendileri ondan uzak kalırlar. Onlar farkına varmaksızın, ancak kendilerini helâk ediyorlar."},{"n":27,"t":"Ateşin karşısında durdurulup da, \"Ah, keşke dünyaya geri döndürülsek de Rabbimizin âyetlerini yalanlamasak ve mü’minlerden olsak\" dedikleri vakit (hâllerini) bir görsen!"},{"n":28,"t":"Hayır, (bu yakınmaları) daha önce gizlemekte oldukları şeyler onlara göründü (de ondan). Eğer çevrilselerdi, elbette kendilerine yasaklanan şeylere yine döneceklerdi. Şüphesiz onlar yalancıdırlar."},{"n":29,"t":"Derler ki: \"Hayat ancak dünya hayatımızdır. Artık biz bir daha diriltilecek de değiliz.\""},{"n":30,"t":"Rab’lerinin huzurunda durduruldukları vakit (hâllerini) bir görsen! (Allah) diyecek ki: \"Nasıl, şu (dirilmek) gerçek değil miymiş?\" Onlar, \"Evet, Rabbimize andolsun ki, gerçekmiş\" diyecekler. (Allah), \"Öyleyse inkâr etmekte olduğunuzdan dolayı tadın azabı!\" diyecek."},{"n":31,"t":"Allah’ın huzuruna çıkmayı yalanlayanlar gerçekten ziyana uğramıştır. Nihayet onlara ansızın o saat (kıyamet) gelip çatınca, bütün günahlarını sırtlarına yüklenerek, \"Hayatta yaptığımız kusurlardan ötürü vay hâlimize!\" diyecekler. Dikkat edin, yüklendikleri günah yükü ne kötüdür!"},{"n":32,"t":"Dünya hayatı ancak bir oyun ve bir eğlencedir. Elbette ki ahiret yurdu Allah’a karşı gelmekten sakınanlar için daha hayırlıdır. Hâlâ akıllanmayacak mısınız?"},{"n":33,"t":"Ey Muhammed! Biz çok iyi biliyoruz ki söyledikleri elbette seni incitiyor. Onlar gerçekte seni yalanlamıyorlar; fakat o zalimler Allah’ın âyetlerini inadına inkâr ediyorlar."},{"n":34,"t":"Andolsun ki, senden önce de birçok Peygamberler yalanlanmıştı da onlar yalanlanmalarına ve eziyet edilmelerine karşı sabretmişler ve nihayet kendilerine yardımımız yetişmişti. Allah’ın kelimelerini değiştirebilecek bir güç de yoktur. Andolsun peygamberler ile ilgili haberlerin bir kısmı sana gelmiş bulunuyor."},{"n":35,"t":"Eğer onların yüz çevirmeleri sana ağır geldiyse; bir delik açıp yerin dibine inerek, yahut bir merdiven kurup göğe çıkarak onlara bir mucize getirmeye gücün yetiyorsa durma, yap! Eğer Allah dileseydi, elbette onları hidayet üzere toplardı. O hâlde, sakın cahillerden olma."},{"n":36,"t":"(Davete), ancak (bütün kalpleriyle) kulak verenler uyar. (Kalben) ölüleri ise (yalnızca) Allah diriltir. Sonra da hepsi O’na döndürülürler."},{"n":37,"t":"Dediler ki: \"Ona Rabbinden bir mucize indirilse ya!\" (Ey Muhammed!) De ki: \"Şüphesiz Allah’ın, bir mucize indirmeğe gücü yeter. Fakat onların çoğu bilmiyor.\""},{"n":38,"t":"Yeryüzünde gezen her türlü canlı ve (gökte) iki kanadıyla uçan her tür kuş, sizin gibi birer topluluktan başka bir şey değildir. Biz Kitap’ta hiçbir şeyi eksik bırakmadık. Sonunda hepsi Rablerinin huzuruna toplanıp getirilecekler."},{"n":39,"t":"Âyetlerimizi yalanlayanlar, karanlıklar içerisindeki birtakım sağırlar ve dilsizlerdir. Allah, kimi dilerse onu şaşırtır. Kimi de dilerse onu dosdoğru yol üzere kılar."},{"n":40,"t":"(Ey Muhammed!) De ki: \"Söyleyin bakalım. Acaba size Allah’ın azabı gelse veya size kıyamet saati gelip çatsa (böyle bir durumda) siz Allah’tan başkasını mı çağırırsınız? Eğer (putların size yararı dokunduğu iddianızda) doğru söyleyenlerseniz (haydi onları yardıma çağırın)."},{"n":41,"t":"Hayır! (Bu durumda) yalnız O’na dua edersiniz, O da dilerse (kurtulmak için) dua ettiğiniz sıkıntıyı giderir ve siz o an Allah’a ortak koştuklarınızı unutursunuz."},{"n":42,"t":"Andolsun, senden önce birtakım ümmetlere de peygamberler gönderdik. (Peygamberlerini dinlemediler.) Sonunda, yalvarsınlar da tövbe etsinler diye onları şiddetli yoksulluk ve darlıklarla yakaladık."},{"n":43,"t":"Hiç olmazsa onlara azabımız geldiği zaman yakarıp tövbe etselerdi ya.. Fakat (onu yapmadılar) kalpleri katılaştı. Şeytan da yapmakta olduklarını zaten onlara süslü göstermişti."},{"n":44,"t":"Derken onlar kendilerine hatırlatılanı unuttuklarında, (önce) üzerlerine her şeyin kapılarını açtık. Sonra kendilerine verilenle sevinip şımardıkları sırada, onları ansızın yakaladık da bir anda tüm ümitlerini kaybedip yıkıldılar."},{"n":45,"t":"Böylece zulmeden o toplumun kökü kesildi. Hamd, âlemlerin Rabbi Allah’a mahsustur."},{"n":46,"t":"De ki: \"Ne dersiniz, eğer Allah sizin kulağınızı ve gözlerinizi alır, kalplerinizi de mühürlerse, Allah’tan başka onu size (geri) getirecek ilâh kimmiş?\" Bak, biz âyetleri değişik biçimlerde nasıl açıklıyoruz, sonra onlar nasıl yüz çeviriyorlar?"},{"n":47,"t":"De ki: \"Ne dersiniz, Allah’ın azabı size beklenmedik bir anda veya açıktan açığa gelse, zalimler toplumundan başkası mı helâk edilecek?\""},{"n":48,"t":"Biz peygamberleri ancak müjdeleyiciler ve uyarıcılar olarak göndeririz. Kim iman eder ve kendini düzeltirse onlara korku yoktur. Onlar mahzun da olacak değillerdir."},{"n":49,"t":"Âyetlerimizi yalanlayanlara ise, yapmakta oldukları fasıklık sebebiyle azap dokunacaktır."},{"n":50,"t":"De ki: \"Ben size, ‘Allah’ın hazineleri benim yanımdadır’ demiyorum. Ben gaybı da bilmem. Size ‘Ben bir meleğim’ de demiyorum. Ben sadece, bana gönderilen vahye uyuyorum.\" De ki: \"Görmeyenle gören bir olur mu? Siz hiç düşünmez misiniz?\""},{"n":51,"t":"Kendileri için Allah’tan başka ne bir dost, ne de bir şefaatçi bulunmaksızın, Rab’lerinin huzurunda toplanmaktan korkanları, Allah’a karşı gelmekten sakınsınlar diye, onunla (Kur’an ile) uyar."},{"n":52,"t":"Rab’lerinin rızasını isteyerek sabah akşam O’na dua edenleri yanından kovma. Onların hesabından sana bir şey yok, senin hesabından da onlara bir şey yok ki onları kovasın. Eğer kovarsan zalimlerden olursun."},{"n":53,"t":"Böylece insanların bazısını bazısı ile denedik ki, \"Allah, aramızdan şu adamları mı iman nimetine lâyık gördü?\" desinler. Allah, şükreden kullarını daha iyi bilen değil mi?"},{"n":54,"t":"Âyetlerimize iman edenler sana geldikleri zaman, de ki: \"Selâm olsun size! Rabbiniz kendi üzerine rahmeti (merhameti) yazdı. Şöyle ki: Sizden kim cahillikle bir kabahat işler de sonra peşinden tövbe eder, kendini düzeltirse (bilmiş olun ki) O, çok bağışlayandır, çok merhamet edendir.\""},{"n":55,"t":"Suçluların yolu da açığa çıksın diye âyetleri işte böyle ayrı ayrı açıklarız."},{"n":56,"t":"De ki: \"Sizin, Allah’tan başka ibadet ettiğiniz şeylere ibadet etmem bana kesinlikle yasaklandı. Ben sizin arzularınıza uymam. (Uyarsam) o takdirde sapmış olurum, hidayete erenlerden olmam.\""},{"n":57,"t":"De ki: \"Şüphesiz ben, Rabbimden (gelen) kesin bir belge üzereyim. Siz ise onu yalanladınız. Sizin acele istediğiniz azap benim elimde değil. Hüküm yalnızca Allah’a aittir. O, hakkı anlatır. O, hakkı batıldan ayırt edenlerin en hayırlısıdır.\""},{"n":58,"t":"De ki: \"Sizin acele istediğiniz azap şayet benim elimde olsaydı, benimle sizin aranızda iş elbette bitirilmiş olurdu.\" Allah, zalimleri daha iyi bilir."},{"n":59,"t":"Gaybın anahtarları yalnızca O’nun katındadır. Onları ancak O bilir. Karada ve denizde olanı da bilir. Hiçbir yaprak düşmez ki onu bilmesin. Yerin karanlıklarında da hiçbir tane, hiçbir yaş, hiçbir kuru şey yoktur ki apaçık bir kitapta (Allah’ın bilgisi dâhilinde, Levh-i Mahfuz’da) olmasın."},{"n":60,"t":"O, geceleyin sizi ölü gibi kendinizden geçirip alan (uyutan) ve gündüzün kazandıklarınızı bilen, sonra da belirlenmiş eceliniz tamamlanıncaya kadar gündüzleri sizi tekrar diriltendir (uyandırandır). Sonra dönüşünüz yalnız O’nadır. Sonra O, işlemekte olduklarınızı size haber verecektir."},{"n":61,"t":"O, kullarının üstünde mutlak hâkimiyet sahibidir. Üzerinize de koruyucu melekler gönderir. Nihayet birinize ölüm geldiği vakit (görevli) elçilerimiz onun canını alır ve onlar görevlerinde asla kusur etmezler."},{"n":62,"t":"Sonra hepsi, gerçek sahipleri Allah’a döndürülürler. İyi bilin ki hüküm yalnız O’nundur. O, hesap görenlerin en çabuğudur."},{"n":63,"t":"De ki: \"Sizler, açıktan ve gizlice O’na ‘Eğer bizi bundan kurtarırsa, elbette şükredenlerden olacağız’ diye dua ederken, sizi karanın ve denizin karanlıklarından (tehlikelerinden) kim kurtarır?\""},{"n":64,"t":"De ki: \"Onlardan ve her türlü sıkıntıdan sizi Allah kurtarır. Ama siz yine de O’na ortak koşuyorsunuz.\""},{"n":65,"t":"De ki: \"O, size üstünüzden (gökten) veya ayaklarınızın altından (yerden) bir azap göndermeğe, ya da sizi grup grup birbirinize düşürmeğe ve kiminizin şiddetini kiminize tattırmaya gücü yetendir.\" Bak, anlasınlar diye, âyetleri değişik biçimlerde nasıl açıklıyoruz."},{"n":66,"t":"O (Kur’an) hak olduğu hâlde, kavmin onu yalanladı. De ki: \"Ben size vekil (sizden sorumlu) değilim.\""},{"n":67,"t":"Her haberin gerçekleşeceği bir zamanı vardır. İleride bileceksiniz."},{"n":68,"t":"Âyetlerimiz hakkında dedikoduya dalanları gördüğün vakit başka bir söze dalıncaya kadar onlardan yüz çevir, uzaklaş. Şayet şeytan sana unutturursa hatırladıktan sonra (kalk), o zalimler grubu ile beraber oturma."},{"n":69,"t":"Allah’a karşı gelmekten sakınanlara, onların hesabından bir şey (sorumluluk) yoktur. Fakat üzerlerine düşen bir hatırlatmadır. Belki sakınırlar."},{"n":70,"t":"Dinlerini oyun ve eğlence edinenleri ve dünya hayatı kendilerini aldatmış olanları bırak. Hiç kimsenin kazandığı yüzünden mahrumiyete sürüklenmemesi için Kur’an ile öğüt ver. Yoksa ona Allah’tan başka ne bir dost vardır, ne de bir şefaatçi. (Kurtuluşu için) her türlü fidyeyi verse de bu ondan kabul edilmez. İşte onlar kazandıkları yüzünden helâke sürüklenmiş kimselerdir. Küfre saplanıp kalmalarından dolayı onlara çılgınca kaynamış bir içecek ve elem dolu bir azap vardır."},{"n":71,"t":"De ki: \"Allah’ı bırakıp da bize faydası olmayan, zararı da dokunmayan şeylere mi tapalım? Allah, bizi hidayete kavuşturduktan sonra gerisingeri (şirke) mi döndürülelim? Arkadaşları ‘bize gel!’ diye doğru yola çağırdıkları hâlde, yeryüzünde şaşkın şaşkın dolaşıp şeytanların ayarttığı kimse gibi mi (olalım)?\" De ki: \"Hiç şüphesiz asıl doğru yol Allah’ın yoludur. Bize âlemlerin Rabbine boyun eğmek emrolundu.\""},{"n":72,"t":"Bir de, bize, \"Namazı dosdoğru kılın ve Allah’a karşı gelmekten sakının\" diye emrolundu. O, huzurunda toplanacağınız Allah’tır."},{"n":73,"t":"O, gökleri ve yeri, hak ve hikmete uygun olarak yaratandır. Allah’ın \"ol\" deyip de her şeyin oluvereceği günü hatırla. O’nun sözü gerçektir. Sûr’a üflendiği gün de mülk (hükümranlık) O’nundur. Gaybı da, görülen âlemi de bilendir. O, hüküm ve hikmet sahibidir, (her şeyden) hakkıyla haberdardır."},{"n":74,"t":"Hani İbrahim, babası Âzer’e, \"Sen putları ilâh mı ediniyorsun? Şüphesiz, ben seni de, kavmini de apaçık bir sapıklık içinde görüyorum\" demişti."},{"n":75,"t":"İşte böylece İbrahim’e göklerdeki ve yerdeki hükümranlığı ve nizamı gösteriyorduk ki kesin ilme erenlerden olsun."},{"n":76,"t":"Üzerine gece karanlığı basınca, bir yıldız gördü. \"İşte Rabbim!\" dedi. Yıldız batınca da, \"Ben öyle batanları sevmem\" dedi."},{"n":77,"t":"Ay’ı doğarken görünce de, \"İşte Rabbim!\" dedi. Ay da batınca, \"Andolsun ki, Rabbim bana doğru yolu göstermezse, mutlaka ben de sapıklardan olurum\" dedi."},{"n":78,"t":"Güneşi doğarken görünce de, \"İşte benim Rabbim! Bu daha büyük\" dedi. O da batınca (kavmine dönüp), \"Ey kavmim! Ben sizin Allah’a ortak koştuğunuz şeylerden uzağım\" dedi."},{"n":79,"t":"\"Ben, hakka yönelen birisi olarak yüzümü, gökleri ve yeri yaratana döndürdüm. Ben, Allah’a ortak koşanlardan değilim.\""},{"n":80,"t":"Kavmi onunla tartışmaya girişti. Dedi ki: \"Beni doğru yola iletmişken, Allah hakkında benimle tartışmaya mı kalkışıyorsunuz? Hem sizin O’na ortak koştuklarınızdan ben korkmam; ancak Rabbimin bir şey dilemiş olması başka. Rabbimin ilmi her şeyi kuşatmıştır. Hâlâ düşünüp öğüt almayacak mısınız?\""},{"n":81,"t":"\"Allah’ın, size, hakkında hiçbir delil indirmediği şeyleri O’na ortak koşmaktan korkmuyorsunuz da, ben sizin ortak koştuğunuz şeylerden ne diye korkayım? Öyle ise iki taraftan hangisi güvende olmaya daha lâyıktır? Eğer biliyorsanız söyleyin.\""},{"n":82,"t":"İman edip de imanlarına zulmü (şirki) bulaştırmayanlar var ya; işte güven onların hakkıdır. Doğru yolu bulmuş olanlar da onlardır."},{"n":83,"t":"İşte kavmine karşı İbrahim’e verdiğimiz delillerimiz.. Biz dilediğimiz kimsenin derecelerini yükseltiriz. Şüphesiz ki Rabbin hüküm ve hikmet sahibidir, hakkıyla bilendir."},{"n":84,"t":"Biz ona İshak’ı ve Yakub’u armağan ettik. Hepsini hidayete erdirdik. Daha önce Nûh’u da hidayete erdirmiştik. Zürriyetinden Dâvud’u, Süleyman’ı, Eyyub’u, Yûsuf’u, Mûsâ’yı ve Hârûn’u da. İyilik yapanları işte böyle mükâfatlandırırız."},{"n":85,"t":"Zekeriya’yı, Yahya’yı, İsa’yı, İlyas’ı doğru yola erdirmiştik. Bunların hepsi salih kimselerden idi."},{"n":86,"t":"İsmail’i, Elyasa’ı, Yûnus’u ve Lût’u da doğru yola erdirmiştik. Her birini âlemlere üstün kılmıştık."},{"n":87,"t":"Babalarından, çocuklarından ve kardeşlerinden bir kısmını da. Bütün bunları seçtik ve bunları dosdoğru bir yola ilettik."},{"n":88,"t":"İşte bu, Allah’ın hidayetidir ki, kullarından dilediğini buna iletip yöneltir. Eğer onlar da Allah’a ortak koşsalardı, bütün yaptıkları boşa gitmişti."},{"n":89,"t":"Onlar kendilerine kitap, hikmet ve peygamberlik verdiğimiz kimselerdir. Eğer şunlar (inanmayanlar) bunları tanımayıp inkâr ederlerse, biz onları inkâr etmeyecek olan bir kavmi, onlara vekil kılmışızdır."},{"n":90,"t":"İşte, o peygamberler, Allah’ın doğru yola ilettiği kimselerdir. (Ey Muhammed!) Sen de onların tuttuğu yola uy. De ki: \"Bu tebliğe karşı sizden bir ücret istemiyorum. O (Kur’an), bütün âlemler için ancak bir uyarıdır.\""},{"n":91,"t":"Allah’ın kadrini gereği gibi bilemediler. Çünkü, \"Allah, hiç kimseye hiçbir şey indirmedi\" dediler. De ki: \"Mûsâ’nın insanlara bir nur ve hidayet olarak getirdiği, parça parça kâğıtlar hâline koyup ortaya çıkardığınız, pek çoğunu ise gizlediğiniz; (kendisiyle) sizin de, babalarınızın da bilmediği şeylerin size öğretildiği Kitab’ı kim indirdi?\" (Ey Muhammed!) \"Allah\" (indirdi) de, sonra bırak onları, içine daldıkları batakta oynayadursunlar."},{"n":92,"t":"İşte bu (Kur’an) da, bereket kaynağı, kendinden öncekileri (ilâhî kitapları) tasdik eden ve şehirler anasını (Mekke’yi) ve bütün çevresini (tüm insanlığı) uyarasın diye indirdiğimiz bir kitaptır. Ahirete iman edenler, ona da inanırlar. Onlar namazlarını vaktinde kılarlar."},{"n":93,"t":"Allah’a karşı yalan uyduran veya kendine bir şey vahyedilmemişken, \"Bana vahyolundu\" diyen, ya da \"Allah’ın indirdiğinin benzerini ben de indireceğim\" diye laf eden kimseden daha zalim kimdir? Zalimlerin şiddetli ölüm sancıları içinde çırpındığı; meleklerin, ellerini uzatmış, \"Haydi canlarınızı kurtarın! Allah’a karşı doğru olmayanı söylediğiniz, ve O’nun âyetlerinden kibirlenerek yüz çevirdiğiniz için bugün aşağılayıcı azap ile cezalandırılacaksınız\" diyecekleri zaman hâllerini bir görsen!"},{"n":94,"t":"Andolsun, sizi ilk defa yarattığımız gibi teker teker bize geldiniz. Size verdiğimiz dünyalık nimetleri de arkanızda bıraktınız. Hani hakkınızda Allah’ın ortakları olduğunu zannettiğiniz şefaatçilerinizi de yanınızda görmüyoruz? Artık aranızdaki bağlar tamamen kopmuş ve (Allah’ın ortağı olduklarını) iddia ettikleriniz, sizi yüzüstü bırakıp kaybolmuşlardır."},{"n":95,"t":"Şüphesiz Allah, taneyi ve çekirdeği yarıp filizlendirendir. Ölüden diriyi çıkarır. Diriden de ölüyü çıkarandır. İşte budur Allah! Peki (O’ndan) nasıl çevriliyorsunuz?"},{"n":96,"t":"O, karanlığı yarıp sabahı çıkarandır. Geceyi dinlenme zamanı, güneşi ve ayı da ince birer hesap ölçüsü kıldı. Bütün bunlar mutlak güç sahibinin, hakkıyla bilenin takdiridir (ölçüp biçmesidir)."},{"n":97,"t":"O, sayelerinde, kara ve denizin karanlıklarında yolunuzu bulasınız diye sizin için yıldızları yaratandır. Bilen bir toplum için âyetleri ayrı ayrı açıkladık."},{"n":98,"t":"O, sizi bir tek candan yaratandır. Sizin bir karar kılma yeriniz, bir de emanet bırakılma yeriniz var. Biz anlayan bir toplum için âyetleri ayrı ayrı açıklamışızdır."},{"n":99,"t":"O, gökten su indirendir. İşte biz onunla her türlü bitkiyi çıkarıp onlardan yeşillik meydana getirir ve o yeşil bitkilerden, üst üste binmiş taneler, -hurma ağacının tomurcuğunda da aşağıya sarkmış salkımlar- üzüm bahçeleri, zeytin ve nar çıkarırız: (Her biri) birbirine benzer ve (her biri) birbirinden farklı. Bunların meyvesine, bir meyve verdiği zaman, bir de olgunlaştığı zaman bakın. Şüphesiz bunda inanan bir topluluk için (Allah’ın varlığını gösteren) ibretler vardır."},{"n":100,"t":"Bir de cinleri Allah’a birtakım ortaklar yaptılar. Oysa onları O yarattı. Bilgisizce Allah’a oğullar ve kızlar da uydurdular. O, onların niteledikleri şeylerden uzaktır, yücedir."},{"n":101,"t":"O, gökleri ve yeri örnekleri yokken yaratandır. O’nun bir eşi olmadığı hâlde, nasıl bir çocuğu olabilir? Hâlbuki her şeyi O yarattı. O, her şeyi hakkıyla bilendir."},{"n":102,"t":"İşte sizin Rabbiniz Allah. O’ndan başka hiçbir ilâh yoktur. O, her şeyin yaratıcısıdır. Öyle ise O’na kulluk edin. O, her şeye vekil (her şeyi yöneten, görüp gözeten)dir."},{"n":103,"t":"Gözler O’nu idrak edemez ama O, gözleri idrak eder. O, en gizli şeyleri bilendir, (her şeyden) hakkıyla haberdar olandır."},{"n":104,"t":"Rabbinizden size gerçekleri gösteren deliller geldi. Artık kim gözünü açar hakkı idrak ederse kendi yararına, kim de (hakkın karşısında) körlük ederse kendi zararınadır. Ben başınızda bekçi değilim."},{"n":105,"t":"Onlar, \"Sen iyi ders almışsın\" desinler diye ve bir de bilen bir toplum için onu (Kur’an’ı) açıklayalım diye âyetleri değişik biçimlerde işte böylece açıklıyoruz."},{"n":106,"t":"Ey Muhammed! Sen, Rabbinden sana vahyedilene uy. O’ndan başka hiçbir ilâh yoktur. Allah’a ortak koşanlardan yüz çevir."},{"n":107,"t":"Allah dileseydi ortak koşmazlardı. Biz seni onların başına bir bekçi yapmadık. Sen onlara vekil (onlardan sorumlu) da değilsin."},{"n":108,"t":"Onların, Allah’ı bırakıp tapındıklarına sövmeyin, sonra onlar da haddi aşarak, bilgisizce Allah’a söverler. Böylece her ümmete yaptıklarını süslü gösterdik. Sonra dönüşleri ancak Rablerinedir. O, yapmakta olduklarını kendilerine bildirecektir."},{"n":109,"t":"Eğer kendilerine (başka) bir mucize gelirse, mutlaka ona inanacaklarına dair en güçlü yeminleriyle Allah’a yemin ettiler. De ki: \"Mucizeler ancak Allah katındadır. O mucizeler geldiği vakit de inanmayacaklarını siz ne bileceksiniz?\""},{"n":110,"t":"Biz onların kalplerini ve gözlerini ters döndürürüz de ilkin ona iman etmedikleri gibi (mucize geldikten sonra da inanmazlar) ve yine onları azgınlıkları içinde bırakırız da bocalar dururlar."},{"n":111,"t":"Biz onlara melekleri de indirseydik, kendileriyle ölüler de konuşsaydı ve her şeyi karşılarında (hakikatın şahidleri olarak) toplasaydık, Allah dilemedikçe yine de iman edecek değillerdi. Fakat onların çoğu bilmiyorlar."},{"n":112,"t":"İşte böylece biz her peygambere insan ve cin şeytanlarını düşman kıldık. Bunlar aldatmak için birbirlerine yaldızlı laflar fısıldarlar. Rabbin dileseydi, bunu yapamazlardı. O hâlde, onları iftiralarıyla baş başa bırak."},{"n":113,"t":"Bir de (şeytanlar), ahirete inanmayanların gönülleri bu yaldızlı sözlere meyletsin, onlardan hoşlansınlar ve işleyecekleri günahları işlesinler diye (bu fısıldamayı yaparlar)."},{"n":114,"t":"\"Size Kitab’ı (Kur’an’ı) hak olarak indiren O iken ben Allah’tan başka bir hakem mi arayacağım?\" (de). Kendilerine kitap verdiklerimiz de onun, Rabbin katından hak olarak indirilmiş olduğunu bilirler. O hâlde, sakın şüphecilerden olma."},{"n":115,"t":"Rabbinin kelimesi (Kur’an) doğruluk ve adalet bakımından tamdır. Onun kelimelerini değiştirebilecek yoktur. O, hakkıyla işitendir, hakkıyla bilendir."},{"n":116,"t":"Eğer yeryüzündekilerin çoğuna uyarsan seni Allah yolundan saptırırlar. Onlar ancak zanna uyuyorlar ve onlar sadece yalan uyduruyorlar."},{"n":117,"t":"Şüphesiz senin Rabbin, yolundan sapanı çok iyi bilir ve yine O, doğru yolu bulanları en iyi bilendir."},{"n":118,"t":"Artık, âyetlerine inanan kimseler iseniz üzerine Allah’ın ismi anılarak kesilmiş hayvanlardan yiyin."},{"n":119,"t":"Allah, yemek zorunda kaldıklarınız dışında size neleri haram kıldığını tek tek açıklamışken, üzerine adının anıldığı hayvanları yememenizin sebebi nedir. Gerçekten birçokları nefislerinin arzularına uyarak bilmeden (halkı) saptırıyorlar. Şüphesiz senin Rabbin, haddi aşanları çok iyi bilir."},{"n":120,"t":"Günahın açığını da bırakın, gizlisini de. Çünkü günah kazananlar yaptıkları karşılığında cezalandırılacaklardır."},{"n":121,"t":"Üzerine Allah adı anılmayan (hayvan)lardan yemeyin. Çünkü bu şekilde davranış fasıklıktır. Bir de şeytanlar kendi dostlarına sizinle mücadele etmeleri için mutlaka fısıldarlar. Onlara boyun eğerseniz şüphesiz siz de Allah’a ortak koşmuş olursunuz."},{"n":122,"t":"Ölü iken dirilttiğimiz ve kendisine, insanlar arasında yürüyeceği bir nur verdiğimiz kimsenin durumu, hiç, karanlıklar içinde kalmış, bir türlü ondan çıkamamış kimsenin durumu gibi olur mu? İşte kâfirlere, işlemekte oldukları çirkinlikler böyle süslü gösterilmiştir."},{"n":123,"t":"İşte böyle, her memlekette günahkârları oranın ileri gelenleri kıldık ki oralarda hilekârlık etsinler. Hâlbuki onlar hilekârlığı ancak kendilerine yaparlar. Ama farkında olmuyorlar."},{"n":124,"t":"Onlara bir âyet geldiği zaman, \"Allah elçilerine verilenin bir benzeri bize de verilinceye kadar asla inanmayacağız\" derler. Allah, elçilik görevini kime vereceğini çok iyi bilir. Suç işleyenlere Allah katından bir aşağılık ve yapmakta oldukları hilekârlık sebebiyle çetin bir azap erişecektir."},{"n":125,"t":"Allah, her kimi doğruya erdirmek isterse, onun göğsünü İslâm’a açar. Kimi de saptırmak isterse, onun da göğsünü göğe çıkıyormuşçasına daraltır, sıkar. Allah, inanmayanlara azap (ve sıkıntıyı) işte böyle verir."},{"n":126,"t":"Bu, Rabbinin dosdoğru yoludur. Şüphesiz düşünüp öğüt alacak bir toplum için âyetleri ayrı ayrı açıkladık."},{"n":127,"t":"Rableri katında selâm yurdu (cennet) onlarındır. Allah, yapmakta oldukları şeylerden dolayı onların dostudur."},{"n":128,"t":"Onların hepsini bir araya toplayacağı gün şöyle diyecektir: \"Ey cin topluluğu! İnsanlardan pek çoğunu saptırıp aranıza kattınız.\" Onların insanlardan olan dostları, \"Ey Rabbimiz! Bizler birbirimizden yararlandık ve bize belirlediğin süremizin sonuna ulaştık\" diyecekler. Allah da diyecek ki: \"Allah’ın diledikleri (affettikleri) hariç, içinde ebedî kalmak üzere duracağınız yer ateştir.\" Ey Muhammed! Şüphesiz senin Rabbin hüküm ve hikmet sahibidir, hakkıyla bilendir."},{"n":129,"t":"İşte biz, kazanmakta oldukları günahlar sebebiyle zalimlerin bir kısmını diğer bir kısmına böyle musallat ederiz."},{"n":130,"t":"(O gün Allah, şöyle diyecektir:) \"Ey cin ve insan topluluğu! İçinizden size âyetlerimi anlatan ve bu gününüzün gelip çatacağı hakkında sizi uyaran peygamberler gelmedi mi?\" Onlar şöyle diyecekler: \"Biz kendi aleyhimize şahitlik ederiz.\" Dünya hayatı onları aldattı ve kâfir olduklarına dair kendi aleyhlerine şahitlik ettiler."},{"n":131,"t":"Bu (peygamberlerin gönderilmesi), Allah’ın, halkları habersizken ülkeleri haksız yere helâk etmeyeceği içindir."},{"n":132,"t":"Herkesin amellerine göre dereceleri vardır. Rabbin onların yaptıklarından habersiz değildir."},{"n":133,"t":"Rabbin her bakımdan sınırsız zengindir, rahmet sahibidir. Sizi başka bir kavmin soyundan getirdiği gibi, dilerse sizi giderir (yok eder) ve sizden sonra da yerinize dilediğini getirir."},{"n":134,"t":"Şüphesiz size va’dedilen şeyler mutlaka gelecektir. Siz bunun önüne geçemezsiniz."},{"n":135,"t":"De ki: \"Ey kavmim! Elinizden geleni yapın. Ben de (görevimi) yapacağım. Ama dünya yurdunun sonucunun kimin olacağını yakında öğreneceksiniz. Şüphesiz, zalimler kurtuluşa eremezler.\""},{"n":136,"t":"Allah’ın yarattığı ekinlerden ve hayvanlardan O’na bir pay ayırdılar ve akıllarınca, \"Şu, Allah için, şu da bizim ortaklarımız (putlarımız) için\" dediler. Ortakları için olan Allah’ınkine eklenmiyor. Allah için olan ise ortaklarınkine ekleniyor.. Ne kötü hükmediyorlar!"},{"n":137,"t":"Yine bunun gibi, Allah’a ortak koşanların çoğuna, koştukları ortaklar, çocuklarını öldürmelerini güzel gösterdi ki; onları helâke sürüklesinler ve dinlerini karıştırıp onları yanıltsınlar. Eğer Rabbin dileseydi, bunu yapamazlardı. Artık sen onları uydurdukları ile baş başa bırak."},{"n":138,"t":"Bir de (asılsız iddialarda bulunarak) dediler ki: \"Bunlar yasaklanmış hayvanlar ve ekinlerdir. Onları bizim dilediklerimizden başkası yiyemez. (Şunlar da) sırtları (binilmesi ve yük yüklemesi) haram edilmiş hayvanlardır.\" Bir kısım hayvanları da keserken üzerlerine Allah’ın adını anmazlar. (Bütün bunları) Allah’a iftira ederek yaparlar. Bu iftiraları sebebiyle Allah onları cezalandıracaktır."},{"n":139,"t":"Bir de dediler ki: \"Şu hayvanların karınlarındaki yavrular (canlı olursa) sırf erkeklerimize aittir. Karılarımıza ise haramdır.\" Eğer ölü olursa, o vakit onda hepsi ortaktırlar. Allah, onların bu tür nitelemelerinin cezasını verecektir. Şüphesiz O, hüküm ve hikmet sahibidir, hakkıyla bilendir."},{"n":140,"t":"Beyinsizlikleri yüzünden bilgisizce çocuklarını öldürenler, Allah’ın kendilerine verdiği rızkı -Allah’a iftira ederek- haram sayanlar, mutlaka ziyan etmişlerdir. Gerçekten onlar sapmışlardır. Doğru yolu bulmuş da değillerdir."},{"n":141,"t":"O, çardaklı-çardaksız olarak bahçeleri, ürünleri, çeşit çeşit hurmalıkları ve ekinleri, zeytini ve narı (her biri) birbirine benzer ve (her biri) birbirinden farklı biçimde yaratandır. Bunlar meyve verince meyvelerinden yiyin. Hasat günü de hakkını (öşürünü) verin, fakat israf etmeyin. Çünkü O, israf edenleri sevmez."},{"n":142,"t":"Yine O, hayvanlardan da irili ufaklı var edendir. Allah’ın size rızık olarak verdiğinden yiyin de şeytanın adımlarına uymayın. Çünkü o, sizin için apaçık bir düşmandır."},{"n":143,"t":"O, (hayvanlardan) sekiz eşi de yaratandır: (Erkek ve dişi olarak) koyundan iki, keçiden de iki. Ey Muhammed! De ki: \"Allah iki erkeği mi haram kıldı, yoksa iki dişiyi mi? Yoksa iki dişinin rahimlerinde bulunan (yavru)ları mı? Eğer doğru söyleyenler iseniz bana bilerek haber verin.\""},{"n":144,"t":"Yine (erkek ve dişi olarak) deveden iki, sığırdan da iki. De ki: \"İki erkeği mi haram kıldı, iki dişiyi mi? Yoksa iki dişinin rahimlerinde bulunan (yavru)ları mı? Yoksa Allah size bunları haram ettiğinde, orada hazır mı idiniz!?\" İnsanları bilgisizce saptırmak için Allah’a karşı yalan uyduran kimseden daha zalim kimdir? Şüphesiz Allah, zalimler topluluğunu doğru yola iletmez."},{"n":145,"t":"De ki: \"Bana vahyolunan Kur’an’da bir kimsenin yiyecekleri arasında leş, akıtılmış kan, domuz eti -ki o şüphesiz necistir- ya da Allah’tan başkası adına kesilmiş bir (murdar) hayvandan başka, haram kılınmış bir şey bulamıyorum. Fakat istismar etmeksizin ve zaruret ölçüsünü aşmaksızın kim bunlardan yeme zorunda kalırsa yiyebilir.\" Şüphesiz Rabbin çok bağışlayandır, çok merhametlidir."},{"n":146,"t":"Yahudilere tırnaklı hayvanların hepsini haram kıldık. Sığır ve koyunların ise, sırtlarında veya bağırsaklarında bulunanlar, ya da kemiklerine karışanlar dışındaki içyağlarını (yine) onlara haram kıldık. İşte böyle, azgınlıkları sebebiyle onları cezalandırdık. Biz elbette doğru söyleyenleriz."},{"n":147,"t":"Eğer seni yalanlarlarsa, de ki: \"Rabbiniz geniş rahmet sahibidir. (Bununla beraber) suçlu bir toplumdan O’nun azabı geri çevrilmez.\""},{"n":148,"t":"Allah’a ortak koşanlar diyecekler ki: \"Eğer Allah dileseydi, biz de ortak koşmazdık, babalarımız da. Hiçbir şeyi de haram kılmazdık.\" Onlardan öncekiler de (peygamberlerini) böyle yalanlamışlardı da sonunda azabımızı tatmışlardı. De ki: \"Sizin (iddialarınızı ispat edecek) bir bilginiz var mı ki onu bize gösteresiniz? Siz ancak kuruntuya uyuyorsunuz ve siz sadece yalan söylüyorsunuz.\""},{"n":149,"t":"De ki: \"En üstün delil yalnızca Allah’ındır. O, dileseydi elbette sizin hepinizi doğru yola iletirdi.\""},{"n":150,"t":"De ki: \"Haydi, Allah şunu haram kıldı\" diye tanıklık yapacak şahitlerinizi getirin. Onlar şahitlik etseler de sen onlarla beraber şahitlik etme. Âyetlerimizi yalanlayanların ve ahirete inanmayanların arzularına uyma. Onlar Rablerine, başka şeyleri denk tutuyorlar."},{"n":151,"t":"(Ey Muhammed!) De ki: \"Gelin, Rabbinizin size haram kıldığı şeyleri okuyayım: O’na hiçbir şeyi ortak koşmayın. Anaya babaya iyi davranın. Fakirlik endişesiyle çocuklarınızı öldürmeyin. Sizi de onları da biz rızıklandırırız. (Zina ve benzeri) çirkinliklere, bunların açığına da gizlisine de yaklaşmayın. Meşrû bir hak karşılığı olmadıkça, Allah’ın haram (dokunulmaz) kıldığı canı öldürmeyin. İşte size Allah bunu emretti ki aklınızı kullanasınız.\""},{"n":152,"t":"Rüşdüne erişinceye kadar yetimin malına ancak en güzel şekilde yaklaşın. Ölçüyü ve tartıyı adaletle tam yapın. Biz herkesi ancak gücünün yettiği kadarıyla sorumlu tutarız. (Birisi hakkında) konuştuğunuz zaman yakınınız bile olsa âdil olun. Allah’a verdiğiniz sözü tutun. İşte bunları Allah size öğüt alasınız diye emretti."},{"n":153,"t":"İşte bu, benim dosdoğru yolum. Artık ona uyun. Başka yollara uymayın. Yoksa o yollar sizi parça parça edip O’nun yolundan ayırır. İşte size bunları Allah sakınasınız diye emretti."},{"n":154,"t":"Sonra iyilik yapanlara nimeti tamamlamak, her şeyi açıklamak, hidayet ve rahmete erdirmek için Mûsâ’ya Kitab’ı (Tevrat’ı) verdik ki, Rablerinin huzuruna varacaklarına iman etsinler."},{"n":155,"t":"Bu (Kur’an) da bizim indirdiğimiz bereket kaynağı bir kitaptır. Artık ona uyun ve Allah’a karşı gelmekten sakının ki size merhamet edilsin."},{"n":"156-157","t":"\"Kitap, yalnız bizden önceki iki topluluğa (yahudilere ve hıristiyanlara) indirildi. Biz onların okumalarından habersiz idik\" demeyesiniz, yahut, \"Eğer bize kitap indirilseydi, biz onlardan daha çok doğru yolda olurduk\" demeyesiniz, diye bu Kur’an’ı indirdik. İşte size Rabbinizden açıkça bir delil, bir hidayet ve bir rahmet geldi. Artık Allah’ın âyetlerini yalanlayan ve (insanları) onlardan çeviren kimseden daha zalim kimdir? İnsanları âyetlerimizden alıkoymaya kalkışanları, yapmakta oldukları engellemeden dolayı azabın en kötüsü ile cezalandıracağız."},{"n":158,"t":"(Ey Muhammed!) Onlar (iman etmek için) ancak kendilerine meleklerin gelmesini veya Rabbinin gelmesini ya da Rabbinin bazı âyetlerinin gelmesini mi gözlüyorlar? Rabbinin âyetlerinden bazısı geldiği gün, daha önce iman etmemiş veya imanında bir hayır kazanmamış olan bir kimseye (o günkü) imanı fayda vermez. De ki: \"Siz bekleyin. Şüphesiz biz de bekliyoruz.\""},{"n":159,"t":"Şu dinlerini parça parça edenler ve kendileri de grup grup ayrılmış olanlar var ya, (senin) onlarla hiçbir ilişiğin yoktur. Onların işi ancak Allah’a kalmıştır. Sonra (O), yapmakta olduklarını kendilerine haber verecektir."},{"n":160,"t":"Kim bir iyilik yaparsa, ona on katı vardır. Kim de bir kötülük yaparsa, o da sadece o kötülüğün misliyle cezalandırılır ve onlara zulmedilmez."},{"n":161,"t":"De ki: \"Şüphesiz Rabbim beni doğru bir yola, dosdoğru bir dine, Hakk’a yönelen İbrahim’in dinine iletti. O, Allah’a ortak koşanlardan değildi.\""},{"n":162,"t":"Ey Muhammed! De ki: \"Şüphesiz benim namazım da, diğer ibadetlerim de, yaşamam da, ölümüm de âlemlerin Rabbi Allah içindir.\""},{"n":163,"t":"\"O’nun hiçbir ortağı yoktur. İşte ben bununla emrolundum. Ben müslümanların ilkiyim.\""},{"n":164,"t":"De ki: \"Her şeyin Rabbi O iken ben başka bir Rab mı arayayım? Herkes günahı yalnız kendi aleyhine kazanır. Hiçbir günahkâr başka bir günahkârın günah yükünü yüklenmez. Sonra dönüşünüz ancak Rabbinizedir. O size, ihtilaf etmekte olduğunuz şeyleri haber verecektir."},{"n":165,"t":"O, sizi yeryüzünde halifeler (oraya hâkim kimseler) yapan, size verdiği nimetler konusunda sizi sınamak için bazınızı bazınıza derece derece üstün kılandır. Şüphesiz Rabbin, cezası çabuk olandır. Şüphe yok ki O, çok bağışlayandır, çok merhamet edendir."}],[{"n":1,"t":"Elif Lâm Mîm Sâd."},{"n":2,"t":"Bu, sana, kendisiyle (insanları) uyarman için ve mü’minlere öğüt olarak indirilmiş bir kitaptır. Artık ondan dolayı göğsünde bir sıkıntı olmasın."},{"n":3,"t":"Rabbinizden size indirilene uyun. Onu bırakıp başka dostlara uymayın. Ne kadar da az öğüt alıyorsunuz!"},{"n":4,"t":"Nice memleketleri helâk ettik. Onlara azabımız gece uykusuna dalmışken, yahut gündüz istirahat hâlinde iken gelmişti."},{"n":5,"t":"Azabımız kendilerine geldiğinde, \"(Biz bunu hak ettik.) Gerçekten biz zalimler olmuştuk\" demekten başka söyleyecekleri kalmamıştı."},{"n":6,"t":"Kendilerine peygamber gönderilenlere mutlaka soracağız. Peygamberlere de elbette soracağız."},{"n":7,"t":"Andolsun, onlara (yaptıklarını) tam bir bilgi ile anlatacağız. Çünkü biz onlardan uzak değiliz."},{"n":8,"t":"O gün amellerin tartılması da haktır. Kimlerin sevabı ağır basarsa, işte onlar kurtuluşa erenlerdir."},{"n":9,"t":"Ama kimlerin sevabı da hafif gelirse, işte onlar âyetlerimize haksızlık etmiş olmaları sebebiyle kendilerini ziyana sokanlardır."},{"n":10,"t":"Andolsun, size yeryüzünde imkân ve iktidar verdik. Sizin için orada birçok geçim imkânları da yarattık. Ama siz ne kadar az şükrediyorsunuz!"},{"n":11,"t":"Andolsun, sizi yarattık. Sonra size şekil verdik. Sonra da meleklere, \"Âdem için saygı ile eğilin\" dedik. İblis’ten başka hepsi saygı ile eğildiler. O, saygı ile eğilenlerden olmadı."},{"n":12,"t":"Allah, \"Sana emrettiğim zaman seni saygı ile eğilmekten ne alıkoydu?\" dedi. (O da) \"Ben ondan hayırlıyım. Çünkü beni ateşten yarattın. Onu ise çamurdan yarattın\" dedi."},{"n":13,"t":"Allah, \"Şimdi in aşağı oradan. Çünkü senin orada büyüklük taslamak haddine değil! Hemen çık! Çünkü sen aşağılıklardansın\" dedi."},{"n":14,"t":"Şeytan dedi ki: \"(Öyle ise) bana insanların tekrar diriltilecekleri güne kadar süre ver.\""},{"n":15,"t":"Allah da, \"Sen süre verilenlerdensin\" dedi."},{"n":16,"t":"Şeytan dedi ki: \"(Öyle ise) beni azdırmana karşılık, yemin ederim ki, ben de onları saptırmak için senin dosdoğru yolunun üzerinde elbette oturacağım.\""},{"n":17,"t":"\"Sonra (pusu kurup) onlara önlerinden, arkalarından, sağlarından ve sollarından sokulacağım ve sen onların çoğunu şükreden (kimse)ler bulamayacaksın.\""},{"n":18,"t":"Allah, dedi ki: \"Yerilmiş ve kovulmuş olarak çık oradan. Andolsun, onlardan sana kim uyarsa sizin, hepinizi cehenneme doldururum.\""},{"n":19,"t":"\"Ey Âdem! Sen ve eşin cennette kalın. Dilediğiniz yerden yiyin. Fakat şu ağaca yaklaşmayın. Yoksa zalimlerden olursunuz.\""},{"n":20,"t":"Derken şeytan, kendilerinden gizlenmiş olan avret yerlerini onlara açmak için kendilerine vesvese verdi ve dedi ki: \"Rabbiniz size bu ağacı ancak, melek olmayasınız, ya da (cennette) ebedî kalacaklardan olmayasınız diye yasakladı.\""},{"n":21,"t":"\"Şüphesiz ben size öğüt verenlerdenim\" diye de onlara yemin etti."},{"n":22,"t":"Bu sûretle onları kandırarak yasağa sürükledi. Ağaçtan tattıklarında kendilerine avret yerleri göründü. Derhal üzerlerini cennet yapraklarıyla örtmeye başladılar. Rab’leri onlara, \"Ben size bu ağacı yasaklamadım mı? Şeytan size apaçık bir düşmandır, demedim mi?\" diye seslendi."},{"n":23,"t":"Dediler ki: \"Rabbimiz! Biz kendimize zulüm ettik. Eğer bizi bağışlamaz ve bize acımazsan mutlaka ziyan edenlerden oluruz.\""},{"n":24,"t":"Allah, dedi ki: \"Birbirinizin düşmanı olarak inin (oradan). Size yeryüzünde bir zamana kadar yerleşme ve yararlanma vardır.\""},{"n":25,"t":"Allah, dedi ki: \"Orada yaşayacaksınız, orada öleceksiniz ve oradan (mahşere) çıkarılacaksınız.\""},{"n":26,"t":"Ey Âdemoğulları! Size avret yerlerinizi örtecek giysi ve süslenecek elbise verdik. Takva (Allah’a karşı gelmekten sakınma) elbisesi var ya, işte o daha hayırlıdır. Bu (giysiler), Allah’ın rahmetinin alametlerindendir. Belki öğüt alırlar (diye onları insanlara verdik)."},{"n":27,"t":"Ey Âdemoğulları! Avret yerlerini kendilerine açmak için, elbiselerini soyarak ana babanızı cennetten çıkardığı gibi, şeytan sizi de saptırmasın. Çünkü o ve kabilesi, onları göremeyeceğiniz yerden sizi görürler. Şüphesiz biz, şeytanları, iman etmeyenlerin dostları kılmışızdır."},{"n":28,"t":"Çirkin bir iş işledikleri vakit, \"Biz atalarımızı bunun üzerinde bulduk, Allah da bize bunu emretti\" derler. De ki: \"Şüphesiz, Allah çirkin işleri emretmez. Siz bilmediğiniz şeyleri Allah’ın üzerine mi atıyorsunuz?\""},{"n":29,"t":"De ki: \"Rabbim adaleti emretti. Her secde yerinde yüzlerinizi (O’na) doğrultun. Dini Allah’a has kılarak O’na ibadet edin. Sizi başlangıçta yarattığı gibi (yine O’na) döneceksiniz.\""},{"n":30,"t":"Allah, bir kısmına hidayet etti, bir kısmına da sapıklık lâyık oldu. Çünkü onlar Allah’ı bırakıp şeytanları dost edinmişlerdi. Kendilerinin de doğru yolda olduklarını sanıyorlardı."},{"n":31,"t":"Ey Âdemoğulları! Her mescitte ziynetinizi takının (güzel ve temiz giyinin). Yiyin için fakat israf etmeyin. Çünkü O, israf edenleri sevmez."},{"n":32,"t":"De ki: \"Allah’ın, kulları için yarattığı zîneti ve temiz rızkı kim haram kılmış?\" De ki: \"Bunlar, dünya hayatında mü’minler içindir. Kıyamet gününde ise yalnız onlara özgüdür. İşte bilen bir topluluk için âyetleri, ayrı ayrı açıklıyoruz.\""},{"n":33,"t":"De ki: \"Rabbim ancak, açık ve gizli çirkin işleri, günahı, haksız saldırıyı, hakkında hiçbir delil indirmediği herhangi bir şeyi Allah’a ortak koşmanızı ve Allah’a karşı bilmediğiniz şeyleri söylemenizi haram kılmıştır.\""},{"n":34,"t":"Her milletin belli bir eceli vardır. Onların eceli geldi mi, ne bir an geri kalabilirler, ne de öne geçebilirler."},{"n":35,"t":"Ey Âdemoğulları! İçinizden size benim âyetlerimi anlatan Peygamberler gelir de her kim Allah’a karşı gelmekten sakınır ve hâlini düzeltirse, artık onlara korku yoktur. Onlar üzülecek de değillerdir."},{"n":36,"t":"Âyetlerimizi yalanlayanlar ve onlara uymayı kibirlerine yediremeyenlere gelince, işte onlar cehennemliklerdir. Onlar orada ebedî kalacaklardır."},{"n":37,"t":"Kim, Allah’a karşı yalan uyduran veya O’nun âyetlerini yalanlayanlardan daha zalimdir? İşte onlara kitaptan (kendileri için yazılmış ömür ve rızıklardan) payları erişir. Sonunda kendilerine melek elçilerimiz, canlarını almak için geldiğinde, \"Hani Allah’ı bırakıp tapınmakta olduğunuz şeyler nerede?\" derler. Onlar da, \"Bizi yüzüstü bırakıp kayboldular\" derler ve kâfir olduklarına dair kendi aleyhlerine şahitlik ederler."},{"n":38,"t":"Allah, şöyle der: \"Sizden önce gelip geçmiş cin ve insan toplulukları ile birlikte ateşe girin.\" Her topluluk (arkasından gidip sapıklığa düştüğü) yoldaşına lânet eder. Nihayet hepsi orada toplandığı zaman peşlerinden gidenler, kendilerine öncülük edenler için, \"Ey Rabbimiz! Şunlar bizi saptırdılar. Onlara bir kat daha ateş azabı ver\" derler. Allah, der ki: \"Her biriniz için bir kat daha fazla azap vardır. Fakat bilmiyorsunuz.\""},{"n":39,"t":"Öncekiler sonrakilere, \"Sizin bize karşı bir üstünlüğünüz yoktur. Artık kazanmış olduğunuz şeylere karşılık, azabı tadın\" derler."},{"n":40,"t":"Âyetlerimizi yalanlayanlar ve o âyetlere uymayı kibirlerine yediremeyenler var ya, onlara göklerin kapıları açılmaz. Onlar, deve iğne deliğinden geçinceye kadar cennete de giremezler! Biz suçluları işte böyle cezalandırırız."},{"n":41,"t":"Onlar için cehennem ateşinden döşek, üstlerinde de cehennem ateşinden örtüler var. İşte biz zalimleri böyle cezalandırırız."},{"n":42,"t":"İman edip salih ameller işleyenlere gelince -ki biz kişiye ancak gücünün yettiğini yükleriz- işte onlar cennetliklerdir. Onlar orada ebedî kalıcıdırlar."},{"n":43,"t":"Biz onların kalplerinde kin namına ne varsa söküp attık. Altlarından da ırmaklar akar. \"Hamd, bizi buna eriştiren Allah’a mahsustur. Eğer Allah’ın bizi eriştirmesi olmasaydı, biz hidayete ermiş olamazdık. Andolsun, Rabbimizin peygamberleri bize hakkı getirmişler\" derler. Onlara, \"İşte yaptığınız (iyi işler) sayesinde kendisine varis kılındığınız cennet!\" diye seslenilir."},{"n":44,"t":"Cennetlikler cehennemliklere, \"Rabbimizin bize va’dettiğini biz gerçek bulduk. Siz de Rabbinizin va’dettiğini gerçek buldunuz mu?\" diye seslenirler. Onlar, \"Evet\" derler. O zaman aralarında bir duyurucu, \"Allah’ın lâneti zalimlere!\" diye seslenir."},{"n":45,"t":"Onlar Allah yolundan alıkoyan ve onu, eğri ve çelişkili göstermek isteyenlerdir. Onlar ahireti de inkâr edenlerdir."},{"n":46,"t":"İkisi (cennet ve cehennem) arasında bir sur, A’râf üzerinde de birtakım adamlar vardır. Cennet ve cehennemliklerin hepsini simalarından tanımaktadırlar. Cennetliklere, \"Selâm olsun size!\" diye seslenirler. Onlar henüz cennete girmemişlerdir, ama bunu ummaktadırlar."},{"n":47,"t":"Gözleri cehennemlikler tarafına çevrildiği zaman, \"Ey Rabbimiz! Bizi zalim toplumla beraber kılma\" derler."},{"n":48,"t":"A’râftakiler, simalarından tanıdıkları birtakım adamlara da seslenir ve şöyle derler: \"Ne çokluğunuz, ne de taslamakta olduğunuz kibir size bir yarar sağladı!\""},{"n":49,"t":"\"Sizin, ‘Allah bunları rahmete erdirmez’ diye yemin ettikleriniz şunlar mı?\" (Sonra cennetliklere dönerek) \"Haydi, girin cennete. Size korku yok. Siz üzülecek de değilsiniz\" derler."},{"n":50,"t":"Cehennemlikler de cennetliklere, \"Ne olur, sudan veya Allah’ın size verdiği rızıktan biraz da bizim üzerimize akıtın\" diye çağrışırlar. Onlar, \"Şüphesiz, Allah bunları kâfirlere haram kılmıştır\" derler."},{"n":51,"t":"Onlar dinlerini oyun ve eğlence edinmişler ve dünya hayatı da kendilerini aldatmıştı. İşte onlar bu günlerine kavuşacaklarını nasıl unuttular ve âyetlerimizi nasıl inkâr edip durdularsa, biz de onları bugün öyle unuturuz."},{"n":52,"t":"Andolsun biz onlara, bilerek açıkladığımız bir kitabı, inanan bir toplum için bir yol gösterici ve rahmet olarak getirdik."},{"n":53,"t":"Onlar ise ancak, (\"Görelim bakalım!\" diyerek) Kur’an’ın bildirdiği sonucu (te’vilini) bekliyorlar. Onun bildirdiği sonuç gelip çattığı gün, önceden onu unutmuş olanlar derler ki: \"Gerçekten Rabbimizin peygamberleri hakkı getirmişler. Şimdi bizim için şefaatçılar var mı ki bize şefaat etseler veya (dünyaya) döndürülsek de yaptıklarımızdan başkasını yapsak?\" Gerçekten onlar kendilerine yazık etmişlerdir. (İlâh diye) uydurdukları (putlar) da onları yüzüstü bırakarak uzaklaşıp kaybolmuşlardır."},{"n":54,"t":"Şüphesiz sizin Rabbiniz, gökleri ve yeri altı gün içinde (altı evrede) yaratan ve Arş’a kurulan, geceyi, kendisini durmadan takip eden gündüze katan, güneşi, ayı ve bütün yıldızları da buyruğuna tabi olarak yaratan Allah’tır. Dikkat edin, yaratmak da, emretmek de yalnız O’na mahsustur. Âlemlerin Rabbi olan Allah’ın şanı yücedir."},{"n":55,"t":"Rabbinize alçak gönüllüce ve için için dua edin. Çünkü O, haddi aşanları sevmez."},{"n":56,"t":"Düzene sokulduktan sonra yeryüzünde bozgunculuk yapmayın. Allah’a (azabından) korkarak ve (rahmetini) umarak dua edin. Şüphesiz, Allah’ın rahmeti iyilik edenlere çok yakındır."},{"n":57,"t":"O, rüzgârları rahmetinin önünde müjde olarak gönderendir. Nihayet rüzgârlar ağır bulutları yüklendiği vakit, onları ölü bir belde(yi diriltmek) için sevk ederiz de oraya suyu indiririz. Derken onunla türlü türlü meyveleri çıkarırız. İşte ölüleri de öyle çıkaracağız. Ola ki ibretle düşünürsünüz."},{"n":58,"t":"(Toprağı) iyi ve elverişli beldenin bitkisi, Rabbinin izniyle bol ve bereketli çıkar. (Toprağı) kötü ve elverişsiz olandan ise, faydasız bitkiden başkası çıkmaz. Şükredecek bir toplum için biz âyetleri işte böyle değişik biçimlerde açıklıyoruz."},{"n":59,"t":"Andolsun, Nûh’u kendi kavmine peygamber olarak gönderdik de, \"Ey kavmim! Allah’a kulluk edin. Sizin için O’ndan başka hiçbir ilâh yoktur. Şüphesiz ben sizin adınıza büyük bir günün azabından korkuyorum\" dedi."},{"n":60,"t":"Kavminin ileri gelenleri, \"Biz seni açıkça bir sapıklık içinde görüyoruz\" dediler."},{"n":61,"t":"(Nûh onlara) şöyle dedi: \"Ey kavmim! Bende herhangi bir sapıklık yok. Aksine ben, âlemlerin Rabbi tarafından gönderilmiş bir peygamberim.\""},{"n":62,"t":"\"Ben size Rabbimin vahyettiklerini tebliğ ediyorum ve size nasihat ediyorum. Sizin bilmediğiniz şeyleri de Allah tarafından gelen vahiy ile biliyorum.\""},{"n":63,"t":"Sizi uyarması ve sizin de Allah’a karşı gelmekten sakınıp rahmete ulaşmanız için, içinizden bir adam aracılığı ile Rabbinizden size bir zikir (vahiy ve öğüt) gelmesine şaştınız mı?"},{"n":64,"t":"Derken kavmi onu yalanladı. Biz de onu ve gemide onunla beraber bulunanları kurtardık. Âyetlerimizi yalanlayanları da suda boğduk. Çünkü onlar (vicdanları hakka kapalı) kör bir kavim idiler."},{"n":65,"t":"Âd kavmine de kardeşleri Hûd’u peygamber olarak gönderdik. Onlara, \"Ey kavmim! Allah’a kulluk edin. Sizin için O’ndan başka hiçbir ilâh yoktur. Allah’a karşı gelmekten sakınmaz mısınız?\" dedi."},{"n":66,"t":"Kavminin ileri gelenlerinden inkâr edenler dediler ki: \"Şüphesiz, biz seni akıl kıtlığı içinde görüyoruz. Biz senin mutlaka yalancılardan biri olduğuna inanıyoruz.\""},{"n":67,"t":"Hûd, şöyle dedi: \"Ey kavmim! Bende akıl kıtlığı yok. Aksine ben âlemlerin Rabbi tarafından gönderilmiş bir peygamberim.\""},{"n":68,"t":"\"Rabbimin vahyettiklerini size tebliğ ediyorum. Ben sizin için güvenilir bir nasihatçıyım.\""},{"n":69,"t":"\"Sizi uyarması için içinizden bir adam aracılığıyla Rabbinizden size bir zikir (vahy ve öğüt) gelmesine şaştınız mı? Hatırlayın ki, Allah sizi Nûh kavminden sonra onların yerine getirdi ve sizi yaratılış itibariyle daha güçlü kıldı. Allah’ın nimetlerini hatırlayın ki kurtuluşa eresiniz.\""},{"n":70,"t":"Onlar, \"Sen bize tek Allah’a ibadet edelim, atalarımızın ibadet edegeldiklerini bırakalım diye mi geldin? Eğer doğru söyleyenlerden isen, haydi bizi tehdit ettiğin azabı bize getir\" dediler."},{"n":71,"t":"Hûd, \"Artık size Rabbinizden bir azap ve öfke inmiştir. Allah’ın, haklarında hiçbir delil indirmediği, yalnızca sizin ve babalarınızın uydurduğu birtakım isimler (düzmece tanrılar) hakkında mı benimle tartışıyorsunuz? Öyleyse (başınıza geleceği) bekleyin! Ben de sizinle beraber bekleyenlerdenim!\" dedi."},{"n":72,"t":"Bunun üzerine biz onu ve beraberindekileri tarafımızdan bir rahmetle kurtardık. Âyetlerimizi yalanlayan ve iman etmemiş olanların ise kökünü kestik."},{"n":73,"t":"Semûd kavmine de kardeşleri Salih’i Peygamber olarak gönderdik. Dedi ki: \"Ey kavmim! Allah’a kulluk edin. Sizin için O’ndan başka bir ilâh yoktur. Gerçekten size Rabbinizden (benim peygamber olduğumu gösterecek) açık bir delil geldi. İşte size bir mucize olarak Allah’ın şu devesi.. Bırakın onu da Allah’ın mülkünde yesin, içsin. Sakın ona bir kötülük etmeyin. Yoksa sizi elem dolu bir azap yakalar.\""},{"n":74,"t":"\"Hatırlayın ki Allah Âd kavminden sonra, sizi onların yerine getirdi ve sizi yeryüzünde yerleştirdi. Yerin ovalarında köşkler kuruyor, dağları oyup evler yapıyorsunuz. Artık Allah’ın nimetlerini anın da yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.\""},{"n":75,"t":"Kavminin büyüklük taslayan ileri gelenleri, küçük görülüp ezilen inanmışlara, \"Siz, Salih’in, Rabbi tarafından gönderilmiş bir peygamber olduğunu (sahiden) biliyor musunuz?\" dediler. Onlar da, \"Biz şüphesiz onunla gönderilene inananlarız\" dediler."},{"n":76,"t":"Büyüklük taslayanlar, \"Şüphesiz biz sizin inandığınız şeyi inkâr edenleriz\" dediler."},{"n":77,"t":"Nihayet deveyi kestiler, Rablerinin emrine karşı geldiler ve \"Ey Salih! Sen eğer (dediğin gibi) peygamberlerden isen, haydi bizi tehdit ettiğin azabı getir\" dediler."},{"n":78,"t":"Derken, onları o kuvvetli sarsıntı yakaladı da yurtlarında yüzüstü hareketsiz çöke kaldılar."},{"n":79,"t":"Artık, Salih onlardan yüz çevirdi ve \"Andolsun, ben size Rabbimin vahyettiklerini tebliğ ettim ve size nasihatta bulundum. Fakat siz nasihat edenleri sevmiyorsunuz\" dedi."},{"n":80,"t":"Lût’u da Peygamber olarak gönderdik. Hani o kavmine şöyle demişti: \"Sizden önce âlemlerden hiçbir kimsenin yapmadığı çirkin işi mi yapıyorsunuz?\""},{"n":81,"t":"\"Hakikaten siz kadınları bırakıp, şehvetle erkeklere yaklaşıyorsunuz. Hayır, siz haddi aşan bir toplumsunuz.\""},{"n":82,"t":"Kavminin cevabı ise sadece, \"Çıkarın bunları memleketinizden! Güya onlar kendilerini fazla temiz tutan insanlar!..\" demek oldu."},{"n":83,"t":"Bunun üzerine biz de onu ve karısı dışında aile fertlerini kurtardık. Karısı ise azab içinde kalanlardan oldu."},{"n":84,"t":"Onların üstüne bir azap yağmuru yağdırdık.\" Bak, suçluların akıbeti nasıl oldu."},{"n":85,"t":"Medyen halkına da kardeşleri Şu’ayb’ı peygamber olarak gönderdik. Dedi ki: \"Ey kavmim! Allah’a kulluk edin. Sizin için O’ndan başka hiçbir ilâh yoktur. Rabbinizden size açık bir delil gelmiştir. Artık ölçüyü ve tartıyı tam yapın. İnsanların mallarını eksiltmeyin. Düzene sokulduktan sonra yeryüzünde bozgunculuk etmeyin. İnananlar iseniz bunlar sizin için hayırlıdır.\""},{"n":86,"t":"\"Bir de, tehdit ederek Allah’ın yolundan O’na iman edenleri çevirmek, Allah’ın yolunu eğri ve çelişkili göstermek üzere her yol üstüne oturmayın. Hatırlayın ki, siz az (ve güçsüz) idiniz de O sizi çoğalttı. Bakın, bozguncuların sonu nasıl oldu!?\""},{"n":87,"t":"\"Eğer içinizden bir kısmı benimle gönderilen gerçeğe inanmış, bir kısmı da inanmamışsa, artık Allah aramızda hükmünü verinceye kadar sabredin. O, hüküm verenlerin en hayırlısıdır.\""},{"n":88,"t":"Şu’ayb’ın kavminden büyüklük taslayan ileri gelenler dediler ki: \"Ey Şu’ayb! Andolsun, ya kesinlikle bizim dinimize dönersiniz ya da mutlaka seni ve seninle birlikte inananları memleketimizden çıkarırız.\" Şu’ayb, \"İstemesek de mi?\" dedi."},{"n":89,"t":"\"Allah, bizi sizin dininizden kurtardıktan sonra eğer ona dönersek mutlaka Allah’a karşı yalan uydurmuş oluruz. Rabbimiz Allah’ın dilemesi olmadıkça, sizin dininize dönmemiz bizim için olacak şey değildir. Rabbimiz her şeyi ilmiyle kuşatmıştır. Biz yalnız Allah’a tevekkül ettik. Ey Rabbimiz! Bizimle kavmimiz arasında gerçekle hükmet. Çünkü sen hükmedenlerin en hayırlısısın.\""},{"n":90,"t":"Şu’ayb’ın kavminden inkâr eden ileri gelenler dediler ki: \"(Ey ahali!) Andolsun ki eğer Şu’ayb’a uyarsanız, o takdirde mutlaka siz zarar edenler olursunuz.\""},{"n":91,"t":"Derken, onları o korkunç sarsıntı yakaladı da yurtlarında yüzüstü hareketsiz çöke kaldılar."},{"n":92,"t":"Şu’ayb’ı yalanlayanlar sanki orada hiç yaşamamışlardı. Şu’ayb’ı yalanlayanlar var ya, asıl ziyana uğrayanlar onlar oldu."},{"n":93,"t":"(Şu’ayb) onlardan yüz çevirdi ve dedi ki: \"Ey kavmim! Andolsun, ben size Rabbimin vahyettiklerini ulaştırdım. Size nasihat de ettim. Şimdi ben, inkârcı bir topluluğa nasıl üzülürüm?\""},{"n":94,"t":"Biz hiçbir memlekete bir peygamber göndermedik ki (karşı çıkmaktan vazgeçip) yalvarıp yakarsınlar diye ora halkını yoksulluk ve sıkıntıya uğratmış olmayalım."},{"n":95,"t":"Sonra kötülüğün (sıkıntı ve darlığın) yerine iyiliği (bolluk ve genişliği) getirdik. Nihayet çoğaldılar ve (nankörlük edip): \"Atalarımız da darlığa uğramış ve bolluğa kavuşmuşlardı\" dediler. Biz de, farkında değillerken onları ansızın yakaladık."},{"n":96,"t":"Eğer, o memleketlerin halkları iman etseler ve Allah’a karşı gelmekten sakınsalardı, elbette onların üstüne gökten ve yerden nice bereketler(in kapılarını) açardık. Fakat onlar yalanladılar, biz de kendilerini işledikleri günahlarından dolayı yakalayıverdik."},{"n":97,"t":"Memleketlerin halkları geceleyin uyurken kendilerine azabımızın gelmesinden emin mi oldular?"},{"n":98,"t":"Ya da o memleketlerin halkları kuşluk vakti gülüp oynarken kendilerine azabımızın gelmesinden emin mi oldular?"},{"n":99,"t":"Yoksa Allah’ın tuzağından emin mi oldular? Ziyana uğrayan kavimden başkası Allah’ın tuzağından emin olamaz."},{"n":100,"t":"Önceki sahiplerinden sonra yeryüzüne varis olanlara şu gerçek apaçık belli olmadı mı ki, biz dileseydik onları da (öncekiler gibi) günahları yüzünden cezalandırırdık. Biz onların kalplerini mühürleriz de onlar hakkı işitmezler."},{"n":101,"t":"İşte memleketler! Onların haberlerinden bir kısmını sana anlatıyoruz. Andolsun, peygamberleri onlara apaçık deliller getirmişti. Fakat onlar daha önce yalanladıklarına inanacak değillerdi. Allah, kâfirlerin kalplerini işte böyle mühürler."},{"n":102,"t":"Biz onların çoğunda, sözünde durma diye bir şey bulmadık. Ama gerçekten onların çoklarını yoldan çıkmış kimseler bulduk."},{"n":103,"t":"Sonra onların ardından Mûsâ’yı, apaçık mucizelerimizle Firavun’a ve onun ileri gelen adamlarına peygamber olarak gönderdik de onları (mucizeleri) inkâr ettiler. Bak, bozguncuların sonu nasıl oldu."},{"n":104,"t":"Mûsâ dedi ki: \"Ey Firavun! Şüphesiz ki ben âlemlerin Rabbi tarafından gönderilmiş bir peygamberim.\""},{"n":105,"t":"Bana, Allah’a karşı sadece gerçeği söylemem yaraşır. Ben size Rabbinizden açık bir delil (mucize) getirdim. Artık İsrailoğullarını benimle gönder."},{"n":106,"t":"Firavun, \"Eğer açık bir delil getirdiysen haydi göster onu bakalım, şayet doğru söyleyenlerden isen\" dedi."},{"n":107,"t":"Bunun üzerine Mûsâ, asasını yere attı. Bir de ne görsünler, apaçık bir ejderha."},{"n":108,"t":"Elini (koynundan) çıkardı. Bir de ne görsünler o, bakanlar için, bembeyaz olmuş."},{"n":109,"t":"Firavun’un kavminden ileri gelenler, dediler ki: \"Şüphesiz bu adam usta bir sihirbazdır.\""},{"n":110,"t":"\"Sizi yerinizden çıkarmak istiyor.\" Firavun, ileri gelenlere, \"Öyle ise siz ne düşünüyorsunuz?\" dedi."},{"n":111,"t":"Onlar şöyle dediler: \"Mûsâ’yı ve kardeşini (bir süre) beklet (haklarında bir işlem yapma) ve şehirlere toplayıcılar yolla.\""},{"n":112,"t":"\"Bütün usta sihirbazları (toplayıp) sana getirsinler.\""},{"n":113,"t":"Sihirbazlar Firavun’a geldiler. \"Galip gelenler biz olursak mutlaka bize bir mükâfat vardır, değil mi?\" dediler."},{"n":114,"t":"Firavun, \"Evet. Üstelik siz (ücretle de kalmayacaksınız) mutlaka benim en yakınlarımdan olacaksınız\" dedi."},{"n":115,"t":"(Sihirbazlar), \"Ey Mûsâ! Ya önce sen at, ya da önce atanlar biz olalım\" dediler."},{"n":116,"t":"(Mûsâ), \"Siz atın\" dedi. Bunun üzerine onlar (ellerindekini) atınca insanların gözlerini büyülediler ve onlara korku saldılar. Büyük bir sihir yaptılar."},{"n":117,"t":"Biz de Mûsâ’ya, \"Elindeki değneğini at\" diye vahyettik. Bir de ne görsünler o, onların uydurduklarını yakalayıp yutuyor."},{"n":118,"t":"Böylece hak yerini buldu ve onların yapmış oldukları şeylerin hepsi boşa çıktı."},{"n":119,"t":"Artık orada yenilmişler ve küçük düşmüşlerdi."},{"n":120,"t":"Sihirbazlar ise secdeye kapandılar."},{"n":121,"t":"\"Âlemlerin Rabbine iman ettik\" dediler."},{"n":122,"t":"\"Mûsâ ve Hârûn’un Rabbine.\""},{"n":123,"t":"Firavun, \"Ben size izin vermeden ona iman ettiniz ha!\" dedi. \"Şüphesiz bu halkını oradan çıkarmak için şehirde kurduğunuz bir tuzaktır. Göreceksiniz!\""},{"n":124,"t":"\"Mutlaka sizin ellerinizi ve ayaklarınızı çaprazlama keseceğim, sonra da (ibret olsun diye) sizin tümünüzü elbette asacağım.\""},{"n":125,"t":"Dediler ki: \"Biz mutlaka Rabbimize döneceğiz.\""},{"n":126,"t":"\"Sen sırf, Rabbimizin âyetleri bize geldiğinde iman ettiğimiz için bize hınç duyuyorsun. Ey Rabbimiz! Üzerimize sabır yağdır ve müslüman olarak bizim canımızı al.\""},{"n":127,"t":"Firavun’un kavminden ileri gelenler dediler ki: \"Sen (sihirbazları cezalandıracaksın da) Mûsâ’yı ve kavmini, bu ülkede fesat çıkarsınlar, seni ve ilâhlarını terk etsinler diye bırakacak mısın?\" Firavun, \"Biz onların oğullarını öldüreceğiz, kadınlarını sağ bırakacağız. Biz onların üzerinde ezici bir güce sahibiz?\" dedi."},{"n":128,"t":"Mûsâ, kavmine, \"Allah’tan yardım isteyin ve sabredin. Şüphesiz yeryüzü Allah’ındır. Ona, kullarından dilediğini mirasçı kılar. Sonuç Allah’a karşı gelmekten sakınanlarındır\" dedi."},{"n":129,"t":"Dediler ki: \"Sen bize gelmeden önce de bize işkence edildi, geldikten sonra da.\" Mûsâ, \"Umulur ki, Rabbiniz düşmanınızı helâk edecek ve sizi bu yerde (Mısır’da) egemen kılıp, nasıl davranacağınıza bakacaktır\" dedi."},{"n":130,"t":"Andolsun biz, Firavun ailesini, öğüt alsınlar diye yıllarca süren kıtlık ve ürün eksikliği ile cezalandırdık."},{"n":131,"t":"Fakat onlara iyilik geldiği zaman, \"Bu bizimdir, (biz çalışıp kazandık)\" derler. Eğer başlarına bir kötülük gelirse, Mûsâ ve beraberindekilerin uğursuzluğuna yorarlardı. İyi bilin ki, onların uğursuzluk sebebi ancak Allah katında (yazılı)dır. Fakat çokları bilmezler."},{"n":132,"t":"Dediler ki: \"Bizi büyülemek için her ne getirirsen getir, biz sana inanacak değiliz.\""},{"n":133,"t":"Biz de, her biri ayrı ayrı birer mucize olmak üzere başlarına tufan, çekirge, ürün güvesi (haşarat), kurbağalar ve kan gönderdik. (Hiçbirinden ders almadılar.) Büyüklük tasladılar ve suçlu bir kavim oldular."},{"n":134,"t":"Üzerlerine azap çökünce, \"Ey Mûsâ! Rabbinin sana verdiği söz uyarınca bizim için dua et. Eğer azabı üzerimizden kaldırırsan, mutlaka sana inanacağız ve İsrailoğullarını seninle birlikte elbette göndereceğiz\" dediler."},{"n":135,"t":"Fakat erişecekleri bir süreye kadar biz azabı üzerlerinden kaldırınca hemen yeminlerini bozarlar."},{"n":136,"t":"Bu yüzden onlardan intikam aldık. Âyetlerimizi yalanlamaları ve onları umursamamaları sebebiyle kendilerini denizde boğduk."},{"n":137,"t":"Hor görülüp ezilmekte olan kavmi (İsrailoğullarını), toprağına bolluk ve bereket verdiğimiz yerin doğu ve batı taraflarına mirasçı kıldık. Rabbinin İsrailoğullarına verdiği güzel söz, onların sabretmeleri karşılığında gerçekleşti. Firavun ve kavminin yaptıklarını ve (özenle kurup) yükselttiklerini yerle bir ettik."},{"n":138,"t":"İsrailoğullarını denizden geçirdik. Derken, kendilerine ait putlara tapan bir kavme rastladılar. İsrailoğulları, \"Ey Mûsâ! Onların kendilerine ait ilâhları (putları) olduğu gibi sen de bize ait bir ilâh yapsana\" dediler. Mûsa şöyle dedi: \"Şüphesiz siz cahillik eden bir kavimsiniz.\""},{"n":139,"t":"Şüphesiz bunların (din diye) içinde bulundukları şey yok olmaya mahkûmdur. Yapmakta olduklarının hepsi batıldır.\""},{"n":140,"t":"\"Sizi âlemlere üstün kılmış iken, Allah’tan başka ilâh mı araştırayım size?\""},{"n":141,"t":"Hani sizi Firavun ailesinden kurtarmıştık. Onlar size en kötü işkenceyi uyguluyorlardı. Oğullarınızı öldürüyor, kadınlarınızı sağ bırakıyorlardı. Bunda size Rabbiniz tarafından büyük bir imtihan vardı."},{"n":142,"t":"Mûsâ’ya otuz gece süre belirledik, buna on (gece) daha kattık. Böylece Rabbinin belirlediği vakit kırk geceye tamamlandı. Mûsâ, kardeşi Hârûn’a, \"Kavmim arasında benim yerime geç ve yapıcı ol. Sakın bozguncuların yoluna uyma\" dedi."},{"n":143,"t":"Mûsâ, belirlediğimiz yere (Tûr’a) gelip Rabbi de ona konuşunca, \"Rabbim! Bana (kendini) göster, sana bakayım\" dedi. Allah da, \"Beni (dünyada) katiyen göremezsin. Fakat (şu) dağa bak, eğer o yerinde durursa sen de beni görebilirsin.\" dedi. Rabbi, dağa tecelli edince onu darmadağın ediverdi. Mûsâ da baygın düştü. Ayılınca, \"Seni eksikliklerden uzak tutarım Allah’ım! Sana tövbe ettim. Ben inananların ilkiyim\" dedi."},{"n":144,"t":"(Allah) \"Ey Mûsâ! Vahiylerim ve konuşmamla seni insanlar üzerine seçkin kıldım. Öyleyse sana verdiğimi al ve şükredenlerden ol\" dedi."},{"n":145,"t":"Mûsâ için, Tevrat levhalarında her şeye dair bir öğüt ve her şeyin bir açıklamasını yazdık ve ona şöyle dedik: \"Şimdi onları kuvvetle tut, kavmine de emret. Onları en güzeliyle alsınlar (uygulasınlar). Yakında size fasıkların yurdunu göstereceğim.\""},{"n":146,"t":"Yeryüzünde haksız yere büyüklük taslayanları âyetlerimden uzaklaştıracağım. (Onlar) her âyeti görseler de ona iman etmezler. Doğru yolu görseler onu yol edinmezler. Ama sapıklık yolunu görseler onu (hemen) yol edinirler. Bu, onların, âyetlerimizi yalanlamaları ve onlardan hep gafil olmaları sebebiyledir."},{"n":147,"t":"Âyetlerimizi ve ahirete kavuşmayı yalanlayanların amelleri boşa çıkmıştır. Onlar ancak yapmakta olduklarının cezasını çekerler."},{"n":148,"t":"Mûsâ’nın kavmi onun (Tur’a gitmesinin) ardından, ziynet eşyalarından, böğürmesi olan bir buzağı heykeli (yaparak ilâh) edindiler. Onun kendileriyle konuşmadığını ve onlara hiçbir yol göstermediğini görmediler mi? (Böyle iken) onu (ilâh) edindiler de zalim kimseler oldular."},{"n":149,"t":"İsrailoğulları (yaptıklarına) pişman olup, gerçekten sapmış olduklarını görünce, \"Eğer Rabbimiz bize acımaz ve bizi bağışlamazsa, mutlaka ziyana uğrayanlardan oluruz\" dediler."},{"n":150,"t":"Mûsâ, kavmine kızgın ve üzgün olarak döndüğünde, \"Benden sonra arkamdan ne kötü işler yaptınız! Rabbinizin emrini beklemeyip acele mi ettiniz?\" dedi. (Öfkesinden) levhaları attı ve kardeşinin saçından tuttu, onu kendine doğru çekmeye başladı. (Kardeşi) \"Ey anam oğlu\" dedi, \"Kavim beni güçsüz buldu. Az kalsın beni öldürüyorlardı. Sen de bana böyle davranarak düşmanları sevindirme. Beni o zalimler topluluğu ile bir tutma.\""},{"n":151,"t":"(Mûsâ), \"Ey Rabbim! Beni ve kardeşimi bağışla. Bizi kendi rahmetine sok. Sen, merhametlilerin en merhametlisisin\" dedi."},{"n":152,"t":"Buzağıyı ilâh edinenlere mutlaka (ahirette) Rablerinden bir gazab, dünya hayatında ise bir zillet erişecektir. İşte biz iftiracıları böyle cezalandırırız."},{"n":153,"t":"Kötülükleri işleyip de sonra ardından tövbe edenler ile iman(larında sebat) edenlere gelince şüphe yok ki, Rabbin ondan (tövbeden) sonra elbette çok bağışlayandır, çok merhamet edendir."},{"n":154,"t":"Mûsâ’nın öfkesi dinince (attığı) levhaları aldı. Onların yazısında Rableri için korku duyanlara bir hidayet ve bir rahmet vardı."},{"n":155,"t":"Mûsâ, kavminden, belirlediğimiz yere gitmek için yetmiş adam seçti. Onları sarsıntı yakalayınca (bayıldılar). Mûsâ, \"Ey Rabbim! Dileseydin onları da beni de bundan önce helâk ederdin. Şimdi içimizden birtakım beyinsizlerin işledikleri günah sebebiyle bizi helâk mı edeceksin? Bu, sırf senin bir imtihanındır. Onunla dilediğin kimseyi saptırırsın, dilediğini de doğruya iletirsin. Sen, bizim velimizsin. Artık bizi bağışla ve bize acı. Sen, bağışlayanların en hayırlısısın\" dedi."},{"n":156,"t":"\"Bizim için bu dünyada da bir iyilik yaz, ahirette de. Çünkü biz sana varan doğru yola yöneldik.\" Allah, şöyle dedi: \"Azabım var ya, dilediğim kimseyi ona uğratırım. Rahmetim ise her şeyi kapsamıştır. Onu, bana karşı gelmekten sakınanlara, zekâtı verenlere ve âyetlerimize inananlara yazacağım.\""},{"n":157,"t":"Onlar, yanlarındaki Tevrat’ta ve İncil’de yazılı buldukları Resûle, o ümmî peygambere uyan kimselerdir. O, onlara iyiliği emreder, onları kötülükten alıkoyar. Onlara iyi ve temiz şeyleri helâl, kötü ve pis şeyleri haram kılar. Üzerlerindeki ağır yükleri ve zincirleri kaldırır. Ona iman edenler, ona saygı gösterenler, ona yardım edenler ve ona indirilen nura (Kur’an’a) uyanlar var ya, işte onlar kurtuluşa erenlerdir."},{"n":158,"t":"(Ey Muhammed!) De ki: \"Ey insanlar! Şüphesiz ben, yer ve göklerin hükümranlığı kendisine ait olan Allah’ın hepinize gönderdiği peygamberiyim. O’ndan başka hiçbir ilâh yoktur. O, diriltir ve öldürür. O hâlde, Allah’a ve O’nun sözlerine inanan Resûlüne, o ümmî peygambere iman edin ve ona uyun ki doğru yolu bulasınız.\""},{"n":159,"t":"Mûsâ’nın kavminden (insanları) hak ile doğru yola ileten ve onunla adaletli davranan bir topluluk da vardı."},{"n":160,"t":"Biz onları on iki kabile hâlinde topluluklara ayırdık. (Tîh sahrasında susuzluktan sıkılan) kavmi Mûsâ’dan su istediğinde biz ona, \"Asânı taşa vur\" diye vahyettik. (Vurunca) taştan on iki pınar fışkırdı. Herkes (kendi) su içeceği yeri bildi. Üzerlerine bulutu da gölgelik yaptık ve onlara kudret helvası ve bıldırcın indirdik. \"Size rızık olarak verdiğimiz şeylerin iyi ve temiz olanlarından yiyin\" (dedik). Onlar bize zulmetmediler, fakat kendi nefislerine zulmediyorlardı."},{"n":161,"t":"O zaman onlara denilmişti ki: \"Şu memlekete yerleşin. Orada dilediğiniz gibi yiyin ve ‘Hıtta (Ya Rabbi, bizi affet)’ deyin. Kentin kapısından eğilerek tevazu ile girin ki biz de sizin hatalarınızı bağışlayalım. İyilik edenlere daha da fazlasını vereceğiz.\""},{"n":162,"t":"Onlardan zulmedenler hemen sözü, kendilerine söylenenden başka şekle soktular. Biz de zulmetmelerine karşılık üzerlerine gökten bir azab gönderdik."},{"n":163,"t":"(Ey Muhammed!) Onlara, deniz kıyısında bulunan kent halkının durumunu sor. Hani onlar Cumartesi (yasağı) konusunda haddi aşıyorlardı. Zira tatil yaptıkları Cumartesi günü balıklar onlara akın akın geliyor, tatil yapmadıkları (diğer) günlerde ise gelmiyorlardı. İşte onları yoldan çıkmaları sebebiyle böyle imtihan ediyorduk."},{"n":164,"t":"Hani onlardan bir topluluk demişti ki: \"Siz, Allah’ın helâk edeceği veya şiddetli bir azaba uğratacağı bir kavme ne diye (boş yere) öğüt veriyorsunuz?\" Onlar da, \"Rabbinize bir mazeret beyan etmek için, bir de belki Allah’a karşı gelmekten sakınırlar diye (öğüt veriyoruz)\" demişlerdi."},{"n":165,"t":"Onlar kendilerine hatırlatılanı unutunca, biz de kötülükten alıkoymaya çalışanları kurtardık. Zulmedenleri yoldan çıkmaları sebebiyle, şiddetli bir azapla yakaladık."},{"n":166,"t":"Yasaklandıkları şeylerden vazgeçmeye yanaşmayınca da onlara \"aşağılık maymunlar olun\" dedik."},{"n":167,"t":"Hani Rabbin, elbette kıyamet gününe kadar onlara azabın en kötüsünü tattıracak kimseleri göndereceğini bildirmişti. Şüphesiz Rabbin, elbette cezayı çabuk verendir. Şüphesiz O, çok bağışlayandır, çok merhamet edendir."},{"n":168,"t":"Biz onları yeryüzünde parça parça topluluklara ayırdık. Onlardan iyi kimseler vardır. İçlerinden öyle olmayanları da vardı. Belki dönüş yaparlar diye de onları güzellikler ve kötülükler ile sınadık."},{"n":169,"t":"Derken, onların ardından yerlerine Kitab’a (Tevrat’a) varis olan (kötü) bir nesil geldi. Şu geçici dünyanın değersiz malını alır ve \"(nasıl olsa) biz bağışlanacağız\" derlerdi. Kendilerine benzeri bir mal gelse onu da alırlar. Allah hakkında, gerçek dışında bir şey söylemeyeceklerine dair onlardan Kitap’ta söz alınmamış mıydı? Onun içindekileri okumamışlar mıydı? Hâlbuki, Allah’a karşı gelmekten sakınanlar için ahiret yurdu daha hayırlıdır. Hiç düşünmüyor musunuz?"},{"n":170,"t":"Kitab’a sımsıkı sarılanlara ve namazı dosdoğru kılanlara gelince, şüphesiz biz, iyiliğe çalışan (erdemli) kimselerin mükâfatını zayi etmeyiz."},{"n":171,"t":"Hani dağı sanki bir gölgelikmiş gibi onların üstüne kaldırmıştık da üzerlerine düşecek sanmışlardı. (Onlara:) \"Size verdiğimiz Kitab’a sımsıkı sarılın ve onun içindekileri hatırlayın ki, Allah’a karşı gelmekten sakınasınız\" demiştik."},{"n":172,"t":"Hani Rabbin (ezelde) Âdemoğullarının sulplerinden zürriyetlerini almış, onları kendilerine karşı şahit tutarak, \"Ben sizin Rabbiniz değil miyim?\" demişti. Onlar da, \"Evet, şahit olduk (ki Rabbimizsin)\" demişlerdi. Böyle yapmamız kıyamet günü, \"Biz bundan habersizdik\" dememeniz içindir."},{"n":173,"t":"Yahut, \"Bizden önce babalarımız Allah’a ortak koşmuşlar. Biz onlardan sonra gelen bir nesiliz. Şimdi batılcıların işlediği yüzünden bizi helâk mı edeceksin?\" dememeniz içindir."},{"n":174,"t":"Hakka dönsünler diye işte âyetleri böylece ayrı ayrı açıklıyoruz."},{"n":175,"t":"Kendisine âyetlerimizi verdiğimiz hâlde, onlardan sıyrılıp da şeytanın kendisini peşine taktığı, bu yüzden de azgınlardan olan kimsenin haberini onlara anlat."},{"n":176,"t":"Dileseydik o âyetlerle onu elbette yüceltirdik. Fakat o, dünyaya saplanıp kaldı da kendi heva ve hevesine uydu. Onun durumu köpeğin durumu gibidir: Üzerine varsan da dilini sarkıtıp solur; kendi hâline bıraksan da dilini sarkıtıp solur. İşte bu, âyetlerimizi yalanlayan toplumun durumudur. Şimdi onlara bu olayları anlat ki düşünsünler."},{"n":177,"t":"Âyetlerimizi yalan sayan ve ancak kendilerine zulmeden bir kavmin durumu ne kötüdür!"},{"n":178,"t":"Allah, kimi doğru yola iletirse, odur doğru yolu bulan. Kimleri de saptırırsa, işte onlar, ziyana uğrayanların ta kendileridir."},{"n":179,"t":"Andolsun biz, cinler ve insanlardan, kalpleri olup da bunlarla anlamayan, gözleri olup da bunlarla görmeyen, kulakları olup da bunlarla işitmeyen birçoklarını cehennem için var ettik. İşte bunlar hayvanlar gibi, hatta daha da aşağıdadırlar. İşte bunlar gafillerin ta kendileridir."},{"n":180,"t":"En güzel isimler Allah’ındır. O’na o güzel isimleriyle dua edin ve O’nun isimleri hakkında gerçeği çarpıtanları bırakın. Onlar yaptıklarının cezasına çarptırılacaklardır."},{"n":181,"t":"Yarattıklarımızdan, hakka sarılarak doğru yolu gösteren ve hak ile adaleti gerçekleştiren bir topluluk vardır."},{"n":182,"t":"Âyetlerimizi yalanlayanlara gelince, biz onları bilemeyecekleri bir yerden yavaş yavaş felakete götüreceğiz."},{"n":183,"t":"Ben onlara mühlet veririm. Şüphesiz benim tuzağım çetindir."},{"n":184,"t":"Onlar düşünmediler mi ki (çok iyi tanıdıkları, kendileriyle iç içe yaşamış olan) arkadaşlarında (Peygamber’de) delilikten eser yoktur. O, ancak apaçık bir uyarıcıdır."},{"n":185,"t":"Onlar göklerdeki ve yerdeki sınırsız hükümranlık ve nizama, Allah’ın yarattığı her şeye, ecellerinin yaklaşmış olabileceğine hiç bakmadılar mı? Peki, bundan sonra artık hangi söze inanacaklar?"},{"n":186,"t":"Allah, kimi saptırırsa artık onu doğru yola iletecek kimse yoktur. Allah, onları azgınlıkları içinde bırakır, bocalayıp dururlar."},{"n":187,"t":"Sana kıyametin ne zaman kopacağını soruyorlar. De ki: \"Onun bilgisi ancak Rabbimin katındadır. Onu vaktinde ancak O (Allah) ortaya çıkaracaktır. O göklere de, yere de ağır basmıştır. O, size ancak ansızın gelecektir.\" Sanki senin ondan haberin varmış gibi sana soruyorlar. De ki: \"Onun bilgisi sadece Allah katındadır. Fakat insanların çoğu bilmiyorlar.\""},{"n":188,"t":"De ki: \"Allah dilemedikçe ben kendime bir zarar verme ve bir fayda sağlama gücüne sahip değilim. Eğer ben gaybı biliyor olsaydım, daha çok hayır elde etmek isterdim ve bana kötülük dokunmazdı. Ben inanan bir kavim için sadece bir uyarıcı ve bir müjdeciyim.\""},{"n":189,"t":"Allah, sizi bir tek nefisten yaratan ve kendisi ile huzur bulsun diye eşini de ondan var edendir. (İnsan) eşiyle birleşince eşi hafif bir yük yüklenir (gebe kalır) ve (bir müddet) onu taşır. Gebeliği ağırlaşınca her ikisi de Rableri Allah’a, \"Eğer bize iyi ve sağlıklı bir çocuk verirsen, elbette şükredenlerden olacağız\" diye dua ederler."},{"n":190,"t":"Fakat Allah onlara iyi ve sağlıklı bir çocuk verince de, Allah’ın kendilerine verdiği çocuk konusunda O’na ortaklar koşarlar. Allah, onların ortak koştukları şeylerden yücedir."},{"n":191,"t":"Hiçbir şeyi yaratamayan, kendileri yaratılan şeyleri Allah’a ortak mı koşuyorlar?"},{"n":192,"t":"Hâlbuki onlar (edindikleri ilâhlar) ne onlara yardım edebilirler, ne de kendilerine yardım edebilirler."},{"n":193,"t":"Onları doğru yola çağırsanız size uymazlar. Onları çağırsanız da, sussanız da sizin için birdir (sonuç alamazsınız)."},{"n":194,"t":"Allah’ı bırakıp tapındıklarınızın hepsi sizin gibi (yaratılmış) kullardır. Eğer doğru söyleyenler iseniz, haydi hemen onları çağırın da size cevap versinler (duanıza icabet etsinler)."},{"n":195,"t":"Onların yürüyecek ayakları mı var? Yahut tutacak elleri mi var? Veya görecek gözleri mi var, ya da işitecek kulakları mı var? De ki: \"Haydi, çağırın ortaklarınızı, sonra bana tuzak kurun da bana göz açtırmayın bakalım!\""},{"n":196,"t":"Çünkü benim velim, Kitab’ı (Kur’an’ı) indiren Allah’tır. O, bütün salihlere velilik eder."},{"n":197,"t":"Allah’tan başka taptıklarınızın ise size yardım etmeğe güçleri yetmez. Onlar kendilerine de yardım edemezler."},{"n":198,"t":"Eğer onları, doğru yola çağırırsanız işitmezler. Sen onların sana baktıklarını görürsün, hâlbuki onlar görmezler."},{"n":199,"t":"Sen af yolunu tut, iyiliği emret, cahillerden yüz çevir."},{"n":200,"t":"Eğer şeytandan bir kışkırtma seni dürterse, hemen Allah’a sığın. Şüphesiz O, hakkıyla işitendir, hakkıyla bilendir."},{"n":201,"t":"Şüphe yok ki Allah’a karşı gelmekten sakınanlar, kendilerine şeytandan bir vesvese dokunduğu zaman iyice düşünürler (derhal Allah’ı hatırlarlar da) sonra hemen gözlerini açarlar."},{"n":202,"t":"Şeytanlara kardeş olanlara gelince, şeytanlar onları azgınlığın içine çekerler, sonra da bundan hiç geri durmazlar."},{"n":203,"t":"(Ey Muhammed!) Onlara (istedikleri) bir âyet getirmediğin zaman (alay ederek) derler ki: \"Onu (da) bir yerlerden derleyip toplasaydın ya.\" De ki: \"Ben ancak Rabbimden bana vahyedilene uymaktayım. Bu (Kur’an âyetleri), Rabbinizden gelen basiretlerdir (Gönül gözlerini aydınlatan nurlardır). İman edecek bir topluluk için bir hidayet kaynağı ve bir rahmettir.\""},{"n":204,"t":"Kur’an okunduğu zaman ona kulak verip dinleyin ve susun ki size merhamet edilsin."},{"n":205,"t":"Rabbini, içinden yalvararak ve korkarak, yüksek olmayan bir sesle sabah-akşam zikret ve gafillerden olma."},{"n":206,"t":"Şüphesiz Rabbin katındaki (melek)ler O’na ibadet etmekten büyüklenmezler. O’nu tespih ederler ve yalnız O’na secde ederler."}],[{"n":1,"t":"(Ey Muhammed!) Sana ganimetler hakkında soruyorlar. De ki: \"Ganimetler, Allah’a ve Resûlüne aittir. O hâlde, eğer mü’minler iseniz Allah’a karşı gelmekten sakının, aranızı düzeltin, Allah ve Rasûlüne itaat edin.\""},{"n":2,"t":"Mü’minler ancak o kimselerdir ki; Allah anıldığı zaman kalpleri ürperir. O’nun âyetleri kendilerine okunduğu zaman (bu) onların imanlarını artırır. Onlar sadece Rablerine tevekkül ederler."},{"n":3,"t":"Onlar namazı dosdoğru kılan, kendilerine rızık olarak verdiğimiz şeylerden Allah yolunda harcayan kimselerdir."},{"n":4,"t":"İşte onlar gerçekten mü’minlerdir. Onlara, Rableri katında yüksek mertebeler, bağışlanma ve cömertçe verilmiş rızık vardır."},{"n":5,"t":"Nasıl ki, Rabbin seni hak uğruna (savaşmak üzere) evinden çıkarmıştı. Mü’minlerden bir grup ise bu konuda kesinlikle isteksizlerdi."},{"n":6,"t":"Gerçek apaçık ortaya çıktıktan sonra, sanki göz göre göre ölüme sürülüyorlarmış gibi seninle o konuda tartışıyorlardı."},{"n":7,"t":"Hani Allah size iki taifeden birini, o sizindir diye va’dediyordu. Siz de güçsüz olanın sizin olmasını istiyordunuz. Oysa Allah, sözleriyle hakkı meydana çıkarmak ve kâfirlerin ardını kesmek istiyordu."},{"n":8,"t":"Bu, suçlular hoşlanmasa da Allah’ın hakkı ortaya çıkarması ve batılı ortadan kaldırması içindi."},{"n":9,"t":"Hani Rabbinizden yardım istiyor, yalvarıyordunuz. O da, \"Ben size ard arda bin melekle yardım ediyorum\" diye cevap vermişti."},{"n":10,"t":"Allah bunu, sadece bir müjde olsun ve onunla kalpleriniz yatışsın diye yapmıştı. Yoksa yardım ancak Allah katındandır. Şüphesiz Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":11,"t":"Hani (Allah) kendi tarafından bir güvenlik olarak sizi hafif bir uykuya daldırıyor; sizi temizlemek, sizden şeytanın vesvesesini gidermek, kalplerinizi pekiştirmek ve ayaklarınızı sağlam bastırmak için üzerinize gökten yağmur yağdırıyordu."},{"n":12,"t":"Hani Rabbin meleklere, \"Ben sizinle beraberim. İman edenlere sebat verin. Ben kâfirlerin kalplerine korku salacağım. Şimdi vurun boyunlarının üstüne. Vurun, onların bütün parmaklarına\" diye vahyediyordu."},{"n":13,"t":"Bu, onların Allah’a ve Resûlüne karşı gelmelerindendir. Her kim de Allah’a ve Resûlüne karşı gelirse bilsin ki Allah’ın cezası şiddetlidir."},{"n":14,"t":"İşte şimdi siz tadın onu! Kâfirlere bir de cehennem azabı vardır."},{"n":15,"t":"Ey iman edenler. Savaş düzeninde iken kâfirlerle karşılaştığınız zaman sakın onlara arkanızı dönmeyin (savaştan kaçmayın)."},{"n":16,"t":"-Savaş taktiği olarak düşmanı vurmak için çekilme, ya da diğer bir birliğe katılmak durumu hariç- böyle bir günde her kim onlara arkasını dönerse mutlaka o, Allah’ın gazabına uğramış olur. Onun varacağı yer de cehennemdir. Ne kötü varılacak yerdir orası!"},{"n":17,"t":"(Savaşta) onları siz öldürmediniz, fakat Allah onları öldürdü. Attığın zaman da sen atmadın, fakat Allah attı. Mü’minleri, tarafından güzel bir imtihanla denemek için Allah öyle yaptı. Şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir."},{"n":18,"t":"İşte durum bu: (Allah, mü’minleri güzel bir şekilde dener). Bir de Allah, kâfirlerin tuzağını zayıf düşürendir."},{"n":19,"t":"(Ey inkârcılar!) Eğer fetih istiyorsanız işte size fetih geldi. Eğer (peygambere karşı gelmekten) vazgeçerseniz, bu sizin için daha hayırlı olur. Eğer dönerseniz biz de döneriz. Çok olsa bile topluluğunuz size hiç fayda vermez. Çünkü Allah mü’minlerle beraberdir."},{"n":20,"t":"Ey iman edenler! Allah’a ve Resûlüne itaat edin ve (Kur’an’ı) dinlediğiniz hâlde ondan yüz çevirmeyin."},{"n":21,"t":"İşitmedikleri hâlde, \"işittik\" diyenler gibi de olmayın."},{"n":22,"t":"Şüphesiz, yeryüzünde yürüyen canlıların Allah katında en kötüsü, akıllarını kullanmayan (gerçeği görmeyen) sağırlar, dilsizlerdir."},{"n":23,"t":"Allah, onlarda bir hayır (hakka yöneliş) olduğunu bilseydi, elbette onlara işittirirdi. Onlara işittirseydi dahi mutlaka yine yüz çevirerek dönüp giderlerdi."},{"n":24,"t":"Ey iman edenler! Size hayat verecek şeylere sizi çağırdığı zaman, Allah’ın ve Resûlü’nün çağrısına uyun ve bilin ki Allah, kişi ile kalbi arasına girer. Yine bilin ki, O’nun huzurunda toplanacaksınız."},{"n":25,"t":"Sadece içinizden zulmedenlere erişmekle kalmayacak olan bir azaptan sakının ve bilin ki Allah, azabı çetin olandır."},{"n":26,"t":"O vakti hatırlayın ki siz yeryüzünde güçsüz ve zayıf idiniz. İnsanların sizi kapıp götürmesinden korkuyordunuz. Derken Allah sizi barındırdı, yardımıyla destekledi ve sizi temiz şeylerden rızıklandırdı ki şükredesiniz."},{"n":27,"t":"Ey iman edenler! Allah’a ve Peygamber’e hainlik etmeyin. Bile bile kendi (aranızdaki) emanetlerinize de hainlik etmeyin."},{"n":28,"t":"Bilin ki mallarınız ve çoluk çocuğunuz birer deneme aracıdır. Allah katında ise büyük bir mükâfat vardır."},{"n":29,"t":"Ey iman edenler! Eğer Allah’a karşı gelmekten sakınırsanız; O, size iyiyi kötüden ayırt edecek bir anlayış verir ve sizin kötülüklerinizi örter, sizi bağışlar. Allah, büyük lütuf sahibidir."},{"n":30,"t":"Hani kâfirler seni tutuklamak veya öldürmek, ya da (Mekke’den) çıkarmak için tuzak kuruyorlardı. Onlar tuzak kuruyorlar. Allah da tuzak kuruyordu. Allah, tuzak kuranların en hayırlısıdır."},{"n":31,"t":"Onlara karşı âyetlerimiz okunduğu zaman, \"Duyduk, istesek biz de bunun benzerini elbette söyleriz. Bu, eskilerin masallarından başka bir şey değildir\" dediler."},{"n":32,"t":"Hani onlar, \"Ey Allah’ım, eğer şu (Kur’an) senin katından inmiş hak (kitap) ise hemen üzerimize gökten taş yağdır veya bize elem dolu bir azap getir\" demişlerdi."},{"n":33,"t":"Oysa sen onların içinde iken, Allah onlara azap edecek değildi. Bağışlanma dilerlerken de Allah onlara azap edecek değildir."},{"n":34,"t":"Onlar Mescid-i Haram’dan (mü’minleri) alıkoyarken ve oranın bakımına ehil de değillerken, Allah onlara ne diye azap etmesin? Oranın bakımına ehil olanlar ancak Allah’a karşı gelmekten sakınanlardır. Fakat onların çoğu bilmez."},{"n":35,"t":"Onların, Kâ’be’nin yanında duaları ıslık çalıp el çırpmaktan ibarettir. Öyle ise (ey müşrikler) inkâr etmekte olduğunuzdan dolayı tadın azabı."},{"n":36,"t":"Şüphe yok ki, inkâr edenler mallarını (insanları) Allah yolundan alıkoymak için harcarlar ve harcayacaklardır. Sonra bu mallar onlara bir iç acısı olacak, sonra da yenilgiye uğrayacaklardır. İnkâr edenler toplanıp cehenneme sürüleceklerdir."},{"n":37,"t":"Allah, pis olanı temizden ayırmak, pis olanların hepsini birbiri üstüne koyup yığarak cehenneme koymak için böyle yapar. İşte onlar ziyana uğrayanların ta kendileridir."},{"n":38,"t":"Ey Muhammed! İnkâr edenlere söyle: Eğer (iman edip, düşmanlık ve savaştan) vazgeçerlerse, geçmiş günahları bağışlanır. Eğer (düşmanlık ve savaşa) dönerlerse, öncekilere uygulanan ilâhî kanun devam etmiş olacaktır."},{"n":39,"t":"Baskı ve şiddet kalmayıncaya ve din tamamen Allah’ın oluncaya kadar onlarla savaşın. Eğer (küfürden) vazgeçerlerse, şüphesiz ki Allah onların yaptıklarını hakkıyla görendir."},{"n":40,"t":"Eğer yüz çevirirlerse bilin ki Allah sizin dostunuzdur. O, ne güzel dosttur; O, ne güzel yardımcıdır!"},{"n":41,"t":"Bilin ki, ganimet olarak aldığınız herhangi bir şeyin beşte biri mutlaka Allah’a, Peygamber’e, onun yakınlarına, yetimlere, yoksullara ve yolculara aittir. Eğer Allah’a; hak ile batılın birbirinden ayrıldığı gün, (yani) iki ordunun (Bedir’de) karşılaştığı gün kulumuza indirdiklerimize inandıysanız (bunu böyle bilin). Allah, her şeye hakkıyla gücü yetendir."},{"n":42,"t":"Hani siz vadinin (Medine’ye) yakın tarafında; onlar uzak tarafında, kervansa sizin aşağınızdaydı. (Onlar sayıca sizden öylesine fazla idi ki), şâyet buluşmak üzere sözleşmiş olsaydınız (durumu fark edince) sözleşmenizde ayrılığa düşerdiniz (savaşa yanaşmazdınız). Fakat Allah, olacak bir işi (mü’minlerin zaferini) gerçekleştirmek için böyle yaptı ki, ölen açık bir delille ölsün, yaşayan da açık bir delille yaşasın. Şüphesiz Allah, elbette hakkıyla işitendir, hakkıyla bilendir."},{"n":43,"t":"Hani Allah sana onları uykunda az gösteriyordu. Eğer sana onları çok gösterseydi elbette gevşerdiniz ve o iş hakkında birbirinizle çekişirdiniz. Fakat Allah (sizi bunlardan) kurtardı. Çünkü O, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir."},{"n":44,"t":"Hani karşılaştığınız zaman onları gözlerinize az gösteriyor, sizi de onların gözlerinde azaltıyordu ki Allah, olacak bir işi gerçekleştirsin. Bütün işler Allah’a döndürülür."},{"n":45,"t":"Ey iman edenler! (Savaş için) bir toplulukla karşılaştığınız zaman sebat edin ve Allah’ı çok anın ki kurtuluşa eresiniz."},{"n":46,"t":"Allah’a ve Resûl’üne itaat edin ve birbirinizle çekişmeyin. Sonra gevşersiniz ve gücünüz, devletiniz elden gider. Sabırlı olun. Çünkü Allah sabredenlerle beraberdir."},{"n":47,"t":"Şımarıp böbürlenmek, insanlara gösteriş yapmak ve (halkı) Allah yolundan alıkoymak için yurtlarından çıkanlar (Mekke müşrikleri) gibi olmayın. Allah, onların yaptıklarını kuşatıcıdır."},{"n":48,"t":"Hani şeytan onlara yaptıklarını süslemiş ve, \"Bu gün artık insanlardan size galip gelecek (kimse) yok, mutlaka ben de size yardımcıyım.\" demişti. Fakat iki taraf (savaş alanında) yüz yüze gelince (şeytan), gerisin geriye dönüp, \"Ben sizden uzağım. Çünkü ben sizin görmediğiniz şeyler (melekler) görüyorum. Ben Allah’tan korkarım. Allah, cezası çetin olandır\" demişti."},{"n":49,"t":"Hani münafıklar ve kalplerinde hastalık bulunan kimseler, \"Bunları dinleri aldatmış\" diyorlardı. Hâlbuki kim Allah’a tevekkül ederse, hiç şüphesiz Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":50,"t":"Melekler, kâfirlerin yüzlerine ve artlarına vura vura ve \"haydi tadın yangın azabını\" diyerek canlarını alırken bir görseydin."},{"n":51,"t":"(Ey kâfirler!) Bu, sizin ellerinizin önceden yaptığının karşılığıdır. Yoksa, Allah kullarına zulmedici değildir."},{"n":52,"t":"Bunların durumu tıpkı Firavun ailesi ve onlardan öncekilerin durumu gibidir. Allah’ın âyetlerini inkâr etmişler, Allah da kendilerini günahları sebebiyle hemen yakalamıştı. Şüphesiz Allah kuvvetlidir, azabı çetin olandır."},{"n":53,"t":"Bunun sebebi şudur: Bir toplum kendilerinde bulunan (iyi davranışlar)ı değiştirmedikçe, Allah onlara verdiği bir nimeti değiştirmez ve şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir."},{"n":54,"t":"Bunların durumu, tıpkı Firavun ailesi ve onlardan öncekilerin durumu gibidir. Onlar Rablerinin âyetlerini yalanlamışlar, biz de onları günahları sebebiyle helâk etmiştik ve Firavun ailesini de suda boğmuştuk. Hepsi de zalim kimselerdi."},{"n":55,"t":"Şüphesiz Allah katında, yeryüzünde yürüyen canlıların en kötüsü, inkâr edenlerdir. Artık onlar iman etmezler."},{"n":56,"t":"Onlar, kendileriyle antlaşma yaptığın, sonra da her defasında antlaşmalarını hiç çekinmeden bozan kimselerdir."},{"n":57,"t":"Eğer onları savaşta yakalarsan, bunlar(a vereceğin ceza) ile arkalarındakileri de dağıt ki ibret alsınlar."},{"n":58,"t":"(Antlaşma yaptığın) bir kavmin hainlik etmesinden korkarsan, sen de antlaşmayı bozduğunu aynı şekilde onlara bildir. Çünkü Allah, hainleri sevmez."},{"n":59,"t":"İnkâr edenler, asla yakayı kurtardıklarını zannetmesinler. Çünkü onlar (sizi) âciz bırakamazlar."},{"n":60,"t":"Onlara karşı gücünüz yettiği kadar kuvvet ve savaş atları hazırlayın. Onlarla Allah’ın düşmanını, sizin düşmanınızı ve bunlardan başka sizin bilmediğiniz fakat Allah’ın bildiği diğer düşmanları korkutursunuz. Allah yolunda her ne harcarsanız karşılığı size tam olarak ödenir. Size zulmedilmez."},{"n":61,"t":"Eğer onlar barışa yanaşırlarsa, sen de ona yanaş ve Allah’a tevekkül et. Çünkü O, hakkıyla işitendir, hakkıyla bilendir."},{"n":"62-63","t":"Eğer seni aldatmak isterlerse bilmiş ol ki sana yetecek Allah’tır. O, seni bizzat kendi yardımıyla ve mü’minlerle destekleyen ve onların kalplerini uzlaştırandır. Şayet yeryüzündeki şeyleri tümüyle harcasaydın, sen onların kalplerini uzlaştıramazdın. Fakat, Allah onların arasını uzlaştırdı. Şüphesiz O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":64,"t":"Ey Peygamber! Sana ve sana tabi olan mü’minlere Allah yeter."},{"n":65,"t":"Ey Peygamber! Mü’minleri savaşa teşvik et. Eğer içinizde sabırlı yirmi kişi bulunursa, iki yüz kişiye galip gelirler. Eğer içinizde (sabırlı) yüz kişi bulunursa, inkâr edenlerden bin kişiye galip gelirler. Çünkü onlar anlamayan bir kavimdir."},{"n":66,"t":"Şimdi ise, Allah yükünüzü hafifletti ve sizde muhakkak bir zaaf olduğunu bildi. Eğer içinizde sabırlı yüz kişi olursa iki yüz kişiye galip gelirler. Eğer içinizde (sabırlı) bin kişi olursa, Allah’ın izniyle iki bin kişiye galip gelirler. Allah, sabredenlerle beraberdir."},{"n":67,"t":"Yeryüzünde düşmanı tamamıyla sindirip hâkim duruma gelmedikçe, hiçbir peygambere esir almak yakışmaz. Siz geçici dünya menfaatini istiyorsunuz, hâlbuki Allah ahireti (kazanmanızı) istiyor. Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":68,"t":"Eğer Allah’ın daha önce verilmiş bir hükmü olmasaydı, aldığınız şey (fidye)den dolayı size büyük bir azap dokunurdu."},{"n":69,"t":"Artık elde ettiğiniz ganimetten helâl ve temiz olarak yiyin. Allah’a karşı gelmekten sakının. Şüphesiz Allah çok bağışlayandır, çok merhamet edendir."},{"n":70,"t":"Ey Peygamber! Elinizdeki esirlere söyle: Eğer Allah, kalplerinizde (iman, ihlâs, iyi niyet gibi) bir hayır (olduğunu) bilirse, sizden alınan fidyeden daha hayırlısını size verir ve sizi bağışlar. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":71,"t":"Eğer sana hainlik etmek isterlerse, (bil ki) onlar daha önce Allah’a da hainlik etmişlerdi de Allah onlara karşı (sana) imkân vermişti. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":72,"t":"İman edip hicret eden ve Allah yolunda mallarıyla, canlarıyla cihad edenler ve (muhacirleri) barındırıp (onlara) yardım edenler var ya, işte onlar birbirlerinin velileridir. İman edip hicret etmeyenlere gelince, hicret edinceye kadar, onların velayetleri size ait değildir. Eğer din konusunda sizden yardım isterlerse, sizinle aralarında sözleşme bulunan bir kavme karşı olmadıkça, yardım etmek üzerinize borçtur. Allah, yaptıklarınızı hakkıyla görendir."},{"n":73,"t":"İnkâr edenler de birbirlerinin velileridir. Eğer siz bunların gereğini yapmazsanız, yeryüzünde bir karışıklık ve büyük bir bozulma olur."},{"n":74,"t":"İman edip hicret eden ve Allah yolunda cihad edenler ve (muhacirleri) barındırıp (onlara) yardım edenler var ya; işte onlar gerçek mü’minlerdir. Onlar için bir bağışlanma ve bol bir rızık vardır."},{"n":75,"t":"Daha sonra iman edip hicret eden ve sizinle birlikte cihad edenlere gelince, işte onlar da sizdendir. Allah’ın kitabınca, kan akrabaları birbirlerine (varis olmaya) daha lâyıktırlar. Şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir."}],[{"n":1,"t":"Allah ve Resûlünden, kendileriyle antlaşma yapmış olduğunuz müşriklere kesin bir uyarıdır:"},{"n":2,"t":"Yeryüzünde dört ay daha dolaşın. Şunu bilin ki, siz Allah’ı âciz bırakacak değilsiniz; Allah ise, inkârcıları perişan edecektir."},{"n":3,"t":"Hacc-ı ekber gününde, Allah ve Resûlünden bütün insanlara bir bildiridir: Allah ve Resûlü, Allah’a ortak koşanlardan uzaktır. Eğer tövbe ederseniz, bu sizin için hayırlıdır. Ama yüz çevirirseniz, şunu iyi bilin ki, siz Allah’ı âciz bırakabilecek değilsiniz. İnkârcılara, elem dolu bir azabı müjdele!"},{"n":4,"t":"Ancak Allah’a ortak koşanlardan, kendileriyle antlaşma yapmış olduğunuz, sonra da antlaşmalarında size karşı hiçbir eksiklik yapmamış ve sizin aleyhinize hiç kimseye yardım etmemiş olanlar, bu hükmün dışındadır. Onların antlaşmalarını, süreleri bitinceye kadar tamamlayın. Şüphesiz Allah, kendine karşı gelmekten sakınanları sever."},{"n":5,"t":"Haram aylar çıkınca bu Allah’a ortak koşanları artık bulduğunuz yerde öldürün, onları yakalayıp hapsedin ve her gözetleme yerine oturup onları gözetleyin. Eğer tövbe ederler, namazı kılıp zekâtı da verirlerse, kendilerini serbest bırakın. Şüphesiz Allah çok bağışlayıcıdır, çok merhamet edicidir."},{"n":6,"t":"Eğer Allah’a ortak koşanlardan biri senden sığınma talebinde bulunursa, Allah’ın kelâmını işitebilmesi için ona sığınma hakkı tanı. Sonra da onu güven içinde olacağı yere ulaştır. Bu, onların bilmeyen bir kavim olmaları sebebiyledir."},{"n":7,"t":"Allah’a ortak koşanların Allah katında ve Resûlü yanında bir ahdi nasıl olabilir? Ancak Mescid-i Haram’ın yanında kendileriyle antlaşma yaptıklarınız başkadır. Bunlar size karşı dürüst davrandığı sürece, siz de onlara dürüst davranın. Çünkü Allah, kendine karşı gelmekten sakınanları sever."},{"n":8,"t":"Onların bir ahdi nasıl olabilir ki! Eğer onlar size üstün gelselerdi, sizin hakkınızda ne akrabalık (bağlarını), ne de antlaşma (yükümlülüğünü) gözetirlerdi. Ağızlarıyla sizi hoşnut etmeye çalışıyorlar, oysa kalpleri buna karşı çıkıyor. Onların pek çoğu fasık kimselerdir."},{"n":9,"t":"Allah’ın âyetlerini az bir karşılığa değiştiler de insanları O’nun yolundan alıkoydular. Bunların yapmakta oldukları şeyler gerçekten ne kötüdür!"},{"n":10,"t":"Bir mü’min hakkında ne akrabalık (bağlarını), ne de antlaşma (yükümlülüğünü) gözetirler. İşte onlar taşkınlık yapanların ta kendileridir."},{"n":11,"t":"Fakat tövbe edip, namazı kılar ve zekâtı verirlerse, artık onlar sizin din kardeşlerinizdir. Bilen bir kavme âyetleri işte böyle ayrı ayrı açıklarız."},{"n":12,"t":"Eğer antlaşmalarından sonra yeminlerini bozup dininize dil uzatırlarsa, küfrün elebaşlarıyla savaşın. Çünkü onlar yeminlerine riayet etmeyen kimselerdir. Umulur ki, vazgeçerler."},{"n":13,"t":"Yeminlerini bozan, peygamberi yurdundan çıkarmaya kalkışan ve üstelik size tecavüzü ilk defa kendileri başlatan bir kavimle savaşmaz mısınız? Yoksa onlardan korkuyor musunuz? Oysa Allah, -eğer siz gerçek mü’minler iseniz- kendisinden korkmanıza daha lâyıktır."},{"n":"14-15","t":"Onlarla savaşın ki, Allah onlara sizin ellerinizle azap etsin, onları rezil etsin, onlara karşı size yardım etsin, mü’min topluluğun gönüllerini ferahlatsın ve onların kalplerindeki öfkeyi gidersin. Allah, dilediğinin tövbesini kabul eder. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":16,"t":"Yoksa; Allah içinizden, Allah’tan, Resûlünden ve mü’minlerden başkasını kendilerine sırdaş edinmeksizin cihad edenleri ayırt etmeden bırakılacağınızı mı sandınız? Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":17,"t":"Allah’a ortak koşanların, inkârlarına bizzat kendileri şahitlik edip dururken, Allah’ın mescitlerini imar etmeleri düşünülemez. Onların bütün amelleri boşa gitmiştir. Onlar ateşte ebedî kalacaklardır."},{"n":18,"t":"Allah’ın mescitlerini, ancak Allah’a ve ahiret gününe inanan, namazı dosdoğru kılan, zekâtı veren ve Allah’tan başkasından korkmayan kimseler imar eder. İşte onların doğru yolu bulanlardan olmaları umulur."},{"n":19,"t":"Siz hacılara su dağıtmayı ve Mescid-i Haram’ın bakım ve onarımını, Allah’a ve âhiret gününe iman edip Allah yolunda cihad eden kimse(lerin amelleri) gibi mi tuttunuz? Bunlar Allah katında eşit olmazlar. Allah, zâlim topluluğu doğru yola erdirmez."},{"n":20,"t":"İman edip hicret eden ve Allah yolunda mallarıyla, canlarıyla cihad eden kimselerin mertebeleri, Allah katında daha üstündür. İşte onlar, başarıya erenlerin ta kendileridir."},{"n":21,"t":"Rableri onlara, kendi katından bir rahmet, bir hoşnutluk ve kendilerine içinde tükenmez nimetler bulunan cennetler müjdelemektedir."},{"n":22,"t":"Onlar orada ebedî kalacaklardır. Şüphesiz, Allah katında büyük bir mükâfat vardır."},{"n":23,"t":"Ey iman edenler! Eğer küfrü imana tercih ederlerse, babalarınızı ve kardeşlerinizi bile dost edinmeyin. İçinizden kim onları dost edinirse, işte onlar, zalimlerin ta kendileridir."},{"n":24,"t":"De ki: \"Eğer babalarınız, oğullarınız, kardeşleriniz, eşleriniz, aşiretiniz, kazandığınız mallar, kesada uğramasından korktuğunuz bir ticaret ve beğendiğiniz meskenler size Allah’tan, peygamberinden ve O’nun yolunda cihattan daha sevgili ise, artık Allah’ın emri gelinceye kadar bekleyin! Allah, fasık topluluğu doğru yola erdirmez.\""},{"n":25,"t":"Andolsun, Allah birçok yerde ve Huneyn savaşı gününde size yardım etmiştir. Hani, çokluğunuz size kendinizi beğendirmiş, fakat (bu çokluk) size hiçbir yarar sağlamamış, yeryüzü bütün genişliğine rağmen size dar gelmişti. Nihayet (bozularak) gerisin geriye dönüp kaçmıştınız."},{"n":26,"t":"Sonra Allah, Resûlü ile mü’minler üzerine kendi katından güven duygusu ve huzur indirdi. Bir de sizin göremediğiniz ordular indirdi ve inkâr edenlere azap verdi. İşte bu, inkârcıların cezasıdır."},{"n":27,"t":"Sonra Allah, bunun ardından yine dilediği kimsenin tövbesini kabul eder. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":28,"t":"Ey iman edenler! Allah’a ortak koşanlar ancak bir pislikten ibarettir. Artık bu yıllarından sonra, Mescid-i Haram’a yaklaşmasınlar. Eğer yoksulluktan korkarsanız, Allah dilerse lütfuyla sizi zengin kılar. Şüphesiz Allah hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":29,"t":"Kendilerine kitap verilenlerden Allah’a ve ahiret gününe iman etmeyen, Allah’ın ve Resûlünün haram kıldığını haram saymayan ve hak din İslâm’ı din edinmeyen kimselerle, küçülerek (boyun eğerek) kendi elleriyle cizyeyi verinceye kadar savaşın."},{"n":30,"t":"Yahudiler, \"Üzeyr, Allah’ın oğludur\" dediler. Hıristiyanlar ise, \"İsa Mesih, Allah’ın oğludur\" dediler. Bu, onların ağızlarıyla söyledikleri (gerçeği yansıtmayan) sözleridir. Onların bu sözleri daha önce inkâr etmiş kimselerin söylediklerine benziyor. Allah, onları kahretsin. Nasıl da haktan çevriliyorlar!"},{"n":31,"t":"(Yahudiler) Allah’ı bırakıp, hahamlarını; (hıristiyanlar ise) rahiplerini ve Meryem oğlu Mesih’i rab edindiler. Oysa, bunlar da ancak, bir olan Allah’a ibadet etmekle emrolunmuşlardır. O’ndan başka hiçbir ilâh yoktur. O, onların ortak koştukları her şeyden uzaktır."},{"n":32,"t":"Allah’ın nurunu ağızlarıyla söndürmek istiyorlar. Oysa kâfirler hoşlanmasalar da Allah, nurunu tamamlamaktan başka bir şeye razı olmaz."},{"n":33,"t":"O, Allah’a ortak koşanlar hoşlanmasalar bile dinini, bütün dinlere üstün kılmak için, peygamberini hidayetle ve hak dinle gönderendir."},{"n":34,"t":"Ey iman edenler! Hahamlardan ve rahiplerden birçoğu, insanların mallarını haksız yollarla yiyorlar ve Allah’ın yolundan alıkoyuyorlar. Altın ve gümüşü biriktirip gizleyerek onları Allah yolunda harcamayanları elem dolu bir azapla müjdele."},{"n":35,"t":"O gün bunlar cehennem ateşinde kızdırılacak da onların alınları, böğürleri ve sırtları bunlarla dağlanacak ve, \"İşte bu, kendiniz için biriktirip sakladığınız şeylerdir. Haydi tadın bakalım, biriktirip sakladıklarınızı!\" denilecek."},{"n":36,"t":"Şüphesiz Allah’ın gökleri ve yeri yarattığı günkü yazısında, Allah katında ayların sayısı on ikidir. Bunlardan dördü haram aylardır. İşte bu, Allah’ın dosdoğru kanunudur. Öyleyse o aylarda kendinize zulmetmeyin. Fakat Allah’a ortak koşanlar sizinle nasıl topyekûn savaşıyorlarsa, siz de onlarla topyekûn savaşın. Bilin ki Allah, kendine karşı gelmekten sakınanlarla beraberdir."},{"n":37,"t":"Haram ayları ertelemek, ancak inkârda daha da ileri gitmektir ki bununla inkâr edenler saptırılır. Allah’ın haram kıldığı ayların sayısına uygun getirip böylece Allah’ın haram kıldığını helâl kılmak için haram ayı bir yıl helâl, bir yıl haram sayıyorlar. Onların bu çirkin işleri, kendilerine süslenip güzel gösterildi. Allah, inkârcı toplumu doğru yola iletmez."},{"n":38,"t":"Ey iman edenler! Ne oldunuz ki, size \"Allah yolunda sefere çıkın\" denilince, yere çakılıp kaldınız. Yoksa ahiretten vazgeçip dünya hayatını mı seçtiniz? Oysa ahirete göre dünya hayatının yararı, pek az bir şeydir."},{"n":39,"t":"Eğer Allah, yolunda sefere çıkmazsanız, sizi elem dolu bir azap ile cezalandırır ve yerinize sizden başka bir toplum getirir. Siz ise O’na hiçbir zarar veremezsiniz. Allah, her şeye hakkıyla gücü yetendir."},{"n":40,"t":"Eğer siz ona (Peygamber’e) yardım etmezseniz, (biliyorsunuz ki) inkâr edenler onu iki kişiden biri olarak (Mekke’den) çıkardıkları zaman, ona bizzat Allah yardım etmişti. Hani onlar mağarada bulunuyorlardı. Hani o arkadaşına, \"Üzülme, çünkü Allah bizimle beraber\" diyordu. Allah da onun üzerine güven duygusu ve huzur indirmiş, sizin kendilerini görmediğiniz birtakım ordularla onu desteklemiş, böylece inkâr edenlerin sözünü alçaltmıştı. Allah’ın sözü ise en yücedir. Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":41,"t":"Gerek yaya olarak, gerek binek üzerinde Allah yolunda sefere çıkın. Mallarınızla, canlarınızla Allah yolunda cihad edin. Eğer bilirseniz bu sizin için daha hayırlıdır."},{"n":42,"t":"Eğer yakın bir dünya menfaati ve kolay bir yolculuk olsaydı, (sefere katılmayan münafıklar da) mutlaka sana uyarlardı. Fakat meşakkatli yol, onlara uzak geldi. Gerçi onlar, \"Eğer gücümüz yetseydi, elbette sizinle beraber çıkardık\" diye Allah’a yemin edeceklerdir. Onlar kendilerini helâke sürüklüyorlar. Allah, biliyor ki onlar kesinlikle yalancıdırlar."},{"n":43,"t":"Allah, seni affetsin! Doğru söyleyenler sana iyice belli olup, yalancıları bilinceye kadar beklemeden niçin onlara izin verdin?"},{"n":44,"t":"Allah’a ve âhiret gününe iman edenler, mallarıyla ve canlarıyla cihad etmekten geri kalmak için senden izin istemezler. Allah, kendine karşı gelmekten sakınanları çok iyi bilendir."},{"n":45,"t":"Ancak Allah’a ve ahiret gününe inanmayan, kalpleri şüpheye düşüp kendileri de o şüphelerinin içinde bocalayan kimseler senden izin isterler."},{"n":46,"t":"Onlar eğer savaşa çıkmak isteselerdi, elbette bunun için bir hazırlık yaparlardı. Fakat Allah onların harekete geçmelerini istemedi de onları geri bıraktı ve onlara, \"Oturun, oturan âcizlerle beraber\" denildi."},{"n":47,"t":"Eğer onlar da sizin içinizde (sefere) çıksalardı, size bozgunculuktan başka bir katkıları olmayacak ve sizi fitneye düşürmek için aranızda koşuşturacaklardı. Aranızda onları dinleyecek kişiler de vardı. Allah, zalimleri hakkıyla bilendir."},{"n":48,"t":"Andolsun, bunlar daha önce de fitne çıkarmak istemişler ve sana karşı türlü türlü işler çevirmişlerdi. Nihayet hak geldi ve onlar istemedikleri hâlde, Allah’ın dini galip geldi."},{"n":49,"t":"Onlardan \"Bana izin ver, beni fitneye (isyana) sevk etme\" diyen de vardır. Bilesiniz ki onlar (böyle diyerek) fitnenin ta içine düştüler. Şüphesiz ki cehennem, kâfirleri elbette kuşatacaktır."},{"n":50,"t":"Sana bir iyilik gelirse, bu onları üzer. Eğer başına bir musîbet gelirse, \"Biz tedbirimizi önceden almıştık\" derler ve sevinerek dönüp giderler."},{"n":51,"t":"De ki: \"Bizim başımıza ancak, Allah’ın bizim için yazdığı şeyler gelir. O, bizim yardımcımızdır. Öyleyse mü’minler, yalnız Allah’a güvensinler.\""},{"n":52,"t":"De ki: \"Bizim için siz, (şehitlik veya zafer olmak üzere) ancak iki güzellikten birini bekleyebilirsiniz. Biz de, Allah’ın kendi katından veya bizim ellerimizle size ulaştıracağı bir azabı bekliyoruz. Haydi bekleyedurun. Şüphesiz biz de sizinle birlikte beklemekteyiz.\""},{"n":53,"t":"Yine de ki: \"İster gönüllü, ister gönülsüz olarak harcayın, sizden asla kabul olunmayacaktır. Çünkü siz fasık bir topluluksunuz.\""},{"n":54,"t":"Harcamalarının kabul edilmesine, yalnızca, Allah’ı ve Resûlünü inkâr etmeleri, namaza ancak üşene üşene gelmeleri ve ancak gönülsüzce harcamaları engel olmuştur."},{"n":55,"t":"Onların malları ve çocukları seni imrendirmesin. Allah, bununla ancak onlara dünya hayatında azap etmeyi ve canlarının kâfir olarak çıkmasını istiyor."},{"n":56,"t":"Kesinlikle sizden olduklarına dair Allah’a yemin ederler. Oysa onlar sizden değillerdir. Fakat onlar korkudan ödleri patlayan bir topluluktur."},{"n":57,"t":"Eğer sığınacak bir yer veya (gizlenecek) mağaralar yahut girilecek bir delik bulsalardı, hemen koşarak oraya kaçarlardı."},{"n":58,"t":"İçlerinden sadakalar konusunda sana dil uzatanlar da var. Kendilerine ondan bir pay verilirse, hoşnut olurlar; eğer kendilerine ondan bir pay verilmezse, hemen kızarlar."},{"n":59,"t":"Eğer onlar Allah ve Resûlünün kendilerine verdiğine razı olup, \"Bize Allah yeter. Lütuf ve ihsanıyla Allah ve Resûlü ileride bize yine verir. Biz yalnız Allah’a rağbet eder (O’nun ihsanını ister)iz\" deselerdi, kendileri için daha hayırlı olurdu."},{"n":60,"t":"Sadakalar (zekâtlar), Allah’tan bir farz olarak ancak fakirler, düşkünler, zekât toplayan memurlar, kalpleri İslâm’a ısındırılacak olanlarla (özgürlüğüne kavuşturulacak) köleler, borçlular, Allah yolunda cihad edenler ve yolda kalmış yolcular içindir. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":61,"t":"Yine onlardan peygamberi inciten ve \"O (her söyleneni dinleyen) bir kulaktır\" diyen kimseler de vardır. De ki: \"O, sizin için bir hayır kulağıdır ki Allah’a inanır, mü’minlere inanır (güvenir). İçinizden inanan kimseler için bir rahmettir. Allah’ın Resûlünü incitenler için ise elem dolu bir azap vardır.\""},{"n":62,"t":"Sizi razı etmek için, Allah’a yemin ederler. Eğer gerçekten mü’min iseler (bilsinler ki), Allah ve Resûlü’nü razı etmeleri daha önceliklidir."},{"n":63,"t":"Allah’a ve Resûlüne karşı gelen kimseye, içinde ebedî kalacağı cehennem ateşinin olduğunu bilmediler mi? İşte bu, büyük bir rezilliktir."},{"n":64,"t":"Münafıklar, kalplerinde olan şeyleri, yüzlerine karşı açıkça haber verecek bir sûrenin üzerlerine indirilmesinden çekinirler. De ki: \"Siz alay ede durun! Allah, çekindiğiniz o şeyi ortaya çıkaracaktır.\""},{"n":65,"t":"Şâyet kendilerine (niçin alay ettiklerini) sorsan, \"Biz sadece lâfa dalmıştık ve aramızda eğleniyorduk\", derler. De ki: \"Allah’la, O’nun âyetleriyle ve peygamberiyle mi eğleniyordunuz?\""},{"n":66,"t":"Boşuna özür dilemeyin! Çünkü siz, (sözde) iman ettikten sonra küfrünüzü açığa vurdunuz. İçinizden (tövbe eden) bir zümreyi affetsek bile, suçlarında ısrar etmeleri sebebiyle, diğer bir zümreye azap edeceğiz."},{"n":67,"t":"Münafık erkekler ve münafık kadınlar birbirlerindendir (birbirlerinin benzeridir). Kötülüğü emredip iyiliği yasaklarlar, ellerini de sıkı tutarlar. Onlar Allah’ı unuttular; Allah da onları unuttu. Şüphesiz münafıklar, fasıkların ta kendileridir."},{"n":68,"t":"Allah, erkek münafıklara, kadın münafıklara ve kâfirlere, içinde ebedî kalmak üzere cehennem ateşini va’detti. O, onlara yeter. Allah, onlara lânet etmiştir. Onlar için sürekli bir azap vardır."},{"n":69,"t":"(Ey münafıklar!), siz de tıpkı sizden öncekiler gibisiniz: Onlar sizden daha güçlü, malları ve çocukları daha fazlaydı. Onlar paylarına düşenden faydalanmışlardı. Sizden öncekilerin, paylarına düşenden faydalandığı gibi siz de payınıza düşenden öylece faydalandınız ve onların daldığı gibi, siz de (dünya zevkine) daldınız. İşte onların dünyada da ahirette de amelleri boşa gitmiştir. İşte onlar ziyana uğrayanların ta kendileridir."},{"n":70,"t":"Onlara kendilerinden öncekilerin; Nûh, Âd ve Semûd kavimlerinin; İbrahim’in kavminin; Medyen halkının ve yerle bir olan şehirlerin haberleri ulaşmadı mı? Peygamberleri onlara apaçık mucizeler getirmişti. (Ama inanmadılar, Allah da onları cezalandırdı.) Demek ki Allah onlara zulmediyor değildi, ama onlar kendilerine zulmediyorlardı."},{"n":71,"t":"Mü’min erkekler ve mü’min kadınlar birbirlerinin dostlarıdır. İyiliği emreder, kötülükten alıkoyarlar. Namazı dosdoğru kılar, zekâtı verirler. Allah’a ve Resûlüne itaat ederler. İşte bunlara Allah merhamet edecektir. Şüphesiz Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":72,"t":"Allah, mü’min erkeklere ve mü’min kadınlara, ebedî olarak kalacakları, içinden ırmaklar akan cennetler ve Adn cennetlerinde çok güzel köşkler va’detti. Allah’ın rızası ise, bunların hepsinden daha büyüktür. İşte bu büyük başarıdır."},{"n":73,"t":"Ey peygamber! Kâfirlere ve münafıklara karşı cihad et ve onlara karşı çetin ol. Onların varacakları yer cehennemdir. Ne kötü bir varış yeridir orası!"},{"n":74,"t":"Bir şey söylemediklerine dair Allah’a yemin ediyorlar. Hâlbuki o küfür sözünü söylediler ve (sözde) müslüman olduktan sonra inkâr ettiler. Ayrıca başaramadıkları şeye (peygamberi öldürmeye) de yeltendiler. Sırf, Allah ve Resûlü kendi lütfu ile onları zengin kıldığı için intikam almaya kalktılar. Eğer tövbe ederlerse, kendileri için hayırlı olur. Şayet yüz çevirirlerse, Allah onları dünyada ve ahirette elem dolu bir azaba çarptıracaktır. Artık onlar için yeryüzünde ne bir dost, ne de bir yardımcı vardır."},{"n":75,"t":"İçlerinden, \"Eğer Allah bize lütuf ve kereminden verirse, mutlaka bol bol sadaka veririz ve mutlaka salihlerden oluruz\" diye Allah’a söz verenler de vardır."},{"n":76,"t":"Fakat Allah, lütuf ve kereminden onlara verince, onda cimrilik ettiler ve yüz çevirerek dönüp gittiler."},{"n":77,"t":"Allah’a verdikleri sözü tutmadıkları ve yalan söyledikleri için O da kalplerine, kendisiyle karşılaşacakları güne kadar (sürecek) bir nifak soktu."},{"n":78,"t":"Allah’ın, içlerinde gizlediklerini ve fısıltılarını bildiğini ve Allah’ın gaybleri çok iyi bilen olduğunu bilmediler mi?"},{"n":79,"t":"Sadakalar hususunda gönüllü bağışta bulunan mü’minlerle, güçlerinin yettiğinden başkasını bulamayanları çekiştirip onlarla alay edenler var ya; işte Allah asıl onları maskaraya çevirmiştir. Onlar için elem dolu bir azap vardır."},{"n":80,"t":"Onlar için ister bağışlanma dile, ister dileme (fark etmez.) Onlar için yetmiş kez bağışlanma dilesen de, Allah onları asla affetmeyecektir. Bu, onların Allah ve Resûlünü inkâr etmiş olmaları sebebiyledir. Allah, fasık topluluğu doğru yola iletmez."},{"n":81,"t":"Allah’ın Resûlüne karşı gelerek (sefere çıkmayıp) geri bırakılanlar, oturup kalmalarına sevindiler. Allah yolunda mallarıyla canlarıyla cihad etmek hoşlarına gitmedi ve \"Bu sıcakta sefere çıkmayın\" dediler. De ki: \"Cehennemin ateşi daha sıcaktır.\" Keşke anlasalardı."},{"n":82,"t":"Artık kazandıklarının karşılığı olarak, az gülsünler, çok ağlasınlar."},{"n":83,"t":"Eğer (bundan böyle) Allah seni onlardan bir zümrenin yanına döndürür de, onlar (sefere) çıkmak için senden izin isterlerse, de ki: \"Artık siz benimle birlikte ebediyyen çıkmayacak ve benimle birlikte hiçbir düşmanla asla savaşmayacaksınız. Çünkü siz baştan yerinizde oturup kalmaya razı oldunuz. Şimdi de geri kalan (kadın ve çocuk)larla birlikte oturun.\""},{"n":84,"t":"Onlardan ölen hiçbirine asla namaz kılma ve kabrinin başında durma. Çünkü onlar Allah’ı ve Resûlünü inkâr ettiler ve fasık olarak öldüler."},{"n":85,"t":"Onların malları ve evlatları seni imrendirmesin. Allah, bunlarla ancak, dünyada kendilerine azap etmeyi ve canlarının kâfir olarak çıkmasını istiyor."},{"n":86,"t":"\"Allah’a iman edin ve Resûlü ile birlikte cihat edin\" diye bir sûre indirildiğinde, onlardan servet sahibi olanlar, senden izin istediler ve \"Bizi bırak da oturup kalanlarla birlikte olalım\" dediler."},{"n":87,"t":"Onlar geride kalan (kadın ve çocuk)larla birlikte olmaya razı oldular ve kalpleri mühürlendi. Artık onlar anlamazlar."},{"n":88,"t":"Fakat peygamber ve beraberindeki mü’minler, mallarıyla, canlarıyla cihat ettiler. Bütün hayırlar işte bunlarındır. İşte bunlar kurtuluşa erenlerin ta kendileridir."},{"n":89,"t":"Allah onlara, içinde ebedî kalacakları, içinden ırmaklar akan cennetler hazırlamıştır. İşte bu büyük başarıdır."},{"n":90,"t":"Bedevîlerden mazeret ileri sürenler, kendilerine izin verilsin diye geldiler. Allah’a ve Resûlüne yalan söyleyenler ise (mazeret bile belirtmeden) oturup kaldılar. Onlardan kâfir olanlara elem dolu bir azap isabet edecektir."},{"n":91,"t":"Allah’a ve Resûlüne karşı sadık ve samimi oldukları takdirde, güçsüzlere, hastalara ve (seferde) harcayacakları bir şey bulamayanlara (sefere katılmadıkları için) bir günah yoktur. İyilikte bulunan kimselerin (kınanması) için de bir sebep yoktur. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":92,"t":"Kendilerini bindirip (cepheye) sevk edesin diye sana geldikleri zaman, senin, \"Sizi bindirebileceğim bir şey bulamıyorum\" dediğin; bu uğurda harcayacakları bir şey bulamadıklarından dolayı üzüntüden gözleri yaş döke döke geri dönen kimselere de bir sorumluluk yoktur."},{"n":93,"t":"Sorumluluk ancak, zengin oldukları hâlde senden izin isteyenleredir. Bunlar, geride kalan (kadın ve çocuk)larla birlikte olmaya razı oldular. Allah da kalplerini mühürledi. Artık onlar bilmezler."},{"n":94,"t":"Onlara döndüğünüzde, size mazeret beyan edeceklerdir. De ki: \"Mazeret beyan etmeyin. Size kesinlikle inanmayız. Çünkü Allah bize sizin durumunuzu bildirdi. Bundan böyle davranışlarınızı Allah da Resûlü de görecek. Sonra hepiniz, gaybı da görülen âlemi de bilene döndürüleceksiniz de yapmakta olduğunuz şeyleri size haber verecek.\""},{"n":95,"t":"Yanlarına döndüğünüz zaman, kendilerini rahat bırakmanız için size Allah adıyla yemin edeceklerdir. Artık onların peşini bırakın. Çünkü onlar pistir. Kazandıklarının karşılığı olarak, varacakları yer de cehennemdir."},{"n":96,"t":"Kendilerinden razı olasınız diye, size yemin edeceklerdir. Siz onlardan razı olsanız bile, Allah o fasıklar topluluğundan asla razı olmaz."},{"n":97,"t":"Bedevîler inkâr ve nifak bakımından daha ileri ve Allah’ın peygamberine indirdiği hükümlerin sınırlarını tanımamaya daha yatkındırlar. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":98,"t":"Bedevîlerden öyleleri vardır ki, (Allah yolunda) harcayacakları şeyi bir zarar sayar ve (bundan kurtulmak için) size belâlar gelmesini beklerler. Kötü belâlar kendi başlarına olsun. Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":99,"t":"Bedevîlerden kimileri de vardır ki, Allah’a ve ahiret gününe inanır. Harcayacaklarını, Allah katında yakınlığa ve Peygamberin dualarını almağa vesile sayarlar. Bilesiniz ki bu, (Allah katında) onlar için yakınlıktır. Allah, onları rahmetine sokacaktır. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir."},{"n":100,"t":"İslâm’ı ilk önce kabul eden muhâcirler ve ensar ile, iyilikle onlara uyanlar var ya, Allah onlardan razı olmuş; onlar da O’ndan razı olmuşlardır. Allah, onlara içinden ırmaklar akan, içinde ebedî kalacakları cennetler hazırlamıştır. İşte bu büyük başarıdır."},{"n":101,"t":"Çevrenizdeki bedevîlerden birtakım münafıklar vardır. Medine halkından da münafıklıkta direnenler var ki sen onları bilmezsin. Biz onları biliriz. Onlara iki defa azap edeceğiz. Sonra da büyük bir azaba itileceklerdir."},{"n":102,"t":"Diğer bir kısmı ise, günahlarını itiraf ettiler. Bunlar salih amelle kötü ameli birbirine karıştırmışlardır. Umulur ki Allah tövbelerini kabul eder. Çünkü Allah çok bağışlayandır, çok merhamet edendir."},{"n":103,"t":"Onların mallarından, onları kendisiyle arındıracağın ve temizleyeceğin bir sadaka (zekât) al ve onlara dua et. Çünkü senin duan onlar için sükûnettir (Onların kalplerini yatıştırır.) Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":104,"t":"Onlar, kullarının tövbesini kabul edenin ve sadakaları alanın Allah olduğunu; tövbeyi çok kabul edenin, çok merhametli olanın Allah olduğunu bilmediler mi?"},{"n":105,"t":"De ki: \"Çalışın, yapın. Yaptıklarınızı Allah da, Resûlü de, mü’minler de göreceklerdir. Sonra gaybı da, görülen âlemi de bilen Allah’ın huzuruna döndürüleceksiniz. O da size bütün yapmakta olduğunuz şeyleri haber verecektir.\""},{"n":106,"t":"(Sefere katılmayanlardan) diğer bir kısmı da, Allah’ın emrine bırakılmışlardır. Bunlara ya azap eder ya da tövbelerini kabul eder. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":107,"t":"Bir de zararlı faaliyetlerde bulunmak, küfre yardım etmek, mü’minler arasına ayrılık sokmak için ve öteden beri Allah ve Resûlüne karşı savaşanlara üs olsun diye bir mescit yapanlar vardır. Bunlar, \"Bizim iyilikten başka hiçbir kasdımız yok\" diye de mutlaka yemin ederler. Ama Allah şâhitlik eder ki bunlar mutlaka yalancıdırlar."},{"n":108,"t":"Onun içinde asla namaz kılma. İlk günden temeli takva (Allah’a karşı gelmekten sakınmak) üzerine kurulan mescit (Kuba mescidi), içinde namaz kılmana elbette daha lâyıktır. Orada temizlenmeyi seven adamlar vardır. Allah da tertemiz olanları sever."},{"n":109,"t":"Binasını takva (Allah’a karşı gelmekten sakınmak) ve O’nun rızasını kazanmak temeli üzerine kuran kimse mi daha hayırlıdır, yoksa binasını çökmeye yüz tutmuş bir yarın kenarına kurup, onunla birlikte kendisi de cehennem ateşine yuvarlanan kimse mi? Allah, zalimler topluluğunu doğru yola erdirmez."},{"n":110,"t":"Kurmuş oldukları binaları, (ölüp de) kalpleri paramparça olmadıkça yüreklerinde sürekli bir kuşku olarak kalmaya devam edecektir. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":111,"t":"Şüphesiz Allah, mü’minlerden canlarını ve mallarını, kendilerine vereceği cennet karşılığında satın almıştır. Artık, onlar Allah yolunda savaşırlar, öldürürler ve ölürler. Allah, bunu Tevrat’ta, İncil’de ve Kur’an’da kesin olarak va’detmiştir. Kimdir sözünü Allah’tan daha iyi yerine getiren? O hâlde, yapmış olduğunuz bu alışverişten dolayı sevinin. İşte asıl bu büyük başarıdır."},{"n":112,"t":"Bunlar, tövbe edenler, ibâdet edenler, hamdedenler, oruç tutanlar, rükû’ ve secde edenler, iyiliği emredip kötülükten alıkoyanlar ve Allah’ın koyduğu sınırları hakkıyla koruyanlardır. Mü’minleri müjdele."},{"n":113,"t":"Cehennem ehli oldukları açıkça kendilerine belli olduktan sonra, -yakınları da olsalar- Allah’a ortak koşanlar için af dilemek ne Peygambere yaraşır, ne de mü’minlere."},{"n":114,"t":"İbrahim’in, babası için af dilemesi, sadece ona verdiği bir söz yüzündendi. Onun bir Allah düşmanı olduğu kendisine açıkça belli olunca, ondan uzaklaştı. Şüphesiz İbrahim, çok içli, yumuşak huylu bir kişiydi."},{"n":115,"t":"Doğru yola ilettikten sonra, sakınacakları şeyleri kendilerine apaçık bildirmedikçe, Allah bir toplumu saptıracak değildir. Şüphesiz Allah, her şeyi hakkıyla bilendir."},{"n":116,"t":"Şüphesiz göklerin ve yerin hükümranlığı yalnız Allah’ındır. O, diriltir ve öldürür. Sizin için Allah’tan başka ne bir dost, ne de bir yardımcı vardır."},{"n":117,"t":"Andolsun Allah; Peygamber ile içlerinden bir kısmının kalpleri eğrilmeğe yüz tuttuktan sonra, sıkıntılı bir zamanda ona uyan muhacirlerle ensarın tövbelerini kabul etmiştir. Evet, onların tövbelerini kabul etmiştir. Şüphesiz O, onlara çok şefkatli ve çok merhametlidir."},{"n":118,"t":"Savaştan geri kalan üç kişinin de tövbelerini kabul etti. Yeryüzü bütün genişliğine rağmen onlara dar gelmiş, vicdanları da kendilerini sıktıkça sıkmış, böylece Allah’(ın azabın)dan yine O’na sığınmaktan başka çare olmadığını anlamışlardı. Sonra (eski hâllerine) dönsünler diye, onların tövbelerini de kabul etti. Şüphesiz Allah, tövbeyi çok kabul eden ve çok merhamet edendir."},{"n":119,"t":"Ey iman edenler! Allah’a karşı gelmekten sakının ve doğrularla beraber olun."},{"n":120,"t":"Medine halkı ve onların çevresinde bulunan bedevîlere, Allah’ın Resûlünden geri kalmak, kendi canlarını onun canından üstün tutmak yaraşmaz. Çünkü onların, Allah yolunda çektikleri susuzluk, yorgunluk, açlık, kâfirleri öfkelendirmek üzere bir yere adım atmaları ve düşmana karşı herhangi bir başarı kazanmaları gibi hiçbir olay yoktur ki karşılığında kendilerine iyi bir amel(in sevabı) yazılmış olmasın. Şüphesiz Allah, iyilik yapanların mükâfatını elbette zayi etmez."},{"n":121,"t":"Allah yolunda küçük, büyük bir harcama yapmazlar ve bir vadiyi katetmezler ki (bunlar), Allah’ın, yaptıklarının daha güzeliyle kendilerini mükâfatlandırması için hesaplarına yazılmış olmasın."},{"n":122,"t":"(Ne var ki) mü’minlerin hepsi toptan seferber olacak değillerdir. Öyleyse onların her kesiminden bir grup da, din konusunda köklü ve derin bilgi sahibi olmak ve döndükleri zaman kavimlerini uyarmak için geri kalsa ya! Umulur ki sakınırlar."},{"n":123,"t":"Ey iman edenler! Kâfirlerden (öncelikle) yakınınızda olanlarla savaşın ve sizde bir sertlik bulsunlar. Bilin ki, Allah kendisine karşı gelmekten sakınanlarla beraberdir."},{"n":124,"t":"Herhangi bir sûre indirildiğinde, içlerinden, (alaylı bir şekilde) \"Bu hanginizin imanını artırdı?\" diyenler olur. İman etmiş olanlara gelince, inen sûre onların imanını artırmıştır. Onlar bunu birbirlerine müjdelerler."},{"n":125,"t":"Kalplerinde hastalık olanların ise, pisliklerine pislik katmış (küfürlerini artırmış), böylece kâfir olarak ölüp gitmişlerdir."},{"n":126,"t":"Görmüyorlar mı ki, onlar her yıl bir veya iki kere belâya çarptırılıp imtihan ediliyorlar. Sonra ne tövbe ederler, ne de ibret alırlar."},{"n":127,"t":"Bir sûre indirildi mi, \"Sizi bir kimse görüyor mu?\" diye birbirlerine göz ederler, sonra da sıvışıp giderler. Anlamayan bir toplum olmalarından dolayı, Allah onların kalplerini çevirmiştir."},{"n":128,"t":"Andolsun, size kendi içinizden öyle bir peygamber gelmiştir ki, sizin sıkıntıya düşmeniz ona çok ağır gelir. O, size çok düşkün, mü’minlere karşı da çok şefkatli ve merhametlidir."},{"n":129,"t":"Eğer yüz çevirirlerse de ki: \"Bana Allah yeter. O’ndan başka hiçbir ilâh yoktur. Ben ancak O’na tevekkül ettim. O, yüce Arş’ın sahibidir.\""}],[{"n":1,"t":"Elif, Lâm, Râ. Bunlar hikmet dolu Kitab’ın âyetleridir."},{"n":2,"t":"İçlerinden bir adama insanları uyar ve iman edenlere, Rableri katında kendileri için bir doğruluk makamı bulunduğunu müjdele diye vahyetmemiz, insanlar için şaşılacak bir şey mi oldu ki o kâfirler, \"Bu elbette apaçık bir sihirbazdır\" dediler?"},{"n":3,"t":"Şüphesiz ki Rabbiniz, gökleri ve yeri altı gün içinde (altı evrede) yaratan, sonra da Arş’a kurulup işleri yerli yerince düzene koyan Allah’tır. O’nun izni olmaksızın, hiç kimse şefaatçi olamaz. İşte O, Rabbiniz Allah’tır. O hâlde O’na kulluk edin. Hâlâ düşünmüyor musunuz?"},{"n":4,"t":"Hepinizin dönüşü ancak O’nadır. Allah, bunu bir gerçek olarak va’detmiştir. Şüphesiz O, başlangıçta yaratmayı yapar, sonra, iman edip salih ameller işleyenleri adaletle mükâfatlandırmak için onu (yaratmayı) tekrar eder. Kâfirlere gelince, inkâr etmekte olduklarından dolayı, onlar için kaynar sudan bir içki ve elem dolu bir azap vardır."},{"n":5,"t":"O, güneşi bir ışık (kaynağı), ayı da (geceleyin) bir aydınlık (kaynağı) kılan, yılların sayısını ve hesabı bilmeniz için ona menziller takdir edendir. Allah, bunları (boş yere değil) ancak gerçek ile (hikmeti gereğince) yaratmıştır. O, âyetlerini, bilen bir topluma ayrı ayrı açıklamaktadır."},{"n":6,"t":"Şüphesiz gece ve gündüzün ard arda değişmesinde, Allah’ın göklerde ve yeryüzünde yarattığı şeylerde, Allah’a karşı gelmekten sakınan bir toplum için pek çok deliller vardır."},{"n":"7-8","t":"Şüphesiz bize kavuşacağını ummayan ve dünya hayatına razı olup onunla yetinerek tatmin olan kimseler ile âyetlerimizden gafil olanlar var ya; işte onların kazanmakta oldukları günahlar yüzünden, varacakları yer ateştir."},{"n":9,"t":"(Fakat) iman edip salih ameller işleyenlere gelince, Rableri onları imanları sebebiyle, hidayete erdirir. Nimetlerle dolu cennetlerde altlarından ırmaklar akar."},{"n":10,"t":"Bunların oradaki duaları, \"Seni eksikliklerden uzak tutarız Allah’ım!\", aralarındaki esenlik dilekleri, \"selâm\"; dualarının sonu ise, \"Hamd âlemlerin Rabbi Allah’a mahsustur\" sözleridir."},{"n":11,"t":"Eğer Allah, insanlara onların hemen hayra kavuşmayı istedikleri gibi, şerri de acele verseydi, elbette onların ecellerine hükmolunurdu. İşte biz, bize kavuşmayı ummayanları, kendi azgınlıkları içinde bocalar hâlde bırakırız."},{"n":12,"t":"İnsana bir sıkıntı dokundu mu, gerek yan üstü yatarken, gerek otururken, gerekse ayakta iken (her hâlinde bu sıkıntıdan kurtulmak için) bize dua eder. Ama biz onun bu sıkıntısını ondan kaldırdık mı, sanki kendisine dokunan bir sıkıntı için bize hiç yalvarmamış gibi geçer gider. İşte o haddi aşanlara, yapmakta oldukları şeyler, böylece süslenmiş (hoş gösterilmiş)tir."},{"n":13,"t":"Andolsun, sizden önceki nice nesilleri peygamberleri, kendilerine apaçık deliller getirdikleri hâlde (yalanlayıp) zulmettikleri vakit helâk ettik. Onlar zaten inanacak değillerdi. İşte biz suçlu toplumu böyle cezalandırırız."},{"n":14,"t":"Sonra, nasıl davranacağınızı görelim diye, onların ardından yeryüzünde sizi onların yerine getirdik."},{"n":15,"t":"Âyetlerimiz kendilerine apaçık birer delil olarak okunduğunda, (öldükten sonra) bize kavuşmayı ummayanlar, \"Ya (bize) bundan başka bir Kur’an getir veya onu değiştir\" dediler. De ki: \"Onu kendiliğimden değiştirmem benim için olacak şey değildir. Ben ancak bana vahyolunana uyarım. Eğer Rabbime isyan edecek olursam, elbette büyük bir günün azabından korkarım.\""},{"n":16,"t":"De ki: \"Eğer Allah dileseydi, ben size onu okumazdım, Allah da size onu bildirmezdi. Ben sizin aranızda bundan (Kur’an’ın inişinden) önce (kırk yıllık) bir ömür yaşadım. Hiç düşünmüyor musunuz?\""},{"n":17,"t":"Artık, Allah’a karşı yalan uydurandan veya O’nun âyetlerini yalanlayandan daha zâlim kimdir? Şüphe yok ki (böyle) suçlular asla kurtuluşa ermezler."},{"n":18,"t":"Allah’ı bırakıp, kendilerine ne zarar, ne de fayda verebilecek şeylere tapıyorlar ve \"İşte bunlar Allah katında bizim şefaatçılarımızdır\" diyorlar. De ki: \"Siz, Allah’a göklerde ve yerde O’nun bilmediği bir şeyi mi haber veriyorsunuz!? O, onların ortak koştukları şeylerden uzaktır, yücedir.\"."},{"n":19,"t":"İnsanlar (başlangıçta tevhit inancına bağlı) tek bir ümmet idiler; sonra ayrılığa düştüler. Eğer (azabın ertelenmesiyle ilgili olarak ezelde) Rabbinden bir söz geçmiş olmasaydı, ayrılığa düştükleri hususlarda aralarında derhal hüküm verilir (işleri bitirilir)di."},{"n":20,"t":"\"Ona (peygambere) Rabbinden bir mucize indirilse ya!\" diyorlar. De ki: \"Gayb ancak Allah’ındır. Bekleyin, şüphesiz ben de sizinle birlikte bekleyenlerdenim!\""},{"n":21,"t":"Kendilerine dokunan bir sıkıntıdan sonra, insanlara bir rahmet (ferahlık ve mutluluk) tattırdığımız zaman, bir de bakarsın ki âyetlerimiz hakkında onların bir tuzakları (birtakım tertipleri ve asılsız iddiaları) vardır. De ki: \"Allah, daha çabuk tuzak kurar.\" Şüphesiz elçilerimiz (melekler) kurmakta olduğunuz tuzakları yazıyorlar."},{"n":22,"t":"O, sizi karada ve denizde gezdirip dolaştırandır. Öyle ki gemilerle denize açıldığınız ve gemilerinizin içindekilerle birlikte uygun bir rüzgârla seyrettiği, yolcuların da bununla sevindikleri bir sırada ona şiddetli bir fırtına gelip çatar ve her taraftan dalgalar onlara hücum eder de çepeçevre kuşatıldıklarını (batıp boğulacaklarını) anlayınca dini Allah’a has kılarak \"Andolsun, eğer bizi bundan kurtarırsan, mutlaka şükredenlerden olacağız\" diye Allah’a yalvarırlar."},{"n":23,"t":"Fakat onları kurtarınca, bir de bakarsın ki yeryüzünde haksız yere taşkınlık yapıyorlar. Ey İnsanlar! Sizin taşkınlığınız, sırf kendi aleyhinizedir. (Bununla) sadece dünya hayatının yararını elde edersiniz. Sonunda dönüşünüz bizedir. (Biz de) bütün yaptıklarınızı size haber vereceğiz."},{"n":24,"t":"Dünya hayatının hâli, ancak gökten indirdiğimiz bir yağmurun hâli gibidir ki, insanların ve hayvanların yedikleri yeryüzü bitkileri onunla yetişip birbirine karışmıştır. Nihayet yeryüzü (o bitkilerle) bütün zinet ve güzelliklerini alıp süslendiği ve sahipleri de onun üzerine (her türlü tasarrufa) kadir olduklarını sandıkları bir sırada, geceleyin veya güpegündüz ansızın ona emrimiz (afetimiz) geliverir de, bunları, sanki dün yerinde hiç yokmuş gibi, kökünden yolunmuş bir hâle getiririz. İşte düşünen bir toplum için, âyetleri böyle ayrı ayrı açıklıyoruz."},{"n":25,"t":"Allah, esenlik yurduna çağırır ve dilediğini doğru yola iletir."},{"n":26,"t":"Güzel iş yapanlara (karşılık olarak) daha güzeli ve bir de fazlası vardır. Onların yüzlerine ne bir kara bulaşır, ne de bir zillet. İşte onlar cennetliklerdir ve orada ebedî kalacaklardır."},{"n":27,"t":"Kötü işler yapmış olanlara gelince, bir kötülüğün cezası misliyledir ve onları bir zillet kaplayacaktır. Onları Allah’(ın azabın)dan koruyacak hiçbir kimse de yoktur. Sanki yüzleri, karanlık geceden parçalarla örtülmüştür. İşte onlar cehennemliklerdir. Onlar orada ebedî kalacaklardır."},{"n":28,"t":"Onların hepsini bir araya toplayacağımız, sonra da Allah’a ortak koşanlara, \"Siz de, ortaklarınız da yerinizde bekleyin\" diyeceğimiz günü düşün. Artık onların (ortak koştuklarıyla) aralarını tamamen ayırırız ve ortak koştukları derler ki: \"Siz bize ibadet etmiyordunuz.\""},{"n":29,"t":"\"Şimdi ise sizin bize tapınmanızdan habersiz olduğumuza dair sizinle bizim aramızda şâhit olarak Allah yeter.\""},{"n":30,"t":"Orada herkes daha önce yaptığı şeyleri yoklayacak (ve kendi akıbetini öğrenecek), hepsi de gerçek sahipleri olan Allah’a döndürülecekler ve (ilâh diye) uydurdukları şeyler (onları yüzüstü bırakıp) kendilerinden kaybolup gidecektir."},{"n":31,"t":"De ki: \"Sizi gökten ve yerden kim rızıklandırıyor? Ya da işitme ve görme yetisi üzerinde kim mutlak hâkimdir? Ölüden diriyi, diriden ölüyü kim çıkarıyor? İşleri kim yürütüyor?\" \"Allah\" diyecekler. De ki: \"O hâlde, Allah’a karşı gelmekten sakınmayacak mısınız?\""},{"n":32,"t":"İşte O, sizin gerçek Rabbiniz olan Allah’tır. Hak’tan sonra sadece sapıklık vardır. O hâlde, nasıl oluyor da (Hak’tan) döndürülüyorsunuz?"},{"n":33,"t":"Rabbinin yoldan çıkanlar hakkındaki, \"Onlar artık imana gelmezler\" sözü, işte böylece gerçekleşmiştir."},{"n":34,"t":"De ki: \"Allah’a koştuğunuz ortaklarınızdan, başlangıçta yaratmayı yapacak, sonra onu tekrarlayacak kimse var mı?\" De ki: \"Allah, başlangıçta yaratmayı yapar, sonra onu tekrar eder. O hâlde, nasıl oluyor da (haktan) çevriliyorsunuz?\""},{"n":35,"t":"De ki: \"Allah’a koştuğunuz ortaklarınızdan hakka iletecek olan bir kimse var mı?\" De ki: \"Hakka Allah iletir.\" Öyle ise, hakka ileten mi uyulmaya daha lâyıktır, yoksa iletilmedikçe doğru yolu bulamayan kimse mi? Ne oluyor size? Nasıl hüküm veriyorsunuz?\""},{"n":36,"t":"Onların çoğu ancak zannın ardından gider. Oysa zan, hak namına hiçbir şeyin yerini tutmaz. Şüphesiz Allah, onların yapmakta olduklarını hakkıyla bilendir."},{"n":37,"t":"Bu Kur’an, Allah’tan (indirilmiş olup) başkası tarafından uydurulmamıştır. Fakat o, kendinden öncekileri doğrulayıcı ve Kitab’ı (Allah’ın Levh-i Mahfuz’daki yazısını) açıklayıcı olarak, indirilmiştir. Bunda hiçbir şüphe yoktur. (O) âlemlerin Rabbi tarafındandır."},{"n":38,"t":"Yoksa onu (Muhammed kendisi) uydurdu mu diyorlar? De ki: \"Eğer doğru söyleyenler iseniz, haydi siz de onun benzeri bir sûre getirin ve Allah’tan başka, çağırabileceğiniz kim varsa onları da yardıma çağırın."},{"n":39,"t":"Hayır öyle değil. Onlar, ilmini kavrayamadıkları ve kendilerine yorumu gelmemiş olan bir şeyi yalanladılar. Kendilerinden öncekiler de (peygamberleri ve onlara indirilen kitapları) böyle yalanlamışlardı. Bak, o zalimlerin sonu nasıl oldu."},{"n":40,"t":"İçlerinden öylesi var ki ona (Kur’an’a) inanır; yine onlardan öylesi de var ki ona inanmaz. Rabbin bozguncuları daha iyi bilendir."},{"n":41,"t":"Eğer onlar seni yalanlarlarsa, de ki: \"Benim işim bana aittir; sizin işiniz de size. Siz benim yaptığımdan uzaksınız; ben de sizin yapmakta olduğunuz şeylerden uzağım (sorumlu değilim).\""},{"n":42,"t":"Onlardan sana kulak verenler de vardır. Fakat sağırlara, hele akılları da ermiyorsa, sen mi işittireceksin?"},{"n":43,"t":"İçlerinden sana bakanlar da vardır. Fakat körlere, hele gerçeği görmüyorlarsa, sen mi doğru yolu göstereceksin?"},{"n":44,"t":"Şüphesiz Allah, insanlara hiçbir şekilde zulmetmez; fakat insanlar kendilerine zulmederler."},{"n":45,"t":"Onları yeniden diriltip hepsini bir araya toplayacağı gün, sanki gündüzün bir saatinden başka kalmamışlar (yeni ayrılmışlar) gibi, aralarında tanışırlar. Allah’a kavuşmayı yalan sayanlar, ziyana uğramış ve doğru yolu bulamamışlardır."},{"n":46,"t":"Onları tehdit ettiğimiz şeylerin bir kısmını sana göstersek de, (göstermeden) seni vefat ettirsek de sonunda onların dönüşü bizedir. Sonra, Allah onların yapmakta olduklarına da şahittir."},{"n":47,"t":"Her ümmetin bir peygamberi vardır. Onların peygamberi geldiği (tebliğini yaptığı) zaman, aralarında adaletle hükmedilir ve onlara asla zulmedilmez."},{"n":48,"t":"\"Eğer doğru söyleyenler iseniz, (söyleyin) bu tehdit ne zaman (gerçekleşecek)?\" diyorlar."},{"n":49,"t":"De ki: \"Allah dilemedikçe, ben kendime bile ne bir zarar, ne de fayda verme gücüne sahibim. Her milletin bir eceli vardır. Onların eceli geldi mi, ne bir an geri kalabilirler ne de öne geçebilirler.\""},{"n":50,"t":"De ki: \"Söyleyin bakalım, O’nun azabı size geceleyin veya gündüzün (ansızın) gelecek olsa, suçlular bunun hangisini acele isterler?!\" (Bunların hiçbiri istenecek bir şey değildir.)"},{"n":51,"t":"(Onlara) \"Azap gerçekleştikten sonra mı O’na iman ettiniz? Şimdi mi!? Oysa siz onu acele istiyordunuz\" (denilecek)."},{"n":52,"t":"Sonra da zulmedenlere, \"Ebedî azabı tadın! Siz ancak vaktiyle kazanmakta olduğunuzun cezasına çarptırılıyorsunuz\" denilecektir."},{"n":53,"t":"\"O (azap) gerçek midir?\" diye senden haber soruyorlar. De ki: \"Evet, Rabbime andolsun ki o elbette gerçektir. Siz (bu konuda Allah’ı) âciz kılacak değilsiniz.\""},{"n":54,"t":"(O gün) zulmetmiş olan herkes, eğer yeryüzündeki her şeye sahip olsa, kendini kurtarmak için onu fidye verir. Azabı gördüklerinde, için için derin bir pişmanlık duyarlar. Onlara zulmedilmeksizin aralarında adaletle hükmedilir."},{"n":55,"t":"Bilesiniz ki, göklerdeki her şey, yerdeki her şey Allah’ındır. Yine bilesiniz ki, Allah’ın va’di haktır. Fakat onların çoğu bunu bilmez."},{"n":56,"t":"O, diriltir ve öldürür; ancak O’na döndürüleceksiniz."},{"n":57,"t":"Ey insanlar! İşte size Rabbinizden bir öğüt, kalplere bir şifâ ve inananlar için yol gösterici bir rehber ve rahmet (olan Kur’an) geldi."},{"n":58,"t":"De ki: \"Ancak Allah’ın lütuf ve rahmetiyle, yalnız bunlarla sevinsinler. Bu, onların toplayıp durduklarından daha hayırlıdır.\""},{"n":59,"t":"De ki: \"Allah’ın size indirdiği; sizin de, bir kısmını helâl, bir kısmını haram kıldığınız rızıklar hakkında ne dersiniz?\" De ki: \"Bunun için Allah mı size izin verdi, yoksa Allah’a iftira mı ediyorsunuz?\""},{"n":60,"t":"Allah’a karşı yalan uyduranların, kıyamet günü hakkındaki zanları nedir? Şüphesiz Allah insanlara karşı çok lütufkârdır, fakat onların çoğu (O’nun nimetlerine) şükretmezler."},{"n":61,"t":"(Ey Muhammed!) Sen hangi işte bulunursan bulun, ona dair Kur’an’dan ne okursan oku ve (ey insanlar, sizler de) hangi şeyi yaparsanız yapın, siz ona daldığınızda biz sizi mutlaka görürüz. Ne yerde, ne de gökte, zerre ağırlığınca, (hatta) bu zerreden daha küçük veya daha büyük olsun, hiçbir şey Rabbinden uzak (ve gizli) olmaz; hepsi muhakkak apaçık bir kitapta (Levh-i Mahfuz’da yazılı)dır."},{"n":62,"t":"Bilesiniz ki, Allah’ın dostlarına hiçbir korku yoktur. Onlar üzülmeyeceklerdir de."},{"n":63,"t":"Onlar iman etmiş ve Allah’a karşı gelmekten sakınmış olanlardır."},{"n":64,"t":"Dünya hayatında da, ahirette de onlar için müjde vardır. Allah’ın sözlerinde hiçbir değişme yoktur. İşte bu büyük başarıdır."},{"n":65,"t":"Onların (inkârcıların) sözleri seni üzmesin. Çünkü bütün güç Allah’ındır. O, hakkıyla işitendir, hakkıyla bilendir."},{"n":66,"t":"Bilesiniz ki göklerde kim var, yerde kim varsa, hep Allah’ındır. Allah’tan başkasına tapanlar (gerçekte) Allah’a koştukları ortaklara tâbi olmuyorlar. Şüphesiz onlar ancak zanna uyuyorlar ve sadece yalan söylüyorlar."},{"n":67,"t":"O, içinde dinlenesiniz diye geceyi sizin için (karanlık); gündüzü ise aydınlık kılandır. Şüphesiz bunda işiten bir toplum için ibretler vardır."},{"n":68,"t":"\"Allah, bir çocuk edindi\" dediler. O, bundan uzaktır. O, her bakımdan sınırsız zengindir. Göklerdeki her şey, yerdeki her şey O’nundur. Bu konuda elinizde hiçbir delil de yoktur. Allah’a karşı bilmediğiniz bir şeyi mi söylüyorsunuz?"},{"n":69,"t":"De ki: \"Allah hakkında yalan uyduranlar asla kurtuluşa eremezler.\""},{"n":70,"t":"Onlar için dünyada (geçici) bir yararlanma vardır. Sonra dönüşleri bizedir. Sonra da, inkâr etmekte olduklarına karşılık onlara şiddetli azabı tattıracağız."},{"n":71,"t":"Nûh’un haberini onlara oku. Hani o, bir vakit kavmine şöyle demişti: \"Ey kavmim! Eğer benim konumum ve Allah’ın âyetleriyle öğüt vermem size ağır geliyorsa, (biliniz ki) ben sadece Allah’a dayanıp güvenmişim. Artık siz de (bana) ne yapacağınızı ortaklarınızla beraber kararlaştırın ki, işiniz size dert olmasın! Bundan sonra bana hükmünüzü uygulayın; bana mühlet de vermeyin!"},{"n":72,"t":"Eğer yüz çeviriyorsanız, sizden zaten hiçbir ücret istemedim. Benim ücretim, ancak Allah’a aittir. Bana müslümanlardan olmam emredildi.\""},{"n":73,"t":"Onu yine de yalanladılar. Biz de onu ve onunla beraber gemide bulunanları kurtardık ve onları ötekilerin yerine geçirdik. Âyetlerimizi yalanlayanları da suda boğduk. Bak, uyarılan (fakat söz anlamayan)ların sonu nasıl oldu!"},{"n":74,"t":"Sonra, onun ardından birçok peygamberi kendi toplumlarına gönderdik. Onlara apaçık mucizeler getirdiler. Fakat onlar önceden yalanlamakta oldukları şeye inanacak değillerdi. İşte biz haddi aşanların kalplerini böylece mühürleriz."},{"n":75,"t":"Sonra bunların ardından Firavun ile ileri gelenlerine de Mûsâ ve Hârûn’u mucizelerimizle gönderdik. Ama büyüklük tasladılar ve suçlu bir toplum oldular."},{"n":76,"t":"Katımızdan kendilerine hak (mucize) gelince, \"Şüphesiz bu, apaçık bir sihirdir\" dediler."},{"n":77,"t":"Mûsâ: \"Size hak gelince, onun hakkında böyle mi diyorsunuz? Bu bir sihir midir? Oysa sihirbazlar, iflah olmazlar!\" dedi."},{"n":78,"t":"Dediler ki: \"Bizi atalarımızı üzerinde bulduğumuz yoldan döndüresin de yeryüzünde hâkimiyet (devlet) ikinizin eline geçsin diye mi bize geldin? Biz ikinize de inanmıyoruz.\""},{"n":79,"t":"Firavun, \"Bütün usta sihirbazları bana getirin\" dedi."},{"n":80,"t":"Sihirbazlar gelince Mûsâ onlara, \"Atacağınızı atın (hünerinizi ortaya koyun)\" dedi."},{"n":81,"t":"Sihirbazlar atacaklarını atınca, Mûsâ dedi ki: \"Sizin bu yaptığınız sihirdir. Allah, onu elbette boşa çıkaracaktır. Çünkü Allah, bozguncuların işini düzeltmez."},{"n":82,"t":"Suçluların hoşuna gitmese de, Allah, hakkı sözleriyle gerçekleştirecektir.\""},{"n":83,"t":"Firavun ve ileri gelenlerinin kötülük yapmaları korkusu ile kavminin küçük bir bölümünden başkası Mûsâ’ya iman etmedi. Çünkü Firavun, o yerde zorba bir kişi idi. O, gerçekten aşırı gidenlerdendi."},{"n":84,"t":"Mûsâ, \"Ey kavmim! Eğer siz gerçekten Allah’a iman etmişseniz, eğer O’na teslim olmuş kimseler iseniz, artık sadece O’na tevekkül edin\" dedi."},{"n":85,"t":"Onlar da şöyle dediler: \"Biz yalnız Allah’a tevekkül ettik. Ey Rabbimiz, bizi zalimler topluluğunun baskı ve şiddetine maruz bırakma!\""},{"n":86,"t":"Bizi rahmetinle o kâfirler topluluğundan kurtar."},{"n":87,"t":"Mûsâ’ya ve kardeşine, \"Kavminiz için Mısır’da (sığınak olarak) evler hazırlayın ve evlerinizi namaz kılınacak yerler yapın. Namazı dosdoğru kılın. Mü’minleri müjdele\" diye vahyettik."},{"n":88,"t":"Mûsâ, şöyle dedi: \"Ey Rabbimiz! Gerçekten sen Firavun’a ve onun ileri gelenlerine, dünya hayatında nice zinet ve mallar verdin. Ey Rabbimiz, yolundan saptırsınlar diye mi? Ey Rabbimiz, sen onların mallarını silip süpür ve kalplerine darlık ver, çünkü onlar elem dolu azabı görünceye kadar iman etmezler.\""},{"n":89,"t":"Allah da, \"Her ikinizin de duası kabul edildi. Öyleyse dürüst olmakta devam edin ve sakın bilmeyenlerin yolunda gitmeyin\" dedi."},{"n":90,"t":"İsrailoğullarını denizden geçirdik. Firavun da, askerleriyle birlikte zulmetmek ve saldırmak üzere, derhal onları takibe koyuldu. Nihayet boğulmak üzere iken, \"İsrailoğulları’nın iman ettiğinden başka hiçbir ilâh olmadığına inandım. Ben de müslümanlardanım\" dedi."},{"n":91,"t":"Şimdi mi?! Oysa daha önce isyan etmiş ve bozgunculardan olmuştun."},{"n":92,"t":"Biz de bugün bedenini, arkandan geleceklere ibret olman için, kurtaracağız. Çünkü insanlardan birçoğu âyetlerimizden gerçekten habersizdir."},{"n":93,"t":"Andolsun, biz İsrailoğullarını çok güzel bir yurda yerleştirdik ve onlara temiz rızıklar verdik. Kendilerine bilgi gelinceye kadar ayrılığa düşmediler. Şüphesiz ki, ayrılığa düşmüş oldukları şeyler hakkında Rabbin kıyamet günü aralarında hükmünü verecektir."},{"n":94,"t":"Eğer sana indirdiğimiz şeyden şüphe içinde isen, senden önce Kitab’ı (Tevrat’ı) okuyanlara sor. Andolsun ki, sana Rabbinden hak gelmiştir. O hâlde, sakın şüphe edenlerden olma!"},{"n":95,"t":"Sakın Allah’ın âyetlerini yalanlayanlardan da olma! Yoksa zarara uğrayanlardan olursun."},{"n":"96-97","t":"Şüphesiz, haklarında Rabbinin sözü (hükmü) gerçekleşmiş olanlar, kendilerine bütün mucizeler gelse bile, elem dolu azabı görünceye kadar inanmazlar."},{"n":98,"t":"Yûnus’un kavminden başka, keşke (azabı görmeden) iman edip, imanı kendisine fayda veren bir tek memleket halkı olsaydı! (Yûnus’un kavmi) iman edince, dünya hayatında (sürüklenebilecekleri) rezillik azabını onlardan uzaklaştırmış ve onları belli bir zamana kadar yararlandırmıştık."},{"n":99,"t":"Eğer Rabbin dileseydi, yeryüzünde bulunanların hepsi elbette topyekûn iman ederlerdi. Böyle iken sen mi mü’min olsunlar diye, insanları zorlayacaksın?"},{"n":100,"t":"Allah’ın izni olmadıkça, hiçbir kimse iman edemez. Allah, azabı akıllarını (güzelce) kullanmayanlara verir."},{"n":101,"t":"De ki: \"Göklerde ve yerde neler var, bir baksanıza.\" Fakat âyetler ve uyarılar, inanmayan bir topluma hiçbir fayda sağlamaz."},{"n":102,"t":"Onlar sadece, kendilerinden önce gelip geçenlerin başlarına gelen (azap dolu) günlerin benzerini mi bekliyorlar? De ki: \"Bekleyin bakalım, ben de sizinle birlikte bekleyenlerdenim.\""},{"n":103,"t":"Sonra resûllerimizi ve iman edenleri kurtarırız. (Ey Muhammed!) Aynı şekilde üzerimize bir hak olarak, inananları da kurtaracağız."},{"n":104,"t":"De ki: \"Ey insanlar, eğer benim dinimden herhangi bir şüphede iseniz, bilin ki ben, Allah’ı bırakıp da sizin taptıklarınıza tapmam, fakat sizin canınızı alacak olan Allah’a kulluk ederim. Bana mü’minlerden olmam emrolundu.\""},{"n":"105-106","t":"Yine bana şöyle emredildi: \"Hakka yönelen bir kimse olarak yüzünü dîne çevir. Sakın Allah’a ortak koşanlardan olma. Allah’ı bırakıp da sana ne fayda ve ne de zarar verebilecek olan şeylere yalvarma. Eğer böyle yaparsan, şüphesiz ki sen zâlimlerden olursun.\""},{"n":107,"t":"Eğer Allah sana herhangi bir zarar verecek olursa, bil ki onu, O’ndan başka giderebilecek yoktur. Eğer sana bir hayır dilerse, O’nun lütfunu engelleyebilecek de yoktur. O, bunu kullarından dilediğine eriştirir. O, çok bağışlayıcıdır, çok merhamet edicidir."},{"n":108,"t":"De ki: \"Ey insanlar, size Rabbinizden gerçek (Kur’an) gelmiştir. Artık kim doğru yola girerse, ancak kendisi için girer. Kim de saparsa ancak kendi aleyhine sapar. Ben sizden sorumlu değilim.\""},{"n":109,"t":"(Ey Muhammed!) Sana vahyolunana uy ve Allah hükmünü verinceye kadar sabret. O, hüküm verenlerin en hayırlısıdır."}],[{"n":"1-2","t":"Elif Lâm Râ. Bu Kur’an; âyetleri, hüküm ve hikmet sahibi (bulunan ve her şeyden) hakkıyla haberdar olan Allah tarafından muhkem (eksiksiz, sağlam ve açık) kılınmış, sonra da Allah’tan başkasına kulluk etmeyesiniz diye ayrı ayrı açıklanmış bir kitaptır. (De ki:) \"Şüphesiz ben size O’nun tarafından gönderilmiş bir uyarıcı ve müjdeleyiciyim.\""},{"n":3,"t":"Rabbinizden bağışlanma dileyin, sonra da O’na tövbe edin ki sizi belirlenmiş bir süreye (ömrünüzün sonuna) kadar güzel bir şekilde yararlandırsın ve her fazilet sahibine faziletinin karşılığını versin. Eğer yüz çevirirseniz, ben sizin adınıza büyük bir günün azabından korkuyorum."},{"n":4,"t":"Dönüşünüz ancak Allah’adır. O, her şeye hakkıyla gücü yetendir."},{"n":5,"t":"İyi bilin ki onlar, O’ndan gizlenmek için kalplerindeki düşmanlığı gizliyorlar. Yine iyi bilin ki, elbiselerine büründükleri zaman bile, Allah onların gizlediklerini de açığa vurduklarını da bilir. Çünkü O, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir."},{"n":6,"t":"Yeryüzünde hiçbir canlı yoktur ki, rızkı Allah’a ait olmasın. Her birinin (dünyada) duracakları yeri de, (öldükten sonra) emaneten konulacakları yeri de O bilir. Bunların hepsi açık bir kitapta (Levh-i Mahfuz’da yazılı)dır."},{"n":7,"t":"O, hanginizin amelinin daha güzel olacağı konusunda sizi imtihan için, henüz Arş’ı su üstünde iken gökleri ve yeri altı gün içinde (altı evrede) yaratandır. Böyle iken \"Ölümden sonra şüphesiz diriltileceksiniz\" desen, inkârcılar \"Mutlaka bu, apaçık bir büyüdür\" derler."},{"n":8,"t":"Andolsun, biz onlardan azabı belirli bir süreye kadar geciktirsek, o zaman da mutlaka \"Onu ne alıkoyuyor?\" derler. İyi bilin ki, azap onlara geleceği gün, kendilerinden bir daha uzaklaştırılmaz ve alay etmekte oldukları şey, kendilerini çepeçevre kuşatmış olur."},{"n":9,"t":"Eğer insana tarafımızdan bir rahmet (nimet) tattırır da, sonra bunu ondan çekip alırsak, şüphesiz o ümitsiz ve nankör oluverir."},{"n":10,"t":"Ama kendisine dokunan bir sıkıntıdan sonra, ona bir nimet tattırırsak mutlaka, \"Kötülükler benden gitti\" diyecektir. Çünkü o, şımarık ve böbürlenen biridir."},{"n":11,"t":"Ancak sabredip salih amel işleyenler böyle değildir. İşte onlar için bağışlanma ve büyük bir mükâfat vardır."},{"n":12,"t":"(Ey Muhammed!) Belki de sen, (müşriklerin) \"Ona bir hazine indirilseydi veya beraberinde bir melek gelseydi ya!\" demelerinden dolayı sana vahyolunanlardan bir kısmını göz ardı edeceksin ve o yüzden göğsün daralacak. Fakat sen, ancak bir uyarıcısın. Allah ise her şeye vekildir."},{"n":13,"t":"Yoksa \"onu (Kur’an’ı) uydurdu\" mu diyorlar? De ki: \"Eğer doğru söyleyenler iseniz, haydi Allah’tan başka gücünüzün yettiklerini de (yardıma) çağırıp, siz de onun gibi uydurma on sûre getirin.\""},{"n":14,"t":"Eğer size (bu konuda) cevap veremedilerse, bilin ki o (Kur’an) ancak Allah’ın ilmiyle indirilmiştir ve O’ndan başka hiçbir ilâh yoktur. Artık müslüman oluyor musunuz?"},{"n":15,"t":"Kim yalnız dünya hayatını ve onun zinetini isterse, biz onlara yaptıklarının karşılığını orada tastamam öderiz. Orada onlar bir eksikliğe uğratılmazlar."},{"n":16,"t":"İşte onlar, kendileri için âhirette ateşten başka bir şey olmayan kimselerdir. (Dünyada) yaptıkları şeyler, orada boşa gitmiştir. Zaten bütün yapmakta oldukları da boş şeylerdir."},{"n":17,"t":"Rabbi katından açık bir delile dayanan kimse, yalnız dünyalık isteyen kimse gibi midir? Kaldı ki, bu delili Rabbinden bir şahit (Kur’an) ve bir de ondan (Kur’an’dan) önce bir önder ve bir rahmet olarak (indirilmiş olan) Mûsâ’nın kitabı (Tevrat) desteklemektedir. İşte bunlar ona (Kur’an’a) inanırlar. Gruplardan her kim onu inkâr ederse, ateş onun varacağı yerdir. Ondan hiç şüphen olmasın. Şüphesiz o, Rabbin tarafından (bildirilmiş) gerçektir. Fakat insanların çoğu inanmazlar."},{"n":18,"t":"Kim Allah’a karşı yalan uydurandan daha zalimdir? İşte bunlar, Rablerine arz edilecekler ve şâhitler de, \"Rablerine karşı yalan söyleyenler işte bunlardır\" diyeceklerdir. Biliniz ki, Allah’ın lâneti zalimler üzerinedir."},{"n":19,"t":"Onlar (halkı) Allah yolundan alıkoyan ve onu eğri ve çelişkili göstermek isteyen kimselerdir. Hem de onlar ahireti inkâr edenlerin ta kendileridir."},{"n":20,"t":"Onlar yeryüzünde (Allah’ı) âciz bırakabilecek değillerdir. Onların Allah’tan başka sığınabilecekleri bir yardımcıları da yoktur. Azap onlar için kat kat artırılacaktır. Çünkü onlar (gerçekleri) işitmeğe tahammül edemiyorlar, hem de görmüyorlardı."},{"n":21,"t":"İşte bunlar, kendilerini ziyana uğratan kimselerdir. Uydurmakta oldukları şeyler de kendilerini yüz üstü bırakıp kaybolup gitmiştir."},{"n":22,"t":"Şüphesiz bunlar ahirette en çok ziyana uğrayanlardır."},{"n":23,"t":"İman edip, salih ameller işleyen ve Rablerine gönülden bağlananlara gelince, işte onlar cennetliklerdir. Onlar orada ebedî kalacaklardır."},{"n":24,"t":"Bu iki zümrenin durumu, kör ve sağır ile gören ve işiten kimseler gibidir. Bunların durumları hiç birbirlerine denk olur mu? Hâlâ düşünmez misiniz?"},{"n":25,"t":"Andolsun, biz Nûh’u kavmine peygamber olarak gönderdik. Onlara şöyle dedi: \"Ben sizin için apaçık bir uyarıcıyım.\""},{"n":26,"t":"\"Allah’tan başkasına ibadet ve kulluk etmeyin. Doğrusu ben sizin adınıza elem dolu bir günün azabından korkuyorum.\""},{"n":27,"t":"Kavminin inkâr eden ileri gelenleri, \"Biz, senin ancak bizim gibi bir insan olduğunu görüyoruz. İlk bakışta sana uyanların da ancak en aşağılıklarımızdan ibaret olduğunu görüyoruz. Sizin bize karşı herhangi bir üstünlüğünüzü de görmüyoruz. Aksine sizin yalancı kimseler olduğunuzu sanıyoruz\" dediler."},{"n":28,"t":"Nûh dedi ki: \"Ey Kavmim! Söyleyin bakalım; şâyet ben Rabbimden gelen apaçık bir delil üzerinde isem ve O, kendi katından bana bir rahmet vermiş de siz ona karşı kör kalmışsanız, onu istemediğiniz hâlde, biz sizi ona zorlayacak mıyız?\""},{"n":29,"t":"\"Ey kavmim! Buna karşı ben sizden herhangi bir mal da istemiyorum. Benim mükâfatım ancak Allah’a âittir. Ben o iman edenleri (teklifinize uyarak) kovacak da değilim. Çünkü onlar Rablerine kavuşacaklardır. Fakat ben sizin bilgisizce davranan bir toplum olduğunuzu görüyorum.\""},{"n":30,"t":"\"Ey kavmim! Eğer ben onları kovarsam, beni Allah’tan kim koruyabilir? Hiç düşünmüyor musunuz?\""},{"n":31,"t":"Size ben, \"Allah’ın hazineleri yanımdadır\", demiyorum; gaybı da bilmem. \"Ben bir meleğim\" de demiyorum. Sizin hor gördüğünüz kimseler için, \"Allah, onlara asla hiçbir hayır vermez\" de diyemem. Allah, onların içlerindekini daha iyi bilir. Böyle bir şey söylersem, o zaman ben gerçekten zâlimlerden olurum."},{"n":32,"t":"Dediler ki: \"Ey Nûh! Bizimle tartıştın ve tartışmayı uzattın. Eğer doğru söyleyenlerden isen, haydi kendisiyle bizi tehdit ettiğin azabı getir.\""},{"n":33,"t":"Nûh dedi ki: \"Onu size, dilerse ancak Allah getirir ve siz (Allah’ı) âciz bırakamazsınız.\""},{"n":34,"t":"Ben size öğüt vermek istesem de, eğer Allah sizi azdırmak istemişse, öğüdüm size fayda vermez. O, sizin Rabbinizdir ve O’na döndürüleceksiniz."},{"n":35,"t":"(Ey Muhammed!) Yoksa \"Onu (Kur’an’ı) kendisi uydurdu\" mu diyorlar? De ki: \"Eğer onu uydurmuşsam, suçum bana âittir. Ben de sizin işlemekte olduğunuz suçlardan uzağım.\""},{"n":36,"t":"Nûh’a vahyolundu ki: \"Kavminden daha önce iman etmiş olanlardan başka, artık hiç kimse iman etmeyecek. O hâlde, onların yapmakta oldukları şeylerden dolayı üzülme.\""},{"n":37,"t":"\"Gözetimimiz altında ve vahyimize göre gemiyi yap. Zulmedenler hakkında bana bir şey söyleme. Çünkü onlar suda boğulacaklardır.\""},{"n":38,"t":"(Nûh) gemiyi yapıyordu. Kavminden ileri gelenler her ne zaman yanına uğrasalar, onunla alay ediyorlardı. Dedi ki: \"Bizimle alay ediyorsanız, sizin bizimle alay ettiğiniz gibi biz de sizinle alay edeceğiz.\""},{"n":39,"t":"Artık, geldiği kimseyi rezil eden azabın kime geleceğini, kimin üzerine sürekli bir azabın ineceğini ileride anlayacaksınız."},{"n":40,"t":"Nihayet emrimiz gelip, tandır kaynamaya başlayınca (sular coşup taşınca) Nûh’a dedik ki: \"Her cins canlıdan (erkekli dişili) birer çift, bir de kendileri hakkında daha önce hüküm verilmiş olanlar dışındaki âilen ile iman edenleri ona yükle.\" Ama, onunla beraber sadece pek az kimse iman etmişti."},{"n":41,"t":"(Nûh), \"Binin ona. Onun yüzüp gitmesi de durması da Allah’ın adıyladır. Şüphesiz Rabbim çok bağışlayandır, çok merhamet edendir.\" dedi."},{"n":42,"t":"Gemi, dağlar gibi dalgalar arasında onları götürüyordu. Nûh, ayrı bir yere çekilmiş olan oğluna, \"Yavrucuğum, bizimle beraber sen de bin, inkârcılarla birlikte olma\" diye seslendi."},{"n":43,"t":"O, \"Ben, kendimi sudan koruyacak bir dağa sığınacağım\" dedi. Nûh, \"Bugün Allah’ın rahmet ettikleri hariç, O’nun azabından korunacak hiç kimse yoktur\" dedi. Derken aralarına dalga giriverdi de oğlu boğulanlardan oldu."},{"n":44,"t":"\"Ey yeryüzü! Yut suyunu. Ey gök! Tut suyunu\" denildi. Su çekildi, iş bitirildi. Gemi de Cûdî’ye oturdu ve \"Zalimler topluluğu, Allah’ın rahmetinden uzak olsun!\" denildi."},{"n":45,"t":"Nûh, Rabbine seslenip şöyle dedi: \"Rabbim! Şüphesiz oğlum da âilemdendir. Senin va’din elbette gerçektir. Sen de hükmedenlerin en iyi hükmedenisin.\""},{"n":46,"t":"Allah, \"Ey Nûh! O, asla senin âilenden değildir. Onun yaptığı, iyi olmayan bir iştir. O hâlde, hakkında hiçbir bilgin olmayan şeyi benden isteme. Ben, sana cahillerden olmamanı öğütlerim\" dedi."},{"n":47,"t":"Nûh, \"Rabbim! Şüphesiz ben senden hakkında bilgim olmayan şeyi istemekten sana sığınırım. Eğer beni bağışlamaz ve bana acımazsan, şüphesiz ziyana uğrayanlardan olurum\" dedi."},{"n":48,"t":"Ona denildi ki: \"Ey Nûh! Sana ve seninle birlikte bulunanlardan birçok ümmete bizden esenlik ve bereketlerle (gemiden) in. Daha birtakım ümmetler de olacak ki, biz onları (dünyada) yararlandıracağız. Sonra da bizden kendilerine elem dolu bir azap dokunacak.\""},{"n":49,"t":"İşte bunlar, sana vahyettiğimiz gayb haberlerindendir. Bundan önce onları ne sen biliyordun, ne de kavmin. O hâlde sabret. Çünkü (iyi) sonuç, Allah’a karşı gelmekten sakınanların olacaktır."},{"n":50,"t":"Âd kavmine de kardeşleri Hûd’u gönderdik. Hûd, şöyle dedi: \"Ey kavmim! Allah’a kulluk edin. O’ndan başka sizin hiçbir ilâhınız yoktur. Siz, sadece iftira ediyorsunuz.\""},{"n":51,"t":"\"Ey kavmim! Ben buna karşı sizden bir ücret istemiyorum. Benim ücretim, ancak beni yaratana âittir. Hâlâ aklınızı kullanmayacak mısınız?\""},{"n":52,"t":"\"Ey kavmim! Rabbinizden bağışlanma dileyin, sonra O’na tövbe edin ki, üzerinize bol bol yağmur göndersin ve gücünüze güç katsın. Günahkârlar olarak yüz çevirmeyin.\""},{"n":53,"t":"Dediler ki: \"Ey Hûd! Sen bize açık bir mucize getirmedin. Biz de senin sözünle ilâhlarımızı bırakacak değiliz. Biz sana iman edecek de değiliz.\""},{"n":"54-55","t":"Biz sadece şunu söyleriz: \"Seni, ilâhlarımızdan biri fena çarpmış.\" Hûd, dedi ki: \"İşte ben Allah’ı şâhit tutuyorum. Siz de şâhit olun ki, ben sizin Allah’ı bırakıp da O’na ortak koştuğunuz şeylerden uzağım. Haydi hepiniz toptan bana tuzak kurun, sonra da bana göz açtırmayın.\""},{"n":56,"t":"\"İşte ben, hem benim, hem sizin Rabbiniz olan Allah’a dayandım. Yeryüzünde bulunan hiçbir canlı yoktur ki, Allah, onun perçeminden tutmuş olmasın. Şüphesiz Rabbim dosdoğru bir yol üzerindedir.\""},{"n":57,"t":"\"Eğer yüz çevirirseniz; bilin ki ben, benimle gönderileni size tebliğ ettim. Rabbim (dilerse) sizden başka bir kavmi sizin yerinize getirir ve siz O’na bir zarar veremezsiniz. Şüphesiz Rabbim, her şeyi koruyup gözetendir.\""},{"n":58,"t":"Helâk emrimiz gelince, Hûd’u ve beraberindeki iman etmiş olanları, tarafımızdan bir rahmetle kurtardık. Onları ağır bir azaptan kurtardık."},{"n":59,"t":"İşte Âd kavmi! Rablerinin âyetlerini inkâr ettiler. O’nun peygamberlerine karşı geldiler ve inatçı her zorbanın emrine uydular!"},{"n":60,"t":"Onlar, hem bu dünyada, hem de kıyamet gününde lânete uğratıldılar. Biliniz ki Âd kavmi, Rablerini inkâr etti. (Yine) biliniz ki Hûd’un kavmi Âd, Allah’ın rahmetinden uzaklaştı."},{"n":61,"t":"Semûd kavmine de kardeşleri Salih’i peygamber gönderdik. Dedi ki: \"Ey kavmim! Allah’a kulluk edin. Sizin O’ndan başka hiçbir ilâhınız yok. O, sizi yeryüzünden (topraktan) yarattı ve sizi oranın imarında görevli (ve buna donanımlı) kıldı. Öyle ise O’ndan bağışlanma dileyin; sonra da O’na tövbe edin. Şüphesiz Rabbim yakındır ve dualara cevap verendir."},{"n":62,"t":"Onlar şöyle dediler: \"Ey Salih! Bundan önce sen, aramızda ümit beslenen bir kimseydin. Şimdi babalarımızın taptıklarına tapmamızı bize yasaklıyor musun? Şüphesiz, biz senin bizi çağırdığın şeyden derin bir şüphe içindeyiz.\""},{"n":63,"t":"Salih, dedi ki: \"Ey kavmim! Söyleyin bakayım, eğer ben Rabbim tarafından apaçık bir delil üzerinde isem ve bana tarafından bir rahmet (peygamberlik) vermişse, O’na karşı geldiğim takdirde beni Allah’tan kim koruyabilir? Demek ki, zarara uğratmaktan başka bana katkınız olmaz.\""},{"n":64,"t":"\"Ey kavmim! İşte size mucize olarak Allah’ın dişi bir devesi. Bırakın onu, Allah’ın arzında yayılıp otlasın. Ona kötülük dokundurmayın, yoksa sizi yakın bir azap yakalar.\""},{"n":65,"t":"Derken onu kestiler. Salih, dedi ki: \"Yurdunuzda üç gün daha yaşayın. (Sonra helâk olacaksınız.) İşte bu, yalanlanamayacak bir tehdittir.\""},{"n":66,"t":"(Helâk) emrimiz geldiğinde Salih’i ve beraberindeki iman etmiş olanları tarafımızdan bir rahmetle helâktan ve o günün rezilliğinden kurtardık. Şüphesiz Rabbin mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":67,"t":"Zulmedenleri o korkunç uğultulu ses yakaladı da yurtlarında diz üstü çökekaldılar."},{"n":68,"t":"Sanki orada hiç yaşamamışlardı. Biliniz ki Semûd kavmi Rablerini inkâr etti. (Yine) biliniz ki Semûd kavmi Allah’ın rahmetinden uzaklaştı."},{"n":69,"t":"Andolsun, elçilerimiz (melekler), İbrahim’e müjde getirip \"Selâm sana!\" dediler. O, \"Size de selâm\" dedi ve kızartılmış bir buzağı getirmekte gecikmedi."},{"n":70,"t":"Ellerini yemeğe uzatmadıklarını görünce, onları yadırgadı ve onlardan dolayı içinde bir korku duydu. Dediler ki: \"Korkma, çünkü biz Lût kavmine gönderildik.\""},{"n":71,"t":"İbrahim’in karısı ayakta idi. (Bu sözleri duyunca) güldü. Ona da İshak’ı müjdeledik; İshak’ın arkasından da Yakûb’u."},{"n":72,"t":"Karısı, \"Vay başıma gelenler! Ben bir kocakarı ve bu kocam da bir ihtiyar iken çocuk mu doğuracağım? Gerçekten bu, çok şaşılacak bir şey!\" dedi."},{"n":73,"t":"Melekler, \"Allah’ın emrine mi şaşıyorsun? Allah’ın rahmeti ve bereketi size olsun ey (peygamber ocağının) ev halkı! Şüphesiz O, övülmeye lâyıktır, şanı yücedir.\" dediler."},{"n":74,"t":"İbrahim’in korkusu gidip, kendisine müjde gelince Lût kavmi hakkında bizim (elçilerimiz)le tartışmaya başladı."},{"n":75,"t":"Çünkü İbrahim çok içli ve Allah’a yönelen bir kimseydi."},{"n":76,"t":"Elçilerimiz, \"Ey İbrahim bundan vazgeç! Çünkü Rabbinin emri kesin olarak gelmiştir. Şüphesiz onlara geri döndürülemeyecek bir azap gelecektir\" dediler."},{"n":77,"t":"Elçilerimiz Lût’a gelince onların yüzünden üzüldü, göğsü daraldı ve \"Bu çok zor bir gün\" dedi."},{"n":78,"t":"Kavmi, (konuklarıyla çirkin ilişkide bulunmak üzere) ona doğru koşa koşa geldiler. Zaten onlar önceden de bu tür çirkin işleri yapıyorlardı. Lût, dedi ki: \"Ey Kavmim! İşte kızlarım. Onlar(la nikâhlanmanız) sizin için daha temizdir. Allah’a karşı gelmekten sakının ve konuklarıma karşı beni rezil etmeyin. İçinizde hiç aklı başında bir adam yok mu?\""},{"n":79,"t":"Onlar, \"İyi biliyorsun ki kızlarında bizim gözümüz yok. Sen bizim ne istediğimizi çok iyi biliyorsun\" dediler."},{"n":80,"t":"(Lût da:) \"Keşke size karşı (koyacak) bir gücüm olsaydı, ya da sağlam bir desteğe dayanabilseydim\" dedi."},{"n":81,"t":"Konukları şöyle dedi: \"Ey Lût! Biz Rabbinin elçileriyiz. Onlar sana asla ulaşamayacaklar. Geceleyin bir vakitte aileni al götür. İçinizden kimse ardına bakmasın. Ancak karın müstesna. (Onu bırak.) Çünkü onların (kavminin) başına gelecek olan azap, onun başına da gelecektir. Onların azabla buluşma zamanı sabahtır. Sabah yakın değil midir?!\""},{"n":"82-83","t":"(Azap) emrimiz gelince oranın altını üstüne getirdik. Üzerine de Rabbinin katında işaretlenmiş pişirilmiş balçıktan taşlar yağdırdık. Bunlar zalimlerden uzak değildir."},{"n":84,"t":"Medyen halkına da kardeşleri Şu’ayb’ı peygamber gönderdik. O, şöyle dedi: \"Ey kavmim! Allah’a kulluk edin. Sizin O’ndan başka hiçbir ilâhınız yoktur. Ölçüyü ve tartıyı eksik yapmayın. Ben sizi bolluk içinde görüyorum. Ben sizin adınıza kuşatıcı bir günün azabından korkuyorum.\""},{"n":85,"t":"\"Ey kavmim! Ölçüyü ve tartıyı adaletle tam yapın. İnsanların eşyalarını (mallarını ve haklarını) eksiltmeyin. Yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.\""},{"n":86,"t":"\"Eğer inanan kimselerseniz Allah’ın bıraktığı helâl kazanç sizin için daha hayırlıdır. Ben sizin başınızda bir bekçi değilim.\""},{"n":87,"t":"Dediler ki: \"Ey Şu’ayb! Babalarımızın taptığını, yahut mallarımız hakkında dilediğimizi yapmayı terk etmemizi sana namazın mı emrediyor. Oysa sen gerçekten yumuşak huylu ve aklı başında bir adamsın.\""},{"n":88,"t":"Şu’ayb, şöyle dedi: \"Ey kavmim! Söyleyin bakayım, ya ben Rabbimden gelen açık bir delil üzere isem ve katından bana güzel bir rızık vermişse!. Ben size yasakladığımı kendim yapmak istemiyorum. Ben sadece gücüm yettiğince (sizi) düzeltmek istiyorum. Başarım ancak Allah’ın yardımı iledir. Ben sadece O’na tevekkül ettim ve sadece O’na yöneliyorum.\""},{"n":89,"t":"\"Ey Kavmim! Bana karşı olan düşmanlığınız, Nûh kavminin veya Hûd kavminin yahut Salih kavminin başına gelenin benzeri gibi bir felaketi sakın sizin de başınıza getirmesin. (Ve unutmayın ki) Lût kavmi sizden uzak değildir.\""},{"n":90,"t":"\"Rabbinizden bağışlanma dileyin, sonra O’na tövbe edin. Şüphesiz Rabbim çok merhametlidir, çok sevendir.\""},{"n":91,"t":"Dediler ki: \"Ey Şu’ayb! Dediklerinin çoğunu anlamıyoruz. Hem biz seni aramızda zayıf görüyoruz. Eğer kabilen olmasaydı, seni taşa tutardık. Zaten sen bizce itibarlı biri değilsin.\""},{"n":92,"t":"Şu’ayb, şöyle dedi: \"Ey kavmim! Benim kabilem sizce Allah’tan daha itibarlı mı ki, O’na sırt çevirdiniz. Şüphesiz Rabbim sizin yaptıklarınızı kuşatmıştır.\""},{"n":93,"t":"\"Ey Kavmim! Elinizden geleni yapın. Şüphesiz ben de (elimden geleni) yapacağım. Rezil edici azabın kime geleceğini ve kimin yalancı olduğunu yakında bileceksiniz. Gözleyin. Şüphesiz ben de sizinle beraber gözlüyorum.\""},{"n":94,"t":"(Azap) emrimiz gelince, Şu’ayb’ı ve onunla birlikte iman edenleri, katımızdan bir rahmetle kurtardık. Zulmedenleri ise o korkunç (uğultulu) ses yakaladı da yurtlarında diz üstü çökekaldılar."},{"n":95,"t":"Sanki orada hiç yaşamamışlardı. Biliniz ki Semûd kavmi Allah’ın rahmetinden uzaklaştığı gibi Medyen halkı da uzaklaştı."},{"n":"96-97","t":"Andolsun, biz Mûsâ’yı âyetlerimizle ve apaçık bir mucize ile Firavun’a ve onun ileri gelen adamlarına peygamber gönderdik de ileri gelenler Firavun’un emrine uydular. Hâlbuki Firavun’un emri doğru değildi."},{"n":98,"t":"Firavun, kıyamet gününde kavminin önüne geçecek ve onları ateşe götürecektir. Ne kötü varış yeridir orası!"},{"n":99,"t":"Onlar, hem bu dünyada, hem de kıyamet gününde lânete uğratıldılar. Ne kötü destektir onlara verilen destek!"},{"n":100,"t":"(Ey Muhammed!) Bunlar o memleketlerin haberlerinden bazılarıdır. Onları sana anlatıyoruz. Onlardan ayakta duranlar da var, yıkılıp gidenler de."},{"n":101,"t":"Biz onlara zulmetmedik. Fakat onlar kendilerine zulmettiler. Rabbinin azap emri gelince, Allah’ı bırakıp da taptıkları ilâhları kendilerine hiçbir fayda sağlamadı. İlâhları onların sadece ziyanlarını artırdı."},{"n":102,"t":"Zulme sapmış memleketlerin halkını yakaladığında, Rabbinin yakalaması işte böyledir! Şüphesiz O’nun yakalaması can yakıcı ve şiddetlidir."},{"n":103,"t":"Şüphesiz, ahiret azabından korkanlar için bunda bir ibret vardır. Bu, insanların (hesap ve ceza için) toplanacakları bir gündür. Bu, herkesin toplanıp bir araya geleceği bir gündür."},{"n":104,"t":"Biz onu ancak belirli bir zamana kadar erteliyoruz."},{"n":105,"t":"O gün geldiği zaman Allah’ın izni olmadan hiçbir kimse konuşamaz. Onlardan mutsuz (cehennemlik) olanlar da vardır, mutlu (cennetlik) olanlar da."},{"n":106,"t":"Mutsuz olanlara gelince; cehennemdedirler. Onların orada şiddetli bir soluyuşları vardır."},{"n":107,"t":"Onlar, gökler ve yerler durdukça orada ebedî olarak kalacaklardır. Ancak Rabbinin dilemesi başka. Şüphesiz Rabbin istediğini yapandır."},{"n":108,"t":"Mutlu olanlara gelince, gökler ve yerler durdukça içinde ebedî kalmak üzere cennettedirler. Ancak Rabbinin dilemesi başka. Bu, onlara ardı kesilmez bir lütuf olarak verilmiştir."},{"n":109,"t":"(Ey Muhammed!) Şunların taptıkları şeylerin batıl olduğu konusunda şüpheye düşme. Onlar sadece, daha önce babalarının taptığı gibi tapıyorlar. Şüphesiz biz onlara (azaptan) paylarını eksiksiz olarak tastamam vereceğiz."},{"n":110,"t":"Andolsun, biz Mûsâ’ya Kitab’ı (Tevrat’ı) vermiştik de onun hakkında ayrılığa düşülmüştü. Eğer daha önce Rabbinin bir sözü geçmemiş olsaydı, elbette aralarında hüküm verilirdi. Onlar da (müşrikler de) o Kur’an hakkında derin bir şüphe içindedirler."},{"n":111,"t":"Şüphesiz Rabbin onların her birine, yaptıklarının karşılığını tastamam verecektir. Şüphesiz Rabbin onların yaptıklarından hakkıyla haberdardır."},{"n":112,"t":"Öyle ise emrolunduğun gibi dosdoğru ol. Beraberindeki tövbe edenler de dosdoğru olsunlar. Hak ve adalet ölçülerini aşmayın. Şüphesiz O, yaptıklarınızı hakkıyla görür."},{"n":113,"t":"Zulmedenlere meyletmeyin. Yoksa size de ateş dokunur. Sizin Allah’tan başka dostlarınız yoktur. Sonra size yardım da edilmez."},{"n":114,"t":"(Ey Muhammed!) Gündüzün iki tarafında ve gecenin gündüze yakın vakitlerinde namaz kıl. Çünkü iyilikler kötülükleri giderir. Bu, öğüt alanlar için bir öğüttür."},{"n":115,"t":"Sabret! Çünkü, Allah iyilik edenlerin mükâfatını zayi etmez."},{"n":116,"t":"Sizden önceki nesillerden aklı başında kimseler (insanları) yeryüzünde bozgunculuk yapmaktan alıkoysalardı ya! Ancak içlerinden kendilerini kurtardığımız pek az kimse bunu yapmıştı. Zulmedenler ise içinde şımartıldıkları refahın ardına düştüler ve günahkâr kimseler oldular."},{"n":117,"t":"Rabbin, halkları salih ve ıslah edici kimseler iken memleketleri zulmederek helâk etmez."},{"n":"118-119","t":"Rabbin dileseydi, insanları (aynı inanca bağlı) tek bir ümmet yapardı. Fakat Rabbinin merhamet ettikleri müstesna, onlar ihtilafa devam edeceklerdir. Zaten onları bunun için yarattı. Rabbinin, \"Andolsun ki cehennemi hem cinlerden, hem insanlardan (suçlularla) dolduracağım\" sözü kesinleşti."},{"n":120,"t":"(Ey Muhammed!) Peygamberlerin haberlerinden, kendileriyle senin kalbini pekiştirdiğimiz her bir haberi sana aktarıyoruz. Bunlarda, sana hak, mü’minlere de bir öğüt ve hatırlatma gelmiştir."},{"n":121,"t":"İman etmeyenlere de ki: \"Elinizden geleni yapın, biz de yapacağız.\""},{"n":122,"t":"\"Bekleyin, biz de bekleyeceğiz.\""},{"n":123,"t":"Göklerin ve yerin gaybını bilmek Allah’a mahsustur. Bütün işler O’na döndürülür. Öyle ise O’na kulluk et ve O’na tevekkül et. Rabbin yaptıklarınızdan habersiz değildir."}],[{"n":1,"t":"Elif Lâm Râ. Bunlar, apaçık Kitab’ın âyetleridir."},{"n":2,"t":"Biz onu, akıl erdiresiniz diye Arapça bir Kur’an olarak indirdik."},{"n":3,"t":"Sana bu Kur’an’ı vahyetmekle kıssaların en güzelini anlatıyoruz. Hâlbuki daha önce sen bunlardan habersiz idin."},{"n":4,"t":"Hani Yûsuf, babasına \"Babacığım! Gerçekten ben (rüyada) on bir yıldız, güneşi ve ayı gördüm. Gördüm ki onlar bana boyun eğiyorlardı\" demişti."},{"n":5,"t":"Babası, şöyle dedi: \"Yavrucuğum! Rüyanı kardeşlerine anlatma. Yoksa, sana tuzak kurarlar. Çünkü şeytan, insanın apaçık düşmanıdır.\""},{"n":6,"t":"\"İşte Rabbin seni böylece seçecek, sana (rüyada görülen) olayların yorumunu öğretecek ve daha önce ataların İbrahim ve İshak’a nimetlerini tamamladığı gibi sana ve Yakub soyuna da tamamlayacaktır. Şüphesiz Rabbin hakkıyla bilendir, hüküm ve hikmet sahibidir.\""},{"n":7,"t":"Andolsun, Yûsuf ve kardeşlerinde (hakikati arayıp) soranlar için ibretler vardır."},{"n":8,"t":"Kardeşleri dediler ki: \"Biz güçlü bir topluluk olduğumuz hâlde, Yûsuf ve kardeşi (Bünyamin) babamıza bizden daha sevgilidir. Doğrusu babamız açık bir yanılgı içindedir.\""},{"n":9,"t":"\"Yûsuf’u öldürün veya onu bir yere atın ki babanız sadece size yönelsin. Ondan sonra (tövbe edip) salih kimseler olursunuz.\""},{"n":10,"t":"Onlardan bir sözcü, \"Yûsuf’u öldürmeyin, onu bir kuyunun dibine bırakın ki geçen kervanlardan biri onu bulup alsın. Eğer yapacaksanız böyle yapın\" dedi."},{"n":11,"t":"Babalarına şöyle dediler: \"Ey babamız! Yûsuf hakkında bize neden güvenmiyorsun? Hâlbuki biz onun iyiliğini isteyen kişileriz.\""},{"n":12,"t":"\"Yarın onu bizimle beraber gönder de gezip oynasın. Şüphesiz biz onu koruruz.\""},{"n":13,"t":"Babaları, \"Doğrusu onu götürmeniz beni üzer, siz ondan habersiz iken onu kurt yer, diye korkuyorum.\""},{"n":14,"t":"Onlar da, \"Andolsun biz kuvvetli bir topluluk iken onu kurt yerse (o takdirde) biz gerçekten hüsrana uğramış oluruz\" dediler."},{"n":15,"t":"Yûsuf’u götürüp kuyunun dibine bırakmaya karar verdikleri zaman biz de ona, \"Andolsun, (senin Yûsuf olduğunun) farkında değillerken onların bu işlerini sen kendilerine haber vereceksin\" diye vahyettik."},{"n":16,"t":"(Yûsuf’u kuyuya bırakıp) akşamleyin ağlayarak babalarına geldiler."},{"n":17,"t":"\"Ey babamız! Biz yarışa girmiştik. Yûsuf’u da eşyamızın yanında bırakmıştık. (Bir de ne görelim) onu kurt yemiş. Her ne kadar doğru söylesek de sen bize inanmazsın\" dediler."},{"n":18,"t":"Bir de üzerine, sahte bir kan bulaştırılmış gömleğini getirdiler. Yakub dedi ki: \"Hayır! Nefisleriniz sizi aldatıp böyle bir işe sürükledi. Artık bana düşen, güzel bir sabırdır. Anlattıklarınıza karşı yardımı istenilecek de ancak Allah’tır.\""},{"n":19,"t":"Bir kervan gelmiş, sucularını suya göndermişlerdi. Sucu kovasını kuyuya salınca, \"Müjde! Müjde! İşte bir oğlan!\" dedi. Onu alıp bir ticaret malı olarak sakladılar. Oysa Allah, onların yaptıklarını biliyordu."},{"n":20,"t":"Onu ucuz bir fiyata, birkaç dirheme sattılar. Zaten ona değer vermiyorlardı."},{"n":21,"t":"Onu satın alan Mısırlı kişi, hanımına dedi ki: \"Ona iyi bak. Belki bize yararı dokunur veya onu evlat ediniriz.\" İşte böylece biz Yûsuf’u o yere (Mısır’a) yerleştirdik ve ona (rüyadaki) olayların yorumunu öğretelim diye böyle yaptık. Allah, işinde galiptir, fakat insanların çoğu bunu bilmezler."},{"n":22,"t":"Olgunluk çağına erişince, ona hikmet ve ilim verdik. İşte biz, iyi davrananları böyle mükâfatlandırırız."},{"n":23,"t":"Evinde bulunduğu kadın (gönlünü ona kaptırıp) ondan arzuladığı şeyi elde etmek istedi ve kapıları kilitleyerek, \"Haydi gelsene!\" dedi. O ise, \"Allah’a sığınırım, çünkü o (kocan) benim efendimdir, bana iyi baktı. Şüphesiz zalimler kurtuluşa eremezler\" dedi."},{"n":24,"t":"Andolsun, kadın ona (göz koyup) istek duymuştu. Eğer Rabbinin delilini görmemiş olsaydı, Yûsuf da ona istek duyacaktı. Biz, ondan kötülüğü ve fuhşu uzaklaştırmak için işte böyle yaptık. Çünkü o, ihlâsa erdirilmiş kullarımızdandı."},{"n":25,"t":"İkisi de kapıya koştular. Kadın, Yûsuf’un gömleğini arkadan yırttı. Kapının yanında hanımın efendisine rastladılar. Kadın dedi ki: \"Senin ailene kötülük yapmak isteyenin cezası, ancak zindana atılmak veya can yakıcı bir azaptır.\""},{"n":26,"t":"Yûsuf, \"O, benden arzusunu elde etmek istedi\" dedi. Kadının ailesinden bir şahit de şöyle şahitlik etti: \"Eğer onun gömleği önden yırtılmışsa, kadın doğru söylemiştir, o (Yûsuf) yalancılardandır.\""},{"n":27,"t":"\"Eğer gömleği arkadan yırtılmışsa, kadın yalan söylemiştir. O (Yûsuf) ise, doğru söyleyenlerdendir.\""},{"n":28,"t":"Kadının kocası Yûsuf’un gömleğinin arkadan yırtıldığını görünce, dedi ki: \"Şüphesiz bu, siz kadınların tuzağıdır. Şüphesiz sizin tuzağınız çok büyüktür.\""},{"n":29,"t":"\"Ey Yûsuf! Sen bundan sakın kimseye bahsetme. (Ey Kadın,) sen de günahının bağışlanmasını dile. Çünkü sen günah işleyenlerdensin.\""},{"n":30,"t":"Şehirde birtakım kadınlar, \"Aziz’in karısı, (hizmetçisi olan) delikanlısından murad almak istemiş. Ona olan aşkı yüreğine işlemiş. Şüphesiz biz onu açık bir sapıklık içinde görüyoruz\" dediler."},{"n":31,"t":"Kadın, bunların dedikodularını işitince haber gönderip onları çağırdı. (Ziyafet düzenleyip) onlar için oturup yaslanacakları yer hazırladı. Her birine birer de bıçak verdi ve Yûsuf’a, \"Çık karşılarına\" dedi. Kadınlar Yûsuf’u görünce, onu pek büyüttüler ve şaşkınlıkla ellerini kestiler. \"Hâşâ! Allah için, bu bir insan değil, ancak şerefli bir melektir\" dediler."},{"n":32,"t":"Bunun üzerine kadın onlara dedi ki: \"İşte bu, beni hakkında kınadığınız kimsedir. Andolsun, ben ondan murad almak istedim. Fakat o, iffetinden dolayı bundan kaçındı. Andolsun, eğer emrettiğimi yapmazsa, mutlaka zindana atılacak ve zillete uğrayanlardan olacak.\""},{"n":33,"t":"Yûsuf, \"Ey Rabbim! Zindan bana, bunların beni dâvet ettiği şeyden daha sevimlidir. Onların tuzaklarını benden uzaklaştırmazsan, onlara meyleder ve cahillerden olurum\" dedi."},{"n":34,"t":"Rabbi, onun duasını kabul etti ve kadınların tuzaklarını ondan uzaklaştırdı. Şüphesiz ki O, hakkıyla işitendir, hakkıyla bilendir."},{"n":35,"t":"Sonra onlar, Yûsuf’un suçsuzluğunu ortaya koyan delilleri gördükten sonra yine de mutlaka onu bir süre zindana atmayı uygun buldular."},{"n":36,"t":"Onunla beraber zindana iki delikanlı daha girdi. Biri, \"Ben rüyamda şaraplık üzüm sıktığımı gördüm\" dedi. Diğeri, \"Ben de rüyamda başımın üzerinde, kuşların yediği bir ekmek taşıdığımı gördüm. Bize bunun yorumunu haber ver. Şüphesiz biz seni iyilik yapanlardan görüyoruz\" dedi."},{"n":37,"t":"Yûsuf dedi ki: \"Sizin yiyeceğiniz yemek size gelmeden önce, onun ne olduğunu bildiririm. Bu, bana Rabbimin öğrettiklerindendir. Ben, Allah’a inanmayan ve ahireti inkâr eden bir milletin dinini bıraktım.\""},{"n":38,"t":"\"Atalarım İbrahim, İshak ve Yakub’un dinine uydum. Bizim, Allah’a herhangi bir şeyi ortak koşmamız (söz konusu) olamaz. Bu, bize ve insanlara Allah’ın bir lütfudur, fakat insanların çoğu şükretmezler.\""},{"n":39,"t":"\"Ey zindan arkadaşlarım! Ayrı ayrı ilâhlar mı daha iyidir, yoksa mutlak hâkimiyet sahibi olan tek Allah mı?\""},{"n":40,"t":"\"Siz Allah’ı bırakıp; sadece sizin ve atalarınızın taktığı birtakım isimlere (düzmece ilâhlara) tapıyorsunuz. Allah, onlar hakkında hiçbir delil indirmemiştir. Hüküm ancak Allah’a aittir. O, kendisinden başka hiçbir şeye tapmamanızı emretmiştir. İşte en doğru din budur. Fakat insanların çoğu bilmezler.\""},{"n":41,"t":"\"Ey zindan arkadaşlarım! (Rüyanızın yorumuna gelince,) biriniz efendisine şarap sunacak, diğeri ise asılacak ve kuşlar başından yiyecektir. Yorumunu sorduğunuz iş böylece kesinleşmiştir.\""},{"n":42,"t":"Yûsuf, onlardan kurtulacağını düşündüğü kişiye, \"Efendinin yanında beni an\", dedi. Fakat şeytan onu efendisine hatırlatmayı unutturdu da bu yüzden o, birkaç yıl daha zindanda kaldı."},{"n":43,"t":"Kral, \"Ben rüyamda yedi semiz ineği, yedi zayıf ineğin yediğini; ayrıca yedi yeşil başak ve yedi de kuru başak görüyorum. Ey ileri gelenler! Eğer rüya yorumluyorsanız, rüyamı bana yorumlayın\" dedi."},{"n":44,"t":"Dediler ki: \"Bunlar karma karışık düşlerdir. Biz böyle düşlerin yorumunu bilmiyoruz.\""},{"n":45,"t":"Zindandaki iki kişiden kurtulmuş olanı, nice zamandan sonra (Yûsuf’u) hatırladı ve, \"Ben size onun yorumunu haber veririm, hemen beni (zindana) gönderin\" dedi."},{"n":46,"t":"(Zindana varınca), \"Yûsuf! Ey doğru sözlü! Rüyada yedi semiz ineği yedi zayıf ineğin yemesi, bir de yedi yeşil başakla diğer yedi kuru başak hakkında bize yorum yap. Ümid ederim ki (vereceğin bilgi ile) insanlara dönerim de onlar da (senin değerini) bilirler\" dedi."},{"n":47,"t":"Yûsuf dedi ki: \"Yedi yıl âdetiniz üzere ekin ekeceksiniz. Yiyeceğiniz az bir miktar hariç, biçtiklerinizi başağında bırakın.\""},{"n":48,"t":"\"Sonra bunun ardından yedi kurak yıl gelecek, saklayacağınız az bir miktar hariç bu yıllar için biriktirdiklerinizi yiyip bitirecek.\""},{"n":49,"t":"\"Sonra bunun ardından insanların yağmura kavuşacağı bir yıl gelecek. O zaman (bol rızka kavuşup) şıra ve yağ sıkacaklar.\""},{"n":50,"t":"Kral, \"Onu bana getirin\" dedi. Elçi, Yûsuf’a gelince (Yûsuf) dedi ki: \"Efendine dön de, ellerini kesen o kadınların derdi ne idi, diye sor. Şüphesiz Rabbim onların hilesini hakkıyla bilendir.\""},{"n":51,"t":"Kral, kadınlara, \"Yûsuf’tan murad almak istediğiniz zaman derdiniz ne idi?\" dedi. Kadınlar, \"Hâşâ! Allah için, biz onun bir kötülüğünü bilmiyoruz\" dediler. Aziz’in karısı ise, \"Şimdi gerçek ortaya çıktı. Ondan ben murad almak istedim. Şüphesiz Yûsuf doğru söyleyenlerdendir\" dedi."},{"n":52,"t":"(Yûsuf), \"Benim böyle yapmam, Aziz’in; yokluğunda, benim kendisine hainlik etmediğimi ve Allah’ın, hainlerin tuzaklarını başarıya ulaştırmayacağını bilmesi içindi\" dedi."},{"n":53,"t":"\"Ben nefsimi temize çıkarmam, çünkü Rabbimin merhamet ettiği hariç, nefis aşırı derecede kötülüğü emreder. Şüphesiz Rabbim çok bağışlayandır, çok merhamet edendir\" dedi."},{"n":54,"t":"Kral, \"Onu bana getirin, onu özel olarak yanıma alayım\", dedi. Onunla konuşunca dedi ki: \"Şüphesiz bugün sen yanımızda yüksek makam sahibi ve güvenilir bir kişisin.\""},{"n":55,"t":"Yûsuf, \"Beni ülkenin hazinelerine bakmakla görevlendir. Çünkü ben iyi koruyucu ve bilgili bir kişiyim\" dedi."},{"n":56,"t":"Böylece Yûsuf’a, dilediği yerde oturmak üzere ülkede imkân ve iktidar verdik. Biz rahmetimizi istediğimize veririz ve iyi davrananların mükâfatını zayi etmeyiz."},{"n":57,"t":"Elbette ki, ahiret mükâfatı, inananlar ve Allah’a karşı gelmekten sakınanlar için daha iyidir."},{"n":58,"t":"(Derken) Yûsuf’un kardeşleri çıkageldiler ve yanına girdiler. Yûsuf onları tanıdı, onlar ise Yûsuf’u tanımıyorlardı."},{"n":59,"t":"Yûsuf, onların yüklerini hazırlatınca dedi ki: \"Sizin baba bir kardeşinizi de bana getirin. Görmüyor musunuz, ölçeği tam dolduruyorum ve ben misafir ağırlayanların en iyisiyim.\""},{"n":60,"t":"\"Eğer onu bana getirmezseniz, artık benim yanımda size verilecek tek ölçek (zahire) bile yoktur ve bir daha da bana yaklaşmayın.\""},{"n":61,"t":"Dediler ki: \"Onu babasından isteyeceğiz ve muhakkak bunu yaparız.\""},{"n":62,"t":"Yûsuf, adamlarına dedi ki: \"Onların ödedikleri zahire bedellerini yüklerinin içine koyun. Umulur ki ailelerine varınca onu anlarlar da belki yine dönüp gelirler.\""},{"n":63,"t":"Onlar, babalarına döndüklerinde, \"Ey babamız! Bize artık zahire verilmeyecek. Kardeşimizi (Bünyamin’i) bizimle gönder ki zahire alalım. Onu biz elbette koruruz\" dediler."},{"n":64,"t":"Yakub onlara, \"Onun hakkında size ancak, daha önce kardeşi hakkında güvendiğim kadar güvenebilirim! Allah en iyi koruyandır ve O, merhametlilerin en merhametlisidir\" dedi."},{"n":65,"t":"Yüklerini açıp zahire bedellerinin kendilerine geri verildiğini gördüler. \"Ey babamız! Daha ne isteriz? İşte ödediğimiz bedeller de bize geri verilmiş. Onunla yine ailemize yiyecek getirir, kardeşimizi korur ve bir deve yükü zahire de fazladan alırız. Çünkü bu getirdiğimiz az bir zahiredir\" dediler."},{"n":66,"t":"Babaları, \"Kuşatılıp çaresiz durumda kalmanız hariç, onu bana geri getireceğinize dair Allah adına sağlam bir söz vermedikçe, onu sizinle göndermeyeceğim\" dedi. Ona güvencelerini verdiklerinde, \"Allah söylediklerimize vekildir\" dedi."},{"n":67,"t":"Sonra da, \"Ey oğullarım! Bir kapıdan girmeyin, ayrı ayrı kapılardan girin. Ama Allah’tan gelecek hiçbir şeyi sizden uzaklaştıramam. Hüküm ancak Allah’ındır. Ben O’na tevekkül ettim. Tevekkül edenler de yalnız O’na tevekkül etsinler\" dedi."},{"n":68,"t":"Babalarının emrettiği şekilde (ayrı kapılardan) girdiklerinde (bile) bu, Allah’tan gelecek hiçbir şeyi onlardan uzaklaştıracak değildi. Sadece Yakub, içindeki bir dileği ortaya koymuş oldu. Şüphesiz o, biz kendisine öğrettiğimiz için bilgi sahibidir. Fakat insanların çoğu bilmezler."},{"n":69,"t":"Yûsuf’un huzuruna girdiklerinde; o, kardeşi Bünyamin’i yanına bağrına bastı ve (gizlice) \"Haberin olsun ben senin kardeşinim, artık onların yaptıklarına üzülme\" dedi."},{"n":70,"t":"Yûsuf, onların yüklerini hazırlatırken su kabını kardeşinin yüküne koydurdu. Sonra da bir çağırıcı şöyle seslendi: \"Ey kervancılar! Siz hırsızsınız.\""},{"n":71,"t":"Yûsuf’un kardeşleri onlara dönerek, \"Ne yitirdiniz?\" dediler."},{"n":72,"t":"Onlar, \"Hükümdar’ın su kabını yitirdik. Onu getirene bir deve yükü ödül var. Ben buna kefilim\" dediler."},{"n":73,"t":"Dediler ki: \"Allah’a andolsun, siz de biliyorsunuz ki biz bu ülkede fesat çıkarmaya gelmedik, hırsız da değiliz.\""},{"n":74,"t":"Onlar, \"Eğer yalancı iseniz, hırsızlığın cezası nedir?\" dediler."},{"n":75,"t":"Onlar da: \"Cezası, su kabı kimin yükünde bulunursa, o kimsenin kendisi(nin alıkonması) onun cezasıdır. Biz zalimleri böyle cezalandırırız\" dediler."},{"n":76,"t":"Bunun üzerine Yûsuf, kardeşinin yükünden önce onların yüklerini aramaya başladı. Sonra su kabını kardeşinin yükünden çıkardı. İşte biz Yûsuf’a böyle bir plan öğrettik. Yoksa kralın kanunlarına göre kardeşini alıkoyamazdı. Ancak Allah’ın dilemesi başka. Biz dilediğimiz kimsenin derecelerini yükseltiriz. Her ilim sahibinin üstünde daha iyi bir bilen vardır."},{"n":77,"t":"Dediler ki: \"Eğer o çalmışsa, daha önce onun bir kardeşi de çalmıştı.\" Yûsuf, bunu içinde sakladı ve onlara belli etmedi. İçinden, \"Siz kötü bir durumdasınız; anlattığınızı Allah çok daha iyi biliyor\" dedi."},{"n":78,"t":"Onlar, Yûsuf’a: \"Ey güçlü vezir! Bunun çok yaşlı bir babası var. Onun yerine bizden birini alıkoy. Şüphesiz biz senin iyilik edenlerden olduğunu görüyoruz\" dediler."},{"n":79,"t":"Yûsuf, \"Malımızı yanında bulduğumuz kimseden başkasını tutmaktan Allah’a sığınırız. Şüphesiz biz o takdirde zulmetmiş oluruz\" dedi."},{"n":80,"t":"Ondan ümitlerini kesince, kendi aralarında konuşmak üzere bir kenara çekildiler. Büyükleri dedi ki: \"Babanızın Allah adına sizden söz aldığını, daha önce de Yûsuf hakkında işlediğiniz kusuru bilmiyor musunuz? Artık babam bana izin verinceye veya Allah, hakkımda hükmedinceye kadar buradan asla ayrılmayacağım. O, hükmedenlerin en hayırlısıdır.\""},{"n":81,"t":"\"Siz babanıza dönün ve deyin ki: \"Ey babamız! Şüphesiz oğlun hırsızlık etti, biz ancak bildiğimize şahitlik ettik. (Sana söz verdiğimiz zaman) gaybı (oğlunun hırsızlık edeceğini) bilemezdik.\""},{"n":82,"t":"\"Bulunduğumuz kent halkına ve aralarında olduğumuz kervana da sor. Şüphesiz biz doğru söyleyenleriz.\""},{"n":83,"t":"Yakub, \"Nefisleriniz sizi bir iş yapmağa sürükledi. Artık bana düşen, güzel bir sabırdır. Umulur ki, Allah onların hepsini bana getirir. Çünkü O, hakkıyla bilendir, hüküm ve hikmet sahibidir\" dedi."},{"n":84,"t":"Onlardan yüz çevirdi ve, \"Vah! Yûsuf’a vah!\" dedi ve üzüntüden iki gözüne ak düştü. O artık acısını içinde saklıyordu."},{"n":85,"t":"Oğulları, \"Allah’a yemin ederiz ki, sen hâlâ Yusuf’u anıp duruyorsun. Sonunda üzüntüden eriyip gideceksin veya helâk olacaksın\" dediler."},{"n":86,"t":"Yakub, \"Ben tasa ve üzüntümü ancak Allah’a arz ederim. Ben, Allah tarafından sizin bilmediğiniz şeyleri bilirim\" dedi."},{"n":87,"t":"\"Ey oğullarım! Gidin Yûsuf’u ve kardeşini araştırın. Allah’ın rahmetinden ümit kesmeyin. Çünkü kâfirler topluluğundan başkası Allah’ın rahmetinden ümidini kesmez.\""},{"n":88,"t":"Bunun üzerine (Mısır’a dönüp) Yûsuf’un yanına girdiklerinde, \"Ey güçlü vezir! Bize ve ailemize darlık ve sıkıntı dokundu. Değersiz bir sermaye ile geldik. Zahiremizi tam ölç, ayrıca bize sadaka ver. Şüphesiz Allah, sadaka verenleri mükâfatlandırır\" dediler."},{"n":89,"t":"Yûsuf dedi ki: \"Siz (henüz) cahil kimseler iken Yûsuf ve kardeşine neler yaptığınızı biliyor musunuz?\""},{"n":90,"t":"Kardeşleri, \"Yoksa sen, sen Yûsuf musun?\" dediler. O da, \"Ben Yûsuf’um, bu da kardeşim. Allah, bize iyilikte bulundu. Çünkü, kim kötülükten sakınır ve sabrederse, şüphesiz Allah iyilik yapanların mükâfatını zayi etmez\" dedi."},{"n":91,"t":"Dediler ki: \"Allah’a andolsun, gerçekten Allah seni bize üstün kıldı. Gerçekten biz suç işlemiştik.\""},{"n":92,"t":"Yûsuf dedi ki: \"Bugün size kınama yok. Allah sizi bağışlasın. O, merhametlilerin en merhametlisidir."},{"n":93,"t":"Bu gömleğimi götürün de babamın yüzüne koyun ki, gözleri açılsın ve bütün ailenizi bana getirin\" dedi."},{"n":94,"t":"Kervan (Mısır’dan) ayrılınca babaları, \"Bana bunak demezseniz, şüphesiz ben Yûsuf’un kokusunu alıyorum\" dedi."},{"n":95,"t":"Onlar da, \"Allah’a yemin ederiz ki sen hâlâ eski şaşkınlığındasın\" dediler."},{"n":96,"t":"Müjdeci gelip gömleği Yakub’un yüzüne koyunca gözleri açılıverdi. Yakub, \"Ben size, Allah tarafından, sizin bilemeyeceğiniz şeyleri bilirim demedim mi?\" dedi."},{"n":97,"t":"Oğulları, \"Ey babamız! Allah’tan suçlarımızın bağışlanmasını dile. Biz gerçekten suçlu idik\" dediler."},{"n":98,"t":"Yakub, \"Rabbimden sizin bağışlanmanızı dileyeceğim. Şüphesiz O, çok bağışlayandır, çok merhamet edendir\" dedi."},{"n":99,"t":"(Mısır’a gidip) Yûsuf’un huzuruna girdiklerinde; Yûsuf ana babasını bağrına bastı ve \"Allah’ın iradesi ile güven içinde Mısır’a girin\" dedi."},{"n":100,"t":"Ana babasını tahtın üzerine çıkardı. Hepsi ona (Yûsuf’a) saygı ile eğildiler. Yûsuf dedi ki: \"Babacığım! İşte bu, daha önce gördüğüm rüyanın yorumudur. Rabbim onu gerçekleştirdi. Şeytan benimle kardeşlerimin arasını bozduktan sonra; Rabbim beni zindandan çıkararak ve sizi çölden getirerek bana çok iyilikte bulundu. Şüphesiz Rabbim, dilediği şeyde nice incelikler sergileyendir. Şüphesiz O, hakkıyla bilendir, hüküm ve hikmet sahibidir.\""},{"n":101,"t":"Rabbim! Gerçekten bana mülk verdin ve bana sözlerin yorumunu öğrettin. Ey gökleri ve yeri yaratan! Dünyada ve ahirette sen benim velimsin. Benim canımı müslüman olarak al ve beni iyilere kat.\""},{"n":102,"t":"İşte bu (kıssa), gayb haberlerindendir. Onu sana biz vahiy yolu ile bildiriyoruz. Yoksa onlar tuzak kurarak işlerine karar verdikleri zaman sen onların yanında değildin."},{"n":103,"t":"Sen ne kadar şiddetle arzu etsen de insanların çoğu inanacak değillerdir."},{"n":104,"t":"Hâlbuki sen buna karşılık onlardan bir ücret de istemiyorsun. O (Kur’an) âlemler içinde ancak bir öğüttür."},{"n":105,"t":"Göklerde ve yerde nice deliller vardır ki yanlarına uğrarlar da onlardan yüzlerini çevirerek geçerler."},{"n":106,"t":"Onların çoğu Allah’a ancak ortak koşarak inanırlar."},{"n":107,"t":"Yoksa Allah tarafından kendilerini kuşatacak bir azabın gelmeyeceğinden veya onlar farkında olmadan kıyametin ansızın gelip çatmayacağından emin mi oldular?"},{"n":108,"t":"De ki: \"İşte bu benim yolumdur. Ben ve bana uyanlar bilerek Allah’a çağırırız. Allah’ın şanı yücedir. Ben, Allah’a ortak koşanlardan değilim.\""},{"n":109,"t":"Biz senden önce de, memleketler halkından ancak kendilerine vahyettiğimiz birtakım erkekleri peygamber olarak gönderdik. Yeryüzünde dolaşıp da, kendilerinden önce gelenlerin akıbetlerinin nasıl olduğuna bakmadılar mı? Elbette ahiret yurdu Allah’a karşı gelmekten sakınanlar için daha iyidir. Hâlâ aklınızı kullanmıyor musunuz?"},{"n":110,"t":"Nihayet peygamberler ümitlerini kesecek hâle gelip yalanlandıklarını düşündükleri sırada, onlara yardımımız geldi de, böylece dilediğimiz kimseler kurtuluşa erdirildi. Azabımız ise, suçlular topluluğundan geri çevrilemez."},{"n":111,"t":"Andolsun ki, onların kıssalarında akıl sahipleri için ibret vardır. Kur’an, uydurulabilecek bir söz değildir. Fakat kendinden öncekileri tasdik eden, her şeyi ayrı ayrı açıklayan ve inanan bir toplum için de bir yol gösterici ve bir rahmettir."}],[{"n":1,"t":"Elif Lâm Mîm Râ. İşte bunlar Kitab’ın âyetleridir. Sana Rabbinden indirilen gerçektir, fakat insanların çoğu inanmazlar."},{"n":2,"t":"Allah, gökleri gördüğünüz herhangi bir direk olmadan yükselten, sonra Arş’a kurulan, güneşi ve ayı buyruğu altına alandır. Bunların hepsi belli bir zamana kadar akıp gitmektedir. O, her işi (hakkıyla) düzenler, yürütür, âyetleri ayrı ayrı açıklar ki Rabbinize kavuşacağınıza kesin olarak inanasınız."},{"n":3,"t":"O, yeri yayıp döşeyen, orada dağlar, nehirler meydana getiren, orada her türlü meyveden (erkekli-dişili) iki eş yaratandır. O, geceyi gündüze bürüyor. Şüphesiz bunlarda, düşünen bir kavim için (Allah’ın varlığını gösteren) deliller vardır."},{"n":4,"t":"Yeryüzünde birbirine komşu kara parçaları, üzüm bağları, ekinler; bir kökten çıkan çok gövdeli ve tek gövdeli hurma ağaçları vardır ki hepsi aynı su ile sulanır. Ama biz ürünleri konusunda bir kısmını bir kısmına üstün kılıyoruz. Şüphesiz bunda aklını kullanan bir kavim için (Allah’ın varlığını gösteren) deliller vardır."},{"n":5,"t":"Eğer şaşacaksan, asıl şaşılacak olan onların, \"Biz toprak olunca yeniden mi yaratılacakmışız?\" demeleridir. İşte bunlar Rablerini inkâr edenlerdir. İşte onlar boyunlarına demir halkalar vurulanlardır ve işte onlar cehennemliklerdir. Onlar orada ebedî kalacaklardır."},{"n":6,"t":"Bir de senden, iyilikten önce kötülüğün acele gelmesini istiyorlar. Oysa onlardan önce ibret alınacak birçok azap gelip geçmiştir. Şüphesiz Rabbin, insanların zulümlerine rağmen bağışlama sahibidir. Bununla beraber Rabbinin azabı pek şiddetlidir."},{"n":7,"t":"İnkâr edenler, \"Ona Rabbinden bir mucize indirilseydi ya!\" diyorlar. Sen ancak bir uyarıcısın. Her kavim için de bir yol gösteren vardır."},{"n":8,"t":"Allah, her dişinin neye gebe olduğunu, rahimlerin artırdığı şeyi ve eksilttiği şeyi bilir. Her şey O’nun katında bir ölçü iledir."},{"n":9,"t":"O, gaybı da görülen âlemi de bilendir, çok büyüktür, çok yücedir."},{"n":10,"t":"(O’na göre) içinizden sözü gizleyen ile açığa vuran, geceleyin gizlenenle gündüz ortaya çıkan eşittir."},{"n":11,"t":"İnsanı önünden ve ardından takip eden melekler vardır. Allah’ın emriyle onu korurlar. Şüphesiz ki, bir kavim kendi durumunu değiştirmedikçe Allah onların durumunu değiştirmez. Allah, bir kavme kötülük diledi mi, artık o geri çevrilemez. Onlar için Allah’tan başka hiçbir yardımcı da yoktur."},{"n":12,"t":"O, korku ve ümit vermek için size şimşeği gösterendir, yağmur yüklü bulutları meydana getirendir."},{"n":13,"t":"Gök gürlemesi O’na hamd ederek tespih eder. Melekler de O’nun korkusundan tespih ederler. O, yıldırımlar gönderir de onlarla dilediğini çarpar. Onlar ise Allah hakkında mücadele ediyorlar. Hâlbuki O, azabı çok şiddetli olandır."},{"n":14,"t":"Gerçek dua ancak O’nadır. O’ndan başka yalvardıkları ise onların isteklerine ancak, ağzına ulaşmayacağı hâlde, ulaşsın diye avuçlarını suya uzatan kimsenin isteğine suyun cevap verdiği kadar cevap verirler. Kâfirlerin duası daima boşa çıkar."},{"n":15,"t":"Göklerde ve yerde kim varsa, ister istemez kendileri de gölgeleri de sabah akşam Allah’a boyun eğer."},{"n":16,"t":"De ki: \"Göklerin ve yerin Rabbi kimdir?\" \"Allah’tır\" de. De ki: \"O’nu bırakıp da kendilerine (bile) bir faydası ve zararı olmayan dostlar (mabutlar) mı edindiniz?\" De ki: \"Kör ile gören bir olur mu? Ya da karanlıklarla aydınlık bir olur mu? Yoksa Allah’a, O’nun yarattığı gibi yaratan ortaklar buldular da bu yaratma ile Allah’ın yaratması onlara göre birbirine mi benzedi?\" De ki: \"Her şeyin yaratıcısı Allah’tır. O, birdir, mutlak hâkimiyet sahibidir.\""},{"n":17,"t":"O, gökten su indirdi de dereler kendi ölçülerince dolup aktı ve sel üste çıkan köpüğü aldı götürdü. Süs eşyası veya yararlanılacak bir şey elde etmek için ateşte erittikleri şeylerden de böyle köpük olur. İşte Allah, hak ile batıla böyle misal getirir. Köpüğe gelince sönüp gider. İnsanlara yararlı olan ise yerde kalır. İşte Allah, böyle misaller verir."},{"n":18,"t":"Rablerinin emrine uyanlar için mükâfatın en güzeli vardır. Ona uymayanlar ise, yeryüzünde olan her şey ve onun yanında bir katı daha kendilerinin olsa, kurtulmak için hepsini kurtuluş fidyesi olarak verirlerdi. İşte hesabın kötüsü bunlar içindir. Varacakları yer de cehennemdir. O ne kötü yataktır!"},{"n":19,"t":"Rabbinden sana indirilenin gerçek olduğunu bilen kimse, (onu bilemeyen) kör gibi olur mu? (Bunu) ancak akıl sahipleri anlar."},{"n":20,"t":"Onlar, Allah’a verdikleri sözü yerine getiren ve sözleşmeyi bozmayanlardır."},{"n":21,"t":"Onlar, Allah’ın riâyet edilmesini emrettiği haklara riâyet eden, Rablerine saygı besleyen ve kötü hesaptan korkanlardır."},{"n":22,"t":"Onlar, Rablerinin rızasına ermek için sabreden, namazı dosdoğru kılan, kendilerine verdiğimiz rızıklardan gizli olarak ve açıktan Allah için harcayan ve kötülüğü iyilikle ortadan kaldıranlardır. İşte bunlar için dünya yurdunun iyi sonucu vardır."},{"n":23,"t":"Bu sonuç da Adn cennetleridir. Atalarından, eşlerinden ve çocuklarından iyi olanlarla beraber oraya girerler. Melekler de her bir kapıdan yanlarına girerler (ve şöyle derler):"},{"n":24,"t":"\"Sabretmenize karşılık selâm sizlere. Dünya yurdunun sonucu (olan cennet) ne güzeldir!\""},{"n":25,"t":"Allah’a verdikleri sözü, pekiştirilmesinden sonra bozanlar, Allah’ın korunmasını emrettiği şeyleri (akrabalık bağlarını) koparanlar ve yeryüzünde fesat çıkaranlar var ya; işte lânet onlara, yurdun kötüsü (cehennem) de onlaradır."},{"n":26,"t":"Allah, rızkı dilediğine bol verir, (dilediğine de) kısar. Onlar ise dünya hayatı ile sevinmektedirler. Hâlbuki dünya hayatı, ahiretin yanında çok az bir yararlanmadan ibarettir."},{"n":27,"t":"İnkâr edenler diyorlar ki: \"Ona (Muhammed’e) Rabbinden bir mucize indirilseydi ya!\" De ki: \"Şüphesiz Allah dilediğini saptırır, kendisine yöneleni de doğru yola eriştirir.\""},{"n":28,"t":"Onlar, inananlar ve kalpleri Allah’ı anmakla huzura kavuşanlardır. Biliniz ki, kalpler ancak Allah’ı anmakla huzur bulur."},{"n":29,"t":"İnanan ve salih amel işleyenler için, mutluluk ve güzel bir dönüş yeri vardır."},{"n":30,"t":"(Ey Muhammed!) Böylece seni, kendilerinden önce nice ümmetlerin geçmiş olduğu bir ümmete gönderdik ki, onlar Rahmân’ı inkâr ederken sana vahyettiğimizi kendilerine okuyasın. De ki: \"O, benim Rabbimdir. O’ndan başka hiçbir ilâh yoktur. Ben yalnız O’na tevekkül ettim, dönüşüm de yalnız O’nadır.\""},{"n":31,"t":"Kendisiyle dağların yürütüleceği veya yeryüzünün parçalanacağı, ya da ölülerin konuşturulacağı bir Kur’an olacak olsaydı (o yine bu kitap olurdu). Fakat bütün emir yalnız Allah’ındır. İman edenler anlamadılar mı ki, Allah dileseydi bütün insanları doğru yola eriştirirdi. Allah’ın sözü yerine gelinceye kadar, inkâr edenlere yaptıkları işler sebebiyle devamlı olarak, ya büyük bir felaket gelecek veya o felaket yurtlarının yakınına inecektir. Şüphesiz Allah, verdiği sözden dönmez."},{"n":32,"t":"Andolsun, senden önce de nice peygamberler alaya alındı da ben inkâr edenlere bir süre (mühlet) verdim, sonra da onları yakalayıverdim. Benim cezalandırmam nasılmış!"},{"n":33,"t":"Herkesin kazandığını görüp gözeten Allah inkâr edilir mi? Hâlbuki onlar, Allah’a ortaklar koştular. De ki: \"Onların isimlerini açıklayın. Yoksa siz (bununla) O’na yeryüzünde bilmediği bir şeyi mi haber vermiş olacaksınız, yoksa boş söz mü etmiş olacaksınız?\" Hayır, inkâr edenlere hileleri güzel gösterildi ve onlar doğru yoldan saptırıldılar. Allah, kimi saptırırsa artık onu doğru yola iletecek yoktur."},{"n":34,"t":"Onlara dünya hayatında bir azap vardır. Ahiret azabı ise daha ağırdır ve onları Allah’ın azabından koruyacak kimse de yoktur."},{"n":35,"t":"Allah’a karşı gelmekten sakınanlara va’dolunan cennetin durumu şudur: Onun içinden ırmaklar akar, yemişleri ve gölgeleri devamlıdır. İşte bu, Allah’a karşı gelmekten sakınanların sonudur. İnkâr edenlerin sonu ise ateştir."},{"n":36,"t":"Kendilerine kitap verdiğimiz kimseler, sana indirilen Kur’an ile sevinirler. Fakat (senin aleyhinde olan) gruplardan onun bir kısmını inkâr edenler de vardır. De ki: \"Ben ancak Allah’a kulluk etmek ve O’na ortak koşmamakla emrolundum. Ben yalnız O’na çağırıyorum ve dönüşüm de yalnız O’nadır.\""},{"n":37,"t":"Böylece biz onu (Kur’an’ı) Arapça bir hüküm olarak indirdik. Sana gelen bu ilimden sonra eğer sen onların heva ve heveslerine uyarsan, Allah tarafından senin için ne bir dost vardır, ne de bir koruyucu."},{"n":38,"t":"Andolsun, senden önce de peygamberler gönderdik. Onlara da eşler ve çocuklar verdik. Allah’ın izni olmadan hiçbir peygamber bir mucize getiremez. Her ecelin (vadenin) bir yazısı vardır."},{"n":39,"t":"Allah, dilediğini siler, dilediğini de sabit kılıp bırakır. Ana kitap (Levh-i Mahfuz) O’nun yanındadır."},{"n":40,"t":"Onlara va’dettiğimiz azabın bir kısmını sana göstersek de, (göstermeden) senin ruhunu alsak da senin görevin sadece tebliğ etmektir. Hesap görmek ise bize aittir."},{"n":41,"t":"Onlar, bizim yeryüzüne (kudretimizle) gelip onu etrafından eksilttiğimizi görmediler mi? Allah, hükmeder. O’nun hükmünü bozacak hiçbir kimse yoktur. O, hesabı çabuk görendir."},{"n":42,"t":"Onlardan öncekiler de tuzak kurmuşlardı. Bütün tuzaklar Allah’a aittir. O, her nefsin kazandığını bilir. İnkâr edenler de dünya yurdunun sonunun kime ait olduğunu bileceklerdir."},{"n":43,"t":"İnkâr edenler, \"Sen peygamber değilsin\" diyorlar. De ki: \"Benimle sizin aranızda şahit olarak Allah ve bir de yanında kitap (Kur’an) bilgisi bulunanlar yeter.\""}],[{"n":"1-2","t":"Elif Lâm Râ. Bu Kur’an, Rablerinin izniyle insanları karanlıklardan aydınlığa, mutlak güç sahibi ve övgüye lâyık, göklerdeki ve yerdeki her şey kendisine ait olan Allah’ın yoluna çıkarman için sana indirdiğimiz bir kitaptır. Şiddetli azaptan dolayı vay kâfirlerin hâline."},{"n":3,"t":"Dünya hayatını ahirete tercih edenler, (insanları) Allah yolundan çevirip onu eğri ve çelişkili göstermek isteyenler var ya, işte onlar derin bir sapıklık içindedirler."},{"n":4,"t":"Biz her peygamberi, ancak kendi kavminin diliyle gönderdik ki, onlara (Allah’ın emirlerini) iyice açıklasın. Allah, dilediğini saptırır, dilediğini de doğru yola iletir. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":5,"t":"Andolsun, Mûsâ’yı da, \"Kavmini karanlıklardan aydınlığa çıkar ve onlara Allah’ın (geçmiş milletleri cezalandırdığı) günlerini hatırlat\" diye âyetlerimizle gönderdik. Şüphesiz bunda çok sabreden, çok şükreden herkes için ibretler vardır."},{"n":6,"t":"Hani Mûsâ kavmine, \"Allah’ın size olan nimetini anın. Hani O sizi, Firavun ailesinden kurtarmıştı. Onlar sizi işkencenin en ağırına uğratıyorlar, oğullarınızı boğazlayıp kadınlarınızı sağ bırakıyorlardı. İşte bunda size Rabbinizden büyük bir imtihan vardır\" demişti."},{"n":7,"t":"Hani Rabbiniz şöyle duyurmuştu: \"Andolsun, eğer şükrederseniz elbette size nimetimi artırırım. Eğer nankörlük ederseniz, hiç şüphesiz azabım çok şiddetlidir.\""},{"n":8,"t":"Mûsâ, şöyle dedi: \"Siz ve yeryüzünde bulunanların hepsi nankörlük etseniz de gerçek şu ki, Allah her bakımdan sınırsız zengindir, övgüye lâyık olandır.\""},{"n":9,"t":"Sizden önceki Nûh, Âd, ve Semûd kavimlerinin ve onlardan sonrakilerin –ki onları Allah’tan başkası bilmez- haberi size gelmedi mi? Onlara peygamberleri mucizeler getirdiler de onlar (öfkeden parmaklarını ısırmak için) ellerini ağızlarına götürüp, \"Biz sizinle gönderileni inkâr ediyoruz. Bizi çağırdığınız şeyden de derin bir şüphe içindeyiz\" dediler."},{"n":10,"t":"Peygamberleri dedi ki: \"Gökleri ve yeri yaratan Allah hakkında şüphe mi var? (Hâlbuki) O, günahlarınızı bağışlamak ve sizi belli bir zamana kadar ertelemek için sizi (imana) çağırıyor. Onlar, \"Siz de bizim gibi sadece birer insansınız. Bizi babalarımızın taptıklarından alıkoymak istiyorsunuz. Öyleyse bize apaçık bir delil getirin\" dediler."},{"n":11,"t":"Peygamberleri, onlara dedi ki: \"Biz ancak sizin gibi birer insanız. Fakat Allah, kullarından dilediğine (peygamberlik) nimetini bahşeder. Allah’ın izni olmadıkça, bizim size bir delil getirmemiz haddimize değil. Mü’minler ancak Allah’a tevekkül etsinler.\""},{"n":12,"t":"\"Allah, bize yollarımızı dosdoğru göstermişken, biz ne diye O’na tevekkül etmeyelim? Bize yaptığınız eziyete elbette katlanacağız. Tevekkül edenler, yalnız Allah’a tevekkül etsinler.\""},{"n":13,"t":"İnkâr edenler, peygamberlerine; \"Andolsun, ya sizi yurdumuzdan çıkaracağız, ya da bizim dinimize dönersiniz\" dediler. Rableri de onlara şöyle vahyetti: \"Biz zalimleri mutlaka yok edeceğiz.\""},{"n":14,"t":"\"Onlardan sonra sizi elbette o yere yerleştireceğiz. Bu, makamımdan korkan ve tehdidimden sakınan kimseler içindir.\""},{"n":15,"t":"Peygamberler, Allah’tan yardım istediler ve her inatçı zorba hüsrana uğradı."},{"n":16,"t":"Hüsranın ardından da cehennem vardır. Orada kendisine irinli su içirilecektir."},{"n":17,"t":"Onu yudumlamaya çalışacak fakat boğazından geçiremeyecektir. Ona her yönden ölüm gelecek fakat ölmeyecek, arkasından da şiddetli bir azap gelecektir."},{"n":18,"t":"Rablerini inkâr edenlerin durumu şudur: Onların işleri, fırtınalı bir günde rüzgârın şiddetle savurduğu küle benzer. (Dünyada) kazandıkları hiçbir şeyin (ahirette) yararını görmezler. İşte bu, derin sapıklıktır."},{"n":19,"t":"Allah’ın, gökleri ve yeri hak ve hikmete uygun olarak yarattığını görmedin mi? Dilerse sizi giderir ve yeni bir halk getirir."},{"n":20,"t":"Bu, Allah’a hiç de güç gelmez."},{"n":21,"t":"İnsanların hepsi Allah’ın huzuruna çıkacak ve güçsüzler büyüklük taslayanlara diyecek ki: \"Şüphesiz bizler size uymuştuk; şimdi siz az bir şey olsun, Allah’ın azabından bizi koruyabilecek misiniz?\" Onlar da, \"Eğer Allah bizi doğru yola eriştirseydi, biz de sizi doğru yola eriştirirdik. Şimdi sızlansak da, sabretsek de bizim için birdir. Artık bizim için hiçbir kurtuluş yoktur\" derler."},{"n":22,"t":"İş bitirilince şeytan da diyecek ki: \"Şüphesiz Allah, size gerçek olanı söz verdi. Ben de size söz verdim ama yalancı çıktım. Zaten benim sizi zorlayacak bir gücüm yoktu. Ben sadece sizi çağırdım, siz de hemen bana geliverdiniz. O hâlde beni kınamayın, kendinizi kınayın. Artık ben sizi kurtaramam, siz de beni kurtaramazsınız. Şüphesiz ben, daha önce sizin, beni Allah’a ortak koşmanızı kabul etmemiştim. Şüphesiz, zalimlere elem dolu bir azap vardır.\""},{"n":23,"t":"İnanan ve salih ameller işleyenler, Rablerinin izniyle, ebedî kalacakları ve içlerinden ırmaklar akan cennetlere sokulacaklardır. Oradaki esenlik dilekleri \"selâm\"dır."},{"n":24,"t":"Görmedin mi, Allah güzel bir sözü nasıl misal getirdi? (Güzel bir söz), kökü sağlam, dalları göğe yükselen bir ağaç gibidir."},{"n":25,"t":"Bu ağaç, Rabbinin izniyle her zaman meyvesini verir. Öğüt alsınlar diye Allah insanlara misaller getirir."},{"n":26,"t":"Kötü bir sözün durumu da; yerden koparılmış, ayakta durma imkânı olmayan kötü bir ağacın durumu gibidir."},{"n":27,"t":"Allah, iman edenleri hem dünya hayatında hem de ahirette sabit bir sözle sağlamlaştırır, zalimleri ise saptırır. Ve Allah dilediğini yapar."},{"n":"28-29","t":"Allah’ın nimetini küfre değişenleri ve kavimlerini helâk yurduna, yaslanacakları cehenneme sürükleyenleri görmedin mi? O, ne kötü duraktır!"},{"n":30,"t":"Allah’ın yolundan saptırmak için O’na ortaklar koştular. De ki: \"Bir süre daha faydalanın. Çünkü varışınız ateşedir.\""},{"n":31,"t":"İnanan kullarıma söyle, namazı dosdoğru kılsınlar, hiçbir alışveriş ve dostluğun bulunmadığı bir gün gelmeden önce kendilerine rızık olarak verdiğimiz şeylerden Allah yolunda gizlice ve açıktan harcasınlar."},{"n":32,"t":"Allah, gökleri ve yeri yaratan, gökten yağmur indiren ve onunla size rızık olarak türlü meyveler çıkaran, emri gereğince denizde yüzmek üzere gemileri emrinize veren, nehirleri de hizmetinize sunandır."},{"n":33,"t":"O, âdetleri üzere hareket eden güneşi ve ayı sizin hizmetinize sunan, geceyi ve gündüzü sizin emrinize verendir."},{"n":34,"t":"O, istediğiniz şeylerin hepsinden size verdi. Eğer Allah’ın nimetlerini saymaya kalkışsanız sayamazsınız. Şüphesiz insan çok zalimdir, çok nankördür."},{"n":35,"t":"Hani İbrahim demişti ki: \"Rabbim! Bu şehri güvenli kıl, beni ve oğullarımı putlara tapmaktan uzak tut.\""},{"n":36,"t":"\"Rabbim! Çünkü o putlar insanlardan birçoğunu saptırdılar. Artık kim bana uyarsa, o bendendir. Kim de bana karşı gelirse, şüphesiz sen çok bağışlayan, çok merhamet edensin.\""},{"n":37,"t":"\"Rabbimiz! Ben çocuklarımdan bazısını, senin kutsal evinin (Kâbe’nin) yanında ekin bitmez bir vadiye yerleştirdim. Rabbimiz! Namazı dosdoğru kılmaları için (böyle yaptım). Sen de insanlardan bir kısmının gönüllerini onlara meylettir, onları ürünlerden rızıklandır, umulur ki şükrederler.\""},{"n":38,"t":"\"Rabbimiz! Şüphesiz sen, gizlediğimizi de, açığa vurduğumuzu da bilirsin. Yerde ve gökte hiçbir şey Allah’a gizli kalmaz.\""},{"n":39,"t":"\"Hamd, iyice yaşlanmış iken bana İsmail’i ve İshak’ı veren Allah’a mahsustur. Şüphesiz Rabbim duayı işitendir.\""},{"n":40,"t":"\"Rabbim! Beni namaza devam eden bir kimse eyle. Soyumdan da böyle kimseler yarat. Rabbimiz! Duamı kabul eyle.\""},{"n":41,"t":"\"Rabbimiz! Hesap görülecek günde, beni, ana babamı ve inananları bağışla.\""},{"n":42,"t":"Sakın, Allah’ı zalimlerin yaptıklarından habersiz sanma! Allah, onları ancak gözlerin dehşetle bakakalacağı bir güne erteliyor."},{"n":43,"t":"O gün başlarını dikerek (çağırıldıkları yere doğru) koşarlar. Gözleri kendilerine bile dönmez, kalpleri de bomboştur."},{"n":44,"t":"(Ey Muhammed!) İnsanları, kendilerine azabın geleceği gün ile uyar. Zira o gün zalimler, \"Ey Rabbimiz! Yakın bir süreye kadar bizi ertele de senin çağrına uyalım ve peygamberlerin izinden gidelim\" diyecekler. Onlara şöyle denilecek: \"Daha önce siz, sonunuzun gelmeyeceğine yemin etmemiş miydiniz?\""},{"n":45,"t":"\"Kendilerine zulmedenlerin yerlerinde oturdunuz. Onlara ne yaptığımız ise size belli olmuştu. Size misaller de vermiştik.\""},{"n":46,"t":"Onlar gerçekten tuzaklarını kurmuşlardı. Tuzakları yüzünden dağlar yerinden oynayacak olsa bile, tuzakları Allah katındadır (Allah, onu bilir)."},{"n":47,"t":"Sakın Allah’ın, peygamberlerine verdiği sözden cayacağını sanma! Şüphesiz Allah, mutlak güç sahibidir, intikam sahibidir."},{"n":48,"t":"O gün yer, başka bir yere, gökler de başka göklere dönüştürülür ve insanlar bir ve kahhar (her şeyin üzerinde yegâne hâkim) olan Allah’ın huzuruna çıkarlar."},{"n":49,"t":"O gün, suçluları zincirlere vurulmuş olarak görürsün."},{"n":50,"t":"Gömlekleri katrandandır. Yüzlerini de ateş bürüyecektir."},{"n":51,"t":"Allah, herkese kazandığının karşılığını vermek için böyle yapar. Şüphesiz Allah, hesabı çabuk görendir."},{"n":52,"t":"Bu Kur’an; kendisiyle uyarılsınlar, Allah’ın ancak tek ilâh olduğunu bilsinler ve akıl sahipleri düşünüp öğüt alsınlar diye insanlara bir bildiridir."}],[{"n":1,"t":"Elif Lâm Râ. Bunlar, kitabın ve apaçık olan Kur’an’ın âyetleridir."},{"n":2,"t":"İnkâr edenler, \"Keşke müslüman olsaydık\" diye çok arzu edeceklerdir."},{"n":3,"t":"Bırak onları yesinler (içsinler), yararlansınlar; emelleri onları oyalayadursun. İleride (gerçeği) bilecekler."},{"n":4,"t":"Helâk ettiğimiz her memleketin mutlaka bilinen bir yazısı (belli vakti) vardır."},{"n":5,"t":"Hiçbir toplum ecelini geçemez ve ondan geri de kalamaz."},{"n":6,"t":"Dediler ki: \"Ey kendisine Zikir (Kur’an) indirilen kimse! Sen mutlaka delisin!\""},{"n":7,"t":"\"Eğer doğru söyleyenlerden isen bize melekleri getirsene!\""},{"n":8,"t":"Biz, melekleri ancak hak ve hikmete uygun olarak indiririz. O zaman da onlara mühlet verilmez."},{"n":9,"t":"Şüphesiz o Zikr’i (Kur’an’ı) biz indirdik biz! Onun koruyucusu da elbette biziz."},{"n":10,"t":"Ey Muhammed! Andolsun, senden önceki topluluklara da peygamber gönderdik."},{"n":11,"t":"Onlar kendilerine gelen her peygamberle alay ediyorlardı."},{"n":12,"t":"Aynı şekilde (onların tutumlarına uygun olarak) biz onu suçluların kalbine sokarız."},{"n":13,"t":"Önceki milletlerin (helâkine dair Allah’ın) kanunu geçmiş iken onlar buna (Kur’an’a) inanmazlar."},{"n":"14-15","t":"Onlara gökten bir kapı açsak da oradan yukarı çıkmaya koyulsalar, yine \"Gözlerimiz döndürüldü, biz herhâlde büyülenmiş bir toplumuz\" derlerdi."},{"n":16,"t":"Andolsun, biz gökte burçlar yaptık ve onu, bakanlar için süsledik."},{"n":17,"t":"Onu kovulmuş her şeytandan koruduk."},{"n":18,"t":"Ancak kulak hırsızlığı eden olursa, onu da parlak bir ateş takip etmektedir."},{"n":19,"t":"Yeri de yaydık, ona sabit dağlar yerleştirdik ve orada ölçülü (bir biçimde) her şeyi bitirdik."},{"n":20,"t":"Orada hem sizin için, hem de sizin rızık vermediğiniz kimseler için geçimlikler meydana getirdik."},{"n":21,"t":"Hiçbir şey yoktur ki hazineleri yanımızda olmasın. Biz onu ancak belli bir ölçüyle indiririz."},{"n":22,"t":"Rüzgârları da aşılayıcı olarak gönderip yukarıdan su indirerek sizi onunla suladık. Onu toplayıp depolayan da siz değilsiniz."},{"n":23,"t":"Hiç şüphesiz biz diriltir, biz öldürürüz ve biz (her şeye gerçek) varisleriz"},{"n":24,"t":"Andolsun biz, sizden önce gelip geçenleri de biliriz, sonraya kalanları da."},{"n":25,"t":"Şüphesiz senin Rabbin onları diriltip bir araya getirecektir. Şüphesiz O, hüküm ve hikmet sahibidir, hakkıyla bilendir."},{"n":26,"t":"Andolsun, biz insanı kuru bir çamurdan, şekillendirilmiş bir balçıktan yarattık."},{"n":27,"t":"Cinleri de daha önce dumansız ateşten yaratmıştık."},{"n":"28-29","t":"Hani Rabbin meleklere, \"Ben kuru bir çamurdan, şekillendirilmiş balçıktan bir insan yaratacağım. Onu düzenleyip içine ruhumdan üflediğim zaman, onun için hemen saygı ile eğilin\" demişti."},{"n":30,"t":"Bunun üzerine bütün melekler saygı ile eğildiler."},{"n":31,"t":"Ancak İblis, saygı ile eğilenlerle beraber olmaktan kaçındı."},{"n":32,"t":"Allah, \"Ey İblis! Saygı ile eğilenlerle beraber olmamandaki maksadın ne?\" dedi."},{"n":33,"t":"İblis dedi ki: \"Ben, kuru bir çamurdan, şekillenmiş balçıktan yarattığın insan için saygı ile eğilemem.\""},{"n":"34-35","t":"Allah, \"Öyleyse çık oradan, çünkü sen kovuldun. Şüphesiz hesap gününe kadar lânet senin üzerinedir\" dedi."},{"n":36,"t":"İblis: \"Rabbim! Öyle ise onların tekrar diriltilecekleri güne kadar bana mühlet ver\" dedi."},{"n":"37-38","t":"Allah da, \"O hâlde, sen vakti (yalnızca benim tarafımdan) bilinen güne (kıyamete) kadar mühlet verilenlerdensin\" dedi."},{"n":"39-40","t":"İblis, \"Rabbim! Beni azdırmana karşılık, andolsun ki yeryüzünde kötülükleri onlara güzel göstereceğim, içlerinde ihlâsa erdirilmiş kulların hariç, onların hepsini azdıracağım\" dedi."},{"n":"41-42","t":"Allah, \"İşte bu bana ulaştıran dosdoğru yoldur. Azgınlardan sana uyanlar dışında, kullarım üzerinde senin hiçbir hâkimiyetin yoktur\" dedi."},{"n":43,"t":"Şüphesiz cehennem, onların hepsinin buluşacağı yerdir."},{"n":44,"t":"Onun yedi kapısı vardır ve her kapıya onlardan bir grup ayrılmıştır."},{"n":45,"t":"Şüphesiz Allah’a karşı gelmekten sakınanlar, cennetler içinde ve pınarlar başındadır."},{"n":46,"t":"Onlara, \"Girin oraya esenlikle, güven içinde\" denilir."},{"n":47,"t":"Biz, onların kalplerindeki kini söküp attık. Artık onlar sedirler üzerinde, kardeşler olarak karşılıklı otururlar."},{"n":48,"t":"Onlara orada hiçbir yorgunluk dokunmaz, onlar oradan çıkarılacak da değillerdir."},{"n":"49-50","t":"Ey Muhammed! Kullarıma, benim elbette çok bağışlayıcı, çok merhametli olduğumu, azabımın da elem dolu azap olduğunu haber ver."},{"n":51,"t":"Onlara İbrahim’in misafirlerinden de haber ver."},{"n":52,"t":"Hani misafirler İbrahim’in yanına girmiş ve \"Selâm\" demişlerdi. O da, \"Gerçekten biz sizden korkuyoruz\" demişti."},{"n":53,"t":"Onlar, \"Korkma, biz sana bilgin bir oğul müjdeliyoruz\" dediler."},{"n":54,"t":"İbrahim, \"Bana yaşlılık gelip çatmış iken beni mi müjdeliyorsunuz? Bana neyi müjdeliyorsunuz?\" dedi."},{"n":55,"t":"\"Biz sana gerçeği müjdeledik. Sakın ümitsizlerden olma\" dediler."},{"n":56,"t":"Dedi ki: \"Rabbinin rahmetinden, sapıklardan başka kim ümit keser?\""},{"n":57,"t":"İbrahim, \"Ey Elçiler! Göreviniz nedir?\" dedi."},{"n":58,"t":"Şöyle dediler: \"Şüphesiz biz suçlu bir millete gönderildik."},{"n":"59-60","t":"Lût’un ailesi başka (Onlar suçlu değillerdir). Lût’un karısı dışında onların hepsini kurtaracağız. Biz, onun geride kalanlardan olmasını takdir ettik."},{"n":"61-62","t":"Elçiler (melekler) Lût’un ailesine gelince, Lût onlara, \"Gerçekten siz tanınmayan kimselersiniz\" dedi."},{"n":63,"t":"Dediler ki: \"Evet, fakat biz sana (kavminin) şüphe etmekte olduğu azabı getirdik.\""},{"n":64,"t":"\"Biz, sana gerçeği getirdik. Şüphesiz biz doğru söyleyenleriz.\""},{"n":65,"t":"\"Gecenin bir bölümünde aile fertlerini yola çıkar, sen de arkalarından git. Hiçbiriniz arkaya bakmasın. Emrolunduğunuz yere (doğru) geçin gidin.\""},{"n":66,"t":"Ona şu durumu kesin olarak bildirdik: \"Sabaha çıkarken onların sonu kesilmiş olacak.\""},{"n":67,"t":"Şehir halkı sevinerek geldiler."},{"n":68,"t":"Lût, dedi ki: \"Şüphesiz bunlar benim misafirlerimdir. Sakın beni rezil etmeyin.\""},{"n":69,"t":"\"Allah’a karşı gelmekten sakının, beni utandırmayın\" dedi."},{"n":70,"t":"Onlar, \"Biz seni insanlarla ilgilenmekten men etmemiş miydik\" dediler."},{"n":71,"t":"Lût: \"İşte kızlarım. Eğer yapacaksanız (onlarla evlenebilirsiniz)\" dedi."},{"n":72,"t":"(Melekler, Lût’a:) \"Ömrüne andolsun ki onlar (şehvetten) gözleri dönmüş hâlde, sarhoşlukları içinde bocalayıp duruyorlar (Bu durumda asla seni dinlemezler)\" dediler."},{"n":73,"t":"Derken güneşin doğuşu sırasında, o korkunç uğultulu ses onları yakalayıverdi."},{"n":74,"t":"Hemen onların altını üstüne getirdik. Üzerlerine de balçıktan pişirilmiş taşlar yağdırdık."},{"n":75,"t":"Şüphesiz bunda düşünüp görebilen kimseler için ibretler vardır."},{"n":76,"t":"O şehrin kalıntıları hâlâ mevcut olan bir yol üstünde duruyor."},{"n":77,"t":"Şüphesiz bunda inananlar için bir ibret vardır."},{"n":78,"t":"\"Eyke\" halkı da şüphesiz zalim idiler."},{"n":79,"t":"Onlardan da intikam aldık. İkisi de (Lût kavminin yaşadığı Sodom ile Şu’ayb kavminin yaşadığı Eyke) belirgin bir anayol üzerinde idiler."},{"n":80,"t":"Andolsun, Hicr halkı da peygamberleri yalanlamıştı."},{"n":81,"t":"Biz, onlara âyetlerimizi vermiştik de onlardan yüz çevirmişlerdi."},{"n":82,"t":"Onlar güven içinde dağlardan evler yontuyorlardı."},{"n":83,"t":"Onları da sabaha çıkarlarken o korkunç uğultulu ses yakalayıverdi."},{"n":84,"t":"Kazanmakta oldukları şeyler kendilerine bir fayda vermedi."},{"n":85,"t":"Biz, gökleri, yeri ve her ikisi arasında bulunanları ancak hakka ve hikmete uygun olarak yarattık. Kıyamet günü mutlaka gelecektir. Sen şimdi güzel bir şekilde hoşgörü ile muamele et."},{"n":86,"t":"Şüphesiz, Rabbin hakkıyla yaratanın (ve her şeyi) bilenin ta kendisidir."},{"n":87,"t":"Andolsun, biz sana tekrarlanan yedi âyeti ve büyük Kur’an’ı verdik."},{"n":88,"t":"Kâfirlerden bir kısmını faydalandırdığımız şeylerde sakın gözün kalmasın. Onlara karşı mahzun olma ve mü’minlere (şefkat) kanadını indir."},{"n":89,"t":"De ki: \"Gerçekten ben, apaçık bir uyarıcıyım.\""},{"n":90,"t":"Nitekim biz kendi kitaplarını parçalara ayıranlara da (kitap) indirmiştik."},{"n":91,"t":"Ki onlar, (bir kısmına inanıp, bir kısmını inkâr ederek) Kur’an’ı da parça parça edenlerdir."},{"n":"92-93","t":"Rabbine andolsun, onların hepsine yapmakta olduklarını mutlaka soracağız."},{"n":94,"t":"Ey Muhammed! Şimdi sen, sana emrolunanı açıkça ortaya koy ve Allah’a ortak koşanlara aldırış etme."},{"n":"95-96","t":"Şüphesiz biz, Allah ile beraber başka ilâh edinen alaycılara karşı sana yeteriz. İlerde bilecekler."},{"n":97,"t":"Andolsun, onların söyledikleri şeylerden dolayı göğsünün daraldığını biliyoruz."},{"n":98,"t":"O hâlde, Rabbini hamd ile tesbih et (yücelt) ve secde edenlerden ol."},{"n":99,"t":"Sana ölüm gelinceye kadar Rabbine ibadet et."}],[{"n":1,"t":"Allah’ın emri gelecektir. Artık onun acele gelmesini istemeyin. Allah, onların ortak koştukları şeylerden uzaktır, yücedir."},{"n":2,"t":"Allah, \"Benden başka ilâh yoktur. Öyle ise bana karşı gelmekten sakının\" diye (insanları) uyarmaları için emrini içeren vahiy ile melekleri kullarından dilediğine indirir."},{"n":3,"t":"Allah, gökleri ve yeri hak ve hikmete uygun olarak yarattı. O, müşriklerin ortak koştukları şeylerden yücedir."},{"n":4,"t":"İnsanı nutfeden (bir damla sudan) yarattı. Böyle iken bakarsın ki o, Rabbine açık bir hasım kesilmiştir."},{"n":5,"t":"Hayvanları da yarattı. Onlarda sizin için bir ısınma ve birçok faydalar vardır. Hem de onlardan yersiniz."},{"n":6,"t":"Onları akşamleyin getirirken, sabahleyin salıverirken de sizin için bir güzellik (ve zevk) vardır."},{"n":7,"t":"Onlar ağırlıklarınızı, sizin ancak zorlukla varabileceğiniz beldelere taşırlar. Şüphesiz Rabbiniz çok esirgeyicidir, çok merhametlidir."},{"n":8,"t":"Hem binesiniz diye, hem de süs olarak atları, katırları ve merkepleri de yarattı. Bilemeyeceğiniz daha nice şeyleri de yaratır."},{"n":9,"t":"Doğru yolu göstermek Allah’a aittir. Yolun eğrisi de vardır. Allah dileseydi, hepinizi doğru yola iletirdi."},{"n":10,"t":"O, gökten sizin için su indirendir. İçilecek su ondandır. Hayvanlarınızı otlattığınız bitkiler de onunla meydana gelir."},{"n":11,"t":"Allah o su ile size; ekin, zeytin, hurma ağaçları, üzümler ve her türlü meyvelerden bitirir. Elbette bunda düşünen bir kavim için bir ibret vardır."},{"n":12,"t":"O, geceyi, gündüzü, güneşi ve ayı sizin hizmetinize verdi. Bütün yıldızlar da O’nun emri ile sizin hizmetinize verilmiştir. Şüphesiz bunlarda aklını kullanan bir millet için ibretler vardır."},{"n":13,"t":"Sizin için yeryüzünde çeşitli renk ve biçimlerle yarattığı şeyleri de sizin hizmetinize verdi. Öğüt alan bir toplum için bunda ibretler vardır."},{"n":14,"t":"O, taze et yemeniz ve takınacağınız süs eşyası çıkarmanız için denizi sizin hizmetinize verendir. Gemilerin orada suyu yara yara gittiğini görürsün. (Bütün bunlar) O’nun lütfundan nasip aramanız ve şükretmeniz içindir."},{"n":"15-16","t":"Sizi sarsmaması için yeryüzünde sağlam dağlar; yolunuzu bulmanız için de nehirler, yollar ve nice işaretler meydana getirdi. İnsanlar yıldızlarla da yollarını bulurlar."},{"n":17,"t":"Şu hâlde yaratan, yaratamayan gibi olur mu? Artık siz düşünmez misiniz?"},{"n":18,"t":"Hâlbuki Allah’ın nimetini saymaya kalksanız onu sayamazsınız. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir."},{"n":19,"t":"Allah, gizlediğinizi de açığa vurduğunuzu da bilir."},{"n":20,"t":"Allah’ı bırakıp da taptıkları şeyler, yaratılmış olduklarına göre hiçbir şey yaratamazlar."},{"n":21,"t":"Onlar, diri olmayan cansız varlıklardır! Ne zaman dirileceklerinin de şuuruna varamazlar."},{"n":22,"t":"Sizin ilâhınız tek bir ilâhtır. Ahirete inanmayanların kalpleri bunu inkâr etmekte, kendileri de büyüklük taslamaktadırlar."},{"n":23,"t":"Şüphe yok ki Allah, onların gizlediklerini de, açığa vurduklarını da bilir. O, büyüklük taslayanları hiç sevmez."},{"n":24,"t":"Onlara \"Rabbiniz ne indirdi?\" denildiği zaman, \"Öncekilerin masalları\" dediler."},{"n":25,"t":"Böylece kıyamet gününde kendi günahlarını tam olarak, bilgisizce saptırdıkları kimselerin günahlarının da bir kısmını yüklenirler. Dikkat et, yüklendikleri ne kötüdür."},{"n":26,"t":"Onlardan öncekiler de tuzak kurmuşlardı. Allah’ın azabı binalarını, temelinden gelip yıktı da tavanları başlarına çöküverdi ve azap kendilerine fark edemedikleri yerden geldi."},{"n":27,"t":"Sonra kıyamet günü, Allah onları rezil edecek ve diyecek ki: \"Uğrunda mücadele ettiğiniz ortaklarım nerede?!\" Kendilerine ilim verilenler ise şöyle derler: \"Şüphesiz bugün rezillik, aşağılık ve kötülük kâfirlerin üzerinedir.\""},{"n":28,"t":"O kâfirler, nefislerine zulmederlerken melekler onların canlarını alır da onlar teslim olup, \"Biz hiçbir kötülük yapmıyorduk\" derler. (Melekler de şöyle diyecekler:) \"Hayır! Allah sizin yapmakta olduklarınızı hakkıyla bilmektedir.\""},{"n":29,"t":"\"Haydi, içinde ebedî kalacağınız cehennemin kapılarından girin. Büyüklük taslayanların yeri ne kötüdür!\""},{"n":30,"t":"Allah’a karşı gelmekten sakınan kimselere, \"Rabbiniz ne indirdi?\" denildiğinde, \"Hayr indirdi\" derler. Bu dünyada iyilik yapanlara bir iyilik vardır. Ahiret yurdu ise daha hayırlıdır. Allah’a karşı gelmekten sakınanların yurdu ne güzeldir."},{"n":31,"t":"İçinden nehirler akan Adn cennetlerine gireceklerdir. Kendileri için orada diledikleri her şey vardır. Allah, kendine karşı gelmekten sakınanları böyle mükâfatlandırır."},{"n":32,"t":"Melekler, onların canlarını iyi kimseler olarak alırken, \"Selâm size! Yapmış olduğunuz iyi işlere karşılık girin cennete\" derler."},{"n":33,"t":"(O kâfirler) kendilerine ancak meleklerin veya senin Rabbinin helâk emrinin gelmesini bekliyorlar. Onlardan öncekiler de böyle yapmıştı. Allah onlara zulmetmedi, fakat onlar kendilerine zulmediyorlardı."},{"n":34,"t":"Bu sebeple işledikleri kötülüklerin cezası onlara ulaştı ve alay ettikleri şey kendilerini kuşattı."},{"n":35,"t":"Allah’a ortak koşanlar, dediler ki: \"Allah dileseydi ne biz, ne de atalarımız O’ndan başka hiçbir şeye tapmazdık, O’nun emri olmadan hiçbir şeyi de haram kılmazdık.\" Kendilerinden öncekiler de böyle yapmıştı. Peygamberlere düşen sadece apaçık bir tebliğdir."},{"n":36,"t":"Andolsun biz, her ümmete, \"Allah’a kulluk edin, tâğûttan kaçının\" diye peygamber gönderdik. Allah, onlardan kimini doğru yola iletti; onlardan kimine de (kendi iradeleri sebebiyle) sapıklık hak oldu. Şimdi yeryüzünde dolaşın da peygamberleri yalanlayanların sonunun ne olduğunu görün."},{"n":37,"t":"Sen onların doğru yola erişmelerine aşırı istek göstersen de şüphesiz Allah saptırdığı kimseyi doğru yola iletmez. Onların yardımcıları da yoktur."},{"n":38,"t":"Onlar, \"Allah, ölen bir kimseyi diriltmez\" diye var güçleriyle Allah’a yemin ettiler. Hayır, diriltecek! Bu, yerine getirilmesini Allah’ın üzerine aldığı bir vaaddir. Fakat insanların çoğu bilmezler."},{"n":39,"t":"(Diriltecek ki) ayrılığa düştükleri şeyi onlara anlatsın ve kâfir olanlar da kendilerinin yalancı olduklarını bilsinler!"},{"n":40,"t":"Biz bir şeyin olmasını istediğimiz zaman sözümüz sadece, ona, \"ol\" dememizdir. O da hemen oluverir."},{"n":41,"t":"Zulme uğradıktan sonra Allah yolunda hicret edenlere gelince, elbette onları dünyada güzel bir şekilde yerleştiririz. Ahiret mükâfatı ise daha büyüktür. Keşke bilselerdi.."},{"n":42,"t":"Onlar, sabreden ve yalnız Rablerine tevekkül eden kimselerdir."},{"n":43,"t":"Senden önce de ancak, kendilerine vahyettiğimiz birtakım erkekleri peygamber olarak gönderdik. Eğer bilmiyorsanız ilim sahiplerine sorun."},{"n":44,"t":"(O peygamberleri) apaçık belgeler ve kitaplarla gönderdik. İnsanlara, kendilerine indirileni açıklaman ve onların da (üzerinde) düşünmeleri için sana bu Kur’an’ı indirdik."},{"n":45,"t":"Kötü işler yapmak için tuzak kuranlar, Allah’ın kendilerini yere geçirmesinden veya (ansızın) bilemeyecekleri bir yerden kendilerine azap gelmesinden emin mi oldular?"},{"n":46,"t":"Yahut onlar dönüp dolaşırken Allah’ın kendilerini yakalayıvermesinden emin mi oldular? Onlar, Allah’ı âciz bırakacak değillerdir."},{"n":47,"t":"Yahut da, onları korku üzere iken yakalamayacağından güven içinde midirler? Şüphesiz Rabbiniz çok esirgeyicidir, çok merhametlidir."},{"n":48,"t":"Allah’ın yarattığı şeyleri görmüyorlar mı? Onların gölgeleri Allah’a secde ederek ve tevazu ile boyun eğerek sağa ve sola dönmektedir."},{"n":49,"t":"Göklerde ve yerde bulunan canlılar ve melekler büyüklük taslamadan Allah’a secde ederler (boyun eğerler)."},{"n":50,"t":"Üzerlerinde hâkim ve üstün olan Rablerinden korkarlar ve emrolundukları şeyleri yaparlar."},{"n":51,"t":"Allah, şöyle dedi: \"İki ilâh edinmeyin. O, ancak tek ilâhtır. O hâlde, yalnız benden korkun.\""},{"n":52,"t":"Göklerdeki her şey, yerdeki her şey O’nundur. İtaat de daima O’na olmalıdır. Öyle iken siz Allah’tan başkasından mı korkuyorsunuz?"},{"n":53,"t":"Size ulaşan her nimet Allah’tandır. Sonra size bir sıkıntı ve zarar dokunduğu zaman yalnız O’na yalvarır yakarırsınız."},{"n":54,"t":"Sonra sizden o sıkıntıyı giderince, bir de bakarsınız, içinizden bir kısmı Rablerine ortak koşar."},{"n":55,"t":"Kendilerine verdiğimiz nimetlere karşı nankörlük etmek için böyle yaparlar. Bir süre daha faydalanın bakalım! Yakında bileceksiniz!"},{"n":56,"t":"Bir de kendilerine rızık olarak verdiklerimizden (mahiyetini) bilmedikleri şeylere (putlara) pay ayırıyorlar. Allah’a andolsun ki, uydurmakta olduğunuz şeylerden mutlaka sorguya çekileceksiniz."},{"n":57,"t":"Onlar, kızları Allah’a nispet ediyorlar -ki O, bundan uzaktır- kendilerine ise, canlarının istediğini."},{"n":58,"t":"Onlardan biri, kız ile müjdelendiği zaman içi öfke ile dolarak yüzü simsiyah kesilir!"},{"n":59,"t":"Kendisine verilen kötü müjde (!) yüzünden halktan gizlenir. Şimdi onu, aşağılanmış olarak yanında tutacak mı, yoksa toprağa mı gömecek? Bak, ne kötü hüküm veriyorlar!"},{"n":60,"t":"Kötü sıfatlar ahirete inanmayanlara aittir. En yüce sıfatlar ise Allah’ındır. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":61,"t":"Eğer Allah, insanları zulümleri yüzünden hemen cezalandırsaydı, yeryüzünde hiçbir canlı bırakmazdı. Fakat onları belirli bir süreye kadar erteler. Ecelleri geldiği zaman ise ne bir an geri kalabilirler, ne de öne geçebilirler."},{"n":62,"t":"Hoşlarına gitmeyen şeyleri Allah’a isnad ederler. En güzel sonuç kendilerininmiş diye dilleri de yalan uyduruyor. Hiç şüphe yok ki onlara cehennem vardır ve onlar oraya en önde sokulacaklardır."},{"n":63,"t":"Allah’a andolsun, senden önceki ümmetlere peygamberler gönderdik. Fakat şeytan onlara işlerini güzel gösterdi. O, bugün de onların dostudur ve onlar için elem dolu bir azap vardır."},{"n":64,"t":"Sana kitabı, ancak ayrılığa düştükleri şeyleri onlara açıklaman için ve iman eden bir topluma doğru yolu gösterici ve rahmet olarak indirdik."},{"n":65,"t":"Allah, gökten su indirdi de onunla yeryüzünü ölümünden sonra diriltti. Şüphesiz bunda dinleyecek bir toplum için bir ibret vardır."},{"n":66,"t":"Şüphesiz (sağmal) hayvanlarda da sizin için bir ibret vardır. Onların karınlarındaki fışkı ile kan arasından (süzülen) içenlere halis ve içimi kolay süt içiriyoruz."},{"n":67,"t":"Hurma ağaçlarının meyvelerinden ve üzümlerden hem içki, hem de güzel bir rızık edinirsiniz. Elbette bunda aklını kullanan bir toplum için bir ibret vardır."},{"n":68,"t":"Rabbin, bal arısına şöyle ilham etti: \"Dağlardan, ağaçlardan ve insanların yaptıkları çardaklardan (kovanlardan) kendine evler edin.\""},{"n":69,"t":"\"Sonra meyvelerin hepsinden ye de Rabbinin sana kolaylaştırdığı (yaylım) yollarına gir.\" Onların karınlarından çeşitli renklerde bal çıkar. Onda insanlar için şifa vardır. Şüphesiz bunda düşünen bir (toplum) için bir ibret vardır."},{"n":70,"t":"Allah, sizi yarattı. Sonra sizi öldürecek. İçinizden kimileri de, bilgili olduktan sonra hiçbir şeyi bilmesin diye ömrünün en düşkün çağına ulaştırılır. Şüphesiz Allah hakkıyla bilendir, (her şeye) hakkıyla gücü yetendir."},{"n":71,"t":"Allah, rızık konusunda kiminizi kiminizden üstün kıldı. Üstün kılınanlar, rızıklarını ellerinin altındakilere vermezler ki rızıkta hep eşit olsunlar. Şimdi Allah’ın nimetini mi inkâr ediyorlar?"},{"n":72,"t":"Allah, size kendi cinsinizden eşler var etti. Eşlerinizden de oğullar ve torunlar verdi ve sizi temiz şeylerden rızıklandırdı. Öyleyken onlar batıla inanıyorlar da Allah’ın nimetini inkâr mı ediyorlar?"},{"n":73,"t":"Allah’ı bırakıp da, kendilerine göklerden ve yerden hiçbir rızık sağlayamayan ve buna gücü de yetmeyen şeylere tapıyorlar."},{"n":74,"t":"Artık Allah’a (şanına uymayan) benzetmeler yapmaya kalkmayın. Çünkü Allah bilir, siz bilmezsiniz."},{"n":75,"t":"Allah, hiçbir şeye gücü yetmeyen ve başkasının malı olan bir köle ile, kendisine verdiğimiz güzel rızıktan gizli ve açık olarak Allah yolunda harcayan kimseyi misal verir. Bunlar hiç eşit olur mu? Hamd Allah’a mahsustur, fakat onların çoğu bilmezler."},{"n":76,"t":"Allah, (şöyle) iki adamı da misal verdi: Onlardan biri dilsizdir, hiçbir şeye gücü yetmez, efendisine sadece bir yüktür. Nereye gönderse olumlu bir sonuç alamaz. Bu, adaletle emreden ve doğru yol üzere olan kimse ile eşit olur mu?"},{"n":77,"t":"Göklerin ve yerin gaybı Allah’a aittir. Kıyamet’in kopması, bir göz kırpması gibi veya daha az bir zamandır. Şüphesiz Allah, her şeye hakkıyla gücü yetendir."},{"n":78,"t":"Allah, sizi analarınızın karnından, siz hiçbir şey bilmez durumda iken çıkardı. Şükredesiniz diye size kulaklar, gözler ve kalpler verdi."},{"n":79,"t":"Gökyüzünde Allah’ın emrine boyun eğerek uçan kuşları görmüyorlar mı? Onları gökte ancak Allah tutar. Şüphesiz bunda inanan bir toplum için ibretler vardır."},{"n":80,"t":"Allah, size evlerinizi huzur ve dinlenme yeri yaptı. Hayvanların derilerinden gerek göç gününüzde, gerek ikamet gününüzde kolayca taşıyacağınız evler; onların yünlerinden, yapağılarından ve kıllarından bir süreye kadar yararlanacağınız ev eşyası ve geçimlikler meydana getirdi."},{"n":81,"t":"Allah, yarattıklarından sizin için gölgeler yaptı ve dağlarda da sizin için barınaklar var etti. Sizi sıcaktan koruyacak elbiseler ve savaşta sizi koruyacak zırhlar verdi. Böylece Allah, müslüman olasınız diye üzerinizde olan nimetini tamamlıyor."},{"n":82,"t":"Ey Muhammed! Eğer yüz çevirirlerse, artık sana düşen açık bir tebliğden ibarettir."},{"n":83,"t":"Onlar, Allah’ın nimetini bilirler, sonra da inkâr ederler. Onların çoğu kâfirlerdir."},{"n":84,"t":"Kıyamet günü her ümmetten bir şahit göndereceğiz; sonra inkâr edenlere ne (özür dilemeleri için) izin verilecek, ne de Allah’ın rızasını kazandıracak amelleri işleme istekleri kabul edilecek."},{"n":85,"t":"O zalimler, azabı gördükleri zaman artık onlardan azap hafifletilmez ve kendilerine mühlet de verilmez."},{"n":86,"t":"Allah’a ortak koşanlar, ortaklarını gördüklerinde diyecekler ki: \"Rabbimiz! Bunlar, seni bırakıp kendilerine tapmış olduğumuz ortaklarımızdır.\" Koştukları ortaklar da onlara: \"Siz elbette yalancılarsınız\" diye laf atacaklar."},{"n":87,"t":"Onlar o gün Allah’a teslim olurlar ve uydurdukları şeyler de onları yüzüstü bırakıp kaybolur."},{"n":88,"t":"İnkâr eden ve insanları Allah’ın yolundan alıkoyanların, yapmakta oldukları bozgunculuklarına karşılık azaplarının üstüne azap ekleriz."},{"n":89,"t":"(Ey Muhammed!) Her ümmetin kendi içinden üzerlerine bir şahit göndereceğimiz, seni de onların üzerine bir şahit olarak getireceğimiz günü düşün. Sana bu kitabı; her şey için bir açıklama, doğru yolu gösteren bir rehber, bir rahmet ve müslümanlar için bir müjde olarak indirdik."},{"n":90,"t":"Şüphesiz Allah, adaleti, iyilik yapmayı, yakınlara yardım etmeyi emreder; hayâsızlığı, fenalık ve azgınlığı da yasaklar. O, düşünüp tutasınız diye size öğüt veriyor."},{"n":91,"t":"Antlaşma yaptığınız zaman, Allah’a karşı verdiğiniz sözü yerine getirin. Allah’ı kendinize kefil kılarak pekiştirdikten sonra yeminlerinizi bozmayın. Şüphesiz Allah, yaptıklarınızı bilir."},{"n":92,"t":"Bir topluluk diğer bir topluluktan daha (güçlü ve) çoktur diye yeminlerinizi aranızda bir hile ve fesat sebebi yaparak, ipliğini iyice eğirip büktükten sonra (tekrar) çözüp bozan kadın gibi olmayın. Allah, bununla sizi ancak imtihan eder. Hakkında ayrılığa düştüğünüz şeyleri kıyamet günü size elbette açıklayacaktır."},{"n":93,"t":"Allah dileseydi, sizi tek bir ümmet yapardı. Fakat O, dilediğini saptırır, dilediğini de doğru yola iletir. Yapmakta olduğunuz şeylerden mutlaka sorguya çekileceksiniz."},{"n":94,"t":"Yeminlerinizi aranızda hile ve fesat sebebi yapmayın. Sonra sağlamca bastıktan sonra ayak(larınız) kayar da Allah yolundan sapmanız sebebiyle kötü azabı tadarsınız. (Ahirette de) sizin için büyük bir azap vardır."},{"n":95,"t":"Allah’a verdiğiniz sözü az bir karşılığa değişmeyin. Eğer bilirseniz, şüphesiz Allah katında olan sizin için daha hayırlıdır."},{"n":96,"t":"Sizin yanınızdaki tükenir, Allah katında olan ise kalıcıdır. Elbette sabredenlere, yapmakta olduklarının en güzeliyle mükâfatlarını vereceğiz."},{"n":97,"t":"Erkek veya kadın, kim mü’min olarak iyi iş işlerse, elbette ona hoş bir hayat yaşatacağız ve onların mükâfatlarını yapmakta olduklarının en güzeli ile vereceğiz."},{"n":98,"t":"Kur’an okuduğun zaman, kovulmuş şeytandan Allah’a sığın."},{"n":99,"t":"Gerçek şu ki; şeytanın, inanan ve yalnız Rablerine tevekkül eden kimseler üzerinde bir hâkimiyeti yoktur."},{"n":100,"t":"Şeytanın hâkimiyeti, sadece onu dost edinenler ve Allah’a ortak koşanlar üzerindedir."},{"n":101,"t":"Biz bir âyeti değiştirip yerine başka bir âyet getirdiğimiz zaman -ki Allah, neyi indireceğini gayet iyi bilir- onlar Peygamber’e, \"Sen ancak uyduruyorsun\" derler. Hayır, onların çoğu bilmezler."},{"n":102,"t":"Ey Muhammed! De ki: \"Ruhu’l-Kudüs (Cebrail), inananların inançlarını sağlamlaştırmak, müslümanlara doğru yolu göstermek ve onlara bir müjde olmak üzere Kur’an’ı Rabbinden hak olarak indirdi.\""},{"n":103,"t":"Andolsun ki biz onların, \"Kur’an’ı ona bir insan öğretiyor\" dediklerini biliyoruz. İma ettikleri kimsenin dili yabancıdır. Bu Kur’an ise gayet açık bir Arapça’dır."},{"n":104,"t":"Allah’ın âyetlerine inanmayanları, Allah elbette doğru yola iletmez. Onlar için elem dolu bir azap vardır."},{"n":105,"t":"Yalanı, ancak Allah’ın âyetlerine inanmayanlar uydurur. İşte onlar, yalancıların ta kendileridir."},{"n":106,"t":"Kalbi imanla dolu olduğu hâlde zorlanan kimse hariç, inandıktan sonra Allah’ı inkâr eden ve böylece göğsünü küfre açanlara Allah’tan gazap iner ve onlar için büyük bir azap vardır."},{"n":107,"t":"Bu, onların dünya hayatını sevip ahirete tercih etmelerinden ve Allah’ın kâfirler topluluğunu asla doğru yola iletmeyeceğindendir."},{"n":108,"t":"İşte onlar, Allah’ın; kalplerini, kulaklarını ve gözlerini mühürlediği kimselerdir. İşte onlar gafillerin ta kendileridir."},{"n":109,"t":"Hiç şüphesiz onlar, ahirette ziyana uğrayanların da ta kendileridir."},{"n":110,"t":"Sonra şüphesiz ki Rabbin, eziyete uğratıldıktan sonra hicret eden, sonra Allah yolunda cihad edip sabreden kimselerin yanındadır. Şüphesiz Rabbin bundan sonra da çok bağışlayandır, çok merhamet edendir."},{"n":111,"t":"Herkesin nefsi için mücadele ederek geleceği, kendilerine zulmedilmeksizin herkese yaptığının karşılığının eksiksiz ödeneceği günü düşün."},{"n":112,"t":"Allah, şöyle bir kenti misal verdi: Orası güven ve huzur içinde idi. Oraya her taraftan bolca rızık gelirdi. Fakat Allah’ın nimetlerine nankörlük ettiler; bu yüzden yaptıklarına karşılık, Allah onlara şiddetli açlık ve korku ızdırabını tattırdı."},{"n":113,"t":"Andolsun, onlara içlerinden bir peygamber geldi de onu yalanladılar. Böylece zulmederlerken azap onları yakalayıverdi."},{"n":114,"t":"Artık Allah’ın size helâl ve temiz olarak verdiği rızıklardan yiyin. Eğer yalnız O’na ibadet ediyorsanız, Allah’ın nimetine şükredin."},{"n":115,"t":"Allah, size ancak leş, kan, domuz eti ve Allah’tan başkası adına kesileni haram kıldı. Ama kim mecbur olur da istismar etmeksizin ve zaruret ölçüsünü aşmaksızın yemek zorunda kalırsa, şüphesiz ki Allah çok bağışlayandır, çok merhamet edendir."},{"n":116,"t":"Dilleriniz yalana alışageldiğinden dolayı, Allah’a karşı yalan uydurmak için, \"Şu helâldir\", \"Şu haramdır\" demeyin. Şüphesiz, Allah’a karşı yalan uyduranlar, kurtuluşa eremezler."},{"n":117,"t":"(Dünyada elde ettikleri) az bir yararlanmadır. Hâlbuki (ahirette) onlara acıklı bir azap vardır."},{"n":118,"t":"Daha önce sana anlattıklarımızı yahudi olanlara da haram kılmıştık. Biz (bununla) onlara zulmetmedik, fakat onlar kendilerine zulmediyorlardı."},{"n":119,"t":"Sonra, şüphesiz ki Rabbin; cahillik sebebiyle kötülük yapan, sonra bunun ardından tövbe eden ve durumunu düzeltenlerden yanadır. Şüphesiz Rabbin bundan sonra da elbette çok bağışlayandır, çok merhamet edendir."},{"n":120,"t":"Şüphesiz İbrahim, Allah’a itaat eden, hakka yönelen bir önder idi. Allah’a ortak koşanlardan değildi."},{"n":121,"t":"O’nun nimetlerine şükreden bir önderdi. Allah, onu seçmiş ve doğru yola iletmişti."},{"n":122,"t":"Ona dünyada iyilik verdik. Şüphesiz o, ahirette de salihlerdendir."},{"n":123,"t":"Sonra da sana, \"Hakka yönelen İbrahim’in dinine uy. O, Allah’a ortak koşanlardan değildi\" diye vahyettik."},{"n":124,"t":"Cumartesi gününe saygı, ancak onda görüş ayrılığına düşenlere farz kılındı. Şüphesiz Rabbin, ayrılığa düşmekte oldukları şeyler konusunda kıyamet günü aralarında hüküm verecektir."},{"n":125,"t":"(Ey Muhammed!) Rabbinin yoluna, hikmetle, güzel öğütle çağır ve onlarla en güzel şekilde mücadele et. Şüphesiz senin Rabbin, kendi yolundan sapanları en iyi bilendir. O, doğru yolda olanları da en iyi bilendir."},{"n":126,"t":"Eğer ceza verecekseniz, size yapılanın misliyle cezalandırın. Eğer sabrederseniz, elbette bu, sabredenler için daha hayırlıdır."},{"n":127,"t":"Sabret! Senin sabrın ancak Allah’ın yardımı iledir. Onlardan yana üzülme. Tuzak kurmalarından dolayı da sıkıntıya düşme."},{"n":128,"t":"Şüphesiz Allah, kendisine karşı gelmekten sakınanlar ve iyilik yapanlarla beraberdir."}],[{"n":1,"t":"Kendisine âyetlerimizden bir kısmını gösterelim diye kulunu (Muhammed’i) bir gece Mescid-i Haram’dan çevresini bereketlendirdiğimiz Mescid-i Aksa’ya götüren Allah’ın şanı yücedir. Hiç şüphesiz O, hakkıyla işitendir, hakkıyla görendir."},{"n":2,"t":"Mûsâ’ya Kitab’ı (Tevrat’ı) verdik ve onu, \"Benden başkasını vekil edinmeyin\" diyerek, İsrailoğullarına bir rehber yaptık."},{"n":3,"t":"Ey kendilerini Nûh ile birlikte (gemide) taşıdığımız kimselerin çocukları! Gerçek şu ki, o çok şükreden bir kuldu."},{"n":4,"t":"Biz, Kitap’ta (Tevrat’ta) İsrailoğullarına, \"Yeryüzünde muhakkak iki defa bozgunculuk yapacaksınız ve büyük bir kibre kapılarak böbürleneceksiniz\" diye hükmettik."},{"n":5,"t":"Nihayet bu iki bozgunculuktan ilkinin zamanı gelince (sizi cezalandırmak için) üzerinize, pek güçlü olan birtakım kullarımızı gönderdik. Onlar evlerinizin arasına kadar sokuldular. Bu, herhâlde yerine gelmesi gereken bir va’d idi."},{"n":6,"t":"Sonra onlara karşı size tekrar egemenlik verdik. Mallar ve çocuklarla sizi güçlendirdik; sayınızı daha da çoğalttık."},{"n":7,"t":"İyilik ederseniz kendinize iyilik etmiş olursunuz, kötülük yaparsanız yine kendinize yapmış olursunuz. İkinci bozgunculuğun zamanı gelince, yüzünüzü kara etsinler, daha önce girdikleri gibi yine mescide (Beyt-i Makdis’e) girsinler ve ellerine geçirdikleri her şeyi yerle bir etsinler diye (üzerinize yine düşmanlarınızı gönderdik.)"},{"n":8,"t":"Umulur ki Rabbiniz size merhamet eder. Eğer yine eski duruma dönerseniz, biz de (cezaya) döneriz. Biz cehennemi kâfirlere bir zindan yapmışızdır."},{"n":"9-10","t":"Gerçekten bu Kur’an en doğru olan yola götürür ve iyi işler yapan mü’minler için büyük bir mükâfat olduğunu ve ahirete inanmayanlar için elem dolu bir azap hazırladığımızı müjdeler."},{"n":11,"t":"İnsan hayra dua eder gibi şerre dua eder. İnsan çok acelecidir."},{"n":12,"t":"Biz geceyi ve gündüzü (kudretimizi gösteren) iki alâmet yaptık. Rabbinizden lütuf isteyesiniz, yılların sayısını ve hesabını bilesiniz diye gece alametini giderip gündüz alametini aydınlatıcı kıldık. İşte biz her şeyi açıkça anlattık."},{"n":13,"t":"Her insanın amelini boynuna yükledik. Kıyamet günü kendisine, açılmış olarak karşılaşacağı bir kitap çıkaracağız."},{"n":14,"t":"\"Oku kitabını! Bugün hesap sorucu olarak sana nefsin yeter\" denilecektir."},{"n":15,"t":"Kim doğru yolu bulmuşsa, ancak kendisi için bulmuştur; kim de sapıtmışsa kendi aleyhine sapıtmıştır. Hiçbir günahkâr, başka bir günahkârın günah yükünü yüklenmez. Biz, bir peygamber göndermedikçe azap edici değiliz."},{"n":16,"t":"Biz bir memleketi helâk etmek istediğimizde, onun refah içinde yaşayan şımarık elebaşlarına (itaati) emrederiz de onlar orada kötülük işlerler. Böylece o memleket hakkındaki hükmümüz gerçekleşir de oranın altını üstüne getiririz."},{"n":17,"t":"Nûh’tan sonra da nice nesilleri helâk ettik. Kullarının günahlarını hakkıyla bilici ve görücü olarak Rabbin yeter."},{"n":18,"t":"Kim bu geçici dünyayı isterse orada ona, (evet) dilediğimiz kimseye dilediğimiz kadar hemen veririz. Sonra da cehennemi ona mekân yaparız. O, buraya kınanmış ve Allah’ın rahmetinden kovulmuş olarak girer."},{"n":19,"t":"Kim de mü’min olarak ahireti ister ve ona ulaşmak için gereği gibi çalışırsa, işte bunların çalışmalarının karşılığı verilir."},{"n":20,"t":"Rabbinin lütfundan her birine; onlara da, bunlara da veririz. Rabbinin lütfu (hiç kimseye) yasaklanmış değildir."},{"n":21,"t":"Bak nasıl, onların kimini kimine üstün kıldık. Elbette ahiretteki dereceler daha büyüktür, üstünlükler daha büyüktür."},{"n":22,"t":"Allah ile birlikte başka bir tanrı edinme, yoksa kınanmış ve yalnızlığa itilmiş olarak kalırsın."},{"n":23,"t":"Rabbin, kendisinden başkasına asla ibadet etmemenizi, anaya babaya iyi davranmanızı kesin olarak emretti. Eğer onlardan biri, ya da her ikisi senin yanında ihtiyarlık çağına ulaşırsa, sakın onlara \"öf!\" bile deme; onları azarlama; onlara tatlı ve güzel söz söyle."},{"n":24,"t":"Onlara merhamet ederek tevazu kanadını indir ve de ki: \"Rabbim! Tıpkı beni küçükken koruyup yetiştirdikleri gibi sen de onlara acı.\""},{"n":25,"t":"Rabbiniz, içinizde olanı en iyi bilendir. Eğer siz iyi kişiler olursanız, şunu bilin ki Allah tövbeye yönelenleri çok bağışlayandır."},{"n":26,"t":"Akrabaya, yoksula ve yolda kalmış yolcuya haklarını ver, fakat saçıp savurma."},{"n":27,"t":"Çünkü saçıp savuranlar şeytanların kardeşleridir. Şeytan ise Rabbine karşı çok nankörlük etmiştir."},{"n":28,"t":"Eğer Rabbinden umduğun bir rahmeti istemek için onlardan yüz çevirecek olursan, o zaman onlara yumuşak bir söz söyle."},{"n":29,"t":"Eli sıkı olma, büsbütün eli açık da olma. Sonra kınanır ve çaresiz kalırsın."},{"n":30,"t":"Şüphesiz Rabbin, dilediğine rızkı bol bol verir ve (dilediğine) kısar. Çünkü O, gerçekten kullarından haberdardır ve onları görmektedir."},{"n":31,"t":"Yoksulluk korkusuyla çocuklarınızı öldürmeyin. Onları da, sizi de biz rızıklandırırız. Onları öldürmek gerçekten büyük bir günahtır."},{"n":32,"t":"Zinaya yaklaşmayın. Çünkü o, son derece çirkin bir iştir ve çok kötü bir yoldur."},{"n":33,"t":"Haklı bir sebep olmadıkça, Allah’ın, öldürülmesini haram kıldığı cana kıymayın. Kim haksız yere öldürülürse, biz onun velisine yetki vermişizdir. Ancak o da (kısas yoluyla) öldürmede meşru ölçüleri aşmasın. Çünkü kendisine yardım edilmiştir."},{"n":34,"t":"Rüştüne erişinceye kadar, yetimin malına ancak en güzel şekilde yaklaşın, verdiğiniz sözü de yerine getirin. Çünkü söz (veren sözünden) sorumludur."},{"n":35,"t":"Ölçtüğünüzde ölçmeyi tam yapın, doğru terazi ile tartın. Bu daha hayırlı, sonuç bakımından daha güzeldir."},{"n":36,"t":"Hakkında kesin bilgi sahibi olmadığın şeyin peşine düşme. Çünkü kulak, göz ve kalp, bunların hepsi ondan sorumludur."},{"n":37,"t":"Yeryüzünde böbürlenerek yürüme. Çünkü sen yeri asla yaramazsın, boyca da dağlara asla erişemezsin."},{"n":38,"t":"Bütün bu sayılanların kötü olanları, Rabbinin katında sevimsiz şeylerdir."},{"n":39,"t":"Bunlar, Rabbinin sana vahyettiği bazı hikmetlerdir. Allah ile birlikte başka ilâh edinme. Sonra kınanmış ve Allah’ın rahmetinden kovulmuş olarak cehenneme atılırsın."},{"n":40,"t":"Rabbiniz erkek çocukları size seçip ayırdı da kendisine meleklerden kız çocukları mı edindi? Gerçekten çok büyük bir söz söylüyorsunuz."},{"n":41,"t":"Andolsun biz, onlar düşünüp öğüt alsınlar diye (gerçekleri) bu Kur’an’da değişik biçimlerde açıkladık. Fakat bu, onların ancak kaçışlarını artırıyor."},{"n":42,"t":"De ki: \"Eğer onların iddia ettiği gibi, Allah’la beraber (başka) ilâhlar olsaydı, o zaman o ilâhlar da Arş’ın sahibine ulaşmak için elbette bir yol ararlardı."},{"n":43,"t":"Allah, her türlü eksiklikten uzaktır, onların söylediklerinin ötesindedir, yücedir."},{"n":44,"t":"Yedi gök, yer ve bunların içinde bulunanlar Allah’ı tespih ederler. Her şey O’nu hamd ile tespih eder. Ancak, siz onların tespihlerini anlamazsınız. O, halîm’dir (hemen cezalandırmaz, mühlet verir), çok bağışlayandır."},{"n":45,"t":"Kur’an okuduğunda, seninle ahirete inanmayanların arasına gizli bir perde çekeriz."},{"n":46,"t":"Kur’an’ı anlamamaları için kalpleri üzerine perdeler, kulaklarına da ağırlık koyarız. Kur’an’da (ibadete lâyık ilâh olarak) sadece Rabbini andığın zaman arkalarına dönüp kaçarlar."},{"n":47,"t":"Onlar seni dinlerlerken hangi maksatla dinlediklerini, kendi aralarında konuşurlarken de o zalimlerin, \"Siz ancak büyülenmiş bir adama uyuyorsunuz\" dediklerini çok iyi biliyoruz."},{"n":48,"t":"Bak, senin için ne türlü benzetmeler yaptılar da saptılar. Artık (doğru) yolu bulamazlar."},{"n":49,"t":"Dediler ki: \"Biz bir yığın kemik, bir yığın ufantı olduğumuz zaman mı yeniden bir yaratılışla diriltilecekmişiz, biz mi?\""},{"n":50,"t":"De ki: \"(Şüphe mi var?) İster taş olun ister demir!\""},{"n":51,"t":"\"Yahut aklınızca, diriltilmesi daha da imkânsız olan başka bir varlık olun, (yine de diriltileceksiniz.)\" Diyecekler ki: \"Peki bizi hayata tekrar kim döndürecek?\" De ki: \"Sizi ilk defa yaratan.\" Bunun üzerine başlarını sana (alaylı bir tarzda) sallayacaklar ve \"Ne zamanmış o?\" diyecekler. De ki: \"Yakın olsa gerek!\""},{"n":52,"t":"Allah’ın sizi (kabirlerinizden) çağıracağı, sizin de O’na hamd ederek emrine hemen uyacağınız ve (kabirlerinizde) pek az kaldığınızı sanacağınız günü hatırla!"},{"n":53,"t":"Kullarıma söyle: (İnsanlara karşı) en güzel sözü söylesinler. Çünkü şeytan aralarını bozar. Çünkü şeytan insanın apaçık bir düşmanıdır."},{"n":54,"t":"Rabbiniz sizi daha iyi bilir. (Durumunuza göre) dilerse size merhamet eder, dilerse azap eder. Seni de onlara vekil olarak göndermedik."},{"n":55,"t":"Hem Rabbin göklerde ve yerde kim varsa daha iyi bilir. Andolsun, peygamberlerin bir kısmını bir kısmına üstün kıldık. Dâvûd’a da Zebûr’u verdik."},{"n":56,"t":"De ki: \"Onu bırakıp da ilâh diye ileri sürdüklerinizi çağırın. Onlar, başınızdaki sıkıntıyı ne kaldırabilirler ne de değiştirebilirler.\""},{"n":57,"t":"Onların yalvardıkları bu varlıklar, \"hangimiz daha yakın olacağız\" diye Rablerine vesile ararlar. O’nun rahmetini umarlar, azabından korkarlar. Çünkü Rabbinin azabı gerçekten korkunçtur."},{"n":58,"t":"Ne kadar memleket varsa hepsini kıyamet gününden önce ya helâk edeceğiz, ya da şiddetli bir azapla cezalandıracağız. İşte bu, Kitap’ta (Levh-i Mahfuz’da) yazılmış bulunuyor."},{"n":59,"t":"Bizi, (Kureyş’in istediği) mucizeleri göndermekten, ancak, öncekilerin onları yalanlamış olması alıkoydu. (Nitekim) Semûd kavmine o dişi deveyi açık bir mucize olarak verdik de onlar bu yüzden zalim oldular. Oysa biz mucizeleri sırf korkutmak için göndeririz."},{"n":60,"t":"Hani sana, \"Muhakkak Rabbin, insanları çepeçevre kuşatmıştır\" demiştik. Sana gösterdiğimiz o rüyayı da, Kur’an’da lânetlenmiş bulunan o ağacı da sırf insanları sınamak için vesile yaptık. Biz onları korkutuyoruz. Fakat bu, sadece onların büyük azgınlıklarını (daha da) artırdı."},{"n":61,"t":"Hani meleklere, \"Âdem için saygı ile eğilin\" demiştik, onlar da saygı ile eğilmişlerdi. Yalnız İblis saygı ile eğilmemiş, \"Hiç ben, çamur hâlinde yarattığın kimse için saygı ile eğilir miyim?\" demişti."},{"n":62,"t":"Yine demişti ki: \"Benden üstün tuttuğun kişi bu mu, söyler misin? Andolsun eğer beni kıyamete kadar ertelersen, onun soyunu, pek azı hariç, (azdırarak) kontrolüm altına alacağım.\""},{"n":63,"t":"Allah, şöyle dedi: \"Çekil, git.\" Onlardan kim sana uyarsa, kuşkusuz cehennem tam bir karşılık olarak hepinizin cezası olacaktır.\""},{"n":64,"t":"\"(Haydi) onlardan gücünün yettiğinin ayağını çağrınla kaydır. Atlıların ve yayalarınla onların üzerine yürü. Onların mallarına ve evlatlarına ortak ol. Onlara vaadlerde bulun.\" Hâlbuki şeytan onlara aldatmadan başka bir şey va’detmez."},{"n":65,"t":"\"Şüphesiz, (gerçek) kullarım üzerinde senin hiçbir hâkimiyetin olmayacaktır. Vekil olarak Rabbin yeter!\""},{"n":66,"t":"Rabbiniz, lütfundan nasip arayasınız diye sizin için denizde gemiler yürütendir. Şüphesiz O, size karşı çok merhametlidir."},{"n":67,"t":"Denizde size bir sıkıntı dokunduğunda bütün taptıklarınız (sizi yüzüstü bırakıp) kaybolur, yalnız Allah kalır. Fakat sizi kurtarıp karaya çıkarınca yüz çevirirsiniz. Zaten insan çok nankördür."},{"n":68,"t":"Peki, karada sizi yere geçirmesinden, yahut üzerinize taşlar savuran kasırga göndermesinden, sonra da kendinize bir vekil bulamamaktan güvende misiniz?"},{"n":69,"t":"Yahut sizi tekrar denize döndürüp üstünüze, kasıp kavuran bir fırtına yollayarak nankörlüğünüz sebebiyle sizi boğmasından, sonra da bize karşı kendiniz için arka çıkacak bir yardımcı bulamama (durumun)dan güvende misiniz?"},{"n":70,"t":"Andolsun, biz insanoğlunu şerefli kıldık. Onları karada ve denizde taşıdık. Kendilerini en güzel ve temiz şeylerden rızıklandırdık ve onları yarattıklarımızın birçoğundan üstün kıldık."},{"n":71,"t":"Bütün insanları kendi önderleriyle birlikte çağıracağımız günü hatırla. (O gün) her kime kitabı sağından verilirse, işte onlar kitaplarını okurlar ve kıl kadar haksızlığa uğratılmazlar."},{"n":72,"t":"Kim bu dünyada körlük ettiyse ahirette de kördür, yolunu daha da şaşırmıştır."},{"n":73,"t":"Onlar, sana vahyettiğimizden başkasını bize karşı uydurman için az kalsın seni ondan şaşırtacaklardı. (Eğer böyle yapabilselerdi) işte o zaman seni dost edinirlerdi."},{"n":74,"t":"Eğer biz sana sebat vermiş olmasaydık, az kalsın onlara biraz meyledecektin."},{"n":75,"t":"İşte o zaman sana, hayatın da, ölümün de katmerli acılarını tattırırdık. Sonra bize karşı kendine hiçbir yardımcı bulamazdın."},{"n":76,"t":"Seni o yerden (Mekke’den) sürüp çıkarmak için neredeyse seni sıkıştıracaklardı. Bunu yapabilselerdi, senin ardından orada pek az kalırlardı."},{"n":77,"t":"Senden önce gönderdiğimiz peygamberlerimiz hakkındaki kanun böyledir. Bizim kanunumuzda hiçbir değişme bulamazsın."},{"n":78,"t":"Güneşin zevalinden (öğle vaktinde Batı’ya kaymasından) gecenin karanlığına kadar (belli vakitlerde) namazı kıl. Bir de sabah namazını kıl. Çünkü sabah namazı şahitlidir."},{"n":79,"t":"Gecenin bir kısmında da uyanarak sana mahsus fazla bir ibadet olmak üzere teheccüd namazı kıl ki, Rabbin seni Makam-ı Mahmud’a ulaştırsın."},{"n":80,"t":"De ki: \"Rabbim! (Gireceğim yere) doğruluk ve esenlik içinde girmemi sağla. (Çıkacağım yerden de) beni doğruluk ve esenlik içinde çıkar. Katından bana yardımcı bir kuvvet ver.\""},{"n":81,"t":"De ki: \"Hak geldi, batıl yok oldu. Şüphesiz batıl, yok olmaya mahkûmdur.\""},{"n":82,"t":"Biz Kur’an’dan, mü’minler için şifa ve rahmet olacak şeyler indiriyoruz. Zalimlerin ise Kur’an, ancak zararını artırır."},{"n":83,"t":"İnsana nimet verdiğimizde yüz çevirip yan çizer. Kendisine şer dokununca da umutsuzluğa düşer."},{"n":84,"t":"De ki: \"Herkes kendi yapısına uygun işler görür. Rabbiniz, en doğru yolda olanı daha iyi bilir.\""},{"n":85,"t":"Sana ruh hakkında soru soruyorlar. De ki: \"Ruh, Rabbimin bileceği bir şeydir. Size pek az ilim verilmiştir.\""},{"n":86,"t":"Andolsun, dileseydik biz sana vahyettiğimizi tamamen ortadan kaldırırdık; sonra bu konuda bize karşı kendine hiçbir yardımcı da bulamazdın."},{"n":87,"t":"Ancak Rabbin’den bir rahmet olarak böyle yapmadık. Çünkü O’nun sana olan lütfu büyüktür."},{"n":88,"t":"De ki: \"Andolsun, insanlar ve cinler bu Kur’an’ın bir benzerini getirmek üzere toplansalar ve birbirlerine de destek olsalar, yine onun benzerini getiremezler.\""},{"n":89,"t":"Andolsun, biz bu Kur’an’da insanlara her türlü misali değişik şekillerde açıkladık. Yine de insanların çoğu ancak inkârda direttiler."},{"n":"90-93","t":"Dediler ki: \"Yerden bize bir pınar fışkırtmadıkça; yahut senin hurmalardan, üzümlerden oluşan bir bahçen olup, aralarından şarıl şarıl ırmaklar akıtmadıkça; yahut iddia ettiğin gibi, gökyüzünü üzerimize parça parça düşürmedikçe; yahut Allah’ı ve melekleri karşımıza getirmedikçe; yahut altından bir evin olmadıkça; ya da göğe çıkmadıkça sana asla inanmayacağız. Bize gökten okuyacağımız bir kitap indirmedikçe göğe çıktığına da inanacak değiliz.\" De ki: \"Rabbimi tenzih ederim. Ben ancak resûl olarak gönderilen bir beşerim.\""},{"n":94,"t":"İnsanlara hidayet (Kur’an) geldikten sonra onların iman etmelerine ancak, \"Allah, bir beşeri mi peygamber olarak gönderdi?\" demeleri engel olmuştur."},{"n":95,"t":"De ki: \"Eğer yeryüzünde, (insanlar yerine) yerleşip dolaşan melekler olsaydı, elbette onlara gökten bir melek peygamber indirirdik.\""},{"n":96,"t":"De ki: \"Sizinle benim aramda şahit olarak Allah yeter. Çünkü O, kullarından hakkıyla haberdardır, onları hakkıyla görendir.\""},{"n":97,"t":"Allah, kimi doğru yola iletirse işte o, doğru yolu bulmuştur. Kimi de saptırırsa, böyleleri için O’nun dışında dostlar bulamazsın. Onları kıyamet günü körler, dilsizler ve sağırlar olarak yüzüstü haşredeceğiz. Varacakları yer cehennemdir. Cehennemin ateşi dindikçe, onlara çılgın ateşi artırırız."},{"n":98,"t":"Bu, onların cezasıdır. Çünkü onlar âyetlerimizi inkâr ettiler ve, \"Biz bir yığın kemik, bir yığın ufantı olduktan sonra mı yeniden bir yaratılışla diriltilecekmişiz, biz mi?\" dediler."},{"n":99,"t":"Onlar, gökleri ve yeri yaratan Allah’ın kendileri gibilerini yaratmaya kadir olduğunu görmediler mi? Allah onlar için, hakkında hiçbir şüphe bulunmayan bir ecel belirlemiştir. Fakat zalimler ancak inkârda direttiler."},{"n":100,"t":"De ki: \"Eğer siz Rabbimin rahmet hazinelerine sahip olsaydınız, o zaman da tükenir korkusuyla cimrilik ederdiniz. Zaten insan çok cimridir.\""},{"n":101,"t":"Andolsun, biz Mûsâ’ya apaçık dokuz mucize verdik. İsrailoğullarına sor (sana anlatsınlar): Hani Mûsâ onlara gelmiş ve Firavun da ona, \"Ben senin kesinlikle büyülendiğini zannediyorum ey Mûsâ!\" demişti."},{"n":102,"t":"Mûsâ ise, \"İyi biliyorsun ki, bunları ancak, göklerin ve yerin Rabbi apaçık deliller olarak indirmiştir. Ey Firavun, ben de seni kesinlikle helâk olmuş bir kişi olarak görüyorum\" demişti."},{"n":103,"t":"Bunun üzerine Firavun (işkence etmek ve öldürmek suretiyle) o yerden onların kökünü kazımak istedi. Biz de onu ve beraberindekileri hep birden suda boğduk."},{"n":104,"t":"Bunun ardından İsrailoğullarına şöyle dedik: \"Bu topraklarda oturun, ahiret va’di (kıyamet) gelince hepinizi toplayıp bir araya getireceğiz.\""},{"n":105,"t":"Biz onu (Kur’an’ı) hak olarak indirdik ve o da hak ile indi. Seni de ancak müjdeci ve uyarıcı olarak gönderdik."},{"n":106,"t":"Biz Kur’an’ı, insanlara dura dura okuyasın diye âyet âyet ayırdık ve onu peyderpey indirdik."},{"n":107,"t":"De ki: \"Ona ister inanın, ister inanmayın. Şüphesiz, daha önce kendilerine ilim verilenler, Kur’an kendilerine okunduğunda derhal yüzüstü secdeye kapanırlar.\""},{"n":108,"t":"\"Rabbimizin şanı yücedir. Rabbimizin va’di mutlaka gerçekleşecektir\" derler."},{"n":109,"t":"Onlar ağlayarak yüzüstü yere kapanırlar. Bu da onların derin saygısını artırır."},{"n":110,"t":"De ki: \"(Rabbinizi) ister Allah diye çağırın, ister Rahman diye çağırın. Hangisiyle çağırırsanız çağırın, nihayet en güzel isimler O’nundur.\" Namazında sesini pek yükseltme, çok da kısma. İkisi ortası bir yol tut."},{"n":111,"t":"\"Hamd, çocuk edinmeyen, mülkte ortağı olmayan, zillet ve âcizliğin gerektirdiği bir yardımcıya ihtiyacı bulunmayan Allah’a mahsustur\" de ve O’nu tekbir ile yücelt."}],[{"n":1,"t":"Hamd, kuluna Kitab’ı (Kur’an’ı) indiren ve onda hiçbir eğrilik yapmayan Allah’a mahsustur."},{"n":"2-4","t":"(Allah onu), katından gelecek şiddetli bir azap ile (inanmayanları) uyarmak, salih ameller işleyen mü’minleri, içlerinde ebedî olarak kalacakları güzel bir mükâfat (cennet) ile müjdelemek ve \"Allah, bir çocuk edindi\" diyenleri de uyarmak için dosdoğru bir kitap kıldı."},{"n":5,"t":"Bu konuda ne kendilerinin, ne de atalarının hiçbir bilgisi yoktur. Ne büyük bir söz (bu) ağızlarından çıkan! Onlar ancak yalan söylüyorlar."},{"n":6,"t":"Demek sen, bu söze (Kur’an’a) inanmazlarsa, arkalarından üzülerek âdeta kendini tüketeceksin!"},{"n":7,"t":"İnsanların hangisinin daha güzel amel yaptığını deneyelim diye şüphesiz biz yeryüzündeki şeyleri ona bir zinet yaptık."},{"n":8,"t":"Biz, elbette (zamanı gelince) yeryüzündeki her şeyi bir kuru toprak hâline getireceğiz."},{"n":9,"t":"Yoksa sen, (sadece) Ashab-ı Kehf ve Ashab-ı Rakîm’i mi bizim ibret verici delillerimizden sandın?"},{"n":10,"t":"Hani o gençler mağaraya sığınmışlardı da, \"Ey Rabbimiz! Bize katından bir rahmet ver ve içinde bulunduğumuz şu durumda bize kurtuluş ve doğruluğa ulaşmayı kolaylaştır\" demişlerdi."},{"n":11,"t":"Bunun üzerine biz de nice yıllar onların kulaklarını (dış dünyaya) kapattık (Onları uyuttuk)."},{"n":12,"t":"Sonra onları uyandırdık ki, iki zümreden hangisinin bekledikleri süreyi daha iyi hesap ettiğini bilelim."},{"n":13,"t":"Biz sana onların haberlerini gerçek olarak anlatıyoruz: Şüphesiz onlar Rablerine inanmış birkaç genç yiğitti. Biz de onların hidayetlerini artırmıştık."},{"n":"14-15","t":"Kalkıp da, \"Rabbimiz, göklerin ve yerin Rabbidir. O’ndan başkasına asla ilâh demeyiz. Yoksa andolsun ki saçma bir söz söylemiş oluruz. Şunlar, şu kavmimiz, O’ndan başka tanrılar edindiler. Onlar hakkında açık bir delil getirselerdi ya! Artık kim Allah’a karşı yalan uydurandan daha zalimdir?\" dediklerinde onların kalplerine kuvvet vermiştik."},{"n":16,"t":"(İçlerinden biri şöyle dedi:) \"Mademki onlardan ve Allah’tan başkasına tapmakta olduklarından yüz çevirip ayrıldınız, o hâlde mağaraya çekilin ki, Rabbiniz size rahmetini yaysın ve içinde bulunduğunuz durumda yararlanacağınız şeyler hazırlasın.\""},{"n":17,"t":"(Orada olsaydın) güneş doğduğunda onun; mağaralarının sağ tarafına kaydığını, batarken de onlara dokunmadan sol tarafa gittiğini görürdün. Kendileri ise mağaranın geniş bir yerinde idiler. Bu, Allah’ın mucizelerindendir. Allah, kime hidayet ederse işte o, doğru yolu bulandır. Kimi de şaşırtırsa, artık ona doğru yolu gösterecek bir dost bulamazsın."},{"n":18,"t":"Uykuda oldukları hâlde, sen onları uyanık sanırsın. Biz onları sağa sola çeviriyorduk. Köpekleri de mağaranın girişinde iki kolunu uzatmış (yatmakta idi.) Onları görseydin, mutlaka onlardan yüz çevirip kaçardın ve gördüklerin yüzünden için korku ile dolardı."},{"n":19,"t":"Böylece biz, birbirlerine sorsunlar diye onları uyandırdık. İçlerinden biri: \"Ne kadar kaldınız\"? dedi. (Bir kısmı) \"Bir gün, ya da bir günden az\", dediler. (Diğerleri de) şöyle dediler: \"Ne kadar kaldığınızı Rabbiniz daha iyi bilir. Şimdi siz birinizi şu gümüş para ile kente gönderin de baksın; (şehir halkından) hangisinin yiyeceği daha temiz ve lezzetli ise ondan size bir rızık getirsin. Ayrıca, çok nazik davransın (da dikkat çekmesin) ve sizi hiçbir kimseye sakın sezdirmesin.\""},{"n":20,"t":"\"Çünkü onlar sizi ele geçirirlerse ya taşlayarak öldürürler, yahut kendi dinlerine döndürürler. O zaman da bir daha asla kurtuluşa eremezsiniz.\""},{"n":21,"t":"Böylece biz, (insanları) onların hâlinden haberdar ettik ki, Allah’ın va’dinin hak olduğunu ve kıyametin gerçekleşmesinde de hiçbir şüphe olmadığını bilsinler. Hani onlar (olayın mucizevî tarafını ve asıl hikmetini bırakmışlar da) aralarında onların durumunu tartışıyorlardı. (Bazıları), \"Onların üstüne bir bina yapın, Rableri onların hâlini daha iyi bilir\" dediler. Duruma hâkim olanlar ise, \"Üzerlerine mutlaka bir mescit yapacağız\" dediler."},{"n":22,"t":"(Ey Muhammed!) Bazıları bilmedikleri şey hakkında atıp tutarak: \"Onlar üç kişidirler, dördüncüleri köpekleridir\" diyecekler. Yine, \"Beş kişidirler, altıncıları köpekleridir\" diyecekler. Şöyle de diyecekler: \"Yedi kişidirler, sekizincileri köpekleridir.\" De ki: \"Onların sayısını Rabbim daha iyi bilir. Zaten onları pek az kimse bilir. O hâlde, onlar hakkında (Kur’an’daki) apaçık tartışma(yı aktarmak)dan başka tartışmaya girme ve bunlar hakkında onlardan hiçbirine bir şey sorma.\""},{"n":23,"t":"Hiçbir şey hakkında sakın \"yarın şunu yapacağım\" deme!"},{"n":24,"t":"Ancak, \"Allah dilerse yapacağım\" de. Unuttuğun zaman Rabbini an ve \"Umarım Rabbim beni, bundan daha doğru olana ulaştırır\" de."},{"n":25,"t":"Onlar mağaralarında üç yüz yıl kaldılar. Buna dokuz daha eklediler."},{"n":26,"t":"De ki: \"Kaldıkları süreyi Allah daha iyi bilir. Göklerin ve yerin gaybını bilmek O’na aittir. O, ne güzel görür; O, ne güzel işitir! Onların, O’ndan başka hiçbir dostu da yoktur. O, hükmüne hiçbir kimseyi ortak etmez.\""},{"n":27,"t":"Rabbinin kitabından sana vahyedileni oku. O’nun kelimelerini değiştirecek hiçbir kimse yoktur. O’ndan başka asla bir sığınak da bulamazsın."},{"n":28,"t":"Sabah akşam Rablerine, O’nun rızasını dileyerek dua edenlerle birlikte ol. Dünya hayatının zînetini arzu edip de gözlerini onlardan ayırma. Kalbini bizi anmaktan gafil kıldığımız, boş arzularına uymuş ve işi hep aşırılık olmuş kimselere boyun eğme."},{"n":29,"t":"De ki: \"Hak, Rabbinizdendir. Artık dileyen iman etsin, dileyen inkâr etsin.\" Biz zalimlere öyle bir ateş hazırladık ki, onun alevden duvarları kendilerini çepeçevre kuşatmıştır. (Susuzluktan) feryat edip yardım dilediklerinde, maden eriyiği gibi, yüzleri yakıp kavuran bir su ile kendilerine yardım edilir. O ne kötü bir içecektir! Cehennem ne korkunç bir yaslanacak yerdir."},{"n":30,"t":"Gerçek şu ki, iman edip iyi işler yapanlara gelince, elbette biz iyi iş yapanların ecrini zayi etmeyiz."},{"n":31,"t":"İşte onlar için içlerinden ırmaklar akan Adn cennetleri vardır. Orada tahtlar üzerine kurularak altın bileziklerle süslenecekler, ince ve kalın ipekten yeşil giysiler giyeceklerdir. O ne güzel karşılıktır! Cennet de ne güzel bir yaslanacak yerdir!"},{"n":32,"t":"Onlara şu iki adamı örnek ver: Onlardan birine iki üzüm bağı vermiş, bağların çevresini hurmalarla donatmış, ikisinin arasına da bir ekinlik koymuştuk."},{"n":33,"t":"Her iki bağ da meyvelerini vermiş ve ürünlerinden hiçbir şeyi eksik bırakmamıştı. Bu iki bağın arasından bir de nehir fışkırtmıştık."},{"n":34,"t":"Derken onun büyük bir serveti oldu. Arkadaşıyla konuşurken ona dedi ki: \"Benim malım seninkinden daha çok. Adamlardan yana da senden daha üstünüm.\""},{"n":35,"t":"Derken kendine zulmederek bağına girdi. Şöyle dedi: \"Bunun sonsuza değin yok olacağını sanmıyorum.\""},{"n":36,"t":"\"Kıyametin kopacağını da sanmıyorum. Rabbime döndürülsem bile andolsun bundan daha iyi bir sonuç bulurum.\""},{"n":37,"t":"Arkadaşı, ona cevap vererek dedi ki: \"Seni topraktan, sonra bir damla döl suyundan yaratan, sonra da seni (eksiksiz) bir insan şeklinde düzenleyen Allah’ı inkâr mı ediyorsun?\""},{"n":38,"t":"\"Fakat O Allah benim Rabbimdir. Ben Rabbime hiç kimseyi ortak koşmam.\""},{"n":"39-40","t":"\"Bağına girdiğinde ‘Mâşaallah! Kuvvet yalnız Allah’ındır’ deseydin ya!. Eğer benim malımı ve çocuklarımı kendininkilerden daha az görüyorsan, belki Rabbim bana, senin bağından daha iyisini verir. Seninkinin üzerine de gökten bir afet indirir de bağ kupkuru ve yalçın bir toprak hâline geliverir.\""},{"n":41,"t":"\"Ya da suyu çekiliverir de (bırak bir daha bulmayı) artık onu arayamazsın bile.\""},{"n":42,"t":"Derken bütün serveti helâk edildi. (Yıkılmış) çardakları üzerine çökmüş hâldeki bağına yaptığı harcamalar karşısında ellerini oğuşturuyor ve şöyle diyordu: \"Keşke Rabbime hiçbir kimseyi ortak koşmasaydım..\""},{"n":43,"t":"Onun, Allah’tan başka kendisine yardım edebilecek kimseleri yoktu. Kendi kendini kurtaracak güçte de değildi."},{"n":44,"t":"İşte bu durumda velayet (himaye ve koruyuculuk) yalnızca hak olan Allah’a mahsustur. O’nun mükâfatı da daha hayırlıdır, vereceği sonuç da daha hayırlıdır."},{"n":45,"t":"Onlara dünya hayatının örneğini ver: (Dünya hayatı), gökten indirdiğimiz yağmur gibidir ki, onun sebebiyle yeryüzünün bitkileri boy verip birbirine karışırlar. Fakat bütün bu canlılık sonunda rüzgârın savurduğu kuru bir çer çöpe döner. Allah, her şey üzerinde kudret sahibidir."},{"n":46,"t":"Mallar ve evlatlar, dünya hayatının süsüdür. Baki kalacak salih ameller ise, Rabbinin katında, sevap olarak da ümit olarak da daha hayırlıdır."},{"n":47,"t":"Dağları yürüteceğimiz ve senin yeryüzünü çırılçıplak göreceğin günü bir hatırla. Biz onları mahşerde toplarız da içlerinden hiçbirini bırakmayız."},{"n":48,"t":"Hepsi saf saf Rabbinin huzuruna çıkarılırlar. Onlara, \"Andolsun, sizi ilk önce yarattığımız gibi bize geldiniz. Oysa siz, sizin için hesaba çekileceğiniz bir zaman belirlemediğimizi sanmıştınız\" denir."},{"n":49,"t":"Kitap ortaya konur. Suçluları, kitabın içindekilerden korkuya kapılmış görürsün. \"Eyvah bize! Bu nasıl bir kitaptır ki küçük, büyük hiçbir şey bırakmadan hepsini sayıp dökmüş!\" derler. Onlar bütün yaptıklarını karşılarında bulurlar. Senin Rabbin hiç kimseye zulmetmez."},{"n":50,"t":"Hani biz meleklere, \"Âdem için saygı ile eğilin\" demiştik de İblis’ten başka hepsi saygı ile eğilmişlerdi. İblis ise cinlerdendi de Rabbinin emri dışına çıktı. Şimdi siz, beni bırakıp da İblis’i ve neslini, kendinize dostlar mı ediniyorsunuz? Hâlbuki onlar sizin için birer düşmandırlar. Bu, zalimler için ne kötü bir bedeldir!"},{"n":51,"t":"Ben onları ne göklerin ve yerin yaratılışına, ne de kendilerinin yaratılışına şahit tuttum. Saptıranları da hiçbir zaman yardımcı edinmiş değilim."},{"n":52,"t":"(Ey Muhammed!) Allah’ın, \"Ortağım olduklarını iddia ettiklerinizi çağırın\" diyeceği, onların da çağıracakları, fakat kendilerine (çağırdıklarının) cevap vermeyecekleri ve bizim de aralarına bir uçurum koyacağımız günü hatırla!"},{"n":53,"t":"Suçlular (o gün) ateşi görünce, onun içine düşeceklerini iyice anlayacaklar ve ondan kurtuluş yolu da bulamayacaklardır."},{"n":54,"t":"Andolsun, biz bu Kur’an’da insanlar için her türlü misali değişik şekillerde açıkladık. Fakat insan tartışmaya her şeyden daha çok düşkündür."},{"n":55,"t":"İnsanlara hidayet geldikten sonra onların inanmalarına ve Rab’lerinden mağfiret dilemelerine, ancak, öncekilerin başına gelenlerin kendi başlarına da gelmesi, ya da kendilerine azabın göz göre göre gelmesi (yönündeki beklentileri) engel olmuştur."},{"n":56,"t":"Biz, peygamberleri ancak müjdeleyiciler ve uyarıcılar olarak göndeririz. İnkâr edenler ise, hakkı batılla çürütmek için mücadele ederler. Âyetlerimizi ve kendilerine yapılan uyarıları alaya alırlar."},{"n":57,"t":"Kim, kendisine Rabbinin âyetleri hatırlatılıp da onlardan yüz çeviren ve elleriyle yaptığını unutandan daha zalimdir? Şüphesiz biz, onu anlamamaları için, kalplerine perdeler gerdik, kulaklarına da ağırlıklar koyduk. Sen onları hidayete çağırsan da artık ebediyen hidayet bulamazlar."},{"n":58,"t":"Rabbin, çok bağışlayıcıdır, merhamet sahibidir. Eğer yaptıkları yüzünden onları (dünyada) cezaya çarptırsaydı, elbette azaplarını çarçabuk verirdi. Hayır, onlar için belirlenmiş bir gün vardır ki (o gün gelince) hiçbir kurtuluş çaresi bulamazlar."},{"n":59,"t":"İşte zulmettiklerinde yok ettiğimiz memleketler.. Helâk edilmeleri için de belli bir zaman tayin etmiştik."},{"n":60,"t":"Hani Mûsâ, beraberindeki gence şöyle demişti: \"İki denizin birleştiği yere varıncaya kadar durmayacağım, ya da uzun zaman gideceğim.\""},{"n":61,"t":"Onlar iki denizin birleştiği yere varınca, balıklarını unuttular. Balık denizde yolunu tutup kayıp gitti."},{"n":62,"t":"Oradan uzaklaştıklarında Mûsâ beraberindeki gence, \"Öğle yemeğimizi getir, bu yolculuğumuzdan dolayı çok yorgun düştük\" dedi."},{"n":63,"t":"Genç, \"Gördün mü! Kayaya sığındığımız sırada balığı unutmuşum. –Doğrusu onu sana söylememi bana ancak şeytan unutturdu- Balık şaşılacak bir şekilde denizde yolunu tutup gitmişti\" dedi."},{"n":64,"t":"Mûsâ: \"İşte aradığımız bu idi\" dedi. Bunun üzerine tekrar izlerini takip ederek gerisingeri döndüler."},{"n":65,"t":"Derken kullarımızdan bir kul buldular ki, biz ona katımızdan bir rahmet vermiş, kendisine tarafımızdan bir ilim öğretmiştik."},{"n":66,"t":"Mûsâ ona, \"Sana öğretilen bilgilerden bana, doğruya iletici bir bilgi öğretmen için sana tabi olayım mı?\" dedi."},{"n":67,"t":"Adam, şöyle dedi: \"Doğrusu sen benimle beraberliğe asla sabredemezsin.\""},{"n":68,"t":"\"İç yüzünü kavrayamadığın bir şeye nasıl sabredebilirsin?\""},{"n":69,"t":"Mûsâ, \"İnşaallah beni sabırlı bulacaksın. Hiçbir işte de sana karşı gelmeyeceğim\" dedi."},{"n":70,"t":"O da şöyle dedi: \"O hâlde, eğer bana tabi olacaksan, ben sana söylemedikçe hiçbir şey hakkında bana soru sormayacaksın.\""},{"n":71,"t":"Derken yola koyuldular. Nihayet, bir gemiye bindiklerinde (adam) gemiyi deldi. Mûsâ, \"Sen onu içindekileri boğmak için mi deldin? Doğrusu, şaşılacak bir iş yaptın.\" dedi."},{"n":72,"t":"Adam, \"Sen benimle beraberliğe asla sabredemezsin, demedim mi?\" dedi."},{"n":73,"t":"Mûsâ, \"Unuttuğum için bana çıkışma ve bu işimde bana güçlük çıkarma!\" dedi."},{"n":74,"t":"Yine yola koyuldular. Nihayet bir erkek çocukla karşılaştıklarında, adam (hemen) onu öldürdü. Mûsâ, \"Bir cana karşılık olmaksızın suçsuz birini mi öldürdün? Andolsun çok kötü bir iş yaptın!\" dedi."},{"n":75,"t":"Adam, \"Sana, benimle beraberliğe asla sabredemezsin demedim mi?\" dedi."},{"n":76,"t":"Mûsâ, \"Eğer bundan sonra sana bir şey hakkında soru sorarsam, artık benimle arkadaşlık etme. Doğrusu, tarafımdan (dilenecek son) özre ulaştın (bu son özür dileyişim)\" dedi."},{"n":77,"t":"Yine yola koyuldular. Nihayet bir şehir halkına varıp onlardan yiyecek istediler. Halk onları konuk etmek istemedi. Derken orada yıkılmaya yüz tutmuş bir duvar gördüler. Adam hemen o duvarı doğrulttu. Mûsâ, \"İsteseydin bu iş için bir ücret alırdın\" dedi."},{"n":78,"t":"Adam, \"İşte bu birbirimizden ayrılmamız demektir\" dedi. \"Şimdi sana sabredemediğin şeylerin içyüzünü anlatacağım.\""},{"n":79,"t":"\"O gemi, denizde çalışan birtakım yoksul kimselere ait idi. Onu yaralamak istedim, çünkü onların ilerisinde, her gemiyi zorla ele geçiren bir kral vardı.\""},{"n":80,"t":"\"Çocuğa gelince, anası babası mü’min insanlardı. Onları azgınlığa ve küfre sürüklemesinden korktuk.\""},{"n":81,"t":"\"Böylece, Rablerinin onlara, bu çocuğun yerine daha hayırlı ve daha merhametli bir çocuk vermesini diledik.\""},{"n":82,"t":"\"Duvar ise şehirdeki iki yetim çocuğa ait idi. Altında onlara ait bir define vardı. Babaları da iyi bir insandı. Rabbin, onların olgunluk çağına ulaşmalarını ve Rabbinden bir rahmet olarak definelerini çıkarmalarını istedi. Bunları ben kendi görüşüme göre yapmadım. İşte senin, sabredemediğin şeylerin içyüzü budur.\""},{"n":83,"t":"(Ey Muhammed!) Bir de sana Zülkarneyn hakkında soru soruyorlar. De ki: \"Size ondan bir anı okuyacağım.\""},{"n":84,"t":"Biz onu yeryüzünde kudret sahibi kıldık ve kendisine her konuda (amacına ulaşabileceği) bir yol verdik."},{"n":85,"t":"O da (Batı’ya gitmek istedi ve) bir yol tuttu."},{"n":86,"t":"Güneşin battığı yere varınca, onu siyah balçıklı bir su gözesinde batar (gibi) buldu. Orada (kâfir) bir kavim gördü. \"Ey Zülkarneyn! Ya (onları) cezalandırırsın ya da haklarında iyilik yolunu tutarsın\" dedik."},{"n":87,"t":"Zülkarneyn, \"Her kim zulmederse, biz onu cezalandıracağız. Sonra o Rabbine döndürülür. O da kendisini görülmedik bir azaba uğratır\" dedi."},{"n":88,"t":"\"Her kim de iman eder ve salih amel işlerse, ona mükâfat olarak daha güzeli var. (Üstelik) ona emrimizden kolay olanı söyleyeceğiz.\""},{"n":89,"t":"Sonra yine (doğuya doğru) bir yol tuttu."},{"n":90,"t":"Güneşin doğduğu yere ulaşınca, onu kendileriyle güneş arasına örtü koymadığımız bir halk üzerine doğar buldu."},{"n":91,"t":"İşte böyle. Şüphesiz biz onun yanındakileri ilmimizle kuşatmışızdır."},{"n":92,"t":"Sonra yine bir yol tuttu."},{"n":93,"t":"İki dağ arasına ulaşınca, bunların önünde, neredeyse hiçbir sözü anlamayan bir halk buldu."},{"n":94,"t":"Dediler ki: \"Ey Zülkarneyn! Ye’cüc ve Me’cüc (adlı kavimler) yeryüzünde bozgunculuk yapmaktadırlar. Onlarla bizim aramıza bir engel yapman karşılığında sana bir vergi verelim mi?\""},{"n":95,"t":"Zülkarneyn, \"Rabbimin bana verdiği (imkân ve kudret, sizin vereceğiniz vergiden) daha hayırlıdır. Şimdi siz bana gücünüzle yardım edin de, sizinle onların arasına sağlam bir engel yapayım\" dedi."},{"n":96,"t":"\"Bana (yeterince) demir madeni getirin\" dedi. İki yamacın arasındaki boşluğu (dağlarla) bir hizaya getirince, \"körükleyin!\" dedi. Demiri eritip kor (gibi) yapınca da, \"Bana erimiş bakır getirin, bunun üzerine boşaltayım\" dedi."},{"n":97,"t":"Artık onu ne aşabildiler, ne de delebildiler."},{"n":98,"t":"Zülkarneyn, \"Bu, Rabbimin bir rahmetidir. Rabbimin vaadi (kıyametin kopma vakti) gelince onu yerle bir eder. Rabbimin vaadi gerçektir\" dedi."},{"n":99,"t":"O gün biz onları bırakırız, dalga dalga birbirlerine karışırlar. Sonra sûra üfürülür de onları toptan bir araya getiririz."},{"n":"100-101","t":"O gün cehennemi; gözleri Zikr’ime (Kur’an’a) karşı perdeli olan ve onu dinleme zahmetine dahi katlanamayan kâfirlerin karşısına (bütün dehşetiyle) dikeriz!"},{"n":102,"t":"İnkâr edenler, beni bırakıp da kullarımı dost edineceklerini mi sandılar? Biz cehennemi kâfirlere konak olarak hazırladık."},{"n":"103-104","t":"(Ey Muhammed!) De ki: \"Amelce en çok ziyana uğrayan; iyi iş yaptıklarını sandıkları hâlde, dünya hayatındaki çabaları kaybolup giden kimseleri size haber verelim mi?\""},{"n":105,"t":"Onlar, Rab’lerinin âyetlerini ve O’na kavuşacaklarını inkâr eden, böylece amelleri boşa çıkan, o yüzden de kıyamet gününde amelleri için bir terazi kurmayacağımız kimselerdir."},{"n":106,"t":"İşte böyle. İnkâr etmeleri, âyetlerimi ve Peygamberlerimi alay konusu yapmaları yüzünden onların cezası cehennemdir."},{"n":"107-108","t":"Şüphesiz, inanıp yararlı işler yapanlara gelince, onlar için içlerinde ebedî kalacakları Firdevs cennetleri bir konaktır. Oradan ayrılmak istemezler."},{"n":109,"t":"De ki: \"Rabbimin sözlerini yazmak için denizler mürekkep olsa ve bir o kadar da ilave etsek (denizlere deniz katsak); Rabbimin sözleri tükenmeden önce denizler tükenirdi.\""},{"n":110,"t":"De ki: \"Ben de ancak sizin gibi bir insanım. (Ne var ki) bana, ‘Sizin ilâh’ınız ancak bir tek ilâhtır\" diye vahyolunuyor. Kim Rabbine kavuşmayı umuyorsa yararlı bir iş yapsın ve Rabbine ibadette kimseyi ortak koşmasın.\""}],[{"n":1,"t":"Kâf Hâ Yâ Ayn Sâd."},{"n":2,"t":"Bu, Rabbinin, Zekeriya kuluna olan merhametinin anılmasıdır."},{"n":3,"t":"Hani o, Rabbine gizli bir sesle yalvarmıştı."},{"n":4,"t":"O, şöyle demişti: \"Rabbim! Şüphesiz kemiklerim gevşedi. Saçım sakalım ağardı. Sana yaptığım dualarda (cevapsız bırakılarak) hiç mahrum olmadım.\""},{"n":"5-6","t":"\"Gerçek şu ki ben, benden sonra gelecek akrabalarım(ın isyankâr olmaların)dan korkuyorum. Karım ise kısırdır. Bana kendi tarafından; bana ve Yakub hanedanına varis olacak bir çocuk bağışla ve onu hoşnutluğuna ulaşmış bir kimse kıl!\""},{"n":7,"t":"(Allah, şöyle dedi:) \"Ey Zekeriyya! Haberin olsun ki biz sana Yahya adlı bir oğul müjdeliyoruz. Daha önce onun adını kimseye vermedik.\""},{"n":8,"t":"Zekeriyya, \"Rabbim!\" \"Hanımım kısır ve ben de ihtiyarlığın son noktasına ulaşmış iken, benim nasıl çocuğum olur?\" dedi."},{"n":9,"t":"(Vahiy meleği) dedi ki: Evet, öyle. (Ancak) Rabbin diyor ki: \"Bu, bana göre kolaydır. Nitekim daha önce, hiçbir şey değil iken seni de yarattım.\""},{"n":10,"t":"Zekeriyya, \"Rabbim, öyleyse bana (çocuğumun olacağına) bir işaret ver\", dedi. Allah da, \"Senin işaretin, sapasağlam olduğun hâlde insanlarla (üç gün) üç gece konuşamamandır\" dedi."},{"n":11,"t":"Derken Zekeriya ibadet yerinden halkının karşısına çıktı. (Konuşmak istedi, konuşamadı) ve onlara \"Sabah akşam Allah’ı tespih edin\" diye işaret etti."},{"n":"12-14","t":"(Yahya, dünyaya gelip büyüyünce onu peygamber yaptık ve kendisine) \"Ey Yahya, kitaba sımsıkı sarıl\" dedik. Biz, ona daha çocuk iken hikmet ve katımızdan kalp yumuşaklığı ve ruh temizliği vermiştik. O, Allah’tan sakınan, anne babasına iyi davranan bir kimse idi. İsyancı bir zorba değildi."},{"n":15,"t":"Doğduğu gün, öleceği gün ve diriltileceği gün ona selâm olsun!"},{"n":"16-17","t":"(Ey Muhammed!) Kitap’ta (Kur’an’da) Meryem’i de an. Hani ailesinden ayrılarak doğu tarafında bir yere çekilmiş ve (kendini onlardan uzak tutmak için) onlarla arasında bir perde germişti. Biz, ona Cebrail’i göndermiştik de ona tam bir insan şeklinde görünmüştü."},{"n":18,"t":"Meryem, \"Senden, Rahmân’a sığınırım. Eğer Allah’tan çekinen biri isen (bana kötülük etme)\" dedi."},{"n":19,"t":"Cebrail, \"Ben ancak Rabbinin elçisiyim. Sana tertemiz bir çocuk bağışlamak için gönderildim\" dedi."},{"n":20,"t":"Meryem, \"Bana hiçbir insan dokunmadığı ve iffetsiz bir kadın olmadığım hâlde, benim nasıl çocuğum olabilir?\" dedi."},{"n":21,"t":"Cebrail, \"Evet, öyle. Rabbin diyor ki: O benim için çok kolaydır. Onu insanlara bir mucize, katımızdan bir rahmet kılmak için böyle takdir ettik. Bu, zaten (ezelde) hükme bağlanmış bir iştir\" dedi."},{"n":22,"t":"Böylece Meryem, çocuğa gebe kaldı ve onunla uzak bir yere çekildi."},{"n":23,"t":"Doğum sancısı onu bir hurma ağacına yöneltti. \"Keşke bundan önce ölseydim de unutulup gitmiş olsaydım!\" dedi."},{"n":24,"t":"Bunun üzerine (Cebrail) ağacın altından ona şöyle seslendi: \"Üzülme, Rabbin senin alt tarafında bir dere akıttı.\""},{"n":25,"t":"\"Hurma ağacını kendine doğru silkele ki sana taze hurma dökülsün.\""},{"n":26,"t":"\"Ye, iç, gözün aydın olsun. İnsanlardan birini görecek olursan, \"Şüphesiz ben Rahmân’a susmayı adadım. Bugün hiçbir insan ile konuşmayacağım\" de."},{"n":27,"t":"Kucağında çocuğu ile halkının yanına geldi. Onlar şöyle dediler: \"Ey Meryem! Çok çirkin bir şey yaptın!\""},{"n":28,"t":"\"Ey Hârûn’un kız kardeşi! Senin baban kötü bir kimse değildi. Annen de iffetsiz değildi.\""},{"n":29,"t":"Bunun üzerine (Meryem, çocukla konuşun diye) ona işaret etti. \"Beşikteki bir bebekle nasıl konuşuruz?\" dediler."},{"n":30,"t":"Bebek şöyle konuştu: \"Şüphesiz ben Allah’ın kuluyum. Bana kitabı (İncil’i) verdi ve beni bir peygamber yaptı.\""},{"n":31,"t":"\"Nerede olursam olayım beni kutlu ve erdemli kıldı ve bana yaşadığım sürece namazı ve zekâtı emretti.\""},{"n":32,"t":"\"Beni anama saygılı kıldı. Beni azgın bir zorba kılmadı.\""},{"n":33,"t":"\"Doğduğum gün, öleceğim gün ve diriltileceğim gün bana selâm (esenlik verilmiştir).\""},{"n":34,"t":"Hakkında şüpheye düştükleri hak söze göre Meryem oğlu İsa işte budur."},{"n":35,"t":"Allah’ın çocuk edinmesi düşünülemez. O, bundan yücedir, uzaktır. Bir işe hükmettiği zaman ona sadece \"ol!\" der ve o da oluverir."},{"n":36,"t":"Şüphesiz, Allah, benim de Rabbim, sizin de Rabbinizdir. Öyleyse (yalnız) O’na kulluk edin. Bu, dosdoğru bir yoldur."},{"n":37,"t":"(Fakat hıristiyan) gruplar, aralarında ayrılığa düştüler. Büyük bir günü görüp yaşayacakları için vay kâfirlerin hâline!"},{"n":38,"t":"Bize gelecekleri gün (gerçekleri) ne iyi işitip ne iyi görecekler! Ama zalimler bugün apaçık bir sapıklık içindedirler."},{"n":39,"t":"Onları, gaflet içinde bulunup iman etmezlerken işin bitirileceği o pişmanlık günüyle uyar."},{"n":40,"t":"Şüphesiz yeryüzüne ve onun üzerindekilere biz varis olacağız, biz! Ancak bize döndürülecekler."},{"n":41,"t":"Kitap’ta İbrahim’i de an. Gerçekten o, son derece dürüst bir kimse, bir peygamber idi."},{"n":42,"t":"Hani babasına şöyle demişti: \"Babacığım! İşitmeyen, görmeyen ve sana bir faydası olmayan şeylere niçin tapıyorsun?\""},{"n":43,"t":"\"Babacığım! Doğrusu, sana gelmeyen bir ilim bana geldi. Bana uy ki seni doğru yola ileteyim.\""},{"n":44,"t":"\"Babacığım! Şeytana tapma! Çünkü şeytan Rahmân’a isyankâr olmuştur.\""},{"n":45,"t":"\"Babacığım! Doğrusu ben, sana, çok esirgeyici Rahmân tarafından bir azabın dokunmasından, böylece şeytana bir dost olmandan korkuyorum.\""},{"n":46,"t":"Babası, \"Ey İbrahim! Sen benim ilâhlarımdan yüz mü çeviriyorsun? Eğer vazgeçmezsen, mutlaka seni taşa tutarım. Uzun bir süre benden uzaklaş!\" dedi."},{"n":47,"t":"İbrahim, şöyle dedi: \"Esen kal! Senin için Rabbimden af dileyeceğim. Şüphesiz O, beni nimetleriyle kuşatmıştır.\""},{"n":48,"t":"\"Sizi ve Allah’tan başka taptıklarınızı terk ediyor ve Rabb’ime ibadet ediyorum. Rabbime ibadet etmekle de mutsuz olmayacağımı umuyorum.\""},{"n":49,"t":"İbrahim, onları da onların taptıklarını da terk edince, ona İshak ile Yakub’u bağışladık ve her birini peygamber yaptık."},{"n":50,"t":"Onlara rahmetimizden bağışta bulunduk. Onlar için yüce bir doğruluk dili var ettik (güzel bir söz ile anılmalarını temin ettik)."},{"n":51,"t":"Kitap’ta, Mûsâ’yı da an. Şüphesiz o seçkin bir insan idi. Bir resûl, bir nebî idi."},{"n":52,"t":"Ona, Tûr dağının sağ tarafından seslendik ve kendisi ile gizlice konuşmak için kendimize yaklaştırdık."},{"n":53,"t":"Rahmetimiz sonucu kardeşi Hârûn’u bir nebî olarak kendisine bahşettik."},{"n":54,"t":"Kitap’ta İsmail’i de an. Şüphesiz o, sözünde duran bir kimse idi. Bir resûl, bir nebî idi."},{"n":55,"t":"Ailesine namaz ve zekâtı emrederdi. Rabb’inin katında da hoşnutluğa ulaşmıştı."},{"n":56,"t":"Kitap’ta İdris’i de an. Şüphesiz o, doğru sözlü bir kimse, bir nebî idi."},{"n":57,"t":"Onu yüce bir makama yükselttik."},{"n":58,"t":"İşte bunlar, Âdem’in ve Nûh ile beraber (gemiye) bindirdiklerimizin soyundan, İbrahim’in, Yakub’un ve doğru yola iletip seçtiklerimizin soyundan kendilerine nimet verdiğimiz nebîlerdir. Kendilerine Rahmân’ın âyetleri okunduğu zaman ağlayarak secdeye kapanırlardı."},{"n":59,"t":"Onlardan sonra, namazı zayi eden, şehvet ve dünyevî tutkularının peşine düşen bir nesil geldi. Onlar bu tutumlarından ötürü büyük bir azaba çarptırılacaklardır."},{"n":"60-61","t":"Ancak tövbe edip inanan ve salih amel işleyenler başka. Onlar cennete, Rahmân’ın, kullarına gıyaben vaad ettiği \"Adn\" cennetlerine girecekler ve hiçbir haksızlığa uğratılmayacaklardır. Şüphesiz O’nun va’di kesinlikle gerçekleşir."},{"n":62,"t":"Orada boş söz işitmezler. Yalnızca (meleklerin) \"selâm!\" (deyişini) işitirler. Orada sabah akşam rızıkları da vardır."},{"n":63,"t":"İşte bu, kullarımızdan Allah’a karşı gelmekten sakınanlara miras kılacağımız cennettir."},{"n":64,"t":"(Cebrail, şöyle dedi:) \"Biz ancak Rabbinin emriyle ineriz. Önümüzdekiler, arkamızdakiler ve bunlar arasındakiler hep O’nundur. Rabbin unutkan değildir.\""},{"n":65,"t":"(Allah) göklerin, yerin ve bu ikisi arasındakilerin Rabbidir. Şu hâlde, O’na ibadet et ve O’na ibadet etmede sabırlı ol. Hiç, O’nun adını taşıyan bir başkasını biliyor musun?"},{"n":66,"t":"İnsan, \"Öldüğümde gerçekten diri olarak (topraktan) çıkarılacak mıyım?\" der."},{"n":67,"t":"İnsan, daha önce hiçbir şey değil iken kendisini yarattığımızı düşünmez mi?"},{"n":68,"t":"Rabbine andolsun, onları şeytanlarla beraber mutlaka haşredeceğiz. Sonra onları kesinlikle cehennemin çevresinde diz üstü hazır edeceğiz."},{"n":69,"t":"Sonra her bir topluluktan, Rahman’a karşı en isyankâr olanları mutlaka çekip çıkaracağız."},{"n":70,"t":"Sonra, oraya girmeye en lâyık olanları muhakkak ki en iyi biz biliriz."},{"n":71,"t":"(Ey insanlar!) Sizden cehenneme varmayacak hiç kimse yoktur. Rabbin için bu, kesin olarak hükme bağlanmış bir iştir."},{"n":72,"t":"Sonra Allah’a karşı gelmekten sakınanları kurtarırız da zalimleri orada diz üstü çökmüş hâlde bırakırız."},{"n":73,"t":"Âyetlerimiz kendilerine apaçık bir şekilde okunduğu zaman, inkâr edenler, inananlara, \"İki topluluktan hangisinin bulunduğu yer daha hayırlı meclis ve mahfili daha güzeldir?\" dediler."},{"n":74,"t":"Biz onlardan önce, mal mülk ve görünümü daha güzel olan nice nesilleri helâk ettik."},{"n":75,"t":"(Ey Muhammed!) De ki: \"Kim sapıklık içinde ise Rahmân onlara, istenildiği kadar süre versin! Nihayet kendilerine vaad olunan azabı, ya da kıyameti gördüklerinde kimin yeri daha kötüymüş, kimin taraftarları daha zayıfmış bilecekler."},{"n":76,"t":"Allah, doğruya erenlerin hidayetini artırır. Kalıcı salih ameller, Rabbinin katında sevap bakımından da daha hayırlıdır, sonuç itibari ile de."},{"n":77,"t":"Âyetlerimizi inkâr edip \"Bana elbette mal ve evlat verilecek!\" diyen kimseyi gördün mü?"},{"n":78,"t":"Gaybı mı görüp bilmiş, yoksa Rahmân’dan bir söz mü almış?"},{"n":79,"t":"Hayır! (İş onun dediği gibi değil). Biz, onun söylediklerini yazacağız ve azabını arttırdıkça arttıracağız!"},{"n":80,"t":"Onun (ahirette sahip olacağını) söylediği şeylere biz varis olacağız ve o bize tek başına gelecek."},{"n":81,"t":"Onlar, kendileri için kuvvet ve şeref (kaynağı) olsunlar diye, Allah’tan başka ilâhlar edindiler."},{"n":82,"t":"Hayır! İlâhları, onların ibadetlerini inkâr edecekler ve kendilerine düşman olacaklar."},{"n":83,"t":"Kâfirlerin başına, onları durmadan (günaha ve azgınlığa) tahrik eden şeytanları gönderdiğimizi görmedin mi?"},{"n":84,"t":"Ey Muhammed! Şu hâlde, onların azaba uğramalarını istemekte acele etme. Biz onlar için ancak (takdir ettiğimiz günleri) sayıp durmaktayız."},{"n":"85-86","t":"Allah’a karşı gelmekten sakınanları Rahmân’ın huzurunda bir elçiler heyeti gibi toplayacağımız, suçluları da suya koşan susuz develer gibi cehenneme sevk edeceğimiz günü düşün!"},{"n":87,"t":"Rahmân’ın katında söz almış olanlardan başkaları şefaat hakkına sahip olmayacaklardır."},{"n":88,"t":"Onlar, \"Rahmân, bir çocuk edindi\" dediler."},{"n":89,"t":"Andolsun, siz çok çirkin bir şey ortaya attınız."},{"n":"90-91","t":"Rahman’a çocuk isnat etmelerinden dolayı neredeyse gökler parçalanacak, yer yarılacak, dağlar yıkılıp çökecektir!"},{"n":92,"t":"Hâlbuki Rahmân’a bir çocuk edinmek yakışmaz."},{"n":93,"t":"Göklerdeki ve yerdeki herkes Rahman’a kul olarak gelecektir."},{"n":94,"t":"Andolsun, Allah onları ilmiyle kuşatmış ve tek tek saymıştır."},{"n":95,"t":"Onlar(ın her biri) kıyamet günü O’na tek başına gelecektir."},{"n":96,"t":"İnanıp salih ameller işleyenler için Rahmân, (gönüllere) bir sevgi koyacaktır."},{"n":97,"t":"Ey Muhammed! Biz, Allah’a karşı gelmekten sakınanları Kur’an ile müjdeleyesin, inat eden bir topluluğu da uyarasın diye, onu senin dilin ile (indirip) kolaylaştırdık."},{"n":98,"t":"Biz onlardan önce nice nesilleri helâk ettik. Onlardan hiçbirini hissediyor yahut onların bir fısıltısını olsun işitiyor musun?"}],[{"n":1,"t":"Tâ Hâ."},{"n":"2-3","t":"(Ey Muhammed!) Biz, Kur’an’ı sana sıkıntı çekesin diye değil, ancak (Allah’ın azabından) korkacaklara bir öğüt (bir uyarı) olsun diye indirdik."},{"n":4,"t":"(O) yüksek gökleri yaratanın katından peyderpey indirilmiştir."},{"n":5,"t":"Rahmân, Arş’a kurulmuştur."},{"n":6,"t":"Göklerdeki, yerdeki bu ikisi arasındaki ve toprağın altındaki her şey, yalnızca O’nundur."},{"n":7,"t":"Sen sözü açığa vursan da, gizlesen de Allah için birdir. Çünkü O, gizliyi de bilir, ondan daha gizli olanı da."},{"n":8,"t":"Allah, kendisinden başka hiçbir ilâh bulunmayandır. En güzel isimler O’nundur."},{"n":9,"t":"Mûsâ’nın haberi sana ulaştı mı?"},{"n":10,"t":"Hani bir ateş görmüştü de ailesine, \"Siz burada kalın, ben bir ateş gördüm (oraya gidiyorum). Umarım ondan size bir kor ateş getiririm, yahut ateşin başında, yol gösterecek birini bulurum\" demişti."},{"n":11,"t":"Ateşin yanına varınca, ona şöyle seslenildi: \"Ey Mûsâ!\""},{"n":12,"t":"\"Şüphe yok ki, ben senin Rabbinim. Hemen ayakkabılarını çıkar. Çünkü sen mukaddes vadi Tuvâ’dasın.\""},{"n":13,"t":"\"Ben seni (peygamber olarak) seçtim. Şimdi vahyolunacak şeyleri dinle.\""},{"n":14,"t":"\"Şüphe yok ki ben Allah’ım. Benden başka hiçbir ilâh yoktur. O hâlde bana ibadet et ve beni anmak için namaz kıl.\""},{"n":15,"t":"\"Kıyamet mutlaka gelecektir. Herkes işlediğinin karşılığını görsün diye, neredeyse onu gizleyecek (geleceğinden hiç söz etmeyecek)tim.\""},{"n":16,"t":"\"Buna inanmayan ve nefsinin arzusuna uyan kimseler, seni ondan (ona hazırlanmaktan) sakın alıkoymasın, sonra helâk olursun!\""},{"n":17,"t":"\"Şu sağ elindeki nedir ey Mûsâ?\""},{"n":18,"t":"Mûsâ dedi ki: \"O benim değneğimdir. Ona dayanırım, onunla koyunlarıma yaprak silkelerim. Onunla başka işlerimi de görürüm.\""},{"n":19,"t":"Allah, \"Onu yere at ey Mûsâ!\" dedi."},{"n":20,"t":"Mûsâ da onu attı. Bir de ne görsün o, hızla akan bir yılan olmuş!"},{"n":21,"t":"Allah, şöyle dedi: \"Tut onu. Korkma! Biz, onu yine eski durumuna döndüreceğiz.\""},{"n":"22-23","t":"\"Sana büyük mucizelerimizden birini daha göstermemiz için elini koynuna sok ki bir başka mucize olarak, (alaca hastalığı gibi) bir hastalık sebebiyle olmaksızın bembeyaz bir hâlde çıksın.\""},{"n":24,"t":"\"Firavun’a git, çünkü o azmıştır.\""},{"n":25,"t":"Mûsâ, dedi ki: \"Rabbim! Gönlüme ferahlık ver.\""},{"n":26,"t":"\"İşimi bana kolaylaştır.\""},{"n":"27-28","t":"\"Dilimdeki tutukluğu çöz ki sözümü anlasınlar.\""},{"n":29,"t":"\"Bana ailemden birini yardımcı yap,\""},{"n":30,"t":"\"Kardeşim Hârûn’u.\""},{"n":31,"t":"\"Onunla gücümü artır.\""},{"n":32,"t":"\"Onu işime ortak et.\""},{"n":33,"t":"\"Seni çok tespih edelim diye\","},{"n":34,"t":"\"Seni çok zikredelim diye.\""},{"n":35,"t":"\"Çünkü sen bizi hakkıyla görmektesin.\""},{"n":36,"t":"Allah, şöyle dedi: \"İstediğin sana verildi ey Mûsâ!\""},{"n":37,"t":"\"Andolsun, biz sana bir kere daha iyilikte bulunmuştuk.\""},{"n":38,"t":"\"Hani annene ilham edilmesi gereken şeyleri ilham etmiştik:\""},{"n":39,"t":"\"Onu (bebek Mûsâ’yı) sandığın içine koy ve denize (Nil’e) bırak ki, deniz onu kıyıya atsın da kendisini, hem bana düşman, hem de ona düşman olan birisi (Firavun) alsın. Sana da, ey Mûsâ, sevilesin ve gözetimimizde yetiştirilesin diye tarafımızdan bir sevgi bırakmıştım.\""},{"n":40,"t":"\"Hani kız kardeşin (Firavun ailesine) gidiyor ve \"size onun bakımını üstlenecek kimseyi göstereyim mi?\" diyordu. Derken, gözü aydın olsun, üzülmesin diye seni annene döndürdük. (Sana baktı, büyüdün) ve (kazara) bir cana kıydın da biz seni kederden kurtardık, seni sıkı bir denemeden geçirdik (ve kaçıp Medyen’e gittin). Medyen halkı içinde yıllarca kaldın, sonra (peygamber olman için) takdir edilmiş bir zamanda (Tûr’a) geldin ey Mûsâ!\""},{"n":41,"t":"\"Ben seni kendim için seçtim.\""},{"n":42,"t":"\"Sen ve kardeşin mucizelerim ile (desteklenmiş olarak) gidin ve beni anmakta gevşeklik göstermeyin.\""},{"n":43,"t":"\"Firavun’a gidin. Çünkü o azmıştır.\""},{"n":44,"t":"\"Ona yumuşak söz söyleyin. Belki öğüt alır, yahut korkar.\""},{"n":45,"t":"Mûsâ ve Hârûn, şöyle dediler: \"Ey Rabbimiz! Şüphesiz biz, onun bize karşı aşırı davranmasından yahut azmasından korkuyoruz.\""},{"n":46,"t":"Allah, şöyle dedi: \"Korkmayın, çünkü ben sizinle beraberim. İşitirim ve görürüm.\""},{"n":47,"t":"\"Ona gidin ve şöyle deyin: ‘Şüphesiz biz Rabbinin elçileriyiz. İsrailoğullarını (serbest bırak ve) bizimle gönder. Onlara işkence etme. Sana Rabbinin katından bir mucize getirdik. Selâm, doğru yola uyanlara olsun.’ \""},{"n":48,"t":"\"Şüphesiz bize, azabın yalanlayan ve yüz çevirenlere olacağı vahyolundu.\""},{"n":49,"t":"Firavun, \"Sizin Rabbiniz kim, ey Mûsâ?\" dedi."},{"n":50,"t":"Mûsâ, \"Rabbimiz, her şeye hilkatini (yaratılış özelliklerini) veren, sonra onlara yol gösterendir\" dedi."},{"n":51,"t":"Firavun, \"Ya geçmiş nesillerin hâli ne olacak?\" dedi."},{"n":52,"t":"Mûsâ, şöyle dedi: \"Onlar hakkındaki bilgi Rabbimin katında bir kitapta (Levh-i Mahfuz’da yazılı)dır. Rabbim, yanılmaz ve unutmaz.\""},{"n":53,"t":"\"Rabbim, yeryüzünü size beşik yapan, orada size yollar açan ve size gökten yağmur indirendir.\" Böylece onunla sizin için yerden türlü türlü bitkileri çift çift çıkardık."},{"n":54,"t":"Yiyin, hayvanlarınızı yayın. Şüphesiz bunda akıl sahipleri için (Allah’ın varlığını ve birliğini gösteren) deliller vardır."},{"n":55,"t":"(Ey insanlar!) Sizi topraktan yarattık, (ölümünüzle) sizi oraya döndüreceğiz ve sizi bir kere daha oradan çıkaracağız."},{"n":56,"t":"Andolsun, biz ona (Firavun’a) bütün mucizelerimizi gösterdik de o bunları yalanladı ve reddetti."},{"n":57,"t":"Şöyle dedi: \"Ey Mûsâ! Sihrin ile bizi yurdumuzdan çıkarmak için mi geldin?\""},{"n":58,"t":"\"Biz de mutlaka sana karşı onun gibi bir sihir yapacağız. Bunun için seninle bizim aramızda; uygun bir yerde, senin de, bizim de caymayacağımız bir buluşma vakti belirle.\""},{"n":59,"t":"Mûsâ, \"Buluşma vaktimiz, bayram günü, insanların toplandığı kuşluk vaktidir\" dedi."},{"n":60,"t":"Bunun üzerine Firavun ayrılıp, hilesini kuracak sihirbazlarını topladı, sonra geldi."},{"n":61,"t":"Mûsâ, onlara şöyle dedi: \"Yazıklar olsun size! Allah’a karşı yalan uydurmayın, yoksa sizi azap ile yok eder. Allah’a karşı yalan uyduran mutlaka hüsrana uğramıştır.\""},{"n":62,"t":"Sihirbazlar, işlerini kendi aralarında tartıştılar ve gizli gizli konuştular."},{"n":63,"t":"Şöyle dediler: \"Şüphesiz bu ikisi, sihirleri ile sizi yurdunuzdan çıkarmak ve en üstün olan dininizi ortadan kaldırmak isteyen birer sihirbazdırlar.\""},{"n":64,"t":"\"Öyleyse, hilelerinizi toplayın (birbirinize destek olun) sonra sıra hâlinde gelin. Bu gün üstün gelen muhakkak başarıya ulaşmıştır.\""},{"n":65,"t":"Sihirbazlar: \"Ey Mûsâ! Ya önce atmayı tercih edersin, ya da ilk atan biz oluruz\" dediler."},{"n":66,"t":"Mûsâ: \"Yok, (önce) siz atın\" dedi. Bir de ne görsün, onların ipleri ve değnekleri yaptıkları sihirden dolayı kendisine hızla sürünür gibi görünüyor."},{"n":67,"t":"Bunun üzerine Mûsâ, içinde bir korku hissetti."},{"n":68,"t":"Şöyle dedik: \"Korkma (ey Mûsâ!). Çünkü, sensin en üstün olan.\""},{"n":69,"t":"\"Sağ elindekini (değneğini) at ki, onların yaptıklarını yutsun. Şüphesiz yaptıkları bir sihirbaz hilesidir. Sihirbaz ise nereye varsa kurtuluşa eremez.\""},{"n":70,"t":"(Mûsâ’nın değneği, sihirbazların ipleriyle değneklerini yutunca) sihirbazlar hemen secdeye kapandılar ve, \"Hârûn ve Mûsâ’nın Rabbine inandık\" dediler."},{"n":71,"t":"Firavun, \"Demek, ben size izin vermeden önce ona (Mûsâ’ya) inandınız ha! Şüphe yok, o size sihiri öğreten büyüğünüzdür. Şimdi andolsun, sizin ellerinizi ve ayaklarınızı çaprazlama keseceğim ve mutlaka sizi hurma dallarına asacağım. Hangimizin azabı daha şiddetli ve daha kalıcıymış, mutlaka göreceksiniz.\""},{"n":72,"t":"Sihirbazlar şöyle dediler: \"Bize gelen apaçık delillere ve bizi yaratana seni asla tercih etmeyeceğiz. Artık sen vereceğin hükmü ver. Sen ancak bu dünya hayatında hüküm verirsin.\""},{"n":73,"t":"\"Şüphesiz ki biz; günahlarımızı ve bize zorla yaptırdığın sihri affetmesi için, Rabbimize inandık. Allah’ın vereceği mükâfat daha hayırlı ve daha kalıcıdır.\""},{"n":74,"t":"Şüphesiz, kim Rabbine günahkâr olarak varırsa, kesinlikle ona cehennem vardır. Orada ne ölür, ne de (güzel bir hayat) yaşar."},{"n":"75-76","t":"Her kim de O’na salih ameller işlemiş bir mü’min olarak varırsa, işte onlar için en yüksek dereceler, içinden ırmaklar akan, içinde ebediyyen kalacakları Adn cennetleri vardır. İşte bu, günahlardan temizlenenlerin mükâfatıdır."},{"n":77,"t":"(Firavun’un imana yanaşmaması üzerine) Mûsâ’ya, \"Kullarımı (İsrailoğullarını) geceleyin (Mısır’dan) yürütüp çıkar. Yakalanmaktan korkmaksızın, endişe etmeksizin onlara denizde kuru bir yol aç\" diye vahyettik."},{"n":78,"t":"Bunun üzerine Firavun askerleriyle birlikte onların peşine düştü de, deniz onları görülmedik bir şekilde kuşatıp yuttu."},{"n":79,"t":"Firavun, halkını saptırdı, onlara doğru yolu göstermedi."},{"n":80,"t":"(Allah, şöyle dedi:) \"Ey İsrailoğulları! Sizi düşmanınızdan kurtardık, size Tûr’un sağ yanını va’dettik ve size kudret helvası ile bıldırcın indirdik.\""},{"n":81,"t":"\"Size rızık olarak verdiğimiz şeylerin temiz ve helâl olanlarından yiyin. Bu konuda aşırı da gitmeyin, yoksa üzerinize gazabım iner. Gazabım da kimin üzerine inerse, o muhakkak helâk olmuş demektir.\""},{"n":82,"t":"\"Şüphe yok ki ben, tövbe edip inanan ve salih ameller işleyen, sonra da doğru yol üzere devam eden kimse için son derece affediciyim.\""},{"n":83,"t":"(Mûsâ, Tûr’a varınca): \"Seni, acele ile kavminden uzaklaştıran nedir, ey Mûsâ?\" (dedik.)"},{"n":84,"t":"Mûsâ, şöyle dedi: \"Onlar, işte onlar hemen arkamdalar. Rabbim! Sen hoşnut olasın diye, acele ederek sana geldim.\""},{"n":85,"t":"Allah, \"Şüphesiz, biz senden sonra halkını sınadık; Sâmirî onları saptırdı\" dedi."},{"n":86,"t":"Bunun üzerine Mûsâ, öfke dolu ve üzgün bir hâlde halkına döndü. \"Ey kavmim! Rabbiniz, size güzel bir vaadde bulunmadı mı? (Ayrılışımdan sonra) çok zaman mı geçti, yoksa üzerinize Rabbinizden bir gazap inmesini mi istediniz de bana verdiğiniz söze uymadınız (ve buzağıya taptınız)?\" dedi."},{"n":87,"t":"Şöyle dediler: \"Sana verdiğimiz sözden kendi isteğimizle caymış değiliz. Fakat biz Mısır halkının mücevheratından yüklü miktarlarda takınmıştık. İşte onları ateşe attık. Sâmirî de aynı şekilde attı.\""},{"n":88,"t":"Böylece (Sâmirî) onlar için böğürmesi olan bir buzağı heykeli ortaya çıkardı. (Sâmirî ve adamları) \"Bu sizin de ilâhınızdır, Mûsâ’nın da ilâhıdır. Öyle iken Mûsâ, (ilâhını burada) unuttu (da onu Tûr’da aramaya gitti)\" dediler."},{"n":89,"t":"Onlar bu heykelin, sözlerine karşılık vermediğini, kendilerinden hiçbir zararı uzaklaştıramayacağını ve onlara hiçbir fayda sağlayamayacağını görmezler mi?"},{"n":90,"t":"Andolsun, Hârûn onlara daha önce şöyle demişti: \"Ey kavmim! Siz bununla yalnızca imtihan edildiniz. Doğrusu sizin Rabbiniz ancak Rahmân’dır. Öyleyse bana uyun ve emrime itaat edin.\""},{"n":91,"t":"Onlar da, \"Mûsâ bize dönünceye kadar buzağıya ibadet etmeye devam edeceğiz\" dediler."},{"n":"92-93","t":"Mûsâ, (Tûr’dan dönünce) şöyle dedi: \"Ey Hârûn! Saptıklarını gördüğün zaman bana uymana ne engel oldu? Yoksa emrime karşı mı geldin?\""},{"n":94,"t":"Hârûn: \"Ey anam oğlu! Saçımı sakalımı çekme. Şüphesiz ben, İsrailoğullarının arasını açtın, sözüme uymadın demenden korktum\" dedi."},{"n":95,"t":"Mûsâ, \"Ya senin derdin neydi ey Sâmirî?\" dedi."},{"n":96,"t":"Sâmirî, şöyle dedi: \"Ben onların görmediği şeyi gördüm. Elçinin izinden bir avuç avuçladım da onu attım. Böyle yapmayı bana nefsim güzel gösterdi.\""},{"n":97,"t":"Mûsâ, \"Çekil git! Artık sen hayatın boyunca (hastalanıp) \"Bana dokunmak yok!\" diyeceksin. Senin için, asla kaçamayacağın bir ceza daha var. Hele şu ibadet edip durduğun ilâhına bak! Biz onu elbette yakacağız ve onu muhakkak denize savuracağız."},{"n":98,"t":"Sizin ilâhınız ancak kendisinden başka hiçbir ilâh bulunmayan Allah’tır. O, ilmiyle her şeyi kuşatmıştır."},{"n":99,"t":"(Ey Muhammed!) Sana geçmişin haberlerinden bir kısmını böylece anlatıyoruz. Şüphe yok ki sana katımızdan bir zikir (Kur’an) verdik."},{"n":100,"t":"Kim ondan yüz çevirirse şüphesiz ki o, kıyamet gününde ağır bir günah yükü yüklenecektir."},{"n":101,"t":"Onlar o günahın cezası içinde ebediyen kalacaklardır. Sûra üfürüleceği gün, bu ağır yük onlar için ne kötü bir yüktür!"},{"n":102,"t":"O gün günahkârları, (gözleri korkudan donup) gömgök kesilmiş olarak haşredeceğiz."},{"n":"103-104","t":"Aralarında birbirlerine \"(Dünya’da) sadece on (gün) kaldınız\" diye gizli gizli konuşacaklar. -Onların, hakkında konuşacakları şeyi biz daha iyi biliriz.- O vakit içlerinden en aklı başında olanları, \"Siz sadece bir gün kaldınız\" diyecektir."},{"n":105,"t":"(Ey Muhammed!) Sana dağların (kıyamet günündeki) hâlini soruyorlar. De ki: \"Rabbim onları toz edip savuracak.\""},{"n":106,"t":"\"Onların yerlerini dümdüz, boş bir alan hâlinde bırakacaktır.\""},{"n":107,"t":"\"Orada hiçbir çukur, hiçbir tümsek göremeyeceksin.\""},{"n":108,"t":"O gün kendisinden yan çizmek mümkün olmayan davetçiye (İsrâfil’e) uyarlar. Sesler, Rahmân’ın azametinden dolayı kısılmıştır. Artık sadece fısıltı işitebilirsin."},{"n":109,"t":"O gün, Rahmân’ın izin verdiği ve sözünden razı olduğu kimseden başkasının şefaati fayda vermez."},{"n":110,"t":"O, önlerindekini ve arkalarındakini (dünyadaki ve ahiretteki durumlarını) bilir. Onların bilgisi ise Rahmân’ı kuşatamaz."},{"n":111,"t":"Bütün yüzler; diri, yaratıklarına hâkim ve onları koruyup gözeten Allah’a boyun eğmiştir. Zulüm yüklenen, mutlaka hüsrana uğramıştır."},{"n":112,"t":"Kim de inanmış olarak salih ameller işlerse, o, ne zulme uğramaktan korkar, ne yoksun bırakılmaktan."},{"n":113,"t":"İşte böylece biz onu Arapça bir Kur’an olarak indirdik ve Allah’a karşı gelmekten sakınsınlar, yahut onlara bir uyarı versin diye onda tehditleri teker teker sıraladık."},{"n":114,"t":"Gerçek hükümdar olan Allah yücedir. Sana vahyedilmesi tamamlanmadan önce Kur’an’ı okumakta acele etme. \"Rabbim! İlmimi arttır\" de."},{"n":115,"t":"Andolsun, bundan önce biz Âdem’e (cennetteki ağacın meyvesinden yeme, diye) emrettik. O ise bunu unutuverdi. Biz onda bir kararlılık bulmadık."},{"n":116,"t":"Hani meleklere, \"Âdem için saygı ile eğilin\" demiştik de, İblis’ten başka melekler hemen saygı ile eğilmişler; İblis bundan kaçınmıştı."},{"n":117,"t":"Biz de şöyle dedik: \"Ey Âdem! Şüphesiz bu (İblis), sen ve eşin için bir düşmandır. Sakın sizi cennetten çıkarmasın; sonra mutsuz olursun.\""},{"n":118,"t":"\"Şüphesiz senin için orada aç kalmak, çıplak kalmak yoktur.\""},{"n":119,"t":"\"Orada ne susuzluk çekersin, ne de güneş altında kalırsın.\""},{"n":120,"t":"Nihayet şeytan ona vesvese verip şöyle dedi: \"Ey Âdem! Sana ebedîlik ağacını ve yok olmayan bir saltanatı göstereyim mi?\""},{"n":121,"t":"Bunun üzerine onlar (Âdem ve eşi Havva) o ağacın meyvesinden yediler. Bu sebeple ayıp yerleri kendilerine göründü ve cennet yaprağından üzerlerine örtmeye başladılar. Âdem, Rabbine isyan etti ve yolunu şaşırdı."},{"n":122,"t":"Sonra Rabbi onu seçti, tövbesini kabul etti ve ona doğru yolu gösterdi."},{"n":123,"t":"Allah, şöyle dedi: \"Birbirinize düşman olarak hepiniz oradan inin. Eğer tarafımdan size bir yol gösterici (kitap) gelir de, kim benim yol göstericime uyarsa artık o, ne (dünyada) sapar ne de (ahirette) sıkıntı çeker.\""},{"n":124,"t":"\"Her kim de benim zikrimden (Kur’an’dan) yüz çevirirse, mutlaka ona dar bir geçim vardır. Bir de onu kıyamet gününde kör olarak haşrederiz.\""},{"n":125,"t":"O da şöyle der: \"Rabbim! Dünyada gören bir kimse olduğum hâlde, niçin beni kör olarak haşrettin?\""},{"n":126,"t":"Allah, \"Evet, öyle. Âyetlerimiz sana geldi de sen onları unuttun. Aynı şekilde bugün de sen unutuluyorsun\" der."},{"n":127,"t":"Haddi aşan ve Rabbi’nin âyetlerine inanmayanları işte böyle cezalandırırız. Şüphesiz ahiret azabı daha şiddetli ve daha kalıcıdır."},{"n":128,"t":"Yurtlarında dolaşıp durdukları, kendilerinden önceki nice nesilleri helâk etmiş olmamız, onları doğru yola iletmedi mi? Şüphesiz bunda akıl sahipleri için ibretler vardır."},{"n":129,"t":"Rabbin tarafından daha önce söylenmiş bir hüküm ve belirlenmiş bir süre olmasaydı, onlar da hemen cezalandırılırlardı."},{"n":130,"t":"O hâlde, onların söylediklerine sabret ve güneşin doğuşundan ve batışından önce Rabbini hamd ile tespih et. Gece vakitlerinde ve gündüzün uçlarında da tespih et ki hoşnut olasın."},{"n":131,"t":"Onlardan bazı kesimlere, kendilerini sınamak için dünya hayatının süsü olarak verdiğimiz şeylere gözünü dikme. Rabbinin rızkı daha hayırlı ve daha kalıcıdır."},{"n":132,"t":"Ailene namazı emret ve kendin de ona devam et. Senden rızık istemiyoruz. Sana da biz rızık veriyoruz. Güzel sonuç, Allah’a karşı gelmekten sakınmanındır."},{"n":133,"t":"İnanmayanlar, \"Doğru söylediğine dair bize Rabbinden açık bir delil (bir mucize) getirse ya!\" dediler. Önceki kitaplarda olanların apaçık delili (olan Kur’an) onlara gelmedi mi?"},{"n":134,"t":"Eğer biz onları o Kur’an’dan önce bir azap ile helâk etseydik mutlaka, \"Ey Rabbimiz! Keşke bize bir peygamber gönderseydin de alçalıp rezil olmadan önce âyetlerine uysaydık\" derlerdi."},{"n":135,"t":"Ey Muhammed, de ki: \"Herkes beklemektedir, siz de bekleyin. Yakında kimin düz yolun sahipleri olduğunu, kimin doğru yolu bulduğunu bileceksiniz!\""}],[{"n":1,"t":"İnsanların hesaba çekilmeleri yaklaştı. Hâlbuki onlar gaflet içinde yüz çevirmekteler."},{"n":"2-3","t":"Rab’lerinden kendilerine yeni bir öğüt (bir uyarı) gelmez ki, onlar mutlaka onu alaya alarak, kalpleri de gaflette olarak dinlemesinler. O zulmedenler gizlice şöyle konuştular: \"Bu da ancak sizin gibi bir insan. Şimdi siz göz göre göre sihre mi kapılacaksınız?\""},{"n":4,"t":"Peygamber, onlara dedi ki: \"Rabbim yerdeki ve gökteki her sözü bilir. O, hakkıyla işitendir, hakkıyla bilendir.\""},{"n":5,"t":"Onlar, \"Hayır, bunlar karma karışık yalancı düşlerdir. Hayır, onu kendisi uydurdu; hayır, o bir şairdir. Eğer böyle değilse, önceki peygamberlerin (mucizelerle) gönderildikleri gibi o da bize bir mucize getirsin\" dediler."},{"n":6,"t":"Onlardan önce helâk ettiğimiz hiçbir memleket halkı iman etmedi de şimdi bunlar mı iman edecekler?"},{"n":7,"t":"Senden önce de ancak kendilerine vahyettiğimiz birtakım erkekleri peygamber gönderdik. Eğer bilmiyorsanız ilim sahiplerine sorun."},{"n":8,"t":"Biz, onları yemek yemez bir beden yapısında yaratmadık. Onlar ölümsüz de değillerdi."},{"n":9,"t":"Sonra onlara verdiğimiz sözü yerine getirdik. Kendilerini ve dilediğimiz kimseleri kurtardık. Haddi aşanları ise helâk ettik."},{"n":10,"t":"Andolsun, size öyle bir kitap indirdik ki sizin bütün şeref ve şanınız ondadır. Hâlâ aklınızı kullanmayacak mısınız?"},{"n":11,"t":"Biz zulmetmekte olan nice memleketleri kırıp geçirdik ve onlardan sonra başka başka toplumlar meydana getirdik."},{"n":12,"t":"Onlar azabımızı hissedince, hemen oradan süratle kaçıyorlardı."},{"n":13,"t":"Onlara, \"Kaçmayın, o içinde şımartıldığınız bolluğa ve yurtlarınıza dönün. Çünkü sorulacaksınız\" denildi."},{"n":14,"t":"\"Eyvah bizlere! Bizler gerçekten zalim kimseler idik\" dediler."},{"n":15,"t":"Biz onları biçilmiş ekin, sönmüş ateş gibi yapıncaya kadar bu feryatları devam etti."},{"n":16,"t":"Biz yeri, göğü ve arasındakileri oyun olsun diye yaratmadık."},{"n":17,"t":"Eğer bir eğlence edinmek isteseydik, onu kendi katımızdan edinirdik. Yapacak olsaydık böyle yapardık."},{"n":18,"t":"Hayır, biz hakkı batılın üzerine atarız da beynini parçalar. Bir de bakarsın yok olup gitmiş. Allah’a karşı yakıştırdığınız nitelemelerden ötürü yazıklar olsun size!"},{"n":19,"t":"Göklerde ve yerde kim varsa hep O’nundur. O’nun katındakiler, ne O’na ibadetten çekinir (ve büyüklenir) ne de yorgunluk (ve bıkkınlık) duyarlar."},{"n":20,"t":"Hiç ara vermeksizin gece gündüz tespih ederler."},{"n":21,"t":"Yoksa yerden, ölüleri diriltebilecek birtakım ilâhlar mı edindiler?"},{"n":22,"t":"Eğer yerde ve gökte Allah’tan başka ilâhlar olsaydı, kesinlikle ikisinin de düzeni bozulurdu. Demek ki, Arş’ın Rabbi Allah, onların nitelemelerinden uzaktır, yücedir."},{"n":23,"t":"O, yaptığından dolayı sorgulanamaz fakat onlar sorgulanırlar."},{"n":24,"t":"Yoksa ondan başka ilâhlar mı edindiler? De ki: \"Haydi getirin delilinizi! İşte benimle beraber olanların kitabı ve işte benden öncekilerin kitabı (Hiçbirinde birden fazla ilâh olduğuna dair hiçbir delil yok). Şüphesiz çokları hakkı bilmezler de bu sebeple yüz çevirirler.\""},{"n":25,"t":"Senden önce gönderdiğimiz bütün peygamberlere, \"Şüphesiz, benden başka hiçbir ilâh yoktur. Öyleyse bana ibadet edin\" diye vahyetmişizdir."},{"n":26,"t":"(Böyle iken) \"Rahmân, çocuk edindi\" dediler. O, böyle şeylerden uzaktır, yücedir. Hayır, (evlat diye niteledikleri) o melekler ikrama erdirilmiş kullardır."},{"n":27,"t":"Onlar Allah’tan önce söz söylemezler ve hep O’nun emriyle iş görürler."},{"n":28,"t":"Allah, onların önlerindekini de arkalarındakini de (yaptıklarını da yapacaklarını da) bilir. Onlar, O’nun razı olduğu kimselerden başkasına şefaat etmezler ve hepsi O’nun korkusuyla titrerler."},{"n":29,"t":"İçlerinden her kim, \"Allah’tan başka ben de şüphesiz bir ilâhım\" derse, böylesini cehennemle cezalandırırız. İşte biz zalimleri böyle cezalandırırız."},{"n":30,"t":"İnkâr edenler, göklerle yer bitişikken, bizim onları ayırdığımızı ve diri olan her şeyi sudan meydana getirdiğimizi görmediler mi? Hâlâ inanmayacaklar mı?"},{"n":31,"t":"Onları sarsmasın diye yere de sabit dağlar yerleştirdik ve (varacakları yere) yol bulabilsinler diye ondan geçitler, yollar meydana getirdik."},{"n":32,"t":"Gökyüzünü de korunmuş bir tavan yaptık. Onlar ise oradaki, (Allah’ın varlığını gösteren) delillerden yüz çevirmektedirler."},{"n":33,"t":"O, geceyi, gündüzü, güneşi ve ayı yaratandır. Her biri bir yörüngede yüzmektedirler."},{"n":34,"t":"Biz, senden önce de hiçbir beşere ölümsüzlük vermedik. Şimdi sen ölürsen, onlar ebedî mi kalacaklar?"},{"n":35,"t":"Her nefis ölümü tadacaktır. Sizi bir imtihan olarak hayır ile de şer ile de deniyoruz. Ancak bize döndürüleceksiniz."},{"n":36,"t":"İnkâr edenler seni gördükleri zaman ancak alaya alırlar. \"Bu mu ilâhlarınızı diline dolayan?\" derler. Hâlbuki kendileri Rahmân’ın kitabını inkâr ediyorlar."},{"n":37,"t":"İnsan çok aceleci (tez canlı) yaratılmıştır. Size yakında âyetlerimi göstereceğim. Şimdi acele etmeyin."},{"n":38,"t":"Bir de \"Eğer doğru söyleyenler iseniz, bu tehdit ne zaman gerçekleşecek?\" diyorlar."},{"n":39,"t":"İnkâr edenler, yüzlerinden ve sırtlarından ateşi savamayacakları ve hiçbir yardım da görmeyecekleri vakti bir bilseler!"},{"n":40,"t":"Şüphesiz o (tehdit edildikleri azap) onlara ansızın gelecek de kendilerini şaşkınlıktan dondurup bırakacak. Artık ne onu geri çevirmeye güçleri yetecek, ne de kendilerine göz açtırılacak."},{"n":41,"t":"Andolsun, senden önce de birçok peygamberle alay edildi de içlerinden alay edenleri, o alaya aldıkları şey kuşatıverdi."},{"n":42,"t":"(Ey Muhammed!) De ki: \"(Size azab edecek olsa) gece ve gündüz Rahmân’ın azabından sizi kim koruyacak?\" Öyle iken onlar Rablerinin zikrinden yüz çevirmekteler."},{"n":43,"t":"Yoksa bizim dışımızda onları koruyacak ilâhları mı var? O ilâh edindikleri nesneler kendilerine bile yardım edemezler. Zaten onlar bizden de yardım görmezler."},{"n":44,"t":"Evet, biz onları da atalarını da, faydalandırdık. Öyle ki uzun süre yaşadılar. Ama, artık görmüyorlar mı ki, biz yeryüzünü çevresinden eksiltiyoruz? O hâlde, onlar mı galip gelecekler?"},{"n":45,"t":"De ki: \"Ben sizi ancak vahy ile uyarıyorum.\" Ama sağırlar uyarıldıkları vakit çağrıyı işitmezler."},{"n":46,"t":"Andolsun, onlara Rabbinin azabından hafif bir esinti dokunsa, muhakkak \"Eyvah bize! Gerçekten biz zalim kimselerdik\" diyeceklerdir."},{"n":47,"t":"Kıyamet günü için adalet terazileri kuracağız. Öyle ki hiçbir kimseye zerre kadar zulmedilmeyecek. (Yapılan iş) bir hardal tanesi ağırlığınca da olsa, onu getirip ortaya koyacağız. Hesap görücü olarak biz yeteriz."},{"n":48,"t":"Andolsun, biz Mûsâ ile Hârûn’a, Allah’a karşı gelmekten sakınanlar için o Furkân’ı (Tevrat’ı) bir ışık ve öğüt olarak verdik."},{"n":49,"t":"Onlar, görmedikleri hâlde Rablerinden içten içe korkarlar. Onlar kıyamet gününden de korkarlar."},{"n":50,"t":"İşte bu (Kur’an) da bizim indirdiğimiz mübarek bir öğüttür. Şimdi siz bunu mu inkâr ediyorsunuz?"},{"n":51,"t":"Andolsun, daha önce de İbrahim’e doğruyu yanlıştan ayırma yeteneğini verdik. Biz zaten onu biliyorduk."},{"n":52,"t":"Hani o, babasına ve kavmine, \"Ne bu tapınıp durduğunuz heykeller?\" demişti."},{"n":53,"t":"\"Babalarımızı bunlara ibadet ediyor bulduk\" dediler."},{"n":54,"t":"İbrahim, \"Andolsun, siz de, atalarınız da apaçık bir sapıklık içindesiniz\" dedi."},{"n":55,"t":"\"Bize gerçeği mi getirdin, yoksa sen bizimle eğleniyor musun?\" dediler."},{"n":56,"t":"İbrahim, dedi ki: \"Hayır! Rabbiniz, göklerin ve yerin Rabbidir. O, bunları yaratandır ve ben de buna şahitlik edenlerdenim.\""},{"n":57,"t":"Allah’a yemin ederim ki, siz arkanızı dönüp gittikten sonra ben putlarınıza muhakkak bir tuzak kuracağım."},{"n":58,"t":"Derken (İbrahim) belki kendisine başvururlar diye içlerinden bir büyüğü bırakarak onları (putları) paramparça etti."},{"n":59,"t":"Onlar, \"Kim yaptı bunu tanrılarımıza! Muhakkak o zalimlerden biridir\" dediler."},{"n":60,"t":"(İçlerinden bazıları), \"İbrahim denilen bir gencin onları diline doladığını duyduk\" dediler."},{"n":61,"t":"(Bir kısmı da) \"O hâlde haydi, onu insanların gözü önüne getirin. Belki (bu konuda) şahitlik ederler\" dediler."},{"n":62,"t":"(İbrahim gelince) \"Sen mi yaptın bunu ilâhlarımıza ey İbrahim\" dediler."},{"n":63,"t":"Dedi ki: \"Hayır! Bunu şu büyükleri yapmıştır. Konuşabiliyorlarsa, onlara sorun bakalım!\""},{"n":64,"t":"Bunun üzerine birbirlerine dönüp, \"Hiç şüphesiz asıl zalimler sizsiniz siz\" dediler."},{"n":65,"t":"Sonra eski inanç ve inatlarına döndüler ve, \"Andolsun, bunların konuşmayacağını sen de bilirsin\" dediler."},{"n":66,"t":"İbrahim, şöyle dedi: \"Öyle ise siz, (hâlâ) Allah’ı bırakıp da, size hiçbir fayda, hiçbir zarar veremeyecek şeylere mi tapacaksınız?\""},{"n":67,"t":"\"Yazıklar olsun, size de; Allah’ı bırakıp tapmakta olduklarınıza da! Hâlâ aklınızı başınıza almayacak mısınız?\""},{"n":68,"t":"(İçlerinden bazıları), \"Eğer (bir şey) yapacaksanız, onu yakın da ilâhlarınıza yardım edin\" dediler."},{"n":69,"t":"\"Ey ateş! İbrahim’e karşı serin ve esenlik ol\" dedik."},{"n":70,"t":"Ona böyle bir tuzak kurmak istediler. Fakat biz onları en çok zarar edenler durumuna düşürdük."},{"n":71,"t":"Onu Lût ile beraber kurtarıp, içinde âlemler için bereketler kıldığımız yere ulaştırdık."},{"n":72,"t":"Ona İshak’ı ve ayrıca da Yakub’u bağışladık ve her birini salih kimseler yaptık."},{"n":73,"t":"Onları bizim emrimizle doğru yolu gösteren önderler yaptık ve kendilerine hayırlar işlemeyi, namazı dosdoğru kılmayı, zekâtı vermeyi vahyettik. Onlar sadece bize ibadet eden kimselerdi."},{"n":74,"t":"Biz, Lût’a da bir hikmet ve bir ilim verdik ve onu çirkin işler yapan memleketten kurtardık. Gerçekten onlar kötü bir toplum idiler, fasık (Allah’ın emrinden çıkan kimseler) idiler."},{"n":75,"t":"Onu rahmetimizin içine soktuk. Çünkü o, gerçekten salih kimselerdendi."},{"n":76,"t":"(Ey Muhammed!) Nûh’u da hatırla. Hani o daha önce dua etmişti de biz onun duasını kabul ederek, kendisini ve ailesini o büyük sıkıntıdan (tufandan) kurtarmıştık."},{"n":77,"t":"Âyetlerimizi yalanlayanlara karşı ona yardım etmiştik. Şüphesiz onlar kötü bir toplumdu. Bu yüzden biz de onları topyekûn suda boğduk."},{"n":78,"t":"Dâvûd ile Süleyman’ı da hatırla. Hani bir ekin tarlası hakkında hüküm veriyorlardı. Çünkü halkın koyunları o ekine girmişti. Biz de hükümlerine şahit olmuştuk."},{"n":79,"t":"Biz hüküm vermeyi Süleyman’a kavratmıştık. Zaten her birine hükümranlık ve ilim vermiştik. Dâvûd ile birlikte, Allah’ı tespih etmeleri için dağları ve kuşları onun emrine verdik. Bunları yapan biz idik."},{"n":80,"t":"Bir de Davud’a, sizin için, zırh yapma sanatını öğrettik ki, savaşlarınızda sizi korusun. Şimdi siz şükrediyor musunuz?"},{"n":81,"t":"Süleyman’ın hizmetine de güçlü esen rüzgârı verdik. Rüzgâr, onun emriyle içinde bereketler yarattığımız yere eser giderdi. Biz, her şeyi hakkıyla bileniz."},{"n":82,"t":"Bir de şeytanlardan, Süleyman için dalgıçlık eden ve daha bundan başka işler yapanları da onun emrine verdik. Hep onları zapteden bizdik."},{"n":83,"t":"Eyyûb’u da hatırla. Hani o Rabbine, \"Şüphesiz ki ben derde uğradım, sen ise merhametlilerin en merhametlisisin\" diye niyaz etmişti."},{"n":84,"t":"Biz de onun duasını kabul edip kendisinde dert namına ne varsa gidermiştik. Tarafımızdan bir rahmet ve kullukta bulunanlar için de bir ibret olmak üzere ona ailesini ve onlarla beraber bir mislini daha vermiştik."},{"n":85,"t":"İsmail’i, İdris’i ve Zülkifl’i de hatırla. Bunların hepsi sabredenlerdendi."},{"n":86,"t":"Onları da rahmetimizin içine soktuk. Şüphesiz onlar salih kimselerdendi."},{"n":87,"t":"Zünnûn’u da hatırla. Hani öfkelenerek (halkından ayrılıp) gitmişti de kendisini asla sıkıştırmayacağımızı sanmıştı. Derken karanlıklar içinde, \"Senden başka hiçbir ilâh yoktur. Seni eksikliklerden uzak tutarım. Ben gerçekten (nefsine) zulmedenlerden oldum\" diye dua etti."},{"n":88,"t":"Biz de duasını kabul ettik ve kendisini kederden kurtardık. İşte biz mü’minleri böyle kurtarırız."},{"n":89,"t":"Zekeriya’yı da hatırla. Hani o, Rabbine, \"Rabbim! Beni tek başıma bırakma. Sen varislerin en hayırlısısın\" diye dua etmişti."},{"n":90,"t":"Biz de onun duasını kabul ettik ve kendisine Yahya’yı bağışladık. Eşini de kendisi için, (doğurmaya) elverişli kıldık. Onlar gerçekten hayır işlerinde yarışırlar, (rahmetimizi) umarak ve (azabımızdan) korkarak bize dua ederlerdi. Onlar bize derin saygı duyan kimselerdi."},{"n":91,"t":"Irzını korumuş olan kadını da (Meryem’i de) hatırla. Ona ruhumuzdan üflemiştik. Kendisini de, oğlunu da âlemlere (kudretimizi gösteren) birer delil yapmıştık."},{"n":92,"t":"Şüphesiz bu (İslâm), tek ümmet (din) olarak sizin ümmetiniz (dininiz)dir. Ben de Rabbinizim. Onun için sadece bana kulluk edin."},{"n":93,"t":"(İnsanlar) işlerini kendi aralarında parça parça ettiler. Hepsi de ancak bize dönecekler."},{"n":94,"t":"Şu hâlde, kim mü’min olarak bir salih amel işlerse, çalışması asla inkâr edilmez. Şüphesiz biz onu yazmaktayız."},{"n":95,"t":"Helâk ettiğimiz bir memleket halkının bize dönmemeleri imkânsızdır."},{"n":96,"t":"Nihayet Ye’cüc ve Me’cüc’ün önü açıldığı zaman her tepeden akın ederler."},{"n":97,"t":"Gerçek vaad (kıyametin kopması) yaklaşır, bir de bakarsın inkâr edenlerin gözleri açılıp donakalmıştır. \"Eyvah bizlere! Doğrusu biz bundan gafildik. Hatta biz zalim kimselermişiz\" derler."},{"n":98,"t":"Hiç şüphesiz siz ve Allah’tan başka kulluk ettikleriniz cehennem odunusunuz. Siz oraya varacaksınız."},{"n":99,"t":"Eğer onlar ilâh olsalardı oraya varmazlardı. Hâlbuki hepsi orada ebedî kalacaklardır."},{"n":100,"t":"Onların orada derin bir iç çekişleri vardır! Onlar orada hiçbir şey işitmezler."},{"n":101,"t":"Şüphesiz kendileri için tarafımızdan en güzel mükâfat hazırlanmış olanlar var ya; işte bunlar cehennemden uzaklaştırılmışlardır."},{"n":102,"t":"Onlar cehennemin hışıltısını bile duymazlar. Canlarının istediği nimetler içinde ebedî olarak kalırlar."},{"n":103,"t":"En büyük korku bile onları tasalandırmaz ve melekler onları, \"İşte bu, size vaad edilen (mutlu) gününüzdür\" diyerek karşılarlar."},{"n":104,"t":"Yazılı kâğıt tomarlarının dürülmesi gibi göğü düreceğimiz günü düşün. Başlangıçta ilk yaratmayı nasıl yaptıysak, -üzerimize aldığımız bir vaad olarak- onu yine yapacağız. Biz bunu muhakkak yapacağız."},{"n":105,"t":"Andolsun, Zikir’den (Tevrat’tan) sonra Zebûr’da da, \"Yere muhakkak benim iyi kullarım varis olacaktır\" diye yazmıştık."},{"n":106,"t":"Şüphesiz bunda Allah’a kulluk eden bir toplum için yeterli bir mesaj vardır."},{"n":107,"t":"(Ey Muhammed!) Seni ancak âlemlere rahmet olarak gönderdik."},{"n":108,"t":"De ki: \"Bana ancak, ilâhınızın yalnızca bir tek ilâh olduğu vahyolunuyor. Artık müslüman oluyor musunuz?\""},{"n":109,"t":"Eğer yüz çevirirlerse, de ki: \"(Bana emrolunanı, ayırım yapmadan) size eşit olarak bildirdim. Tehdit edildiğiniz şey yakın mı yoksa uzak mı, bilmiyorum.\""},{"n":110,"t":"\"Şüphesiz, Allah sözün açığa vurulanını da bilir, gizlediğinizi de bilir.\""},{"n":111,"t":"\"Bilmem! Belki bu (mühlet) sizin için bir imtihan ve bir vakte kadar yararlanmadır.\""},{"n":112,"t":"(Peygamber), \"Ey Rabbim! Hak ile hüküm ver. Bizim Rabbimiz, sizin nitelemelerinize karşı yardımı istenecek olan Rahmân’dır\" dedi."}],[{"n":1,"t":"Ey insanlar! Rabbinize karşı gelmekten sakının. Çünkü kıyamet sarsıntısı çok büyük bir şeydir."},{"n":2,"t":"Onu göreceğiniz gün, her emzikli kadın emzirmekte olduğu çocuğundan geçer ve her hamile kadın da karnındaki çocuğunu düşürür. İnsanları sarhoş görürsün; hâlbuki onlar sarhoş değillerdir. Ne var ki Allah’ın azabı çok şiddetlidir."},{"n":3,"t":"İnsanlardan kimi vardır ki, hiçbir bilgisi olmadığı hâlde, Allah hakkında tartışmaya girer ve her azgın şeytanın ardına düşer."},{"n":4,"t":"Şeytan hakkında, \"Her kim onu dost edinirse, mutlaka o kimseyi saptırır ve onu cehennem azabına sürükler\" diye yazılmıştır."},{"n":5,"t":"Ey insanlar! Ölümden sonra diriliş konusunda herhangi bir şüphe içindeyseniz (düşünün ki) hiç şüphesiz biz sizi topraktan, sonra az bir sudan (meniden), sonra bir \"alaka\"dan, sonra da yaratılışı belli belirsiz bir \"mudga\"dan yarattık ki size (kudretimizi) apaçık anlatalım. Dilediğimizi belli bir süreye kadar rahimlerde durduruyoruz. Sonra sizi bir çocuk olarak çıkarıyor, sonra da (akıl, temyiz ve kuvvette) tam gücünüze ulaşmanız için (sizi kemale erdiriyoruz.) İçinizden ölenler olur. Yine içinizden bir kısmı da ömrün en düşkün çağına ulaştırılır ki, bilirken hiçbir şey bilmez hâle gelsin. Yeryüzünü de ölü, kupkuru görürsün. Biz, onun üzerine yağmur indirdiğimiz zaman kıpırdar, kabarır ve her türden iç açıcı çift çift bitkiler bitirir."},{"n":6,"t":"Bu böyle. Çünkü Allah, hakkın ta kendisidir. Şüphesiz O, ölüleri diriltir ve O, her şeye hakkıyla kadirdir."},{"n":7,"t":"Çünkü kıyamet muhakkak gelecektir. Onda hiçbir şüphe yoktur ve şüphesiz Allah, kabirlerdeki kimseleri diriltecektir."},{"n":"8-9","t":"İnsanlardan öylesi de vardır ki, bir ilmi, bir yol göstericisi, aydınlatıcı bir kitabı olmadığı hâlde kibirlenerek insanları Allah’ın yolundan saptırmak için, Allah hakkında tartışmaya kalkar. Ona dünyada bir rezillik vardır. Ona kıyamet gününde de yangın azabını tattıracağız."},{"n":10,"t":"(Ona), \"İşte bu kendi ellerinin önceden işledikleri yüzündendir. Allah, kesinlikle kullara zulmedici değildir\" (denir.)"},{"n":11,"t":"İnsanlardan öylesi de vardır ki, Allah’a kıyıdan kenardan kulluk eder. Eğer kendisine bir hayır dokunursa, gönlü onunla hoş olur. Şâyet başına bir kötülük gelirse, gerisingeri (küfre) dönüverir. O dünyayı da kaybetmiştir, ahireti de. İşte bu apaçık ziyanın ta kendisidir."},{"n":12,"t":"O, Allah’ı bırakır da kendine ne zarar, ne de fayda veren şeylere tapar. Bu da derin sapıklığın ta kendisidir."},{"n":13,"t":"Zararı faydasından daha yakın olana tapar. O (taptığı) ne kötü yardımcı, ne fena yoldaştır!"},{"n":14,"t":"Muhakkak ki Allah, iman edip salih ameller işleyenleri içinden ırmaklar akan cennetlere koyacaktır. Şüphesiz Allah, dilediğini yapar."},{"n":15,"t":"Her kim ona (Muhammed’e) Allah’ın dünyada ve ahirette asla yardım etmeyeceğini zannediyorsa hemen tavana bir ip çeksin, sonra kendini assın da bir baksın; başvurduğu (bu yöntem), öfkelendiği şeyi giderecek mi?"},{"n":16,"t":"Böylece biz Kur’an’ı apaçık âyetler hâlinde indirdik. Şüphesiz Allah, dilediğini doğru yola iletir."},{"n":17,"t":"Şüphesiz, iman edenler, Yahudiler, Sâbiîler, Hıristiyanlar, Mecûsiler ve Allah’a ortak koşanlar var ya; Allah, kıyamet günü onların aralarında mutlaka hüküm verecektir. Çünkü Allah, her şeye şahittir."},{"n":18,"t":"Görmedin mi ki şüphesiz, göklerde ve yerde olanlar, güneş, ay, yıldızlar, ağaçlar, hayvanlar ve insanların birçoğu Allah’a secde etmektedir. Birçoğunun üzerine de azap hak olmuştur. Allah, kimi alçaltırsa ona saygınlık kazandıracak hiçbir kimse yoktur. Şüphesiz Allah, dilediğini yapar."},{"n":19,"t":"İşte iki hasım taraf ki, Rableri hakkında tartışmaya girmişlerdir. Bunlardan inkâr edenler için ateşten giysiler biçilmiştir. Başlarının üstünden de kaynar su dökülür."},{"n":20,"t":"Onunla, karınlarının içindekiler ve derileri eritilir."},{"n":21,"t":"Onlar için bir de demirden topuzlar vardır."},{"n":22,"t":"Her ne zaman cehennemden, o ızdıraptan çıkmak isteseler, oraya geri döndürülürler ve onlara, \"Tadın yangın azabını\" denilir."},{"n":23,"t":"Şüphesiz Allah, iman edip salih ameller işleyenleri içlerinden ırmaklar akan cennetlere koyacak, orada altından bileziklerle, incilerle süsleneceklerdir. Oradaki giysileri ise ipektir."},{"n":24,"t":"Onlar hem sözün hoş olanına ulaştırılmışlar, hem de övgüye lâyık olan Allah’ın yoluna iletilmişlerdir."},{"n":25,"t":"İnkâr edenler ile Allah’ın yolundan ve içinde, yerli, misafir bütün insanları eşit kıldığımız Mescid-i Haram’dan alıkoyanlar (azabı hak etmişlerdir.) Kim de orada zulmederek haktan sapmak isterse, biz ona elem dolu bir azaptan tattıracağız."},{"n":26,"t":"Hani biz İbrahim’e, Kâbe’nin yerini, \"Bana hiçbir şeyi ortak koşma; evimi, tavaf edenler, namaz kılanlar, rükû ve secde edenler için temizle\" diye belirlemiştik."},{"n":27,"t":"İnsanlar arasında haccı ilan et ki, gerek yaya olarak, gerek uzak yollardan gelen yorgun develer üzerinde sana gelsinler."},{"n":28,"t":"Gelsinler ki, kendilerine ait birtakım menfaatlere şahit olsunlar ve Allah’ın kendilerine rızık olarak verdiği (kurbanlık) hayvanlar üzerine belli günlerde (onları kurban ederken) Allah’ın adını ansınlar. Artık onlardan siz de yiyin, yoksula fakire de yedirin."},{"n":29,"t":"Sonra kirlerini gidersinler, adaklarını yerine getirsinler ve Beyt-i Atik’i (Kâbe’yi) tavaf etsinler."},{"n":30,"t":"Bu böyle. Kim Allah’ın hükümlerine saygı gösterirse, bu, Rabbi katında kendisi için bir hayırdır. Haramlığı size okunanların (bildirilenlerin) dışında bütün hayvanlar size helâl kılındı. Artık putlara tapma pisliğinden kaçının, yalan sözden kaçının."},{"n":31,"t":"Allah’a yönelen, O’na ortak koşmayan kimseler (olun). Kim Allah’a ortak koşarsa, sanki gökten düşmüş de kendisini kuşlar kapışıyor veya rüzgâr onu uzak bir yere sürüklüyor gibidir."},{"n":32,"t":"Bu böyle. Her kim de Allah’ın nişanelerini (kurbanlıklarını) yüceltirse, şüphesiz ki bu kalplerin takvasından (Allah’a karşı gelmekten sakınmasından)dır."},{"n":33,"t":"Sizin için onlarda belli bir zamana kadar birtakım yararlar vardır. Sonra da kurbanlık olarak varacakları yer Beyt-i Atik (Kâbe)’dir."},{"n":34,"t":"Her ümmet için, Allah’ın kendilerine rızık olarak verdiği hayvanlar üzerine ismini ansınlar diye kurban kesmeyi meşru kıldık. İşte sizin ilâhınız bir tek ilâhtır. Şu hâlde yalnız O’na teslim olun. Alçak gönüllüleri müjdele!"},{"n":35,"t":"Onlar, Allah anıldığı zaman kalpleri ürperen, başlarına gelen musibetlere sabreden, namazı dosdoğru kılan ve kendilerine rızık olarak verdiklerimizden Allah yolunda harcayan kimselerdir."},{"n":36,"t":"Kurbanlık büyük baş hayvanları da sizin için Allah’ın dininin nişanelerinden kıldık. Sizin için onlarda hayır vardır. Onlar saf saf sıralanmış dururken (kurban edeceğinizde) üzerlerine Allah’ın adını anın. Yanları üzerlerine düşüp canları çıkınca onlardan siz de yiyin, istemeyen fakire de istemek zorunda kalan fakire de yedirin. Şükredesiniz diye onları böylece sizin hizmetinize verdik."},{"n":37,"t":"Onların etleri ve kanları asla Allah’a ulaşmaz. Fakat O’na sizin takvanız (Allah’a karşı gelmekten sakınmanız) ulaşır. Böylece onları sizin hizmetinize verdi ki, size doğru yolu gösterdiğinden dolayı Allah’ı büyük tanıyasınız. İyilik edenleri müjdele."},{"n":38,"t":"Şüphesiz, Allah inananları savunur. Doğrusu Allah hiçbir haini, nankörü sevmez."},{"n":39,"t":"Kendilerine savaş açılan müslümanlara, zulme uğramaları sebebiyle cihad için izin verildi. Şüphe yok ki Allah’ın onlara yardım etmeğe gücü yeter."},{"n":40,"t":"Onlar, haksız yere, sırf, \"Rabbimiz Allah’tır\" demelerinden dolayı yurtlarından çıkarılmış kimselerdir. Eğer Allah’ın, insanların bir kısmını bir kısmıyla defetmesi olmasaydı, içlerinde Allah’ın adı çok anılan manastırlar, kiliseler, havralar ve mescitler muhakkak yerle bir edilirdi. Şüphesiz ki Allah, kendi dinine yardım edene mutlaka yardım eder. Şüphesiz ki Allah, çok kuvvetlidir, mutlak güç sahibidir."},{"n":41,"t":"Onlar öyle kimselerdir ki, şâyet kendilerine yeryüzünde imkân ve iktidar versek, namazı dosdoğru kılar, zekâtı verir, iyiliği emreder ve kötülüğü yasaklarlar. Bütün işlerin âkıbeti Allah’a aittir."},{"n":42,"t":"Ey Muhammed! Eğer seni yalanlarlarsa bil ki, onlardan önce Nûh, Âd ve Semûd kavimleri de (peygamberlerini) yalanlamışlardı."},{"n":"43-44","t":"İbrahim’in kavmi ile Lût’un kavmi ve Medyen halkı da (yalanlamışlardı). Mûsâ da yalanlandı ve nihayet o inkârcılara mühlet verdim, sonra da onları yakalayıverdim. Beni inkâr etmek nasılmış, (gördüler)."},{"n":45,"t":"Halkı zulmetmekteyken helâk ettiğimiz, böylece duvarları, çökmüş çatılarının üzerine yıkılmış nice memleketler, nice kullanılmaz kuyular, nice muhteşem saraylar vardır!"},{"n":46,"t":"Yeryüzünde gezip dolaşmadılar mı ki, düşünecek kalpleri, işitecek kulakları olsun? (Dolaştılar, ama ibret almadılar). Çünkü gerçekte gözler değil, göğüslerdeki kalpler (kalp gözleri) kör olur."},{"n":47,"t":"Bir de senden acele azap istiyorlar. Hâlbuki Allah asla va’dinden caymaz. Şüphesiz Rabbinin nezdinde bir gün, sizin saydığınız bin yıl gibidir."},{"n":48,"t":"Zalim oldukları hâlde, mühlet verdiğim, sonra da kendilerini azabımla yakaladığım nice memleket halkları vardır. Dönüş yalnız banadır."},{"n":49,"t":"De ki: \"Ey insanlar! Ben sizin için ancak apaçık bir uyarıcıyım.\""},{"n":50,"t":"Artık iman edip salih ameller işleyenler var ya, işte onlar için bir bağışlama güzel bir nimet (cennet) vardır."},{"n":51,"t":"Âyetlerimizi geçersiz kılmak için çaba gösterenler var ya, işte onlar cehennemliklerdir."},{"n":52,"t":"Senden önce hiçbir resûl ve nebî göndermedik ki, bir şey temenni ettiği zaman, şeytan onun bu temennisine dair vesvese vermiş olmasın. Ama Allah, şeytanın vesvesesini giderir. Sonra Allah, âyetlerini sağlamlaştırır. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":53,"t":"Allah, şeytanın verdiği bu vesveseyi, kalplerinde hastalık bulunanlar ile kalpleri katı olanlara bir imtihan vesilesi kılmak için böyle yapar. Hiç şüphesiz ki o zalimler, derin bir ayrılık içindedirler."},{"n":54,"t":"Bir de kendilerine ilim verilmiş olanlar onun, Rabbinden gelen hak olduğunu bilsinler, böylece ona iman etsinler ve sonuçta da kalpleri ona saygı duysun diye Allah böyle yapar. Hiç şüphe yok ki Allah, iman edenleri doğru yola iletir."},{"n":55,"t":"İnkâr edenler, kendilerine kıyamet ansızın gelinceye, yahut da onlara kısır bir günün azabı gelip çatıncaya dek o Kur’an’dan bir şüphe içinde kalırlar."},{"n":56,"t":"İşte o gün mülk (hükümranlık) Allah’ındır. O, insanların arasında hükmünü verir. Artık iman edip salih ameller işlemiş olanlar Naîm Cennetleri’ndedirler."},{"n":57,"t":"İnkâr edip âyetlerimizi yalanlamış olanlara gelince, onlar için de alçaltıcı bir azap vardır."},{"n":58,"t":"Allah yolunda hicret edip de sonra öldürülmüş veya ölmüş olanlara gelince, Allah onlara muhakkak güzel bir rızık verecektir. Şüphe yok ki Allah, rızık verenlerin en hayırlısıdır."},{"n":59,"t":"Elbette onları hoşnut olacakları bir yere sokacaktır. Şüphesiz Allah hakkıyla bilendir, halîmdir (hemen cezalandırmaz, mühlet verir)."},{"n":60,"t":"Bu böyle. Bir de kim kendisine verilen eziyetin dengiyle karşılık verir de sonra yine kendisine zulmedilirse, elbette Allah ona yardım eder. Hiç şüphesiz ki Allah çok affedendir, çok bağışlayandır."},{"n":61,"t":"Bu böyle. Çünkü Allah, geceyi gündüzün içine sokar, gündüzü de gecenin içine sokar. Şüphesiz ki Allah hakkıyla işiten, hakkıyla görendir."},{"n":62,"t":"Bu böyle. Çünkü Allah, hakkın ta kendisidir. O’nu bırakıp da taptıkları ise batılın ta kendisidir. Şüphesiz ki Allah yücedir, büyüktür."},{"n":63,"t":"Allah’ın gökten yağmur indirdiği, böylece yeryüzünün yemyeşil olduğunu görmedin mi? Şüphesiz Allah, çok lütufkârdır, hakkıyla haberdardır."},{"n":64,"t":"Göklerdeki her şey, yerdeki her şey O’nundur. Şüphesiz ki Allah elbette zengindir, elbette övgüye lâyıktır."},{"n":65,"t":"Görmüyor musun ki, Allah bütün yerdekileri ve emri uyarınca denizde akıp gitmekte olan gemileri sizin hizmetinize vermiştir. İzni olmaksızın yerin üzerine düşmesin diye göğü O tutuyor. Şüphesiz ki Allah, insanlara karşı çok esirgeyici, çok merhametlidir."},{"n":66,"t":"O, size hayat veren, sonra sizi öldürecek, daha sonra da diriltecek olandır. Şüphesiz, insan çok nankördür."},{"n":67,"t":"Biz her ümmet için uygulayacağı bir ibadet yolu verdik. O hâlde, din işinde seninle asla çekişmesinler. Sen Rabbine davet et. Çünkü sen hiç şüphesiz hakka götüren dosdoğru bir yol üzerindesin."},{"n":68,"t":"Eğer seninle mücadele ederlerse, de ki: \"Allah, yapmakta olduğunuzu daha iyi bilmektedir.\""},{"n":69,"t":"Hakkında ayrılığa düşüp durduğunuz şeyler konusunda, kıyamet günü Allah aranızda hüküm verecektir."},{"n":70,"t":"Bilmez misin ki, kuşkusuz Allah gökte ve yerde ne varsa hepsini bilir. Kuşkusuz bunların hepsi bir kitapta (Levh-i Mahfuz’da)dır. Şüphesiz bu, Allah’a göre çok kolaydır."},{"n":71,"t":"Onlar, Allah’ı bırakıp, hakkında Allah’ın hiçbir delil indirmediği, kendilerinin de hakkında hiçbir bilgilerinin bulunmadığı şeylere kulluk ederler. Zalimlerin hiçbir yardımcısı yoktur."},{"n":72,"t":"Kendilerine âyetlerimiz açık açık okunduğu zaman, o kâfirlerin yüz ifadelerinden inkârlarını anlarsın. Neredeyse, kendilerine âyetlerimizi okuyanlara hışımla saldıracaklar. De ki: \"Şimdi size bu durumdan daha beterini haber vereyim mi: Ateş.. Allah, onu kâfirlere vaad etti. Ne kötü varış yeridir orası!\""},{"n":73,"t":"Ey insanlar! Size bir örnek verildi. Şimdi ona iyi kulak verin. Sizin Allah’tan başka taptıklarınız bir sinek dahi yaratamazlar, hepsi bunun için toplansalar bile. Eğer sinek onlardan bir şey kapsa, bunu ondan kurtaramazlar. İsteyen de âciz, istenen de."},{"n":74,"t":"Allah’ın kadrini gereği gibi bilemediler. Şüphesiz Allah kuvvetlidir, mutlak güç sahibidir."},{"n":75,"t":"Allah, meleklerden de resûller seçer, insanlardan da. Şüphesiz Allah, hakkıyla işitendir, hakkıyla görendir."},{"n":76,"t":"Onların önlerindekini de (yaptıklarını da), arkalarındakini de (yapacaklarını da) bilir. Bütün işler hep Allah’a döndürülür."},{"n":77,"t":"Ey iman edenler, rükû edin, secde edin, Rabbinize kulluk edin ve hayır işleyin ki kurtuluşa eresiniz."},{"n":78,"t":"Allah uğrunda hakkıyla cihad edin. O, sizi seçti ve dinde üzerinize hiçbir güçlük yüklemedi. Babanız İbrahim’in dinine uyun. Allah, sizi hem daha önce, hem de bu Kur’an’da müslüman diye isimlendirdi ki, Peygamber size şahit (ve örnek) olsun, siz de insanlara şahit (ve örnek) olasınız. Artık namazı dosdoğru kılın, zekâtı verin ve Allah’a sarılın. O, sizin sahibinizdir. O, ne güzel sahip, ne güzel yardımcıdır!"}],[{"n":1,"t":"Mü’minler, gerçekten kurtuluşa ermişlerdir."},{"n":2,"t":"Onlar ki, namazlarında derin saygı içindedirler."},{"n":3,"t":"Onlar ki, faydasız işlerden ve boş sözlerden yüz çevirirler."},{"n":4,"t":"Onlar ki, zekâtı öderler."},{"n":5,"t":"Onlar ki, ırzlarını korurlar."},{"n":6,"t":"Ancak eşleri ve ellerinin altında bulunan cariyeleri bunun dışındadır. Onlarla ilişkilerinden dolayı kınanmazlar."},{"n":7,"t":"Kim bunun ötesine geçmek isterse, işte onlar haddi aşanlardır."},{"n":8,"t":"Yine onlar ki, emanetlerine ve verdikleri sözlere riâyet ederler."},{"n":9,"t":"Onlar ki, namazlarını kılmağa devam ederler."},{"n":10,"t":"İşte bunlar varis olanların ta kendileridir."},{"n":11,"t":"Onlar Firdevs cennetlerine varis olurlar. Onlar orada ebedî kalacaklardır."},{"n":12,"t":"Andolsun, biz insanı, çamurdan (süzülmüş) bir özden yarattık."},{"n":13,"t":"Sonra onu az bir su (meni) hâlinde sağlam bir karargâha (ana rahmine) yerleştirdik."},{"n":14,"t":"Sonra bu az suyu \"alaka\" hâline getirdik. Alakayı da \"mudga\" yaptık. Bu \"mudga\"yı da kemiklere dönüştürdük ve bu kemiklere de et giydirdik. Nihayet onu bambaşka bir yaratık olarak ortaya çıkardık. Yaratanların en güzeli olan Allah’ın şânı ne yücedir!"},{"n":15,"t":"Sonra (ey insanlar) siz bunun ardından muhakkak öleceksiniz."},{"n":16,"t":"Sonra yine muhakkak siz, kıyamet gününde (tekrar) diriltileceksiniz."},{"n":17,"t":"Andolsun, biz sizin üzerinizde yedi yol yarattık. Biz yarattıklarımızdan habersiz değiliz."},{"n":18,"t":"Biz, gökten belli bir ölçüde su indirdik de (faydalanmanız için) onu yeryüzünde tuttuk. Bizim onu tamamen gidermeye de muhakkak gücümüz yeter."},{"n":19,"t":"Onunla sizin için hurma bahçeleri ve üzüm bağları meydana getirdik. Bu bağ ve bahçelerde sizin için pek çok meyveler vardır ve siz onlardan yiyorsunuz."},{"n":20,"t":"Yine o su ile Sîna dağında biten bir ağaç (zeytin ağacı) yarattık ki hem yağ, hem de yiyenlere katık verir."},{"n":21,"t":"Hayvanlarda sizin için elbette bir ibret vardır. Onların içlerindeki sütten size içiririz. Onlarda sizin için daha birçok faydalar da vardır ve onlardan yersiniz de."},{"n":22,"t":"Onların üzerinde ve gemilerde taşınırsınız."},{"n":23,"t":"Andolsun biz, Nûh’u kendi kavmine peygamber olarak gönderdik de, \"Ey kavmim! Allah’a kulluk edin. Sizin O’ndan başka hiçbir ilâhınız yoktur. Allah’a karşı gelmekten hâlâ sakınmaz mısınız?\" dedi."},{"n":24,"t":"Bunun üzerine kendi kavminden inkâr eden ileri gelenler şöyle dediler: \"Bu ancak sizin gibi bir beşerdir, size üstünlük taslamak istiyor. Eğer Allah dileseydi, bir melek gönderirdi. Biz önceki atalarımızdan böyle bir şey duymadık.\""},{"n":25,"t":"\"Bu, ancak cinnet getirmiş bir adamdır. Öyle ise bir müddet onu gözetleyiniz.\""},{"n":26,"t":"(Nûh), \"Rabbim! Beni yalanlamalarına karşı bana yardım et!\" dedi."},{"n":27,"t":"Bunun üzerine Nûh’a, \"Bizim gözetimimiz altında ve vahyimize göre o gemiyi yap\" diye vahyettik. \"Bizim emrimiz gelip de tandır kaynamaya başlayınca, (sular coşup taştığında Nûh’a) dedik ki: \"Her cins canlıdan (erkekli dişili) birer çift, bir de kendileri aleyhinde daha önce hüküm verilmiş olanlardan başka aileni gemiye al ve zulmeden kimseler hakkında bana hiç yalvarma! Şüphesiz onlar suda boğulacaklardır.\""},{"n":28,"t":"Sen ve beraberindeki kimseler, gemiye bindiğiniz zaman: \"Bizi zalim kavmin elinden kurtaran Allah’a hamd olsun\" de."},{"n":29,"t":"Yine de ki: \"Ey Rabbim! Beni bereketli bir yere kondur. Sen, konuk edenlerin en hayırlısısın.\""},{"n":30,"t":"Şüphesiz bu olayda ibretler vardır. Biz gerçekten (kullarımızı) imtihan ederiz."},{"n":31,"t":"Sonra onların (Nûh kavminin) ardından başka bir nesil yarattık."},{"n":32,"t":"Onlara, kendilerinden, \"Allah’a kulluk edin, sizin O’ndan başka hiçbir ilâhınız yoktur, hâlâ O’na karşı gelmekten sakınmaz mısınız?\" diye öğüt veren bir peygamber gönderdik."},{"n":33,"t":"O peygamberin kavminden, Allah’ı inkâr eden, ahireti yalanlayan ve bizim dünya hayatında kendilerine bol bol nimet verdiğimiz ileri gelenler şöyle dediler: \"O da ancak sizin gibi bir insandır. Sizin yediğiniz şeylerden yiyor, içtiğiniz şeylerden içiyor.\""},{"n":34,"t":"\"Andolsun, kendiniz gibi bir beşere itaat ederseniz mutlaka ziyana uğrarsınız.\""},{"n":35,"t":"\"O, öldüğünüz, toprak ve kemik hâline geldiğiniz zaman sizin tekrar mutlaka (diriltilip) çıkarılacağınızı mı vaad ediyor?\""},{"n":36,"t":"\"Hâlbuki bu size vaad olunan şey, ne kadar da uzak!\""},{"n":37,"t":"\"Hayat, bu dünya hayatından ibarettir. Ölürüz ve yaşarız. Biz tekrar diriltilecek değiliz.\""},{"n":38,"t":"\"Bu, Allah’a karşı yalan uyduran bir kimseden başkası değildir. Biz ona inanmayız.\""},{"n":39,"t":"O peygamber, \"Ey Rabbim! Yalanlamalarına karşı bana yardım et!\" dedi."},{"n":40,"t":"Allah, \"Yakın zamanda mutlaka pişman olacaklardır!\" dedi."},{"n":41,"t":"Derken onları o korkunç ses, kaçınılmaz olarak kıskıvrak yakalayıverdi de kendilerini çör çöp yığını hâline getirdik. Zalimler topluluğu, Allah’ın rahmetinden uzak olsun!"},{"n":42,"t":"Sonra bunların arkalarından başka nesiller yarattık."},{"n":43,"t":"Hiçbir ümmet, kendi ecelinin önüne geçemez, onu geciktiremez de."},{"n":44,"t":"Sonra arka arkaya peygamberlerimizi gönderdik. Her ümmete kendi peygamberi geldikçe, onu yalanladılar. Biz de onları birbiri ardından helâk ettik ve onları birer ibretli hikâye yaptık. Artık inanmayan bir kavim, Allah’ın rahmetinden uzak olsun!"},{"n":"45-46","t":"Sonra Mûsâ ve kardeşi Hârûn’u mucizelerimizle ve apaçık bir delille Firavun ve ileri gelenlerine peygamber olarak gönderdik de (onlar) büyüklük tasladılar ve kendilerini büyük görüp böbürlenen bir topluluk oldular."},{"n":47,"t":"Bu yüzden, \"Kavimleri bize kul köle iken, bizim gibi iki insana mı inanacağız\" dediler."},{"n":48,"t":"Böylece ikisini de yalanladılar, bu yüzden de helâk edilenlerden oldular."},{"n":49,"t":"Andolsun, hidayete ersinler diye Mûsâ’ya Kitab’ı (Tevrat’ı) verdik."},{"n":50,"t":"Meryem oğlu İsa’yı ve annesini büyük bir mucize kıldık ve her ikisini de oturmaya elverişli, akarsulu yüksek bir yere yerleştirdik."},{"n":51,"t":"Ey peygamberler! Temiz şeylerden yiyiniz ve iyi ameller işleyiniz. Doğrusu ben, sizin yaptığınız şeyleri tamamen bilirim."},{"n":52,"t":"Şüphesiz bu (İslâm), tek bir din olarak sizin dininizdir. Ben de Rabbinizim. Öyle ise bana karşı gelmekten sakının."},{"n":53,"t":"(İnsanlar ise, din) işlerini kendi aralarında parça parça ettiler. Her grup kendinde bulunan ile sevinmektedir."},{"n":54,"t":"Ey Muhammed! Sen onları bir zamana kadar, gaflet ve şaşkınlıklarıyla baş başa bırak!"},{"n":"55-56","t":"Kendilerine bol bol verdiğimiz mal ve evlatla onların iyiliğine koştuğumuzu mu sanıyorlar? Hayır, onlar farkına varmıyorlar!"},{"n":57,"t":"Rablerinin azametinden korkup titreyenler,"},{"n":58,"t":"Rablerinin âyetlerine inananlar,"},{"n":59,"t":"Rablerine ortak koşmayanlar,"},{"n":60,"t":"Rabblerine dönecekleri için verdiklerini kalpleri ürpererek verenler,"},{"n":61,"t":"İşte bunlar hayır işlerine koşuşurlar ve o uğurda öne geçerler."},{"n":62,"t":"Biz hiçbir kimseye gücünün yettiğinden fazla yük yüklemeyiz. Katımızda hakkı söyleyen bir kitab vardır. Onlar zulme, haksızlığa uğratılmazlar."},{"n":63,"t":"Ancak kâfirlerin kalbleri bu Kur’an’a karşı bir gaflet içindedir. Onların bundan başka yapageldikleri birtakım (kötü) işleri de vardır."},{"n":64,"t":"Nihayet refah ve bolluk içinde olanlarını azapla kıskıvrak yakaladığımız zaman, bakmışsın ki feryat edip duruyorlar."},{"n":65,"t":"Boşuna feryat edip durmayın bugün. Zira bizden yardım görmeyeceksiniz."},{"n":"66-67","t":"Çünkü âyetlerim size okunurdu da siz buna karşı büyüklük taslayarak arkanızı döner, geceleyin toplanıp hezeyanlar savururdunuz."},{"n":68,"t":"Onlar bu sözü (Kur’an’ı) hiç düşünmediler mi? Yoksa kendilerine, önceki atalarına gelmeyen bir şey mi geldi?"},{"n":69,"t":"Ya da onlar henüz kendi peygamberlerini tanımadılar da o yüzden mi onu inkâr ediyorlar?"},{"n":70,"t":"Yoksa \"O cinnet getirmiş\" mi diyorlar? Hayır o, onlara hakkı getirdi. Hâlbuki onların pek çoğu haktan hoşlanmamaktadırlar."},{"n":71,"t":"Eğer hak onların arzularına uysaydı, gökler ile yer ve onlarda bulunanlar elbette bozulur giderdi. Hayır, biz onlara şereflerini (Kur’an’ı) getirdik. Onlar ise bu şereflerinden yüz çeviriyorlar."},{"n":72,"t":"Ey Muhammed! Yoksa sen onlardan bir vergi mi istiyorsun (da inanmıyorlar)? Rabbinin vergisi daha hayırlıdır. O, rızık verenlerin en hayırlısıdır."},{"n":73,"t":"Şüphesiz sen onları doğru bir yola çağırıyorsun."},{"n":74,"t":"Fakat ahirete inanmayanlar, ısrarla bu yoldan çıkmaktadırlar."},{"n":75,"t":"Biz onlara merhamet edip başlarına gelen zararı giderseydik, yine de azgınlıkları içinde bocalayıp kalırlardı."},{"n":76,"t":"Andolsun, biz onları azap ile kıskıvrak yakaladık da yine Rablerine boyun eğmediler ve O’na yalvarıp yakarmadılar."},{"n":77,"t":"Sonunda onlara şiddetli bir azap kapısı açtığımızda bir de bakarsın onun içinde ümitsizliğe düşüvereceklerdir."},{"n":78,"t":"Hâlbuki O, sizin için kulakları, gözleri ve gönülleri yaratandır. Ne kadar az şükrediyorsunuz!"},{"n":79,"t":"O, sizi yeryüzünde yaratıp türetendir. Sadece O’nun huzurunda toplanacaksınız."},{"n":80,"t":"O, diriltendir, öldürendir. Gece ile gündüzün birbirini takib etmesi de O’na aittir. Hâlâ aklınızı kullanmıyor musunuz?"},{"n":81,"t":"Hayır onlar, öncekilerin söyledikleri sözler gibi sözler ettiler."},{"n":82,"t":"Dediler ki: \"Gerçekten biz, ölüp bir toprak ve kemik yığını hâline geldikten sonra mı tekrar diriltileceğiz?\""},{"n":83,"t":"Andolsun, biz de bizden önce atalarımız da bununla tehdit edildik. Bu, öncekilerin uydurduğu masallardan başka bir şey değildir."},{"n":84,"t":"De ki: \"Eğer biliyorsanız söyleyin: Yer ve yerde bulunanlar kime aittir?\""},{"n":85,"t":"\"Allah’ındır\" diyecekler. \"Öyle ise siz hiç düşünüp öğüt almaz mısınız?\" de."},{"n":86,"t":"De ki: \"Yedi kat göklerin Rabbi, büyük Arş’ın Rabbi kimdir?\""},{"n":87,"t":"\"Allah’ındır\" diyecekler. \"Öyle ise O’na karşı gelmekten sakınmaz mısınız?\" de."},{"n":88,"t":"De ki: \"Eğer biliyorsanız söyleyin: Her şeyin hükümranlığı elinde olan, kendisi koruyan, kendisine karşı korunulamaz olan kimdir?\""},{"n":89,"t":"\"Allah’ındır\" diyecekler. \"Öyle ise nasıl aldanıyorsunuz?\" de."},{"n":90,"t":"Hayır, biz onlara gerçeği getirdik, fakat onlar kesinlikle yalancıdırlar."},{"n":"91-92","t":"Allah, hiçbir çocuk edinmemiştir. O’nunla birlikte başka hiçbir ilâh yoktur. Öyle olsaydı, her ilâh kendi yarattığını alır götürür ve mutlaka birbirlerine üstün gelmeye çalışırlardı. Gaybı da, görülen âlemi de bilen Allah, onların yakıştırdığı nitelemelerden uzaktır. Onların koştukları ortaklardan çok yücedir."},{"n":"93-94","t":"De ki: \"Ey Rabbim! Onlara yöneltilen tehditleri bana mutlaka göstereceksen, beni o zalim milletin içinde bulundurma.\""},{"n":95,"t":"Bizim onlara yönelttiğimiz tehditleri sana göstermeye elbette gücümüz yeter."},{"n":96,"t":"Kötülüğü, en güzel olan şeyle uzaklaştır. Biz onların yakıştırmakta oldukları şeyleri daha iyi biliriz."},{"n":97,"t":"De ki: \"Ey Rabbim! Şeytanların vesveselerinden sana sığınırım.\""},{"n":98,"t":"\"Ey Rabbim! Onların benim yanımda bulunmalarından da sana sığınırım.\""},{"n":"99-100","t":"Nihayet onlardan birine ölüm gelince, \"Rabbim! Beni dünyaya geri gönderiniz ki, terk ettiğim dünyada salih bir amel yapayım\" der. Hayır! Bu, sadece onun söylediği (boş) bir sözden ibarettir. Onların arkasında, tekrar dirilecekleri güne kadar (devam edecek, dönmelerine engel) bir perde (berzah) vardır."},{"n":101,"t":"Sûr’a üfürüldüğü zaman, (işte) o gün ne aralarında soy sop yakınlığı kalacak, ne de birbirlerini arayıp soracaklardır."},{"n":102,"t":"Artık kimin tartıları ağır gelirse, işte onlar kurtuluşa erenlerin ta kendileridir."},{"n":103,"t":"Kimlerin de tartıları hafif gelirse, işte onlar da kendilerini ziyana uğratanların ta kendileridir. Onlar cehennemde ebedî kalacaklardır."},{"n":104,"t":"Ateş yüzlerini yalar ve onlar orada sırıtır kalırlar."},{"n":105,"t":"Allah, \"Âyetlerim size okunuyordu da siz onları yalanlıyordunuz, değil mi?\" der."},{"n":106,"t":"Onlar da şöyle derler: \"Ey Rabbimiz! Biz azgınlığımıza yenik düştük ve sapık bir toplum olduk.\""},{"n":107,"t":"\"Ey Rabbimiz! Bizi buradan çıkar. Eğer (tekrar günaha) dönersek şüphesiz kendimize zulmetmiş oluruz.\""},{"n":108,"t":"Allah, \"Aşağılık içinde kalın orada, artık benimle konuşmayın!\" der."},{"n":109,"t":"Kullarımdan, \"Ey Rabbimiz! Biz inandık, bizi bağışla, bize merhamet et, sen merhamet edenlerin en hayırlısısın\" diyen bir grup var idi."},{"n":110,"t":"Siz ise onlarla alay ediyordunuz. O kadar ki onlar size beni anmayı unutturdu. Onlara hep gülüyordunuz."},{"n":111,"t":"Sabretmiş olmaları sebebiyle, bugün ben onları mükâfatlandırdım. Şüphesiz onlar başarıya erenlerin ta kendileridir."},{"n":112,"t":"Allah, (inkârcılara) \"Yeryüzünde kaç sene kaldınız?\" diye sorar."},{"n":113,"t":"Onlar, \"Bir gün, ya da bir günden daha az bir süre kaldık. Hesap tutanlara sor\" derler."},{"n":114,"t":"Allah, şöyle der: \"Çok az bir zaman kaldınız. Keşke bunu (daha önce) bilmiş olsaydınız.\""},{"n":115,"t":"\"Sizi boşuna yarattığımızı ve bize tekrar döndürülmeyeceğinizi mi sandınız?\""},{"n":116,"t":"Gerçek hükümdar olan Allah, yücedir. O’ndan başka hiç ilâh yoktur. O, şerefli ve yüce Arş’ın Rabbidir."},{"n":117,"t":"Kim, hakkında hiçbir delili olmadığı hâlde Allah ile birlikte başka bir ilâha taparsa, onun hesabı ancak Rabbi katındadır. Şüphesiz kâfirler asla kurtuluşa eremezler."},{"n":118,"t":"De ki: \"Rabbim! Bağışla, merhamet et. Çünkü sen merhamet edenlerin en hayırlısısın!\""}],[{"n":1,"t":"Bu, bizim indirdiğimiz ve (hükümlerini) farz kıldığımız bir sûredir. Düşünüp öğüt almanız için onda apaçık âyetler indirdik."},{"n":2,"t":"Zina eden kadın ve zina eden erkekten her birine yüzer değnek vurun. Allah’a ve ahiret gününe inanıyorsanız, Allah’ın dini(nin koymuş olduğu hükmü uygulama) konusunda onlara acıyacağınız tutmasın. Mü’minlerden bir topluluk da onların cezalandırılmasına şahit olsun."},{"n":3,"t":"Zina eden erkek ancak, zina eden veya Allah’a ortak koşan bir kadınla evlenir. Zina eden bir kadınla da ancak zina eden veya Allah’a ortak koşan bir erkek evlenir. Bu, mü’minlere haram kılınmıştır."},{"n":4,"t":"Namuslu kadınlara zina isnat edip sonra da dört şahit getiremeyenlere seksen değnek vurun. Artık onların şahitliğini asla kabul etmeyin. İşte bunlar fâsık kimselerdir."},{"n":5,"t":"Ancak tövbe edip bundan sonra ıslah olanlar müstesna. Çünkü Allah, çok bağışlayandır, çok merhamet edendir."},{"n":"6-7","t":"Eşlerine zina isnat edip de kendilerinden başka şahitleri olmayanlara gelince, onların her birinin şahitliği; kendisinin doğru söyleyenlerden olduğuna dair, Allah adına dört defa yemin ederek şahitlik etmesi, beşinci defada da; eğer yalancılardan ise, Allah’ın lânetinin kendi üzerine olmasını ifade etmesiyle yerine gelir."},{"n":"8-9","t":"Kocasının yalancılardan olduğuna dair Allah’ı dört defa şahit getirmesi (Allah adına yemin etmesi), beşinci defada da eğer kocası doğru söyleyenlerden ise Allah’ın gazabının kendi üzerine olmasını dilemesi, kadından cezayı kaldırır."},{"n":10,"t":"Allah’ın size lütfu ve merhameti olmasaydı ve Allah tövbeleri kabul eden, hüküm ve hikmet sahibi olmasaydı, hâliniz nice olurdu?"},{"n":11,"t":"O ağır iftirayı uyduranlar, sizin içinizden bir güruhtur. Bu iftirayı kendiniz için kötü bir şey sanmayın. Aksine o sizin için bir hayırdır. Onlardan her biri için, işledikleri günahın cezası vardır. İçlerinden (elebaşılık ederek) o günahın büyüğünü üstlenen için ise ağır bir azap vardır."},{"n":12,"t":"Bu iftirayı işittiğiniz zaman, iman eden erkek ve kadınlar, kendi (din kardeş)leri hakkında iyi zan besleyip de, \"Bu, apaçık bir iftiradır\" deselerdi ya!"},{"n":13,"t":"Onlar (iftiracılar) bu iddialarına dair dört şahit getirselerdi ya! Mademki şahit getirmediler; işte onlar Allah yanında yalancıların ta kendileridir."},{"n":14,"t":"Eğer size dünya ve ahirette Allah’ın lütfu ve rahmeti olmasaydı, içine daldığınız bu iftiradan dolayı size mutlaka büyük bir azap dokunurdu!"},{"n":15,"t":"Hani o iftirayı dilden dile dolaştırıyor; hakkında hiçbir bilginiz olmayan şeyleri ağzınıza alıp söylüyor ve bunu önemsiz bir iş sanıyordunuz. Hâlbuki bu, Allah katında büyük bir günahtır."},{"n":16,"t":"Bu iftirayı işittiğiniz vakit, \"Böyle sözleri ağzımıza almamız bize yaraşmaz. Seni eksikliklerden uzak tutarız Allah’ım! Bu, çok büyük bir iftiradır\" deseydiniz ya!"},{"n":17,"t":"Eğer inanıyorsanız, bu gibi şeylere bir daha ebediyyen dönmemeniz için Allah size öğüt veriyor."},{"n":18,"t":"Allah, size âyetleri açıklıyor. Allah, her şeyi hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":19,"t":"İnananlar arasında hayâsızlığın yayılmasını arzu eden kimseler var ya; onlar için dünya ve ahirette elem dolu bir azap vardır. Allah bilir, siz bilmezsiniz."},{"n":20,"t":"Allah’ın lütfu ve rahmeti sizin üzerinize olmasaydı ve Allah çok esirgeyici ve çok merhametli olmasaydı, hâliniz nice olurdu?"},{"n":21,"t":"Ey iman edenler! Şeytanın adımlarına uymayın. Kim şeytanın adımlarına uyarsa, bilsin ki o hayâsızlığı ve kötülüğü emreder. Eğer Allah’ın size lütfu ve merhameti olmasaydı, sizden hiçbiriniz asla temize çıkamazdı. Fakat Allah, dilediği kimseyi tertemiz kılar. Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":22,"t":"İçinizden varlık ve servet sahibi kimseler yakınlarına, düşkünlere ve Allah yolunda hicret edenlere (kendi mallarından bir şey) vermeyeceklerine yemin etmesinler. Onlar affetsinler, vazgeçip iyi muamelede bulunsunlar. Allah’ın sizi bağışlamasını arzu etmez misiniz? Allah, çok bağışlayandır, çok merhamet edendir."},{"n":"23-24","t":"İffetli ve (haklarında uydurulan kötülüklerden) habersiz mü’min kadınlara zina isnat edenler, gerçekten dünya ve ahirette lânetlenmişlerdir. İşlemiş oldukları günahtan dolayı dillerinin, ellerinin ve ayaklarının kendi aleyhlerine şahitlik edecekleri günde onlara çok büyük bir azap vardır."},{"n":25,"t":"O gün Allah, onlara kesinleşmiş cezalarını tastamam verecek ve onlar Allah’ın apaçık bir gerçek olduğunu bileceklerdir."},{"n":26,"t":"Kötü kadınlar, kötü erkeklere; kötü erkekler de kötü kadınlara; temiz kadınlar temiz erkeklere, temiz erkekler de temiz kadınlara lâyıktır. O temiz olanlar, iftiracıların söyledikleri şeylerden uzaktırlar. Onlar için bir bağışlanma ve bolca verilmiş iyi bir rızık vardır."},{"n":27,"t":"Ey iman edenler! Kendi evlerinizden başka evlere, geldiğinizi hissettirip (izin alıp) ev sahiplerine selâm vermeden girmeyin. Bu davranış sizin için daha hayırlıdır. Düşünüp anlayasınız diye size böyle öğüt veriliyor."},{"n":28,"t":"Eğer evde kimseyi bulamazsanız, size izin verilinceye kadar oraya girmeyin. Eğer size, \"Geri dönün\" denirse, hemen dönün. Çünkü bu, sizin için daha nezih bir davranıştır. Allah, yaptıklarınızı hakkıyla bilendir."},{"n":29,"t":"İçinde size ait bir eşya olan, oturanı bulunmayan evlere girmenizde herhangi bir günah yoktur. Allah, açığa vurduklarınızı da, gizlediklerinizi de bilir."},{"n":30,"t":"Mü’min erkeklere söyle, gözlerini haramdan sakınsınlar, ırzlarını korusunlar. Bu davranış onlar için daha nezihtir. Şüphe yok ki, Allah onların yaptıklarından hakkıyla haberdardır."},{"n":31,"t":"Mü’min kadınlara da söyle, gözlerini haramdan sakınsınlar, ırzlarını korusunlar. (Yüz ve el gibi) görünen kısımlar müstesna, zînet (yer)lerini göstermesinler. Başörtülerini ta yakalarının üzerine kadar salsınlar. Zinetlerini, kocalarından, yahut babalarından, yahut kocalarının babalarından, yahut oğullarından, yahut üvey oğullarından, yahut erkek kardeşlerinden, yahut erkek kardeşlerinin oğullarından, yahut kız kardeşlerinin oğullarından, yahut müslüman kadınlardan, yahut sahip oldukları kölelerden, yahut erkekliği kalmamış hizmetçilerden, yahut da henüz kadınların mahrem yerlerine vakıf olmayan erkek çocuklardan başkalarına göstermesinler. Gizledikleri zinetler bilinsin diye ayaklarını yere vurmasınlar. Ey mü’minler, hep birlikte tövbe ediniz ki kurtuluşa eresiniz!"},{"n":32,"t":"Sizden bekâr olanları, kölelerinizden ve cariyelerinizden durumu uygun olanları evlendirin. Eğer bunlar yoksul iseler, Allah onları lütfuyla zenginleştirir. Allah, lütfu geniş olandır, hakkıyla bilendir."},{"n":33,"t":"Evlenmeye güçleri yetmeyenler de, Allah kendilerini lütfuyla zengin edinceye kadar iffetlerini korusunlar. Sahip olduğunuz kölelerden \"mükâtebe\" yapmak isteyenlere gelince, eğer onlarda bir hayır görürseniz onlarla mükâtebe yapın. Allah’ın size verdiği maldan onlara verin. Dünya hayatının geçici menfaatlerini elde etmek için iffetli olmak isteyen cariyelerinizi fuhşa zorlamayın. Kim onları buna zorlarsa bilinmelidir ki hiç şüphesiz onların zorlanmasından sonra Allah (onları) çok bağışlayıcıdır, çok merhametlidir."},{"n":34,"t":"Andolsun, biz size açıklayıcı âyetler, sizden önce gelip geçenlerden bir misal ve Allah’a karşı gelmekten sakınanlar için bir öğüt indirdik."},{"n":35,"t":"Allah, göklerin ve yerin nurudur. O’nun nurunun temsili şudur: Duvarda bir hücre; içinde bir kandil, kandil de bir cam fânûs içinde. Fânûs sanki inci gibi parlayan bir yıldız. Mübarek bir ağaçtan, ne doğuya, ne de batıya ait olan zeytin ağacından tutuşturulur. Bu ağacın yağı, ateş dokunmasa bile neredeyse aydınlatacak (kadar berrak)tır. Nur üstüne nur. Allah, dilediği kimseyi nuruna iletir. Allah, insanlar için misaller verir. Allah, her şeyi hakkıyla bilendir."},{"n":"36-37","t":"Allah’ın, yüceltilmesine ve içlerinde adının anılmasına izin verdiği evlerde hiçbir ticaretin ve hiçbir alışverişin kendilerini, Allah’ı anmaktan, namazı kılmaktan, zekâtı vermekten alıkoymadığı birtakım adamlar, buralarda sabah akşam O’nu tesbih ederler. Onlar, kalplerin ve gözlerin dikilip kalacağı bir günden korkarlar."},{"n":38,"t":"(Bütün bunları) Allah, kendilerini yaptıklarının en güzeli ile mükâfatlandırsın ve lütfundan onlara daha da fazlasını versin diye (yaparlar). Allah, dilediğini hesapsız olarak rızıklandırır."},{"n":39,"t":"İnkâr edenlere gelince; onların amelleri ıssız bir çöldeki serap gibidir. Susamış kimse onu su sanır. Yanına geldiğinde hiçbir şey bulamaz. (Tıpkı bunun gibi kâfir de hesap günü amellerinden bir şey bulamaz). Ancak Allah’ı yanında bulur da Allah onun hesabını tastamam görür. Allah, hesabı çabuk görendir."},{"n":40,"t":"Yahut (inkârcıların küfür içindeki hâlleri) derin bir denizdeki karanlıklar gibidir. (Bir deniz ki) onu dalga üstüne dalga kaplıyor, üstünde de bulutlar var. Karanlıklar üstüne karanlıklar. İnsan, elini çıkarsa neredeyse onu bile göremez. Kime Allah nur vermezse, onun için nur diye bir şey yoktur."},{"n":41,"t":"Göklerde ve yeryüzünde bulunan kimselerle, sıra sıra (kanat çırparak uçan) kuşların Allah’ı tespih ettiğini görmez misin? Her biri duasını ve tesbihini kesin olarak bilmektedir. Allah, onların yapmakta olduğu şeyleri hakkıyla bilendir."},{"n":42,"t":"Göklerin ve yerin hükümranlığı Allah’ındır. Dönüş de ancak Allah’adır."},{"n":43,"t":"Görmez misin ki Allah, bulutları sevk eder. Sonra, onları kaynaştırıp üst üste yığar. Nihayet yağmurun, onların arasından yağdığını görürsün. O, gökten, oradaki dağ (gibi bulut)lardan dolu indirir de onu dilediğine isabet ettirir, dilediğinden de geri çevirir. Bu bulutların şimşeğinin parıltısı neredeyse gözleri alacak."},{"n":44,"t":"Allah, geceyi ve gündüzü döndürüp duruyor. Şüphesiz bunda basiret sahibi olanlar için bir ibret vardır."},{"n":45,"t":"Allah, bütün canlıları sudan yarattı. İşte bunlardan bir kısmı karnı üzerinde sürünür, kimi iki ayak üzerinde yürür, kimisi dört ayak üzerinde yürür. Allah, dilediğini yaratır. Çünkü Allah, her şeye hakkıyla gücü yetendir."},{"n":46,"t":"Andolsun, biz açıklayıcı âyetler indirdik. Allah, dilediği kimseyi doğru yola iletir."},{"n":47,"t":"(Münâfıklar), \"Allah’a ve peygambere inandık ve itaat ettik\" derler. Sonra da onların bir kısmı bunun ardından yüz çevirirler. Hâlbuki onlar inanmış değillerdir."},{"n":48,"t":"Aralarında hüküm vermesi için Allah’a (Kur’an’a) ve peygambere çağırıldıkları zaman, bir de bakarsın ki içlerinden bir grup yüz çevirmektedir."},{"n":49,"t":"Ama gerçek (verilen hüküm) kendi lehlerinde ise, boyun eğerek ona gelirler."},{"n":50,"t":"Kalplerinde bir hastalık mı var, yoksa şüphe ve tereddüde mi düştüler? Yoksa Allah ve Resûlünün kendilerine karşı zulüm ve haksızlık edeceğinden mi korkuyorlar? Hayır, işte onlar asıl zalimlerdir."},{"n":51,"t":"Aralarında hüküm vermek için Allah’a (Kur’an’a) ve Resûlüne davet edildiklerinde, mü’minlerin söyleyeceği söz ancak, \"işittik ve iman ettik\" demeleridir. İşte onlar kurtuluşa erenlerin ta kendileridir."},{"n":52,"t":"Kim Allah’a ve Resûlüne itaat eder, Allah’tan korkar ve O’na karşı gelmekten sakınırsa, işte onlar başarıyı elde edenlerin ta kendileridir."},{"n":53,"t":"Münâfıklar, sen kendilerine emrettiğin takdirde mutlaka savaşa çıkacaklarına dair en ağır bir şekilde Allah’a yemin ettiler. De ki: \"Yemin etmeyin. Sizden istenen güzelce itaat etmektir. Şüphesiz Allah, yaptıklarınızdan hakkıyla haberdardır.\""},{"n":54,"t":"\"Allah’a itaat edin, peygambere itaat edin\" de. Eğer yüz çevirirseniz bilin ki ona yüklenen sorumluluğu ancak ona ait; size yüklenen görevin sorumluluğu da yalnızca size aittir. Eğer ona itaat ederseniz doğru yola erersiniz. Peygambere düşen ancak apaçık bir tebliğdir."},{"n":55,"t":"Allah, içinizden, iman edip de salih ameller işleyenlere, kendilerinden önce geçenleri egemen kıldığı gibi onları da yeryüzünde mutlaka egemen kılacağına, onlar için hoşnut ve razı olduğu dinlerini iyice yerleştireceğine, yaşadıkları korkularının ardından kendilerini mutlaka emniyete kavuşturacağına dair vaadde bulunmuştur. Onlar bana kulluk eder ve bana hiçbir şeyi ortak koşmazlar. Artık bundan sonra kimler inkâr ederse, işte onlar fasıkların ta kendileridir."},{"n":56,"t":"Namazı dosdoğru kılın, zekâtı verin, Resûle itaat edin ki size merhamet edilsin."},{"n":57,"t":"İnkâr edenlerin (Allah’ı) yeryüzünde âciz bırakacaklarını sanma! Onların varacağı yer cehennemdir. Ne kötü varış yeridir o!"},{"n":58,"t":"Ey iman edenler! Ellerinizin altında bulunanlar (köleleriniz) ve sizden henüz bulûğ çağına ermemiş olanlar, günde üç defa; sabah namazından önce, öğleyin elbiselerinizi çıkardığınız vakit ve yatsı namazından sonra (yanınıza girecekleri zaman) sizden izin istesinler. Bu üç vakit sizin soyunup dökündüğünüz vakitlerdir. Bu vakitlerin dışında (izinsiz girme konusunda) ne size, ne onlara bir günah vardır. Birbirinizin yanına girip çıkabilirsiniz. Allah, âyetlerini size işte böylece açıklar. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":59,"t":"Çocuklarınız erginlik çağına geldiklerinde, kendilerinden öncekilerin izin istedikleri gibi izin istesinler. İşte Allah âyetlerini size böyle açıklar. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":60,"t":"Artık evlenme ümidi beslemeyen, hayızdan ve doğumdan kesilmiş yaşlı kadınların zinetlerini göstermeksizin dış elbiselerini çıkarmalarında kendileri için bir günah yoktur. Ama yine sakınmaları onlar için daha hayırlıdır. Allah, hakkıyla işitendir, hakkıyla bilendir."},{"n":61,"t":"Köre güçlük yoktur, topala güçlük yoktur, hastaya da güçlük yoktur. Kendi evlerinizde veya babalarınızın evlerinde veya annelerinizin evlerinde veya erkek kardeşlerinizin evlerinde veya kız kardeşlerinizin evlerinde veya amcalarınızın evlerinde veya halalarınızın evlerinde veya dayılarınızın evlerinde veya teyzelerinizin evlerinde veya anahtarlarına sahip olduğunuz evlerde ya da dostlarınızın evlerinde yemek yemenizde de bir sakınca yoktur. Bir arada veya ayrı ayrı olarak yemek yemenizde de bir sakınca yoktur. Evlere girdiğiniz zaman birbirinize, Allah katından mübarek ve hoş bir esenlik dileği olarak, selâm verin. İşte Allah, düşünesiniz diye âyetleri size böyle açıklar."},{"n":62,"t":"Mü’minler ancak Allah’a ve peygamberine inanan, onunla beraber toplumu ilgilendiren bir iş üzerindeyken ondan izin almadan çekip gitmeyen kimselerdir. O hâlde bazı işlerini görmek için senden izin isterlerse, içlerinden dilediğine izin ver ve onlar için Allah’tan bağışlama dile. Şüphesiz Allah çok bağışlayandır, çok merhamet edendir."},{"n":63,"t":"(Ey inananlar!) Peygamberin (sizi) çağırmasını aranızda birbirinizi çağırmanız gibi tutmayın. İçinizden biribirini siper ederek sıvışıp gidenleri Allah gerçekten bilir. Artık onun emrine muhalefet edenler, başlarına bir belânın gelmesinden veya elem dolu bir azaba uğramaktan sakınsınlar."},{"n":64,"t":"Bilmiş olun ki şüphesiz göklerdeki her şey, yerdeki her şey Allah’ındır. O, içinde bulunduğunuz durumu gerçekten bilir. Allah’a döndürülecekleri ve yaptıklarını Allah’ın onlara haber vereceği günü hatırla. Allah, her şeyi hakkıyla bilendir."}],[{"n":1,"t":"Âlemlere bir uyarıcı olsun diye kuluna Furkân’ı indiren Allah’ın şanı yücedir."},{"n":2,"t":"O, göklerin ve yeryüzünün mülkü (hükümranlığı) kendisine ait olandır. Çocuk edinmemiştir. Mülkünde hiçbir ortağı da yoktur. O, her şeyi yaratmış ve yarattığı o şeyleri bir ölçüye göre takdir etmiştir."},{"n":3,"t":"(İnkâr edenler), Allah’ı bırakıp hiçbir şey yaratmayan ve zaten kendileri yaratılmış olan, üstelik kendilerine fayda ve zararları dokunmayan, öldürmeye, yaşatmaya ve ölüleri diriltip kabirden çıkarmaya güçleri yetmeyen ilâhlar edindiler."},{"n":4,"t":"İnkâr edenler, \"Bu Kur’an, Muhammed’in uydurduğu bir yalandan başka bir şey değildir. Başka bir topluluk da bu konuda ona yardım etmiştir\" dediler. Böylece onlar haksız ve asılsız bir söz uydurdular."},{"n":5,"t":"\"(Bu Kur’an, başkalarından) yazıp aldığı öncekilere ait efsanelerdir. Bunlar ona sabah akşam okunmaktadır\" dediler."},{"n":6,"t":"(Ey Muhammed!) De ki: \"O kitabı göklerin ve yerin sırrını bilen indirmiştir. Şüphesiz O, bağışlayandır, çok merhamet edendir.\""},{"n":7,"t":"Dediler ki: \"Bu ne biçim peygamber ki yemek yer, çarşıda pazarda dolaşır. Ona bir melek indirilseydi de, bu onunla beraber bir uyarıcı olsaydı ya!\""},{"n":8,"t":"\"Yahut kendisine bir hazine verilseydi veya ürününden yiyeceği bir bahçesi olsaydı ya!\" Zalimler, (inananlara): \"Siz ancak büyülenmiş bir adama uyuyorsunuz\" dediler."},{"n":9,"t":"(Ey Muhammed!) Senin hakkında bak nasıl da temsiller getirdiler de (haktan) saptılar. Artık onlar doğru yolu bulamazlar."},{"n":10,"t":"Dilerse sana bundan daha güzelini, içinden ırmaklar akan cennetleri verebilecek olan, sana saraylar kurabilecek olan Allah’ın şanı yücedir."},{"n":11,"t":"Hayır, onlar Kıyameti de yalanladılar. Biz ise o Kıyameti yalanlayanlara çılgın bir cehennem ateşi hazırlamışızdır."},{"n":12,"t":"Bu ateş onları uzak bir mesafeden görünce onun müthiş kaynamasını ve uğultusunu işitirler."},{"n":13,"t":"Elleri boyunlarına bağlanmış, çatılmış olarak cehennemin daracık bir yerine atıldıkları zaman orada, yok olup gitmeyi isterler"},{"n":14,"t":"(Kendilerine) \"Bugün bir kere yok olmayı istemeyin, birçok kere yok olmayı isteyin!\" (denir.)"},{"n":15,"t":"De ki: \"Bu mu daha hayırlıdır, yoksa Allah’a karşı gelmekten sakınanlara va’dedilen ebedîlik cenneti mi?\" Orası onlar için bir mükâfat ve varılacak bir yerdir."},{"n":16,"t":"Ebedî olarak kalacakları orada onlar için diledikleri her şey vardır. Bu, Rabbinin uhdesine aldığı, (yerine getirilmesi) istenen bir va’didir."},{"n":17,"t":"Rabbinin, onları ve Allah’ı bırakıp da taptıkları şeyleri bir araya getireceği ve (taptıklarına), \"Siz mi saptırdınız benim şu kullarımı, yoksa onlar kendileri mi yoldan saptılar\" diyeceği günü hatırla."},{"n":18,"t":"Onlar, \"Seni eksikliklerden uzak tutarız. Seni bırakıp da başka dostlar edinmek bize yaraşmaz. Fakat sen onlara ve atalarına o kadar bol nimet verdin ki, sonunda seni anmayı unuttular ve helâke giden bir toplum oldular\" derler."},{"n":19,"t":"(İlâh edindikleriniz) söyledikleriniz konusunda sizi yalancı çıkardılar. Artık kendinizden azabı savmaya gücünüz yetmeyecek ve kendinize yardım da edemeyeceksiniz. Sizden kim de zulüm ve haksızlık ederse, ona büyük bir azap tattırırız."},{"n":20,"t":"Senden önce gönderdiğimiz bütün peygamberler de şüphesiz yemek yerler, çarşıda pazarda gezerlerdi. (Ey insanlar!) Sizi birbiriniz için imtihan aracı kıldık. (Bakalım) sabredecek misiniz? Rabbin, hakkıyla görendir."},{"n":21,"t":"Bize kavuşacaklarını ummayanlar, \"Bize melekler indirilseydi, yahut Rabbimizi görseydik ya!\" dediler. Andolsun, onlar kendi benliklerinde büyüklük tasladılar ve büyük bir taşkınlık gösterdiler."},{"n":22,"t":"Fakat melekleri görecekleri gün, işte o gün suçlulara hiçbir müjde yoktur. \"Eyvah! Biz Allah’ın rahmetinden tamamen uzaklaştırılmışız\" diyecekler."},{"n":23,"t":"Onların yaptıkları bütün amellerine yöneldik ve onları dağılmış zerreciklere çevirdik."},{"n":24,"t":"O gün cennetliklerin kalacakları yer daha hayırlı, dinlenecekleri yer daha güzeldir."},{"n":25,"t":"O gün gök bulutlarla yarılıp parçalanacak ve melekler bölük bölük indirilecektir."},{"n":26,"t":"O gün gerçek hükümranlık Rahmân’ındır ve kâfirlere zorlu bir gün olacaktır."},{"n":27,"t":"O gün zalim kimse, (çaresizlik içinde) ellerini ısırıp şöyle diyecektir: \"Ne olurdu ben de peygamberle beraber aynı yolu tutsaydım!\""},{"n":28,"t":"\"Yazıklar olsun bana, keşke falanı dost edinmeseydim!\""},{"n":29,"t":"\"Andolsun, Kur’an bana geldikten sonra beni ondan o saptırdı. Zaten şeytan insanı yardımcısız bırakıverir.\""},{"n":30,"t":"Peygamber, \"Ey Rabbim! Kavmim şu Kur’an’ı terk edilmiş bir şey hâline getirdi\" dedi."},{"n":31,"t":"Biz, işte böyle, her peygamber için suçlulardan bir düşman yarattık. Yol gösterici ve yardım edici olarak Rabbin yeter."},{"n":32,"t":"İnkâr edenler, \"Kur’an ona bir defada toptan indirilseydi ya!\" dediler. Biz, Kur’an’la senin kalbini pekiştirmek için onu böyle kısım kısım indirdik ve onu ağır ağır okuduk."},{"n":33,"t":"Onlar sana hiçbir misal getirmezler ki (buna karşılık) sana gerçeği ve en güzel açıklamayı getirmiş olmayalım."},{"n":34,"t":"Yüzüstü cehenneme sürüklenecek olanlar var ya; işte onlar konumları itibariyle daha kötü, tuttukları yol itibariyle daha sapıktırlar."},{"n":35,"t":"Andolsun, Biz, Mûsâ’ya Kitab’ı (Tevrat’ı) verdik ve kardeşi Hârûn’u da ona yardımcı kıldık."},{"n":36,"t":"Onlara, \"Âyetlerimizi yalanlayan topluluğa gidin\" dedik. Nihayet o kavmi yerle bir ettik."},{"n":37,"t":"Nûh kavmini de, Peygamberleri yalanladıkları vakit suda boğduk. Onları insanlara bir ibret yaptık ve zalimlere elem dolu bir azap hazırladık."},{"n":38,"t":"Âd ve Semûd kavimlerini, Ress halkını ve bunların arasında pek çok nesilleri de helâk ettik."},{"n":39,"t":"Bunların her birine misaller getirdik, (öğüt almadıkları için) hepsini kırıp geçirdik."},{"n":40,"t":"Andolsun, senin kavmin, belâ yağmuruna tutularak yok edilen kente uğramışlardır. Yoksa onu görmüyorlar mıydı (ki ibret almadılar)? Hayır! (Görüyorlardı fakat) tekrar dirilmeyi ummuyorlardı."},{"n":"41-42","t":"Onlar seni görünce ancak eğlenceye alırlar. \"Allah’ın peygamber olarak gönderdiği adam bu mu? Biz, ilâhlarımıza sımsıkı sarılmasaydık neredeyse bizi ilâhlarımızdan uzaklaştıracaktı\" (derler.) Onlar yakında azabı gördükleri zaman, yolca kimin daha sapık olduğunu görecekler."},{"n":43,"t":"Kendi nefsinin arzusunu kendisine ilâh edineni gördün mü? Ona sen mi vekil olacaksın?"},{"n":44,"t":"Yoksa sen onların çoğunun (söz) dinleyeceklerini yahut akıllarını kullanacaklarını mı sanıyorsun? Onlar hayvanlar gibidirler, belki yolca onlardan daha da şaşkındırlar."},{"n":45,"t":"Rabbinin gölgeyi nasıl uzattığını görmez misin? İsteseydi onu sabit kılardı. Sonra biz güneşi gölgeye delil kıldık."},{"n":46,"t":"Sonra onu kendimize yavaş yavaş çektik."},{"n":47,"t":"O, geceyi size bir örtü, uykuyu istirahat zamanı ve gündüzü de hareket ve çalışma vakti yapandır."},{"n":"48-49","t":"O, rahmetinin önünde rüzgârları müjdeci olarak gönderendir. Ölü toprağı canlandıralım, yarattıklarımızdan birçok hayvanları ve insanları sulayalım diye gökten tertemiz bir su indirdik."},{"n":50,"t":"Andolsun, biz bunu insanlar arasında, düşünüp ibret alsınlar diye tekrar tekrar açıkladık. Fakat insanların çoğu nankörlükte direttiler."},{"n":51,"t":"Dileseydik her memlekete bir uyarıcı gönderirdik."},{"n":52,"t":"Öyle ise kâfirlere itaat etme, onlara karşı bu Kur’an’la büyük bir mücadele ver."},{"n":53,"t":"O, birinin suyu lezzetli ve tatlı, diğerininki tuzlu ve acı olan iki denizi salıverip aralarına da görünmez bir perde ve karışmalarını önleyici bir engel koyandır."},{"n":54,"t":"O, sudan bir insan yaratıp ondan soy sop ve hısımlık meydana getirendir. Rabbin, her şeye hakkıyla gücü yetendir."},{"n":55,"t":"Onlar, Allah’ı bırakıp, kendilerine ne faydası ne de zararı dokunan şeylere kulluk ederler. Kâfir, Rabbine karşı (şeytana) arka çıkandır."},{"n":56,"t":"Biz, seni ancak bir müjdeci ve bir uyarıcı olarak gönderdik."},{"n":57,"t":"De ki: \"Ben buna karşılık sizden dileyen kimsenin, Rabbine giden yolu tutmasından başka herhangi bir ücret istemiyorum.\""},{"n":58,"t":"Sen, o ölümsüz ve daima diri olana (Allah’a) tevekkül et. O’nu her türlü övgüyle yücelterek tesbih et. Kullarının günahlarından hakkıyla haberdar olarak O yeter!"},{"n":59,"t":"Gökleri ve yeryüzünü ve ikisi arasındakileri altı gün içinde (altı evrede) yaratan, sonra da Arş’a kurulan Rahmân’dır. Sen bunu haberdar olana sor!"},{"n":60,"t":"Onlara, \"Rahmân’a secdeye kapanın denildiğinde \"Rahmân da nedir? Senin bize emrettiğine mi secde edeceğiz?\" derler ve bu onların nefretini artırır."},{"n":61,"t":"Göğe burçlar yerleştiren, orada bir ışık kaynağı (güneş) ve aydınlatıcı bir ay yaratanın şanı çok yücedir."},{"n":62,"t":"O, öğüt almak isteyen ve çok şükredici olmayı dileyen kimseler için geceyi ve gündüzü birbiri ardınca getirendir."},{"n":63,"t":"Rahmân’ın kulları, yeryüzünde vakar ve tevazu ile yürüyen kimselerdir. Cahiller onlara laf attıkları zaman, \"selâm!\" der (geçer)ler."},{"n":64,"t":"Onlar, Rabblerine secde ederek ve kıyamda durarak geceleyenlerdir."},{"n":65,"t":"Onlar, şöyle diyenlerdir: \"Ey Rabbimiz! Bizden cehennem azabını uzaklaştır, gerçekten onun azabı sürekli bir helâktir!\""},{"n":66,"t":"\"Şüphesiz, ne kötü bir durak ve ne kötü bir konaktır orası.\""},{"n":67,"t":"Onlar, harcadıklarında ne israf ne de cimrilik edenlerdir. Onların harcamaları, bu ikisi arası dengeli bir harcamadır."},{"n":68,"t":"Onlar, Allah ile beraber başka bir ilâha kulluk etmeyen, haksız yere, Allah’ın haram kıldığı cana kıymayan ve zina etmeyen kimselerdir. Kim bunları yaparsa ağır azaba uğrar."},{"n":69,"t":"Kıyamet günü onun azabı kat kat artırılır ve horlanmış olarak orada ebedî kalır."},{"n":70,"t":"Ancak tövbe edip de inanan ve salih amel işleyenler başka. Allah işte onların kötülüklerini iyiliklere çevirir. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":71,"t":"Kim de tövbe eder ve salih amel işlerse işte o, Allah’a, tövbesi kabul edilmiş olarak döner."},{"n":72,"t":"Onlar, yalana şahitlik etmeyen, faydasız boş bir şeyle karşılaştıkları zaman, vakar ve hoşgörü ile geçip gidenlerdir."},{"n":73,"t":"Onlar, kendilerine Rabblerinin âyetleri hatırlatıldığı zaman, onlara kör ve sağır kesilmezler."},{"n":74,"t":"Onlar, \"Ey Rabbimiz! Eşlerimizi ve çocuklarımızı bize göz aydınlığı kıl ve bizi Allah’a karşı gelmekten sakınanlara önder eyle\" diyenlerdir."},{"n":75,"t":"İşte onlar, sabretmelerine karşılık cennetin yüksek makamlarıyla mükâfatlandırılacaklar ve orada esenlik dileği ve selâmla karşılanacaklardır."},{"n":76,"t":"Orada ebedî kalırlar. Orası ne güzel bir durak ve ne güzel bir konaktır!"},{"n":77,"t":"(Ey Muhammed!) De ki: \"Duanız olmasa, Rabbim size ne diye değer versin! Siz yalanladınız. Öyle ise azap yakanızı bırakmayacak.\""}],[{"n":1,"t":"Tâ Sîn Mîm."},{"n":2,"t":"Bunlar, apaçık Kitab’ın âyetleridir."},{"n":3,"t":"Ey Muhammed! Mü’min olmuyorlar diye âdeta kendini helâk edeceksin!"},{"n":4,"t":"Biz dilesek, onlara gökten bir mucize indiririz de, ona boyun eğmek zorunda kalırlar."},{"n":5,"t":"Rahmân’dan kendilerine gelen her yeni öğütten mutlaka yüz çevirirler."},{"n":6,"t":"Onlar (Allah’ın âyetlerini) yalanladılar, fakat alay edegeldikleri şeylerin haberleri başlarına gelecek."},{"n":7,"t":"Yeryüzüne bakmazlar mı, orada her türden nice güzel ve yararlı bitkiler bitirdik."},{"n":8,"t":"Şüphesiz bunlarda (Allah’ın varlığına) bir delil vardır, ama onların çoğu inanmamaktadırlar."},{"n":9,"t":"Şüphesiz senin Rabbin, elbette mutlak güç sahibidir, çok merhametlidir."},{"n":"10-11","t":"Hani Rabbin, Mûsâ’ya; \"Zalimler topluluğuna, Firavun’un kavmine git! Başlarına geleceklerden hâlâ korkmuyorlar mı?\" diye seslenmişti."},{"n":12,"t":"Mûsâ, şöyle dedi: \"Ey Rabbim! Muhakkak ki ben, beni yalanlamalarından korkuyorum.\""},{"n":13,"t":"\"Göğsüm daralır. Akıcı konuşamam. Onun için, Hârûn’a da peygamberlik ver (ve onu bana yardımcı yap).\""},{"n":14,"t":"\"Bir de onlara karşı ben suçlu durumundayım. Bu yüzden onların beni öldürmelerinden korkarım.\""},{"n":15,"t":"Allah dedi ki, \"Hayır, korkma! Mucizelerimizle gidin. Çünkü biz sizinle beraberiz, (her şeyi) işitmekteyiz.\""},{"n":16,"t":"\"Firavun’a gidin ve deyin: \"Şüphesiz biz âlemlerin Rabbinin elçisiyiz\","},{"n":17,"t":"\"İsrailoğullarını bizimle beraber gönder.\""},{"n":18,"t":"Firavun, şöyle dedi: \"Seni biz küçük bir çocuk olarak alıp aramızda büyütmedik mi? Sen ömrünün nice yıllarını aramızda geçirdin.\""},{"n":19,"t":"\"(Böyle iken) sen o yaptığın işi yaptın (adam öldürdün). Sen nankörlerdensin.\""},{"n":20,"t":"Mûsâ, şöyle dedi: \"Ben onu, o vakit kendimi kaybetmiş bir hâlde iken (istemeyerek) yaptım.\""},{"n":21,"t":"\"Sizden korktuğum için de hemen aranızdan kaçtım. Derken, Rabbim bana hüküm ve hikmet bahşetti de beni peygamberlerden kıldı.\""},{"n":22,"t":"\"Senin başıma kaktığın bu nimet (gerçekte) İsrailoğullarını köleleştirmen(in neticesi)dir.\""},{"n":23,"t":"Firavun, \"Âlemlerin Rabbi de nedir?\" dedi."},{"n":24,"t":"Mûsâ, \"O, göklerin ve yerin ve her ikisi arasında bulunan her şeyin Rabbidir. Eğer gerçekten inanırsanız bu böyledir.\""},{"n":25,"t":"Firavun, etrafındakilere (alaycı bir ifade ile) \"dinlemez misiniz?\" dedi."},{"n":26,"t":"Mûsâ, \"O, sizin de Rabbiniz, geçmiş atalarınızın da Rabbidir\" dedi."},{"n":27,"t":"Firavun, \"Bu size gönderilen peygamberiniz, şüphesiz delidir\" dedi."},{"n":28,"t":"Mûsâ, \"O, doğunun da batının da ve ikisi arasındaki her şeyin de Rabbidir. Eğer düşünüyorsanız bu, böyledir\" dedi."},{"n":29,"t":"Firavun, \"Eğer benden başka bir ilâh edinirsen, andolsun seni zindana atılanlardan ederim.\""},{"n":30,"t":"Mûsâ, \"Sana apaçık bir delil getirmiş olsam da mı?\" dedi."},{"n":31,"t":"Firavun, \"Doğru söyleyenlerden isen haydi getir onu,\" dedi."},{"n":32,"t":"Bunun üzerine Mûsâ, asasını attı, bir de ne görsünler, asa açıkça kocaman bir yılan olmuş."},{"n":33,"t":"Elini koynundan çıkardı, bir de ne görsünler, bakanlara bembeyaz olmuş."},{"n":34,"t":"Firavun, çevresindeki ileri gelenlere, \"Şüphesiz bu, bilgin bir sihirbazdır\" dedi."},{"n":35,"t":"\"Sizi, yaptığı sihirle, yurdunuzdan çıkarmak istiyor. Ne dersiniz?\""},{"n":36,"t":"Dediler ki: \"Onu ve kardeşini alıkoy. Şehirlere de toplayıcı adamlar gönder.\""},{"n":37,"t":"\"Sana bütün usta sihirbazları getirsinler.\""},{"n":38,"t":"Böylece sihirbazlar, belli bir günün belirlenen bir vaktinde bir araya getirildiler."},{"n":39,"t":"İnsanlara da \"Siz de toplanır mısınız?\" denildi."},{"n":40,"t":"\"Umarız, üstün gelirlerse sihirbazlara uyarız\" (dediler.)"},{"n":41,"t":"Sihirbazlar gelince, Firavun’a, \"Eğer biz üstün gelirsek, gerçekten bize bir mükâfat var mı?\" dediler."},{"n":42,"t":"Firavun, \"Evet, hem o takdirde mutlaka bana yakın kimselerden olacaksınız\" dedi."},{"n":43,"t":"Mûsâ onlara, \"Hadi ortaya atacağınız şeyi atın\" dedi."},{"n":44,"t":"Bunun üzerine onlar iplerini ve değneklerini attılar ve \"Firavun’un gücüyle elbette bizler üstün geleceğiz\" dediler."},{"n":45,"t":"Mûsâ da asasını attı. Bir de ne görsünler, asa onların düzdükleri sihir takımlarını yutuyor."},{"n":46,"t":"Bunun üzerine sihirbazlar derhal secdeye kapandılar."},{"n":47,"t":"\"Âlemlerin Rabbine inandık\" dediler."},{"n":48,"t":"\"Mûsâ’nın ve Hârûn’un Rabbi’ne.\""},{"n":49,"t":"Firavun, \"Ben size izin vermeden ona inandınız ha? Mutlaka o, size sihri öğreten büyüğünüzdür. Yakında bilip göreceksiniz siz! Andolsun, ellerinizi ve ayaklarınızı çaprazlama keseceğim ve hepinizi asacağım\" dedi."},{"n":50,"t":"Sihirbazlar şöyle dediler: \"Zararı yok, mutlaka Rabbimize döneceğiz.\""},{"n":51,"t":"\"(Burada) ilk inananlar biz olduğumuz için şüphesiz Rabbimizin, hatalarımızı bağışlayacağını umuyoruz.\""},{"n":52,"t":"Biz Mûsâ’ya, \"Kullarımı geceleyin yola çıkar, muhakkak ki takip edileceksiniz\" diye vahyettik."},{"n":53,"t":"Firavun da şehirlere (asker) toplayıcılar gönderdi."},{"n":54,"t":"Dedi ki, \"Bunlar pek az ve önemsiz bir topluluktur.\""},{"n":55,"t":"\"Şüphesiz onlar bize öfke duyuyorlar.\""},{"n":56,"t":"\"Ama biz uyanık ve tedbirli bir topluluğuz.\""},{"n":"57-58","t":"Biz de Firavun’un kavmini bahçelerden, pınar başlarından, servetlerden ve iyi bir konumdan çıkardık."},{"n":59,"t":"İşte böyle yaptık ve onlara, İsrailoğullarını mirasçı kıldık."},{"n":60,"t":"Firavun ve adamları gün doğarken onları takibe koyuldular."},{"n":61,"t":"İki topluluk birbirini görünce Mûsâ’nın arkadaşları, \"Eyvah yakalandık\" dediler."},{"n":62,"t":"Mûsâ, \"Hayır! Rabbim şüphesiz benimledir, bana yol gösterecektir\" dedi."},{"n":63,"t":"Bunun üzerine Mûsâ’ya, \"Asan ile denize vur\" diye vahyettik. Deniz derhal yarıldı. Her parçası koca bir dağ gibiydi."},{"n":64,"t":"Ötekileri de oraya yaklaştırdık."},{"n":65,"t":"Mûsâ’yı ve beraberindekilerin hepsini kurtardık."},{"n":66,"t":"Sonra ötekileri suda boğduk."},{"n":67,"t":"Bunda şüphesiz bir ibret vardır. Ama pek çokları iman etmiş değillerdi."},{"n":68,"t":"Şüphesiz ki senin Rabbin elbette mutlak güç sahibidir, çok merhametlidir."},{"n":69,"t":"Ey Muhammed! Onlara İbrahim’in haberini de oku."},{"n":70,"t":"Hani o, babasına ve kavmine, \"Neye tapıyorsunuz?\" demişti."},{"n":71,"t":"\"Putlara tapıyoruz ve onlara tapmağa devam edeceğiz\" demişlerdi."},{"n":72,"t":"İbrahim, dedi ki: \"Onlara yalvardığınızda sizi işitiyorlar mı?\""},{"n":73,"t":"\"Yahut size fayda veya zararları dokunur mu?\""},{"n":74,"t":"\"Hayır, ama biz babalarımızı böyle yaparken bulduk\" dediler."},{"n":"75-76","t":"İbrahim, şöyle dedi: \"Sizin ve geçmiş atalarınızın taptığı şeyleri gördünüz mü?\""},{"n":77,"t":"\"Şüphesiz onlar benim düşmanımdır. Ancak âlemlerin Rabbi olan Allah, dostumdur.\""},{"n":78,"t":"\"O, beni yaratan ve bana doğru yolu gösterendir.\""},{"n":79,"t":"\"O, bana yediren ve içirendir.\""},{"n":80,"t":"\"Hastalandığımda da O bana şifa verir.\""},{"n":81,"t":"\"O, benim canımı alacak ve sonra diriltecek olandır.\""},{"n":82,"t":"\"O, hesap gününde, hatalarımı bağışlayacağını umduğumdur.\""},{"n":83,"t":"\"Ey Rabbim! Bana bir hikmet bahşet ve beni salih kimseler arasına kat.\""},{"n":84,"t":"\"Sonra gelecekler arasında beni doğrulukla anılanlardan kıl.\""},{"n":85,"t":"\"Beni Naîm cennetinin varislerinden eyle.\""},{"n":86,"t":"\"Babamı da bağışla. Çünkü o gerçekten yolunu şaşıranlardandır.\""},{"n":87,"t":"\"(Kulların) diriltilecekleri gün beni utandırma!\""},{"n":88,"t":"\"O gün ki ne mal fayda verir ne oğullar!\""},{"n":89,"t":"\"Allah’a arınmış bir kalp ile gelen başka.\""},{"n":90,"t":"Cennet, Allah’a karşı gelmekten sakınanlara yaklaştırılacak."},{"n":"91-93","t":"Cehennem de azgınlara gösterilecek ve onlara, \"Allah’ı bırakıp da tapmakta olduklarınız nerede? Size yardım ediyorlar mı veya kendilerini kurtarabiliyorlar mı?\" denilecek."},{"n":"94-95","t":"Artık onlar ve o azgınlar ile İblis’in askerleri hepsi birden tepetakla oraya atılırlar."},{"n":96,"t":"Orada onlar taptıklarıyla çekişerek şöyle derler:"},{"n":97,"t":"\"Allah’a andolsun! Biz gerçekten apaçık bir sapıklık içindeymişiz.\""},{"n":98,"t":"\"Çünkü sizi, âlemlerin Rabbi ile bir tutuyorduk.\""},{"n":99,"t":"\"Bizi ancak (önderlerimiz olan) suçlular saptırdı.\""},{"n":100,"t":"\"İşte bu yüzden bizim şefaatçilerimiz yok.\""},{"n":101,"t":"\"Candan bir dostumuz da yok.\""},{"n":102,"t":"\"Keşke (dünyaya) bir dönüşümüz olsa da inananlardan olsak.\""},{"n":103,"t":"Elbet bunda bir ibret vardır. Onların çoğu iman etmiş değillerdi."},{"n":104,"t":"Şüphesiz senin Rabbin, mutlak güç sahibi olandır, çok merhametli olandır."},{"n":105,"t":"Nûh’un kavmi de Peygamberleri yalanladı."},{"n":106,"t":"Hani kardeşleri Nûh, onlara şöyle demişti: \"Allah’a karşı gelmekten sakınmaz mısınız?\""},{"n":107,"t":"\"Şüphesiz ben size gönderilmiş güvenilir bir peygamberim.\""},{"n":108,"t":"\"Artık Allah’a karşı gelmekten sakının ve bana itaat edin.\""},{"n":109,"t":"\"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.\""},{"n":110,"t":"\"O hâlde, Allah’a karşı gelmekten sakının ve bana itaat edin!\""},{"n":111,"t":"Dediler ki: \"Sana hep aşağılık kimseler uymuş iken, biz hiç sana inanır mıyız?\""},{"n":112,"t":"Nûh, şöyle dedi: \"Onların yaptıklarına dair benim ne bilgim olabilir?\""},{"n":113,"t":"\"Onların hesaplarını görmek ancak Rabbime aittir. Bir anlayabilseniz!\""},{"n":114,"t":"\"Ben inananları kovacak değilim.\""},{"n":115,"t":"\"Ben ancak apaçık bir uyarıcıyım.\""},{"n":116,"t":"Dediler ki: \"Ey Nûh! (Bu işten) vazgeçmezsen mutlaka taşlananlardan olacaksın!\""},{"n":117,"t":"Nûh, şöyle dedi: \"Ey Rabbim! Kavmim beni yalanladı.\""},{"n":118,"t":"\"Artık onlarla benim aramda sen hükmet. Beni ve benimle birlikte olan mü’minleri kurtar.\""},{"n":119,"t":"Derken biz onu ve beraberindekileri dolu geminin içinde (taşıyıp) kurtardık."},{"n":120,"t":"Sonra da geride kalanları suda boğduk."},{"n":121,"t":"Şüphesiz bunda bir ibret vardır. Onların çoğu ise iman etmiş değillerdir."},{"n":122,"t":"Şüphesiz senin Rabbin mutlak güç sahibi olandır, çok merhametli olandır."},{"n":123,"t":"Âd kavmi de peygamberleri yalanladı."},{"n":124,"t":"Hani kardeşleri Hûd, onlara şöyle demişti: \"Allah’a karşı gelmekten sakınmaz mısınız?\""},{"n":125,"t":"\"Şüphesiz ben, size gönderilmiş güvenilir bir peygamberim.\""},{"n":126,"t":"\"Öyle ise Allah’a karşı gelmekten sakının ve bana itaat edin.\""},{"n":127,"t":"\"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.\""},{"n":128,"t":"\"Siz her yüksek yere bir alamet bina yapıp boş şeylerle eğleniyor musunuz?\""},{"n":129,"t":"\"İçlerinde ebedî yaşama ümidiyle sağlam yapılar mı ediniyorsunuz?\""},{"n":130,"t":"\"Tutup yakaladığınız zaman zorbaca yakalarsınız.\""},{"n":131,"t":"\"Artık Allah’a karşı gelmekten sakının ve bana itaat edin.\""},{"n":"132-134","t":"\"Bildiğiniz her şeyi size veren, size hayvanlar, oğullar, bahçeler ve pınarlar veren Allah’a karşı gelmekten sakının.\""},{"n":135,"t":"\"Çünkü ben, sizin adınıza büyük bir günün azabından korkuyorum.\""},{"n":136,"t":"Dediler ki: \"Sen ister öğüt ver, ister öğüt verenlerden olma, bize göre birdir.\""},{"n":137,"t":"\"Bu, öncekilerin geleneklerinden başka bir şey değildir.\""},{"n":138,"t":"\"Biz azaba uğratılacak da değiliz.\""},{"n":139,"t":"Böylece onlar Hûd’u yalanladılar. Biz de bu yüzden onları helâk ettik. Şüphesiz bunda bir ibret vardır. Onların çoğu ise iman etmiş değillerdir."},{"n":140,"t":"Şüphesiz senin Rabbin, mutlak güç sahibi ve çok merhametli olandır."},{"n":141,"t":"Semûd kavmi de Peygamberleri yalanladı."},{"n":142,"t":"Hani kardeşleri Salih, onlara şöyle demişti: \"Allah’a karşı gelmekten sakınmaz mısınız?\""},{"n":143,"t":"\"Ben size gönderilmiş güvenilir bir peygamberim.\""},{"n":144,"t":"\"Öyle ise Allah’a karşı gelmekten sakının ve bana itaat edin!\""},{"n":145,"t":"\"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.\""},{"n":"146-148","t":"\"Siz buradaki bahçelerde, pınar başlarında, ekinlerde, meyveleri olgunlaşmış hurmalıklarda güven içinde bırakılacak mısınız?\""},{"n":149,"t":"\"Bir de dağlardan ustalıkla evler yontuyorsunuz.\""},{"n":150,"t":"\"Artık Allah’a karşı gelmekten sakının ve bana itaat edin.\""},{"n":"151-152","t":"\"Yeryüzünde ıslaha çalışmayıp fesat çıkaran haddi aşmışların emrine itaat etmeyin.\""},{"n":153,"t":"Dediler ki: \"Sen ancak büyülenmişlerdensin.\""},{"n":154,"t":"\"Sen de ancak bizim gibi bir beşersin. Eğer doğru söyleyenlerden isen haydi bize bir mucize getir.\""},{"n":155,"t":"Salih, şöyle dedi: \"İşte bir dişi deve! Onun (belli bir gün) su içme hakkı var, sizin de belli bir gün su içme hakkınız vardır.\""},{"n":156,"t":"\"Sakın ona bir kötülük dokundurmayın. Yoksa büyük bir günün azabı sizi yakalar.\""},{"n":157,"t":"Derken onu kestiler, fakat pişman oldular."},{"n":158,"t":"Böylece onları azap yakaladı. Şüphesiz bunda bir ibret vardır. Onların çoğu ise iman etmiş değillerdir."},{"n":159,"t":"Şüphesiz senin Rabbin, mutlak güç sahibi ve çok merhametli olandır."},{"n":160,"t":"Lût’un kavmi de peygamberleri yalanladı."},{"n":161,"t":"Hani kardeşleri Lût, onlara şöyle demişti: \"Allah’a karşı gelmekten sakınmaz mısınız?\""},{"n":162,"t":"\"Şüphesiz ben size gönderilmiş güvenilir bir peygamberim.\""},{"n":163,"t":"\"Artık Allah’a karşı gelmekten sakının ve bana itaat edin.\""},{"n":164,"t":"\"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.\""},{"n":"165-166","t":"\"Rabbinizin, sizin için yarattığı eşlerinizi bırakıyor da insanlar arasından erkeklere mi yanaşıyorsunuz? Siz gerçekten haddi aşan bir topluluksunuz.\""},{"n":167,"t":"Dediler ki: \"Ey Lût! (İşimize karışmaktan) vazgeçmezsen mutlaka (şehirden) çıkarılanlardan olacaksın!\""},{"n":168,"t":"Lût, şöyle dedi: \"Şüphesiz ben sizin yaptığınız bu çirkin işe kızanlardanım.\""},{"n":169,"t":"\"Ey Rabbim! Beni ve ailemi onların yaptıkları çirkin işten kurtar.\""},{"n":"170-171","t":"Bunun üzerine biz de onu ve geri kalanlar arasındaki yaşlı bir kadın hariç bütün ailesini kurtardık."},{"n":172,"t":"Sonra diğerlerini helâk ettik."},{"n":173,"t":"Onların üzerine bir yağmur (gibi taş) yağdırdık. (Başlarına gelecekler konusunda) uyarılanların yağmuru ne kadar da kötü idi!"},{"n":174,"t":"Şüphesiz bunda büyük bir ibret vardır. Onların çoğu ise iman etmiş değillerdir."},{"n":175,"t":"Şüphesiz senin Rabbin, mutlak güç sahibi ve çok merhametli olandır."},{"n":176,"t":"Eyke halkı da peygamberleri yalanladı."},{"n":177,"t":"Hani Şu’ayb, onlara şöyle demişti: \"Allah’a karşı gelmekten sakınmaz mısınız?\""},{"n":178,"t":"\"Şüphesiz ben size gönderilmiş güvenilir bir peygamberim.\""},{"n":179,"t":"Artık, Allah’a karşı gelmekten sakının ve bana itaat edin."},{"n":180,"t":"\"Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.\""},{"n":181,"t":"\"Ölçüyü tam yapın. Eksik verenlerden olmayın.\""},{"n":182,"t":"\"Doğru terazi ile tartın.\""},{"n":183,"t":"\"İnsanların mallarını ve haklarını eksiltmeyin. Yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.\""},{"n":184,"t":"\"Sizi ve önceki nesilleri yaratana karşı gelmekten sakının.\""},{"n":185,"t":"Onlar şöyle dediler: \"Sen ancak büyülenmişlerdensin.\""},{"n":186,"t":"\"Sen sadece bizim gibi bir insansın. Biz senin yalancılardan olduğunu sanıyoruz.\""},{"n":187,"t":"\"Eğer doğru söyleyenlerden isen, haydi gökten üzerimize bir parça düşür.\""},{"n":188,"t":"Şu’ayb, \"Rabbim, yaptıklarınızı en iyi bilendir\" dedi."},{"n":189,"t":"Onlar Şu’ayb’ı yalanladılar. Derken gölge gününün azabı onları yakaladı. Şüphesiz o, büyük bir günün azabı idi."},{"n":190,"t":"Şüphesiz bunda bir ibret vardır. Onların çoğu ise iman etmiş değillerdir."},{"n":191,"t":"Şüphesiz senin Rabbin, mutlak güç sahibi ve çok merhametli olandır."},{"n":192,"t":"Şüphesiz bu Kur’an, âlemlerin Rabbi’nin indirmesidir."},{"n":"193-195","t":"Uyarıcılardan olasın diye onu güvenilir Ruh (Cebrail) senin kalbine apaçık Arapça bir dil ile indirmiştir."},{"n":196,"t":"Şüphesiz bu (Kur’an’ın indirileceği) öncekilerin kitaplarında da vardı."},{"n":197,"t":"İsrailoğulları bilginlerinin onu bilmesi, onlar (Mekke müşrikleri) için bir delil değil midir?"},{"n":"198-199","t":"Biz onu Arapça bilmeyenlerden birine indirseydik ve o da bunu kendilerine okusaydı, yine buna inanmazlardı."},{"n":200,"t":"İşte böylece biz onu (Kur’an’ı) suçluların kalbine soktuk."},{"n":"201-203","t":"Onlar, farkında olmadan ansızın kendilerine gelecek olan elem dolu azabı görüp de, \"Bize mühlet verilmez mi?\" demedikçe, ona inanmazlar."},{"n":204,"t":"Bizim azabımızın çabuklaşmasını mı istiyorlar?"},{"n":205,"t":"Ey Muhammed! Ne dersin; biz onları yıllarca (dünya nimetlerinden) yararlandırsak,"},{"n":206,"t":"Sonra da kendilerine tehdit edildikleri şey gelse, (hâlleri nice olurdu?)"},{"n":207,"t":"(Dünyada) yararlandırıldıkları şeyler onlara fayda sağlamazdı."},{"n":208,"t":"Biz, hiçbir memleketi uyarıcıları olmadıkça helâk etmedik."},{"n":209,"t":"Bu, bir hatırlatmadır. Biz zalim değiliz."},{"n":210,"t":"O Kur’an’ı şeytanlar indirmemiştir."},{"n":211,"t":"Zaten bu onların harcı değildir, buna güçleri de yetmez."},{"n":212,"t":"Çünkü onlar (vahyi) işitmekten uzaklaştırılmışlardır."},{"n":213,"t":"Öyle ise sakın Allah ile beraber başka bir ilâha yalvarma, sonra azaba uğratılanlardan olursun!"},{"n":214,"t":"(Önce) en yakın akrabanı uyar."},{"n":215,"t":"Mü’minlerden sana uyanlara kanatlarını indir."},{"n":216,"t":"Eğer sana karşı gelirlerse, \"Şüphesiz ben sizin yaptığınız şeylerden uzağım\" de."},{"n":"217-219","t":"Namaza kalktığında, seni ve secde edenler arasında dolaşmanı gören; mutlak güç sahibi, çok merhametli olan Allah’a tevekkül et."},{"n":220,"t":"Şüphesiz O, hakkıyla işitendir, hakkıyla bilendir."},{"n":221,"t":"Şeytanların kime ineceğini size haber vereyim mi?"},{"n":222,"t":"Onlar, her günahkâr yalancıya inerler."},{"n":223,"t":"Bunlar da şeytanlara kulak verirler. Onların çoğu ise yalancıdır."},{"n":224,"t":"Şairlere ise haddi aşan azgınlar uyarlar."},{"n":"225-226","t":"Görmez misin ki onlar, her vadide şaşkın şaşkın dolaşırlar ve yapmadıkları şeyleri söylerler."},{"n":227,"t":"Ancak iman edip salih amel işleyen, Allah’ı çok anan ve haksızlığa uğratıldıktan sonra öçlerini alanlar başka. Zulmedenler hangi akıbete uğrayacaklarını göreceklerdir."}],[{"n":1,"t":"Tâ-Sîn. Bunlar Kur’an’ın, apaçık bir kitabın âyetleridir."},{"n":"2-3","t":"Kur’an, namazı dosdoğru kılan, zekâtı veren ve ahirete de kesin olarak inanan mü’minler için bir hidayet rehberi ve bir müjdedir."},{"n":4,"t":"Şüphesiz, ahiret hayatına inanmayanların işlerini biz kendilerine güzel göstermişizdir de o yüzden bocalayıp dururlar."},{"n":5,"t":"Onlar, azabın en kötüsü kendilerine has olan kimselerdir. Onlar ahirette en çok ziyana uğrayanlardır."},{"n":6,"t":"Şüphesiz bu Kur’an sana, hüküm ve hikmet sahibi, hakkıyla bilen Allah tarafından verilmektedir."},{"n":7,"t":"Hani Mûsâ, ailesine, \"Ben bir ateş gördüm, ondan size bir haber, yahut ısınasınız diye bir kor ateş getireceğim\" demişti."},{"n":8,"t":"(Mûsâ) Ateşe varınca ona şöyle seslenildi: \"Ateşin başındaki de çevresindekiler de kutlu olsun! Âlemlerin Rabbi olan Allah, eksikliklerden uzaktır.\""},{"n":9,"t":"\"Ey Mûsâ! Gerçek şu ki, ben mutlak güç sahibi, hüküm ve hikmet sahibi olan Allah’ım.\""},{"n":10,"t":"\"Değneğini at.\" (Mûsâ değneğini attı.) Onu yılanmış gibi hareket eder görünce, dönüp ardına bakmadan kaçtı. (Allah, şöyle dedi): \"Ey Mûsâ, korkma! Benim katımda peygamberler korkmazlar.\""},{"n":11,"t":"\"Ancak kim zulmeder de sonra (yaptığı) kötülüğün yerine iyilik yaparsa bilsin ki şüphesiz ben çok bağışlayıcıyım, çok merhamet edenim.\""},{"n":12,"t":"\"Elini koynuna sok; Firavun’a ve onun kavmine gönderilen dokuz mucizeden biri olarak, kusursuz bembeyaz olarak çıksın. Çünkü onlar fasık bir kavimdir.\""},{"n":13,"t":"Nitekim âyetlerimiz kendilerine gerçeği gösterecek biçimde gelince, \"Bu apaçık bir sihirdir\" dediler."},{"n":14,"t":"Kendileri de bunların hak olduklarını kesin olarak bildikleri hâlde, sırf zalimliklerinden ve büyüklük taslamalarından ötürü onları inkâr ettiler. Ama bozguncuların sonunun nasıl olduğuna bir bak!"},{"n":15,"t":"Andolsun! Biz Dâvûd’a ve Süleyman’a ilim verdik. Onlar, \"Hamd, bizi mü’min kullarının birçoğundan üstün kılan Allah’a mahsustur\" dediler."},{"n":16,"t":"Süleyman, Dâvûd’a varis oldu ve, \"Ey insanlar, bize kuş dili öğretildi ve bize her şey verildi. Şüphesiz bu, apaçık bir lütuftur\" dedi."},{"n":17,"t":"Süleyman’ın, cinlerden, insanlardan ve kuşlardan meydana gelen orduları onun önünde toplandı. Hep birlikte düzenli olarak sevk ediliyorlardı."},{"n":18,"t":"Nihayet karınca vadisine geldikleri vakit bir karınca, \"Ey karıncalar! Yuvalarınıza girin, Süleyman ve ordusu farkına varmadan sizi ezmesinler\" dedi."},{"n":19,"t":"Süleyman, onun bu sözüne tebessüm ile gülerek dedi ki: \"Ey Rabbim! Beni; bana ve ana babama verdiğin nimetlere şükretmeye ve razı olacağın salih ameller işlemeye sevk et ve beni rahmetinle salih kullarının arasına kat!\""},{"n":20,"t":"Süleyman, kuşlara göz atıp yokladı ve şöyle dedi: \"Hüdhüd’ü niçin göremiyorum? Yoksa kayıplara mı karıştı?\""},{"n":21,"t":"\"Bana (mazeretini gösteren) apaçık bir delil getirmedikçe kesinlikle onu ağır bir şekilde cezalandıracağım, ya da kafasını keseceğim.\""},{"n":22,"t":"Derken Hüdhüd çok beklemedi, çıkageldi ve (Süleyman’a) şöyle dedi: \"Senin bilmediğin bir şey öğrendim. Sebe’den sana sağlam bir haber getirdim.\""},{"n":23,"t":"\"Ben, onlara (Sebe halkına) hükümdarlık eden, kendisine her şeyden bolca verilmiş ve büyük bir tahtı olan bir kadın gördüm.\""},{"n":24,"t":"\"Onun ve kavminin, Allah’ı bırakıp güneşe taptıklarını gördüm. Şeytan, onlara yaptıklarını süslü göstermiş ve böylece onları yoldan çıkarmış. Bu yüzden de onlar doğru yolu bulamıyorlar.\""},{"n":25,"t":"\"Göklerde ve yerde gizli olanı ortaya çıkaran, sizin gizlediğiniz ve açığa vurduğunuz şeyleri bilen Allah’a secde etmesinler diye (şeytan onları yoldan çıkarmış.)\""},{"n":26,"t":"Allah, kendisinden başka hiçbir ilâh bulunmayandır. Büyük Arş’ın Rabbidir."},{"n":27,"t":"Süleyman, Hüdhüd’e şöyle dedi: \"Doğru mu söylüyorsun, yoksa yalancılardan mısın, göreceğiz.\""},{"n":28,"t":"\"Benim şu mektubumu götür onlara at, sonra da yanlarından ayrıl ve ne sonuca varacaklarına bak.\""},{"n":29,"t":"Sebe kraliçesi Belkıs dedi ki: \"Ey ileri gelenler! Bana çok önemli bir mektup atıldı.\""},{"n":"30-31","t":"\"Mektup, Süleyman’dan gelmiştir. O, ‘Bismillâhirrahmânirrahîm’ diye başlamakta ve içinde ‘Bana karşı büyüklük taslamayın ve teslimiyet göstererek bana gelin’ denilmektedir.\""},{"n":32,"t":"\"Ey ileri gelenler! Durumum hakkında bana görüş bildirin. Sizler yanımda bulunmadıkça hiçbir işe kesin olarak karar vermem.\""},{"n":33,"t":"Dediler ki: \"Biz güçlü kimseleriz ve çetin savaşçılarız. Emir senin. Ne emredeceğini düşün.\""},{"n":34,"t":"(Kraliçe Belkıs) şöyle dedi: \"Krallar bir memlekete girdi mi, orayı harap ederler ve halkının ileri gelenlerini zelil hâle getirirler. İşte onlar böyle yaparlar.\""},{"n":35,"t":"\"Ben onlara bir hediye gönderip, elçilerin ne haber ile döneceklerine bakacağım.\""},{"n":36,"t":"(Elçilerin sözcüsü) Süleyman’ın huzuruna gelince, Süleyman ona şöyle dedi: \"Siz beni mal ile desteklemek (ve böylece etkilemek) mi istiyorsunuz? Oysa Allah’ın bana verdiği, size verdiğinden daha hayırlıdır. Fakat hediyenizle ancak siz sevinirsiniz.\""},{"n":37,"t":"\"Sen onlara dön. Andolsun, biz onlara, karşı koyamayacakları ordularla gelir ve onları oradan aşağılanmış ve küçük düşürülmüş olarak çıkarırız.\""},{"n":38,"t":"Süleyman, \"Ey ileri gelenler! Onlar bana teslim olmadan önce hanginiz bana onun (kraliçenin) tahtını getirebilir?\""},{"n":39,"t":"Cinlerden bir ifrit, \"Sen yerinden kalkmadan ben onu sana getiririm ve şüphesiz ben, buna güç yetirecek güvenilir biriyim\" dedi."},{"n":40,"t":"Kitaptan bilgisi olan biri, \"Ben onu, gözünü kapayıp açmadan önce sana getiririm\" dedi. Süleyman, tahtı yanında yerleşmiş hâlde görünce şöyle dedi: \"Bu, şükür mü, yoksa nankörlük mü edeceğim diye beni denemek için, Rabbimin bana bir lütfudur. Kim şükrederse ancak kendisi için şükretmiş olur. Kim de nankörlük ederse (bilsin ki) Rabbim her bakımdan sınırsız zengindir, cömerttir.\""},{"n":41,"t":"Süleyman, \"Tahtını tanınmaz hâle getirin. Bakalım tanıyacak mı, yoksa tanımayacaklardan mı olacak?\" dedi."},{"n":42,"t":"Belkıs gelince, \"Senin tahtın böyle mi?\" denildi. O da, \"Sanki o! Fakat zaten daha önce bize bilgi verilmişti ve biz teslimiyet göstermiştik\" dedi."},{"n":43,"t":"Daha önce Allah’tan başka taptığı şeyler ona engel olmuştu. Çünkü o inkâr eden bir kavimden idi."},{"n":44,"t":"Ona \"köşke gir\" denildi. Köşkü görünce onu (zeminini) derin bir su sandı ve eteklerini topladı. Süleyman, ona \"Bu, (zemini) billurdan döşenmiş bir köşktür\" dedi. Belkıs, \"Ey Rabbim! Şüphesiz ben nefsime zulmetmiştim. Şimdi ise Süleyman ile birlikte âlemlerin Rabbi olan Allah’a teslim oldum\" dedi."},{"n":45,"t":"Andolsun biz, \"Allah’a kulluk edin\" diye (uyarması için) Semûd kavmine, kardeşleri Salih’i peygamber olarak göndermiştik. Bir de ne görsün, onlar birbiriyle çekişen iki grup olmuşlar."},{"n":46,"t":"Salih, onlara \"Ey kavmim! Niçin iyilikten önce kötülüğün acele gelmesini istiyorsunuz? Merhamet edilmeniz için Allah’tan bağışlanma dileseniz ya!\""},{"n":47,"t":"Onlar, \"Sen ve beraberindekiler yüzünden uğursuzluğa uğradık\" dediler. Salih, \"Sizin uğursuzluğunuzun sebebi Allah katında (yazılı)dır. Aslında siz imtihan edilmekte olan bir kavimsiniz\" dedi."},{"n":48,"t":"Şehirde dokuz kişilik bir çete vardı. Bunlar yeryüzünde bozgunculuk yapıyorlar ve ıslaha çalışmıyorlardı."},{"n":49,"t":"Aralarında Allah adına and içerek şöyle dediler: \"Mutlaka onu ve ailesini geceleyin öldüreceğiz, sonra da velisine; ‘Biz onun ailesinin öldürülüşüne şahit olmadık. Biz kesinlikle doğru söyleyenleriz’, diyeceğiz.\""},{"n":50,"t":"Onlar bir tuzak kurdular. Farkında değillerken Allah da bir tuzak kurdu."},{"n":51,"t":"Bak, onların tuzaklarının sonucu nasıl oldu: Biz onları ve kavimlerini topyekûn helâk ettik."},{"n":52,"t":"İşte zulümleri yüzünden harabeye dönmüş evleri! Şüphesiz bunda bilen bir kavim için bir ibret vardır."},{"n":53,"t":"İman edip Allah’a karşı gelmekten sakınmakta olanları ise kurtardık."},{"n":54,"t":"Lût’u da (Peygamber olarak gönderdik.) Hani o, kavmine şöyle demişti: \"Göz göre göre, o çirkin işi mi yapıyorsunuz?\""},{"n":55,"t":"\"Siz kadınları bırakıp şehvetle erkeklere mi varıyorsunuz? Doğrusu siz ne yaptığını bilmez bir toplumsunuz.\""},{"n":56,"t":"Bunun üzerine kavminin cevabı ancak şöyle demek oldu: \"Lût’un ailesini memleketinizden çıkarın. Çünkü onlar temiz kalmak isteyen insanlarmış(!)\""},{"n":57,"t":"Biz de onu ve ailesini kurtardık. Ancak karısı başka. Onun geride kalıp helâk olmasını takdir ettik."},{"n":58,"t":"Onların üzerine bir yağmur (gibi taş) yağdırdık. (Başlarına gelecekler konusunda) uyarılanların yağmuru ne kötüydü!"},{"n":59,"t":"(Ey Muhammed!) De ki: \"Hamd Allah’a mahsustur. Selâm onun seçtiği kullarına.\" Allah mı daha hayırlıdır, yoksa onların ortak koştukları mı?"},{"n":60,"t":"Yahut gökleri ve yeri yaratan ve size gökten yağmur indirip, onunla, ağaçlarını sizin yetiştiremeyeceğiniz gönül alıcı güzel bahçeler meydana getiren mi? Allah ile birlikte başka ilâh mı var!? Hayır, onlar (Allah’a) eş tutan bir kavimdir."},{"n":61,"t":"Yahut yeryüzünü karar kılma yeri yapan, içinde nehirler akıtan, onun için oturaklı dağlar yapan ve iki denizin arasına bir engel koyan mı? Allah ile birlikte başka bir ilâh mı var!? Hayır, onların çoğu bilmiyor!"},{"n":62,"t":"Yahut kendisine dua ettiği zaman zorda kalmışa cevap veren ve başa gelen kötülüğü kaldıran, sizi yeryüzünün halifeleri kılan mı? Allah ile birlikte başka ilâh mı var!? Ne kadar az düşünüyorsunuz!"},{"n":63,"t":"Yahut karanın ve denizin karanlıklarında size yolunuzu gösteren ve rahmetinin önünden rüzgârları bir müjdeci olarak gönderen mi? Allah ile birlikte başka bir ilâh mı var!? Allah, onların ortak koştuklarından yücedir."},{"n":64,"t":"Yoksa, başlangıçta yaratmayı yapan, sonra onu tekrarlayan ve sizi gökten ve yerden rızıklandıran mı? Allah ile birlikte başka bir ilâh mı var!? De ki, \"Eğer doğru söyleyenler iseniz kesin delilinizi getirin.\""},{"n":65,"t":"De ki: \"Göktekiler ve yerdekiler gaybı bilemezler, ancak Allah bilir. Onlar öldükten sonra ne zaman diriltileceklerinin de farkında değildirler.\""},{"n":66,"t":"Ahiret (gününün gerçekleşeceği) hakkında bilgi (peygamberler aracılığı ile) onlara peş peşe gelmiştir. Fakat onlar bu konuda şüphe içindedirler. Daha doğrusu onlar ahiretten yana kördürler."},{"n":67,"t":"İnkâr edenler dediler ki: \"Biz ve babalarımız toprak olmuş iken mi, gerçekten bizler mi (diriltilip) çıkarılacağız?\""},{"n":68,"t":"\"Andolsun, bizler de bizden önce babalarımız da bununla tehdit edilmiştik. Bu, öncekilerin masallarından başka bir şey değildir.\""},{"n":69,"t":"De ki: \"Yeryüzünde dolaşın da suçluların sonunun nasıl olduğuna bir bakın.\""},{"n":70,"t":"Onlardan yana üzülme. Kurdukları tuzaklardan ötürü de sıkıntıya düşme."},{"n":71,"t":"Onlar, \"Eğer doğru söyleyenler iseniz, bu tehdit ne zaman gerçekleşecek?\" diyorlar."},{"n":72,"t":"De ki: \"Belki de acele gelmesini istediğiniz şeyin bir kısmı size çok yaklaşmıştır.\""},{"n":73,"t":"Şüphesiz senin Rabbin insanlara karşı lütuf sahibidir. Ancak onların çoğu şükretmezler."},{"n":74,"t":"Şüphesiz senin Rabbin, onların kalplerinin gizlediği şeyleri de, açığa çıkardıklarını da mutlaka bilir."},{"n":75,"t":"Gökte ve yerde gâib (gizli) hiçbir şey yoktur ki apaçık bir Kitap’ta (Levh-i Mahfuz’da) olmasın."},{"n":76,"t":"Şüphesiz bu Kur’an, İsrailoğullarına üzerinde ayrılığa düştükleri şeylerin çoğunu açıklıyor."},{"n":77,"t":"Şüphesiz o, elbette mü’minler için bir hidayet ve bir rahmettir."},{"n":78,"t":"Şüphesiz senin Rabbin, onların arasında hükmünü verecektir. O, mutlak güç sahibidir, hakkıyla bilendir."},{"n":79,"t":"Öyle ise Allah’a tevekkül et. Çünkü sen apaçık bir hak üzere bulunuyorsun."},{"n":80,"t":"Şüphesiz sen ölülere duyuramazsın. Arkalarına dönüp kaçarlarken sağırlara da çağrıyı duyuramazsın."},{"n":81,"t":"Körleri sapıklıklarından vazgeçirip doğru yola getiremezsin. Ancak âyetlerimize inanıp da müslüman olmuş olanlara duyurabilirsin."},{"n":82,"t":"(Kıyametin kopacağına dair) o söz başlarına gelince, onlar için yerden kendilerine bir dâbbe (canlı bir yaratık) çıkarırız. O, onlara insanların âyetlerimize kesin olarak inanmadıklarını söyler."},{"n":83,"t":"Her ümmetten âyetlerimizi yalanlayanlarından bir grubu toplayacağımız ve bunların (topluca hesap yerine) sevk edilecekleri günü hatırla."},{"n":84,"t":"Hesap yerine geldiklerinde Allah şöyle der: \"Siz benim âyetlerimi, onları ilmen kavramamışken yalanladınız öyle mi? Yoksa ne yapıyordunuz ki?!\""},{"n":85,"t":"Zulümlerinden dolayı sözü edilen azap tepelerine iner de artık konuşamazlar."},{"n":86,"t":"Onlar görmüyorlar mı ki, biz geceyi içinde rahat etsinler diye, gündüzü de (her şeyi) gösterici (aydınlık) olarak yarattık. Şüphesiz bunda inanan bir toplum için elbette (Allah varlığını gösteren) deliller vardır."},{"n":87,"t":"Sûr’a üfürüleceği ve Allah’ın dilediği kimselerden başka göklerdeki herkesin, yerdeki herkesin korkuya kapılacağı günü hatırla. Hepsi de boyunlarını bükerek O’na gelirler."},{"n":88,"t":"Dağları görürsün, onları hareketsiz sanırsın. Hâlbuki onlar bulutların geçişi gibi hareket ederler. Bunu, her şeyi sağlam ve yerli yerince yapan Allah yapmıştır. Şüphesiz O, yaptıklarınızdan hakkıyla haberdardır."},{"n":89,"t":"Her kim iyi amel getirirse, ona ondan daha hayırlısı vardır. Onlar o gün korkudan emindirler."},{"n":90,"t":"Kimler de kötü amel getirirse, yüzüstü ateşe atılırlar. (Onlara), \"Ancak yaptıklarınızın karşılığını görüyorsunuz\" (denir.)"},{"n":"91-92","t":"De ki: \"Bana ancak, bu beldenin (Mekke’nin); onu mukaddes kılan ve her şey kendisine ait olan Rabbine kulluk yapmam emredildi. Yine bana, müslümanlardan olmam ve Kur’an’ı okumam emredildi.\" Artık kim doğru yola girerse yalnız kendisi için girer. Kim de doğru yoldan saparsa, de ki: \"Ben ancak uyarıcılardanım.\""},{"n":93,"t":"De ki: \"Hamd Allah’a mahsustur. O, âyetlerini size gösterecek ve siz de onları tanıyacaksınız. Rabbin, yaptıklarınızdan habersiz değildir.\""}],[{"n":1,"t":"Tâ-Sîn-Mîm."},{"n":2,"t":"Bunlar apaçık Kitab’ın âyetleridir."},{"n":3,"t":"İman eden bir kavm için Mûsâ ile Firavun’un haberlerinden bir kısmını sana gerçek olarak anlatacağız."},{"n":4,"t":"Şüphe yok ki, Firavun yeryüzünde (ülkesinde) büyüklük taslamış ve ora halkını sınıflara ayırmıştı. Onlardan bir kesimi eziyor, oğullarını boğazlıyor, kadınlarını ise sağ bırakıyordu. Şüphesiz o, bozgunculardandı."},{"n":5,"t":"Biz ise, istiyorduk ki yeryüzünde ezilmekte olanlara lütufta bulunalım, onları önderler yapalım ve onları varisler kılalım."},{"n":6,"t":"Yeryüzünde onları kudret sahibi kılalım ve onların eliyle Firavun’a, Hâmân’a ve ordularına, çekinegeldikleri şeyleri gösterelim."},{"n":7,"t":"Mûsâ’nın annesine, \"Onu emzir, başına bir şey gelmesinden korktuğun zaman onu denize (Nil’e) bırak, korkma, üzülme. Çünkü biz onu sana döndüreceğiz ve onu peygamberlerden kılacağız\" diye ilham ettik."},{"n":8,"t":"Nihayet Firavun ailesi kendilerine düşman ve üzüntü kaynağı olacak olan o çocuğu bulup aldı. Şüphesiz Firavun, (veziri) Hâmân ve onların askerleri hata yapıyorlardı."},{"n":9,"t":"Firavun’un karısı şöyle dedi: \"Bana da, sana da göz aydınlığı (bir çocuk)! Sakın onu öldürmeyin. Belki bize faydası dokunur, ya da onu evlat ediniriz.\" Oysaki onlar (olacak şeylerin) farkında değillerdi."},{"n":10,"t":"Mûsâ’nın anasının kalbi bomboş kaldı. Eğer biz (çocuğu ile ilgili sözümüze) inancını koruması için kalbine güç vermeseydik, neredeyse bunu açıklayacaktı."},{"n":11,"t":"Annesi, Mûsâ’nın kız kardeşine, \"Onu takip et\" dedi. O da Mûsâ’yı, onlar farkına varmadan uzaktan gözledi."},{"n":12,"t":"Biz, daha önce onun, süt analarının sütünü emmemesini sağladık. Kız kardeşi, \"Size onun bakımını, sizin adınıza üstlenecek ve ona içtenlik ve şefkatle davranacak bir aile göstereyim mi?\" dedi."},{"n":13,"t":"Böylece biz, anasının gözü aydın olsun ve üzülmesin, Allah’ın va’dinin hak olduğunu bilsin diye onu anasına geri döndürdük. Fakat onların pek çoğu bunu bilmezler."},{"n":14,"t":"Mûsâ, olgunluk çağına ulaşıp gelişimini tamamlayınca, biz ona ilim ve hikmet verdik. Biz, iyilik edenleri böyle mükâfatlandırırız."},{"n":15,"t":"Mûsâ, halkın habersiz olduğu bir sırada şehre girdi. Orada biri kendi tarafından, diğeri düşmanı tarafından; kavga eden iki adam gördü. Kendi tarafından olan, düşmanına karşı ondan yardım istedi. Mûsâ da ona bir yumruk indirip onu öldürdü. Mûsâ, \"Bu şeytanın işidir. O, gerçekten apaçık bir saptırıcı düşmandır\" dedi."},{"n":16,"t":"Mûsâ, \"Rabbim! Şüphesiz ben nefsime zulmettim. Beni affet\" dedi. Allah da onu affetti. Şüphesiz O, çok bağışlayandır, çok merhamet edendir."},{"n":17,"t":"\"Rabbim! Bana verdiğin nimetle asla suçlulara arka çıkmayacağım\" dedi."},{"n":18,"t":"Korkarak, etrafı gözetleyerek şehirde sabahladı. Bir de ne görsün, dün kendisinden yardım isteyen yine feryat ederek ondan yardım istiyordu. Mûsâ da ona, \"Belli ki sen azgın bir kimsesin\" dedi."},{"n":19,"t":"Mûsâ, ikisinin de düşmanı olan adamı yakalamak isteyince adam, \"Ey Mûsâ! Dün birini öldürdüğün gibi, beni de öldürmek mi istiyorsun. Sen ancak yeryüzünde bir zorba olmak istiyorsun, arabuluculardan olmak istemiyorsun\" dedi."},{"n":20,"t":"Şehrin öbür ucundan koşarak bir adam geldi. \"Ey Mûsâ! İleri gelenler seni öldürmek için aralarında senin durumunu görüşüyorlar. Şehirden hemen çık. Şüphesiz ben sana öğüt verenlerdenim\" dedi."},{"n":21,"t":"Mûsâ, korku içinde etrafı gözetleyerek şehirden çıktı ve \"Ey Rabbim! Beni bu zalim kavimden kurtar\" dedi."},{"n":22,"t":"(Şehirden çıkıp) Medyen’e doğru yöneldiğinde, \"Umarım Rabbim beni doğru yola iletir\" dedi."},{"n":23,"t":"Medyen suyuna varınca, suyun başında (hayvanlarını) sulamakta olan bazı insanlar gördü. Bunların yanında da koyunlarını suya salmamak için uğraşan iki kız gördü. Mûsâ onlara, \"(Koyunlarınızı burada tutmaktaki) maksadınız ne?\" dedi. Onlar, \"Çobanlar sulayıp çekilinceye kadar biz koyunlarımızı sulayamayız. Babamız ise çok yaşlı bir adamdır\" dediler."},{"n":24,"t":"Bunun üzerine Mûsâ onların koyunlarını suladı. Sonra gölgeye çekilip, \"Rabbim! Bana göndereceğin her hayra muhtacım\" dedi."},{"n":25,"t":"Nihayet kızlardan biri utana utana yürüyerek ona gelip, \"Bizim için koyunlarımızı sulamanın ücretini vermek üzere babam seni çağırıyor\" dedi. Mûsâ, onun (Şu’ayb’ın) yanına gelip başından geçenleri ona anlatınca Şu’ayb, \"Korkma, o zalim kavimden kurtuldun\" dedi."},{"n":26,"t":"Kızlardan biri, \"Babacığım, onu ücretle tut. Herhâlde ücretle tuttuklarının en hayırlısı, güçlü ve güvenilir olan bu adam olacaktır\" dedi."},{"n":27,"t":"Şu’ayb, \"Ben, sekiz yıl bana çalışmana karşılık, şu iki kızımdan birisini sana nikâhlamak istiyorum. Eğer sen bunu on yıla tamamlarsan, o da senden olur. Ben seni zora koşmak da istemiyorum. İnşaallah beni salih kimselerden bulacaksın\" dedi."},{"n":28,"t":"Mûsâ, şöyle dedi: \"Bu, seninle benim aramda bir iş. İki süreden hangisini tamamlarsam bana bir husûmet yok. Allah, söylediklerimize vekildir.\""},{"n":29,"t":"Mûsâ, süreyi tamamlayıp ailesiyle yola çıkınca, Tûr tarafında bir ateş görmüş ve ailesine, \"Siz burada kalın, ben bir ateş gördüm, (oraya gidiyorum). Umarım oradan size bir haber ya da ısınmanız için ateşten bir kor getiririm\" dedi."},{"n":30,"t":"Mûsâ, ateşin yanına gelince, o mübarek yerdeki vadinin sağ tarafındaki ağaçtan şöyle seslenildi: \"Ey Mûsâ! Şüphesiz ben, evet, ben âlemlerin Rabbi olan Allah’ım.\""},{"n":31,"t":"\"Değneğini (yere) at.\" (Mûsâ, değneğini attı). Onu bir yılanmış gibi süratle hareket eder görünce, arkasına bakmadan dönüp kaçtı. (Bu sefer şöyle seslenildi:) \"Ey Mûsâ! Beri gel, korkma. Çünkü sen güvenlikte olanlardansın.\""},{"n":32,"t":"\"Elini koynuna sok. (Alaca hastalığı gibi) bir hastalık sebebiyle olmaksızın bembeyaz bir hâlde çıksın. Korkudan açılan kolunu kendine çek (toparlan). İşte bunlar, Firavun ve ileri gelen adamlarına (göstermen için) Rabbin tarafından (sana verilen) iki delildir. Çünkü onlar fasık bir kavimdirler.\""},{"n":33,"t":"Mûsâ, şöyle dedi: \"Ey Rabbim! Şüphesiz ben onlardan birisini öldürdüm. Onların da beni öldürmelerinden korkuyorum.\""},{"n":34,"t":"\"Kardeşim Hârûn’un dili benimkinden daha düzgündür. Onu da benimle birlikte, beni doğrulayan bir yardımcı olarak gönder. Çünkü ben, onların beni yalanlamalarından korkuyorum.\""},{"n":35,"t":"Allah, \"Seni kardeşinle destekleyeceğiz ve size bir iktidar vereceğiz de âyetlerimiz sayesinde size (kötü bir amaçla) ulaşamayacaklar. Siz ve size uyanlar, galip gelecek olanlardır\" dedi."},{"n":36,"t":"Mûsâ, onlara delillerimizi apaçık olarak getirince onlar, \"Bu, ancak uydurulmuş bir sihirdir. Biz geçmiş atalarımızın zamanında böyle bir şeyin varlığını duymadık\" dediler."},{"n":37,"t":"Mûsâ, \"Katından kimin hidayet getirdiğini ve bu yurdun (güzel) sonucunun kimin olacağını Rabbim daha iyi bilir. Doğrusu zalimler kurtuluşa eremezler\" dedi."},{"n":38,"t":"Firavun, \"Ey ileri gelenler! Sizin benden başka bir ilâhınız olduğunu bilmiyorum. Ey Hâmân! Benim için bir ateş yakıp tuğla pişir de bana bir kule yap! Belki Mûsâ’nın ilâhına çıkar bakarım(!) Şüphesiz ben onun mutlaka yalancılardan olduğunu sanıyorum\" dedi."},{"n":39,"t":"O ve askerleri yeryüzünde haksız yere büyüklük tasladılar ve gerçekten bize döndürülmeyeceklerini sandılar."},{"n":40,"t":"Biz de onu ve askerlerini yakaladık ve onları denize attık (Orada boğuldular). Zalimlerin sonunun nasıl olduğuna bak!"},{"n":41,"t":"Biz onları, ateşe çağıran öncüler kıldık. Kıyamet günü de kendilerine yardım edilmeyecektir."},{"n":42,"t":"Bu dünyada onları lânete uğrattık. Kıyamet gününde de onlar iğrenç kılınmış kimselerden olacaklardır."},{"n":43,"t":"Andolsun, ilk nesilleri yok ettikten sonra Mûsâ’ya -düşünüp ibret alsınlar diye- insanların kalp gözünü açan deliller ve bir hidayet rehberi, bir rahmet olarak Kitab’ı (Tevrat’ı) verdik."},{"n":44,"t":"(Ey Muhammed!) Mûsâ’ya o emri verdiğimiz zaman sen (vadinin) batı tarafında değildin. (O olayı) görenlerden de değildin."},{"n":45,"t":"Fakat biz (Mûsâ’dan sonra) birçok nesiller meydana getirdik. Üzerlerinden uzun çağlar geçti. Sen Medyen halkı arasında yaşıyor değildin, âyetlerimizi onlardan okuyup öğreniyor da değildin. Fakat biz (bu haberi) göndereniz."},{"n":46,"t":"Yine biz (Mûsâ’ya) seslendiğimiz zaman Tûr’un yan tarafında da değildin. Fakat Rabbinden bir rahmet olarak, senden önce kendilerine hiçbir uyarıcı gelmeyen bir kavmi, düşünüp öğüt alsınlar diye uyarman için (o haberleri) sana bildiriyoruz."},{"n":47,"t":"Kendi yaptıkları sebebiyle başlarına bir musibet gelip de, \"Ey Rabbimiz! Bize bir Peygamber gönderseydin de âyetlerine uysaydık ve mü’minlerden olsaydık\" diyecek olmasalardı, seni peygamber olarak göndermezdik."},{"n":48,"t":"Onlara katımızdan gerçek gelince, \"Mûsâ’ya verilen (mucize)lerin benzeri niçin buna da verilmedi\" dediler. Onlar daha önce Mûsâ’ya verilen (mucize)leri inkâr etmemişler miydi? Onlar, \"İki sihirbaz birbirlerine destek oluyor\" dediler. \"Biz hepsini inkâr ediyoruz\" dediler."},{"n":49,"t":"De ki: \"Eğer doğru söyleyenler iseniz, Allah katından, doğruya bu ikisinden (Tevrat ve Kur’an’dan) daha çok ulaştıran bir kitap getirin de, ben ona uyayım.\""},{"n":50,"t":"Eğer (bu konuda) sana cevap veremezlerse, bil ki onlar sadece kendi nefislerinin arzularına uymaktadırlar. Kim, Allah’tan bir yol gösterme olmaksızın kendi nefsinin arzusuna uyandan daha sapıktır. Şüphesiz Allah, zalimler toplumunu doğruya iletmez."},{"n":51,"t":"Andolsun, düşünüp öğüt alsınlar diye o sözü (Kur’an âyetlerini) onlara peş peşe ulaştırdık."},{"n":52,"t":"Bu Kur’an’dan önce kendilerine kitap verdiklerimiz var ya, işte onlar ona da inanırlar."},{"n":53,"t":"Kur’an kendilerine okunduğu zaman, \"Ona inandık, şüphesiz o Rabbimizden gelen gerçektir. Şüphesiz biz ondan önce de müslümandık\" derler."},{"n":54,"t":"İşte onların, sabredip kötülüğü iyilikle savmaları ve kendilerine rızık olarak verdiklerimizden Allah yolunda harcamaları karşılığında, mükâfatları kendilerine iki kez verilecektir."},{"n":55,"t":"Boş sözü işittikleri vakit ondan yüz çevirirler ve, \"Bizim işlerimiz bize, sizin işleriniz de size. Selâm olsun size (bizden size zarar gelmez). Biz cahilleri istemeyiz\" derler."},{"n":56,"t":"Şüphesiz sen sevdiğin kimseyi doğru yola iletemezsin. Fakat Allah, dilediği kimseyi doğru yola eriştirir. O, doğru yola gelecekleri daha iyi bilir."},{"n":57,"t":"Onlar, \"Sizinle beraber doğru yolu tutarsak, kendi yurdumuzdan koparılıp çıkarılırız\" dediler. Biz onları tarafımızdan bir rızık olarak, her türlü meyve ve mahsullerin kendisinde toplandığı, saygın ve güvenlikli bir yere yerleştirmedik mi? Fakat onların çoğu bilmezler."},{"n":58,"t":"Biz nimetler içinde şımaran nice memleket halkını helâk etmişizdir. İşte kendilerinden sonra içlerinde pek az oturulmuş yurtları! (O yurtlara) biz varis olduk, biz."},{"n":59,"t":"Rabbin, ülkelerin merkezî yerlerine, kendilerine âyetlerimizi okuyan bir peygamber göndermedikçe oraları helâk edici değildir. Zaten biz, halkları zalim olmadıkça memleketleri helâk etmeyiz."},{"n":60,"t":"(Dünyalık olarak) size verilen her şey, dünya hayatının geçimliği ve süsüdür. Allah’ın katındaki ise daha hayırlı ve daha kalıcıdır. Hâlâ aklınızı kullanmıyor musunuz?"},{"n":61,"t":"Kendisine güzel bir vaadde bulunduğumuz ve o vaad edilen şeye kavuşacak olan kimse, dünya hayatının geçimliklerinden yararlandırdığımız, sonra da kıyamet günü (hesaba çekilmek için) huzura getirilecek kimse gibi midir?"},{"n":62,"t":"Allah’ın onlara seslenerek, \"Hani benim, var olduğunu iddia ettiğiniz ortaklarım?\" diyeceği günü hatırla!"},{"n":63,"t":"Haklarında azap hükmü gerçekleşenler, \"Ey Rabbimiz! İşte şunlar bizim azdırdıklarımızdır. Kendimiz azdığımız gibi onları da azdırdık. Şimdi de onlardan uzaklaşıp sana döndük. Zaten (gerçekte) onlar bize tapmıyorlardı\" diyeceklerdir."},{"n":64,"t":"Onlara, \"Haydi ortaklarınızı çağırın!\" denir. Onlar da çağırırlar fakat ortakları onlara cevap veremez. Azabı görürler. Keşke onlar (dünyada iken) doğru yola gelselerdi."},{"n":65,"t":"Allah’ın onlara seslenerek, \"Peygamberlere ne cevap verdiniz? diyeceği günü hatırla.\""},{"n":66,"t":"O gün onlara karşı bütün haberler kapanmıştır. Artık birbirlerine de soramazlar."},{"n":67,"t":"Ama tövbe edip iman eden ve salih amel işleyen kimsenin kurtuluşa erenlerden olması umulur."},{"n":68,"t":"Rabbin, dilediğini yaratır ve seçer. Onların ise seçim hakkı yoktur. Allah, onların ortak koştuklarından uzaktır ve yücedir."},{"n":69,"t":"Rabbin, onların sinelerinin gizlediğini de açığa vurduklarını da bilir."},{"n":70,"t":"O, Allah’tır. O’ndan başka hiçbir ilâh yoktur. Dünyada da ahirette de hamd O’na mahsustur. Hüküm yalnızca O’nundur. Kesinlikle O’na döndürüleceksiniz."},{"n":71,"t":"De ki: \"Ne dersiniz? Allah, üzerinize geceyi kıyamete kadar sürekli kılsaydı, Allah’tan başka hangi ilâh size bir aydınlık getirir? Hâlâ duymayacak mısınız?\""},{"n":72,"t":"De ki: \"Ne dersiniz? Allah, üzerinize gündüzü kıyamete kadar sürekli kılsaydı, Allah’tan başka hangi ilâh size içinde dinleneceğiniz bir gece getirebilir? Hâlâ görmeyecek misiniz?\""},{"n":73,"t":"Allah, rahmetinden ötürü geceyi içinde dinlenesiniz; gündüzü de, lütfundan isteyesiniz ve şükredesiniz diye sizin için yarattı."},{"n":74,"t":"Allah’ın, onlara seslenerek, \"Hani benim, var olduğunu iddia ettiğiniz ortaklarım\"? diyeceği günü hatırla."},{"n":75,"t":"Her ümmetten bir şahit çıkarırız ve (kâfirlere), \"Kesin delilinizi getirin\" deriz. Onlar da gerçeğin Allah’a ait olduğunu bilirler ve (Allah’a ortak diye) uydurdukları şeyler kendilerini yüzüstü bırakıp kaybolup gitmişlerdir."},{"n":76,"t":"Şüphesiz Kârûn, Mûsâ’nın kavmindendi. Onlara karşı azgınlık etti. Biz ona, anahtarlarını (bile taşımak) güçlü bir topluluğa ağır gelecek hazineler verdik. Hani, kavmi kendisine şöyle demişti: \"Böbürlenme! Çünkü Allah, böbürlenip şımaranları sevmez.\""},{"n":77,"t":"\"Allah’ın sana verdiği şeylerde ahiret yurdunu ara. Dünyadan da nasibini unutma. Allah’ın sana iyilik yaptığı gibi sen de iyilik yap ve yeryüzünde bozgunculuk isteme. Çünkü Allah, bozguncuları sevmez.\""},{"n":78,"t":"Kârûn, \"Bunlar bana bendeki bilgi ve beceriden dolayı verilmiştir\" dedi. O, Allah’ın kendinden önceki nesillerden, ondan daha kuvvetli ve daha çok mal biriktirmiş kimseleri helâk etmiş olduğunu bilmiyor muydu? Suçlulukları kesinleşmiş olanlara günahları konusunda soru sorulmaz (Çünkü Allah hepsini bilir)."},{"n":79,"t":"Kârûn, zineti ve görkemi içerisinde kavminin karşısına çıktı. Dünya hayatını arzu edenler, \"Keşke Kârûn’a verilen (servet) gibi bizim de (servetimiz) olsaydı. Şüphesiz o büyük bir servet sahibidir\" dediler."},{"n":80,"t":"Kendilerine ilim verilmiş olanlar ise, \"Yazıklar olsun size! İman edip de iyi işler yapanlara Allah’ın vereceği mükâfat daha hayırlıdır. Ona da ancak sabredenler kavuşturulur\" dediler."},{"n":81,"t":"Sonunda onu da, sarayını da yerin dibine batırdık. Allah’a karşı ona yardım edebilecek adamları da yoktu. Kendisini savunup kurtarabileceklerden de değildi!"},{"n":82,"t":"Daha dün onun yerinde olmayı arzu edenler, \"Vay! Demek ki Allah, kullarından dilediği kimselere rızkı bol verir ve (dilediğine) kısarmış. Allah, bize lütfetmiş olmasaydı, bizi de yerin dibine geçirirdi. Demek ki kâfirler iflah olmayacak\" demeye başladılar."},{"n":83,"t":"İşte ahiret yurdu. Biz, onu yeryüzünde büyüklük taslamayan ve bozgunculuk çıkarmayanlara has kılarız. Sonuç, Allah’a karşı gelmekten sakınanlarındır."},{"n":84,"t":"Kim bir iyilik getirirse, ona bundan daha hayırlısı vardır. Kim de bir kötülük getirirse, bilsin ki, kötülük işleyenler ancak yapmakta olduklarının cezasına çarptırılırlar."},{"n":85,"t":"Kur’an’ı sana farz kılan Allah, şüphesiz seni dönülecek bir yere döndürecektir. De ki: \"Rabbim hidayetle geleni ve apaçık bir sapıklık içinde olanı daha iyi bilir.\""},{"n":86,"t":"Sen, bu kitabın sana verileceğini ummuyordun. Ancak o, Rabbinden bir rahmet olarak sana verildi. Öyle ise kâfirlere sakın arka çıkma."},{"n":87,"t":"Allah’ın âyetleri sana indirildikten sonra, sakın seni onlardan çevirmesinler. Rabbine çağır ve sakın Allah’a ortak koşanlardan olma!"},{"n":88,"t":"Sen Allah ile beraber başka bir ilâha ibadet etme. O’ndan başka hiçbir ilâh yoktur. O’nun zatından başka her şey yok olacaktır. Hüküm yalnızca O’nundur ve kesinlikle O’na döndürüleceksiniz."}],[{"n":1,"t":"Elif Lâm Mîm."},{"n":2,"t":"İnsanlar, \"İnandık\" demekle imtihan edilmeden bırakılacaklarını mı zannederler."},{"n":3,"t":"Andolsun, biz onlardan öncekileri de imtihan etmiştik. Allah, doğru söyleyenleri de mutlaka bilir, yalancıları da mutlaka bilir."},{"n":4,"t":"Yoksa kötülük yapanlar, bizden kaçıp kurtulacaklarını mı sandılar. Ne kötü hükmediyorlar!"},{"n":5,"t":"Her kim Allah’a kavuşmayı umarsa, bilsin ki Allah’ın tayin ettiği o vakit elbette gelecektir. O, hakkıyla işitendir, hakkıyla bilendir."},{"n":6,"t":"Her kim cihad ederse, ancak kendisi için cihad etmiş olur. Şüphesiz Allah, âlemlere muhtaç değildir."},{"n":7,"t":"İman edip salih amel işleyenlerin kötülüklerini elbette örteceğiz. Onları işlediklerinin daha güzeliyle mükâfatlandıracağız."},{"n":8,"t":"Biz, insana, ana babasına iyilik etmesini emrettik. Şâyet onlar seni, hakkında hiçbir bilgin olmayan şeyi bana ortak koşman için zorlarlarsa, bu takdirde onlara itaat etme. Dönüşünüz ancak bana olacaktır ve ben yapmakta olduklarınızı size haber vereceğim."},{"n":9,"t":"İman edip de salih amel işleyenler var ya, biz onları mutlaka salihler (iyiler) arasına sokacağız."},{"n":10,"t":"İnsanlardan öyleleri vardır ki, \"Allah’a inandık\" derler. Ama Allah uğrunda bir ezaya uğratılınca, insanlardan gördükleri baskı ve işkenceyi Allah’ın azabı gibi tutar. Andolsun, Rabbinden bir yardım gelecek olsa mutlaka, \"Biz de sizinle beraberdik\" derler. Allah, herkesin kalbinde olanı en iyi bilen değil midir?"},{"n":11,"t":"Allah, elbette kendisine iman edenleri de bilir ve elbette münafıkları da bilir."},{"n":12,"t":"İnkâr edenler iman edenlere, \"Yolumuza uyun da sizin günahlarınızı yüklenelim\" derler. Hâlbuki onların günahlarından hiçbir şey yüklenecek değillerdir. Şüphesiz onlar kesinlikle yalancılardır."},{"n":13,"t":"Andolsun, onlar mutlaka kendi yüklerini ve kendi yükleriyle beraber nice ağır yükleri yükleneceklerdir. Uydurmakta oldukları şeylerden de kıyamet günü şüphesiz, sorguya çekileceklerdir."},{"n":14,"t":"Andolsun, biz, Nûh’u kendi kavmine peygamber olarak gönderdik. O da dokuz yüz elli yıl onların arasında kaldı. Neticede onlar zulümlerini sürdürürlerken tûfan kendilerini yakalayıverdi."},{"n":15,"t":"Biz de onu (Nûh’u) ve gemide bulunanları kurtardık ve bunu âlemlere bir ibret kıldık."},{"n":16,"t":"İbrahim’i de peygamber olarak gönderdik. Hani o, kavmine şöyle demişti: \"Allah’a kulluk edin, O’na karşı gelmekten sakının. Eğer bilirseniz, bu sizin için daha hayırlıdır.\""},{"n":17,"t":"\"Siz, Allah’ı bırakarak ancak putlara tapıyorsunuz ve yalan uyduruyorsunuz. Allah’ı bırakarak taptıklarınızın size hiçbir rızık vermeye güçleri yetmez. Öyle ise rızkı Allah’ın katında arayın. O’na kulluk edin ve O’na şükredin. Siz yalnız O’na döndürüleceksiniz.\""},{"n":18,"t":"\"Eğer siz yalanlarsanız bilin ki, sizden önce geçen birtakım ümmetler de yalanlamışlardı. Peygambere düşen apaçık tebliğden başka bir şey değildir.\""},{"n":19,"t":"Onlar, Allah’ın başlangıçta yaratmayı nasıl yaptığını, sonra onu nasıl tekrarladığını görmüyorlar mı? Şüphesiz bu, Allah’a göre kolaydır."},{"n":20,"t":"De ki: \"Yeryüzünde dolaşın da Allah’ın başlangıçta yaratmayı nasıl yaptığına bakın. Sonra Allah (aynı şekilde) sonraki yaratmayı da yapacaktır. (Kıyametten sonra her şeyi tekrar yaratacaktır) Şüphesiz Allah’ın gücü her şeye hakkıyla yeter.\""},{"n":21,"t":"O, dilediğine azap eder, dilediğine de merhamet eder. Ancak O’na döndürüleceksiniz."},{"n":22,"t":"Siz, yerde de gökte de (Allah’ı) âciz bırakacak değilsiniz. Sizin Allah’tan başka ne bir dostunuz, ne de bir yardımcınız vardır."},{"n":23,"t":"Allah’ın âyetlerini ve O’na kavuşmayı inkâr edenler var ya; işte onlar benim rahmetimden ümit kesmişlerdir. İşte onlar için elem dolu bir azap vardır."},{"n":24,"t":"(İbrahim’in) kavminin cevabı, \"Onu öldürün veya yakın\" demekten ibaret oldu. Allah da onu ateşten kurtardı. Şüphesiz bunda inanan bir toplum için ibretler vardır."},{"n":25,"t":"İbrahim, onlara dedi ki: \"Sırf aranızda dünya hayatına mahsus bir sevgi (ve çıkar) uğruna Allah’ı bırakıp birtakım putlar edindiniz. Sonra kıyamet gününde kiminiz kiminizi inkâr edip tanımayacak; kiminiz kiminize lânet edecektir. Barınağınız cehennem olacaktır. Yardımcılarınız da olmayacaktır.\""},{"n":26,"t":"Bunun üzerine Lût, ona (İbrahim’e) iman etti. İbrahim, \"Ben, Rabbime (gitmemi emrettiği yere) hicret edeceğim. Şüphesiz O, mutlak güç sahibidir, hüküm ve hikmet sahibidir\" dedi."},{"n":27,"t":"Ona (İbrahim’e) İshak’ı ve Yakub’u bahşettik. Onun soyundan gelenlere peygamberlik ve kitab verdik. Ayrıca ona dünyada mükâfatını da verdik. Şüphesiz o, ahirette de salih kimselerdendir."},{"n":28,"t":"Lût’u da peygamber olarak gönderdik. Hani o, kavmine şöyle demişti: \"Gerçekten siz, sizden önce dünyada hiçbir toplumun yapmadığı bir hayâsızlığı işliyorsunuz.\""},{"n":29,"t":"\"Siz hâlâ erkeklere yanaşacak, yol kesecek ve toplantılarınızda edepsizlik yapacak mısınız?\" Kavminin cevabı, \"Eğer doğru söyleyenlerden isen, haydi Allah’ın azabını getir bize\" demeden ibaret oldu."},{"n":30,"t":"(Lût) \"Ey Rabbim! Şu bozguncu kavme karşı bana yardım et\" dedi."},{"n":31,"t":"Elçilerimiz (melekler) İbrahim’e müjdeyi getirdiklerinde, \"Biz, bu memleket halkını helâk edeceğiz, çünkü oranın ahalisi zalim kimselerdir\" dediler."},{"n":32,"t":"İbrahim, \"Ama orada Lût var\" dedi. Onlar, \"Orada kimin bulunduğunu biz daha iyi biliriz. Biz, onu ve ailesini elbette kurtaracağız. Ancak karısı başka. O, geri kalıp helâk edilenlerden olacaktır.\""},{"n":33,"t":"Elçilerimiz Lût’a geldiklerinde, Lût, onlar yüzünden tasalandı, onlar hakkında çaresizlik içine düştü. Elçiler ona, \"Korkma, üzülme. Biz, seni ve aileni kurtaracağız. Ancak karın başka. O, geride kalıp helâk edilenlerden olacaktır.\""},{"n":34,"t":"Şüphesiz biz, bu memleket halkı üzerine, fasıklık ettiklerinden dolayı gökten bir azap indireceğiz."},{"n":35,"t":"Andolsun biz, aklını kullanacak bir kavm için o memleketten ibret alınacak apaçık bir delil bıraktık."},{"n":36,"t":"Medyen’e de kardeşleri Şu’ayb’ı peygamber olarak gönderdik. Şu’ayb, \"Ey kavmim! Allah’a kulluk edin. Ahiret gününe ümit besleyin ve yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın\" dedi."},{"n":37,"t":"Kavmi, onu yalanladı. Bunun üzerine kendilerini o malum sarsıntı yakaladı da yurtlarında diz üstü çökekaldılar."},{"n":38,"t":"Âd ve Semûd kavimlerini de helâk ettik. Bu, onların (harap olmuş) yurtlarından size besbelli olmuştur. Şeytan, onlara işlerini süslemiş ve onları doğru yoldan alıkoymuştur. Hâlbuki onlar gözü açık kimselerdi."},{"n":39,"t":"Kârûn’u, Firavun’u ve Hâmân’ı da helâk ettik. Andolsun, Mûsâ kendilerine apaçık mucizeler getirmişti de yeryüzünde büyüklük taslamışlardı. Oysa bizi geçip (azabımızdan) kurtulamazlardı."},{"n":40,"t":"Bunların her birini kendi günahları yüzünden yakaladık. Onlardan taş yağmuruna tuttuklarımız var. Onlardan o korkunç sesin yakaladığı kimseler var. Onlardan yerin dibine geçirdiklerimiz var. Onlardan suda boğduklarımız var. Allah, onlara zulmediyor değildi, fakat onlar kendilerine zulmediyorlardı."},{"n":41,"t":"Allah’tan başkalarını dost edinenlerin durumu, kendine bir ev edinen örümceğin durumu gibidir. Evlerin en dayanıksızı ise şüphesiz örümcek evidir. Keşke bilselerdi!"},{"n":42,"t":"Şüphesiz Allah, onların, kendini bırakıp da başka ne tür şeylere taptıklarını biliyor. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":43,"t":"İşte bu temsilleri biz insanlar için getiriyoruz. Onları ancak bilginler düşünüp anlarlar."},{"n":44,"t":"Allah, gökleri ve yeri hak ve hikmete uygun olarak yaratmıştır. İşte bunda inananlar için bir ibret vardır."},{"n":45,"t":"(Ey Muhammed!) Kitaptan sana vahyolunanı oku, namazı da dosdoğru kıl. Çünkü namaz, insanı hayâsızlıktan ve kötülükten alıkor. Allah’ı anmak (olan namaz) elbette en büyük ibadettir. Allah, yaptıklarınızı biliyor."},{"n":46,"t":"İçlerinden zulmedenler hariç, Kitap ehli ile ancak en güzel bir yolla mücadele edin ve (onlara) şöyle deyin: \"Biz, bize indirilene de, size indirilene de inandık. Bizim ilâhımız ve sizin ilâhınız birdir (aynı ilâhtır). Biz sadece O’na teslim olmuş kimseleriz.\""},{"n":47,"t":"İşte böylece biz sana kitabı indirdik. Kendilerine kitap verdiklerimiz ona inanırlar. Şunlar (Kitap ehlinden çağdaşın olanlar)dan da ona inananlar vardır. Bizim âyetlerimizi ancak kâfirler inkâr ederler."},{"n":48,"t":"Sen şu Kur’an’dan önce hiçbir kitap okumuyor ve onu sağ elinle yazmıyordun. (Okuyup yazsaydın) o takdirde batıl peşinde koşanlar, şüpheye düşerlerdi."},{"n":49,"t":"Hayır, o, kendilerine ilim verilenlerin kalplerindeki apaçık âyetlerdir. Bizim âyetlerimizi ancak zalimler inkâr eder."},{"n":50,"t":"Dediler ki: \"Ona Rabbinden mucizeler indirilseydi ya!\" De ki: \"Mucizeler ancak Allah katındadır ve ben ancak apaçık bir uyarıcıyım.\""},{"n":51,"t":"Kendilerine okunan kitabı sana indirmiş olmamız onlara yetmedi mi? Şüphesiz bunda inanan bir kavim için bir rahmet ve bir öğüt vardır."},{"n":52,"t":"De ki: \"Benimle sizin aranızda şahit olarak Allah yeter. O, göklerde ve yerde olanları bilir. Batıla inanıp Allah’ı inkâr edenler var ya; işte onlar asıl ziyana uğrayanlardır.\""},{"n":53,"t":"Senden azabın çabucak gelmesini istiyorlar. (Hikmet gereği) belirlenmiş bir süre olmasaydı, azap onlara mutlaka gelirdi. Onlar farkında değillerken kendilerine ansızın elbette gelecektir."},{"n":"54-55","t":"Senden azabın çabucak gelmesini istiyorlar. Oysa azap kâfirleri üstlerinden ve ayaklarının altından bürüyeceği gün, şüphesiz cehennem onları mutlaka kuşatmış olacaktır. Allah, onlara, \"Yapmakta olduklarınızın cezasını tadın\" diyecektir."},{"n":56,"t":"Ey iman eden kullarım! Şüphesiz ki benim arzım (yeryüzü) geniştir. O hâlde, ancak bana kulluk edin."},{"n":57,"t":"Her can ölümü tadacaktır. Sonra bize döndürüleceksiniz."},{"n":58,"t":"İman edip salih amel işleyenler var ya, onları içinden ırmaklar akan ve içinde ebedî kalacakları cennet köşklerine yerleştireceğiz. Çalışanların mükâfatı ne güzeldir!"},{"n":59,"t":"Onlar, sabreden ve yalnız Rablerine tevekkül eden kimselerdir."},{"n":60,"t":"Nice canlılar vardır ki, rızıklarını taşımazlar (yiyecek biriktirmezler). Onları da sizi de Allah rızıklandırır. O, hakkıyla işitendir, hakkıyla bilendir."},{"n":61,"t":"Andolsun, eğer onlara, \"Gökleri ve yeri kim yarattı, güneşi ve ayı hizmetinize kim verdi?\" diye soracak olsan mutlaka, \"Allah\" diyeceklerdir. O hâlde nasıl (haktan) döndürülüyorlar?"},{"n":62,"t":"Allah, kullarından dilediğine bol verir ve (dilediğine) kısar. Şüphesiz Allah, her şeyi hakkıyla bilendir."},{"n":63,"t":"Andolsun, eğer onlara, \"Gökten yağmuru kim indirip de onunla yeryüzünü ölümünden sonra diriltti?\" diye soracak olsan, mutlaka, \"Allah\" diyeceklerdir. De ki: \"Hamd Allah’a mahsustur.\" Fakat onların çoğu akıllarını kullanmazlar."},{"n":64,"t":"Bu dünya hayatı ancak bir eğlence ve oyundan ibarettir. Ahiret yurduna gelince, işte gerçek hayat odur. Keşke bilselerdi!"},{"n":65,"t":"Gemiye bindikleri zaman dini Allah’a has kılarak O’na dua ederler. Onları kurtarıp karaya çıkardığı zaman ise bir de bakarsın ki, Allah’a ortak koşuyorlar."},{"n":66,"t":"Kendilerine verdiğimiz nimetlere nankörlük etsinler ve bir süre daha faydalansınlar bakalım! İleride bilecekler."},{"n":67,"t":"Çevrelerindeki insanlar kapılıp götürülürken, bizim, onların yurtlarını saygın ve güvenlikli bir yer kıldığımızı görmediler mi? Onlar hâlâ batıla inanıyorlar da Allah’ın nimetini inkâr mı ediyorlar?"},{"n":68,"t":"Allah’a karşı yalan uyduran, yahut kendisine geldiğinde, gerçeği yalanlayandan daha zalim kimdir? Cehennemde kâfirler için bir yer mi yok?"},{"n":69,"t":"Bizim uğrumuzda cihad edenler var ya, biz onları mutlaka yollarımıza ileteceğiz. Şüphesiz Allah, mutlaka iyilik yapanlarla beraberdir."}],[{"n":1,"t":"Elif Lâm Mîm."},{"n":"2-5","t":"Rumlar, yakın bir yerde yenilgiye uğratıldılar. Onlar yenilgilerinden sonra birkaç yıl içinde galip geleceklerdir. Önce de, sonra da emir Allah’ındır. O gün Allah’ın (Rumlara) zafer vermesiyle mü’minler sevinecektir. Allah, dilediğine yardım eder. O, mutlak güç sahibidir, çok merhametlidir."},{"n":6,"t":"Allah, (onlara zafer konusunda) bir vaadde bulunmuştur. Allah, vaadinden dönmez. Fakat insanların çoğu bilmezler."},{"n":7,"t":"Onlar dünya hayatının ancak dış yönünü bilirler. Ahiret konusunda ise tamamen gaflettedirler."},{"n":8,"t":"Onlar, kendi nefisleri(nin yaratılış incelikleri) hakkında hiç düşünmediler mi? Hem Allah, gökler ile yeri ve ikisi arasındakileri ancak hak ve hikmete uygun olarak ve belirli bir süre için yaratmıştır. Şüphesiz insanların birçoğu Rablerine kavuşacaklarını inkâr ediyorlar."},{"n":9,"t":"(Yine) onlar, yeryüzünde dolaşıp kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Onlar kendilerinden daha kuvvetli idiler. Yeryüzünü sürüp işlemişler ve orayı kendilerinin imar ettiğinden daha çok imar etmişlerdi. Onlara da peygamberleri apaçık deliller getirmişlerdi. Allah, onlara asla zulmediyor değildi. Fakat onlar kendilerine zulmediyorlardı."},{"n":10,"t":"Sonra, Allah’ın âyetlerini yalanladıkları ve onlarla alay etmekte oldukları için, kötülük işleyenin sonu daha da kötü oldu."},{"n":11,"t":"Allah, başlangıçta yaratmayı yapar, sonra onu tekrar eder. Sonra da yalnız O’na döndürüleceksiniz."},{"n":12,"t":"Kıyametin kopacağı günde, suçlular hayal kırıklığı içinde ümitsizliğe düşeceklerdir."},{"n":13,"t":"Onların, Allah’a koştukları ortaklardan kendileri için şefaatçılar da olmayacaktır. Artık onlar ortak koştukları şeyleri de inkâr ederler."},{"n":14,"t":"Kıyametin kopacağı gün, işte o gün mü’minler ve kâfirler birbirinden ayrılacaklardır."},{"n":15,"t":"İman edip salih ameller işleyenlere gelince, işte onlar cennet bahçelerinde sevindirilirler."},{"n":16,"t":"İnkâr edip âyetlerimizi ve ahirete kavuşmayı yalanlayanlara gelince, işte onlar azabın içine atılacaklardır."},{"n":17,"t":"Öyle ise akşama girdiğinizde, sabaha kavuştuğunuzda, Allah’ı tespih edin."},{"n":18,"t":"Göklerde ve yerde hamd O’na mahsustur. Gündüzün sonunda ve öğle vaktine girdiğinizde Allah’ı tespih edin."},{"n":19,"t":"Allah, diriyi ölüden çıkarır, ölüyü de diriden çıkarır. Ölümünden sonra yeryüzünü diriltir. Siz de (mezarlarınızdan) işte böyle çıkarılacaksınız."},{"n":20,"t":"Sizi topraktan yaratması, O’nun (varlığının ve kudretinin) delillerindendir. Sonra bir de gördünüz ki siz beşer olmuş (çoğalıp) yayılıyorsunuz."},{"n":21,"t":"Kendileri ile huzur bulasınız diye sizin için türünüzden eşler yaratması ve aranızda bir sevgi ve merhamet var etmesi de O’nun (varlığının ve kudretinin) delillerindendir. Şüphesiz bunda düşünen bir toplum için elbette ibretler vardır."},{"n":22,"t":"Göklerin ve yerin yaratılması, dillerinizin ve renklerinizin farklı olması da O’nun (varlığının ve kudretinin) delillerindendir. Şüphesiz bunda bilenler için elbette ibretler vardır."},{"n":23,"t":"Geceleyin uyumanız ve gündüzün O’nun lütfundan istemeniz de O’nun (varlığının ve kudretinin) delillerindendir. Şüphesiz bunda işiten bir toplum için ibretler vardır."},{"n":24,"t":"Korku ve ümit kaynağı olarak şimşeği size göstermesi, gökten yağmur indirip onunla yeryüzünü ölümünden sonra diriltmesi, O’nun (varlığının ve kudretinin) delillerindendir. Şüphesiz bunda aklını kullanan bir toplum için elbette ibretler vardır."},{"n":25,"t":"Emriyle göğün ve yerin (kendi düzenlerinde) durması da O’nun (varlığının ve kudretinin) delillerindendir. Sonra sizi yerden (kalkmaya) bir çağırdı mı, bir de bakarsınız ki (dirilmiş olarak) çıkıyorsunuz."},{"n":26,"t":"Göklerde ve yerde kim varsa yalnızca O’na âittir. Hepsi O’na boyun eğmektedirler."},{"n":27,"t":"O, başlangıçta yaratmayı yapan, sonra onu tekrarlayacak olandır. Bu, O’na göre (ilk yaratmadan) daha kolaydır. Göklerde ve yerde en yüce ve eşsiz sıfatlar O’nundur. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":28,"t":"Allah, size kendinizden şöyle bir örnek getirdi: Kölelerinizden, verdiğimiz rızıklarda sizinle eşit haklara sahip olan ve birbirinizden çekindiğiniz gibi kendilerinden çekindiğiniz ortaklarınız var mı? Düşünen bir topluluk için âyetleri böyle ayrı ayrı açıklıyoruz."},{"n":29,"t":"Fakat, zulmedenler bilgisizce nefislerinin arzularına uydular. Allah’ın (bu şekilde) saptırdığı kimseleri kim doğru yola iletir? Onların hiçbir yardımcıları yoktur."},{"n":30,"t":"Hakka yönelen bir kimse olarak yüzünü dine çevir. Allah’ın insanları üzerinde yarattığı fıtrata sımsıkı tutun. Allah’ın yaratmasında hiçbir değiştirme yoktur. İşte bu dosdoğru dindir. Fakat insanların çoğu bilmezler."},{"n":"31-32","t":"Allah’a yönelmiş kimseler olarak yüzünüzü hak dine çevirin, O’na karşı gelmekten sakının, namazı dosdoğru kılın ve müşriklerden; dinlerini darmadağınık edip grup grup olan kimselerden olmayın. (Ki onlardan) her bir grup kendi katındaki (dinî anlayış) ile sevinip böbürlenmektedir."},{"n":33,"t":"İnsanlara bir zarar dokunduğu zaman, Rablerine yönelerek O’na dua ederler. Sonra Allah, onlara kendinden bir rahmet tattırınca da, bir bakarsın ki içlerinden bir grup, Rablerine ortak koşuyorlar."},{"n":34,"t":"Kendilerine verdiğimiz nimetleri inkâr etsinler bakalım! Haydi (şimdilik) yararlanın, ama yakında bileceksiniz."},{"n":35,"t":"Yoksa biz kendilerine bir delil mi indirdik de o, Allah’a ortak koşmaları konusunda (isabetli olduklarını) söylüyor?"},{"n":36,"t":"İnsanlara bir rahmet tattırdığımız zaman ona sevinirler. Eğer kendi işledikleri şeyler sebebiyle başlarına bir kötülük gelirse, bir de bakarsın ki ümitsizliğe düşerler."},{"n":37,"t":"Allah’ın, rızkı dilediğine bol verdiğini ve (dilediğine) kıstığını görmediler mi? Bunda inanan bir toplum için elbette ibretler vardır."},{"n":38,"t":"Öyle ise akrabaya, yoksula, ve yolcuya hakkını ver. Bu, Allah’ın hoşnutluğunu kazanmak isteyenler için daha hayırlıdır. İşte onlar kurtuluşa erenlerdir."},{"n":39,"t":"İnsanların malları içinde artsın diye faizle her ne verirseniz, Allah katında artmaz. Ama Allah’ın hoşnutluğunu isteyerek her ne zekât verirseniz; işte bunu yapanlar sevaplarını kat kat arttıranlardır."},{"n":40,"t":"Allah, sizi yaratan, sonra size rızık veren, sonra sizi öldürecek ve daha sonra da diriltecek olandır. Allah’a koştuğunuz ortaklardan, bunlardan herhangi bir şeyi yapabilen var mı? O, onların ortak koştuklarından uzaktır, yücedir."},{"n":41,"t":"İnsanların kendi işledikleri (kötülükler) sebebiyle karada ve denizde bozulma ortaya çıkmıştır. Dönmeleri için Allah, yaptıklarının bazı (kötü) sonuçlarını (dünyada) onlara tattıracaktır."},{"n":42,"t":"De ki: \"Yeryüzünde dolaşın da önceki milletlerin sonlarının nasıl olduğuna bakın.\" Onların çoğu Allah’a ortak koşan kimselerdi."},{"n":43,"t":"Allah tarafından, geri çevrilmesi olmayan bir gün gelmeden önce yüzünü dosdoğru dine çevir. O gün insanlar bölük bölük ayrılacaklardır."},{"n":44,"t":"Kim inkâr ederse, inkârı kendi aleyhinedir. Kimler de salih amel işlerse, ancak kendileri için (cennette yer) hazırlarlar."},{"n":45,"t":"Bu hazırlığı Allah’ın; iman edip salih amel işleyenleri kendi lütfundan mükâfatlandırması için yaparlar. Şüphesiz O, inkâr edenleri sevmez."},{"n":46,"t":"Rüzgârları, yağmurun müjdecileri olarak göndermesi, Allah’ın (varlık ve kudretinin) delillerindendir. O, bunu, size rahmetinden tattırmak, emriyle gemilerin yol alması, O’nun lütfundan rızkınızı aramanız ve şükretmeniz için yapar."},{"n":47,"t":"Andolsun, senden önce biz nice peygamberleri kendi kavimlerine gönderdik. Peygamberler onlara apaçık mucizeler getirdiler. Biz de suç işleyenlerden intikam aldık. Mü’minlere yardım etmek ise üzerimizde bir haktır."},{"n":48,"t":"Allah, rüzgârları gönderendir. Onlar da bulutları harekete geçirir. Allah, onları dilediği gibi, (bazen) yayar ve (bazen) yoğunlaştırır. Nihayet yağmurun onların arasından çıktığını görürsün. Onu kullarından dilediklerine uğrattığı zaman bir de bakarsın sevinirler."},{"n":49,"t":"Oysa onlar daha önce kendilerine yağmur yağdırılmadan evvel kesin bir ümitsizliğe kapılmışlardı."},{"n":50,"t":"Allah’ın rahmetinin eserlerine bak! Yeryüzünü ölümünden sonra nasıl diriltiyor. Şüphe yok ki O, ölüleri de elbette diriltecektir. O, her şeye hakkıyla gücü yetendir."},{"n":51,"t":"Andolsun, eğer (ekinlerine zararlı) bir rüzgâr göndersek de o ekini sararmış görseler, ardından mutlaka nankörlük etmeye başlarlar."},{"n":52,"t":"Şüphesiz, sen ölülere işittiremezsin. Dönüp gittikleri zaman çağrıyı sağırlara da işittiremezsin."},{"n":53,"t":"Sen, körleri sapkınlıklarından çıkarıp doğru yola iletemezsin. Sen, çağrını ancak âyetlerimize inanıp müslüman olan kimselere işittirebilirsin."},{"n":54,"t":"Allah, sizi güçsüz olarak yaratan, sonra güçsüzlüğün ardından bir güç veren, sonra gücün ardından bir güçsüzlük ve yaşlılık verendir. O, dilediğini yaratır. O, hakkıyla bilendir, hakkıyla kudret sahibidir."},{"n":55,"t":"Kıyametin kopacağı gün suçlular, (dünyada) bir andan fazla kalmadıklarına yemin ederler. Onlar (dünyada haktan) işte böyle döndürülüyorlardı."},{"n":56,"t":"Kendilerine ilim ve iman verilmiş olanlar ise onlara şöyle diyeceklerdir: \"Andolsun, siz, Allah’ın yazısına göre, yeniden dirilme gününe kadar kaldınız. İşte bu yeniden dirilme günüdür. Fakat siz bilmiyordunuz.\""},{"n":57,"t":"O gün zulmedenlere mazeretleri fayda sağlamaz, Allah’ı razı edecek amelleri işleme istekleri de kabul edilmez."},{"n":58,"t":"Andolsun, biz bu Kur’an’da insanlara her türlü misali verdik. Andolsun, eğer sen onlara bir âyet getirsen, inkâr edenler mutlaka, \"Siz ancak asılsız şeyler uyduranlarsınız\" derler."},{"n":59,"t":"Allah, bilmeyenlerin kalplerini işte böyle mühürler."},{"n":60,"t":"Sabret. Şüphesiz, Allah’ın va’di gerçektir. Kesin imana sahip olmayanlar sakın seni gevşekliğe (ve tedirginliğe) sürüklemesinler. Öyleyse sabret. ALLAH’ın sözü gerçektir. Kuşkusuz bir onaya sahip olmayanlar seni gevşekliğe sürüklemesin."}],[{"n":1,"t":"Elif Lâm Mîm."},{"n":"2-3","t":"Bunlar, hikmet dolu Kitab’ın; iyilik yapanlara bir hidayet ve rahmet olarak indirilmiş âyetleridir."},{"n":4,"t":"Onlar; namazı dosdoğru kılan, zekâtı veren kimselerdir. Onlar ahirete de kesin olarak inanırlar."},{"n":5,"t":"İşte onlar, Rablerinden gelen bir hidayet üzeredirler ve işte onlar kurtuluşa erenlerin ta kendileridir."},{"n":6,"t":"İnsanlardan öylesi vardır ki, bilgisizce Allah yolundan saptırmak ve o yolu eğlenceye almak için, eğlencelik asılsız ve faydasız sözleri satın alır. İşte onlar için aşağılayıcı bir azap vardır."},{"n":7,"t":"Ona âyetlerimiz okunduğu zaman; onları hiç işitmemiş gibi, kulağında bir ağırlık var da büyüklenerek arkasını döner. Ona, elem dolu bir azabı müjdele."},{"n":"8-9","t":"Şüphesiz, iman edip salih amel işleyenler için içlerinde ebedî kalacakları Naîm cennetleri vardır. Allah, (bu konuda) gerçek bir vaadde bulunmuştur. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":10,"t":"Allah, gökleri görebileceğiniz direkler olmaksızın yarattı. Yeryüzüne de, sizi sarsmasın diye sabit dağlar yerleştirdi ve orada her türlü canlıyı yaydı. Gökten de yağmur indirip orada her türden güzel ve faydalı bitki bitirdik."},{"n":11,"t":"İşte Allah’ın yarattıkları! Haydi, Allah’ı bırakıp da taptıklarınızın yarattığını bana gösterin! Hayır, zalimler açık bir sapıklık içindedirler."},{"n":12,"t":"Andolsun, biz Lokmân’a \"Allah’a şükret\" diye hikmet verdik. Kim şükrederse, ancak kendisi için şükretmiş olur. Kim de nankörlük ederse, bilsin ki Allah her bakımdan sınırsız zengindir, övülmeye lâyıktır."},{"n":13,"t":"Hani Lokmân, oğluna öğüt vererek şöyle demişti: \"Yavrum! Allah’a ortak koşma! Çünkü ortak koşmak elbette büyük bir zulümdür.\""},{"n":14,"t":"İnsana da, anne babasına iyi davranmasını emrettik. Annesi, onu her gün biraz daha güçsüz düşerek karnında taşımıştır. Onun sütten kesilmesi de iki yıl içinde olur. (İşte onun için) insana şöyle emrettik: \"Bana ve anne babana şükret. Dönüş banadır.\""},{"n":15,"t":"\"Eğer, hakkında hiçbir bilgi sahibi olmadığın bir şeyi bana ortak koşman için seninle uğraşırlarsa, onlara itaat etme. Fakat dünyada onlarla iyi geçin. Bana yönelenlerin yoluna uy. Sonra dönüşünüz ancak banadır. Ben de size yapmakta olduğunuz şeyleri haber vereceğim.\""},{"n":16,"t":"(Lokmân, öğütlerine şöyle devam etti:) \"Yavrum! Şüphesiz yapılan iş bir hardal tanesi ağırlığında olsa ve bir kayanın içinde, yahut göklerde ya da yerin içinde bile olsa, Allah onu çıkarır getirir. Çünkü Allah, en gizli şeyleri bilendir, (her şeyden) hakkıyla haberdar olandır.\""},{"n":17,"t":"\"Yavrum! Namazı dosdoğru kıl. İyiliği emret. Kötülükten alıkoy. Başına gelen musibetlere karşı sabırlı ol. Çünkü bunlar kesin olarak emredilmiş işlerdendir.\""},{"n":18,"t":"\"Küçümseyerek surat asıp insanlardan yüz çevirme ve yeryüzünde böbürlenerek yürüme! Çünkü Allah, hiçbir kibirleneni, övüngeni sevmez.\""},{"n":19,"t":"\"Yürüyüşünde tabiî ol. Sesini alçalt. Çünkü seslerin en çirkini, şüphesiz eşeklerin sesidir!\""},{"n":20,"t":"Göklerde, yerde ne varsa hepsini Allah’ın sizin hizmetinize verdiğini ve açıkça yahut gizlice üzerinizdeki nimetlerini tamamladığını görmediniz mi? Yine de insanlar arasında, hiçbir bilgisi, yol göstericisi ve aydınlatıcı bir kitabı olmadan Allah hakkında tartışıp duranlar vardır."},{"n":21,"t":"Kendilerine, \"Allah’ın indirdiğine uyun\" denildiği zaman, \"Hayır, biz babalarımızı üzerinde bulduğumuz şeye uyarız\" derler. Şeytan, kendilerini cehennem azabına çağırıyor olsa da mı?"},{"n":22,"t":"Kim iyilik yaparak kendini Allah’a teslim ederse, şüphesiz en sağlam kulpa tutunmuştur. İşlerin sonu ancak Allah’a varır."},{"n":23,"t":"Kim inkâr ederse, onun inkârı seni üzmesin. Onların dönüşleri ancak bizedir. Biz de onlara yaptıklarını haber veririz. Allah, göğüslerin içindekini (kalplerde olanı) hakkıyla bilendir."},{"n":24,"t":"Biz, onları (dünyada) biraz yararlandırırız. Sonra da onları ağır bir azaba sürükleriz."},{"n":25,"t":"Andolsun, eğer onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan, mutlaka \"Allah\" derler. De ki: \"Hamd, Allah’a mahsustur.\" Fakat onların çoğu bilmezler."},{"n":26,"t":"Göklerde ve yerde ne varsa Allah’ındır. Şüphesiz Allah, her bakımdan sınırsız zengin olandır, övülmeye lâyık olandır."},{"n":27,"t":"Eğer yeryüzündeki ağaçlar kalem, deniz de mürekkep olsa, arkasından yedi deniz daha ona katılsa, Allah’ın sözleri (yazmakla) yine de tükenmez. Şüphesiz Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":28,"t":"(Ey insanlar!) Sizin yaratılmanız ve öldükten sonra tekrar diriltilmeniz, ancak bir tek insanı yaratmak ve diriltmek gibidir. Şüphesiz Allah hakkıyla işitendir, hakkıyla görendir."},{"n":29,"t":"Görmedin mi ki, Allah, geceyi gündüzün içine ve gündüzü de gecenin içine sokuyor. Güneşi ve ayı da koyduğu kanunlara boyun eğdirmiştir. Her biri (kendi yörüngesinde) belli bir zamana kadar akar gider. Şüphesiz Allah, işlediklerinizden hakkıyla haberdardır."},{"n":30,"t":"Bu böyledir. Çünkü Allah hakkın ta kendisidir, onu bırakıp da taptıkları ise batıldır. Şüphesiz Allah yücedir, büyüktür."},{"n":31,"t":"Görmedin mi ki, gemiler Allah’ın nimetiyle denizde akıp gitmektedir. Allah, bunu âyetlerinden bir kısmını size göstermek için yapmaktadır. Şüphesiz ki bunda hakkıyla sabreden, hakkıyla şükreden herkes için ibretler vardır."},{"n":32,"t":"Onları, (denizde) bir dalga gölgelikler gibi kapladığında, dini Allah’a has kılarak O’na yalvarırlar. Allah, onları kurtarıp karaya çıkarınca, onlardan bir kısmı orta yolu tutar. Bizim âyetlerimizi ise ancak son derece kaypak, son derece nankör olanlar inkâr eder."},{"n":33,"t":"Ey insanlar! Rabbinize karşı gelmekten sakının. Hiçbir babanın çocuğuna hiçbir yarar sağlayamayacağı, hiçbir çocuğun da babasına hiçbir yarar sağlayamayacağı günden korkun! Şüphesiz Allah’ın va’di gerçektir. Sakın dünya hayatı sizi aldatmasın. O aldatıcı şeytan da Allah hakkında sizi aldatmasın."},{"n":34,"t":"Kıyametin ne zaman kopacağı bilgisi şüphesiz yalnızca Allah katındadır. O, yağmuru indirir, rahimlerdekini bilir. Hiç kimse yarın ne kazanacağını bilemez. Hiç kimse nerede öleceğini de bilemez. Şüphesiz Allah hakkıyla bilendir, (her şeyden) hakkıyla haberdar olandır."}],[{"n":1,"t":"Elif Lâm Mîm."},{"n":2,"t":"Kendisinde hiçbir şüphe bulunmayan bu Kitab’ın indirilişi, âlemlerin Rabbi tarafındandır."},{"n":3,"t":"Yoksa \"Onu Muhammed uydurdu\" mu diyorlar? Hayır o, kendilerine senden önce hiçbir uyarıcı gelmemiş olan bir kavmi uyarman için, doğru yolu bulsunlar diye Rabbin tarafından indirilmiş gerçektir."},{"n":4,"t":"Allah, gökleri ve yeri, ikisi arasındakileri altı gün içinde (altı evrede) yaratan sonra da Arş’a kurulandır. Sizin için O’ndan başka hiçbir dost, hiçbir şefaatçi yoktur. Hâlâ düşünüp öğüt almayacak mısınız?"},{"n":5,"t":"Gökten yere kadar bütün işleri Allah yürütür. Sonra bu işler, süresi sizin hesabınızla bin yıl olan bir günde O’na yükselir."},{"n":6,"t":"İşte Allah, gaybı da görünen âlemi de bilendir, mutlak güç sahibidir, çok merhametlidir."},{"n":7,"t":"O ki, yarattığı her şeyi güzel yaptı. İnsanı yaratmaya da çamurdan başladı."},{"n":8,"t":"Sonra onun neslini bir öz sudan, değersiz bir sudan yarattı."},{"n":9,"t":"Sonra onu şekillendirip ona ruhundan üfledi. Sizin için işitme, görme ve idrak duygularını yarattı. Ne kadar az şükrediyorsunuz!"},{"n":10,"t":"(Kâfirler dediler ki:) \"Biz toprakta yok olduktan sonra mı, biz mi yeniden yaratılacakmışız? Hayır, onlar Rablerine kavuşmayı inkâr etmektedirler."},{"n":11,"t":"De ki: \"Sizin için görevlendirilen ölüm meleği canınızı alacak, sonra Rabbinize döndürüleceksiniz.\""},{"n":12,"t":"Suçlular, Rablerinin huzurunda boyunlarını büküp, \"Rabbimiz! (Gerçeği) gördük ve işittik. Artık şimdi bizi (dünyaya) döndür ki, salih amel işleyelim. Biz artık kesin olarak inanmaktayız\" dedikleri vakit, (onları) bir görsen!"},{"n":13,"t":"Eğer dileseydik, herkese hidayetini verirdik. Fakat benim, \"Andolsun, cehennemi hem cinlerden hem de insanlardan dolduracağım\" sözüm gerçekleşecektir."},{"n":14,"t":"(Onlara şöyle denilecek:) \"O hâlde, bu gününüze kavuşmayı unutmanıza karşılık azabı tadın. Biz de sizi unuttuk. Yapmakta olduklarınıza karşılık ebedî azabı tadın.\""},{"n":15,"t":"Bizim âyetlerimize ancak, kendilerine bu âyetlerle öğüt verildiği zaman secdeye kapanan, kibirlenmeksizin Rablerine hamd ederek tespih edenler inanırlar."},{"n":16,"t":"Onlar, korkarak ve ümid ederek Rablerine ibadet etmek için yataklarından kalkarlar. Kendilerine rızık olarak verdiğimiz şeylerden de Allah için harcarlar."},{"n":17,"t":"Hiç kimse, yapmakta olduklarına karşılık olarak, onlar için saklanan göz aydınlıklarını bilemez."},{"n":18,"t":"Hiç mü’min, fasık gibi olur mu? Bunlar (elbette) eşit olmazlar."},{"n":19,"t":"İman edip salih amel işleyenlere gelince, onlar için, yapmakta olduklarına karşılık bir mükâfat olarak Me’vâ cennetleri vardır."},{"n":20,"t":"Fasıklık edenlere gelince, onların barınağı ateştir. Oradan her çıkmak istediklerinde, oraya döndürülürler ve onlara, \"Yalanlamakta olduğunuz ateş azabını tadın\" denir."},{"n":21,"t":"Andolsun, dönsünler diye biz onlara (ahiretteki) en büyük azaptan önce (dünyadaki) yakın azabı elbette tattıracağız."},{"n":22,"t":"Kim, Rabbinin âyetleri kendisine hatırlatıldıktan sonra onlardan yüz çevirenden daha zalimdir? Şüphesiz ki biz suçlulardan intikam alıcıyız."},{"n":23,"t":"Andolsun, biz Mûsâ’ya Kitab’ı (Tevrat’ı) vermiştik. Sen de kitaba (Kur’an’a) kavuşma konusunda sakın şüphe içinde olma. Onu İsrailoğullarına bir yol gösterici kılmıştık."},{"n":24,"t":"Sabredip âyetlerimize kesin olarak inandıkları zaman, içlerinden emrimizle doğru yola ileten önderler çıkardık."},{"n":25,"t":"Şüphesiz Rabbin kıyamet günü, üzerinde ayrılığa düşmekte oldukları şeyler konusunda onlar arasında hüküm verecektir."},{"n":26,"t":"Yurtlarında gezip dolaştıkları nice nesilleri helâk etmiş olmamız, onlar için yol gösterici olmadı mı? Şüphesiz bunda ibretler vardır. Hâlâ duymayacaklar mı?"},{"n":27,"t":"Görmediler mi ki, biz yağmuru kupkuru yere gönderip onunla hayvanlarının ve kendilerinin yiyeceği ekinler çıkarırız. Hâlâ görmeyecekler mi?"},{"n":28,"t":"\"Eğer doğru söyleyenler iseniz, şu fetih ne zamanmış?\" diyorlar."},{"n":29,"t":"De ki: \"Fetih (Kıyamet) günü, inkâr edenlere iman etmeleri fayda vermeyecektir. Onlara göz de açtırılmayacaktır.\""},{"n":30,"t":"Şimdi sen onlardan yüz çevir ve bekle. Şüphesiz onlar da bekliyorlar."}],[{"n":1,"t":"Ey Peygamber! Allah’a karşı gelmekten sakın. Kâfirlere ve münafıklara itaat etme. Şüphesiz Allah hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":2,"t":"Rabbinden sana vahyolunana uy. Şüphesiz Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":3,"t":"Allah’a tevekkül et, vekil olarak Allah yeter."},{"n":4,"t":"Allah, hiçbir adamın içine iki kalp koymamıştır. Kendilerine zıhâr yaptığınız eşlerinizi de anneleriniz yapmamıştır. Yine evlatlıklarınızı da öz çocuklarınız (gibi) kılmamıştır. Bu, sizin ağızlarınızla söylediğiniz (fakat gerçekliği olmayan) sözünüzdür. Allah ise gerçeği söyler ve doğru yola iletir."},{"n":5,"t":"Onları babalarına nispet ederek çağırın. Bu, Allah katında daha (doğru ve) adaletlidir. Eğer babalarını bilmiyorsanız, onlar sizin din kardeşleriniz ve dostlarınızdır. Hata ile yaptığınız bir işte size hiçbir günah yoktur. Fakat kasten yaptığınız şeylerde size günah vardır. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":6,"t":"Peygamber, mü’minlere kendi canlarından daha önce gelir. Onun eşleri de mü’minlerin analarıdır. Aralarında akrabalık bağı olanlar, Allah’ın Kitab’ına göre, (miras konusunda) birbirleri için (diğer) mü’minlerden ve muhacirlerden daha önceliklidirler. Ancak dostlarınıza bir iyilik yapmanız başka. Bu (hüküm) Kitap’ta yazılıdır."},{"n":7,"t":"Hani biz peygamberlerden sağlam söz almıştık. Senden, Nûh’tan, İbrahim, Mûsâ ve Meryem oğlu İsa’dan da. Evet biz, onlardan sapa sağlam bir söz almıştık."},{"n":8,"t":"(Allah, bunu) doğru kimseleri doğruluklarından hesaba çekmek için (yapmıştır.) Kâfirlere de elem dolu bir azap hazırlamıştır."},{"n":9,"t":"Ey iman edenler! Allah’ın size olan nimetini hatırlayın. Hani (düşman) ordular üzerinize gelmişti de biz onların üzerine bir rüzgâr ve göremediğiniz ordular göndermiştik. Allah, yaptıklarınızı hakkıyla görmektedir."},{"n":10,"t":"Hani onlar size hem üst tarafınızdan hem alt tarafınızdan gelmişlerdi. Hani gözler kaymış ve yürekler ağızlara gelmişti. Siz de Allah’a karşı çeşitli zanlarda bulunuyordunuz."},{"n":11,"t":"İşte orada mü’minler denendiler ve şiddetli bir şekilde sarsıldılar."},{"n":12,"t":"Hani münafıklar ve kalplerinde hastalık olanlar, \"Allah ve Resûlü bize, ancak aldatmak için vaadde bulunmuşlar\" diyorlardı."},{"n":13,"t":"Hani onlardan bir grup, \"Ey Yesrib (Medine) halkı! Sizin burada durmak imkânınız yok. Haydi geri dönün\" demişti. Onlardan bir başka grup da, \"Evlerimiz açık (korumasız)\" diyerek Peygamberden izin istiyorlardı. Oysa evleri açık (korumasız) değildi. Onlar sadece kaçmak istiyorlardı."},{"n":14,"t":"Eğer Medine’nin her tarafından üzerlerine gelinse ve orada karışıklık çıkarmaları istenseydi, onu mutlaka yaparlardı; o konuda fazla gecikmezlerdi."},{"n":15,"t":"Andolsun ki, onlar, daha önce geri dönüp kaçmayacaklarına dair Allah’a söz vermişlerdi. Allah’a verilen söz ise sorumluluğu gerektirir."},{"n":16,"t":"De ki: \"Eğer siz ölümden ya da öldürülmekten kaçıyorsanız, kaçmak size asla fayda vermeyecektir. O takdirde bile (hayatın zevklerinden) pek az yararlandırılırsınız.\""},{"n":17,"t":"De ki: \"Eğer Allah size bir kötülük dilese, sizi Allah’tan koruyacak kimdir? Yahut size bir rahmet dilese, buna engel olacak kimdir?\" Onlar kendilerine Allah’tan başka hiçbir dost ve hiçbir yardımcı bulamazlar."},{"n":"18-19","t":"Şüphesiz Allah içinizden, savaştan alıkoyanları ve kardeşlerine, \"Bize gelin\" diyenleri biliyor. Size katkıda cimri davranarak savaşa pek az gelirler. Korku geldiğinde ise, üzerine ölüm baygınlığı çökmüş kimse gibi gözleri dönerek sana baktıklarını görürsün. Korku gidince de ganimete karşı aşırı düşkünlük göstererek sizi keskin dillerle incitirler. İşte onlar iman etmediler. Allah da onların amellerini boşa çıkardı. Bu, Allah’a kolaydır."},{"n":20,"t":"Düşman birliklerinin gitmediğini sanıyorlar. Düşman birlikleri (bir daha) gelecek olsa, isterler ki, (çölde) bedevilerin arasında bulunsunlar da size dair haberleri (gidip gelenlerden) sorsunlar. İçinizde bulunsalardı da pek az savaşırlardı."},{"n":21,"t":"Andolsun, Allah’ın Resûlünde sizin için; Allah’a ve ahiret gününe kavuşmayı uman, Allah’ı çok zikreden kimseler için güzel bir örnek vardır."},{"n":22,"t":"Mü’minler, düşman birliklerini görünce, \"İşte bu, Allah’ın ve Resûlünün bize vaad ettiği şeydir. Allah ve Resûlü doğru söylemişlerdir\" dediler. Bu, onların ancak imanlarını ve teslimiyetlerini artırmıştır."},{"n":23,"t":"Mü’minlerden öyle adamlar vardır ki, Allah’a verdikleri söze sâdık kaldılar. İçlerinden bir kısmı verdikleri sözü yerine getirmiştir (şehit olmuştur). Bir kısmı da (şehit olmayı) beklemektedir. Verdikleri sözü asla değiştirmemişlerdir."},{"n":24,"t":"Bunun böyle olması Allah’ın, doğruları, doğrulukları sebebiyle mükâfatlandırması, dilerse münafıklara azap etmesi yahut onların tövbesini kabul etmesi içindir. Şüphesiz Allah çok bağışlayandır, çok merhamet edendir."},{"n":25,"t":"Allah, inkâr edenleri, hiçbir hayra ulaşmaksızın kin ve öfkeleriyle geri çevirdi. Allah, savaşta mü’minlere kâfi geldi. Allah, kuvvetlidir, mutlak güç sahibidir."},{"n":26,"t":"Allah, kitap ehlinden olup müşriklere yardım edenleri kalelerinden indirdi ve kalplerine büyük bir korku saldı. Siz onların bir kısmını öldürüyor, bir kısmını da esir ediyordunuz."},{"n":27,"t":"Allah, sizi onların topraklarına, yurtlarına, mallarına ve henüz ayak basmadığınız topraklara varis kıldı. Allah, her şeye hakkıyla gücü yetendir."},{"n":28,"t":"Ey Peygamber! Hanımlarına de ki: \"Eğer dünya hayatını ve onun süsünü istiyorsanız, gelin size mut’a vereyim ve sizi güzelce bırakayım.\""},{"n":29,"t":"\"Eğer Allah’ı, Resûlünü ve ahiret yurdunu istiyorsanız, bilin ki Allah içinizden iyilik yapanlara büyük bir mükâfat hazırlamıştır.\""},{"n":30,"t":"Ey Peygamber’in hanımları! İçinizden kim apaçık bir çirkinlik yaparsa, onun cezası iki kat verilir. Bu, Allah’a göre kolaydır."},{"n":31,"t":"İçinizden kim Allah’a ve Resûlüne itaat eder ve salih bir amel işlerse, ona mükâfatını iki kat veririz. Biz, ona bereketli bir rızık hazırlamışızdır."},{"n":32,"t":"Ey Peygamber’in hanımları! Siz, kadınlardan herhangi biri gibi değilsiniz. Eğer Allah’a karşı gelmekten sakınıyorsanız (erkeklerle konuşurken) sözü yumuşak bir eda ile söylemeyin ki kalbinde hastalık (kötü niyet) olan kimse ümide kapılmasın. Güzel (ve doğru) söz söyleyin."},{"n":33,"t":"Evlerinizde oturun. Önceki cahiliye dönemi kadınlarının açılıp saçıldığı gibi siz de açılıp saçılmayın. Namazı kılın, zekâtı verin. Allah’a ve Resûlüne itaat edin. Ey Peygamberin ev halkı! Allah, sizden ancak günah kirini gidermek ve sizi tertemiz yapmak istiyor."},{"n":34,"t":"Siz evlerinizde okunan Allah’ın âyetlerini ve hikmeti hatırlayın. Şüphesiz Allah en gizli şeyi bilendir, hakkıyla haberdardır."},{"n":35,"t":"Şüphesiz müslüman erkeklerle müslüman kadınlar, mü’min erkeklerle mü’min kadınlar, itaatkâr erkeklerle itaatkâr kadınlar, doğru erkeklerle doğru kadınlar, sabreden erkeklerle sabreden kadınlar, Allah’a derinden saygı duyan erkekler, Allah’a derinden saygı duyan kadınlar, sadaka veren erkeklerle sadaka veren kadınlar, oruç tutan erkeklerle oruç tutan kadınlar, namuslarını koruyan erkeklerle namuslarını koruyan kadınlar, Allah’ı çokça anan erkeklerle çokça anan kadınlar var ya, işte onlar için Allah bağışlanma ve büyük bir mükâfat hazırlamıştır."},{"n":36,"t":"Allah ve Resûlü bir iş hakkında hüküm verdikleri zaman, hiçbir mü’min erkek ve hiçbir mü’min kadın için kendi işleri konusunda tercih kullanma hakları yoktur. Kim Allah’a ve Resûlüne karşı gelirse, şüphesiz ki o apaçık bir şekilde sapmıştır."},{"n":37,"t":"Hani sen Allah’ın kendisine nimet verdiği, senin de (azat etmek suretiyle) iyilikte bulunduğun kimseye, \"Eşini nikâhında tut (onu boşama) ve Allah’tan sakın\" diyordun. İçinde, Allah’ın ortaya çıkaracağı bir şeyi gizliyor ve insanlardan çekiniyordun. Oysa kendisinden çekinmene Allah daha lâyıktı. Zeyd, eşinden yana isteğini yerine getirince (eşini boşayınca), onu seninle evlendirdik ki, eşlerinden yana isteklerini yerine getirdiklerinde (onları boşadıklarında), evlatlıklarının eşleriyle evlenmeleri konusunda mü’minlere bir zorluk olmasın. Allah’ın emri mutlaka yerine getirilmiştir."},{"n":38,"t":"Allah’ın, kendisine farz kıldığı şeyleri yerine getirmesi konusunda peygambere bir darlık yoktur. Daha önce gelip geçen peygamberler hakkında da Allah’ın kanunu böyledir. Allah’ın emri, kesinleşmiş bir hükümdür."},{"n":39,"t":"Daha önce gelip geçen o peygamberler, Allah’ın vahiylerini tebliğ eden, Allah’tan korkan, başka hiç kimseden korkmayan kimselerdir. Allah, hesap görücü olarak yeter."},{"n":40,"t":"Muhammed, sizin erkeklerinizden hiçbirinin babası değildir. Fakat o, Allah’ın Resûlü ve nebîlerin sonuncusudur. Allah, her şeyi hakkıyla bilendir."},{"n":41,"t":"Ey iman edenler! Allah’ı çokça zikredin."},{"n":42,"t":"O’nu sabah akşam tespih edin."},{"n":43,"t":"O, sizi karanlıklardan aydınlığa çıkarmak için size merhamet eden; melekleri de sizin için bağışlanma dileyendir. Allah, mü’minlere çok merhamet edendir."},{"n":44,"t":"Allah’a kavuşacakları gün mü’minlere yönelik esenlik dileği \"Selâm\"dır. Allah, onlara bol bir mükâfat hazırlamıştır."},{"n":"45-46","t":"Ey Peygamber! Biz seni bir şahit, bir müjdeleyici, bir uyarıcı; Allah’ın izniyle kendi yoluna çağıran bir davetçi ve aydınlatıcı bir kandil olarak gönderdik."},{"n":47,"t":"Mü’minlere kendileri için Allah’tan büyük bir lütuf olduğunu müjdele."},{"n":48,"t":"Kâfirlere ve münafıklara itaat etme! Onların eziyetlerine aldırma ve Allah’a tevekkül et. Vekil olarak Allah yeter."},{"n":49,"t":"Ey iman edenler! Mü’min kadınları nikâhlayıp, sonra onlara dokunmadan (cinsel ilişkide bulunmadan) kendilerini boşadığınızda, onlar üzerinde sizin sayacağınız bir iddet hakkınız yoktur. Bu durumda onlara mut’a verin ve kendilerini güzel bir şekilde bırakın."},{"n":50,"t":"Ey Peygamber! Biz sana mehirlerini verdiğin eşlerini, Allah’ın sana ganimet olarak verdiklerinden elinin altında bulunan kadınları; seninle beraber hicret eden, amcanın kızlarını, halalarının kızlarını, dayının kızlarını ve teyzelerinin kızlarını sana helâl kıldık. Ayrıca, diğer mü’minlere değil de, sana has olmak üzere, mehirsiz olarak kendini Peygamber’e bağışlayan, Peygamber’in de kendisini nikâhlamak istediği herhangi bir mü’min kadını da (sana helâl kıldık.) Mü’minlere eşleri ve sahip oldukları cariyeleri hakkında farz kıldığımız şeyleri elbette bilmekteyiz. Bütün bunlar, sana herhangi bir zorluk olmaması içindir. Allah çok bağışlayıcıdır, çok merhamet edicidir."},{"n":51,"t":"Ey Muhammed! Bunlardan (hanımlarından) dilediğini geri bırakırsın, dilediğini yanına alırsın. Uzak durduklarından dilediklerini yanına almanda da sana bir günah yoktur. Bu onların gözlerinin aydın olması, üzülmemeleri ve hepsinin de kendilerine verdiğine razı olmaları için daha uygundur. Allah, kalplerinizdekini bilir. Allah, hakkıyla bilendir, halîmdir. (Hemen cezalandırmaz, mühlet verir.)"},{"n":52,"t":"Bundan sonra, güzellikleri hoşuna gitse bile başka kadınlarla evlenmek, eşlerini boşayıp başka eşler almak sana helâl değildir. Ancak sahip olduğun cariyeler başka. Şüphesiz Allah, her şeyi gözetleyendir."},{"n":53,"t":"Ey iman edenler! Yemek için çağrılmaksızın ve yemeğin pişmesini beklemeksizin (vakitli vakitsiz) Peygamber’in evlerine girmeyin, çağrıldığınız zaman girin. Yemeği yiyince de hemen dağılın. Sohbet için beklemeyin. Çünkü bu davranışınız Peygamber’i rahatsız etmekte, fakat o sizden de çekinmektedir. Allah ise gerçeği söylemekten çekinmez. Peygamberin hanımlarından bir şey istediğiniz zaman perde arkasından isteyin. Böyle davranmanız hem sizin kalpleriniz, hem de onların kalpleri için daha temizdir. Allah’ın Resûlüne rahatsızlık vermeniz ve kendisinden sonra hanımlarını nikâhlamanız ebediyyen söz konusu olamaz. Çünkü bu, Allah katında büyük bir günahtır."},{"n":54,"t":"Siz bir şeyi açığa vursanız da gizleseniz de, biliniz ki Allah her şeyi hakkıyla bilendir."},{"n":55,"t":"Peygamberin hanımlarına, babalarından, oğullarından, erkek kardeşlerinden, erkek kardeşlerinin oğullarından, kız kardeşlerinin oğullarından, mü’min kadınlardan ve sahip oldukları cariyelerden ötürü bir günah yoktur. Ey Peygamber hanımları! Allah’a karşı gelmekten sakının. Şüphesiz Allah, her şeye hakkıyla şahittir."},{"n":56,"t":"Şüphesiz Allah ve melekleri Peygamber’e salât ediyorlar. Ey iman edenler! Siz de ona salât edin, selâm edin."},{"n":57,"t":"Şüphesiz Allah ve Resûlünü incitenlere, Allah dünya ve ahirette lânet etmiş ve onlara aşağılayıcı bir azap hazırlamıştır."},{"n":58,"t":"Mü’min erkekleri ve mü’min kadınları işlemedikleri şeyler yüzünden incitenler, bir iftira ve apaçık bir günah yüklenmişlerdir."},{"n":59,"t":"Ey Peygamber! Hanımlarına, kızlarına ve mü’minlerin kadınlarına söyle, bedenlerini örtecek elbiselerini giysinler. Bu, onların tanınıp incitilmemelerine de daha uygundur. Şüphesiz Allah çok bağışlayıcıdır, çok merhamet edicidir."},{"n":"60-61","t":"Andolsun, eğer münafıklar, kalplerinde bir hastalık bulunanlar ve Medine’de kötü haberler yayıp ortalığı karıştıranlar (tuttukları yoldan) vazgeçmezlerse, elbette seni onların üzerine gitmeye teşvik edeceğiz. Onlar da (bundan sonra) orada lânete uğramış kimseler olarak seninle pek az süre komşu kalacaklardır. Nerede bulunurlarsa, yakalanırlar ve yaman bir şekilde öldürülürler."},{"n":62,"t":"Daha önce gelip geçenler hakkında da Allah’ın kanunu böyledir. Allah’ın kanununda asla değişme bulamazsın."},{"n":63,"t":"İnsanlar sana kıyametin vaktini soruyorlar. De ki: \"Onun ilmi ancak Allah katındadır.\" Ne bilirsin, belki de kıyamet yakında gerçekleşir."},{"n":64,"t":"Şüphesiz Allah, kâfirlere lânet etmiş ve onlara alevli bir ateş hazırlamıştır."},{"n":65,"t":"Onlar, orada ebedî olarak kalacaklardır. Hiçbir dost, hiçbir yardımcı bulamayacaklardır."},{"n":66,"t":"Yüzlerinin ateşte bir yandan bir yana döndürüleceği gün, \"Keşke Allah’a ve Resûl’e itaat edeydik\" diyecekler."},{"n":67,"t":"Yine şöyle diyecekler: \"Ey Rabbimiz! Biz önderlerimize ve büyüklerimize itaat ettik de bizi yoldan saptırdılar.\""},{"n":68,"t":"\"Ey Rabbimiz! Onlara iki kat azap ver ve onları büyük bir lânete uğrat.\""},{"n":69,"t":"Ey iman edenler! Siz Mûsâ’ya eziyet eden kimseler gibi olmayın. Nihayet Allah onu onların dediklerinden temize çıkarmıştı. Mûsâ, Allah katında itibarlı bir kimse idi."},{"n":"70-71","t":"Ey iman edenler! Allah’a karşı gelmekten sakının ve doğru söz söyleyin ki, Allah sizin işlerinizi düzeltsin ve günahlarınızı bağışlasın. Kim Allah’a ve Resûlüne itaat ederse, muhakkak büyük bir başarıya ulaşmıştır."},{"n":72,"t":"Şüphesiz biz emaneti göklere, yere ve dağlara teklif ettik de onlar onu yüklenmek istemediler, ondan çekindiler. Onu insan yüklendi. Çünkü o çok zalimdir, çok cahildir."},{"n":73,"t":"Allah, münafık erkeklere ve münafık kadınlara, Allah’a ortak koşan erkeklere ve Allah’a ortak koşan kadınlara azap etmek; mü’min erkeklerin ve mü’min kadınların da tövbelerini kabul etmek için insana emaneti yüklemiştir. Allah çok bağışlayandır, çok merhamet edendir."}],[{"n":1,"t":"Hamd, göklerdeki ve yerdeki her şey kendisinin olan Allah’a mahsustur. Hamd ahirette de O’na mahsustur. O, hüküm ve hikmet sahibidir, (her şeyden) hakkıyla haberdardır."},{"n":2,"t":"Allah, yere gireni, yerden çıkanı; gökten ineni ve oraya yükseleni bilir. O, çok merhamet edicidir, çok bağışlayıcıdır."},{"n":3,"t":"İnkâr edenler, \"Kıyamet bize gelmeyecektir\" dediler. De ki: \"Hayır, öyle değil, gaybı bilen Rabbime andolsun ki, Kıyamet size mutlaka gelecektir. Ne göklerde ve ne de yerde zerre ağırlığında bir şey bile O’ndan gizli kalmaz. Bundan daha küçük ve daha büyük ne varsa, hepsi apaçık bir kitaptadır.\""},{"n":4,"t":"Allah’ın, iman edip salih amel işleyenleri mükâfatlandırması için (her şey o kitapta tespit edilmiştir.) İşte onlar için bir bağışlanma ve bereketli bir rızık vardır."},{"n":5,"t":"Âyetlerimizi geçersiz kılmak için yarışırcasına çaba harcayanlar var ya; işte onlar için elem dolu, çok kötü bir azap vardır."},{"n":6,"t":"Kendilerine ilim verilenler, Rabbinden sana indirilen Kur’an’ın gerçek olduğunu ve onun, mutlak güç sahibi ve övgüye lâyık Allah’ın yoluna ilettiğini görürler."},{"n":7,"t":"Yine inkâr edenler şöyle dediler: \"Çürüyüp ufalandıktan sonra sizin yeniden diriltileceğinizi söyleyen bir adamı size gösterelim mi?"},{"n":8,"t":"\"Allah’a karşı yalan mı uydurdu, yoksa onda delilik mi var?\" Hayır, öyle değil! Ahirete inanmayanlar azap ve derin sapıklık içindedirler."},{"n":9,"t":"Onlar, önlerindeki ve arkalarındaki (kendilerini dört bir yandan kuşatan) göğe ve yere bakmadılar mı? Eğer dilersek onları yere geçirir veya gökten üzerlerine parçalar düşürürüz. Bunda, Rabbine yönelen her kul için bir ibret vardır."},{"n":"10-11","t":"Andolsun, Davud’a tarafımızdan bir lütuf verdik. \"Ey dağlar! Kuşların eşliğinde onunla birlikte tespih edin\" dedik ve \"(Bütün vücudu örtecek) zırhlar yap, işçilikte de ölçüyü tuttur diye demiri ona yumuşattık. \"Salih amel işleyin. Çünkü ben sizin yaptıklarınızı görürüm\" diye vahyettik."},{"n":12,"t":"Süleyman’ın emrine de, sabah esişi bir ay, akşam esişi de bir ay(lık yol) olan rüzgârı verdik. Erimiş bakır ocağını da ona sel gibi akıttık. Cinlerden de Rabbinin izniyle onun önünde çalışanlar vardı. İçlerinden kim bizim emrimizden çıkarsa, ona alevli ateş azabını tattırırız."},{"n":13,"t":"Cinler, Süleyman için dilediği biçimde kaleler, heykeller, havuz gibi çanaklar ve sabit kazanlar yapıyorlardı. Ey Davûd ailesi, şükredin! Kullarımdan şükredenler pek azdır."},{"n":14,"t":"Süleyman’ın ölümüne hükmettiğimiz zaman, onun ölümünü onlara ancak değneğini yemekte olan bir kurt gösterdi. Süleyman’ın cesedi yıkılınca cinler anladılar ki, eğer gaybı bilmiş olsalardı aşağılayıcı azap içinde kalmamış olacaklardı."},{"n":15,"t":"Andolsun, Sebe’ halkı için kendi yurtlarında bir ibret vardı: Biri sağda biri solda iki bahçe bulunuyordu. Onlara şöyle denilmişti: \"Rabbinizin rızkından yiyin ve O’na şükredin. Beldeniz güzel bir belde, Rabbiniz de çok bağışlayıcı bir Rabdir.\""},{"n":16,"t":"Fakat onlar yüz çevirdiler. Biz de üzerlerine Arim selini gönderdik. Onların bahçelerini ekşi meyveli ağaçlar, acı ılgın ve biraz da sedir ağacı bulunan iki bahçeye çevirdik."},{"n":17,"t":"Nimetlere karşı nankörlük etmeleri sebebiyle onları işte böyle cezalandırdık. Biz (bu şekilde) ancak nankörleri cezalandırırız."},{"n":18,"t":"Sebe’ halkı ile bereketlendirdiğimiz kentler arasına (her biri diğerinden) görülen kentler oluşturduk. Oralarda gidiş gelişi belirledik (seyahati kolaylaştırdık) ve onlara da şöyle dedik: \"Oralarda gece gündüz güvenlik içinde dolaşın.\""},{"n":19,"t":"Onlar ise, \"Ey Rabbimiz! Yolculuğumuzun konakları arasını uzaklaştır\" dediler ve kendilerine zulmettiler. Biz de onları ibret kıssalarına çevirdik ve kendilerini darmadağın ettik. Şüphesiz ki bunda çok sabreden, çok şükreden herkes için ibretler vardır."},{"n":20,"t":"Şeytan, onlar hakkındaki zannını doğru çıkardı. İnananlardan bir grup dışında hepsi ona uydular."},{"n":21,"t":"Oysa şeytanın onlar üzerinde hiçbir hâkimiyeti yoktu. Ancak ahirete inananları, onun hakkında şüphe içinde bulunanlardan ayırt edelim diye (ona bu fırsatı verdik). Senin Rabbin her şey üzerinde hakiki bir koruyucudur."},{"n":22,"t":"(Ey Muhammed!) De ki: \"Allah’ı bırakıp da ilâh olduklarını iddia ettiklerinizi çağırın. Göklerde ve yerde zerre kadar bir şeye sahip değillerdir. Onların yerde ve gökte hiçbir ortaklıkları yoktur. Allah’ın onlardan bir yardımcısı da yoktur."},{"n":23,"t":"Allah katında, O’nun izin verdiği kimseden başkasının şefaati yarar sağlamaz. (Şefaat için izin verilip de) kalplerinden korku giderilince birbirlerine, \"Rabbiniz ne söyledi?\" diye sorarlar. Onlar da \"Gerçeği\" diye cevap verirler. O, yücedir, büyüktür."},{"n":24,"t":"De ki: \"Size göklerden ve yerden kim rızık verir?\" De ki: \"Allah. O hâlde, ya biz hidayet veya apaçık bir sapıklık üzereyiz, ya da siz!\""},{"n":25,"t":"De ki: \"Bizim işlediğimiz suçlardan siz sorumlu tutulmazsınız. Sizin işlediklerinizden de biz sorumlu tutulmayız.\""},{"n":26,"t":"De ki: \"Rabbimiz hepimizi kıyamet günü bir araya toplayacak, sonra da aramızda hak ile hüküm verecektir. O, gerçeği apaçık ortaya koyan, hakkıyla bilendir.\""},{"n":27,"t":"De ki: \"Allah’a ortak tuttuklarınızı bana gösterin! Hayır! (Hiçbir şey Allah’a ortak olamaz.) Aksine O, mutlak güç sahibi, hüküm ve hikmet sahibi Allah’tır.\""},{"n":28,"t":"Biz, seni ancak bütün insanlara müjdeleyici ve uyarıcı olarak gönderdik. Fakat insanların çoğu bilmezler."},{"n":29,"t":"\"Eğer doğru söyleyenler iseniz, bu tehdit ne zaman gerçekleşecek\" diyorlar."},{"n":30,"t":"De ki: \"Sizin için belirlenen bir gün vardır ki, ondan ne bir saat geri kalabilirsiniz, ne de ileri geçebilirsiniz.\""},{"n":31,"t":"İnkâr edenler, \"Biz bu Kur’an’a da ondan önceki kitaplara da asla inanmayız\" dediler. Zalimler, Rablerinin huzurunda durduruldukları zaman hâllerini bir görsen! Birbirlerine laf çevirip dururlar. Zayıf ve güçsüz görülenler, büyüklük taslayanlara, \"Siz olmasaydınız, biz mutlaka iman eden kimseler olurduk\" derler."},{"n":32,"t":"Büyüklük taslayanlar, zayıf ve güçsüz görülenlere, \"Size hidayet geldikten sonra, biz mi sizi ondan alıkoyduk? Hayır, suçlu olanlar sizlerdiniz\" derler."},{"n":33,"t":"Zayıf ve güçsüz görülenler, büyüklük taslayanlara, \"Hayır, bizi hidayetten saptıran gece ve gündüz kurduğunuz tuzaklardır. Çünkü siz bize Allah’ı inkâr etmemizi ve O’na eşler koşmamızı emrediyordunuz\" derler. Azabı görünce de içten içe pişmanlık duyarlar. Biz de inkâr edenlerin boyunlarına demir halkalar geçiririz. Onlar ancak yapmakta olduklarının cezasını göreceklerdir."},{"n":34,"t":"Biz, hangi memlekete bir uyarıcı göndermişsek oranın şımarık zenginleri, \"Biz, sizinle gönderileni inkâr ediyoruz\" demişlerdir."},{"n":35,"t":"Yine, \"Bizim mallarımız ve çocuklarımız daha çoktur. Bize azap edilmeyecektir\" demişlerdi."},{"n":36,"t":"Ey Muhammed, de ki: \"Şüphesiz, Rabbim rızkı dilediğine bol verir ve (dilediğine) kısar. Fakat insanların çoğu bilmezler.\""},{"n":37,"t":"Ne mallarınız ne de çocuklarınız, sizi bizim katımıza daha çok yaklaştıran şeylerdir! Ancak iman edip salih amel işleyenler başka. İşte onlar için işlediklerine karşılık kat kat mükâfat vardır. Onlar cennet köşklerinde güven içindedirler."},{"n":38,"t":"Âyetlerimizi geçersiz kılmak için yarışanlar var ya, işte onlar azap için hazır bulundurulacaklar."},{"n":39,"t":"De ki: \"Şüphesiz, Rabbim rızkı kullarından dilediğine bol bol verir ve (dilediğine) kısar. Allah yolunda her ne harcarsanız, Allah onun yerine başkasını verir. O, rızık verenlerin en hayırlısıdır.\""},{"n":40,"t":"Allah’ın, onları hep birden toplayacağı, sonra da meleklere, \"Bunlar mı size ibadet ediyorlardı?\" diyeceği günü bir hatırla!"},{"n":41,"t":"(Melekler) derler ki: \"Seni eksikliklerden uzak tutarız. Onlar değil, sen bizim dostumuzsun. Hayır, onlar cinlere ibadet ediyorlardı. Onların çoğu cinlere inanıyordu.\""},{"n":42,"t":"İşte bugün birbirinize ne fayda ne de zarar verebilirsiniz. Zulmedenlere, \"Yalanlamakta olduğunuz cehennem azabını tadın\" deriz."},{"n":43,"t":"Âyetlerimiz apaçık bir şekilde onlara okunduğunda, \"Bu sadece, atalarınızın tapmakta olduğu şeylerden sizi alıkoymak isteyen bir adamdır\" dediler. Bir de, \"Bu (Kur’an), uydurulmuş bir yalandır\" dediler. Yine hak kendilerine geldiğinde onu inkâr edenler, \"Bu, ancak apaçık bir büyüdür\" dediler."},{"n":44,"t":"Oysa biz onlara okuyup inceleyecekleri kitaplar vermedik. Onlara senden önce hiçbir uyarıcı da göndermedik."},{"n":45,"t":"Onlardan öncekiler de yalanlamışlardı. Hâlbuki bunlar onlara verdiğimiz şeylerin onda birine bile ulaşamamışlardır. Elçilerimi yalanladılar. Peki, beni inkâr etmenin sonucu nasıl oldu!"},{"n":46,"t":"(Ey Muhammed!) De ki: \"Ben size ancak bir tek şeyi, Allah için ikişer ikişer, teker teker kalkıp düşünmenizi öğütlüyorum. Arkadaşınız Muhammed’de cinnetten eser yoktur. O, şiddetli bir azaptan önce sizin için ancak bir uyarıcıdır.\""},{"n":47,"t":"De ki: \"Sizden herhangi bir ücret istemişsem, o sizin olsun. Benim ücretim ancak Allah’a aittir. O, her şeye hakkıyla şahittir.\""},{"n":48,"t":"De ki: \"Şüphesiz Rabbim gerçeği ortaya koyar. O, gaybleri hakkıyla bilendir.\""},{"n":49,"t":"De ki: \"Hak geldi. Artık batıl yeni bir şey ortaya çıkaramaz, eskiyi de geri getiremez.\""},{"n":50,"t":"De ki: \"Ben eğer sapmışsam, ancak kendi aleyhime sapmış olurum. Eğer hidayete ermişsem, bu da Rabbimin bana vahyettiği sayesindedir. Şüphesiz O, hakkıyla işitendir, kuluna çok yakındır.\""},{"n":51,"t":"Sen onları, dehşetli bir korkuya kapılıp da kaçıp kurtulamayacakları ve yakın bir yerden yakalanacakları zaman bir görsen!"},{"n":52,"t":"(Azabı görünce), \"ona inandık derler\" ama onlar için, artık uzak bir yerden (dünyadan) iman elde etmek nasıl mümkün olur?"},{"n":53,"t":"Oysa daha önce onu inkâr etmişlerdi ve uzak bir yerden gayb hakkında atıp tutuyorlardı."},{"n":54,"t":"Tıpkı daha önce benzerlerine yapıldığı gibi, kendileriyle arzuladıkları arasına bir engel konmuştur. Çünkü onlar derin bir şüphe içindeydiler."}],[{"n":1,"t":"Hamd, gökleri ve yeri yaratan, melekleri ikişer, üçer, dörder kanatlı elçiler yapan Allah’a mahsustur. O, yaratmada dilediğini artırır. Şüphesiz Allah’ın gücü her şeye hakkıyla yeter."},{"n":2,"t":"Allah, insanlar için ne rahmet açarsa, artık onu tutacak (engelleyecek) yoktur. Neyi de tutarsa, bundan sonra onu gönderecek yoktur. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":3,"t":"Ey insanlar! Allah’ın size olan nimetini hatırlayın. Allah’tan başka size göklerden ve yerden rızık veren bir yaratıcı var mı? O’ndan başka hiçbir ilâh yoktur. O hâlde nasıl oluyor da haktan döndürülüyorsunuz?"},{"n":4,"t":"(Ey Muhammed!) Eğer seni yalancı sayıyorlarsa bil ki, senden önce de nice peygamberler yalancı sayılmıştır. Bütün işler ancak Allah’a döndürülür."},{"n":5,"t":"Ey insanlar! Şüphesiz Allah’ın vaadi gerçektir. Sakın dünya hayatı sizi aldatmasın. Sakın çok aldatıcı (şeytan), Allah hakkında sizi aldatmasın."},{"n":6,"t":"Şüphesiz şeytan sizin için bir düşmandır. Öyle ise (siz de) onu düşman tanıyın. O, kendi taraftarlarını ancak alevli ateşe girecek kimselerden olmaya çağırır."},{"n":7,"t":"İnkâr edenler için çetin bir azap vardır. İman edip salih ameller işleyenler için ise bir bağışlanma ve büyük bir mükâfat vardır."},{"n":8,"t":"Kötü ameli kendisine süslü gösterilip de onu güzel gören kimse, ameli iyi olan kimse gibi mi olacaktır? Şüphesiz Allah dilediğini saptırır, dilediğini hidayete erdirir. (Ey Muhammed!) Onlar için duyduğun üzüntüler yüzünden kendini helâk etme! Şüphesiz ki Allah, onların yaptıklarını hakkıyla bilendir."},{"n":9,"t":"Allah, rüzgârları gönderendir. Onlar da bulutları hareket ettirir. Biz de bulutları ölü bir toprağa sürer ve onunla ölümünden sonra yeryüzünü diriltiriz. İşte ölümden sonra diriliş de böyledir."},{"n":10,"t":"Her kim şan ve şeref istiyorsa bilsin ki, şan ve şeref bütünüyle Allah’a aittir. Güzel sözler ancak O’na yükselir. Salih ameli de güzel sözler yükseltir. Kötülükleri tuzak yapanlar var ya, onlar için çetin bir azap vardır. İşte onların tuzağı boşa çıkar."},{"n":11,"t":"Allah, sizi önce topraktan, sonra da az bir sudan (meniden) yarattı. Sonra sizi (erkekli dişili) eşler yaptı. Allah’ın ilmine dayanmadan hiçbir dişi ne hamile kalır, ne de doğurur. Herhangi bir kimseye uzun ömür verilmez, yahut ömrü kısaltılmaz ki bu bir kitapta (Levh-i Mahfuz’da yazılı) olmasın. Şüphesiz bu, Allah’a kolaydır."},{"n":12,"t":"İki deniz aynı olmaz. Şu tatlıdır, susuzluğu giderir, içimi kolaydır. Şu ise tuzludur, acıdır. Bununla beraber her birinden taze et yersiniz ve takınacağınız süs eşyası çıkarırsınız. Allah’ın lütfundan istemeniz ve şükretmeniz için gemilerin orada suyu yara yara gittiğini görürsün."},{"n":13,"t":"Allah, geceyi gündüzün içine sokar, gündüzü de gecenin içine sokar. Güneşi ve Ay’ı da koyduğu kanunlara boyun eğdirmiştir. Her biri belirli bir vakte kadar akıp gitmektedir. İşte bu, Allah’tır, Rabbinizdir. Mülk yalnızca O’nundur. Allah’ı bırakıp da ibadet ettikleriniz, bir çekirdek zarına bile hükmedemezler."},{"n":14,"t":"Eğer onları çağırsanız, çağrınızı duymazlar. Duysalar bile çağrınıza karşılık veremezler. Kıyamet günü de sizin ortak koştuğunuzu inkâr ederler. Bunları sana hiç kimse, hakkıyla haberdar olan (Allah) gibi haber veremez."},{"n":15,"t":"Ey insanlar! Siz Allah’a muhtaçsınız. Allah ise her bakımdan sınırsız zengin olandır, övülmeye hakkıyla lâyık olandır."},{"n":16,"t":"Eğer Allah dilerse, sizi giderir ve yeni bir halk getirir."},{"n":17,"t":"Bu, Allah’a göre zor bir şey değildir."},{"n":18,"t":"Hiçbir günahkâr başka bir günahkârın yükünü yüklenmez. Günah yükü ağır olan kimse, (bir başkasını), günahını yüklenmeye çağırırsa, ondan hiçbir şey yüklenilmez, çağırdığı kimse yakını da olsa. Sen ancak, görmedikleri hâlde Rablerinden için için korkanları ve namaz kılanları uyarırsın. Kim arınırsa ancak kendisi için arınmış olur. Dönüş ancak Allah’adır."},{"n":19,"t":"Kör ile gören bir olmaz."},{"n":20,"t":"Karanlıklar ile aydınlık bir olmaz."},{"n":21,"t":"Gölge ile sıcaklık bir olmaz."},{"n":22,"t":"Diriler ile ölüler de bir olmaz. Allah, dilediğine işittirir. Sen, kabirde bulunanlara işittirecek değilsin."},{"n":23,"t":"Sen, ancak bir uyarıcısın."},{"n":24,"t":"Şüphesiz biz, seni müjdeleyici ve uyarıcı olarak hak ile gönderdik. Hiçbir ümmet yoktur ki, aralarında bir uyarıcı gelip geçmiş olmasın."},{"n":25,"t":"(Ey Muhammed!) Eğer seni yalanlıyorlarsa bil ki, onlardan öncekiler de peygamberlerini yalanlamışlardı. Oysa peygamberleri onlara apaçık delilleri, sahifeleri ve aydınlatıcı kitabı getirmişlerdi."},{"n":26,"t":"Sonra ben inkâr edenleri yakaladım. Beni inkâr etmenin sonucu nasıl oldu!"},{"n":27,"t":"Görmüyor musun ki, Allah gökten su indirdi. Biz onunla türlü türlü ürünler çıkardık. Dağlardan da beyaz, kırmızı (birbirinden farklı) çeşitli renklerde yollar (katmanlar) var, simsiyah taşlar da var."},{"n":28,"t":"İnsanlardan, (yeryüzünde) hareket eden (diğer) canlılardan ve hayvanlardan yine böyle çeşitli renklerde olanlar vardır. Allah’a karşı ancak; kulları içinden âlim olanlar derin saygı duyarlar. Şüphesiz Allah mutlak güç sahibidir, çok bağışlayandır."},{"n":29,"t":"Şüphesiz, Allah’ın kitabını okuyanlar, namazı kılanlar ve kendilerine rızık olarak verdiğimiz şeylerden, gizlice ve açıktan Allah yolunda harcayanlar, asla zarar etmeyecek bir ticaret umabilirler."},{"n":30,"t":"Allah, kendilerine mükâfatlarını tam olarak versin ve kendi lütfundan daha da artırsın diye (böyle yaparlar). Şüphesiz O, çok bağışlayandır, şükrün karşılığını verendir."},{"n":31,"t":"(Ey Muhammed!) Sana vahyettiğimiz kitap (Kur’an), kendinden öncekini tasdik eden hak kitaptır. Şüphesiz Allah (kullarından) hakkıyla haberdardır. Onları hakkıyla görür."},{"n":32,"t":"Sonra biz, o kitabı kullarımızdan seçtiğimiz kimselere (Muhammed’in ümmetine) miras olarak verdik. Onlardan kendine zulmedenler vardır. Onlardan ortada olanlar vardır. Yine onlardan Allah’ın izniyle hayırlı işlerde öne geçenler vardır. İşte bu büyük lütuftur."},{"n":33,"t":"Onlar, Adn cennetlerine girerler. Orada altın bilezikler ve incilerle süslenirler. Oradaki elbiseleri de ipektir."},{"n":34,"t":"Şöyle derler: \"Hamd, bizden hüznü gideren Allah’a mahsustur. Şüphesiz Rabbimiz çok bağışlayandır, şükrün karşılığını verendir.\""},{"n":35,"t":"\"O, lütfuyla bizi kalınacak yurda yerleştirendir. Bize orada bir yorgunluk dokunmaz. Bize orada usanç da gelmez.\""},{"n":36,"t":"İnkâr edenler için ise cehennem ateşi vardır. Öldürülmezler ki ölsünler. Kendilerinden cehennem azabı da hafifletilmez. İşte biz her nankörü böyle cezalandırırız."},{"n":37,"t":"Onlar cehennemde, \"Ey Rabbimiz! Bizi buradan çıkar ki dünyada iken işlemekte olduğumuzdan başka ameller, salih ameller işleyelim\" diye bağrışırlar. (Onlara şöyle denilir:) \"Sizi, düşünüp öğüt alacak kimsenin düşünüp öğüt alabileceği kadar yaşatmadık mı? Size uyarıcı da gelmişti. Öyle ise tadın azabı. Çünkü zalimler için hiçbir yardımcı yoktur.\""},{"n":38,"t":"Şüphesiz Allah, göklerin ve yerin gaybını bilendir. Şüphesiz O, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir."},{"n":39,"t":"O, sizi yeryüzünde halifeler kılandır. Artık kim inkâr ederse inkârı kendi aleyhinedir. İnkârcıların inkârı, Rableri katında ancak uğrayacakları gazabı artırır. İnkârcıların inkârı, ancak ziyanlarını arttırır."},{"n":40,"t":"De ki: \"Allah’ı bırakıp da taptığınız ortaklarınızı gördünüz mü? Gösterin bana, onlar yerden ne yaratmışlardır?\" Yoksa onların göklerde bir ortaklıkları mı var? Yoksa kendilerine bir kitap verdik de, o kitaptan, açık bir delile mi sahip bulunuyorlar? Hayır, zalimler birbirlerine aldatmadan başka hiçbir şey vaad etmezler."},{"n":41,"t":"Şüphesiz Allah, gökleri ve yeri, yok olup gitmesinler diye (kurduğu düzende) tutuyor. Andolsun, eğer onlar (yörüngelerinden sapıp) yok olur giderlerse, O’ndan başka hiç kimse onları tutamaz. Şüphesiz O, halîmdir (hemen cezalandırmaz, mühlet verir), çok bağışlayandır."},{"n":42,"t":"Müşrikler, eğer kendilerine bir uyarıcı gelirse, ümmetlerden herhangi birinden daha çok doğru yol üzere olacaklarına dair en güçlü şekilde Allah’a yemin etmişlerdi. Fakat onlara bir uyarıcı gelince, bu ancak onların nefretlerini artırdı."},{"n":43,"t":"Yeryüzünde büyüklük taslamak ve kötü tuzak kurmak için (böyle davranıyorlardı). Oysa kötü tuzak, ancak sahibini kuşatır. Onlar ancak öncekilere uygulanan kanunu bekliyorlar. Sen Allah’ın kanununda hiçbir değişiklik bulamazsın. Sen, Allah’ın kanununda hiçbir sapma bulamazsın."},{"n":44,"t":"Yeryüzünde dolaşıp kendilerinden öncekilerin sonunun nasıl olduğuna bakmadılar mı? Oysa onlar kendilerinden daha da kuvvetli idiler. Göklerdeki ve yerdeki hiçbir şey, Allah’ı âciz bırakacak değildir. Şüphesiz O, hakkıyla bilendir, hakkıyla kudret sahibidir."},{"n":45,"t":"Eğer Allah, insanları kazandıkları yüzünden hemen cezalandıracak olsaydı, yerkürenin sırtında hiçbir canlı bırakmazdı. Ne var ki, onları belirli bir süreye kadar erteliyor. Nihayet süreleri gelince, (gerekeni yapar). Çünkü Allah, kullarını hakkıyla görmektedir."}],[{"n":1,"t":"Yâ Sîn."},{"n":"2-4","t":"(Ey Muhammed!) Hikmet dolu Kur’an’a andolsun ki, sen elbette dosdoğru bir yol üzere (peygamber) gönderilenlerdensin."},{"n":"5-6","t":"Kur’an, ataları uyarılmamış, bu yüzden de gaflet içinde olan bir kavmi uyarman için mutlak güç sahibi, çok merhametli Allah tarafından indirilmiştir."},{"n":7,"t":"Andolsun, onların çoğu üzerine o söz (azap) hak olmuştur. Artık onlar iman etmezler."},{"n":8,"t":"Onların boyunlarına demir halkalar geçirdik, o halkalar çenelerine dayanmıştır. Bu sebeple kafaları yukarıya kalkık durumdadır."},{"n":9,"t":"Biz, onların önlerine bir set, arkalarına da bir set çekip gözlerini perdeledik. Artık görmezler."},{"n":10,"t":"Onları uyarsan da, uyarmasan da onlar için birdir, inanmazlar."},{"n":11,"t":"Sen ancak Zikr’e (Kur’an’a) uyanı ve görmediği hâlde Rahmân’dan korkan kimseyi uyarırsın. İşte onu bir bağışlanma ve güzel bir mükâfatla müjdele."},{"n":12,"t":"Şüphesiz biz, ölüleri mutlaka diriltiriz. Onların yaptıklarını ve bıraktıkları eserlerini yazarız. Biz, her şeyi apaçık bir kitapta (Levh-i Mahfuz’da) bir bir kaydetmişizdir."},{"n":13,"t":"(Ey Muhammed!) Onlara, o memleket halkını örnek ver. Hani oraya elçiler gelmişti."},{"n":14,"t":"Hani biz onlara iki elçi göndermiştik de onları yalancı saymışlardı. Biz de onlara üçüncü bir elçi ile destek vermiştik. Onlar, \"Şüphesiz biz size gönderilmiş elçileriz\" dediler."},{"n":15,"t":"Onlar şöyle dediler: \"Siz de ancak bizim gibi insansınız. Rahmân, hiçbir şey indirmemiştir. Siz sadece yalan söylüyorsunuz.\""},{"n":16,"t":"(Elçiler ise) şöyle dediler: \"Bizim gerçekten size gönderilmiş elçiler olduğumuzu Rabbimiz biliyor.\""},{"n":17,"t":"\"Bize düşen ancak apaçık bir tebliğdir.\""},{"n":18,"t":"Dediler ki: \"Şüphesiz biz sizin yüzünüzden uğursuzluğa uğradık. Eğer vazgeçmezseniz, sizi mutlaka taşlarız ve bizim tarafımızdan size elem dolu bir azap dokunur.\""},{"n":19,"t":"Elçiler de, \"Uğursuzluğunuz kendinizdendir. Size öğüt verildiği için mi (uğursuzluğa uğruyorsunuz?). Hayır, siz aşırı giden bir kavimsiniz\" dediler."},{"n":20,"t":"Şehrin öbür ucundan bir adam koşarak geldi ve şöyle dedi: \"Ey kavmim! Bu elçilere uyun.\""},{"n":21,"t":"\"Sizden hiçbir ücret istemeyen kimselere uyun, onlar hidayete erdirilmiş kimselerdir.\""},{"n":22,"t":"\"Hem ben, ne diye beni yaratana kulluk etmeyeyim. Oysa siz de yalnızca O’na döndürüleceksiniz.\""},{"n":23,"t":"\"O’nu bırakıp da başka ilâhlar mı edineyim? Eğer Rahmân bana bir zarar vermek istese, onların şefaati bana hiçbir fayda sağlamaz ve beni kurtaramazlar.\""},{"n":24,"t":"\"O taktirde ben mutlaka açık bir sapıklık içinde olurum.\""},{"n":25,"t":"\"Şüphesiz ben sizin Rabbinize inandım. Gelin, beni dinleyin!\""},{"n":"26-27","t":"(Kavmi onu öldürdüğünde kendisine): \"Cennete gir!\" denildi. O da, \"Keşke kavmim, Rabbimin beni bağışladığını ve beni ikram edilenlerden kıldığını bilseydi!\" dedi."},{"n":28,"t":"Kendisinden sonra kavmi üzerine (onları cezalandırmak için) gökten hiçbir ordu indirmedik. İndirecek de değildik."},{"n":29,"t":"Sadece korkunç bir ses oldu. Bir anda sönüp gittiler."},{"n":30,"t":"Yazık o kullara! Kendilerine bir peygamber gelmezdi ki, onunla alay ediyor olmasınlar."},{"n":31,"t":"Kendilerinden önce nice nesilleri helâk ettiğimizi; onların artık kendilerine dönmeyeceklerini görmediler mi?"},{"n":32,"t":"Onların hepsi de mutlaka toplanıp (hesap için) huzurumuza çıkarılacaklardır."},{"n":33,"t":"Ölü toprak onlar için bir delildir. Biz, onu diriltir ve ondan taneler çıkarırız da onlardan yerler."},{"n":"34-35","t":"Meyvelerinden yesinler diye biz orada hurmalıklar, üzüm bağları var ettik ve içlerinde pınarlar fışkırttık. Bunları onların elleri yapmış değildir. Hâlâ şükretmeyecekler mi?"},{"n":36,"t":"Yerin bitirdiği şeylerden, insanların kendilerinden ve (daha) bilemedikleri (nice) şeylerden, bütün çiftleri yaratanın şanı yücedir."},{"n":37,"t":"Gece de onlar için bir delildir. Gündüzü ondan çıkarırız, bir de bakarsın karanlık içinde kalmışlardır."},{"n":38,"t":"Güneş de kendi yörüngesinde akıp gitmektedir. Bu, mutlak güç sahibi, hakkıyla bilen Allah’ın takdiri (düzenlemesi)dir."},{"n":39,"t":"Ayın dolaşımı için de konak yerleri (evreler) belirledik. Nihayet o, eğrilmiş kuru hurma dalı gibi olur."},{"n":40,"t":"Ne güneş aya yetişebilir, ne de gece gündüzü geçebilir. Her biri bir yörüngede yüzmektedir."},{"n":41,"t":"Onların soylarını dolu gemide taşımamız da onlar için bir delildir."},{"n":42,"t":"Biz, onlar için o gemi gibi binecekleri nice şeyler yarattık."},{"n":43,"t":"Biz istesek onları suda boğarız da kendileri için ne imdat çağrısı yapan olur, ne de kurtarılırlar."},{"n":44,"t":"Ancak tarafımızdan bir rahmet olarak ve bir süreye kadar daha yaşasınlar diye kurtarılırlar."},{"n":45,"t":"Onlara, \"Önünüzde ve arkanızda olan şeylerden (dünya ve ahirette göreceğiniz azaplardan) sakının ki size merhamet edilsin\" denildiğinde yüz çevirirler."},{"n":46,"t":"Onlara Rablerinin âyetlerinden bir âyet gelmez ki ondan yüz çeviriyor olmasınlar."},{"n":47,"t":"Onlara, \"Allah’ın sizi rızıklandırdığı şeylerden Allah yolunda harcayın\" denildiği zaman, inkâr edenler iman edenlere, \"Allah’ın, dilemiş olsa kendilerini doyurabileceği kimselere mi yedireceğiz? Siz ancak apaçık bir sapıklık içindesiniz\" derler."},{"n":48,"t":"\"Eğer doğru söyleyenlerseniz, bu tehdit ne zaman gelecek?\" diyorlar."},{"n":49,"t":"Onlar ancak, çekişip dururlarken kendilerini yakalayacak korkunç bir ses bekliyorlar."},{"n":50,"t":"Artık ne birbirlerine tavsiyede bulunabilirler, ne de ailelerine dönebilirler."},{"n":51,"t":"Sûra üfürülür. Bir de bakarsın, kabirlerden çıkmış, Rablerine doğru akın akın gitmektedirler."},{"n":52,"t":"Şöyle derler: \"Vay başımıza gelene! Kim bizi diriltip mezarımızdan çıkardı? Bu, Rahman’ın vaad ettiği şeydir. Peygamberler doğru söylemişler.\""},{"n":53,"t":"Sadece korkunç bir ses olur. Bir de bakarsın, hepsi birden toplanıp huzurumuza çıkarılmışlardır."},{"n":54,"t":"O gün kimseye, hiç mi hiç zulmedilmez. Size ancak işlemekte olduğunuz şeylerin karşılığı verilir."},{"n":55,"t":"Şüphesiz cennetlikler o gün nimetlerle meşguldürler, zevk sürerler."},{"n":56,"t":"Onlar ve eşleri gölgelerde koltuklara yaslanmaktadırlar."},{"n":57,"t":"Onlar için orada meyveler vardır. Onlar için diledikleri her şey vardır."},{"n":58,"t":"Çok merhametli olan Rab’den bir söz olarak (kendilerine) \"Selâm\" (vardır)."},{"n":59,"t":"(Allah, şöyle der:) \"Ey suçlular! Ayrılın bu gün!\""},{"n":"60-61","t":"\"Ey Âdemoğulları! Ben, size, şeytana kulluk etmeyin. Çünkü o, sizin için apaçık bir düşmandır. Bana kulluk edin. İşte bu dosdoğru yoldur, diye emretmedim mi?\""},{"n":62,"t":"\"Andolsun, o sizden pek çok nesli saptırmıştı. Hiç düşünmüyor muydunuz?\""},{"n":63,"t":"\"İşte bu, tehdit edildiğiniz cehennemdir.\""},{"n":64,"t":"\"İnkâr ettiğinizden dolayı bugün girin oraya!\""},{"n":65,"t":"O gün biz onların ağızlarını mühürleriz. Elleri bize konuşur, ayakları da kazandıklarına şahitlik eder."},{"n":66,"t":"Eğer dileseydik, onların gözlerini büsbütün kör ederdik de (bu hâlde) yola koyulmak için didişirlerdi. Fakat nasıl görecekler ki?!"},{"n":67,"t":"Yine eğer dileseydik, oldukları yerde başka yaratıklara dönüştürürdük de ne ileri gidebilirler, ne geri dönebilirlerdi."},{"n":68,"t":"Kime uzun ömür verirsek, onu yaratılış itibariyle tersine çeviririz (gücünü azaltırız). Hâlâ düşünmeyecekler mi?"},{"n":69,"t":"Biz, o Peygamber’e şiir öğretmedik. Bu, ona yaraşmaz da. O(na verdiğimiz) ancak bir öğüt ve apaçık bir Kur’an’dır."},{"n":70,"t":"(Aklen ve fikren) diri olanları uyarması ve kâfirler hakkındaki o sözün (azabın) gerçekleşmesi için Kur’an’ı indirdik."},{"n":71,"t":"Görmediler mi ki, biz onlar için, ellerimizin (kudretimizin) eseri olan hayvanlar yarattık da onlar bu hayvanlara sahip oluyorlar."},{"n":72,"t":"Biz, o hayvanları kendilerine boyun eğdirdik. Onlardan bir kısmı binekleridir, bir kısmını da yerler."},{"n":73,"t":"Onlar için bu hayvanlarda (daha pek çok) yararlar ve içecekler vardır. Hâlâ şükretmeyecekler mi?"},{"n":74,"t":"Belki kendilerine yardım edilir diye Allah’ı bırakıp da ilâhlar edindiler."},{"n":75,"t":"Onlar, ilâhlar için (hizmete) hazır asker oldukları hâlde, ilâhlar onlara yardım edemezler."},{"n":76,"t":"(Ey Muhammed!) Artık onların sözü seni üzmesin. Çünkü biz, onların gizlediklerini de açığa vurduklarını da biliyoruz."},{"n":77,"t":"İnsan, bizim, kendisini az bir sudan (meniden) yarattığımızı görmedi mi ki, kalkmış apaçık bir düşman kesilmiştir."},{"n":78,"t":"Bir de kendi yaratılışını unutarak bize bir örnek getirdi. Dedi ki: \"Çürümüşlerken kemikleri kim diriltecek?\""},{"n":79,"t":"De ki: \"Onları ilk defa var eden diriltecektir. O, her yaratılmışı hakkıyla bilendir.\""},{"n":80,"t":"O, sizin için yeşil ağaçtan ateş yaratandır. Şimdi siz ondan yakıp duruyorsunuz."},{"n":81,"t":"Gökleri ve yeri yaratan Allah’ın, onların benzerini yaratmaya gücü yetmez mi? Evet yeter. O, hakkıyla yaratandır, hakkıyla bilendir."},{"n":82,"t":"Bir şeyi dilediği zaman, O’nun emri o şeye ancak \"Ol!\" demektir. O da hemen oluverir."},{"n":83,"t":"Her şeyin hükümranlığı elinde olan Allah’ın şanı yücedir! Siz yalnız O’na döndürüleceksiniz."}],[{"n":"1-4","t":"Saf bağlayıp duranlara, haykırarak sevk edenlere ve zikri (Allah’ın kelâmını) okuyanlara andolsun ki, sizin ilâhınız gerçekten bir tek ilâhtır."},{"n":5,"t":"O, göklerin, yerin ve ikisi arasındakilerin Rabbidir. Doğuların da (Batıların da) Rabbidir."},{"n":6,"t":"Biz, en yakın göğü zinetlerle, yıldızlarla donattık."},{"n":7,"t":"Onu itaatten çıkan her şeytandan koruduk."},{"n":"8-9","t":"Onlar, yüce topluluğu (ileri gelen melekler topluluğunu) dinleyemezler. Kovulmaları için her taraftan taşa tutulurlar. Onlar için sürekli bir azap da vardır."},{"n":10,"t":"Ancak onlardan söz kapan olur. Onu da delip geçen bir alev izler (ve yok eder)."},{"n":11,"t":"(Ey Muhammed!) Şimdi sen onlara sor: \"Kendilerini yaratmak mı daha zor, yoksa yarattığımız diğer şeyleri yaratmak mı?\" Şüphesiz biz onları yapışkan bir çamurdan yarattık."},{"n":12,"t":"Hayır, sen (onların hâline) şaştın, onlar ise alay ediyorlar."},{"n":13,"t":"Kendilerine öğüt verildiği zaman öğüt almıyorlar."},{"n":14,"t":"Bir mucize gördükleri zaman onu alaya alıyorlar."},{"n":15,"t":"(Dediler ki:) \"Bu bir büyüden başka bir şey değildir.\""},{"n":16,"t":"\"Gerçekten biz, ölüp bir toprak ve kemik yığını hâline geldikten sonra mı, biz mi tekrar diriltileceğiz?\""},{"n":17,"t":"\"Önceden gelip geçmiş atalarımız da mı?\""},{"n":18,"t":"De ki: \"Evet, hem de siz aşağılanmış kimseler olarak (diriltileceksiniz).\""},{"n":19,"t":"O ancak şiddetli bir sesten ibarettir. Bir de bakarsın ki onlar (diriltilmiş hazır) beklemektedirler."},{"n":20,"t":"Şöyle diyecekler: \"Vay başımıza gelene! Bu beklenen ceza günüdür.\""},{"n":21,"t":"Onlara, \"İşte bu, yalanlamakta olduğunuz hüküm ve ayırım günüdür\" denilir."},{"n":"22-24","t":"Allah, meleklere şöyle emreder: \"Zulmedenleri, eşlerini ve Allah’ı bırakıp da tapmakta olduklarını toplayın, onları cehennemin yoluna koyun ve onları tutuklayın. Çünkü onlar sorguya çekileceklerdir.\""},{"n":25,"t":"Onlara, \"Ne diye yardımlaşmıyorsunuz?\" denir."},{"n":26,"t":"Hayır, onlar bugün teslim olmuş kimselerdir."},{"n":27,"t":"Birbirlerine yönelip sorarlar (çekişirler)."},{"n":28,"t":"Şöyle derler: \"Siz bize sağdan gelirdiniz. Bize haktan yana görünürdünüz.\""},{"n":29,"t":"Diğerleri de onlara şöyle derler: \"Hayır, siz zaten mü’min kimseler değildiniz.\""},{"n":30,"t":"\"Bizim, sizin üzerinizde hiçbir hâkimiyetimiz yoktu. Hatta siz azgın bir kavimdiniz.\""},{"n":31,"t":"\"Artık Rabbimizin sözü (azap) bizim hakkımızda gerçekleşti. Biz onu mutlaka tadacağız.\""},{"n":32,"t":"\"Evet, biz sizi saptırdık. Çünkü biz de sapkın kimselerdik.\""},{"n":33,"t":"Artık onlar o gün azapta ortaktırlar."},{"n":34,"t":"İşte biz suçlulara böyle yaparız."},{"n":35,"t":"Çünkü onlar, kendilerine, \"Allah’tan başka hiçbir ilâh yoktur\" denildiği zaman, inanmayıp büyüklük taslıyorlardı."},{"n":36,"t":"\"Biz, deli bir şair için ilâhlarımızı mı terk edeceğiz?\" diyorlardı."},{"n":37,"t":"Hayır, öyle değil. O, hakkı getirmiş, (önceki) peygamberleri de tasdik etmiştir."},{"n":38,"t":"Şüphesiz siz mutlaka elem dolu azabı tadacaksınız."},{"n":39,"t":"Siz ancak işlediklerinizin karşılığı ile cezalandırılırsınız."},{"n":40,"t":"Ancak Allah’ın halis kulları başka."},{"n":"41-42","t":"İşte onlar için belli bir rızık, meyveler vardır. Onlar ikram gören kimselerdir."},{"n":43,"t":"Onlar Naîm cennetlerindedirler."},{"n":44,"t":"Koltuklar üzerinde karşılıklı olarak otururlar."},{"n":"45-46","t":"Onların etrafında cennet pınarından doldurulmuş, berrak ve içenlere lezzet veren kadehler dolaştırılır."},{"n":47,"t":"Onda baş döndürme özelliği yoktur. Onlar, onu içmekle sarhoş da olmazlar."},{"n":48,"t":"Yanlarında bakışlarını yalnızca kendilerine çevirmiş iri gözlü eşler vardır."},{"n":49,"t":"Sanki onlar (beyazlıklarıyla), saklanmış (gün yüzü görmemiş) yumurtalardır."},{"n":50,"t":"Derken birbirlerine yönelip sorarlar."},{"n":51,"t":"İçlerinden biri der ki: \"Benim bir arkadaşım vardı.\""},{"n":52,"t":"\"Sen de tekrar dirilmeyi tasdik edenlerden misin?\" derdi."},{"n":53,"t":"\"Gerçekten biz, ölüp bir toprak ve kemik yığını hâline geldikten sonra mı, biz mi hesaba çekileceğiz?\""},{"n":54,"t":"Konuşan o kimse, yanındakilere, \"Bakar mısınız, hâli ne oldu?\" der."},{"n":55,"t":"Kendisi de bakar ve onu cehennemin ortasında görür."},{"n":56,"t":"Ona şöyle der: \"Allah’a andolsun, neredeyse beni de helâk edecektin.\""},{"n":57,"t":"\"Rabbimin nimeti olmasaydı, mutlaka ben de cehenneme konulanlardan olmuştum.\""},{"n":"58-59","t":"\"Nasıl, ilk ölümümüzden başka ölmeyecek miymişiz? Bize azap edilmeyecek miymiş?\""},{"n":60,"t":"Şüphesiz bu (cennetteki nimetlere ulaşmak) büyük bir başarıdır."},{"n":61,"t":"Çalışanlar böylesi için çalışsınlar!"},{"n":62,"t":"Ziyafet olarak bu mu daha hayırlı, yoksa zakkum ağacı mı?"},{"n":63,"t":"Şüphesiz biz onu zalimler için bir imtihan aracı kıldık."},{"n":64,"t":"O, cehennemin dibinde biten bir ağaçtır."},{"n":65,"t":"Onun meyveleri sanki şeytanların kafalarıdır."},{"n":66,"t":"Cehennemlikler ondan yiyecekler ve onunla karınlarını dolduracaklardır."},{"n":67,"t":"Sonra onlar için bunun üstüne kaynar sudan karışık bir içecek vardır."},{"n":68,"t":"Sonra onların dönüşleri mutlaka cehennemedir."},{"n":69,"t":"Çünkü onlar babalarını sapık kimseler olarak buldular."},{"n":70,"t":"Kendileri de onların izinden koşa koşa gitmektedirler."},{"n":71,"t":"Andolsun, onlardan önce, evvelkilerin çoğu da sapmıştı."},{"n":72,"t":"Andolsun, biz onlara da uyarıcılar göndermiştik."},{"n":73,"t":"Bak, uyarılanların sonu nasıl oldu!"},{"n":74,"t":"Ancak Allah’ın ihlâslı kulları başka."},{"n":75,"t":"Andolsun, Nûh bize dua edip seslenmişti. Biz ne güzel cevap vereniz!"},{"n":76,"t":"Onu ve ailesini o büyük sıkıntıdan kurtardık."},{"n":77,"t":"Onun neslini yeryüzünde kalanlar kıldık."},{"n":78,"t":"Sonradan gelenler arasında ona güzel bir ad bıraktık."},{"n":79,"t":"Âlemler içinde Nûh’a selâm olsun!"},{"n":80,"t":"İşte biz iyilik yapanları böyle mükâfatlandırırız."},{"n":81,"t":"Çünkü o, bizim mü’min kullarımızdandı."},{"n":82,"t":"Sonra biz, diğerlerini suda boğduk."},{"n":83,"t":"Şüphesiz İbrahim de O’nun taraftarlarından idi."},{"n":84,"t":"Hani o, Rabbine temiz bir kalple gelmişti."},{"n":85,"t":"Hani babasına ve kavmine şöyle demişti: \"Siz neye tapıyorsunuz?\""},{"n":86,"t":"\"Allah’ı bırakıp da birtakım uydurma ilâhlar mı istiyorsunuz?\""},{"n":87,"t":"\"O hâlde, âlemlerin Rabbi hakkında görüşünüz nedir?\""},{"n":"88-89","t":"İbrahim, yıldızlara baktı ve \"Ben hastayım\" dedi."},{"n":90,"t":"Bunun üzerine arkalarını dönüp ondan uzaklaştılar."},{"n":91,"t":"İbrahim, onların putlarının tarafına gizlice gitti ve şöyle dedi: \"Yemez misiniz?\""},{"n":92,"t":"\"Ne diye konuşmuyorsunuz?\""},{"n":93,"t":"Derken üzerlerine yürüyüp onlara güçlü bir darbe indirdi."},{"n":94,"t":"Kavmi (telaş içinde) koşarak ona doğru geldi."},{"n":95,"t":"İbrahim, şöyle dedi: \"Yonttuğunuz putlara mı tapıyorsunuz?\""},{"n":96,"t":"\"Oysa Allah sizi de, yaptığınız şeyleri de yaratmıştır.\""},{"n":97,"t":"Kavmi, \"Onun için bir bina yapın, (içinde ateş yakın) ve onu ateşe atın\" dedi."},{"n":98,"t":"Böylece ona bir tuzak kurmak istediler. Biz de onları en alçak kimseler kıldık."},{"n":99,"t":"İbrahim, şöyle dedi: \"Ben Rabbime (O’nun emrettiği yere) gideceğim. O, bana yol gösterecektir.\""},{"n":100,"t":"\"Ey Rabbim! Bana salihlerden olacak bir çocuk bağışla.\""},{"n":101,"t":"Biz de ona uysal bir oğul müjdeledik."},{"n":102,"t":"Çocuk kendisiyle birlikte koşup yürüyecek yaşa gelince İbrahim ona, \"Yavrum, ben rüyamda seni boğazladığımı gördüm. Düşün bakalım, ne dersin?\" dedi. O da, \"Babacığım, emrolunduğun şeyi yap. İnşaallah beni sabredenlerden bulacaksın\" dedi."},{"n":"103-104","t":"Nihayet her ikisi de (Allah’ın emrine) boyun eğip, İbrahim de onu (boğazlamak için) yüz üstü yere yatırınca ona, şöyle seslendik: \"Ey İbrahim!\""},{"n":105,"t":"\"Gördüğün rüyanın hükmünü yerine getirdin. Şüphesiz biz iyilik yapanları böyle mükâfatlandırırız.\""},{"n":106,"t":"\"Şüphesiz bu apaçık bir imtihandır.\""},{"n":107,"t":"Biz, (İbrahim’e) büyük bir kurbanlık vererek onu (İsmail’i) kurtardık."},{"n":108,"t":"Sonradan gelenler arasında ona güzel bir ad bıraktık."},{"n":109,"t":"İbrahim’e selâm olsun."},{"n":110,"t":"İyilik yapanları işte böyle mükâfatlandırırız."},{"n":111,"t":"Çünkü o mü’min kullarımızdandı."},{"n":112,"t":"Biz onu salihlerden bir peygamber olarak İshak ile de müjdeledik."},{"n":113,"t":"Onu da İshak’ı da uğurlu kıldık. Her ikisinin nesillerinden iyilik yapanlar da vardı, kendine apaçık zulmedenler de."},{"n":114,"t":"Andolsun, biz Mûsâ’ya ve Hârûn’a da lütufta bulunduk."},{"n":115,"t":"Onları ve kavimlerini o büyük sıkıntıdan kurtardık."},{"n":116,"t":"Onlara yardım ettik de onlar galip gelenler oldular."},{"n":117,"t":"Biz onlara (hükümlerimizi) açıklayan Kitab’ı (Tevrat’ı) verdik."},{"n":118,"t":"Onları doğru yola ilettik."},{"n":119,"t":"Sonradan gelenler arasında onlara güzel birer ad bıraktık."},{"n":120,"t":"Mûsâ’ya ve Hârûn’a selâm olsun."},{"n":121,"t":"Şüphesiz biz iyilik yapanları böyle mükâfatlandırırız."},{"n":122,"t":"Çünkü onlar mü’min kullarımızdan idiler."},{"n":123,"t":"Şüphesiz İlyas da peygamberlerden idi."},{"n":124,"t":"Hani kavmine şöyle demişti: \"Allah’a karşı gelmekten sakınmaz mısınız?\""},{"n":"125-126","t":"\"Yaratıcıların en güzelini, sizin ve geçmiş atalarınızın Rabbi olan Allah’ı bırakarak \"Ba’l’e mi tapıyorsunuz?\""},{"n":127,"t":"Onu yalanladılar. Bu sebeple onlar (cehenneme) götürüleceklerdir."},{"n":128,"t":"Ancak Allah’ın ihlâslı kulları başka."},{"n":129,"t":"Sonradan gelenler içerisinde ona güzel bir ad bıraktık."},{"n":130,"t":"İlyas’a selâm olsun."},{"n":131,"t":"Şüphesiz biz iyilik yapanları böyle mükâfatlandırırız."},{"n":132,"t":"Çünkü o bizim mü’min kullarımızdandı."},{"n":133,"t":"Şüphesiz Lût da peygamberlerdendi."},{"n":"134-135","t":"Hani biz onu ve geride kalanlar arasındaki yaşlı bir kadın (kâfir olan eşi) dışında bütün ailesini kurtarmıştık."},{"n":136,"t":"Sonra da diğerlerini yok ettik."},{"n":"137-138","t":"Şüphesiz sizler (yolculuklarınız sırasında) sabah akşam onların (harap olmuş) yurtlarına uğrayıp duruyorsunuz. Hâlâ düşünmeyecek misiniz?"},{"n":139,"t":"Şüphesiz Yûnus da peygamberlerdendi."},{"n":140,"t":"Hani o kaçıp yüklü gemiye binmişti."},{"n":141,"t":"Gemidekilerle kur’a çekmiş ve kaybedenlerden olmuştu."},{"n":142,"t":"Böylece, Yûnus kendini kınayıp dururken balık onu yuttu."},{"n":"143-144","t":"Eğer o, Allah’ı tespih edip yüceltenlerden olmasaydı, mutlaka insanların diriltileceği güne kadar balığın karnında kalırdı."},{"n":145,"t":"Derken biz onu hasta bir hâlde sahile attık."},{"n":146,"t":"Üzerine geniş yapraklı bir ağaç bitirdik."},{"n":147,"t":"Biz onu yüz bin, yahut daha fazla insana peygamber olarak gönderdik."},{"n":148,"t":"Nihayet onlar iman ettiler. Biz de onları bir süreye kadar geçindirdik."},{"n":149,"t":"Ey Muhammed! Onlara sor: Kız çocukları Rabbinin de, erkek çocukları onların mı?"},{"n":150,"t":"Yoksa biz melekleri dişi olarak yaratmışız da onlar şahid mi bulunuyorlarmış?"},{"n":"151-152","t":"İyi bilin ki onlar kendi uydurmaları olarak, \"Allah çocuk sahibi oldu\" diyorlar. Onlar elbette yalan söylüyorlar."},{"n":153,"t":"Yoksa Allah kızları erkeklere tercih mi etti?"},{"n":154,"t":"Neyiniz var? Nasıl hüküm veriyorsunuz!"},{"n":155,"t":"Hiç düşünmüyor musunuz?"},{"n":156,"t":"Yoksa sizin apaçık bir deliliniz mi var?"},{"n":157,"t":"Eğer doğru söyleyen kimseler iseniz getirin (bu delili içeren) kitabınızı!"},{"n":158,"t":"Allah ile cinler arasında da nesep bağı kurdular. Oysa cinler de kendilerinin Allah’ın huzuruna getirileceklerini bilirler."},{"n":159,"t":"Allah, onların nitelendirdiği şeylerden uzaktır, yücedir."},{"n":160,"t":"Ancak Allah’ın ihlâslı kulları bunlar gibi değildir."},{"n":"161-163","t":"(Ey müşrikler!) Ne siz ve ne de taptıklarınız, cehenneme gireceklerden başkasını kandırıp Allah’ın yolundan saptırabilirsiniz."},{"n":164,"t":"(Melekler derler ki:) \"Bizim her birimizin bilinen bir makamı vardır.\""},{"n":165,"t":"\"Şüphesiz biz (orada) saf duranlarız.\""},{"n":166,"t":"\"Şüphesiz biz (Allah’ı) tespih edip yüceltenleriz.\""},{"n":"167-169","t":"Müşrikler) şunu da söylüyorlardı: \"Eğer yanımızda öncekilere verilen kitaplardan bir kitap olsaydı, elbette biz ihlâslı kullar olurduk.\""},{"n":170,"t":"Fakat (kitap gelince) onu inkâr ettiler. Yakında (sonlarının ne olacağını) bilecekler."},{"n":171,"t":"Andolsun, peygamber olarak gönderilen kullarımız hakkında şu sözümüz geçmişti:"},{"n":172,"t":"\"Onlara mutlaka yardım edilecektir.\""},{"n":173,"t":"\"Şüphesiz ordularımız galip gelecektir.\""},{"n":174,"t":"O hâlde, bir süreye kadar onlardan yüz çevir"},{"n":175,"t":"Gözetle onları, yakında onlar da görecekler."},{"n":176,"t":"Yoksa onlar azabımızı acele mi istiyorlar?"},{"n":177,"t":"Fakat azabımız onların yurtlarına indiğinde, o uyarılmış olanların sabahı ne kötü olur!"},{"n":178,"t":"Ey Muhammed! Bir süreye kadar onlardan yüz çevir."},{"n":179,"t":"(Bekle ve) gör. Onlar da yakında görecekler."},{"n":180,"t":"Senin Rabbin; kudret ve şeref sahibi olan Rab, onların nitelendirdiği şeylerden uzaktır, yücedir."},{"n":181,"t":"Peygamberlere selâm olsun."},{"n":182,"t":"Hamd, âlemlerin Rabbi olan Allah’a mahsustur."}],[{"n":1,"t":"Sâd. O şanlı, şerefli Kur’an’a andolsun (ki o, Allah sözüdür)."},{"n":2,"t":"Fakat inkâr edenler bir büyüklenme ve ayrılık içindedirler."},{"n":3,"t":"Biz onlardan önce nice nesilleri helâk ettik. Onlar da feryat ettiler, ama artık kurtuluş zamanı değildi."},{"n":4,"t":"Kâfirler, kendilerine içlerinden bir uyarıcının gelmesine şaştılar ve şöyle dediler: \"Bu, yalancı bir sihirbazdır.\""},{"n":5,"t":"\"İlâhları bir tek ilâh mı yaptı? Gerçekten bu çok tuhaf bir şey!\""},{"n":"6-8","t":"İçlerinden ileri gelenler, \"Gidin, ilâhlarınıza tapmaya devam edin. İşte bu istenen şeydir. Biz bunu son dinde (en son dinî inanışlarda) duymadık. Bu ancak bir uydurmadır. O zikir (Kur’an) içimizden ona mı indirildi?\" diyerek kalkıp gittiler. Hayır, onlar benim Zikrimden (Kur’an’dan) şüphe içindedirler. Hayır, henüz azabımı tatmadılar."},{"n":9,"t":"Yoksa mutlak güç sahibi ve çok bağışlayan Rabbinin rahmet hazineleri onların yanında mıdır?"},{"n":10,"t":"Yoksa göklerin, yerin ve ikisi arasındakilerin hükümranlığı onların mıdır? Öyle ise sebeplere yapışarak yükselsinler (bakalım!)"},{"n":11,"t":"Onlar, çeşitli gruplardan oluşmuş ve şuracıkta bozguna uğrayacak derme çatma bir ordudur."},{"n":"12-13","t":"Onlardan önce de Nûh kavmi, Âd kavmi, kazıklar sahibi Firavun, Semûd kavmi, Lût kavmi ve Eyke halkı da Peygamberleri yalanlamışlardı. İşte onlar da (böyle) gruplardı."},{"n":14,"t":"(O grupların) her biri peygamberleri yalanladı da onları cezalandırmam hak oldu."},{"n":15,"t":"Bunlar da (müşrikler de) ancak (vakti gelince) asla geri kalmayacak korkunç bir ses bekliyorlar."},{"n":16,"t":"Müşrikler (alay ederek) şöyle dediler: \"Ey Rabbimiz! Hesap gününden önce payımızı hemen ver!\""},{"n":17,"t":"Ey Muhammed! Onların söylediklerine karşı sabret. Güçlü kulumuz Dâvûd’u hatırla. O, Allah’a çok yönelen bir kimse idi."},{"n":"18-19","t":"Kendisiyle birlikte tesbih etsinler diye biz, dağları ve toplanıp gelen kuşları Dâvûd’un emrine verdik. Onların her biri Allah’a yönelmişlerdi."},{"n":20,"t":"Biz Davud’un mülkünü güçlendirdik, ona hikmet ve hakla batılı ayıran söz (hüküm verme) yeteneği verdik."},{"n":21,"t":"Sana davacıların haberi geldi mi? Hani onlar duvarı aşarak mabede girmişlerdi."},{"n":22,"t":"Hani Dâvûd’un yanına girmişlerdi de Dâvûd onlardan korkmuştu. Onlar, \"Korkma! Biz, iki davacı grubuz. Birimiz diğerine haksızlık etmiştir. Aramızda adaletle hükmet. Zulmetme ve bizi hak yola ilet\" dediler."},{"n":23,"t":"İçlerinden biri şöyle dedi: \"Bu benim kardeşimdir. Onun doksan dokuz koyunu var. Benim ise bir tek koyunum var. Böyle iken ‘Onu da bana ver’ dedi ve tartışmada beni bastırdı.\""},{"n":24,"t":"Davud dedi ki: \"Andolsun, senin koyununu kendi koyunlarına katmak istemek suretiyle sana zulmetmiştir. Esasen ortakların pek çoğu birbirine haksızlık eder. Ancak iman edip salih ameller işleyenler başka. Onlar da pek azdır.\" Dâvûd, bizim kendisini imtihan ettiğimizi anladı. Derken Rabbinden bağışlama diledi, eğilerek secdeye kapandı ve Allah’a yöneldi."},{"n":25,"t":"Biz de bunu ona bağışladık. Şüphesiz katımızda onun için bir yakınlık ve dönüp geleceği güzel bir yer vardır."},{"n":26,"t":"Ona dedik ki: \"Ey Dâvûd! Gerçekten biz seni yeryüzünde halife yaptık. İnsanlar arasında hak ile hüküm ver. Nefis arzusuna uyma, yoksa seni Allah’ın yolundan saptırır. Allah’ın yolundan sapanlar için hesap gününü unutmaları sebebiyle şiddetli bir azap vardır.\""},{"n":27,"t":"Biz göğü, yeri ve ikisi arasındakileri boş yere yaratmadık. Bu (yaratılanların boş yere yaratıldığı iddiası) inkâr edenlerin zannıdır. Cehennem ateşinden dolayı vay inkâr edenlerin hâline!"},{"n":28,"t":"Yoksa biz iman edip salih ameller işleyenleri, yeryüzünde fesat çıkaranlar gibi mi tutacağız? Yoksa Allah’a karşı gelmekten sakınanları yoldan çıkan arsızlar gibi mi tutacağız?"},{"n":29,"t":"Bu Kur’an, âyetlerini düşünsünler ve akıl sahipleri öğüt alsınlar diye sana indirdiğimiz mübarek bir kitaptır."},{"n":30,"t":"Dâvûd’a Süleyman’ı bağışladık. O ne güzel kuldu! Şüphesiz o, Allah’a çok yönelen bir kimse idi."},{"n":31,"t":"Hani ona akşamüstü bir ayağını tırnağı üstüne dikip üç ayağının üzerinde duran çalımlı ve soylu atlar sunulmuştu."},{"n":"32-33","t":"Süleyman, \"Gerçekten ben malı, Rabbimi anmamı sağladığından dolayı çok severim\" dedi. Nihayet gözden kaybolup gittikleri zaman, \"Onları bana geri getirin\" dedi. (Atlar gelince de) bacaklarını ve boyunlarını okşamaya başladı."},{"n":34,"t":"Andolsun, biz Süleyman’ı imtihan ettik. Tahtının üstüne bir ceset bıraktık. Sonra tövbe edip bize yöneldi."},{"n":35,"t":"Süleyman, \"Ey Rabbim! Beni bağışla. Bana, benden sonra kimseye lâyık olmayacak bir mülk (hükümranlık) bahşet! Şüphesiz sen çok bahşedicisin!\" dedi."},{"n":36,"t":"Biz de rüzgârı onun buyruğuna verdik. Rüzgâr, onun emriyle dilediği yere hafif hafif eserdi."},{"n":"37-38","t":"Bina ustası olan ve dalgıçlık yapan her bir şeytanı, bukağılara bağlı olarak diğerlerini de, onun emrine verdik."},{"n":39,"t":"\"İşte bu bizim ihsanımızdır. Artık sen de (istediğine) hesapsızca ver yahut verme\" dedik."},{"n":40,"t":"Şüphesiz katımızda onun için bir yakınlık ve dönüp geleceği güzel bir yer vardır."},{"n":41,"t":"(Ey Muhammed!) Kulumuz Eyyûb’u da an. Hani o, Rabbine, \"Şeytan bana bir yorgunluk ve azap dokundurdu\" diye seslenmişti."},{"n":42,"t":"Biz de ona, \"Ayağını yere vur! İşte yıkanacak ve içecek soğuk bir su\" dedik."},{"n":43,"t":"Biz ona tarafımızdan bir rahmet ve akıl sahiplerine bir öğüt olmak üzere ailesini ve onlarla birlikte bir o kadarını bahşettik."},{"n":44,"t":"Şöyle dedik: \"Eline bir demet sap al ve onunla vur, yeminini bozma.\" Gerçekten biz Eyyûb’u sabreden bir kimse olarak bulduk. O ne güzel bir kuldu! O, Allah’a çok yönelen bir kimse idi."},{"n":45,"t":"(Ey Muhammed!) Güçlü ve basiretli kullarımız İbrahim’i, İshak’ı ve Yakub’u da an."},{"n":46,"t":"Şüphesiz biz onları, ahiret yurdunu düşünme özelliği ile (temizleyip) ihlâslı kimseler kıldık."},{"n":47,"t":"Şüphesiz onlar, bizim katımızda hayırlı, seçkin kimselerdendir."},{"n":48,"t":"(Ey Muhammed!) İsmail, el-Yesa’ ve Zülkifl’i de an. Onların her biri iyi kimselerdi."},{"n":"49-50","t":"Bu bir öğüttür. Allah’a karşı gelmekten sakınanlar için elbette güzel bir dönüş yeri, kapıları kendilerine açılmış olarak Adn cennetleri vardır."},{"n":51,"t":"Onlar orada koltuklara yaslanmış olarak pek çok meyveler ve içecekler isterler."},{"n":52,"t":"Yanlarında gözlerini kendilerinden ayırmayan yaşıt eşler vardır."},{"n":53,"t":"İşte bunlar, hesap günü için size vaad edilenlerdir."},{"n":54,"t":"İşte bu bizim verdiğimiz rızıktır. Ona asla tükenme yoktur."},{"n":"55-56","t":"İşte böyle! Şüphesiz azgınlar için elbette kötü bir dönüş yeri, cehennem vardır. Onlar oraya girerler. Orası ne kötü bir yataktır!"},{"n":57,"t":"İşte (azap), onu tatsınlar: Bir kaynar su ve bir irin."},{"n":58,"t":"O azaba benzer çeşit çeşit başka azaplar da vardır."},{"n":59,"t":"(Kendi aralarında şöyle derler:) \"İşte sizinle beraber cehenneme tıkılacak bir grup. Onlara rahat ve huzur olmasın! Şüphesiz onlar cehenneme gireceklerdir.\""},{"n":60,"t":"O grup da, \"Hayır, size rahat ve huzur olmasın. Bu cehennemi bizim önümüze siz sürdünüz. Orası ne kötü durak yeridir!\" der."},{"n":61,"t":"Şöyle derler: \"Ey Rabbimiz! Bunu bizim önümüze kim sürdüyse, cehennemde onun azabını bir kat daha artır.\""},{"n":62,"t":"Yine şöyle derler: \"Dünyada kendilerini kötü saydığımız adamları acaba neden göremiyoruz?\""},{"n":63,"t":"\"(Cehennemlik değillerdi de) biz onları alaya mı almış olduk, yoksa (buradalar da) gözlerimizden mi kaçtılar?\""},{"n":64,"t":"Şüphesiz bu, cehennemliklerin birbirleriyle çekişmesi kesin bir gerçektir."},{"n":65,"t":"(Ey Muhammed!) De ki: \"Ben ancak bir uyarıcıyım. Her şey üzerinde mutlak otorite sahibi olan bir Allah’tan başka hiçbir ilâh yoktur.\""},{"n":66,"t":"\"O, göklerin, yerin ve ikisi arasındakilerin Rabbidir. Mutlak güç sahibidir, çok bağışlayandır.\""},{"n":67,"t":"De ki: \"Bu Kur’an, büyük bir haberdir.\""},{"n":68,"t":"\"Siz ise ondan yüz çeviriyorsunuz.\""},{"n":69,"t":"\"Aralarında tartıştıkları sırada, yüce topluluğa (ileri gelen melekler topluluğuna) dair benim hiçbir bilgim yoktu.\""},{"n":70,"t":"\"Bana ancak, benim sadece bir uyarıcı olduğum vahyediliyor.\""},{"n":71,"t":"Hani, Rabbin meleklere şöyle demişti: \"Muhakkak ben çamurdan bir insan yaratacağım.\""},{"n":72,"t":"\"Onu şekillendirip içine ruhumdan üflediğim zaman onun için saygı ile eğilin.\""},{"n":73,"t":"Derken bütün melekler topluca saygı ile eğildiler."},{"n":74,"t":"Ancak İblis eğilmedi. O büyüklük tasladı ve kâfirlerden oldu."},{"n":75,"t":"Allah, \"Ey İblis! Ellerimle yarattığıma saygı ile eğilmekten seni ne alıkoydu? Büyüklük mü tasladın, yoksa üstünlerden mi oldun?\" dedi."},{"n":76,"t":"İblis, \"Ben ondan daha hayırlıyım. Beni ateşten yarattın, onu ise çamurdan yarattın\" dedi."},{"n":77,"t":"Allah, şöyle dedi: \"Öyle ise çık oradan (cennetten), çünkü sen kovuldun.\""},{"n":78,"t":"\"Şüphesiz benim lânetim hesap ve ceza gününe kadar senin üzerinedir.\""},{"n":79,"t":"İblis, \"Ey Rabbim! Öyle ise bana insanların diriltilecekleri güne kadar mühlet ver\" dedi."},{"n":"80-81","t":"Allah, şöyle dedi: \"Sen o bilinen vakte (kıyamet gününe) kadar mühlet verilenlerdensin.\""},{"n":"82-83","t":"İblis, \"Senin şerefine andolsun ki, içlerinden ihlâslı kulların hariç, elbette onların hepsini azdıracağım\" dedi."},{"n":84,"t":"Allah, şöyle dedi: \"İşte bu gerçektir. Ben de gerçeği söylüyorum:\""},{"n":85,"t":"\"Andolsun, cehennemi seninle ve onlardan sana uyanların hepsiyle dolduracağım.\""},{"n":86,"t":"(Ey Muhammed!) De ki: \"Bundan (tebliğ görevinden) dolayı sizden hiçbir ücret istemiyorum. Ben kendiliğinden yükümlülük altına girenlerden değilim.\""},{"n":87,"t":"\"Bu Kur’an, âlemler için ancak bir öğüttür.\""},{"n":88,"t":"\"Onun haberlerinin doğruluğunu bir süre sonra mutlaka öğreneceksiniz.\""}],[{"n":1,"t":"Kitab’ın indirilmesi mutlak güç sahibi, hüküm ve hikmet sahibi Allah tarafındandır."},{"n":2,"t":"(Ey Muhammed!) Şüphesiz biz o Kitab’ı sana hak olarak indirdik. Öyle ise sen de dini Allah’a has kılarak O’na kulluk et."},{"n":3,"t":"İyi bilin ki, halis din yalnız Allah’ındır. O’nu bırakıp da başka dostlar edinenler, \"Biz onlara sadece, bizi Allah’a daha çok yaklaştırsınlar diye ibadet ediyoruz\" diyorlar. Şüphesiz Allah, ayrılığa düştükleri şeyler konusunda aralarında hüküm verecektir. Şüphesiz Allah, yalancı ve nankör olanları doğru yola iletmez."},{"n":4,"t":"Eğer Allah bir çocuk edinmek isteseydi, yarattıklarından dilediğini seçerdi. O, bundan uzaktır, yücedir. O, bir ve her şey üzerinde mutlak otorite sahibi olan Allah’tır."},{"n":5,"t":"Gökleri ve yeri hak ve hikmete uygun olarak yaratmıştır. Geceyi gündüzün üzerine örtüyor, gündüzü de gecenin üzerine örtüyor. Güneşi ve ayı da koyduğu kanunlara boyun eğdirmiştir. Bunların her biri belli bir zamana kadar akıp gitmektedir. İyi bilin ki O, mutlak güç sahibidir, çok bağışlayandır."},{"n":6,"t":"O, sizi bir tek nefisten yarattı. Sonra ondan eşini var etti. Sizin için hayvanlardan (erkek ve dişi olarak) sekiz eş yarattı. Sizi annelerinizin karnında bir yaratılıştan öbürüne geçirerek üç (kat) karanlık içinde oluşturuyor. İşte Rabbiniz olan Allah budur. Mülk (mutlak hâkimiyet) yalnız O’nundur. O’ndan başka hiçbir ilâh yoktur. O hâlde, nasıl oluyor da haktan döndürülüyorsunuz?"},{"n":7,"t":"Eğer inkâr ederseniz, şüphesiz ki Allah sizin iman etmenize muhtaç değildir. Ama kullarının inkâr etmesine razı olmaz. Eğer şükrederseniz sizin için buna razı olur. Hiçbir günahkâr başka bir günahkârın yükünü yüklenmez. Sonra dönüşünüz ancak Rabbinizedir. O da size yaptıklarınızı haber verir. Çünkü O, göğüslerin özünü (kalplerde olanı) hakkıyla bilir."},{"n":8,"t":"İnsana bir zarar dokunduğu zaman Rabbine yönelerek O’na yalvarır. Sonra kendi tarafından ona bir nimet verdiği zaman daha önce O’na yalvardığını unutur ve Allah’ın yolundan saptırmak için O’na eşler koşar. De ki: \"Küfrünle az bir süre yaşayıp geçin! Şüphesiz sen cehennemliklerdensin.\""},{"n":9,"t":"(Böyle bir kimse mi Allah katında makbuldür,) yoksa gece vakitlerinde, secde hâlinde ve ayakta, ahiretten korkarak ve Rabbinin rahmetini umarak itaat ve kulluk eden mi? De ki: \"Hiç bilenlerle bilmeyenler bir olur mu?\" Ancak akıl sahipleri öğüt alırlar."},{"n":10,"t":"(Ey Muhammed!) Bizim adımıza de ki: \"Ey iman eden kullarım! Rabbinize karşı gelmekten sakının. Bu dünyada iyilik yapanlar için (ahirette) bir iyilik vardır. Allah’ın yeryüzü geniştir. Sabredenlere mükâfatları elbette hesapsız olarak verilir.\""},{"n":11,"t":"De ki: \"Şüphesiz bana, dini Allah’a has kılarak O’na ibadet etmem emredildi.\""},{"n":12,"t":"\"Bana, müslümanların ilki olmam da emredildi.\""},{"n":13,"t":"De ki: \"Eğer ben Rabbime isyan edersem, şüphesiz büyük bir günün azabından korkarım.\""},{"n":14,"t":"De ki: \"Ben dinimi Allah’a has kılarak sadece O’na ibadet ediyorum.\""},{"n":15,"t":"\"Siz de Allah’tan başka dilediğiniz şeylere ibadet edin!\" De ki: \"Şüphesiz hüsrana uğrayanlar, kıyamet gününde kendilerini ve ailelerini hüsrana sokanlardır. İyi bilin ki bu, apaçık hüsranın ta kendisidir.\""},{"n":16,"t":"Onlar için üstlerinde ateşten katmanlar, altlarında (ateşten) katmanlar vardır. İşte Allah, kullarını bununla korkutur. Ey kullarım, bana karşı gelmekten sakının."},{"n":17,"t":"Tâğût’tan, ona kulluk etmekten kaçınan ve içtenlikle Allah’a yönelenler için müjde vardır. O hâlde, kullarımı müjdele!"},{"n":18,"t":"Sözü dinleyip de onun en güzeline uyanlar var ya, işte onlar Allah’ın hidayete erdirdiği kimselerdir. İşte onlar akıl sahiplerinin ta kendileridir."},{"n":19,"t":"Hakkında azap sözü (hükmü) gerçekleşenler, hiç onlar gibi olur mu? Cehennemlikleri sen mi kurtaracaksın?"},{"n":20,"t":"Fakat Rabbine karşı gelmekten sakınanlar için (cennette) üst üste yapılmış ve altlarından ırmaklar akan köşkler vardır. Allah, gerçek bir vaadde bulunmuştur. Allah, va’dinden dönmez."},{"n":21,"t":"Görmedin mi, Allah gökten su indirdi de onu yeryüzündeki kaynaklara ulaştırdı. Sonra onunla renkleri çeşit çeşit ekinler çıkarıyor. Sonra ekinler kuruyor da onları sapsarı kesilmiş görüyorsun. Sonra da Allah onları kurumuş çer çöp hâline getirir. Şüphesiz ki bunda akıl sahipleri için bir öğüt vardır."},{"n":22,"t":"Allah’ın, göğsünü İslâm’a açtığı, böylece Rabbinden bir nur üzere bulunan kimse, kalbi imana kapalı kimse gibi midir? Allah’ın zikrine karşı kalpleri katı olanların vay hâline! İşte onlar açık bir sapıklık içindedirler."},{"n":23,"t":"Allah, sözün en güzelini; âyetleri, (güzellikte) birbirine benzeyen ve (hükümleri, öğütleri, kıssaları) tekrarlanan bir kitap olarak indirmiştir. Rablerinden korkanların derileri (vücutları) ondan dolayı gerginleşir. Sonra derileri de (vücutları da) kalpleri de Allah’ın zikrine karşı yumuşar. İşte bu Kur’an Allah’ın hidayet rehberidir. Onunla dilediğini doğru yola iletir. Allah, kimi saptırırsa artık onun için hiçbir yol gösterici yoktur."},{"n":24,"t":"Kıyamet günü kötü azaba karşı yüzüyle korunan kimse, (o gün) azaptan emin olan kimse gibi midir? Zalimlere, \"Kazandıklarınızı tadın\" denir."},{"n":25,"t":"Onlardan öncekiler de yalanladılar ve azap kendilerine farkına varamadıkları bir yerden geldi."},{"n":26,"t":"Böylece Allah dünya hayatında onlara zilleti tattırdı. Elbette ki ahiret azabı daha büyüktür. Keşke bilselerdi!"},{"n":27,"t":"Andolsun, öğüt alsınlar diye biz bu Kur’an’da insanlar için her türlü misali verdik."},{"n":28,"t":"Biz onu, Allah’a karşı gelmekten sakınsınlar diye hiçbir eğriliği bulunmayan Arapça bir Kur’an olarak indirdik."},{"n":29,"t":"Allah, birbiriyle çekişen ortak sahipleri bulunan bir (köle) adam ile yalnızca bir kişiye ait olan bir (köle) adamı örnek verdi. Bu iki adamın durumu hiç, bir olur mu? Hamd Allah’a mahsustur. Hayır, onların çoğu bilmiyorlar."},{"n":30,"t":"(Ey Muhammed!) Şüphesiz sen öleceksin ve şüphesiz onlar da öleceklerdir."},{"n":31,"t":"Sonra şüphesiz siz kıyamet günü Rabbinizin huzurunda muhakeme edileceksiniz."},{"n":32,"t":"Kim, Allah’a karşı yalan uyduran ve kendisine geldiğinde, doğruyu (Kur’an’ı) yalanlayandan daha zalimdir? Cehennemde kâfirler için kalacak bir yer mi yok!?"},{"n":33,"t":"Dosdoğru Kur’an’ı getiren ile onu tasdik edenler var ya, işte onlar Allah’a karşı gelmekten sakınanlardır."},{"n":34,"t":"Onlar için Rableri katında diledikleri her şey vardır. İşte bu, iyilik yapanların mükâfatıdır."},{"n":35,"t":"Allah, işlediklerinin en kötüsünü örtmek ve onlara yaptıklarının en güzeli ile karşılık vermek için (onları böyle mükâfatlandırdı)."},{"n":36,"t":"Allah, kuluna yetmez mi? Seni O’ndan (Allah’tan) başkalarıyla korkutmaya çalışıyorlar. Allah, kimi saptırırsa artık onun için bir yol gösterici yoktur."},{"n":37,"t":"Allah, kimi de doğru yola iletirse artık onu saptıracak hiç kimse yoktur. Allah mutlak güç sahibi, intikam sahibi değil midir?"},{"n":38,"t":"Andolsun, eğer onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan elbette, \"Allah\", derler. De ki: \"Peki söyleyin bakalım? Allah’ı bırakıp da ibadet ettikleriniz var ya; eğer Allah bana herhangi bir zarar dokundurmak isterse, onlar Allah’ın dokundurduğu zararı kaldırabilirler mi? Yahut Allah bana bir rahmet dilese, onlar O’nun rahmetini engelleyebilirler mi?\" De ki: \"Allah bana yeter. Tevekkül edenler ancak O’na tevekkül ederler.\""},{"n":"39-40","t":"De ki: \"Ey kavmim! Elinizden geleni yapın. Ben de yapacağım. Kişiyi rezil edici azabın kime geleceğini ve sürekli azabın kimin başına ineceğini yakında bileceksiniz!\""},{"n":41,"t":"(Ey Muhammed!) Biz sana Kitab’ı (Kur’an’ı) insanlar için, hak olarak indirdik. Kim doğru yola girerse, kendisi için girmiş olur. Kim de saparsa, ancak kendi aleyhine sapar. Sen onlara vekil değilsin."},{"n":42,"t":"Allah, (ölen) insanların ruhlarını öldüklerinde, ölmeyenlerinkini de uykularında alır. Ölümüne hükmettiklerinin ruhlarını tutar, diğerlerini belli bir süreye (ömürlerinin sonuna) kadar bırakır. Şüphesiz bunda düşünen bir toplum için elbette ibretler vardır."},{"n":43,"t":"Yoksa Allah’tan başka şefaatçiler mi edindiler? De ki: \"Hiçbir şeye güçleri yetmese ve düşünemiyor olsalar da mı?\""},{"n":44,"t":"De ki: \"Şefaat tümüyle Allah’a aittir. Göklerin ve yerin hükümranlığı O’nundur. Sonra yalnız O’na döndürüleceksiniz.\""},{"n":45,"t":"Allah, bir tek (ilâh) olarak anıldığında ahirete inanmayanların kalpleri daralır. Allah’tan başkaları (ilâhları) anıldığında bakarsın sevinirler."},{"n":46,"t":"De ki: \"Ey göklerin ve yerin yaratıcısı olan, gaybı da, görünen âlemi de bilen Allah’ım! Ayrılığa düştükleri şeyler konusunda kulların arasında sen hükmedersin.\""},{"n":47,"t":"Eğer yeryüzünde bulunan her şey tümüyle ve onlarla beraber bir o kadarı da zulmedenlerin olsa, kıyamet günü kötü azaptan kurtulmak için elbette onları verirlerdi. Artık, hiç hesap etmedikleri şeyler Allah tarafından karşılarına çıkmıştır."},{"n":48,"t":"(Dünyada) kazandıkları şeylerin kötülükleri karşılarına çıkmış, alay etmekte oldukları şey onları kuşatmıştır."},{"n":49,"t":"İnsana bir zarar dokunduğunda bize yalvarır. Sonra ona tarafımızdan bir nimet verdiğimizde, \"Bu, bana ancak bilgim sayesinde verilmiştir\" der. Hayır, o bir imtihandır. Fakat onların çoğu bilmezler."},{"n":50,"t":"Bunu kendilerinden öncekiler de söylemişti ama kazandıkları şeyler onlara hiçbir yarar sağlamamıştı."},{"n":51,"t":"Nihayet kazandıkları şeylerin kötülükleri onlara isabet etmişti. Onlardan zulmedenler var ya, kazandıkları şeylerin kötülükleri onlara isabet edecektir. Onlar Allah’ı âciz bırakacak değillerdir."},{"n":52,"t":"Bilmediler mi ki, Allah rızkı dilediğine bol bol verir ve (dilediğine) kısar. Şüphesiz bunda inanan bir toplum için elbette ibretler vardır."},{"n":53,"t":"De ki: \"Ey kendilerinin aleyhine aşırı giden kullarım! Allah’ın rahmetinden ümidinizi kesmeyin. Şüphesiz Allah, bütün günahları affeder. Çünkü O, çok bağışlayandır, çok merhamet edendir.\""},{"n":54,"t":"Azap size gelmeden önce Rabbinize dönün ve O’na teslim olun. Sonra size yardım edilmez."},{"n":"55-56","t":"Farkında olmadan azap size ansızın gelmeden önce, Rabbinizden size indirilenin en güzeline uyun ki, kişi, \"Allah’ın yanında, işlediğim kusurlardan dolayı vay hâlime! Gerçekten ben alay edenlerden idim\" demesin."},{"n":57,"t":"Yahut, \"Allah beni doğru yola iletseydi, elbette O’na karşı gelmekten sakınanlardan olurdum\" demesin."},{"n":58,"t":"Yahut azabı gördüğünde, \"Keşke benim için dünyaya bir dönüş daha olsa da iyilik yapanlardan olsam\" demesin."},{"n":59,"t":"(Allah, şöyle diyecek:) \"Hayır, öyle değil! Âyetlerim sana geldi de sen onları yalanladın, büyüklük tasladın ve inkârcılardan oldun.\""},{"n":60,"t":"Kıyamet günü Allah’a karşı yalan söyleyenleri görürsün, yüzleri kapkara kesilmiştir. Büyüklük taslayanlar için cehennemde bir yer mi yok!?"},{"n":61,"t":"Allah, kendisine karşı gelmekten sakınanları başarıları sebebiyle kurtarır. Onlara kötülük dokunmaz. Onlar üzülmezler de."},{"n":62,"t":"Allah, her şeyin yaratıcısıdır. O, her şeye vekildir."},{"n":63,"t":"Göklerin ve yerin anahtarları O’nundur. Allah’ın âyetlerini inkâr edenler var ya, işte onlar ziyana uğrayanların ta kendileridir."},{"n":64,"t":"De ki: \"Ey cahiller! Siz bana Allah’tan başkasına ibadet etmemi mi emrediyorsunuz?\""},{"n":65,"t":"Andolsun, sana ve senden önceki peygamberlere şöyle vahyedildi: \"Eğer Allah’a ortak koşarsan elbette amelin boşa çıkar ve elbette ziyana uğrayanlardan olursun.\""},{"n":66,"t":"Hayır, yalnız Allah’a ibadet et ve şükredenlerden ol."},{"n":67,"t":"Allah’ın kadrini gereği gibi bilemediler. Yeryüzü kıyamet gününde bütünüyle O’nun elindedir. Gökler de O’nun kudretiyle dürülmüştür. O, onların ortak koştuklarından uzaktır, yücedir."},{"n":68,"t":"Sûr’a üflenir ve Allah’ın dilediği kimseler dışında göklerdeki herkes ve yerdeki herkes ölür. Sonra ona bir daha üflenir, bir de bakarsın onlar kalkmış bekliyorlar."},{"n":69,"t":"Yeryüzü, Rabbinin nuruyla aydınlanır. Kitap (amel defterleri) ortaya konur. Peygamberler ve şahitler getirilir ve haksızlığa uğratılmaksızın aralarında adaletle hüküm verilir."},{"n":70,"t":"Herkese yaptığının karşılığı tam olarak verilir. Allah, onların yaptıklarını en iyi bilendir."},{"n":71,"t":"İnkâr edenler grup grup cehenneme sevk edilirler. Cehenneme vardıklarında oranın kapıları açılır ve cehennem bekçileri onlara şöyle derler: \"Size içinizden, Rabbinizin âyetlerini size okuyan ve bu gününüze kavuşacağınıza dair sizi uyaran peygamberler gelmedi mi?\" Onlar da, \"Evet geldi\" derler. Fakat inkârcılar hakkında azap sözü gerçekleşmiştir."},{"n":72,"t":"Onlara şöyle denir: \"İçinde ebedî kalmak üzere cehennemin kapılarından girin. Büyüklük taslayanların kalacağı yer ne kötüdür!\""},{"n":73,"t":"Rablerine karşı gelmekten sakınanlar da grup grup cennete sevk edilirler. Cennete vardıklarında oranın kapıları açılır ve cennet bekçileri onlara şöyle der: \"Size selâm olsun! Tertemiz oldunuz. Haydi ebedî kalmak üzere buraya girin.\""},{"n":74,"t":"Onlar şöyle derler: \"Hamd, bize olan vaadini gerçekleştiren ve bizi cennetten dilediğimiz yere konmak üzere bu yurda varis kılan Allah’a mahsustur. Salih amel işleyenlerin mükâfatı ne güzelmiş!\""},{"n":75,"t":"Melekleri de, Rablerini hamd ile tesbih edip yücelterek Arş’ın etrafını kuşatmış hâlde görürsün. Artık kulların arasında adaletle hüküm verilmiş ve \"Hamd âlemlerin Rabbi olan Allah’a mahsustur\" denilmiştir."}],[{"n":1,"t":"Hâ Mîm."},{"n":"2-3","t":"Bu kitabın indirilmesi, mutlak güç sahibi, hakkıyla bilen, günahı bağışlayan, tövbeyi kabul eden, azabı ağır olan, lütuf sahibi Allah tarafındandır. O’ndan başka ilâh yoktur. Dönüş ancak O’nadır."},{"n":4,"t":"Allah’ın âyetleri hakkında inkâr edenlerden başkası tartışmaya girişmez. Onların şehirlerde gezip dolaşmaları seni aldatmasın."},{"n":5,"t":"Onlardan önce Nûh’un kavmi ve onlardan sonra gelen topluluklar da yalanlamıştı. Her ümmet kendi peygamberini yakalayıp cezalandırmaya azmetmişti. Hakkı yok etmek için batıl şeyler ileri sürerek tartışmışlardı. Bu yüzden onları kıskıvrak yakaladım. Benim cezalandırmam nasılmış, (gördüler)!"},{"n":6,"t":"Böylece Rabbinin, inkâr edenler hakkındaki, \"Onlar cehennemliklerdir\" sözü gerçekleşmiş oldu."},{"n":7,"t":"Arş’ı taşıyanlar ve onun çevresinde bulunanlar (melekler) Rablerini hamd ederek tespih ederler, O’na inanırlar ve inananlar için (şöyle diyerek) bağışlanma dilerler: \"Ey Rabbimiz! Senin rahmetin ve ilmin her şeyi kuşatmıştır. O hâlde tövbe eden ve senin yoluna uyanları bağışla ve onları cehennem azâbından koru.\""},{"n":8,"t":"\"Ey Rabbimiz! Onları da, onların babalarından, eşlerinden ve soylarından iyi olanları da, kendilerine vaad ettiğin Adn cennetlerine koy. Şüphesiz sen mutlak güç sahibisin, hüküm ve hikmet sahibisin.\""},{"n":9,"t":"\"Onları kötülüklerden koru. Sen o gün kimi kötülüklerden korursan, ona rahmet etmiş olursun. İşte bu büyük başarıdır.\""},{"n":10,"t":"İnkâr edenler var ya, muhakkak onlara: \"Allah’ın (size) gazabı, sizin kendinize olan gazabınızdan daha büyüktür. Çünkü siz imana çağırılırdınız da inkâr ederdiniz\" diye seslenilir."},{"n":11,"t":"Onlar da şöyle derler: \"Ey Rabbimiz! Bizi iki defa öldürdün, iki defa da dirilttin. Günahlarımızı kabulleniyoruz. Şimdi (bu ateşten) bir çıkış yolu var mı?\""},{"n":12,"t":"\"Bu, sizin tevhid çerçevesinde Allah’a çağrıldığında inkâr etmeniz, O’na ortak koşulduğunda ise inanmanız sebebiyledir. Artık hüküm yüce ve büyük Allah’a aittir.\""},{"n":13,"t":"O, size âyetlerini gösteren, sizin için gökten bir rızık indirendir. Ancak O’na yönelen, düşünüp ibret alır."},{"n":14,"t":"O hâlde, kâfirlerin hoşuna gitmese de, siz dini Allah’a has kılarak O’na ibadet edin."},{"n":15,"t":"O, dereceleri hakkıyla yükseltendir, Arş’ın sahibidir. Buluşma günü hakkında (insanları) uyarmak için, irâdesiyle ilgili vahyi kullarından dilediğine, kendi indirir."},{"n":16,"t":"O gün onlar ortaya çıkarlar. Onların hiçbir şeyi Allah’a gizli kalmaz. Bugün mülk (hükümranlık) kimindir? Tek olan, her şeyi kudret ve hâkimiyeti altında tutan Allah’ındır"},{"n":17,"t":"Bugün herkese kazandığının karşılığı verilir. Bugün asla zulüm yoktur. Şüphesiz Allah, hesabı çabuk görendir."},{"n":18,"t":"Yaklaşmakta olan gün konusunda onları uyar. O gün yürekler gam ve tasa ile dolu, (sanki) gırtlaklara dayanmıştır. Zalimlerin ne sıcak bir dostu, ne de sözü dinlenir bir şefaatçisi vardır."},{"n":19,"t":"Allah, gözlerin hain bakışını ve kalplerin gizlediğini bilir."},{"n":20,"t":"Allah, hak ve adâletle hükmeder. Allah’tan başka taptıkları ise hiçbir hükümde bulunamazlar. Şüphesiz Allah hakkıyla işitendir, hakkıyla görendir."},{"n":21,"t":"Onlar yeryüzünde dolaşıp, kendilerinden öncekilerin akıbetlerinin nasıl olduğuna bakmadılar mı? Onlar, kendilerinden daha güçlü ve yeryüzündeki eserleri daha üstündü. Böyle iken Allah, günahları sebebiyle onları yakaladı. Onları Allah’ın azabından koruyacak hiç kimse olmadı."},{"n":22,"t":"Bunun sebebi şu idi: Peygamberleri onlara apaçık mucizeler getiriyorlardı da onlar inkâr ediyorlardı. Bu yüzden Allah da onları yakalayıverdi. Şüphesiz O, güçlüdür, cezası da çok şiddetlidir."},{"n":"23-24","t":"Andolsun ki biz Mûsâ’yı mucizelerimizle ve apaçık bir delille Firavun’a, Hâmân’a ve Kârûn’a gönderdik. Onlar ise; \"Bu çok yalancı bir sihirbazdır\" dediler."},{"n":25,"t":"Mûsâ onlara tarafımızdan gerçeği getirince, \"Onunla beraber iman edenlerin oğullarını öldürün, kadınlarını sağ bırakın\" dediler. Fakat kâfirlerin tuzağı hep boşa çıkmıştır."},{"n":26,"t":"Firavun dedi ki: \"Bırakın beni, Mûsâ’yı öldüreyim. (Faydası olacaksa) Rabbini yardıma çağırsın! Çünkü ben onun, dininizi değiştireceğinden, yahut yeryüzünde bozgunculuk çıkaracağından korkuyorum.\""},{"n":27,"t":"Mûsâ da, \"Ben, hesap gününe inanmayan her kibirliden, benim de Rabbim sizin de Rabbiniz olan Allah’a sığınırım\" dedi."},{"n":28,"t":"Firavun ailesinden, imanını gizlemekte olan mü’min bir adam şöyle dedi: \"Rabbim Allah’tır, dediği için bir adamı öldürecek misiniz? Hâlbuki o, size Rabbinizden apaçık mucizeler getirdi. Eğer yalancı ise, yalanı kendi aleyhinedir. Eğer doğru söylüyorsa, sizi tehdit ettiği şeylerin bir kısmı başınıza gelecektir. Şüphesiz Allah, aşırı giden, yalancılık eden kimseyi doğru yola eriştirmez.\""},{"n":29,"t":"\"Ey kavmim! Bugün yeryüzüne hâkim kimseler olarak iktidar ve saltanat sizindir. Ama başımıza geldiğinde bizi, Allah’ın azabından kim kurtarır?\" Firavun, \"Ben size ancak kendi görüşümü bildiriyorum ve sizi ancak doğru yola götürüyorum\" dedi."},{"n":"30-31","t":"İman etmiş olan adam dedi ki: \"Ey kavmim! Şüphesiz ben, Nûh kavmi, Âd kavmi, Semûd kavmi ve onlardan sonra gelen toplulukların başına gelen olayların sizin de başınıza gelmesinden korkuyorum. Allah, kullarına asla zulmetmek istemez.\""},{"n":"32-33","t":"\"Ey kavmim! Gerçekten sizin için, o bağrışıp çağrışma gününden, arkanıza dönüp kaçmaya çalışacağınız günden korkuyorum. (O gün) sizi, Allah’(ın azabın)dan kurtaracak kimse yoktur. Allah, kimi saptırırsa artık onu doğru yola iletecek de yoktur.\""},{"n":34,"t":"Andolsun, daha önce Yûsuf da size apaçık deliller getirmişti de, onun size getirdikleri hakkında şüphe edip durmuştunuz. Daha sonra o ölünce de, \"Allah, ondan sonra aslâ peygamber göndermez\" demiştiniz. İşte Allah, aşırı giden şüpheci kimseleri böyle saptırır."},{"n":35,"t":"Onlar kendilerine gelmiş hiçbir delil olmaksızın, Allah’ın âyetleri hakkında tartışan kimselerdir. Bu ise Allah katında ve iman edenler katında büyük öfke ve gazap gerektiren bir iştir. Allah, her kibirli zorbanın kalbini işte böyle mühürler."},{"n":"36-37","t":"Firavun dedi ki: \"Ey Hâmân! Bana yüksek bir kule yap, belki yollara, göklerin yollarına erişirim de Mûsâ’nın ilâhını görürüm(!) Çünkü ben, onun yalancı olduğuna inanıyorum.\" Böylece Firavun’a yaptığı kötü iş süslü gösterildi ve doğru yoldan saptırıldı. Firavun’un tuzağı, tamamen sonuçsuz kaldı."},{"n":38,"t":"O inanan kimse dedi ki: \"Ey kavmim! Bana uyun ki, sizi doğru yola ileteyim.\""},{"n":39,"t":"\"Ey kavmim! Şüphesiz bu dünya hayatı ancak (geçici) bir yararlanmadır. Ahiret ise ebedî olarak kalınacak yerdir.\""},{"n":40,"t":"\"Kim bir kötülük yaparsa, ancak onun kadar ceza görür. Kadın veya erkek, kim, mü’min olarak salih bir amel işlerse, işte onlar cennete girecek ve orada hesapsız olarak rızıklandırılacaklardır.\""},{"n":41,"t":"\"Ey kavmim! Bu ne hâl? Ben sizi kurtuluşa çağırıyorum, siz ise beni ateşe çağırıyorsunuz.\""},{"n":42,"t":"\"Siz beni Allah’ı inkâr etmeye ve hakkında hiçbir bilgim olmayan şeyleri O’na ortak koşmaya çağırıyorsunuz. Ben ise sizi mutlak güç sahibine, çok bağışlayana (Allah’a) çağırıyorum.\""},{"n":43,"t":"\"Şüphe yok ki sizin beni tapmaya çağırdığınız şeyin ne dünya ne de ahiret konusunda hiçbir çağrısı yoktur. Kuşkusuz dönüşümüz Allah’adır. Şüphesiz, aşırı gidenler cehennemliklerin ta kendileridir.\""},{"n":44,"t":"\"Size söylediklerimi hatırlayacaksınız. Ben işimi Allah’a havale ediyorum. Şüphesiz Allah, kullarını hakkıyla görendir.\""},{"n":45,"t":"Allah, onu, onların hilelerinin kötülüklerinden korudu. Firavun ailesini, azâbın en kötüsü kuşattı."},{"n":46,"t":"(Öyle bir) ateş ki, onlar sabah akşam ona sunulurlar. Kıyametin kopacağı günde de, \"Firavun ailesini azabın en şiddetlisine sokun\" denilecektir."},{"n":47,"t":"Ateşin içinde birbirleriyle tartışırlarken, zayıf olanlar, büyüklük taslayanlara, \"Biz size uymuş kimselerdik. Şimdi şu ateşin bir kısmını üzerimizden kaldırabilir misiniz?\" derler."},{"n":48,"t":"Büyüklük taslayanlar ise şöyle derler: \"Biz hepimiz ateşin içindeyiz. Şüphesiz Allah, kullar arasında (böyle) hüküm vermiştir.\""},{"n":49,"t":"Ateşte olanlar cehennem bekçilerine, \"Rabbinize yalvarın da (hiç değilse) bir gün bizden azabı hafifletsin\" derler."},{"n":50,"t":"(Cehennem bekçileri) derler ki: \"Size peygamberleriniz açık mucizeler getirmemiş miydi?\" Onlar, \"Evet, getirmişti\" derler. (Bekçiler), \"Öyleyse kendiniz yalvarın\" derler. Şüphesiz kâfirlerin duası boşunadır."},{"n":51,"t":"Şüphesiz ki, peygamberlerimize ve iman edenlere dünya hayatında ve şahitlerin şahitlik edecekleri günde yardım ederiz."},{"n":52,"t":"O gün zalimlere, mazeretleri fayda vermez. Lânet de onlaradır, kötü yurt da onlaradır."},{"n":"53-54","t":"Andolsun, biz Mûsâ’ya hidayet verdik. İsrailoğulları’na da, akıl sahipleri için bir öğüt ve doğruluk rehberi olarak o kitabı (Tevrat’ı) miras bıraktık."},{"n":55,"t":"Ey Muhammed! Sabret. Allah’ın va’di şüphesiz gerçektir. Günahının bağışlanmasını iste. Akşam sabah Rabbini hamd ederek tespih et!"},{"n":56,"t":"Allah’ın âyetleri hakkında, kendilerine gelmiş bir delilleri olmaksızın tartışanlar var ya, onların kalplerinde ancak bir büyüklük taslama vardır. Onlar, tasladıkları büyüklüğe asla ulaşmazlar. Sen Allah’a sığın. Şüphesiz O, hakkıyla işitendir, hakkıyla görendir."},{"n":57,"t":"Elbette göklerin ve yerin yaratılması, insanların yaratılmasından daha büyük bir şeydir. Fakat insanların çoğu bilmezler."},{"n":58,"t":"Kör ile gören, iman edip salih ameller işleyenler ile kötülük yapan bir değildir. Siz pek az düşünüyorsunuz."},{"n":59,"t":"Kıyamet günü mutlaka gelecektir, bunda hiç şüphe yoktur. Fakat insanların çoğu buna inanmazlar."},{"n":60,"t":"Rabbiniz şöyle dedi: \"Bana dua edin, duânıza cevap vereyim. Bana kulluk etmeyi kibirlerine yediremeyenler aşağılanmış bir hâlde cehenneme gireceklerdir.\""},{"n":61,"t":"Allah, içinde rahat edesiniz diye geceyi ve (her şeyi) gösterici (aydınlık) olarak da gündüzü yaratandır. Şüphesiz Allah, insanlara karşı sonsuz iyilik sahibidir, fakat insanların çoğu şükretmezler."},{"n":62,"t":"İşte her şeyin yaratıcısı olan Rabbiniz Allah! O’ndan başka hiçbir ilâh yoktur. Durum bu iken nasıl oluyor da (haktan) döndürülüyorsunuz?"},{"n":63,"t":"Allah’ın âyetlerini inkâr etmekte olanlar, işte böyle döndürülürler."},{"n":64,"t":"Allah, yeryüzünü sizin için karar kılma yeri, göğü de binâ yapan; size şekil verip de şekillerinizi güzel kılan ve sizi temiz şeylerle rızıklandırandır. İşte Rabbiniz Allah! Âlemlerin Rabbi Allah ne yücedir!"},{"n":65,"t":"O, diridir. O’ndan başka hiçbir ilâh yoktur. O hâlde sadece Allah’a itaat ederek (samimi olarak) O’na ibadet edin. Hamd, âlemlerin Rabbine mahsustur."},{"n":66,"t":"De ki: \"Rabbimden bana apaçık deliller gelince, Allah’ı bırakıp da taptıklarınıza tapmam bana yasaklandı ve bana, âlemlerin Rabbine teslim olmam emredildi.\""},{"n":67,"t":"O, sizi (önce) topraktan, sonra az bir sudan (meniden), sonra \"alaka\"dan yaratan, sonra sizi (ana rahminden) çocuk olarak çıkaran, sonra olgunluk çağına ulaşmanız, sonra da ihtiyarlamanız için sizi yaşatandır. İçinizden önceden ölenler de vardır. Allah bunları, belli bir zamana erişmeniz ve düşünüp akıl erdirmeniz için yapar."},{"n":68,"t":"O, yaşatan ve öldürendir. Bir şeye karar verdiğinde, ona sadece \"ol\" der, o da oluverir."},{"n":69,"t":"Allah’ın âyetleri hakkında tartışanları görmedin mi? Nasıl da döndürülüyorlar?"},{"n":70,"t":"Onlar, kitabı (Kur’an’ı) ve elçilerimize gönderdiklerimizi yalanlayanlardır. Onlar bilecekler."},{"n":"71-72","t":"O zaman onlar, boyunlarında demir halkalar ve zincirler olduğu hâlde kaynar suda sürüklenecekler, sonra da ateşte yakılacaklardır."},{"n":"73-74","t":"Sonra onlara, \"Allah’ı bırakıp da ortak koştuklarınız nerede?\" denilir. Onlar da, \"(Yüzüstü bırakıp) bizden uzaklaştılar. Hayır, demek ki, biz önceleri hiçbir şeye tapmıyormuşuz, (taptıklarımız bir hiçmiş)\" derler. İşte Allah, inkârcıları böyle saptırır."},{"n":75,"t":"Bu, sizin yeryüzünde haksız yere şımarmanızdan ve böbürlenmenizden ötürüdür."},{"n":76,"t":"Onlara, \"Ebedî kalmak üzere cehennem kapılarından girin. Büyüklük taslayanların yeri ne kötüdür!\" (denir)."},{"n":77,"t":"Sen sabret! Şüphesiz Allah’ın verdiği söz gerçektir. Onları tehdit ettiğimiz azâbın bir kısmını sana göstersek de (ya da göstermeden önce) seni vefât ettirsek de, sonunda onlar bize döndürüleceklerdir."},{"n":78,"t":"Andolsun, senden önce de peygamberler gönderdik. Onlardan sana anlattıklarımız da var, anlatmadıklarımız da var. Hiçbir peygamber, Allah’ın izni olmadan bir mûcize getiremez. Allah’ın emri gelince de hak yerine getirilir. İşte o zaman bunu batıl sayanlar hüsrana uğrarlar."},{"n":79,"t":"Allah, bir kısmına binesiniz, bir kısmını da yiyesiniz diye sizin için hayvanları yaratandır."},{"n":80,"t":"Onlarda sizin için daha birçok faydalar da vardır. Gönüllerinizdeki ihtiyaçlara kendileri üzerinden ulaşasınız diye onları yaratmıştır. Onlarla ve gemilerle taşınırsınız."},{"n":81,"t":"Allah, size âyetlerini gösteriyor. Allah’ın hangi âyetlerini inkâr edersiniz?"},{"n":82,"t":"Onlar yeryüzünde dolaşıp, kendilerinden önce gelenlerin akıbetlerinin nasıl olduğuna bakmadılar mı? Onlar kendilerinden daha çok, daha güçlü ve onların yeryüzündeki eserleri daha üstündü. Fakat kazanmakta oldukları şeyler onlara bir fayda vermemişti."},{"n":83,"t":"Peygamberleri onlara apaçık deliller getirince, sahip oldukları bilgi ile şımardılar (ve onları alaya aldılar). Sonunda alaya almakta oldukları şey kendilerini sarıverdi."},{"n":84,"t":"Azabımızı gördükleri zaman, \"Yalnız Allah’a inandık; O’na ortak koşmakta olduğumuz şeyleri inkâr ettik\" dediler."},{"n":85,"t":"Fakat azâbımızı gördükleri zaman inanmaları, kendilerine fayda vermedi. Bu, Allah’ın kulları hakkında eskiden beri yürürlükte olan kanunudur. İşte orada inkârcılar hüsrana uğradılar."}],[{"n":1,"t":"Hâ Mîm."},{"n":2,"t":"Bu Kur’an, Rahmân ve Rahîm olan Allah’tan indirilmedir."},{"n":3,"t":"Bu, bilen bir toplum için Arapça bir Kur’an olarak âyetleri genişçe açıklanmış bir kitaptır."},{"n":4,"t":"Müjdeleyici ve uyarıcı olarak gönderilmiştir. Fakat onların çoğu yüz çevirmiştir. Artık onlar işitmezler."},{"n":5,"t":"Dediler ki: \"(Ey Muhammed!) Bizi çağırdığın şeye karşı kalplerimiz örtüler içerisindedir. Kulaklarımızda bir ağırlık, seninle bizim aramızda da bir perde vardır. O hâlde sen (istediğini) yap, şüphesiz biz de (istediğimizi) yapacağız.\""},{"n":6,"t":"De ki: \"Ben de ancak sizin gibi bir insanım. Fakat bana ilâhınızın yalnızca bir tek ilâh olduğu vahyediliyor. Artık O’na yönelin ve O’ndan bağışlanma dileyin. Allah’a ortak koşanların vay hâline!\""},{"n":7,"t":"Onlar zekâtı vermeyen kimselerdir. Onlar ahireti de inkâr ederler."},{"n":8,"t":"Şüphesiz iman edip salih ameller işleyenler için ise kesintisiz bir mükâfat vardır."},{"n":9,"t":"De ki: \"Siz mi yeri iki günde (iki evrede) yaratanı inkâr ediyor ve O’na ortaklar koşuyorsunuz? O, âlemlerin Rabbidir.\""},{"n":10,"t":"O, dört gün içinde (dört evrede), yeryüzünde yükselen sabit dağlar yarattı, orada bolluk ve bereket meydana getirdi ve orada rızık arayanların ihtiyaçlarına uygun olarak rızıklar takdir etti."},{"n":11,"t":"Sonra duman hâlinde bulunan göğe yöneldi; ona ve yeryüzüne, \"İsteyerek veya istemeyerek gelin\" dedi. İkisi de, \"İsteyerek geldik\" dediler."},{"n":12,"t":"Böylece onları, iki günde (iki evrede) yedi gök olarak yarattı ve her göğe kendi işini bildirdi. En yakın göğü kandillerle süsledik ve onu koruduk. İşte bu, mutlak güç sahibi ve hakkıyla bilen Allah’ın takdiridir."},{"n":13,"t":"Eğer yüz çevirirlerse, onlara de ki: \"Ben sizi Âd ve Semûd kavimlerini çarpan yıldırım gibi bir yıldırıma karşı uyardım.\""},{"n":14,"t":"Hani onlara peygamberler önlerinden ve arkalarından gelmiş, \"Allah’tan başkasına ibadet etmeyin\" demişler, onlar da, \"Eğer Rabbimiz dileseydi (Peygamber olarak) melekler indirirdi. Bu sebeple, biz sizinle gönderilenleri inkâr ediyoruz\" demişlerdi."},{"n":15,"t":"Âd kavmi ise yeryüzünde haksız olarak büyüklük taslamış, \"Bizden daha güçlü kim var?\" demişlerdi. Onlar, kendilerini yaratan Allah’ın onlardan daha güçlü olduğunu görmediler mi? Onlar bizim âyetlerimizi inkâr ediyorlardı."},{"n":16,"t":"Biz de onlara dünya hayatında zillet azabını tattırmak için o mutsuz kara günlerde üzerlerine dondurucu bir rüzgâr gönderdik. Ahiret azâbı elbette daha rezil edicidir. Onlara yardım da edilmez."},{"n":17,"t":"Semûd kavmine gelince, biz onlara doğru yolu göstermiştik. Ama onlar körlüğü hidayete tercih etmişler ve yaptıklarına karşılık, alçaltıcı azap yıldırımı onları çarpmıştı."},{"n":18,"t":"İnananları ve Allah’a karşı gelmekten sakınanları kurtardık."},{"n":19,"t":"Allah’ın düşmanlarının, toplanıp yığın yığın cehenneme sevk edilecekleri günü hatırla!"},{"n":20,"t":"Nihayet cehenneme vardıklarında, kulakları, gözleri ve derileri, yapmış oldukları işler hakkında, kendileri aleyhine şahitlik ederler."},{"n":21,"t":"Onlar derilerine, \"Niçin aleyhimize şâhitlik ettiniz?\" derler. Derileri de der ki; \"Bizi her şeyi konuşturan Allah konuşturdu. İlk defa sizi O yaratmıştı ve yine yalnızca O’na döndürülüyorsunuz.\""},{"n":22,"t":"\"Siz (günahları işlerken) kulaklarınızın, gözlerinizin ve derilerinizin, aleyhinize şâhitlik etmesinden sakınmıyordunuz. Lâkin, yaptıklarınızın çoğunu Allah’ın bilmediğini sanıyordunuz.\""},{"n":23,"t":"\"İşte bu sizin, Rabbiniz hakkında beslediğiniz zannınızdır. O, sizi mahvetti de ziyâna uğrayanlardan oldunuz.\""},{"n":24,"t":"Şimdi eğer dayanabilirlerse, artık cehennem onların yeridir! Eğer Allah’ın rızasını kazandıracak amelleri işlemeye izin isteseler, onlara izin verilmez."},{"n":25,"t":"Biz onların başına birtakım arkadaşlar sardık da bu arkadaşlar onlara geçmişlerini ve geleceklerini süslü gösterdiler. Böylece kendilerinden önce gelip geçmiş olan cin ve insan toplulukları ile ilgili o söz (azap), onlar için de gerçekleşti. Çünkü onlar ziyana uğrayanlardı."},{"n":26,"t":"İnkâr edenler dediler ki: \"Bu Kur’an’ı dinlemeyin. Baskın çıkmak için o okunurken yaygara koparın.\""},{"n":27,"t":"İnkâr edenlere mutlaka şiddetli bir azabı tattıracağız ve onları yaptıklarının en kötüsü ile cezalandıracağız."},{"n":28,"t":"İşte böyle, Allah düşmanlarının cezası ateştir. Âyetlerimizi inkâr etmelerinin cezası olarak orada onlar için ebedîlik yurdu vardır."},{"n":29,"t":"(Ateşe giren) inkârcılar şöyle derler: \"Rabbimiz! Cinlerden ve insanlardan bizi saptıranları bize göster de onları ayaklarımızın altına alalım ki en aşağılıklardan olsunlar.\""},{"n":30,"t":"Şüphesiz \"Rabbimiz Allah’tır\" deyip de, sonra dosdoğru olanlar var ya, onların üzerine akın akın melekler iner ve derler ki: \"Korkmayın, üzülmeyin, size (dünyada iken) va’dedilmekte olan cennetle sevinin!\""},{"n":"31-32","t":"\"Biz dünya hayatında da âhirette de sizin dostlarınızız. Çok bağışlayan ve çok merhametli olan Allah’tan bir ağırlama olarak, orada canlarınızın çektiği her şey var, istediğiniz her şey orada sizin için var.\""},{"n":33,"t":"Allah’a çağıran, salih amel işleyen ve \"Kuşkusuz ben müslümanlardanım\" diyenden daha güzel sözlü kimdir?"},{"n":34,"t":"İyilikle kötülük bir olmaz. Kötülüğü en güzel bir şekilde sav. Bir de bakarsın ki, seninle arasında düşmanlık bulunan kimse sanki sıcak bir dost oluvermiştir."},{"n":35,"t":"Bu güzel davranışa ancak sabredenler kavuşturulur. Buna ancak (hayırdan ve olgunluktan) büyük payı olanlar kavuşturulur."},{"n":36,"t":"Eğer şeytandan gelen kötü bir düşünce seni dürtecek olursa, hemen Allah’a sığın. Çünkü O, hakkıyla işitendir, hakkıyla bilendir."},{"n":37,"t":"Gece, gündüz, güneş ve ay Allah’ın varlığının delillerindendir. Güneşe ve aya secde etmeyin. Eğer gerçekten Allah’a kulluk ediyorsanız, onları yaratan Allah’a secde edin."},{"n":38,"t":"Eğer onlar büyüklük taslarlarsa, bilsinler ki Rabbinin yanında bulunanlar (melekler), gece gündüz hiç usanmadan O’nu tespih ederler."},{"n":39,"t":"Allah’ın varlığının delillerinden biri de şudur: Sen yeryüzünü boynu bükük (kupkuru) görürsün. Onun üzerine yağmuru indirdiğimiz zaman kıpırdar kabarır. Şüphesiz ki, onu dirilten, elbette ölüleri de diriltir. Şüphesiz O, her şeye gücü hakkıyla yetendir."},{"n":40,"t":"Âyetlerimiz konusunda (yalanlama amacıyla) doğruluktan sapanlar bize gizli kalmaz. O hâlde kıyamet gününde ateşe atılan mı, yoksa güven içinde gelen kimse mi daha iyidir? Dilediğinizi yapın. Şüphesiz O, yaptıklarınızı hakkıyla görmektedir."},{"n":41,"t":"Kur’an kendilerine geldiğinde onu inkâr edenler mutlaka cezalarını göreceklerdir. Şüphesiz o, çok değerli ve sağlam bir kitaptır."},{"n":42,"t":"Ona ne önünden ne de ardından batıl gelemez. O, hüküm ve hikmet sahibi, övülmeye lâyık olan Allah tarafından indirilmiştir."},{"n":43,"t":"Sana ancak, senden önceki peygamberlere söylenenler söylenmektedir. Hiç şüphesiz senin Rabbin hem bağışlama sahibidir, hem de elem dolu bir azap sahibidir."},{"n":44,"t":"Eğer biz onu başka dilde bir Kur’an yapsaydık onlar mutlaka, \"Onun âyetleri genişçe açıklanmalı değil miydi? Başka dilde bir kitap ve Arap bir peygamber öyle mi?\" derlerdi. De ki: \"O, inananlar için bir hidayet ve şifâdır. İnanmayanların kulaklarında bir ağırlık vardır ve Kur’an onlara kapalı ve anlaşılmaz gelir. (Sanki) onlara uzak bir yerden sesleniliyor (da anlamıyorlar).\""},{"n":45,"t":"Andolsun! Biz, Mûsâ’ya Kitab’ı (Tevrat’ı) vermiştik de, onda ayrılığa düşmüşlerdi. Eğer (azabın ertelenmesi ile ilgili olarak ezelde) Rabbinden bir söz geçmiş olmasaydı, aralarında derhal hüküm verilirdi. Şüphesiz onlar Kur’an hakkında derin bir şüphe içindedirler."},{"n":46,"t":"Kim iyi bir iş yaparsa kendi lehinedir. Kim de kötülük yaparsa kendi aleyhinedir. Rabbin, kullara (zerre kadar) zulmedici değildir."},{"n":47,"t":"Kıyametin ne zaman kopacağına ilişkin bilgi O’na havale edilir. Meyveler tomurcuklarından ancak O’nun bilgisi altında çıkar, dişi ancak O’nun bilgisi altında hamile kalır ve doğurur. Allah onlara, \"Nerede bana ortak koştuklarınız?\" diye seslendiği gün şöyle derler: \"Sana arz ederiz ki, içimizden onları gören hiçbir kimse yok.\""},{"n":48,"t":"Daha önce yalvardıkları (tanrılar) onları yüzüstü bırakıp uzaklaşmıştır. Kendileri için kaçacak bir yer olmadığını anlamışlardır."},{"n":49,"t":"İnsan, hayır (mal, mülk, genişlik) istemekten usanmaz. Fakat başına bir kötülük gelince umutsuzluğa düşer, yıkılır."},{"n":50,"t":"Andolsun! Başına gelen bir zarardan sonra kendisine tarafımızdan bir rahmet tattırsak mutlaka \"Bu benim hakkımdır, Kıyametin kopacağını da sanmıyorum. Andolsun, Rabbime döndürülürsem, şüphesiz O’nun yanında benim için daha güzel şeyler vardır\" der. Andolsun, biz inkâr edenlere yaptıklarını mutlaka haber vereceğiz ve andolsun, onlara mutlaka ağır azaptan tattıracağız."},{"n":51,"t":"İnsana nimet verdiğimizde yüz çevirir ve yan çizer. Başına bir kötülük gelince de yalvarmaya koyulur."},{"n":52,"t":"De ki: \"Ne dersiniz? Eğer o (Kur’an) Allah katından olup da siz de onu inkâr etmişseniz, o zaman derin bir ayrılık içinde bulunan kimseden daha sapık kim olabilir?\""},{"n":53,"t":"Varlığımızın delillerini, (kâinattaki uçsuz bucaksız) ufuklarda ve kendi nefislerinde onlara göstereceğiz ki, o Kur’an’ın gerçek olduğu onlara iyice belli olsun. Rabbinin, her şeye şâhit olması yetmez mi?"},{"n":54,"t":"İyi bilin ki, onlar Rablerine kavuşma konusunda şüphe içindedirler. İyi bilin ki, O, her şeyi kuşatandır."}],[{"n":1,"t":"Hâ Mîm."},{"n":2,"t":"Ayn Sîn Kâf"},{"n":3,"t":"(Ey Muhammed!) Mutlak güç sahibi, hüküm ve hikmet sahibi olan Allah, sana ve senden öncekilere işte böyle vahyeder."},{"n":4,"t":"Göklerde ve yerde ne varsa hepsi O’nundur. O, yücedir, büyüktür."},{"n":5,"t":"Neredeyse gökler (O’nun azametinden) üstlerinden çatlayacaklar. Melekler ise, Rablerini hamd ile tespih ederler ve yeryüzündekiler için bağışlanma dilerler. İyi bilin ki Allah, çok bağışlayandır, çok merhamet edendir."},{"n":6,"t":"Allah’tan başka dostlar edinenlere gelince, Allah onları daima gözetlemektedir. Sen onlara vekil değilsin."},{"n":7,"t":"Böylece biz sana Arapça bir Kur’an vahyettik ki, şehirlerin anası olan Mekke’de ve çevresinde bulunanları uyarasın. Hakkında asla şüphe olmayan toplanma günüyle onları uyarasın. Bir grup cennette, bir grup ise cehennemdedir."},{"n":8,"t":"Allah dileseydi, onları (aynı dine mensup) bir tek ümmet yapardı. Fakat O, dilediğini rahmetine sokar. Zalimlerin ise bir dost ve yardımcısı yoktur."},{"n":9,"t":"Yoksa onlar Allah’tan başka dostlar mı edindiler? Hâlbuki gerçek dost Allah’tır. O, ölüleri diriltir. O, her şeye hakkıyla gücü yetendir."},{"n":10,"t":"Hakkında ayrılığa düştüğünüz herhangi bir şeyin hükmü Allah’a aittir. İşte bu, Rabbim Allah’tır. Yalnız O’na tevekkül ettim ve ancak O’na yöneliyorum."},{"n":11,"t":"O, gökleri ve yeri yaratandır. Size kendinizden eşler, hayvanlardan da (kendilerine) eşler yaratmıştır. Bu sûretle sizi üretiyor. O’nun benzeri hiçbir şey yoktur. O, hakkıyla işitendir, hakkıyla görendir."},{"n":12,"t":"Göklerin ve yerin anahtarları O’nundur. Dilediğine rızkı bol verir ve (dilediğine) kısar. Şüphesiz O, her şeyi hakkıyla bilendir."},{"n":13,"t":"\"Dini dosdoğru tutun ve onda ayrılığa düşmeyin!\" diye Nûh’a emrettiğini, sana vahyettiğini, İbrâhim’e, Mûsâ’ya ve İsâ’ya emrettiğini size de din kıldı. Fakat senin kendilerini çağırdığın şey (İslâm dini), Allah’a ortak koşanlara ağır geldi. Allah, ona dilediğini seçer. İçtenlikle kendine yönelenleri de ona ulaştırır."},{"n":14,"t":"Onlar, kendilerine bilgi geldikten sonra, aralarındaki kıskançlık yüzünden ayrılığa düştüler. Eğer (azabın) belli bir süreye kadar (ertelenmesi ile ilgili olarak) Rabbinden bir söz geçmiş olmasaydı, aralarında hemen hüküm verilirdi. Onlardan sonra Kitab’a mirasçı kılınanlar da, onun hakkında derin bir şüphe içindedirler."},{"n":15,"t":"(Ey Muhammed!) Bundan dolayı sen çağrıya devam et ve emrolunduğun gibi dosdoğru ol. Onların hevâ ve heveslerine uyma ve şöyle de: \"Ben, Allah’ın indirdiği her kitaba inandım ve aranızda adaleti gerçekleştirmekle emrolundum. Allah bizim de Rabbimiz, sizin de Rabbinizdir. Bizim işlediklerimiz bize, sizin işledikleriniz sizedir. Bizimle sizin aranızda tartışılacak bir şey yoktur. Allah, hepimizi bir araya toplayacaktır. Dönüş de ancak O’nadır.\""},{"n":16,"t":"Allah’ın çağrısına uyulduktan sonra O’nun hakkında tartışmaya girenlerin delilleri Rableri katında batıldır. Onlara bir gazap vardır. Onlar için çetin bir azap vardır."},{"n":17,"t":"Allah, hak olarak Kitab’ı ve mizanı indirendir. Sen nereden bileceksin belki de o saat (kıyamet) yakındır."},{"n":18,"t":"Kıyamete inanmayanlar, onun çabuk kopmasını isterler. İnananlar ise, ondan korkarlar ve onun gerçek olduğunu bilirler. İyi bilin ki, Kıyamet günü hakkında tartışanlar derin bir sapıklık içindedirler."},{"n":19,"t":"Allah, kullarına çok lütufkârdır, dilediğini rızıklandırır. O, kuvvetlidir, mutlak güç sahibidir."},{"n":20,"t":"Kim âhiret kazancını isterse, onun kazancını artırırız. Kim de dünya kazancını isterse, ona da istediğinden veririz, fakat onun ahirette hiçbir payı yoktur."},{"n":21,"t":"Yoksa, Allah’ın izin vermediği bir dini kendilerine tutulacak yol kılan ortakları mı var? Eğer (cezaların ertelenmesine dair) kesin hükmü olmasaydı, derhal aralarında hüküm verilirdi. Şüphesiz, zâlimler için elem dolu bir azap vardır."},{"n":22,"t":"Sen, zalimlerin yaptıkları şeyler tepelerine inerken bu yüzden korku ile titrediklerini göreceksin. İnanıp yararlı işler yapanlar da cennet bahçelerindedirler. Onlar için Rableri katında diledikleri her şey vardır. İşte bu büyük lütuftur."},{"n":23,"t":"İşte bu, Allah’ın, inanıp salih ameller işleyen kullarına müjdelediği şeydir. De ki: \"Ben buna (yaptığım tebliğ görevine) karşılık sizden, akrabalıktan doğan sevgiden başka bir ücret istemiyorum.\" Kim güzel bir iş yaparsa, onun iyiliğini artırırız. Şüphesiz Allah, çok bağışlayandır, şükrün karşılığını verendir."},{"n":24,"t":"Yoksa \"Yalan uydurup Allah’a iftira etti\" mi diyorlar. Eğer Allah dilerse senin kalbini mühürler. Allah batılı yok eder, hakkı sözleriyle gerçekleştirir. Şüphesiz O, göğüslerin özünü (kalplerde olanları) hakkıyla bilendir."},{"n":25,"t":"O, kullarından tövbeyi kabul eden, kötülükleri bağışlayan ve yaptıklarınızı bilendir."},{"n":26,"t":"Allah, iman edip salih ameller işleyenlerin dualarına karşılık verir; lütfundan onlara fazlasını da verir. Kâfirler için ise çetin bir azap vardır."},{"n":27,"t":"Allah, kullarına (tümüne birden) rızkı bol bol verseydi, yeryüzünde mutlaka azgınlık ederlerdi. Fakat O, rızkı dilediği ölçüde indirir. Şüphesiz O, kullarından hakkıyla haberdardır ve onları hakkıyla görendir."},{"n":28,"t":"O, insanlar umutlarını kestikten sonra yağmuru indiren, rahmetini her tarafa yayandır. O, dost olandır, övülmeye lâyık olandır."},{"n":29,"t":"Gökleri, yeri ve bu ikisi içinde yaydığı canlıları yaratması, O’nun varlığının delillerindendir. O, dilediği zaman, onları bir araya getirmeye de gücü yetendir."},{"n":30,"t":"Başınıza her ne musibet gelirse, kendi yaptıklarınız yüzündendir. O, yine de çoğunu affeder."},{"n":31,"t":"Yeryüzünde O’nu âciz bırakamazsınız. Sizin için Allah’tan başka hiçbir dost ve yardımcı yoktur."},{"n":32,"t":"Denizde dağlar gibi yüzen gemiler, O’nun varlığının delillerindendir."},{"n":33,"t":"O, dilerse rüzgârı durdurur da onlar denizin üstünde durakalırlar. Elbette bunda çok sabreden, çok şükreden herkes için ibretler vardır."},{"n":34,"t":"Yahut (içlerindekilerin) yaptıklarından dolayı onları helâk eder, birçoğunu da affeder."},{"n":35,"t":"Allah, böyle yapar ki, âyetlerimiz hakkında tartışanlar, kendileri için kaçacak bir yer olmadığını bilsinler."},{"n":"36-39","t":"(Dünyalık olarak) size her ne verilmişse, bu dünya hayatının geçimliğidir. Allah’ın yanında bulunanlar ise daha hayırlı ve kalıcıdır. Bu mükâfat, inananlar ve Rablerine tevekkül edenler, büyük günahlardan ve çirkin işlerden kaçınanlar, öfkelendikleri zaman bağışlayanlar, Rablerinin çağrısına cevap verenler ve namazı dosdoğru kılanlar; işleri, aralarında şûrâ (danışma) ile olanlar, kendilerine verdiğimiz rızıktan Allah yolunda harcayanlar, bir saldırıya uğradıkları zaman, aralarında yardımlaşanlar içindir."},{"n":40,"t":"Bir kötülüğün karşılığı, onun gibi bir kötülüktür (ona denk bir cezadır). Ama kim affeder ve arayı düzeltirse, onun mükâfatı Allah’a aittir. Şüphesiz O, zâlimleri sevmez."},{"n":41,"t":"Zulme uğradıktan sonra, kendini savunup hakkını alan kimseye (ceza vermek için) bir yol yoktur."},{"n":42,"t":"Ceza yolu ancak insanlara zulmedenler ve yeryüzünde haksız yere taşkınlık edenler içindir. İşte onlar için elem dolu bir azap vardır."},{"n":43,"t":"Her kim de sabreder ve bağışlarsa, işte bu elbette azmedilecek işlerdendir."},{"n":44,"t":"Allah, kimi saptırırsa artık bundan sonra onun hiçbir dostu yoktur. Azabı gördüklerinde zâlimlerin, \"Dünyaya dönmek için bir yol var mı?\" dediklerini görürsün."},{"n":45,"t":"Ateşe sunulurken onların zilletten başlarını öne eğmiş, göz ucuyla gizli gizli baktıklarını görürsün. İnananlar da, \"İşte asıl ziyana uğrayanlar, kıyamet günü kendilerini ve ailelerini ziyana sokanlardır\" diyecekler. İyi bilin ki zâlimler, sürekli bir azap içindedirler."},{"n":46,"t":"Onların Allah’tan başka kendilerine yardım edecek dostları da yoktur. Allah, kimi saptırırsa artık onun için hiçbir çıkar yol yoktur."},{"n":47,"t":"Allah’tan, geri çevrilmesi imkânsız olan bir gün gelmeden önce, Rabbinizin çağrısına uyun. O gün sizin için ne sığınacak bir yer vardır, ne de (günahlarınızı) inkâr edebilirsiniz!"},{"n":48,"t":"Eğer yüz çevirirlerse (bilesin ki), biz seni onlara bekçi göndermedik. Sana düşen, sadece tebliğdir. Gerçekten biz insana katımızdan bir rahmet tattırdığımızda ona sevinir; ama elleriyle yaptıkları işler yüzünden onlara bir kötülük dokunursa, o zaman da insan pek nankördür."},{"n":49,"t":"Göklerin ve yerin mülkü (hükümranlığı) Allah’ındır. O, dilediğini yaratır. Dilediğine kız çocukları, dilediğine erkek çocukları verir."},{"n":50,"t":"Yahut o çocukları erkekler, dişiler olmak üzere çift verir, dilediği kimseyi de kısır yapar. Şüphesiz O, her şeyi hakkıyla bilendir, hakkıyla gücü yetendir."},{"n":51,"t":"Allah, bir insanla ancak vahiy yoluyla, yahut perde arkasından konuşur. Yahut bir elçi gönderip, izniyle ona dilediğini vahyeder. Şüphesiz O yücedir, hüküm ve hikmet sahibidir."},{"n":"52-53","t":"İşte sana da, emrimizle, bir ruh (kalpleri dirilten bir kitap) vahyettik. Sen kitap nedir, iman nedir bilmezdin. Fakat biz onu, kullarımızdan dilediğimizi, kendisiyle doğru yola eriştireceğimiz bir nur yaptık. Şüphesiz ki sen doğru bir yola iletiyorsun; göklerdeki ve yerdeki her şeyin sahibi olan Allah’ın yoluna. İyi bilin ki, bütün işler sonunda Allah’a döner."}],[{"n":1,"t":"Hâ Mîm."},{"n":"2-3","t":"Apaçık Kitab’a andolsun ki, iyice anlayasınız diye biz, onu Arapça bir Kur’an yaptık."},{"n":4,"t":"Şüphesiz o, katımızdaki ana kitapta (Levh-i Mahfuz’da) mevcuttur, çok yücedir, hikmetlerle doludur."},{"n":5,"t":"Haddi aşan bir topluluk oldunuz, diye vazgeçip Zikir’le (Kur’an’la) sizi uyarmaktan geri mi duralım?"},{"n":6,"t":"Hâlbuki daha önceki toplumlara da nice peygamberler göndermiştik."},{"n":7,"t":"(Onlar da) kendilerine gelen her peygamberle mutlaka alay ediyorlardı."},{"n":8,"t":"Biz, onlardan daha çetinlerini de helâk ettik. Öncekilerin örneği geçti!"},{"n":9,"t":"Andolsun, onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan, mutlaka, \"Onları mutlak güç sahibi, hakkıyla bilen (Allah) yarattı\" diyeceklerdir."},{"n":10,"t":"O, yeryüzünü size beşik yapan ve gideceğiniz yere ulaşasınız diye sizin için orada yollar var edendir."},{"n":11,"t":"O, gökten bir ölçüye göre yağmur indirendir. Biz onunla ölü araziyi canlandırdık. İşte siz de, böyle diriltileceksiniz."},{"n":"12-14","t":"O, bütün çiftleri yaratan, üzerlerine kurulasınız, sonra da, kurulduğunuzda, Rabbinizin nimetini hatırlayasınız ve \"Bunu hizmetimize veren Allah’ın şanı yücedir. Bunlara bizim gücümüz yetmezdi. Şüphesiz biz Rabbimize döneceğiz\" diyesiniz diye sizin için bindiğiniz gemileri ve hayvanları yaratandır."},{"n":15,"t":"Böyle iken (\"melekler Allah’ın kızlarıdır\" demek suretiyle) kullarından bir kısmını O’nun parçası saydılar. Şüphesiz insan apaçık bir nankördür."},{"n":16,"t":"Yoksa, Allah, yarattıklarından kendisine kızlar edindi de, oğulları size mi seçip ayırdı?"},{"n":17,"t":"Onlardan biri, Rahmân’a örnek kıldığı (isnad ettiği kız çocuğu) ile müjdelendiği zaman, öfkesinden yüzü simsiyah kesilir."},{"n":18,"t":"Süs içerisinde (narin bir biçimde) yetiştirilen ve tartışmada (delilini erkekler gibi) açıklayamayanı mı Allah’a isnad ediyorlar?"},{"n":19,"t":"Onlar, Rahmân’ın kulları olan melekleri de dişi saydılar. Onların yaratılışına şahit mi oldular? Onların (yalan) şahitlikleri yazılacak ve sorgulanacaklardır."},{"n":20,"t":"\"Eğer Rahmân dileseydi, biz onlara kulluk etmezdik\" dediler. Bu konuda hiçbir bilgileri yoktur. Onlar sadece yalan söylüyorlar."},{"n":21,"t":"Yoksa bundan önce onlara bir kitap verdik de ona mı sarılıyorlar?"},{"n":22,"t":"Hayır! Onlar sadece, \"Şüphesiz biz babalarımızı bir din üzerinde bulduk ve biz onların izlerinden gitmekteyiz\" dediler."},{"n":23,"t":"İşte böyle, biz senden önce hiçbir memlekete bir uyarıcı göndermedik ki, oranın şımarık zenginleri, \"Şüphe yok ki biz babalarımızı bir din üzerinde bulduk. Biz de elbette onların izlerinden gitmekteyiz\" demiş olmasınlar."},{"n":24,"t":"(Gönderilen uyarıcı,) \"Ben size, babalarınızı üzerinde bulduğunuz dinden daha doğrusunu getirmiş olsam da mı?\" dedi. Onlar, \"Biz kesinlikle sizinle gönderilen şeyi inkâr ediyoruz\" dediler."},{"n":25,"t":"Biz de onlardan intikam aldık. Yalanlayanların sonu, bak nasıl oldu!"},{"n":26,"t":"Hani İbrahim, babasına ve kavmine şöyle demişti: \"Şüphesiz ben sizin taptıklarınızdan uzağım.\""},{"n":27,"t":"\"Ben ancak O, beni yaratana taparım. Şüphesiz O beni doğru yola iletecektir.\""},{"n":28,"t":"İbrahim bunu, belki dönerler diye, ardından gelecekler arasında kalıcı bir söz yaptı."},{"n":29,"t":"Doğrusu onları (Mekke müşriklerini) ve atalarını kendilerine hak olan Kur’an ve onu açıklayan bir peygamber gelinceye kadar (dünya nimetlerinden) yararlandırırım."},{"n":30,"t":"Fakat kendilerine Hak gelince, \"Bu bir büyüdür, biz onu kesinlikle inkâr ediyoruz\" dediler."},{"n":31,"t":"\"Bu Kur’an, iki şehrin birinden bir büyük adama indirilseydi ya!\" dediler."},{"n":32,"t":"Rabbinin rahmetini onlar mı bölüştürüyorlar? Dünya hayatında onların geçimliklerini aralarında biz paylaştırdık. Birbirlerine iş gördürmeleri için, (çeşitli alanlarda) kimini kimine, derece derece üstün kıldık. Rabbinin rahmeti, onların biriktirdikleri (dünyalık) şeylerden daha hayırlıdır."},{"n":33,"t":"Eğer bütün insanlar (kâfirlere verdiğimiz nimetlere bakıp küfürde birleşen) bir tek ümmet olacak olmasalardı, Rahmân’ı inkâr edenlerin evlerine gümüşten tavanlar ve üzerine çıkacakları merdivenler yapardık."},{"n":"34-35","t":"Evlerine (gümüşten) kapılar ve üzerine yaslanacakları koltuklar ve altın süslemeler yapardık. Bütün bunlar, sadece dünya hayatının geçimliğidir. Rabbinin katında ahiret ise, O’na karşı gelmekten sakınanlarındır."},{"n":36,"t":"Kim, Rahmân’ın Zikri’ni görmezlikten gelirse, biz onun başına bir şeytan sararız. Artık o, onun ayrılmaz dostudur."},{"n":37,"t":"Şüphesiz bu şeytanlar onları doğru yoldan saptırırlar. Onlar ise doğru yolda olduklarını sanırlar."},{"n":38,"t":"Sonunda bize geldiğinde, arkadaşına, \"Keşke benimle senin aranda doğu ile batı arası kadar uzaklık olsaydı! Ne kötü arkadaşmışsın!\" der."},{"n":39,"t":"Onlara, \"(Bu temenniniz) bugün size asla fayda vermez. Çünkü zulmettiniz. Hepiniz azapta ortaksınız\" denir."},{"n":40,"t":"Sağırlara sen mi duyuracaksın; yahut körleri ve apaçık bir sapıklık içinde olanları sen mi doğru yola ileteceksin?"},{"n":41,"t":"Ya biz seni (bu dünyadan) alır götürürüz de, onlardan intikam alırız."},{"n":42,"t":"Yahut da, onlara yaptığımız tehdidi sana gösteririz ki, bizim onlara gücümüz yeter."},{"n":43,"t":"Öyle ise sana vahyedilene sımsıkı sarıl. Şüphesiz sen doğru bir yol üzeresin."},{"n":44,"t":"Şüphesiz bu Kur’an, sana ve kavmine bir öğüt ve bir şereftir, ondan hesaba çekileceksiniz."},{"n":45,"t":"Senden önce gönderdiğimiz elçilerimize sor: Rahmân’dan başka kulluk edilecek ilâhlar var etmiş miyiz?"},{"n":46,"t":"Andolsun, biz Mûsâ’yı mucizelerimizle Firavun’a ve ileri gelen adamlarına göndermiştik de o, \"Şüphesiz ben âlemlerin Rabbinin elçisiyim\" demişti."},{"n":47,"t":"(Mûsâ) mucizelerimizi kendilerine getirince, bir de bakmışsın, o mucizelere gülüyorlar!"},{"n":48,"t":"Onlara gösterdiğimiz her bir mucize önceki benzerinden daha büyüktü. Doğru yola dönsünler diye, onları azaba uğrattık."},{"n":49,"t":"(Onlar azabı görünce) \"Ey büyücü! Sana verdiği söze dayanarak, bizim için Rabbine dua et. Çünkü biz artık doğru yola gireceğiz\" dediler."},{"n":50,"t":"Fakat biz onlardan azabı kaldırınca bir de bakmışsın sözlerinden dönüyorlar."},{"n":51,"t":"Firavun, kavmine seslenerek dedi ki: \"Ey kavmim! Mısır hükümdarlığı benim değil mi? Şu nehirler de benim altımdan akıyor (değil mi?) Hâlâ görmüyor musunuz?\""},{"n":52,"t":"\"Yoksa ben, şu zavallı, nerede ise maksadını anlatamayacak durumda olan bu adamdan daha hayırlı değil miyim?\""},{"n":53,"t":"\"(Eğer doğru söylüyorsa) ona altın bilezikler atılmalı, yahut onunla beraber bulunmak üzere melekler gelmeli değil miydi?\""},{"n":54,"t":"Firavun, kavmini küçük düşürdü (ezdi). Onlar da kendisine itaat ettiler. Çünkü onlar yoldan çıkmış bir toplumdu."},{"n":55,"t":"Onlar bizi bu şekilde öfkelendirince biz de onlardan öç aldık, hepsini suda boğduk."},{"n":56,"t":"Onları, sonradan gelecek inkârcılara, geçmiş bir ibret ve bir örnek kıldık."},{"n":57,"t":"Meryem oğlu İsa bir örnek olarak anlatılınca bir de ne göresin, senin kavmin (seni susturacak bir delil buldukları zannıyla) hemen şamata etmeye başlar."},{"n":58,"t":"\"Bizim tanrılarımız mı hayırlı, yoksa İsa mı?\" dediler. Bunu sadece seninle tartışmak için ortaya attılar. Şüphesiz onlar kavgacı bir toplumdur."},{"n":59,"t":"İsa, sadece, kendisine nimet verdiğimiz ve İsrailoğulları’na örnek kıldığımız bir kuldur."},{"n":60,"t":"Eğer dileseydik, içinizden yeryüzünde sizin yerinize geçecek melekler yaratırdık."},{"n":61,"t":"Şüphesiz o Kıyametin (kopacağının) bir bilgisidir. Artık onun hakkında asla şüphe etmeyin, bana uyun, bu doğru bir yoldur."},{"n":62,"t":"Sakın şeytan sizi yoldan çevirmesin. Çünkü o, size apaçık bir düşmandır."},{"n":63,"t":"İsa, apaçık mucizeleri getirdiği zaman şöyle demişti: \"Ben size hikmeti getirdim ve hakkında ayrılığa düştüğünüz şeylerden bir kısmını size açıklamak için geldim. Öyle ise, Allah’a karşı gelmekten sakının ve bana itaat edin.\""},{"n":64,"t":"Şüphesiz Allah, benim de Rabbim, sizin de Rabbinizdir. Öyleyse O’na kulluk edin, işte bu doğru bir yoldur."},{"n":65,"t":"Ama aralarından çıkan gruplar ayrılığa düştüler. Elem dolu bir günün azâbından vay o zulmedenlerin hâline!"},{"n":66,"t":"Onlar (bu tavırlarıyla) ancak, kıyamet gününün kendilerine ansızın gelmesini beklemektedirler, hâlbuki bunun farkında değillerdir."},{"n":67,"t":"O gün Allah’a karşı gelmekten sakınanlar dışında, dostlar birbirine düşman olurlar."},{"n":"68-69","t":"(Allah, şöyle der:) \"Ey âyetlerimize iman eden ve müslüman olan kullarım! Bugün size korku yoktur, siz üzülmeyeceksiniz de.\""},{"n":70,"t":"\"Siz ve eşleriniz sevinç ve mutluluk içinde cennete giriniz.\""},{"n":71,"t":"Onlar için altın tepsiler ve kadehler dolaştırılır. Canlarının istediği ve gözlerinin hoşlandığı her şey oradadır. Siz orada ebedî olarak kalacaksınız."},{"n":72,"t":"İşte bu, yapmakta olduklarınıza karşılık size mîras verilen cennettir."},{"n":73,"t":"Orada sizin için bol bol meyve var, onlardan yersiniz."},{"n":74,"t":"Şüphesiz suçlular cehennem azabında devamlı kalacaklardır."},{"n":75,"t":"Azapları hafifletilmeyecektir. Onlar azap içinde ümitsizdirler."},{"n":76,"t":"Biz onlara zulmetmedik. Fakat onlar, kendileri zâlim idiler."},{"n":77,"t":"(Görevli meleğe şöyle seslenirler:) \"Ey Mâlik! Rabbin bizim işimizi bitirsin.\" O da, \"Siz hep böyle kalacaksınız\" der."},{"n":78,"t":"Andolsun, size hakkı getirdik. Fakat çoğunuz haktan hoşlanmayanlarsınız."},{"n":79,"t":"Yoksa (gerçeği kabul etmeme konusunda) bir işe kesin karar mı verdiler? Şüphesiz biz de (onları cezalandırmakta) kararlıyız."},{"n":80,"t":"Yoksa onların sırlarını ve gizli konuşmalarını duymadığımızı mı sanıyorlar? Hayır öyle değil, yanlarındaki elçilerimiz (melekler) yazmaktadırlar."},{"n":81,"t":"(Ey Muhammed!) De ki: \"Eğer Rahmân’ın bir çocuğu olsaydı, ona kulluk edenlerin ilki ben olurdum.\""},{"n":82,"t":"Göklerin ve yerin Rabbi, Arş’ın da Rabbi olan Allah, onların nitelendirmelerinden uzaktır."},{"n":83,"t":"Bırak onları, tehdit edildikleri güne kavuşana kadar, (batıl inançlarına) dalsınlar ve (dünya hayatlarında) oynayadursunlar."},{"n":84,"t":"O, gökte de ilâh olandır, yerde de ilâh olandır. O, hüküm ve hikmet sahibidir, hakkıyla bilendir."},{"n":85,"t":"Göklerin, yerin ve ikisi arasındaki her şeyin hükümranlığı kendisine ait olan Allah yücedir! Kıyametin bilgisi de yalnız O’nun katındadır ve yalnızca O’na döndürüleceksiniz."},{"n":86,"t":"O’nu bırakıp taptıkları şeyler şefaat edemezler. Ancak bilerek hakka şâhitlik edenler şefaat edebilirler."},{"n":87,"t":"Andolsun, onlara kendilerini kimin yarattığını sorsan elbette, \"Allah\" derler. Öyleyken nasıl döndürülüyorlar?"},{"n":88,"t":"Onun (Muhammed’in), \"Ya Rabbi!\" demesine andolsun ki, şüphesiz bunlar iman etmeyen bir kavimdir."},{"n":89,"t":"Şimdilik sen onları hoş gör ve \"size selâm olsun\" de. Yakında bilecekler."}],[{"n":1,"t":"Hâ Mîm."},{"n":"2-3","t":"Apaçık olan Kitab’a andolsun ki, biz onu mübarek bir gecede indirdik. Şüphesiz biz insanları uyarmaktayız."},{"n":"4-7","t":"Katımızdan bir emirle her hikmetli iş o gecede ayırt edilir. Eğer kesin olarak inanıyorsanız, Rabbinden; göklerin, yerin ve bu ikisi arasındakilerin Rabbinden bir rahmet olarak biz peygamberler göndermekteyiz. O, hakkıyla işitendir, hakkıyla bilendir."},{"n":8,"t":"O’ndan başka hiçbir ilâh yoktur. Yaşatır, öldürür. O, sizin de Rabbiniz, önceki atalarınızın da Rabbidir."},{"n":9,"t":"Fakat onlar, şüphe içinde eğlenip duruyorlar."},{"n":10,"t":"Göğün açık bir duman getireceği günü bekle."},{"n":11,"t":"(O duman) insanları bürür. Bu, elem dolu bir azaptır."},{"n":12,"t":"İnsanlar, \"Rabbimiz! Bu azabı bizden kaldır, çünkü biz artık inanıyoruz\" derler."},{"n":13,"t":"Nerede onlarda öğüt almak?! Oysa kendilerine (gerçeği) açıklayan bir peygamber gelmişti."},{"n":14,"t":"Sonra ondan yüz çevirdiler ve \"Bu bir öğretilmiş, bu bir deli!\" dediler."},{"n":15,"t":"Biz bu azabı kısa bir süre kaldıracağız, siz de yine eski hâlinize döneceksiniz."},{"n":16,"t":"Onları o en şiddetli yakalayışla yakalayacağımız günü hatırla. Şüphesiz biz öcümüzü alırız."},{"n":17,"t":"Andolsun, onlardan önce Firavun kavmini sınamıştık. Onlara değerli bir peygamber (Mûsâ) gelmişti."},{"n":18,"t":"O, şöyle demişti: \"Allah’ın kullarını (esaret altındaki İsrailoğullarını) bana teslim edin. Çünkü ben güvenilir bir peygamberim.\""},{"n":19,"t":"\"Allah’a karşı ululuk taslamayın. Çünkü ben size apaçık bir delil (mucize) getiriyorum.\""},{"n":20,"t":"\"Şüphesiz ki ben, beni taşlamanızdan, benim de Rabbim, sizin de Rabbiniz olan Allah’a sığındım.\""},{"n":21,"t":"\"Bana inanmadınızsa benden uzak durun.\""},{"n":22,"t":"Sonra Mûsâ, Rabbine, \"Bunlar günahkâr bir toplumdur\" diye seslendi."},{"n":23,"t":"Allah da şöyle dedi: \"O hâlde kullarımı geceleyin yola çıkar, çünkü takip edileceksiniz.\""},{"n":24,"t":"\"Denizi açık hâlde bırak.\" Çünkü onlar boğulacak bir ordudur."},{"n":25,"t":"Onlar geride nice bahçeler, nice pınarlar bıraktılar."},{"n":26,"t":"Nice ekinler, nice güzel konaklar!"},{"n":27,"t":"Zevk ve sefasını sürdükleri nice nimetler!"},{"n":28,"t":"İşte böyle! Onları başka bir topluma miras bıraktık."},{"n":29,"t":"Gök ve yer onların ardından ağlamadı; onlara mühlet de verilmedi."},{"n":"30-31","t":"Andolsun, İsrailoğullarını o alçaltıcı azaptan; Firavun’dan kurtardık. Çünkü o, haddi aşanlardan bir zorba idi."},{"n":32,"t":"Andolsun, onları, bir bilgi üzerine (dönemlerinde) âlemlere üstün kıldık."},{"n":33,"t":"Onlara, içinde açık bir imtihan bulunan mûcizeler verdik."},{"n":"34-35","t":"Bunlar (müşrikler) diyorlar ki: \"İlk ölümümüzden başka bir ölüm yoktur. Biz diriltilecek değiliz.\""},{"n":36,"t":"\"Eğer doğru söyleyenler iseniz atalarımızı getirin.\""},{"n":37,"t":"Bunlar mı daha hayırlı, yoksa Tübba’ kavmi ile onlardan öncekiler mi? Onları helâk ettik. Çünkü onlar suçlu kimselerdi."},{"n":38,"t":"Biz, gökleri, yeri ve bunlar arasında bulunanları, eğlenmek için yaratmadık."},{"n":39,"t":"Biz onları ancak hak ve hikmete uygun olarak yarattık. Ama onların çoğu bilmiyorlar."},{"n":40,"t":"Şüphesiz, hüküm günü, hepsinin bir arada buluşacağı zamandır."},{"n":41,"t":"O gün dostun dosta hiçbir faydası olmaz. Kendilerine yardım da edilmez."},{"n":42,"t":"Yalnız, Allah’ın yardım ettiği kimseler bunların dışındadır. Şüphesiz O, mutlak güç sahibidir, çok merhamet edendir."},{"n":"43-44","t":"Şüphesiz, zakkum ağacı, günahkârların yemeğidir."},{"n":"45-46","t":"O, maden eriyiği gibidir. Kaynar suyun kaynaması gibi karınlarda kaynar."},{"n":47,"t":"(Allah, görevli meleklere şöyle der:) \"Tutun onu, cehennemin ortasına sürükleyin.\""},{"n":48,"t":"\"Sonra başının üstüne kaynar su azabından dökün.\""},{"n":49,"t":"(Deyin ki:) \"Tat bakalım! Hani sen güçlüydün, şerefliydin!?\""},{"n":50,"t":"\"İşte bu, şüphelenip durduğunuz şeydir!\""},{"n":51,"t":"Allah’a karşı gelmekten sakınanlar ise güvenli bir yerdedirler."},{"n":52,"t":"Bahçelerde ve pınar başlarındadırlar."},{"n":53,"t":"İnce ipekten ve parlak atlastan elbiseler giyinerek karşılıklı otururlar."},{"n":54,"t":"İşte böyle. Ayrıca onları iri siyah gözlü hurilerle evlendirmişizdir."},{"n":55,"t":"Orada güven içinde her türlü meyveyi isterler."},{"n":56,"t":"Orada ilk ölümden başka bir ölüm tatmazlar. Allah, onları cehennem azabından korumuştur."},{"n":57,"t":"Bunlar, Rabbinden bir lütuf olarak verilmiştir. İşte bu büyük başarıdır."},{"n":58,"t":"(Ey Muhammed!) Biz Onu (Kur’an’ı) senin dilinle kolaylaştırdık ki, düşünüp öğüt alsınlar."},{"n":59,"t":"Artık sen (onların başına gelecekleri) bekle; onlar da beklemektedirler."}],[{"n":1,"t":"Hâ Mîm."},{"n":2,"t":"Kitab’ın indirilişi, mutlak güç sahibi, hüküm ve hikmet sahibi Allah tarafındandır."},{"n":3,"t":"Şüphesiz, göklerde ve yerde, inananlar için (Allah’ın varlığını ve birliğini gösteren) nice deliller vardır."},{"n":4,"t":"Sizin yaratılışınızda ve Allah’ın (yeryüzüne) yaydığı her bir canlıda da kesin olarak inanan bir toplum için elbette nice deliller vardır."},{"n":5,"t":"Geceyle gündüzün birbiri ardınca gelişinde, Allah’ın gökten rızık (sebebi olarak yağmur) indirip, onunla yeryüzünü ölümünden sonra diriltmesinde, rüzgârları evirip çevirmesinde aklını kullanan bir toplum için deliller vardır."},{"n":6,"t":"İşte bunlar, Allah’ın âyetleridir. Onları sana gerçek olarak okuyoruz. Artık Allah’tan ve O’nun âyetlerinden sonra hangi söze inanacaklar?"},{"n":7,"t":"Her günahkâr yalancının vay hâline!"},{"n":8,"t":"Kendisine Allah’ın âyetlerinin okunduğunu işitir de, sonra büyüklük taslayarak sanki onları hiç duymamış gibi direnir. İşte onu elem dolu bir azap ile müjdele!"},{"n":9,"t":"Âyetlerimizden bir şey öğrenince onu alaya alır. Onlar için alçaltıcı bir azap vardır!"},{"n":10,"t":"Arkalarında da cehennem vardır. Dünyada kazandıkları ve Allah’tan başka edindikleri dostlar onlara hiçbir fayda vermez. Onlar için elbette büyük bir azap vardır."},{"n":11,"t":"İşte bu (Kur’an) bir hidayettir. Rablerinin âyetlerini inkâr edenlere ise elem dolu çok kötü bir azap vardır."},{"n":12,"t":"Allah, içinde gemilerin, emriyle akıp gitmesi, O’nun lütfunu aramanız ve şükretmeniz için denizi sizin hizmetinize verendir."},{"n":13,"t":"Göklerdeki ve yerdeki her şeyi kendi katından (bir nimet olarak) sizin hizmetinize verendir. Elbette bunda düşünen bir toplum için deliller vardır."},{"n":14,"t":"İnananlara söyle, Allah’ın (ceza) günlerinin geleceğini ummayanları (şimdilik) bağışlasınlar ki Allah herhangi bir topluma (kendi) kazandığının karşılığını versin."},{"n":15,"t":"Kim salih bir amel işlerse, kendi lehine işlemiş olur. Kim de kötülük yaparsa, kendi aleyhine yapmış olur. Sonra Rabbinize döndürüleceksiniz."},{"n":16,"t":"Andolsun biz, İsrailoğullarına kitap, hükümranlık ve peygamberlik verdik. Onları güzel ve temiz yiyeceklerle rızıklandırdık ve onları (dönemlerinde) âlemlere üstün kıldık."},{"n":17,"t":"Onlara din işi konusunda açık deliller verdik. Ama onlar ancak kendilerine bilgi geldikten sonra, aralarındaki hasetten dolayı ayrılığa düştüler. Şüphesiz Rabbin, hakkında ayrılığa düştükleri şeyler konusunda kıyamet günü, aralarında hüküm verecektir."},{"n":18,"t":"Sonra da seni din işi konusunda açık bir yola koyduk. Sen ona uy, bilmeyenlerin heva ve heveslerine uyma."},{"n":19,"t":"Çünkü onlar, Allah’a karşı sana asla bir fayda sağlayamazlar. Şüphesiz zalimler birbirinin dostlarıdır. Allah ise kendisine karşı gelmekten sakınanların dostudur."},{"n":20,"t":"Bu Kur’an, insanlar için kalp gözleri (konumundaki bir nur), kesin olarak inanan bir toplum için de bir hidayet ve bir rahmettir."},{"n":21,"t":"Yoksa kötülük işleyenler, kendilerini, inanıp salih amel işleyenler gibi kılacağımızı; hayatlarının ve ölümlerinin bir olacağını mı sanıyorlar? Ne kötü hüküm veriyorlar!"},{"n":22,"t":"Allah, gökleri ve yeri, hak ve hikmete uygun olarak, herkese kazandığının karşılığı verilsin diye yaratmıştır. Onlara zulm edilmez."},{"n":23,"t":"Nefsinin arzusunu ilâh edinen, Allah’ın; (hâlini) bildiği için saptırdığı ve kulağını ve kalbini mühürlediği, gözüne de perde çektiği kimseyi gördün mü? Şimdi onu Allah’tan başka kim doğru yola eriştirebilir? Hâlâ düşünüp ibret almayacak mısınız?"},{"n":24,"t":"Dediler ki: \"Dünya hayatımızdan başka hayat yoktur. Ölürüz ve yaşarız. Bizi ancak zaman yok eder.\" Bu hususta onların bir bilgisi yoktur. Onlar sadece zanda bulunuyorlar."},{"n":25,"t":"Onlara âyetlerimiz açıkça okunduğu zaman onların delilleri ancak, \"Doğru söyleyenler iseniz babalarımızı getirin\" demek oldu."},{"n":26,"t":"De ki: \"Allah sizi yaşatıyor. Sonra sizi öldürecek, sonra da kendisinde şüphe olmayan Kıyamet gününde sizi bir araya getirecek, ama insanların çoğu bilmezler.\""},{"n":27,"t":"Göklerin ve yerin hükümranlığı Allah’ındır. Kıyamet kopacağı gün, işte o gün batıla sapanlar hüsrana uğrayacaklardır."},{"n":28,"t":"O gün her ümmeti diz çökmüş görürsün. Her ümmet kendi kitabına çağrılır. (Onlara şöyle denilir:) \"Bugün (yalnızca) yaptıklarınızın karşılığı verilecektir.\""},{"n":29,"t":"İşte kitabımız, size karşı gerçeği söylüyor. Çünkü biz yapmakta olduklarınızı kaydediyorduk."},{"n":30,"t":"İnanıp salih ameller işleyenlere gelince, Rableri onları rahmetine sokacaktır. İşte bu apaçık başarıdır."},{"n":31,"t":"İnkâr edenlere gelince, onlara şöyle denir: \"Âyetlerim size okunmuştu da sizler büyüklük taslamış ve günahkâr bir kavim olmuş değil miydiniz?\""},{"n":32,"t":"\"Şüphesiz, Allah’ın va’di gerçektir, kıyamet hakkında hiçbir şüphe yoktur\" dendiği zaman ise; \"Kıyametin ne olduğunu bilmiyoruz, sadece zannediyoruz. Biz bu konuda kesin kanaat sahibi değiliz\" demiştiniz."},{"n":33,"t":"Yaptıklarının kötülükleri karşılarına dikilmiş ve alay edip durdukları şey, kendilerini kuşatıvermiştir."},{"n":34,"t":"Onlara şöyle denir: \"Bugüne kavuşacağınızı unuttuğunuz gibi, bu gün biz de sizi unutuyoruz. Barınağınız ateştir. Yardımcılarınız da yoktur.\""},{"n":35,"t":"\"Bunun sebebi, Allah’ın âyetlerini alaya almanız ve dünya hayatının sizi aldatmasıdır.\" Artık bugün ateşten çıkarılmazlar ve Allah’ın rızasını kazandıracak amelleri işleme istekleri kabul edilmez."},{"n":36,"t":"Hamd, göklerin Rabbi ve yerin Rabbi, âlemlerin Rabbi olan Allah’a mahsustur."},{"n":37,"t":"Göklerde ve yerde ululuk O’na aittir. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."}],[{"n":1,"t":"Hâ Mîm."},{"n":2,"t":"Kitab’ın indirilişi, mutlak güç sahibi, hüküm ve hikmet sahibi Allah tarafındandır."},{"n":3,"t":"Biz, gökleri, yeri ve ikisi arasında bulunanları hak ve hikmete uygun olarak ve belirli bir süre için yarattık. İnkâr edenler ise, uyarıldıkları şeylerden yüz çevirmektedirler."},{"n":4,"t":"De ki: \"Allah’ı bırakıp da taptıklarınızı gördünüz mü? Bana gösterin, yeryüzünden neyi yaratmışlardır? Yoksa göklerin yaratılışında onların bir ortaklığı mı var? Eğer doğru söyleyenler iseniz bundan önceki bir kitap, yahut bir bilgi kalıntısı olsun getirin bana!\""},{"n":5,"t":"Kim, Allah’ı bırakıp da, kıyamet gününe kadar kendisine cevap veremeyecek şeylere tapandan daha sapıktır? Oysa onlar, bunların tapınmalarından habersizdirler."},{"n":6,"t":"İnsanlar (kıyamet günü) toplandığında, o taptıkları kendilerine düşman oluverir, onların ibâdetlerini de inkâr ederler."},{"n":7,"t":"Âyetlerimiz onlara açıkça okunduğu zaman, o küfredenler kendilerine geldiğinde Hak (kitap Kur’an) için, düşünmeden \"Bu, apaçık bir büyüdür\" dediler."},{"n":8,"t":"Yoksa, \"Onu uydurdu\" mu diyorlar? De ki: \"Eğer ben onu uydurmuşsam, Allah’tan gelecek olana (cezaya) karşı siz benim için hiçbir şey yapamazsınız. O, sizin, hakkında (düşüncesizce) yaygara kopardığınız şeyi daha iyi bilir. Benimle sizin aranızda şâhit olarak O yeter! O, çok bağışlayandır, çok merhamet edendir.\""},{"n":9,"t":"De ki: \"Ben türedi bir peygamber değilim. Bana ve size ne yapılacağını da bilmem. Ben sadece bana vahyedilene uyarım. Ben sadece apaçık bir uyarıcıyım.\""},{"n":10,"t":"De ki: \"Ne dersiniz? Şayet bu, Allah katından ise ve siz onu inkâr etmişseniz, İsrailoğullarından bir şahit de bunun benzerini (Tevrat’ta görerek) şahitlik edip inandığı hâlde, siz yine de büyüklük taslamışsanız (haksızlık etmiş olmaz mısınız?). Şüphesiz Allah, zâlimler topluluğunu doğru yola iletmez.\""},{"n":11,"t":"İnkâr edenler, inananlar için, \"Eğer o Kur’an iyi bir şey olsaydı, onlar onu kabulde, bizi geçemezlerdi\" dediler. Onunla doğru yolu bulamadıkları için; \"Bu eski bir uydurmadır\" diyecekler."},{"n":12,"t":"Bundan önce bir rehber ve bir rahmet olarak Mûsâ’nın kitabı da vardı. Bu ise, onu doğrulayan ve zulmedenleri uyarmak, iyilik yapanlara müjde olmak üzere Arap diliyle indirilmiş bir kitaptır."},{"n":13,"t":"\"Şüphesiz Rabbimiz Allah’tır\" deyip sonra da dosdoğru olanlara hiçbir korku yoktur, onlar üzülmeyecekler de."},{"n":14,"t":"Onlar cennetliklerdir. Yapmakta olduklarına karşılık, orada sürekli kalacaklardır."},{"n":15,"t":"Biz, insana anne babasına iyi davranmayı emrettik. Annesi onu ne zahmetle karnında taşıdı ve ne zahmetle doğurdu! Onun (anne karnında) taşınması ve sütten kesilme süresi (toplam olarak) otuz aydır. Nihayet olgunluk çağına gelip, kırk yaşına varınca şöyle der: \"Bana ve anne babama verdiğin nimetlere şükretmemi, senin razı olacağın salih amel işlememi bana ilham et. Neslimi de salih kimseler yap. Şüphesiz ben sana döndüm. Muhakkak ki ben sana teslim olanlardanım.\""},{"n":16,"t":"İşte, yaptıklarının iyisini kabul edeceğimiz ve günahlarını bağışlayacağımız bu kimseler cennetlikler arasındadırlar. Bu, onlara öteden beri yapılagelen doğru bir va’ddir."},{"n":17,"t":"Anne ve babasına, \"Öf size! Benden önce nice nesiller gelip geçmiş iken, beni tekrar diriltilecek olmakla mı tehdit ediyorsunuz?\" diyen kimseye, onlar Allah’a sığınarak, \"Yazıklar olsun sana! İman et, Allah’ın va’di gerçektir\" diyorlar, o da, \"Bu, eskilerin masallarından başka bir şey değildir\" diyordu."},{"n":18,"t":"İşte onlar, kendilerinden önce cinlerden ve insanlardan gelip geçmiş topluluklar içinde, haklarında o sözün (azabın) gerçekleştiği kimselerdir. Şüphesiz onlar ziyana uğrayanlardır."},{"n":19,"t":"Herkesin yaptıklarına göre dereceleri vardır. (Bu da) Allah’ın onlara yaptıklarının karşılığını tastamam vermesi içindir. Asla kendilerine haksızlık yapılmaz."},{"n":20,"t":"İnkâr edenler ateşe sunuldukları gün, (onlara şöyle denir:) \"Dünyadaki hayatınızda güzelliklerinizi bitirdiniz, onların zevkini sürdünüz. Bugün ise yeryüzünde haksız yere büyüklük taslamanızdan ve yoldan çıkmanızdan dolayı, alçaltıcı bir azapla cezalandırılacaksınız.\""},{"n":21,"t":"Kendisinden önce ve sonra uyarıcıların gelip geçmiş olan Âd kavminin kardeşini (Hûd’u) hatırla. Hani Ahkâf’taki kavmini, \"Ancak Allah’a ibadet edin, çünkü ben sizin adınıza büyük bir günün azabından korkuyorum\" diye uyarmıştı."},{"n":22,"t":"Onlar ise, \"Sen bizi ilâhlarımızdan alıkoymak için mi geldin? Doğru söyleyenlerden isen bizi tehdit ettiğin şeyi başımıza getir\" dediler."},{"n":23,"t":"Hûd, \"(Bu konudaki) bilgi ancak Allah katındadır. Ben size, benimle gönderileni tebliğ ediyorum. Fakat ben sizi cahillik eden bir kavim olarak görüyorum\" dedi."},{"n":24,"t":"O azabı vadilerine doğru yayılan bir bulut olarak gördüklerinde, \"Bu, bize yağmur getiren bir buluttur\" dediler. Hûd, \"Hayır, o sizin acele gelmesini istediğiniz şeydir. İçinde elem dolu azabın bulunduğu bir rüzgârdır\" dedi."},{"n":25,"t":"\"O, Rabbimin emriyle her şeyi yerle bir eder.\" Derken evlerinden başka hiçbir şeyleri görünmez hâle geldiler. İşte biz, suç işleyen toplumu böyle cezalandırırız."},{"n":26,"t":"Andolsun, size vermediğimiz imkân ve iktidarı onlara vermiştik. Kendilerine kulaklar, gözler ve kalpler vermiştik. Fakat kulakları, gözleri ve kalpleri kendilerine bir yarar sağlamadı. Çünkü Allah’ın âyetlerini inkâr ediyorlardı. Alaya aldıkları şey onları kuşattı."},{"n":27,"t":"Andolsun, biz çevrenizdeki memleketleri de yok ettik. (Doğru yola) dönsünler diye âyetleri tekrar tekrar açıkladık."},{"n":28,"t":"Allah’ı bırakıp O’na yakınlık sağlamaları için edindikleri ilâhlar kendilerine yardım etseydi ya!? Aksine onları yüzüstü bırakarak uzaklaşıp kayboldular. Bu, onların yalanı ve uydurmakta oldukları şeydir."},{"n":29,"t":"Hani Kur’an’ı dinlemek üzere cinlerden bir grubu sana yöneltmiştik. Onlar, onun huzuruna gelince birbirlerine, \"Susun!\" dediler. Kur’an’ın okunması bitince de uyarıcı olarak kavimlerine döndüler."},{"n":30,"t":"Dediler ki: \"Ey kavmimiz! Şüphesiz biz, Mûsâ’dan sonra indirilen, kendinden önceki kitapları doğrulayan, gerçeğe ve doğru yola ileten bir kitap dinledik.\""},{"n":31,"t":"\"Ey kavmimiz! Allah’ın davetçisine uyun, ona iman edin ki, günahlarınızı bağışlasın ve sizi elem dolu bir azaptan kurtarsın.\""},{"n":32,"t":"Kim Allah’ın davetçisine uymazsa, yeryüzünde Allah’ı âciz bırakacak değildir. Kendisi için Allah’tan başka dostlar da bulunmaz. İşte onlar apaçık bir sapıklık içindedirler."},{"n":33,"t":"Gökleri ve yeri yaratan ve onları yaratmaktan yorulmayan Allah’ın, ölüleri diriltmeye gücünün yeteceğini görmediler mi? Evet şüphesiz O, her şeye hakkıyla gücü yetendir."},{"n":34,"t":"İnkâr edenlere ateşe sunuldukları gün, \"Bu gerçek değil miymiş?\" denir. Onlar, \"Evet, Rabbimize andolsun ki gerçekmiş\" derler. Allah, \"Öyle ise inkâr etmekte olduğunuzdan dolayı azabı tadın!\" der."},{"n":35,"t":"(Ey Muhammed!) O hâlde, yüksek azim sahibi peygamberlerin sabretmesi gibi sabret. Onlar için acele etme. Onlar tehdit edildikleri azabı gördükleri gün, sanki dünyada gündüzün bir anından başka kalmadıklarını sanırlar. Bu bir duyurudur. Ancak yoldan çıkmış olan topluluk helâk edilir."}],[{"n":1,"t":"İnkâr edenler ve Allah yolundan alıkoyanlar var ya; işte, Allah onların bütün amellerini boşa çıkarmıştır."},{"n":2,"t":"İnanıp salih ameller işleyenlerin ve Muhammed’e indirilene -ki o Rablerinden gelen haktır- inananların ise Allah günahlarını örtmüş ve hâllerini düzeltmiştir."},{"n":3,"t":"Bu, inkâr edenlerin batıla uymaları ve inananların Rablerinden gelen gerçeğe uymalarından dolayıdır. İşte Allah, onların örnek teşkil edecek durumlarını insanlara böyle anlatır."},{"n":4,"t":"(Savaşta) inkâr edenlerle karşılaştığınız zaman boyunlarını vurun. Nihayet onları çökertip etkisiz hâle getirdiğinizde bağı sıkı bağlayın (sağ kalanlarını esir alın). Artık bundan sonra (esirleri) ya karşılıksız ya da fidye karşılığı salıverin. Savaş sona erinceye kadar hüküm budur. Eğer Allah dileseydi, onlardan öç alırdı. Fakat sizi birbirinizle denemek için böyle yapıyor. Allah yolunda öldürülenlere gelince, Allah onların amellerini asla boşa çıkarmayacaktır."},{"n":5,"t":"Onları doğruya ve güzele erdirecek ve durumlarını düzeltecektir."},{"n":6,"t":"Onları, kendilerine tanıttığı cennete koyacaktır."},{"n":7,"t":"Ey iman edenler! Eğer siz Allah’a yardım ederseniz (emrini tutar, dinini uygularsanız), O da size yardım eder ve ayaklarınızı sağlam bastırır."},{"n":8,"t":"İnkâr edenlere gelince, yıkım onlara! Allah, onların işlerini boşa çıkarmıştır."},{"n":9,"t":"Bu, Allah’ın indirdiğini beğenmemeleri, bu sebeple de Allah’ın onların amellerini boşa çıkarmasındandır."},{"n":10,"t":"Onlar yeryüzünde dolaşıp, kendilerinden öncekilerin sonlarının nasıl olduğuna bakmadılar mı? Allah, onları yerle bir etmiştir. İnkâr edenlere de bu akıbetin benzerleri vardır."},{"n":11,"t":"Bu, Allah’ın inananların yardımcısı olması, inkâr edenlerin ise, hiçbir yardımcısı bulunmamasından dolayıdır."},{"n":12,"t":"Şüphesiz Allah, inanıp salih ameller işleyenleri, içinden ırmaklar akan cennetlere koyacaktır. İnkâr edenler ise (dünya zevklerinden) yararlanırlar ve hayvanların yediği gibi yerler. Onların kalacakları yer ateştir."},{"n":13,"t":"(Ey Muhammed!) Seni çıkaran kendi memleket halkından daha güçlü nice memleket halkları vardı ki, biz onları helâk ettik. Onların hiçbir yardımcısı da olmadı."},{"n":14,"t":"Rabbinin katından açık bir belgesi olan kimse, kötü işleri kendisine güzel gösterilen ve nefislerinin arzularına uyan kimseler gibi midir?"},{"n":15,"t":"Allah’a karşı gelmekten sakınanlara söz verilen cennetin durumu şöyledir: Orada bozulmayan su ırmakları, tadı değişmeyen süt ırmakları, içenlere zevk veren şarap ırmakları ve süzme bal ırmakları vardır. Orada onlar için meyvelerin her çeşidi vardır. Rablerinden de bağışlama vardır. Bu cennetliklerin durumu, ateşte temelli kalacak olan ve bağırsaklarını parça parça edecek kaynar su içirilen kimselerin durumu gibi olur mu?"},{"n":16,"t":"Onlardan seni dinleyenler vardır. Fakat senin yanından çıktıkları zaman (alay ederek), kendilerine bilgi verilmiş olanlara, \"Az önce ne söyledi?\" derler. İşte bunlar, Allah’ın, kalplerini mühürlediği ve nefislerinin arzularına uyan kimselerdir."},{"n":17,"t":"Hidayete erenlere gelince, Allah onların hidayetini artırır. Onların Allah’a karşı gelmekten sakınmalarını sağlar."},{"n":18,"t":"Onlar kıyametin kendilerine ansızın gelmesinden başka bir şey beklemiyorlar. Muhakkak onun alametleri gelmiştir (ama öğüt almıyorlar). Kıyamet kendilerine gelip çatınca öğüt almaları kendilerine ne fayda verecek?"},{"n":19,"t":"Bil ki Allah’tan başka hiçbir ilâh yoktur. Hem kendinin, hem de inanmış erkek ve kadınların günahlarının bağışlanmasını dile! Allah, gezip dolaştığınız yeri de, içinde kalacağınız yeri de bilir."},{"n":20,"t":"İnananlar, \"Keşke bir sûre indirilse!\" derler. Fakat hükmü apaçık bir sûre indirilip de onda savaştan söz edilince; kalplerinde hastalık olanların, ölüm baygınlığına girmiş kimsenin bakışı gibi sana baktıklarını görürsün. O da onlara pek yakındır."},{"n":21,"t":"İtaat ve güzel bir söz onlar için daha hayırlıdır. İş ciddileşince Allah’a verdikleri söze bağlı kalsalardı, elbette kendileri için daha iyi olurdu."},{"n":22,"t":"Demek, yüz çevirdiğinizde yeryüzünde bozgunculuk çıkaracak ve akrabalık bağlarını koparacaksınız, öyle mi?"},{"n":23,"t":"İşte bunlar, Allah’ın lânetleyip, kulaklarını sağır, gözlerini kör ettiği kimselerdir."},{"n":24,"t":"Onlar Kur’an’ı düşünmüyorlar mı? Yoksa kalplerin üzerinde kilitleri mi var?"},{"n":25,"t":"Kendileri için hidayet yolu belli olduktan sonra gerisingeri dönenleri, şeytan aldatıp peşinden sürüklemiş ve kendilerini boş ümitlere düşürmüştür."},{"n":26,"t":"Bu, münafıkların, Allah’ın indirdiğini beğenmeyen kimselere, \"Bazı işlerde size itaat edeceğiz\" demelerindendir. Allah, onların gizlice konuşmalarını bilir."},{"n":27,"t":"Melekler, onların yüzlerine ve sırtlarına vurarak canlarını alırken hâlleri nasıl olacak?"},{"n":28,"t":"Bu, Allah’ı gazaplandıran şeylere uydukları ve O’nun hoşnut olduğu şeyleri beğenmedikleri içindir. Allah da onların amellerini boşa çıkarmıştır."},{"n":29,"t":"Yoksa, kalplerinde hastalık olanlar Allah’ın, kinlerini ortaya çıkarmayacağını mı sandılar?"},{"n":30,"t":"Biz dileseydik, onları sana gösterirdik de, sen onları yüzlerinden tanırdın. Andolsun, sen onları, konuşma tarzlarından da tanırsın. Allah, yaptıklarınızı bilir."},{"n":31,"t":"Andolsun, içinizden, cihad edenleri ve sabredenleri belirleyinceye ve durumlarınızı ortaya koyuncaya kadar sizi deneyeceğiz."},{"n":32,"t":"İnkâr edenler, Allah yolundan alıkoyanlar ve kendilerine hidayet yolu belli olduktan sonra Peygamber’e karşı gelenler hiçbir şekilde Allah’a zarar veremezler. Allah, onların amellerini boşa çıkaracaktır."},{"n":33,"t":"Ey iman edenler! Allah’a itaat edin, Peygamber’e itaat edin. Amellerinizi boşa çıkarmayın."},{"n":34,"t":"İnkâr eden, Allah yolundan alıkoyan, sonra da inkârcılar olarak ölenler var ya, Allah onları asla bağışlamayacaktır."},{"n":35,"t":"Sakın za’f göstermeyin. Üstün olduğunuz hâlde barışa çağırmayın. Allah sizinle beraberdir. Sizin amellerinizi asla eksiltmeyecektir."},{"n":36,"t":"Şüphesiz dünya hayatı ancak bir oyun ve eğlencedir. Eğer inanır ve Allah’a karşı gelmekten sakınırsanız, O size mükâfatınızı verir ve sizden mallarınızı (tamamen sarf etmenizi) istemez."},{"n":37,"t":"Eğer onları sizden isteyip de sizi zorlasaydı, cimrilik ederdiniz, O da kinlerinizi ortaya çıkarırdı."},{"n":38,"t":"İşte sizler, Allah yolunda harcamaya çağrılıyorsunuz. Ama içinizden cimrilik yapanlar var. Kim cimrilik yaparsa ancak kendi zararına cimrilik yapmış olur. Allah, her bakımdan sınırsız zengindir, siz ise fakirsiniz. Eğer O’ndan yüz çevirecek olursanız, yerinize başka bir toplum getirir de onlar sizin gibi olmazlar."}],[{"n":1,"t":"Şüphesiz biz sana apaçık bir fetih verdik."},{"n":"2-3","t":"Ta ki Allah, senin geçmiş ve gelecek günahlarını bağışlasın, sana olan nimetini tamamlasın, seni doğru yola iletsin ve Allah sana, şanlı bir zaferle yardım etsin."},{"n":4,"t":"O, inananların imanlarını kat kat artırmaları için kalplerine huzur ve güven indirendir. Göklerin ve yerin orduları Allah’ındır. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":5,"t":"Bütün bunlar Allah’ın; inanan erkek ve kadınları, içlerinden ırmaklar akan, içinde temelli kalacakları cennetlere koyması, onların kötülüklerini örtmesi içindir. İşte bu, Allah katında büyük bir başarıdır."},{"n":6,"t":"Bir de, Allah’ın, hakkında kötü zanda bulunan münafık erkeklere ve münafık kadınlara, Allah’a ortak koşan erkeklere ve Allah’a ortak koşan kadınlara azap etmesi içindir. Kötülük girdabı onların başına olsun! Allah onlara gazap etmiş, onları lânetlemiş ve kendilerine cehennemi hazırlamıştır. Orası ne kötü bir varış yeridir!"},{"n":7,"t":"Göklerin ve yerin orduları Allah’ındır. Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":8,"t":"(Ey Muhammed!) Şüphesiz biz seni bir şâhit, bir müjdeci ve bir uyarıcı olarak gönderdik."},{"n":9,"t":"Ey insanlar! Allah’a ve Peygamberine inanasınız, ona yardım edesiniz, ona saygı gösteresiniz ve sabah akşam Allah’ı tespih edesiniz diye (Peygamber’i gönderdik.)"},{"n":10,"t":"Sana bîat edenler ancak Allah’a bîat etmiş olurlar. Allah’ın eli onların ellerinin üzerindedir. Verdiği sözden dönen kendi aleyhine dönmüş olur. Allah’a verdiği sözü yerine getirene, Allah büyük bir mükâfat verecektir."},{"n":11,"t":"Bedevîlerin (savaştan) geri bırakılanları sana, \"Bizi mallarımız ve ailelerimiz alıkoydu; Allah’tan bizim için af dile\" diyecekler. Onlar kalplerinde olmayanı dilleriyle söylerler. De ki: \"Allah, sizin bir zarara uğramanızı dilerse, yahut bir yarar elde etmenizi dilerse, O’na karşı kimin bir şeye gücü yeter? Hayır, Allah, yaptıklarınızdan haberdardır.\""},{"n":12,"t":"(Ey münafıklar!) Siz aslında, Peygamberin ve inananların bir daha ailelerine geri dönmeyeceklerini sanmıştınız. Bu, sizin gönüllerinize güzel gösterildi de kötü zanda bulundunuz ve helâki hak eden bir kavim oldunuz."},{"n":13,"t":"Kim Allah’a ve Peygambere inanmazsa bilsin ki, şüphesiz biz, inkârcılar için alevli bir ateş hazırladık."},{"n":14,"t":"Göklerin ve yerin hükümranlığı Allah’ındır. O, dilediğini bağışlar, dilediğine ceza verir. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":15,"t":"Savaştan geri bırakılanlar, siz ganimetleri almaya giderken, \"Bırakın biz de sizinle gelelim\" diyeceklerdir. Onlar Allah’ın sözünü değiştirmek isterler. De ki: \"Siz bizimle asla gelmeyeceksiniz. Allah, önceden böyle buyurmuştur.\" Onlar, \"Bizi kıskanıyorsunuz\" diyeceklerdir. Hayır, onlar pek az anlarlar."},{"n":16,"t":"Bedevîlerin (savaştan) geri bırakılanlarına de ki: \"Siz, güçlü kuvvetli bir kavme karşı teslim oluncaya kadar savaşmaya çağrılacaksınız. Eğer itaat ederseniz, Allah size güzel bir mükâfat verir. Ama önceden döndüğünüz gibi yine dönerseniz, Allah sizi elem dolu bir azaba uğratır.\""},{"n":17,"t":"Köre güçlük yoktur, topala güçlük yoktur, hastaya güçlük yoktur. (Bunlar savaşa katılmak zorunda değillerdir.) Kim Allah’a ve Peygamberine itaat ederse, Allah onu, içlerinden ırmaklar akan cennetlere koyar. Kim de yüz çevirirse, onu elem dolu bir azaba uğratır."},{"n":"18-19","t":"Şüphesiz Allah, ağaç altında sana bîat ederlerken inananlardan hoşnut olmuştur. Gönüllerinde olanı bilmiş, onlara huzur, güven duygusu vermiş ve onlara yakın bir fetih ve elde edecekleri birçok ganimetler nasip etmiştir. Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":20,"t":"Allah, size, elde edeceğiniz birçok ganimetler vaad etmiştir. Şimdilik bunu size hemen vermiş ve insanların ellerini sizden çekmiştir. (Allah, böyle yaptı) ki, bunlar mü’minler için bir delil olsun, sizi de doğru bir yola iletsin."},{"n":21,"t":"Henüz elde edemediğiniz, fakat Allah’ın, ilmiyle kuşattığı başka (kazançlar) da vardır. Allah, her şeye hakkıyla gücü yetendir."},{"n":22,"t":"İnkâr edenler sizinle savaşsalardı, arkalarını dönüp kaçarlar, sonra da ne bir dost, ne de bir yardımcı bulabilirlerdi."},{"n":23,"t":"Allah’ın öteden beri işleyip duran kanunu (budur). Allah’ın kanununda asla bir değişiklik bulamazsın."},{"n":24,"t":"O, Mekke’nin göbeğinde, sizi onlara karşı üstün kıldıktan sonra, onların ellerini sizden, sizin ellerinizi onlardan çekendir. Allah, yaptıklarınızı hakkıyla görmektedir."},{"n":25,"t":"Onlar, inkâr edenler ve sizi Mescid-i Haram’ı ziyaretten ve (ibadet amacıyla) bekletilen kurbanlıkları yerlerine ulaşmaktan alıkoyanlardır. Eğer, oradaki henüz tanımadığınız inanmış erkeklerle, inanmış kadınları bilmeyerek ezmeniz ve böylece size bir eziyet gelecek olmasaydı, (Allah, Mekke’ye girmenize izin verirdi). Allah, dilediğini rahmetine koymak için böyle yapmıştır. Eğer, inananlarla inkârcılar birbirinden ayrılmış olsalardı, onlardan inkâr edenleri elem dolu bir azaba uğratırdık."},{"n":26,"t":"Hani inkâr edenler kalplerine taassubu, cahiliye taassubunu yerleştirmişlerdi. Allah ise, Peygamberine ve inananlara huzur ve güvenini indirmiş ve onların takva (Allah’a karşı gelmekten sakınma) sözünü tutmalarını sağlamıştı. Zaten onlar buna lâyık ve ehil idiler. Allah, her şeyi hakkıyla bilmektedir."},{"n":27,"t":"Andolsun, Allah, Peygamberinin rüyasını doğru çıkardı. Allah dilerse, siz güven içinde başlarınızı kazıtmış veya saçlarınızı kısaltmış olarak, korkmadan Mescid-i Haram’a gireceksiniz. Allah, sizin bilmediğinizi bildi ve size bundan başka yakın bir fetih daha verdi."},{"n":28,"t":"O, Peygamberini hidayet ve hak din ile gönderendir. (Allah) o hak dini bütün dinlere üstün kılmak için (böyle yaptı). Şahit olarak Allah yeter."},{"n":29,"t":"Muhammed, Allah’ın Resûlüdür. Onunla beraber olanlar, inkârcılara karşı çetin, birbirlerine karşı da merhametlidirler. Onların, rükû ve secde hâlinde, Allah’tan lütuf ve hoşnutluk istediklerini görürsün. Onların secde eseri olan alametleri yüzlerindedir. İşte bu, onların Tevrat’ta ve İncil’de anlatılan durumlarıdır: Onlar filizini çıkarmış, onu kuvvetlendirmiş, kalınlaşmış, gövdesi üzerine dikilmiş, ziraatçıların hoşuna giden bir ekin gibidirler. Allah, kendileri sebebiyle inkârcıları öfkelendirmek için onları böyle sağlam ve dirençli kılar. Allah, içlerinden iman edip salih amel işleyenlere bir bağışlama ve büyük bir mükâfat vaad etmiştir."}],[{"n":1,"t":"Ey iman edenler! Allah’ın ve Peygamberinin önüne geçmeyin. Allah’a karşı gelmekten sakının. Şüphesiz, Allah hakkıyla işitendir, hakkıyla bilendir."},{"n":2,"t":"Ey iman edenler! Seslerinizi, Peygamber’in sesinin üstüne yükseltmeyin. Birbirinize bağırdığınız gibi, Peygamber’e yüksek sesle bağırmayın, yoksa siz farkına varmadan işledikleriniz boşa gider."},{"n":3,"t":"Allah’ın elçisinin huzurunda seslerini kısanlar, Allah’ın, gönüllerini takvâ (Allah’a karşı gelmekten sakınma) konusunda sınadığı kimselerdir. Onlar için bir bağışlanma ve büyük bir mükâfat vardır."},{"n":4,"t":"(Ey Muhammed!) Odaların arkasından sana bağıranların çoğu aklı ermeyen kimselerdir."},{"n":5,"t":"Onlar, sen yanlarına çıkıncaya kadar sabretselerdi, elbette kendileri için daha iyi olurdu. Allah, çok bağışlayandır, çok merhamet edendir."},{"n":6,"t":"Ey iman edenler! Size bir fasık bir haber getirirse, bilmeyerek bir topluluğa zarar verip yaptığınıza pişman olmamak için o haberin doğruluğunu araştırın."},{"n":7,"t":"Bilin ki, aranızda Allah’ın elçisi bulunmaktadır. Eğer o, birçok işlerde size uysaydı, sıkıntıya düşerdiniz. Fakat Allah, size imanı sevdirmiş ve onu gönüllerinize güzel göstermiş; inkârı, fasıklığı ve (İslâm’ın emirlerine) karşı çıkmayı da çirkin göstermiştir. İşte bunlar doğru yolda olanların ta kendileridir."},{"n":8,"t":"Allah, kendi katından bir lütuf ve nimet olarak böyle yaptı. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir"},{"n":9,"t":"Eğer inananlardan iki grup birbirleriyle savaşırlarsa aralarını düzeltin. Eğer biri ötekine karşı haddi aşarsa, Allah’ın buyruğuna dönünceye kadar haddi aşan tarafa karşı savaşın. Eğer (Allah’ın emrine) dönerse, artık aralarını adaletle düzeltin ve (onlara) adaletli davranın. Çünkü Allah, adaletli davrananları sever."},{"n":10,"t":"Mü’minler ancak kardeştirler. Öyleyse kardeşlerinizin arasını düzeltin. Allah’a karşı gelmekten sakının ki size merhamet edilsin."},{"n":11,"t":"Ey iman edenler! Bir topluluk bir diğerini alaya almasın. Belki onlar kendilerinden daha iyidirler. Kadınlar da diğer kadınları alaya almasın. Belki onlar kendilerinden daha iyidirler. Birbirinizi karalamayın, birbirinizi (kötü) lakaplarla çağırmayın. İmandan sonra fasıklık ne kötü bir namdır! Kim de tövbe etmezse, işte onlar zâlimlerin ta kendileridir."},{"n":12,"t":"Ey iman edenler! Zannın birçoğundan sakının. Çünkü zannın bir kısmı günahtır. Birbirinizin kusurlarını ve mahremiyetlerini araştırmayın. Birbirinizin gıybetini yapmayın. Herhangi biriniz ölü kardeşinin etini yemekten hoşlanır mı? İşte bundan tiksindiniz! Allah’a karşı gelmekten sakının. Şüphesiz Allah tövbeyi çok kabul edendir, çok merhamet edendir."},{"n":13,"t":"Ey insanlar! Şüphe yok ki, biz sizi bir erkek ve bir dişiden yarattık ve birbirinizi tanımanız için sizi boylara ve kabilelere ayırdık. Allah katında en değerli olanınız, O’na karşı gelmekten en çok sakınanınızdır. Şüphesiz Allah hakkıyla bilendir, hakkıyla haberdar olandır."},{"n":14,"t":"Bedevîler \"İman ettik\" dediler. De ki: \"İman etmediniz. (Öyle ise, \"iman ettik\" demeyin.) \"Fakat boyun eğdik\" deyin. Henüz iman kalplerinize girmedi. Eğer Allah’a ve Peygamberine itaat ederseniz, yaptıklarınızdan hiçbir şeyi eksiltmez. Allah, çok bağışlayandır, çok merhamet edendir.\""},{"n":15,"t":"İman edenler ancak, Allah’a ve Peygamberine inanan, sonra şüpheye düşmeyen, Allah yolunda mallarıyla ve canlarıyla cihad edenlerdir. İşte onlar doğru kimselerin ta kendileridir."},{"n":16,"t":"(Ey Muhammed!) De ki: \"Siz Allah’a dininizi mi öğretiyorsunuz? Oysa Allah, göklerdeki ve yerdeki her şeyi bilir. Allah, her şeyi hakkıyla bilendir.\""},{"n":17,"t":"Müslüman olmalarını bir lütufta bulunmuş gibi sana hatırlatıyorlar. De ki: \"Müslüman olmanızı bir lütuf gibi bana hatırlatıp durmayın. Tam tersine eğer doğru kimselerseniz sizi imana erdirmesinden dolayı Allah size lütufta bulunmuş oluyor.\""},{"n":18,"t":"Şüphesiz Allah, göklerin ve yerin gaybını bilir. Allah, yaptıklarınızı hakkıyla görendir."}],[{"n":"1-2","t":"Kâf. Şerefli Kur’ân’a andolsun ki kâfirler, aralarından bir uyarıcının gelmesine şaştılar ve şöyle dediler: \"Bu tuhaf bir şeydir!\""},{"n":3,"t":"\"Öldüğümüz ve toprak olduğumuz zaman mı (dirilecekmişiz)? Bu, akla uzak (imkânsız) bir dönüştür!\""},{"n":4,"t":"Şüphesiz biz, toprağın; onlardan neleri eksilttiğini bilmekteyiz. Yanımızda (o bilgileri) koruyan bir kitap vardır."},{"n":5,"t":"Hatta gerçek kendilerine gelince onu yalanladılar. Artık onlar kararsız bir hâldedirler."},{"n":6,"t":"Üstlerindeki göğe bakmazlar mı? Onu nasıl bina ettik, nasıl donattık! Onda hiçbir düzensizlik ve eksiklik yoktur."},{"n":7,"t":"Yeryüzünü de yaydık ve orada sabit dağlar yerleştirdik. Orada her türden iç açıcı çift bitkiler bitirdik."},{"n":8,"t":"Bütün bunlar, içtenlikle Allah’a yönelen her kulun gönül gözünü açmak ve ona öğüt ve ibret vermek içindir."},{"n":"9-11","t":"Gökten de bereketli bir su indirip onunla kullar için rızık olarak bahçeler ve biçilecek taneler (ekinler), birbirine girmiş kat kat tomurcukları olan yüksek hurma ağaçları bitirdik ve böylece onunla ölü bir beldeye hayat verdik. İşte (dirilip kabirlerden) çıkış da böyledir."},{"n":"12-14","t":"Onlardan önce Nûh kavmi, Ress halkı ve Semûd kavmi, Âd ve Firavun, Lût’un kardeşleri, Eykeliler, Tübba’ın kavmi de yalanlamıştı. Bütün bunlar (kendilerine gönderilen) peygamberleri yalanladılar, böylece kendilerini uyardığım şey gerçekleşti."},{"n":15,"t":"İlk yaratmada âcizlik mi gösterdik ki (yeniden yaratamayalım)? Doğrusu onlar, yeniden yaratılış konusunda şüphe içindedirler."},{"n":16,"t":"Andolsun, insanı biz yarattık ve nefsinin ona verdiği vesveseyi de biz biliriz. Çünkü biz, ona şah damarından daha yakınız."},{"n":17,"t":"Üstelik, biri insanın sağ tarafında, biri sol tarafında oturmuş iki alıcı melek de (onun yaptıklarını) alıp kaydetmektedir."},{"n":18,"t":"İnsan hiçbir söz söylemez ki onun yanında (yaptıklarını) gözetleyen (ve kaydeden) hazır bir melek bulunmasın."},{"n":19,"t":"Ölüm sarhoşluğu bir hakikat olarak insana gelir de ona, \"İşte bu, senin öteden beri kaçıp durduğun şeydir\" denir."},{"n":20,"t":"(İnsanlar öldükten sonra tekrar dirilmeleri için) Sûr’a üfürülecek. İşte bu, tehdidin gerçekleşeceği gündür."},{"n":21,"t":"Herkes beraberinde bir sevk edici, bir de şahitlik edici (melek) ile gelir."},{"n":22,"t":"(Ona) \"Andolsun ki sen bundan gaflette idin. Şimdi gaflet perdeni açtık; artık bugün gözün keskindir\" (denir.)"},{"n":23,"t":"Beraberindeki (melek) şöyle der: \"İşte bu yanımdaki hazır.\""},{"n":"24-25","t":"(Allah, şöyle der:) \"Atın cehenneme, (hakka karşı) inatçı, hayrı hep engelleyen, haddi aşan şüpheci her kâfiri!\""},{"n":26,"t":"\"Allah ile beraber, başka bir ilâh edinen o kimseyi atın şiddetli azabın içine!\""},{"n":27,"t":"Arkadaşı (olan şeytan) der ki: \"Ey Rabbimiz! Onu ben azdırmadım, fakat kendisi derin bir sapıklık içinde idi.\""},{"n":28,"t":"Allah, şöyle der: \"Benim huzurumda çekişmeyin. Çünkü ben bu (konudaki) uyarıyı size önceden yaptım.\""},{"n":29,"t":"\"Benim katımda söz değiştirilmez ve ben kullara zulmedici değilim.\""},{"n":30,"t":"O gün Cehenneme, \"Doldun mu?\" deriz. O da, \"daha var mı?\" der."},{"n":31,"t":"Cennet, Allah’a karşı gelmekten sakınanlara uzak olmayacak şekilde yaklaştırılacak."},{"n":"32-33","t":"(Onlara şöyle denir:) \"İşte bu, size (dünyada) vaad edilmekte olan şeydir. O, her tövbe eden, O’nun emrini gözeten için, görmediği hâlde sırf saygıdan dolayı Rahmân’dan korkan ve O’na yönelmiş bir kalp ile gelen kimseler içindir.\""},{"n":34,"t":"\"Oraya esenlikle girin. İşte bu, ebedîlik günüdür.\""},{"n":35,"t":"Orada kendileri için diledikleri her şey vardır. Katımızda daha fazlası da vardır."},{"n":36,"t":"Biz onlardan önce, kendilerinden daha zorlu nice nesilleri helâk ettik de ülke ülke dolaşıp kaçacak delik aradılar. Kaçacak bir yer mi var?"},{"n":37,"t":"Şüphesiz bunda, aklı olan yahut hazır bulunup kulak veren kimseler için bir öğüt vardır."},{"n":38,"t":"Andolsun, gökleri, yeri ve ikisi arasında bulunanları altı günde (altı evrede) yarattık. Bize bir yorgunluk da dokunmadı."},{"n":39,"t":"O hâlde onların söylediklerine sabret ve güneşin doğuşundan önce de, batışından önce de Rabbini hamd ederek tespih et."},{"n":40,"t":"Gecenin bir kısmında ve secdelerin ardından da O’nu tespih et."},{"n":41,"t":"(Ey Muhammed!) Çağırıcının yakın bir yerden sesleneceği gün, (o sese) kulak ver."},{"n":42,"t":"O gün insanlar hakka çağıran o korkunç sesi işiteceklerdir. İşte bu, (kabirlerden) çıkış günüdür."},{"n":43,"t":"Şüphesiz biz diriltir ve öldürürüz. Dönüş de ancak bizedir."},{"n":44,"t":"O gün yer, onların üzerinden süratle yarılıp açılır. Bu, (hesap için) bir toplamadır, bize göre kolaydır."},{"n":45,"t":"Biz onların ne dediklerini çok iyi biliyoruz. Sen, onlara karşı bir zorba değilsin. O hâlde sen, benim uyarımdan korkan kimselere Kur’an ile öğüt ver."}],[{"n":"1-6","t":"Tozutup savuranlara, ağırlık taşıyanlara, kolaylıkla akanlara, iş bölüştürenlere andolsun ki, size vaad olunan şey elbette doğrudur. Hesap ve ceza mutlaka gerçekleşecektir."},{"n":"7-8","t":"Yollara (yıldızların dolaştığı yörüngelere) sahip göğe andolsun ki, muhakkak siz, (peygamber hakkında) çelişkili sözler söylüyorsunuz."},{"n":9,"t":"Ondan (Peygamber’den) çevrilen çevrilir."},{"n":"10-11","t":"Cehalet içinde gaflete dalmış olan (ve \"Muhammed şairdir, delidir\" diyen) yalancılar kahrolsun!"},{"n":12,"t":"\"Ceza günü ne zaman?\" diye sorarlar."},{"n":"13-14","t":"Ateş üzerinde azaba uğratılacakları gün (görevli melekler onlara şöyle der): \"Azabınızı tadın! İşte acele isteyip durduğunuz şey budur.\""},{"n":"15-16","t":"Şüphesiz Allah’a karşı gelmekten sakınanlar, Rablerinin kendilerine verdiği şeyleri alarak cennetlerde ve pınar başlarında bulunurlar. Şüphesiz onlar bundan önce iyilik yapan kimselerdi."},{"n":17,"t":"Geceleri pek az uyurlardı."},{"n":18,"t":"Seherlerde bağışlama dilerlerdi."},{"n":19,"t":"Mallarında (yardım) isteyen ve (iffetinden dolayı isteyemeyip) mahrum olanlar için bir hak vardır."},{"n":"20-21","t":"Kesin olarak inananlar için yeryüzünde ve kendi nefislerinizde birçok alametler vardır. Hâlâ görmüyor musunuz?"},{"n":22,"t":"Gökte rızkınız ve size vaad olunan şeyler vardır."},{"n":23,"t":"Göğün ve yerin Rabbine andolsun ki o (size va’dolunanlar), sizin konuşmanız gibi gerçektir."},{"n":24,"t":"(Ey Muhammed!) İbrahim’in ağırlanan misafirlerinin haberi sana geldi mi?"},{"n":25,"t":"Hani onlar, İbrahim’in yanına varmışlar ve \"Selâm olsun sana!\" demişlerdi. O da \"Size de selâm olsun.\" demiş, \"Bunlar tanınmamış (yabancı) kimseler\" (diye düşünmüştü)."},{"n":26,"t":"Hissettirmeden ailesinin yanına gidip, (pişirilmiş) semiz bir buzağı getirdi."},{"n":27,"t":"Onu önlerine koydu. \"Yemez misiniz?\" dedi."},{"n":28,"t":"(Yemediklerini görünce) onlardan İbrahim’in içine bir korku düştü. Onlar, \"korkma\" dediler ve onu bilgin bir oğul ile müjdelediler."},{"n":29,"t":"Bunun üzerine karısı bir çığlık kopararak yönelip elini yüzüne vurdu. \"Ben kısır bir kocakarıyım (nasıl çocuğum olabilir?)\" dedi."},{"n":30,"t":"Onlar dediler ki: \"Rabbin böyle buyurdu. Şüphesiz O, hüküm ve hikmet sahibidir, hakkıyla bilendir.\""},{"n":31,"t":"İbrahim, onlara: \"O hâlde asıl işiniz nedir ey elçiler?\" dedi."},{"n":"32-34","t":"Onlar şöyle dediler: \"Biz suçlu bir kavme (Lût’un kavmine), üzerlerine çamurdan, pişirilmiş ve Rabbinin katında haddi aşanlar için belirlenmiş taşlar yağdırmak için gönderildik.\""},{"n":35,"t":"Orada (Lût’un yöresinde) bulunan mü’minleri çıkardık."},{"n":36,"t":"Zaten orada bir ev halkından başka müslüman bulamadık."},{"n":37,"t":"Orada, elem dolu azaptan korkacaklar için bir ibret bıraktık."},{"n":38,"t":"Mûsâ kıssasında da ibret vardır. Hani biz onu açık bir delil ile Firavun’a göndermiştik."},{"n":39,"t":"O ise kuvvetine güvenerek yüz çevirdi ve \"Bu bir büyücü veya delidir\" dedi."},{"n":40,"t":"Bunun üzerine biz de kendisini ve ordularını yakalayıp denize attık. O ise (pişman olmuş), kendini kınıyordu."},{"n":41,"t":"Âd kavminde de ibretler vardır. Hani onların üzerine köklerini kesen rüzgârı göndermiştik."},{"n":42,"t":"Üzerine uğradığı hiçbir şeyi bırakmıyor, mutlaka onu kül ediyordu."},{"n":43,"t":"Semûd kavminde de ibretler vardır. Hani onlara, \"Bir süreye kadar faydalanın bakalım\" denmişti."},{"n":44,"t":"Derken Rablerinin emrinden uzaklaşıp azmışlardı. Bu yüzden bakınıp dururken kendilerini yıldırım çarpıvermişti."},{"n":45,"t":"Artık, ne yerlerinden kalkmaya güçleri yetti, ne de başkasından yardım görebildiler."},{"n":46,"t":"Bunlardan önce de Nûh kavmini helâk etmiştik. Çünkü onlar fâsık bir toplum idiler."},{"n":47,"t":"Göğü kudretimizle biz kurduk ve şüphesiz bizim (her şeye) gücümüz yeter."},{"n":48,"t":"Yeri de biz döşedik. Biz ne güzel döşeyiciyiz."},{"n":49,"t":"Düşünüp ibret alasınız diye her şeyden (erkekli dişili) iki eş yarattık."},{"n":50,"t":"O hâlde Allah’a koşun. Şüphesiz ben, size O’nun katından gönderilmiş açık bir uyarıcıyım."},{"n":51,"t":"Allah ile beraber başka bir ilâh edinmeyin. Gerçekten ben, size, Allah tarafından gönderilmiş açık bir uyarıcıyım."},{"n":52,"t":"İşte böyle! Onlardan öncekilere hiçbir peygamber gelmemişti ki, \"O bir büyücüdür\" yahut \"bir delidir\" demiş olmasınlar."},{"n":53,"t":"Onlar bunu birbirlerine tavsiye mi ettiler (ki hep aynı şeyleri söylüyorlar)? Hayır, onlar azgın bir topluluktur."},{"n":54,"t":"Onun için, onlardan yüz çevir. Artık kınanacak değilsin."},{"n":55,"t":"Sen yine de öğüt ver. Çünkü öğüt mü’minlere fayda verir."},{"n":56,"t":"Ben cinleri ve insanları, ancak bana kulluk etsinler diye yarattım."},{"n":57,"t":"Ben, onlardan bir rızık istemiyorum. Bana yedirmelerini de istemiyorum."},{"n":58,"t":"Şüphesiz Allah rızık verendir, güçlüdür, çok kuvvetlidir."},{"n":59,"t":"Şüphesiz zulmedenler için (önceki müşrik) arkadaşlarının azap payı gibi payları vardır. Artık azabımı acele istemesinler."},{"n":60,"t":"Uyarıldıkları günlerinden dolayı vay o inkâr edenlerin hâline!"}],[{"n":"1-7","t":"Tûr’a, yayılmış ince deri sayfalara düzenle yazılmış kitaba, \"Beyt-i Ma’mur\"a, yükseltilmiş tavana (göğe), kabaran denize andolsun ki, şüphesiz Rabbinin azabı mutlaka gerçekleşecektir."},{"n":8,"t":"Onu geri çevirecek hiçbir şey yoktur."},{"n":9,"t":"O gün gök şiddetle sallanıp çalkalanır."},{"n":10,"t":"Dağlar yürüdükçe yürür."},{"n":"11-12","t":"İşte o gün, içine daldıkları dünya zevki içinde eğlenip oyalanan yalanlayıcıların vay hâline!"},{"n":"13-14","t":"Cehennem ateşine itilip atılacakları gün onlara, \"İşte bu yalanlamakta olduğunuz ateştir\" denilir."},{"n":15,"t":"\"Bu Kur’an mı bir büyü imiş, yoksa siz mi (gerçeği) göremiyormuşsunuz?\""},{"n":16,"t":"\"Girin oraya. İster dayanın, ister dayanmayın, sizin için birdir. Size ancak yapmakta olduğunuzun karşılığı veriliyor.\""},{"n":"17-18","t":"Şüphesiz Allah’a karşı gelmekten sakınanlar Rablerinin, kendilerine verdiği şeylerle zevk ve mutluluk duyarak cennetlerde ve nimetler içinde bulunurlar. Rableri onları cehennem azabından korumuştur."},{"n":"19-20","t":"Onlara, \"Dünya’da yapmakta olduklarınızın karşılığında, sıra sıra dizilmiş koltuklara dayanarak afiyetle yiyin için\" denir. Biz, onlara, iri gözlü güzel hurileri eş olarak vermişizdir."},{"n":21,"t":"İman eden ve nesilleri de iman konusunda kendilerinin yoluna uyanlar var ya, biz onların nesillerini kendilerine kattık. Bununla beraber onların amellerinden hiçbir şey eksiltmeyiz. Herkes kazandığı karşılığında rehindir."},{"n":22,"t":"Onlara canlarının istediği meyve ve etten bol bol verdik."},{"n":23,"t":"Orada, (içilince) boş söz söyletmeyen, günah işletmeyen dolu bir kadehi elden ele dolaştırırlar."},{"n":24,"t":"Hizmetlerine verilmiş, kabuğunda saklı inci gibi gençler etraflarında dönüp dolaşırlar."},{"n":25,"t":"Birbirlerine dönüp (\"Ne iyilik yaptınız da bu nimetlere ulaştınız?\" diye) sorarlar."},{"n":26,"t":"Derler ki: \"Şüphesiz daha önce biz, ailemiz içinde yaşarken (Allah’a isyandan) korkardık.\""},{"n":27,"t":"\"Allah da bize lütfetti ve bizi iliklere işleyen cehennem azabından korudu.\""},{"n":28,"t":"\"Gerçekten biz bundan önce O’na yalvarıyorduk. Şüphesiz O, iyilik edendir, çok merhametlidir.\""},{"n":29,"t":"(Ey Muhammed!) O hâlde, sen öğüt ver. Rabbinin nimeti sayesinde, sen ne bir kâhinsin, ne de bir deli."},{"n":30,"t":"Yoksa onlar, \"O bir şairdir; onun, zamanın felaketlerine uğramasını bekliyoruz\" mu diyorlar?"},{"n":31,"t":"Onlara de ki: \"Bekleyin. Ben de sizinle beraber bekleyenlerdenim.\""},{"n":32,"t":"Bunu kendilerine akılları mı emrediyor, yoksa onlar azgın bir topluluk mudur?"},{"n":33,"t":"Yoksa \"O Kur’an’ı kendisi uydurup söyledi\" mi diyorlar? Hayır, (sırf inatlarından dolayı) iman etmiyorlar."},{"n":34,"t":"Eğer doğru söyleyenler iseler, haydi onun gibi bir söz getirsinler!"},{"n":35,"t":"Acaba onlar herhangi bir yaratıcı olmadan mı yaratıldılar? Yoksa kendileri mi yaratıcıdırlar?"},{"n":36,"t":"Yoksa, gökleri ve yeri onlar mı yarattılar? Hayır, onlar kesin olarak inanmıyorlar."},{"n":37,"t":"Yoksa, Rabbinin hazineleri onların yanında mıdır? Ya da her şeye hâkim olan kendileri midir?"},{"n":38,"t":"Yoksa onların, kendisi vasıtasıyla (ilâhî vahyi) dinleyecekleri bir merdivenleri mi var? (Eğer varsa) dinleyenleri, açık bir delil getirsin!"},{"n":39,"t":"Yoksa, kızlar O’na (Allah’a) da oğullar size mi?"},{"n":40,"t":"Yoksa sen onlardan (tebliğ görevine karşılık) bir ücret istiyorsun da onlar, borçtan ağır bir yük altında mı kalmışlardır?"},{"n":41,"t":"Yoksa, gayb ilmi onların yanında da ondan mı yazıyorlar?"},{"n":42,"t":"Yoksa, bir tuzak mı kurmak istiyorlar? Asıl, inkâr edenler tuzağa düşecek olanlardır."},{"n":43,"t":"Yoksa, onların Allah’tan başka bir ilâhı mı var? Allah, onların ortak koştuklarından uzaktır."},{"n":44,"t":"Gökten düşmekte olan parçalar görseler, \"Bunlar, üst üste yığılmış bulutlardır\" derler."},{"n":45,"t":"Artık sen çarpılacakları günlerine kadar onları kendi hâllerine bırak."},{"n":46,"t":"O gün tuzakları kendilerine hiçbir fayda vermeyecektir ve kendilerine yardım da edilmeyecektir."},{"n":47,"t":"Şüphesiz zulmedenlere bundan başka bir azap daha var. Fakat onların çoğu bilmezler."},{"n":48,"t":"Rabbinin hükmüne sabret. Çünkü sen gözlerimizin önündesin, kalktığında Rabbini hamd ile tespih et."},{"n":49,"t":"Gecenin bir kısmında ve yıldızların batışı sırasında O’nu tespih et."}],[{"n":"1-2","t":"Battığı zaman yıldıza andolsun ki, arkadaşınız (Muhammed haktan) sapmadı ve azmadı."},{"n":3,"t":"O, nefis arzusu ile konuşmaz."},{"n":4,"t":"(Size okuduğu) Kur’an ancak kendisine bildirilen bir vahiydir."},{"n":"5-7","t":"(Kur’an’ı) ona, üstün güçlere sahip, muhteşem görünümlü (Cebrail) öğretti. O, en yüksek ufukta bulunuyorken (aslî sûretine girip) doğruldu."},{"n":8,"t":"Sonra (ona) yaklaştı derken sarkıp daha da yakın oldu."},{"n":9,"t":"(Peygambere olan mesafesi) iki yay aralığı kadar, yahut daha az oldu."},{"n":10,"t":"Böylece Allah kuluna vahyedeceğini vahyetti."},{"n":11,"t":"Kalp, (gözün) gördüğünü yalanlamadı."},{"n":12,"t":"(Şimdi siz) gördüğü şey hakkında onunla tartışıyor musunuz?"},{"n":13,"t":"Andolsun ki, o, Cebrail’i bir başka inişte daha (aslî suretiyle) görmüştü."},{"n":14,"t":"Sidretü’l-Müntehâ’nın yanında."},{"n":15,"t":"Me’vâ cenneti onun (Sidre’nin) yanındadır."},{"n":16,"t":"O zaman Sidre’yi kaplayan kaplamıştı."},{"n":17,"t":"Göz (gördüğünden) şaşmadı ve (onu) aşmadı."},{"n":18,"t":"Andolsun, o, Rabbinin en büyük alametlerinden bir kısmını gördü."},{"n":"19-20","t":"Lât ve Uzza’ya ve diğer üçüncüsü Menat’a ne dersiniz?"},{"n":21,"t":"Erkek size de, dişi O’na mı?"},{"n":22,"t":"Öyle ise bu çok insafsızca bir paylaştırmadır."},{"n":23,"t":"Onlar ancak sizin ve atalarınızın (ilâh edindiğiniz şeylere) taktığınız isimlerdir. Allah, onlar hakkında hiçbir delil indirmemiştir. Onlar (putperestler) yalnız zanna ve nefislerin arzusuna tâbi oluyorlar. Andolsun ki, kendilerine, Rableri katından yol gösterici gelmiştir."},{"n":24,"t":"Yoksa insan (kayıtsız şartsız), her temenni ettiği şeye sahip mi olacaktır?"},{"n":25,"t":"Oysa, Ahiret de dünya da Allah’ındır."},{"n":26,"t":"Göklerde nice melekler vardır ki onların şefaatleri; ancak Allah’ın izniyle, dilediği ve hoşnut olduğu kimselere yarar sağlar."},{"n":27,"t":"Şüphesiz ahirete iman etmeyenler, meleklere dişi isimleri veriyorlar."},{"n":28,"t":"Hâlbuki onların bu hususta hiçbir bilgileri yoktur. Onlar sadece zanna uyuyorlar. Şüphesiz zan, hakikat namına hiçbir şey ifade etmez."},{"n":29,"t":"Öyle ise bizim zikrimizden (Kur’an’dan) yüz çeviren ve dünya hayatından başka bir şey istemeyen kimselerden yüz çevir."},{"n":30,"t":"İşte onların ilimden ulaşabildikleri nokta! Şüphesiz senin Rabbin, yolundan sapanı daha iyi bilir. O, hidayete ereni de daha iyi bilir."},{"n":31,"t":"Göklerdeki her şey, yerdeki her şey Allah’ındır. (Bu) kötülük edenleri yaptıklarıyla cezalandırması, iyilik edenleri de daha güzeliyle mükâfatlandırması için (böyle)dir."},{"n":32,"t":"Onlar, ufak tefek kusurları dışında, büyük günahlardan ve çirkin işlerden uzak duran kimselerdir. Şüphesiz Rabbin, bağışlaması çok geniş olandır. Sizi, topraktan yarattığında da ve analarınızın karnında ceninler iken de, en iyi bilendir. Bunun için kendinizi temize çıkarmayın. Çünkü O, Allah’a karşı gelmekten sakınanları en iyi bilendir."},{"n":"33-34","t":"Şimdi yüz çevireni; pek az verip de kaskatı cimrileşeni gördün mü?"},{"n":35,"t":"Gayb’ın ilmi kendi yanında da o gerçeği mi görüyor?"},{"n":"36-37","t":"Yoksa, Mûsâ’nın ve Allah’ın emirlerini bütünüyle yerine getiren İbrahim’in sahifelerindeki şu hakikatler kendisine haber verilmedi mi?"},{"n":38,"t":"Hiçbir günahkâr, başkasının günah yükünü yüklenmez."},{"n":39,"t":"İnsan için ancak çalıştığı vardır."},{"n":40,"t":"Şüphesiz onun çalışması ileride görülecektir."},{"n":41,"t":"Sonra çalışmasının karşılığı kendisine tastamam verilecektir."},{"n":42,"t":"Şüphesiz en son varış Rabbinedir."},{"n":43,"t":"Şüphesiz O, güldürür ve ağlatır."},{"n":44,"t":"Şüphesiz O, öldürür ve diriltir."},{"n":"45-46","t":"Şüphesiz O, iki eşi, erkeği ve dişiyi, (rahme) atıldığında az bir sudan (meniden) yaratmıştır."},{"n":47,"t":"Şüphesiz tekrar diriltmek de O’na aittir."},{"n":48,"t":"Şüphesiz O, başkalarına muhtaç olmaktan kurtardı ve varlık sahibi kıldı."},{"n":49,"t":"Şüphesiz O, Şi’râ’nın Rabbidir."},{"n":"50-51","t":"Şüphesiz O, önce gelen Âd kavmini ve Semûd kavmini helâk etti ve hiç kimseyi bırakmadı."},{"n":52,"t":"Daha önce de Nûh’un kavmini helâk etmişti. Şüphesiz onlar daha zalim ve daha azgın kimselerdi."},{"n":"53-54","t":"O, \"Mu’tefike\"yi de kaldırıp yere çarpmış ve onlara örttüğü azap örtüsünü örtmüştür."},{"n":55,"t":"O hâlde Rabbi’nin nimetlerinin hangisinden şüphe ediyorsun (ey insan!)."},{"n":56,"t":"Bu da önceki uyarıcılardan bir uyarıcıdır."},{"n":57,"t":"Yaklaşmakta olan (Kıyamet iyice) yaklaştı."},{"n":58,"t":"Onu Allah’tan başka açacak kimse yoktur."},{"n":"59-61","t":"Şimdi siz gaflet içinde eğlenerek bu söze mi (Kur’an’a mı) şaşıyorsunuz, gülüyorsunuz da ağlamıyorsunuz?"},{"n":62,"t":"Haydi Allah’a secde edin ve O’na kulluk edin."}],[{"n":1,"t":"Kıyamet yaklaştı ve ay yarıldı."},{"n":2,"t":"Onlar bir mucize görseler yüz çevirirler ve \"Süregelen bir sihirdir\" derler."},{"n":3,"t":"Peygamberi yalanladılar, nefislerinin arzularına uydular. Hâlbuki her iş, (Allah nasıl takdir ettiyse öylece) gerçekleşecek (değişmeyecek)tir."},{"n":4,"t":"Andolsun, onlara içinde caydırıcı tehditlerin bulunduğu haberler geldi."},{"n":5,"t":"Bu haberler, zirveye ulaşmış birer hikmettir! Fakat uyarılar fayda vermiyor!"},{"n":"6-7","t":"O hâlde sen de onlardan yüz çevir. Onlar, o davetçinin (İsrafil’in benzeri görülmemiş) bilinmedik (korkunç) bir şeye çağırdığı gün, gözleri düşmüş bir hâlde dağılmış çekirgeler gibi kabirlerden çıkarlar."},{"n":8,"t":"Davetçiye doğru koşarlarken kâfirler, \"Bu zor bir gün\" derler."},{"n":9,"t":"Onlardan önce Nuh’un kavmi de yalanlamıştı. Onlar kulumuzu yalanlayıp \"Bu bir delidir\" dediler ve kulumuz (tebliğ görevinden) alıkonuldu."},{"n":10,"t":"O da Rabbine, \"Ey Rabbim! Ben yenilgiye uğradım, yardım et\" diye dua etti."},{"n":11,"t":"Biz de göğün kapılarını dökülürcesine yağan bir yağmurla açtık."},{"n":12,"t":"Yeryüzünü pınar pınar fışkırttık. Derken sular takdir edilmiş bir iş için birleşti."},{"n":13,"t":"Biz Nûh’u çivilerle perçinli levhalardan oluşan gemiye bindirdik."},{"n":14,"t":"Gemi, inkâr edilen kimseye (Nuh’a) bir mükâfat olarak gözetimimiz altında yüzüyordu."},{"n":15,"t":"Andolsun, biz onu (tufan olayını) bir ibret olarak bıraktık. Var mı düşünüp öğüt alan?"},{"n":16,"t":"Benim azabım ve uyarılarım nasılmış (gördüler)!"},{"n":17,"t":"Andolsun biz, Kur’an’ı düşünüp öğüt almak için kolaylaştırdık. Var mı düşünüp öğüt alan?"},{"n":18,"t":"Âd kavmi de (Hûd’u) yalanladı. Azabım ve uyarılarım nasılmış!"},{"n":19,"t":"Biz onların üstüne, uğursuzluğu sürekli bir günde gürültülü ve dondurucu bir rüzgâr gönderdik."},{"n":20,"t":"İnsanları köklerinden sökülmüş hurma kütükleri gibi kaldırıp atıyordu."},{"n":21,"t":"Azabım ve uyarılarım nasılmış, (gördüler)!"},{"n":22,"t":"Andolsun biz, Kur’an’ı düşünüp öğüt almak için kolaylaştırdık. Var mı düşünüp öğüt alan?"},{"n":"23-24","t":"Semûd kavmi de uyarıcıları yalanlamış ve şöyle demişlerdi: \"İçimizden bir insana mı uyacağız? (Asıl) o takdirde biz apaçık bir sapıklık ve delilik içine düşmüş oluruz.\""},{"n":25,"t":"\"Bizim aramızdan vahiy ona mı verildi? Hayır o, yalancının, şımarığın biridir.\""},{"n":26,"t":"Onlar yarın bilecekler: Kimmiş yalancı, kimmiş şımarık!"},{"n":27,"t":"(Salih’e şöyle demiştik:) \"Şüphesiz biz, onlara bir imtihan olmak üzere, o dişi deveyi göndereceğiz. Şimdi onları gözetle ve sabret.\""},{"n":28,"t":"\"Onlara, suyun (deve ile) kendileri arasında (nöbetleşe) paylaştırıldığını, bildir. Her su nöbetinde sahibi hazır bulunsun.\""},{"n":29,"t":"Derken, (kavmin en azgını olan) arkadaşlarını çağırdılar. O da işe koyuldu ve deveyi kesti."},{"n":30,"t":"Fakat azabım ve uyarılarım nasılmış!"},{"n":31,"t":"Şüphesiz biz, onların üzerine tek bir korkunç ses gönderdik de, onlar, ağıldaki hayvanların çiğneyip ufaladıkları kuru çöpler gibi oldular."},{"n":32,"t":"Andolsun biz, Kur’an’ı düşünüp öğüt almak için kolaylaştırdık. Var mı düşünüp öğüt alan?"},{"n":33,"t":"Lût kavmi de uyarıcıları yalanladı."},{"n":"34-35","t":"Şüphesiz biz de üzerlerine taşlar savuran bir rüzgâr gönderdik. Yalnız Lût’un ailesi başka. Katımızdan bir nimet olarak bir seher vakti onları kurtardık. Şükredenleri işte böyle mükâfatlandırırız."},{"n":36,"t":"Andolsun, Lût onları bizim şiddetli azabımızla uyardı. Fakat onlar bu uyarıları kuşkuyla karşıladılar."},{"n":37,"t":"Andolsun, onlar onun (meleklerden olan) misafirlerinden nefislerindeki kötü arzuları tatmin etmek istediler. Biz de onların gözlerini silme kör ettik. \"Haydi azabımı ve uyarılarımı tadın!\" dedik."},{"n":38,"t":"Andolsun, onlara sabahleyin erkenden kalıcı bir azap geldi."},{"n":39,"t":"\"Haydi azabımı ve uyarılarımı tadın!\" dedik."},{"n":40,"t":"Andolsun, biz Kur’an’ı düşünüp öğüt almak için kolaylaştırdık. Var mı düşünüp öğüt alan?"},{"n":41,"t":"Andolsun, Firavun’un ailesine de uyarıcılar gelmişti."},{"n":42,"t":"Bütün âyetlerimizi yalanladılar. Biz de onları mutlak güç ve iktidar sahibinin yakalaması gibi yakaladık."},{"n":43,"t":"(Ey Mekkeliler!) Sizin kâfirleriniz onlardan daha mı hayırlı? Yoksa sizin için kitaplarda bir berat mı var?"},{"n":44,"t":"Yoksa onlar, \"Biz yardımlaşan (güçlü) bir topluluğuz\" mu diyorlar?"},{"n":45,"t":"O topluluk yakında (Bedir’de) bozguna uğrayacak ve arkalarını dönüp kaçacaklardır."},{"n":46,"t":"Hayır, kıyamet, onların (görecekleri asıl azabın) vaktidir. Kıyamet (azabı) ise daha müthiş ve daha acıdır."},{"n":47,"t":"Şüphesiz suçlular (müşrikler) sapıklık ve ateşler içindedirler."},{"n":48,"t":"Yüzüstü ateşe sürüklendikleri gün kendilerine, \"Cehennemin dokunuşunu tadın!\" denecek."},{"n":49,"t":"Gerçekten biz, her şeyi bir ölçü ve dengede yarattık."},{"n":50,"t":"Emrimiz ancak bir tek emirdir. Göz kırpması gibidir. (Anında gerçekleşir.)"},{"n":51,"t":"Andolsun, biz sizin gibileri hep helâk ettik. Fakat var mı düşünüp öğüt alan?"},{"n":52,"t":"İşledikleri her şey ise kitaplarda kayıtlıdır."},{"n":53,"t":"Küçük, büyük her şey satır satır yazılmıştır."},{"n":54,"t":"Şüphesiz Allah’a karşı gelmekten sakınanlar cennetlerde, ırmak başlarındadırlar."},{"n":55,"t":"Muktedir bir hükümdarın katında, doğruluk meclisindedirler."}],[{"n":"1-2","t":"Rahmân, Kur’an’ı öğretti."},{"n":3,"t":"İnsanı yarattı."},{"n":4,"t":"Ona beyanı (düşünüp ifade etmeyi) öğretti."},{"n":5,"t":"Güneş ve ay bir hesaba göre hareket etmektedir."},{"n":6,"t":"Otlar ve ağaçlar (Allah’a) boyun eğerler."},{"n":7,"t":"Göğü yükseltti ve ölçüyü koydu."},{"n":8,"t":"Ölçüde haddi aşmayın."},{"n":9,"t":"Tartıyı adaletle yapın, teraziyi eksik tutmayın."},{"n":10,"t":"Allah, yeri yaratıklar için var etti."},{"n":11,"t":"Orada meyve(ler) ve salkımlı hurma ağaçları vardır."},{"n":12,"t":"Yapraklı taneler, hoş kokulu bitkiler vardır."},{"n":13,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":14,"t":"Allah, insanı pişmiş çamur gibi bir balçıktan yarattı."},{"n":15,"t":"\"Cin\"i de yalın bir ateşten yarattı."},{"n":16,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":17,"t":"O, iki doğunun ve iki batının Rabbidir."},{"n":18,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":19,"t":"(Suları acı ve tatlı olan) iki denizi salıvermiştir; birbirine kavuşuyorlar."},{"n":20,"t":"(Fakat) aralarında bir engel vardır, birbirine geçip karışmıyorlar."},{"n":21,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":22,"t":"O denizlerin her ikisinden de inci ve mercan çıkar."},{"n":23,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":24,"t":"Denizde akıp giden dağlar gibi yüksek gemiler de O’nundur."},{"n":25,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":26,"t":"Yer üzerinde bulunan her canlı yok olacaktır."},{"n":27,"t":"Ancak azamet ve ikram sahibi Rabbinin zâtı bâki kalacaktır."},{"n":28,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":29,"t":"Göklerde ve yerde bulunanlar, (her şeyi) O’ndan isterler. O, her an yeni bir ilâhî tasarruftadır."},{"n":30,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":31,"t":"Yakında sizi de hesaba çekeceğiz, ey cinler ve insanlar!"},{"n":32,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":33,"t":"Ey cin ve insan toplulukları! Göklerin ve yerin uçlarından bucaklarından geçip gitmeye gücünüz yeterse geçip gidin. Büyük bir güç olmadıkça geçip gidemezsiniz."},{"n":34,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":35,"t":"Üstünüze ateşten yalın bir alevle kıpkızıl bir duman gönderilir de kendinizi koruyamazsınız."},{"n":36,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":37,"t":"Gök yarılıp da, yanıp kızaran yağ gibi kırmızı gül hâline geldiği zaman (hâliniz ne olur?)"},{"n":38,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":39,"t":"İşte o gün ne insana, ne cine günahı sorulmayacak."},{"n":40,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":41,"t":"Suçlular simalarından tanınır da, perçemlerinden ve ayaklarından yakalanırlar."},{"n":42,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":43,"t":"İşte bu suçluların yalanladıkları cehennemdir."},{"n":44,"t":"Onlar, cehennem ateşi ile yüksek derecede kaynar su arasında gider gelirler."},{"n":45,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":46,"t":"Rabbinin huzurunda (hesap vermek üzere) duracağından korkan kimseye iki cennet vardır."},{"n":47,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":48,"t":"İki cennet de (ağaçlar, meyveler, rengârenk bitkiler gibi) çeşit çeşit güzelliklerle bezenmiştir."},{"n":49,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":50,"t":"İçlerinde akan iki pınar vardır."},{"n":51,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":52,"t":"İkisinde de her meyveden çift çift vardır."},{"n":53,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":54,"t":"Onlar astarları kalın ipekten olan döşeklere yaslanırlar. Bu iki cennetin meyveleri (zahmetsizce alınacak kadar) yakındır."},{"n":55,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":56,"t":"Oralarda bakışlarını sadece eşlerine çevirmiş dilberler vardır. Onlara eşlerinden önce ne bir insan, ne bir cin dokunmuştur."},{"n":57,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":58,"t":"Onlar sanki yakut ve mercandır."},{"n":59,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":60,"t":"İyiliğin karşılığı, yalnız iyiliktir."},{"n":61,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":62,"t":"Bu iki cennetten başka iki cennet daha vardır."},{"n":63,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":64,"t":"O iki cennet koyu yeşil renktedir."},{"n":65,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":66,"t":"İçlerinde kaynayan iki pınar vardır."},{"n":67,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":68,"t":"İçlerinde her türlü meyve, hurma ve nar vardır."},{"n":69,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":70,"t":"Onlarda huyları güzel, yüzleri güzel dilberler vardır."},{"n":71,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":72,"t":"Onlar, çadırlara kapanmış hurilerdir."},{"n":73,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":74,"t":"Onlara, eşlerinden önce ne bir insan ne bir cin dokunmuştur."},{"n":75,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":76,"t":"Onlar yeşil yastıklara ve güzel yaygılara yaslanırlar, (nimetlenirler)."},{"n":77,"t":"O hâlde, Rabbinizin hangi nimetlerini yalanlıyorsunuz?"},{"n":78,"t":"Azamet ve ikram sahibi Rabbinin adı yücedir."}],[{"n":"1-2","t":"Kesin gerçekleşecek (olan Kıyamet) koptuğu zaman, onun kopuşunu yalanlayacak kimse olmayacaktır."},{"n":"3-7","t":"Yeryüzü şiddetle sarsıldığı, dağlar parça parça dağılıp saçılmış toz olduğu ve siz de üç sınıf olduğunuz zaman, O, (kimini) yükseltir, (kimini) alçaltır."},{"n":8,"t":"Ahiret mutluluğuna erenler var ya; ne mutlu kimselerdir!"},{"n":9,"t":"Kötülüğe batanlara gelince; ne mutsuz kimselerdir!"},{"n":"10-11","t":"(İman ve amelde) öne geçenler ise (Ahirette de) öne geçenlerdir. İşte onlar (Allah’a) yaklaştırılmış kimselerdir."},{"n":12,"t":"Onlar, Naîm cennetlerindedirler."},{"n":"13-14","t":"Onların çoğu öncekilerden, azı da sonrakilerdendir."},{"n":"15-16","t":"Onlar, karşılıklı yaslanmış vaziyette mücevheratla işlenmiş tahtlar üzerindedirler."},{"n":"17-21","t":"Ebediyen genç kalan uşaklar, onların etrafında; içmekle başlarının dönmeyeceği ve sarhoş olmayacakları, cennet pınarından doldurulmuş sürahileri, ibrikleri ve kadehleri, beğendikleri meyveleri ve arzu ettikleri kuş etlerini dolaştırırlar."},{"n":"22-23","t":"Onlar için saklı inciler gibi, iri gözlü huriler de vardır."},{"n":24,"t":"(Bütün bunlar) işledikleri amellere karşılık bir mükâfat olarak (verilir.)"},{"n":25,"t":"Orada ne boş bir söz, ne de günaha sokan bir şey işitirler."},{"n":26,"t":"Sadece \"selâm!\", \"selâm!\" sözünü işitirler."},{"n":27,"t":"Ahiret mutluluğuna erenler, ne mutlu kimselerdir!"},{"n":"28-34","t":"(Onlar), dikensiz sidir ağaçları ve meyveleri küme küme dizili muz ağaçları altında, yayılmış sürekli bir gölgede, çağlayan bir su başında, tükenmeyen ve yasaklanmayan çok çeşitli meyveler içinde ve yüksek döşekler üzerindedirler."},{"n":35,"t":"Biz onları (hurileri) yepyeni bir yaratılışta yarattık."},{"n":"36-38","t":"Onları ahiret mutluluğuna erenler için, hep bir yaşta eşlerini çok seven gösterişli bakireler yaptık."},{"n":"39-40","t":"Bunların birçoğu öncekilerden, birçoğu da sonrakilerdendir."},{"n":41,"t":"Kötülüğe batanlar ise ne mutsuz kimselerdir!"},{"n":"42-44","t":"Onlar, iliklere işleyen bir ateş ve bir kaynar su içindedirler. Ne serin ve ne de yararlı olan zifirî bir gölge içinde!."},{"n":45,"t":"Çünkü onlar, bundan önce (dünyada varlık içinde) sefahata dalmış ve azgın kimselerdi."},{"n":46,"t":"Büyük günah üzerinde ısrar ediyorlardı."},{"n":47,"t":"Diyorlardı ki: \"Biz öldükten, toprak ve kemik yığını hâline geldikten sonra mı, biz mi bir daha diriltilecekmişiz?\""},{"n":48,"t":"\"Evvelki atalarımız da mı?\""},{"n":"49-50","t":"De ki: \"Şüphesiz öncekiler ve sonrakiler, mutlaka belli bir günün belli bir vaktinde toplanacaklardır.\""},{"n":"51-52","t":"Sonra siz ey haktan sapan yalanlayıcılar! Mutlaka (cehennemde) bir ağaçtan, zakkumdan yiyeceksiniz."},{"n":53,"t":"Karınlarınızı ondan dolduracaksınız."},{"n":54,"t":"Üstüne de o kaynar sudan içeceksiniz."},{"n":55,"t":"Kanmak bilmez susamış develerin suya saldırışı gibi içeceksiniz."},{"n":56,"t":"İşte bu hesap ve ceza gününde onlara ziyafetleridir."},{"n":57,"t":"Sizi biz yarattık. Hâlâ tasdik etmeyecek misiniz?"},{"n":58,"t":"Attığınız o meniye ne dersiniz?!"},{"n":59,"t":"Onu siz mi yaratıyorsunuz, yoksa yaratan biz miyiz?"},{"n":"60-61","t":"Sizin yerinize benzerlerinizi getirmek ve sizi bilemeyeceğiniz bir şekilde yeniden yaratmak üzere aranızda ölümü biz takdir ettik. (Bu konuda) bizim önümüze geçilmez."},{"n":62,"t":"Andolsun, birinci yaratılışı(nızı) biliyorsunuz. O hâlde düşünseniz ya!"},{"n":63,"t":"Ektiğiniz tohuma ne dersiniz?!"},{"n":64,"t":"Onu siz mi bitiriyorsunuz, yoksa bitiren biz miyiz?"},{"n":65,"t":"Dileseydik, onu kuru bir çöp yapardık da şaşkınlık içinde şöyle geveleyip dururdunuz:"},{"n":66,"t":"\"Muhakkak biz çok ziyandayız!\""},{"n":67,"t":"\"Daha doğrusu büsbütün mahrumuz!\""},{"n":68,"t":"İçtiğiniz suya ne dersiniz?!"},{"n":69,"t":"Siz mi onu buluttan indirdiniz, yoksa indiren biz miyiz?"},{"n":70,"t":"Dileseydik onu acı bir su yapardık. O hâlde şükretseydiniz ya!."},{"n":71,"t":"Tutuşturduğunuz ateşe ne dersiniz?!"},{"n":72,"t":"Onun ağacını siz mi yarattınız, yoksa yaratan biz miyiz?"},{"n":73,"t":"Biz onu bir ibret ve ıssız yerlerde yaşayanlara bir yarar kaynağı kıldık."},{"n":74,"t":"O hâlde, O yüce Rabbinin adını tesbih et (yücelt)."},{"n":"75-76","t":"Yıldızların yerlerine yemin ederim ki, -eğer bilirseniz, gerçekten bu, büyük bir yemindir-"},{"n":77,"t":"O, elbette değerli bir Kur’an’dır."},{"n":78,"t":"Korunmuş bir kitaptadır."},{"n":79,"t":"Ona, ancak tertemiz olanlar dokunabilir."},{"n":80,"t":"Âlemlerin Rabb’inden indirilmedir."},{"n":"81-82","t":"Şimdi siz, bu sözü mü küçümsüyorsunuz ve Allah’ın verdiği rızka O’nu yalanlayarak mı şükrediyorsunuz?"},{"n":83,"t":"Can boğaza geldiğinde, onu geri döndürsenize!"},{"n":84,"t":"Oysa siz o zaman bakıp durursunuz."},{"n":85,"t":"Biz ise ona sizden daha yakınız. Fakat siz göremezsiniz."},{"n":"86-87","t":"Eğer hesaba çekilmeyecekseniz ve doğru söyleyenler iseniz, onu geri döndürsenize!"},{"n":"88-89","t":"Fakat (ölen kişi) Allah’a yakın kılınmışlardan ise, ona rahatlık, güzel rızık ve Naîm cenneti vardır."},{"n":"90-91","t":"Eğer Ahiret mutluluğuna ermiş kişilerden ise, kendisine, \"Selâm sana Ahiret mutluluğuna ermişlerden!\" denir."},{"n":"92-93","t":"Ama haktan sapan yalancılardan ise, işte ona da kaynar sudan bir ziyafet vardır."},{"n":94,"t":"Bir de cehenneme atılma vardır."},{"n":95,"t":"Şüphesiz bu, kesin gerçektir."},{"n":96,"t":"Öyleyse yüce Rabbinin adını tesbih et."}],[{"n":1,"t":"Göklerdeki ve yerdeki her şey Allah’ı tespih etmektedir. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":2,"t":"Göklerin ve yerin hükümranlığı yalnızca O’nundur. Diriltir, öldürür. O, her şeye hakkıyla gücü yetendir."},{"n":3,"t":"O, ilk ve sondur. Zâhir ve Bâtın’dır. O, her şeyi hakkıyla bilendir."},{"n":4,"t":"O, gökleri ve yeri altı günde (altı evrede) yaratan, sonra Arş’a kurulandır. Yere gireni, ondan çıkanı, gökten ineni, oraya yükseleni bilir. Nerede olsanız, O sizinle beraberdir. Allah, bütün yaptıklarınızı hakkıyla görendir."},{"n":5,"t":"Göklerin ve yerin hükümranlığı O’nundur. Bütün işler ancak O’na döndürülür."},{"n":6,"t":"Geceyi gündüze sokar, gündüzü de geceye sokar. O, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir."},{"n":7,"t":"Allah’a ve Resûlüne iman edin ve sizi üzerinde tasarrufa yetkili kıldığı maldan, (Allah yolunda) harcayın. İçinizden iman edip de (Allah yolunda) harcayanlar var ya; onlar için büyük bir mükâfat vardır."},{"n":8,"t":"Peygamber, sizi, Rabbinize iman etmeniz için davet edip dururken size ne oluyor da Allah’a iman etmiyorsunuz? Hâlbuki (Allah ezelde) sizden sağlam bir söz de almıştı. Eğer inanacak kimselerseniz (bu çağrıya uyun)."},{"n":9,"t":"O, sizi karanlıklardan aydınlığa çıkarmak için kulu Muhammed’e apaçık âyetler indirendir. Şüphesiz Allah, size karşı çok esirgeyici, çok merhametlidir."},{"n":10,"t":"Size ne oluyor da, Allah yolunda harcama yapmıyorsunuz? Hâlbuki göklerin ve yerin mirası Allah’ındır. İçinizden, fetihten (Mekke fethinden) önce harcayanlar ve savaşanlar, (diğerleri ile) bir değildir. Onların derecesi, sonradan harcayan ve savaşanlardan daha yüksektir. Bununla beraber Allah, hepsine de en güzel olanı (cenneti) va’detmiştir. Allah, bütün yaptıklarınızdan hakkıyla haberdardır."},{"n":11,"t":"Kim Allah’a güzel bir borç verecek ki, Allah da onu kendisine kat kat ödesin. Ona çok değerli bir mükâfat da vardır."},{"n":12,"t":"Mü’min erkeklerle mü’min kadınların nurlarının, önlerinde ve sağlarında koştuğunu göreceğin gün kendilerine şöyle denir: \"Bugün size müjdelenen şey içlerinden ırmaklar akan, ebedî olarak kalacağınız cennetlerdir.\" İşte bu büyük başarıdır."},{"n":13,"t":"Münafık erkeklerle münafık kadınların, iman edenlere, \"Bize bakın ki sizin ışığınızdan biz de aydınlanalım\" diyecekleri gün kendilerine, \"Arkanıza (dünyaya) dönün de bir ışık arayın\" denilecektir. Derken aralarına kapısı olan bir sur çekilir. Bunun iç tarafında rahmet, onlar (münafıklar) tarafındaki dış cihetinde ise azap vardır."},{"n":14,"t":"(Münafıklar) mü’minlere şöyle seslenirler: \"Biz de (dünyada) sizinle beraber değil miydik?\" (Mü’minler de) derler ki: \"Evet, fakat siz kendinizi yaktınız. Başımıza musibetler gelmesini gözlediniz, şüphe ettiniz. Allah’ın emri gelinceye kadar kuruntular sizi aldattı. O çok aldatıcı (şeytan) Allah hakkında da sizi aldattı.\""},{"n":15,"t":"Bugün artık ne sizden, ne de inkâr edenlerden bir fidye alınır. Barınağınız ateştir. Size yaraşan odur. Orası gidilecek ne kötü yerdir!"},{"n":16,"t":"İman edenlerin Allah’ı zikretmekten ve inen haktan dolayı kalplerinin saygı ile ürpermesinin zamanı gelmedi mi? Daha önce kendilerine kitap verilip de, üzerinden uzun zaman geçen, böylece kalpleri katılaşanlar gibi olmasınlar. Onlardan birçoğu fasık kimselerdir."},{"n":17,"t":"Bilin ki Allah, yeryüzünü ölümünden sonra diriltmektedir. Düşünesiniz diye gerçekten, size âyetleri açıkladık."},{"n":18,"t":"Şüphesiz ki sadaka veren erkeklerle sadaka veren kadınlar ve Allah’a güzel bir borç verenler var ya, (verdikleri) onlara kat kat ödenir. Ayrıca onlara çok değerli bir mükâfat da vardır."},{"n":19,"t":"Allah’a ve Peygamberlerine iman edenler var ya, işte onlar sıddîklar (sözü özü doğru kimseler) ve Allah katında şahitlerdir. Onların mükâfatları ve nurları vardır. İnkâr edip âyetlerimizi yalanlayanlara gelince; işte onlar cehennemliklerdir."},{"n":20,"t":"Bilin ki, dünya hayatı ancak bir oyun, bir eğlence, bir süs, aranızda karşılıklı bir övünme, çok mal ve evlat sahibi olma yarışından ibarettir. (Nihayet hepsi yok olur gider). Tıpkı şöyle: Bir yağmur ki, bitirdiği bitki çiftçilerin hoşuna gider. Sonra kurumaya yüz tutar da sen onu sararmış olarak görürsün. Sonra da çer çöp olur. Ahirette ise (dünyadaki amele göre ya) çetin bir azap ve(ya) Allah’ın mağfiret ve rızası vardır. Dünya hayatı, aldanış metaından başka bir şey değildir."},{"n":21,"t":"Rabbinizden bir bağışlanmaya ve eni, gökle yerin genişliği kadar olan, Allah’a ve Resûlüne inananlar için hazırlanan cennete yarışırcasına koşun. İşte bu, Allah’ın lütfudur. Onu dilediğine verir. Allah, büyük lütuf sahibidir."},{"n":22,"t":"Yeryüzünde ve kendi nefislerinizde uğradığınız hiçbir musibet yoktur ki, biz onu yaratmadan önce, bir kitapta (Levh-i Mahfuz’da) yazılmış olmasın. Şüphesiz bu, Allah’a göre kolaydır."},{"n":23,"t":"Elinizden çıkana üzülmeyesiniz ve Allah’ın size verdiği nimetlerle şımarmayasınız diye (böyle yaptık.) Çünkü Allah, kendini beğenip övünen hiçbir kimseyi sevmez."},{"n":24,"t":"Onlar cimrilik edip insanlara da cimriliği emreden kimselerdir. Kim yüz çevirirse bilsin ki şüphesiz Allah ganîdir, zengindir, övülmeye lâyıktır."},{"n":25,"t":"Andolsun, biz elçilerimizi açık mucizelerle gönderdik ve beraberlerinde kitabı ve mizanı (ölçüyü) indirdik ki, insanlar adaleti yerine getirsinler. Kendisinde müthiş bir güç ve insanlar için birçok faydalar bulunan demiri yarattık (ki insanlar ondan yararlansınlar). Allah da kendisine ve Resûllerine gayba inanarak yardım edecekleri bilsin. Şüphesiz Allah kuvvetlidir, mutlak güç sahibidir."},{"n":26,"t":"Andolsun, biz Nûh’u ve İbrahim’i peygamber olarak gönderdik. Peygamberliği ve kitabı onların soylarına da verdik. Onlardan kimi doğru yola ermiştir, ama içlerinden birçoğu da fasık kimselerdir."},{"n":27,"t":"Sonra bunların peşinden ard arda peygamberlerimizi gönderdik. Onların arkasından da Meryem oğlu İsa’yı gönderdik, ona İncil’i verdik ve kendisine uyanların kalplerine şefkat ve merhamet duygusu koyduk. (Kendiliklerinden) icat ettikleri ruhbanlığa gelince; biz onu onlara farz kılmamıştık. Allah’ın rızasını kazanmak için onu kendileri icat etmişlerdi. Fakat ona da gereği gibi uymadılar. Biz de içlerinden iman edenlere mükâfatlarını verdik. Fakat onlardan birçoğu da fasık kimselerdir."},{"n":28,"t":"Ey iman edenler! Allah’a karşı gelmekten sakının ve peygamberine iman edin ki, size rahmetinden iki kat pay versin, size kendisiyle yürüyeceğiniz bir nur versin ve sizi bağışlasın. Allah çok bağışlayıcıdır, çok merhamet edicidir."},{"n":29,"t":"Bunları açıkladık ki, kitap ehli, Allah’ın lütfundan hiçbir şeyi kendilerine has kılmaya güçlerinin yetmeyeceğini ve lütfun, Allah’ın elinde olduğunu, onu dilediği kimseye vereceğini bilsinler. Allah, büyük lütuf sahibidir."}],[{"n":1,"t":"Allah, kocası hakkında seninle tartışan ve Allah’a şikâyette bulunan kadının sözünü işitmiştir. Allah, sizin sürdürdüğünüz konuşmayı (zaten) işitmekteydi. Şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir."},{"n":2,"t":"İçinizden kadınlarına zıhar yapanlar bilsinler ki, o kadınlar onların anaları değildir. Onların anaları ancak, kendilerini doğuran kadınlardır. Şüphesiz onlar (zıhar yaparlarken) hoş karşılanmayan ve yalan bir söz söylüyorlar. Şüphesiz Allah çok affedicidir, çok bağışlayıcıdır."},{"n":3,"t":"Kadınlarından zıhar yaparak ayrılıp sonra da söylediklerinden dönecek olanlar, eşleriyle birbirlerine dokunmadan önce, bir köle azat etmelidirler. İşte bu hüküm ile size öğüt veriliyor. Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":4,"t":"Kim (köle azat etme imkânı) bulamazsa, eşine dokunmadan önce ard arda iki ay oruç tutmalıdır. Kimin de buna gücü yetmezse altmış fakiri doyurmalıdır. Bunlar, Allah’a ve Resûlüne hakkıyla iman edesiniz, diyedir. İşte bunlar Allah’ın sınırlarıdır. Kâfirler için elem dolu bir azap vardır."},{"n":5,"t":"Allah’a ve Resûlüne düşmanlık edenler, kendilerinden öncekilerin alçaltıldığı gibi alçaltılacaklardır. Oysa biz apaçık âyetler indirdik. Kâfirler için alçaltıcı bir azap vardır."},{"n":6,"t":"Allah’ın onları hep birden diriltip yaptıklarını kendilerine haber vereceği günü hatırla. Allah onları sayıp zaptetmiş, onlarsa bunları unutmuşlardır. Allah, her şeye şahittir."},{"n":7,"t":"Göklerdeki ve yerdeki her şeyi Allah’ın bildiğini görmüyor musun? Üç kişi gizlice konuşmaz ki, dördüncüleri O olmasın. Beş kişi gizlice konuşmaz ki altıncıları O olmasın. Bundan daha az, yahut daha çok da olsalar, nerede olurlarsa olsunlar, O mutlaka onlarla beraberdir. Sonra onlara yaptıklarını Kıyamet günü haber verecektir. Allah, her şeyi hakkıyla bilir."},{"n":8,"t":"Gizlice konuşmaktan menedilip de, menedildikleri şeyi işleyen ve günah, düşmanlık ve peygambere isyanı konuşanları görmedin mi? Sana geldiklerinde Allah’ın seni selâmlamadığı selâmla selâmlıyorlar. İçlerinden de, \"Söylediklerimizden dolayı Allah bize azap etse ya!\" diyorlar. Cehennem onlara yeter! Oraya girecekler. Ne kötü varış yeridir orası!"},{"n":9,"t":"Ey iman edenler! Siz baş başa gizlice konuştuğunuz zaman, günah, düşmanlık ve peygambere isyanı konuşmayın. İyilik ve takvayı konuşun ve huzuruna toplanacağınız Allah’a karşı gelmekten sakının."},{"n":10,"t":"O kötü fısıltılar iman edenleri üzmek için ancak şeytandan kaynaklanmaktadır. Oysa şeytan, Allah’ın izni olmadıkça, mü’minlere hiçbir zarar verebilecek değildir. Öyle ise mü’minler ancak Allah’a tevekkül etsinler."},{"n":11,"t":"Ey iman edenler! Size, \"Meclislerde yer açın\" denildiği zaman açın ki, Allah da size genişlik versin. Size, \"Kalkın\", denildiği zaman da kalkın ki, Allah içinizden inananların ve kendilerine ilim verilenlerin derecelerini yükseltsin. Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":12,"t":"Ey iman edenler! Peygamber ile baş başa konuşacağınız zaman, baş başa konuşmanızdan önce bir sadaka verin. Bu, sizin için daha hayırlı ve daha temizdir. Şâyet (sadaka verecek bir şey) bulamazsanız, bilin ki Allah çok bağışlayandır, çok merhamet edendir."},{"n":13,"t":"Baş başa konuşmanızdan önce sadakalar vermekten çekindiniz mi? Bunu yapmadığınıza ve Allah da, sizi affettiğine göre artık namazı kılın, zekâtı verin, Allah’a ve Resûlüne itaat edin. Allah, bütün yaptıklarınızdan hakkıyla haberdardır."},{"n":14,"t":"Allah’ın kendilerine gazap ettiği bir topluluğu dost edinenleri görmez misin? Onlar ne sizdendirler, ne de onlardan. Onlar bile bile yalan yere yemin ederler."},{"n":15,"t":"Allah, onlara çetin bir azap hazırlamıştır. Gerçekten onların yaptıkları şey ne kötüdür!"},{"n":16,"t":"Onlar yeminlerini kalkan yapıp (insanları) Allah’ın dininden alıkoydular. Bunun için onlara alçaltıcı bir azap vardır."},{"n":17,"t":"Onların malları da, evlatları da Allah’a karşı kendilerine bir yarar sağlamayacaktır. Onlar, cehennemliklerdir. Onlar orada ebedî kalacaklardır."},{"n":18,"t":"Allah’ın onları hep birden dirilteceği, onların da (kendilerini kurtaracak) bir iş üzerinde olduklarını sanarak size yemin ettikleri gibi Allah’a da yemin edecekleri günü düşün! İyi bilin ki, onlar yalancıların ta kendileridir."},{"n":19,"t":"Şeytan onları hâkimiyeti altına alıp kendilerine Allah’ı anmayı unutturmuştur. İşte onlar şeytanın tarafında olanlardır. İyi bilin ki, şeytanın tarafında olanlar ziyana uğrayanların ta kendileridir."},{"n":20,"t":"Allah’a ve peygamberine düşman olanlar var ya, işte onlar en aşağı kimselerin arasındadırlar."},{"n":21,"t":"Allah, \"Şüphesiz ben ve peygamberlerim galip geleceğiz\" diye yazmıştır. Şüphe yok ki, Allah çok kuvvetlidir, mutlak güç sahibidir."},{"n":22,"t":"Allah’a ve ahiret gününe iman eden hiçbir topluluğun, babaları, oğulları, kardeşleri yahut kendi soy sopları olsalar bile, Allah’a ve peygamberine düşman olan kimselere sevgi beslediğini göremezsin. İşte Allah onların kalplerine imanı yazmış ve onları kendi katından bir ruh ile desteklemiştir. Onları, içlerinden ırmaklar akan ve içlerinde ebedî kalacakları cennetlere sokacaktır. Allah onlardan razı olmuş, onlar da Allah’tan razı olmuşlardır. İşte onlar, Allah’ın tarafında olanlardır. İyi bilin ki, Allah’ın tarafında olanlar kurtuluşa erenlerin ta kendileridir."}],[{"n":1,"t":"Göklerdeki ve yerdeki her şey Allah’ı tespih etmektedir. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":2,"t":"O, kitap ehlinden inkâr edenleri ilk toplu sürgünde yurtlarından çıkarandır. Siz onların çıkacaklarını sanmamıştınız. Onlar da kalelerinin, kendilerini Allah’tan koruyacağını sanmışlardı. Ama Allah’ın emri onlara ummadıkları yerden geldi. O, yüreklerine korku düşürdü. Öyle ki, evlerini hem kendi elleriyle, hem de mü’minlerin elleriyle yıkıyorlardı. Ey basiret sahipleri, ibret alın."},{"n":3,"t":"Eğer Allah, onlar hakkında sürülmeye hükmetmemiş olsaydı, muhakkak kendilerine dünyada azap edecekti. Ahirette ise, onlar için cehennem azabı vardır."},{"n":4,"t":"Bu, onların Allah’a ve Resûlüne karşı gelmeleri sebebiyledir. Kim Allah’a karşı gelirse bilsin ki, Allah’ın azabı şiddetlidir."},{"n":5,"t":"(Savaş gereği,) hurma ağaçlarından her neyi kestiniz, yahut (kesmeyip) kökleri üzerinde dikili bıraktınızsa hep Allah’ın izniyledir. Bu da fasıkları rezil etmesi içindir."},{"n":6,"t":"Onların mallarından Allah’ın, savaşılmaksızın peygamberine kazandırdığı mallar için siz, at ya da deve koşturmuş değilsiniz. Fakat Allah, peygamberlerini, dilediği kimselerin üzerine salıp onlara üstün kılar. Allah’ın her şeye hakkıyla gücü yeter."},{"n":7,"t":"Allah’ın, (fethedilen) memleketlerin ahalisinden savaşılmaksızın peygamberine kazandırdığı mallar; Allah’a, peygambere, onun yakınlarına, yetimlere, yoksullara ve yolda kalmışlara aittir. O mallar, içinizden yalnız zenginler arasında dolaşan bir servet (ve güç) hâline gelmesin diye (Allah böyle hükmetmiştir). Peygamber size ne verdiyse onu alın, neyi de size yasak ettiyse ondan vazgeçin. Allah’a karşı gelmekten sakının. Şüphesiz, Allah’ın azabı çetindir."},{"n":8,"t":"Bu mallar özellikle, Allah’tan bir lütuf ve hoşnudluk ararken ve Allah’ın dinine ve peygamberine yardım ederken yurtlarından ve mallarından uzaklaştırılan fakir muhacirlerindir. İşte onlar doğru kimselerin ta kendileridir."},{"n":9,"t":"Onlardan (muhacirlerden) önce o yurda (Medine’ye) yerleşmiş ve imanı da gönüllerine yerleştirmiş olanlar, hicret edenleri severler. Onlara verilenlerden dolayı içlerinde bir rahatsızlık duymazlar. Kendileri son derece ihtiyaç içinde bulunsalar bile onları kendilerine tercih ederler. Kim nefsinin cimriliğinden, hırsından korunursa, işte onlar kurtuluşa erenlerin ta kendileridir."},{"n":10,"t":"Onlardan sonra gelenler ise şöyle derler: \"Ey Rabbimiz! Bizi ve bizden önce iman etmiş olan kardeşlerimizi bağışla. Kalplerimizde, iman edenlere karşı hiçbir kin tutturma! Ey Rabbimiz! Şüphesiz sen çok esirgeyicisin, çok merhametlisin.\""},{"n":11,"t":"Kitap ehlinden o inkâr eden kardeşlerine, \"Yemin ederiz ki, siz (Medine’den) çıkarılırsanız, muhakkak biz de sizinle beraber çıkarız. Sizin hakkınızda asla kimseye boyun eğmeyiz. Eğer size karşı savaşılırsa, size mutlaka yardım ederiz\" diyerek münafıklık yapanlara bakmaz mısın? Hâlbuki Allah onların kesinlikle yalancı olduklarına şahitlik eder."},{"n":12,"t":"Andolsun, eğer (kardeşleri Medine’den) çıkarılırsa, onlarla beraber çıkmazlar. Kendilerine karşı savaşılırsa, onlara yardım etmezler. Yardım edecek olsalar bile andolsun mutlaka arkalarını dönüp kaçarlar, sonra kendilerine de yardım edilmez."},{"n":13,"t":"Onların kalplerinde size karşı duydukları korku, Allah’a karşı duydukları korkudan daha baskındır. Bu, onların anlamaz bir toplum olmaları sebebiyledir."},{"n":14,"t":"Onlar müstahkem kaleler içinde veya duvarlar arkasında olmadan sizinle toplu hâlde savaşmazlar. Kendi aralarındaki çekişmeleri şiddetlidir. Sen onları toplu sanırsın. Hâlbuki kalpleri darmadağınıktır. Bu, onların akılları ermez bir topluluk olmalarındandır."},{"n":15,"t":"Onların durumu, kendilerinden az öncekilerin (Mekkeli müşriklerin) durumu gibidir. Onlar (Bedir’de) yaptıklarının cezasını tatmışlardır. Onlara (Ahirette de) elem dolu bir azap vardır."},{"n":16,"t":"Münafıkların durumu ise tıpkı şeytanın durumu gibidir. Çünkü şeytan insana, \"İnkâr et\" der; insan inkâr edince de, \"Şüphesiz ben senden uzağım. Çünkü ben âlemlerin Rabbi olan Allah’tan korkarım\" der."},{"n":17,"t":"Nihayet ikisinin de (azdıranın da azanın da) akıbeti, ebediyen ateşte kalmaları olmuştur. İşte zalimlerin cezası budur."},{"n":18,"t":"Ey iman edenler! Allah’a karşı gelmekten sakının ve herkes, yarın için önceden ne göndermiş olduğuna baksın. Allah’a karşı gelmekten sakının. Şüphesiz Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":19,"t":"Allah’ı unutan ve bu yüzden Allah’ın da kendilerine kendilerini unutturduğu kimseler gibi olmayın. İşte onlar fasık kimselerin ta kendileridir."},{"n":20,"t":"Cehennemliklerle cennetlikler bir olmaz. Cennetlikler kurtuluşa erenlerin ta kendileridir."},{"n":21,"t":"Eğer biz, bu Kur’an’ı bir dağa indirseydik, elbette sen onu Allah korkusundan başını eğerek parça parça olmuş görürdün. İşte misaller! Biz onları insanlara düşünsünler diye veriyoruz."},{"n":22,"t":"O, kendisinden başka hiçbir ilâh olmayan Allah’tır. Gaybı da, görünen âlemi de bilendir. O, Rahmân’dır, Rahîm’dir."},{"n":23,"t":"O, kendisinden başka hiçbir ilâh bulunmayan Allah’tır. O, mülkün gerçek sahibi, kutsal (her türlü eksiklikten uzak), barış ve esenliğin kaynağı, güvenlik veren, gözetip koruyan, mutlak güç sahibi, düzeltip ıslah eden ve dilediğini yaptıran ve büyüklükte eşsiz olan Allah’tır. Allah, onların ortak koştuklarından uzaktır."},{"n":24,"t":"O, yaratan, yoktan var eden, şekil veren Allah’tır. Güzel isimler O’nundur. Göklerdeki ve yerdeki her şey O’nu tesbih eder. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."}],[{"n":1,"t":"Ey İman edenler! Benim de düşmanım, sizin de düşmanınız olanları dost edinmeyin. Siz onlara sevgi gösteriyorsunuz. Hâlbuki onlar size gelen hakkı inkâr ettiler. Rabbiniz olan Allah’a inandınız diye Resûlü ve sizi yurdunuzdan çıkarıyorlar. Eğer rızamı kazanmak üzere benim yolumda cihad etmek için çıktıysanız (böyle yapmayın). Onlara gizlice sevgi besliyorsunuz. Oysa ben sizin gizlediğinizi de, açığa vurduğunuzu da bilirim. Sizden kim bunu yaparsa, mutlaka doğru yoldan sapmıştır."},{"n":2,"t":"Şâyet onlar sizi ele geçirirlerse, size düşman olurlar, size ellerini ve dillerini kötülükle uzatırlar ve inkâr etmenizi arzu ederler."},{"n":3,"t":"Yakınlarınız ve çocuklarınız size asla fayda vermeyecektir. Kıyamet günü Allah aranızı ayıracaktır. Allah, yaptıklarınızı hakkıyla görendir."},{"n":4,"t":"İbrahim’de ve onunla birlikte bulunanlarda sizin için güzel bir örnek vardır. Hani onlar kavimlerine, \"Biz sizden ve Allah’ı bırakıp taptıklarınızdan uzağız. Sizi tanımıyoruz. Siz bir tek Allah’a inanıncaya kadar, sizinle bizim aramızda sürekli bir düşmanlık ve nefret belirmiştir\" demişlerdi. Yalnız İbrahim’in, babasına, \"Senin için mutlaka bağışlama dileyeceğim. Fakat Allah’tan sana gelecek herhangi bir şeyi önlemeye gücüm yetmez\" sözü başka. Onlar şöyle dediler: \"Ey Rabbimiz! Ancak sana dayandık, içtenlikle yalnız sana yöneldik. Dönüş de ancak sanadır.\""},{"n":5,"t":"\"Ey Rabbimiz! Bizi, inkâr edenlerin zulmüne uğratma. Bizi bağışla. Ey Rabbimiz! Şüphesiz sen mutlak güç sahibisin, hüküm ve hikmet sahibisin.\""},{"n":6,"t":"Andolsun, onlarda (İbrahim ve beraberindekilerde) sizin için, Allah’ı ve ahiret gününü arzu edenler için güzel bir örnek vardır. Kim yüz çevirirse bilsin ki, Allah her bakımdan sınırsız zengindir, övülmeye lâyıktır."},{"n":7,"t":"Ola ki Allah sizinle, içlerinden düşman olduğunuz kimseler arasına bir sevgi (ve yakınlık) koyar. Allah, hakkıyla gücü yetendir. Allah çok bağışlayandır, çok merhametlidir."},{"n":8,"t":"Allah, sizi, din konusunda sizinle savaşmamış, sizi yurtlarınızdan da çıkarmamış kimselere iyilik etmekten, onlara âdil davranmaktan men etmez. Şüphesiz Allah, âdil davrananları sever."},{"n":9,"t":"Allah, sizi ancak, sizinle din konusunda savaşan, sizi yurtlarınızdan çıkaran ve çıkarılmanız için destek verenleri dost edinmekten men eder. Kim onları dost edinirse, işte onlar zalimlerin ta kendileridir."},{"n":10,"t":"Ey iman edenler! Mü’min kadınlar muhacir olarak size geldiklerinde, onları imtihan edin. Allah, onların imanlarını daha iyi bilir. Eğer siz onların inanmış kadınlar olduklarını anlarsanız, onları kâfirlere geri göndermeyin. Çünkü müslüman hanımlar kâfirlere helâl değillerdir. Kâfirler de müslüman hanımlara helâl olmazlar. Mehir olarak harcadıklarını onlara (kocalarına geri) verin. Mehirlerini verdiğiniz takdirde, bu kadınlarla evlenmenizde size bir günah yoktur. Müşrik karılarınızın nikâhlarına tutunmayın. (Zira bu nikâhlar ortadan kalkmıştır.) Onlara harcadığınız mehri, (evlendikleri kâfir kocalarından) isteyin. Kâfirler de (İslâm’ı kabul eden ve sizinle evlenen eski hanımlarına) harcamış oldukları mehri (sizden) istesinler. Bu, Allah’ın hükmüdür. O, aranızda hüküm veriyor. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":11,"t":"Eğer eşlerinizden biri kâfirlere kaçar ve siz de onlarla çarpışıp ganimet alırsanız, eşleri gidenlere sarf ettikleri (mehir) kadarını verin ve inandığınız Allah’a karşı gelmekten sakının."},{"n":12,"t":"Ey Peygamber! Mü’min kadınlar, Allah’a hiçbir şeyi ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, elleriyle ayakları arasında bir iftira uydurup getirmemek, hiçbir iyi işte sana karşı gelmemek konusunda sana biat etmek üzere geldikleri zaman, biatlarını kabul et ve onlar için Allah’tan bağışlama dile. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir."},{"n":13,"t":"Ey iman edenler! Kendilerine Allah’ın gazap ettiği, kabirlerdeki kâfirlerin ümit kestikleri gibi tamamen ahiretten ümitlerini kesmiş bir toplumu dost edinmeyin."}],[{"n":1,"t":"Göklerdeki ve yerdeki her şey Allah’ı tespih eder. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":2,"t":"Ey iman edenler! Yapmayacağınız şeyleri niçin söylüyorsunuz?"},{"n":3,"t":"Yapmayacağınız şeyleri söylemeniz, Allah katında büyük gazap gerektiren bir iştir."},{"n":4,"t":"Hiç şüphe yok ki Allah, kendi yolunda, duvarları birbirine kenetlenmiş bir bina gibi saf bağlayarak çarpışanları sever."},{"n":5,"t":"Hani Mûsâ kavmine, \"Ey kavmim! Allah’ın size gönderdiği peygamberi olduğumu bilip durduğunuz hâlde, niçin bana eziyet ediyorsunuz?\" demişti. Onlar yoldan sapınca, Allah da kalplerini (doğru yoldan) saptırdı. Allah, fasıklar topluluğunu hidayete erdirmez."},{"n":6,"t":"Hani, Meryem oğlu İsa, \"Ey İsrailoğulları! Şüphesiz ben, Allah’ın size, benden önce gelen Tevrat’ı doğrulayıcı ve benden sonra gelecek, Ahmed adında bir peygamberi müjdeleyici (olarak gönderdiği) peygamberiyim\" demişti. Fakat (İsa) onlara apaçık mucizeleri getirince, \"Bu, apaçık bir sihirdir\" dediler."},{"n":7,"t":"Kim, İslâm’a davet olunduğu hâlde, Allah’a karşı yalan uydurandan daha zalimdir? Allah, zalimler topluluğunu hidayete erdirmez."},{"n":8,"t":"Onlar ağızlarıyla Allah’ın nurunu söndürmek istiyorlar. Hâlbuki kâfirler istemeseler de Allah nurunu tamamlayacaktır."},{"n":9,"t":"O, kendisine ortak koşanlar hoşlanmasa da, dinini bütün dinlere üstün kılmak için peygamberini hidayet ve hak din ile gönderendir."},{"n":10,"t":"Ey iman edenler! Sizi elem dolu bir azaptan kurtaracak bir ticaret göstereyim mi size?"},{"n":11,"t":"Allah’a ve peygamberine inanır, mallarınızla ve canlarınızla Allah yolunda cihat edersiniz. Eğer bilirseniz, bu sizin için çok hayırlıdır."},{"n":12,"t":"(Bunu yapınız ki) Allah, günahlarınızı bağışlasın, sizi içinden ırmaklar akan cennetlere ve Adn cennetlerindeki güzel meskenlere koysun. İşte bu büyük başarıdır."},{"n":13,"t":"Seveceğiniz başka bir kazanç daha var: Allah’tan bir yardım ve yakın bir fetih (Mekke’nin fethi). (Ey Muhammed!) Mü’minleri müjdele!"},{"n":14,"t":"Ey iman edenler! Allah’ın yardımcıları olun. Nasıl ki Meryem oğlu İsa da havarilere, \"Allah’a giden yolda benim yardımcılarım kimdir?\" demişti. Havariler de, \"Biz Allah’ın yardımcılarıyız\" demişlerdi. Bunun üzerine İsrailoğullarından bir kesim inanmış, bir kesim de inkâr etmişti. Nihayet biz inananları, düşmanlarına karşı destekledik. Böylece üstün geldiler."}],[{"n":1,"t":"Göklerdeki ve yerdeki her şey, mülkün sahibi, mukaddes, mutlak güç sahibi, hüküm ve hikmet sahibi olan Allah’ı tespih eder."},{"n":2,"t":"O, ümmîlere, içlerinden, kendilerine âyetlerini okuyan, onları temizleyen, onlara kitabı ve hikmeti öğreten bir peygamber gönderendir. Hâlbuki onlar, bundan önce apaçık bir sapıklık içinde idiler."},{"n":3,"t":"(Allah, o peygamberi) onlardan henüz kendilerine katılmayan başkalarına da göndermiştir. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir."},{"n":4,"t":"İşte bu, Allah’ın lütfudur. Onu dilediğine verir. Allah, büyük lütuf sahibidir."},{"n":5,"t":"Tevrat’la yükümlü tutulup da onunla amel etmeyenlerin durumu, ciltlerle kitap taşıyan eşeğin durumu gibidir. Allah’ın âyetlerini inkâr eden topluluğun hâli ne kötüdür! Allah, zalimler topluluğunu hidayete erdirmez."},{"n":6,"t":"De ki: \"Ey Yahudi akidesini benimseyenler! Bütün insanlar değil de, yalnız kendinizin Allah’ın dostları olduğunu iddia ediyorsanız, (bunda da) samimi iseniz haydi ölümü isteyin!\""},{"n":7,"t":"Ama onlar, daha evvel yaptıklarından dolayı asla ölümü istemezler. Allah, zalimleri hakkıyla bilir."},{"n":8,"t":"De ki: \"Sizin kendisinden kaçıp durduğunuz ölüm var ya, o mutlaka size ulaşacaktır. Sonra gaybı da, görünen âlemi de bilen Allah’a döndürüleceksiniz de, O size yapmakta olduklarınızı haber verecektir.\""},{"n":9,"t":"Ey iman edenler! Cuma günü namaz için çağrı yapıldığı zaman, hemen Allah’ın zikrine koşun ve alışverişi bırakın. Eğer bilirseniz bu, sizin için daha hayırlıdır."},{"n":10,"t":"Namaz kılınınca artık yeryüzüne dağılın ve Allah’ın lütfundan nasibinizi arayın. Allah’ı çok zikredin ki kurtuluşa eresiniz."},{"n":11,"t":"(Durum böyle iken) onlar bir ticaret veya bir oyun eğlence gördükleri zaman hemen dağılıp ona koştular ve seni ayakta bıraktılar. De ki: \"Allah’ın yanında bulunan, eğlence ve ticaretten daha hayırlıdır. Allah, rızık verenlerin en hayırlısıdır.\""}],[{"n":1,"t":"(Ey Muhammed!) Münafıklar sana geldiklerinde, \"Senin, elbette Allah’ın peygamberi olduğuna şahitlik ederiz\" derler. Allah senin, elbette kendisinin peygamberi olduğunu biliyor. (Fakat) Allah, o münafıkların hiç şüphesiz yalancılar olduklarına elbette şahitlik eder."},{"n":2,"t":"Yeminlerini kalkan yaptılar da insanları Allah’ın yolundan çevirdiler. Gerçekten onların yaptıkları şey ne kötüdür!"},{"n":3,"t":"Bu, onların önce iman edip sonra inkâr etmeleri, bu yüzden de kalplerine mühür vurulması sebebiyledir. Artık onlar anlamazlar."},{"n":4,"t":"Onları gördüğün zaman kalıpları hoşuna gider. Konuşurlarsa sözlerine kulak verirsin. Onlar sanki elbise giydirilmiş kereste gibidirler. Her kuvvetli sesi kendi aleyhlerine sanırlar. Onlar düşmandır, onlardan sakın! Allah onları kahretsin! Nasıl da (haktan) çevriliyorlar!"},{"n":5,"t":"O münafıklara, \"Gelin, Allah’ın Resûlü sizin için bağışlama dilesin\" denildiği zaman başlarını çevirirler ve sen onların büyüklük taslayarak uzaklaştıklarını görürsün."},{"n":6,"t":"Onlara bağışlama dilesen de, dilemesen de onlar için birdir. Allah, onları asla bağışlamayacaktır. Çünkü Allah, fasıklar topluluğunu doğru yola iletmez."},{"n":7,"t":"Onlar, \"Allah Resûlü’nün yanında bulunanlara (muhacirlere) bir şey vermeyin ki dağılıp gitsinler\" diyenlerdir. Hâlbuki göklerin ve yerin hazineleri Allah’ındır. Fakat münafıklar (bunu) anlamazlar."},{"n":8,"t":"Onlar, \"Andolsun, eğer Medine’ye dönersek, üstün olan, zayıf olanı oradan mutlaka çıkaracaktır\" diyorlardı. Hâlbuki asıl üstünlük, ancak Allah’ın, Peygamberinin ve mü’minlerindir. Fakat münafıklar (bunu) bilmezler."},{"n":9,"t":"Ey iman edenler! Mallarınız ve evlatlarınız sizi, Allah’ı zikretmekten alıkoymasın. Her kim bunu yaparsa, işte onlar ziyana uğrayanların ta kendileridir."},{"n":10,"t":"Herhangi birinize ölüm gelip de, \"Ey Rabbim! Beni yakın bir zamana kadar geciktirsen de sadaka verip iyilerden olsam!\" demeden önce, size rızık olarak verdiğimiz şeylerden Allah yolunda harcayın."},{"n":11,"t":"Allah, eceli geldiğinde hiçbir kimseyi asla ertelemez. Allah, bütün yaptıklarınızdan haberdardır."}],[{"n":1,"t":"Göklerdeki ve yerdeki her şey Allah’ı tespih eder. Mülk yalnızca O’nundur, hamd de O’na mahsustur. O, her şeye hakkıyla gücü yetendir."},{"n":2,"t":"O, sizi yaratandır. Böyle iken kiminiz kâfir, kiminiz mü’mindir. Allah, yaptıklarınızı hakkıyla görendir."},{"n":3,"t":"Gökleri ve yeri hak ve hikmete uygun olarak yarattı. Sizi şekillendirdi ve şekillerinizi de güzel yaptı. Dönüş yalnız O’nadır."},{"n":4,"t":"Göklerdeki ve yerdeki her şeyi bilir. Gizlediklerinizi de açığa vurduklarınızı da bilir. Allah, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir."},{"n":5,"t":"Daha önce inkâr edip de inkârlarının cezasını tadanların haberi size gelmedi mi? Onlar için elem dolu bir azap da vardır."},{"n":6,"t":"Bu, peygamberlerinin, onlara apaçık mucizeler getirmeleri ve onların da, \"(Bizim gibi) insanlar mı bizi doğru yola iletecekmiş?\" deyip de inkâr etmeleri ve yüz çevirmeleri sebebiyledir. Allah da hiçbir şeye muhtaç olmadığını göstermiştir. Allah, her bakımdan sınırsız zengindir, övgüye lâyıktır."},{"n":7,"t":"İnkâr edenler, kesinlikle, öldükten sonra diriltilmeyeceklerini iddia ettiler. De ki: \"Hiç de öyle değil, Rabbime and olsun, mutlaka diriltileceksiniz, sonra da yaptıklarınız size elbette haber verilecektir. Bu, Allah’a kolaydır.\""},{"n":8,"t":"Artık siz Allah’a, peygamberine ve indirdiğimiz nûra (Kur’an’a) iman edin. Allah, yaptıklarınızdan hakkıyla haberdardır."},{"n":9,"t":"Toplanma vakti için Allah’ın sizi toplayacağı günü düşün. O gün aldanışın ortaya çıkacağı gündür. Kim Allah’a inanır ve salih amel işlerse, Allah onun kötülüklerini örter ve onu içinden ırmaklar akan, ebedî kalacakları cennetlere sokar. İşte bu büyük başarıdır."},{"n":10,"t":"İnkâr eden ve âyetlerimizi yalanlayanlara gelince, işte onlar, içinde ebedî kalmak üzere cehennemliklerdir. Ne kötü varılacak yerdir orası!"},{"n":11,"t":"Allah’ın izni olmaksızın hiçbir musibet başa gelmez. Kim Allah’a inanırsa, Allah onun kalbini doğruya iletir. Allah, her şeyi hakkıyla bilendir."},{"n":12,"t":"Allah’a itaat edin, peygambere de itaat edin. Eğer yüz çevirirseniz, bilin ki elçimize düşen sadece apaçık bir tebliğdir."},{"n":13,"t":"Allah, kendisinden başka hiçbir ilâh bulunmayandır. Mü’minler yalnız Allah’a tevekkül etsinler."},{"n":14,"t":"Ey iman edenler! Eşlerinizden ve çocuklarınızdan size düşman olabilecekler vardır. Onlardan sakının. Ama affeder, hoş görüp vazgeçer ve bağışlarsanız şüphe yok ki Allah çok bağışlayandır, çok merhamet edendir."},{"n":15,"t":"Mallarınız ve çocuklarınız ancak birer imtihandır; Allah katında ise büyük bir mükâfat vardır."},{"n":16,"t":"O hâlde, gücünüz yettiği kadar Allah’a karşı gelmekten sakının. Dinleyin, itaat edin, kendi iyiliğiniz için harcayın. Kim nefsinin cimriliğinden korunursa, işte onlar kurtuluşa erenlerin ta kendileridir."},{"n":17,"t":"Eğer siz Allah’a güzel bir borç verirseniz, Allah onu size, kat kat öder ve sizi bağışlar. Allah, şükrün karşılığını verendir, halîmdir (hemen cezalandırmaz, mühlet verir)."},{"n":18,"t":"O, gaybı da görünen âlemi de bilendir, mutlak güç sahibidir, hüküm ve hikmet sahibidir."}],[{"n":1,"t":"Ey peygamber! Kadınları boşamak istediğinizde, onları iddetlerini dikkate alarak (temizlik hâlinde) boşayın ve iddeti sayın. Rabbiniz olan Allah’a karşı gelmekten sakının. Apaçık bir hayâsızlık yapmaları dışında onları (bekleme süresince) evlerinden çıkarmayın, kendileri de çıkmasınlar. Bunlar Allah’ın sınırlarıdır. Kim Allah’ın sınırlarını aşarsa, şüphesiz kendine zulmetmiş olur. Bilemezsin, olur ki Allah, sonra yeni bir durum ortaya çıkarır."},{"n":2,"t":"Boşanan kadınlar iddetlerinin sonuna varınca, onları güzelce tutun, yahut onlardan güzelce ayrılın. İçinizden iki âdil kimseyi şahit tutun. Şahitliği Allah için dosdoğru yapın. İşte bununla Allah’a ve ahiret gününe inanan kimselere öğüt verilmektedir. Kim Allah’a karşı gelmekten sakınırsa, Allah ona bir çıkış yolu açar."},{"n":3,"t":"Onu beklemediği yerden rızıklandırır. Kim Allah’a tevekkül ederse, O kendisine yeter. Şüphesiz Allah, emrini yerine getirendir. Allah, her şeye bir ölçü koymuştur."},{"n":4,"t":"Kadınlarınızdan âdetten kesilmiş olanlarla, henüz âdet görmeyenler hususunda tereddüt ederseniz, onların bekleme süresi üç aydır. Hamile olanların bekleme süresi ise, doğum yapmalarıyla sona erer. Kim Allah’a karşı gelmekten sakınırsa, Allah ona işinde bir kolaylık verir."},{"n":5,"t":"İşte bu, Allah’ın size indirdiği emridir. Kim Allah’a karşı gelmekten sakınırsa, Allah onun kötülüklerini örter ve onun mükâfatını büyütür."},{"n":6,"t":"Onları (iddetleri süresince) gücünüz nispetinde, oturduğunuz yerin bir bölümünde oturtun. Onları sıkıntıya sokmak için kendilerine zarar vermeye kalkışmayın. Eğer hamile iseler, doğum yapıncaya kadar nafakalarını verin. Sizin için (çocuğu) emzirirlerse (emzirme) ücretlerini de verin ve aranızda uygun bir şekilde anlaşın. Eğer anlaşamazsanız, çocuğu baba hesabına başka bir kadın emzirecektir."},{"n":7,"t":"Eli geniş olan, elinin genişliğine göre nafaka versin. Rızkı dar olan da, Allah’ın ona verdiğinden (o ölçüde) harcasın. Allah, bir kimseyi ancak kendine verdiği ile yükümlü kılar. Allah, bir güçlükten sonra bir kolaylık yaratacaktır."},{"n":8,"t":"Nice kentlerin halkı Rablerinin ve O’nun elçilerinin emrinden uzaklaşıp azdılar. Bu yüzden kendilerini çetin bir hesaba çektik ve görülmedik bir azaba çarptırdık."},{"n":9,"t":"Böylece yaptıklarının cezasını tattılar ve işlerinin sonu tam bir hüsran oldu."},{"n":10,"t":"Allah, ahirette onlara şiddetli bir azap hazırlamıştır. O hâlde, ey iman etmiş olan akıl sahipleri, Allah’a karşı gelmekten sakının! Allah, size bir zikir (Kur’an) indirdi."},{"n":11,"t":"İman edip salih amel işleyenleri, karanlıklardan aydınlığa çıkarmak için size Allah’ın apaçık âyetlerini okuyan bir peygamber gönderdi. Kim Allah’a inanır ve salih bir amel işlerse, Allah onu, içinden ırmaklar akan, içinde ebedî kalacakları cennetlere sokar. Allah, gerçekten ona güzel bir rızık vermiştir."},{"n":12,"t":"Allah, yedi göğü ve yerden bir o kadarını yaratandır. Allah’ın emri bunlar arasından inip durmaktadır ki, Allah’ın her şeye kadir olduğunu ve Allah’ın her şeyi ilmiyle kuşattığını bilesiniz."}],[{"n":1,"t":"Ey peygamber! Eşlerinin rızasını arayarak, Allah’ın sana helâl kıldığı şeyi niçin sen kendine haram ediyorsun? Allah çok bağışlayandır, çok merhamet edendir."},{"n":2,"t":"Allah (gerektiğinde) yeminlerinizi bozmayı (ve kefaret ödemeyi) size meşru kılmıştır. Allah, sizin yardımcınızdır. O, hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":3,"t":"Hani peygamber eşlerinden birine, gizli bir söz söylemişti. Fakat eşi o sözü (başkasına) haber verip Allah da bunu peygambere bildirince, peygamber bunun bir kısmını bildirmiş, bir kısmından da vazgeçmişti. Peygamber, bunu ona (sırrı açıklayan eşine) haber verince o, \"Bunu sana kim bildirdi?\" dedi. Peygamber, \"Bunu bana, hakkıyla bilen ve hakkıyla haberdar olan Allah haber verdi\" dedi."},{"n":4,"t":"(Ey peygamber’in eşleri!) Eğer siz ikiniz Allah’a tövbe ederseniz, ne iyi. Çünkü kalpleriniz kaydı. Eğer Peygamber’e karşı birbirinize arka çıkarsanız bilin ki Allah onun yardımcısıdır, Cebrail de, salih mü’minler de. Bunlardan sonra melekler de ona arka çıkarlar."},{"n":5,"t":"Eğer o sizi boşarsa, Rabbi ona, sizden daha hayırlı, müslüman, inanan, sebatla itaat eden, tövbe eden, ibadet eden, oruç tutan, dul ve bakire eşler verebilir."},{"n":6,"t":"Ey iman edenler! Kendinizi ve ailenizi, yakıtı insanlar ve taşlar olan ateşten koruyun. O ateşin başında gayet katı, çetin, Allah’ın kendilerine verdiği emirlere karşı gelmeyen ve kendilerine emredilen şeyi yapan melekler vardır."},{"n":7,"t":"Ey inkâr edenler! Bu gün özür dilemeyin! Siz ancak yapmakta olduklarınızın karşılığını görüyorsunuz."},{"n":8,"t":"Ey iman edenler! Allah’a içtenlikle tövbe edin. Umulur ki, Rabbiniz sizin kötülüklerinizi örter, peygamberi ve onunla birlikte iman edenleri utandırmayacağı günde Allah sizi, içlerinden ırmaklar akan cennetlere sokar. Onların nurları önlerinden ve sağlarından aydınlatır, gider. \"Ey Rabbimiz! Nûrumuzu bizim için tamamla, bizi bağışla; çünkü senin her şeye hakkıyla gücün yeter\" derler."},{"n":9,"t":"Ey Peygamber! Kâfirlere ve münafıklara karşı cihad et, onlara karşı sert davran. Onların varacağı yer cehennemdir. Ne kötü varılacak yerdir orası!"},{"n":10,"t":"Allah, inkâr edenlere, Nûh’un karısı ile Lût’un karısını örnek gösterdi. Bu ikisi, kullarımızdan iki salih kişinin nikâhları altında bulunuyorlardı. Derken onlara hainlik ettiler de kocaları, Allah’ın azabından hiçbir şeyi onlardan savamadı. Onlara, \"Haydi, ateşe girenlerle beraber siz de girin!\" denildi."},{"n":11,"t":"Allah, iman edenlere ise, Firavun’un karısını örnek gösterdi. Hani o, \"Rabbim! Bana katında, cennette bir ev yap. Beni Firavun’dan ve onun yaptığı işlerden koru ve beni zalimler topluluğundan kurtar!\" demişti."},{"n":12,"t":"Allah, bir de iffetini sapasağlam koruyan ve bizim de kendisine ruhumuzdan üflediğimiz, Rabbinin kelimelerini ve kitaplarını doğrulayan İmran kızı Meryem’i de (inananlara) örnek gösterdi. O itaat edenlerdendi."}],[{"n":1,"t":"Hükümranlık elinde olan Allah, yücedir. O, her şeye hakkıyla gücü yetendir."},{"n":2,"t":"O, hanginizin daha güzel amel yapacağını sınamak için ölümü ve hayatı yaratandır. O, mutlak güç sahibidir, çok bağışlayandır."},{"n":3,"t":"O, yedi göğü tabaka tabaka yaratandır. Rahmân’ın yaratışında hiçbir uyumsuzluk göremezsin. Bir kere daha bak! Hiçbir çatlak (ve düzensizlik) görüyor musun?"},{"n":4,"t":"Sonra tekrar tekrar bak; bakışların (aradığı çatlak ve düzensizliği bulamayıp) âciz ve bitkin hâlde sana dönecektir."},{"n":5,"t":"Andolsun biz, en yakın göğü kandillerle donattık. Onları şeytanlara atılan taşlar yaptık ve (ahirette de) onlara alevli ateş azabını hazırladık."},{"n":6,"t":"Rablerini inkâr edenler için cehennem azabı vardır. Ne kötü varılacak yerdir orası!"},{"n":7,"t":"Oraya atıldıklarında, onun kaynarken çıkardığı korkunç uğultuyu işitirler."},{"n":8,"t":"Neredeyse cehennem öfkeden çatlayacaktır! Oraya her bir topluluk atıldıkça oranın bekçileri onlara, \"Size bir uyarıcı gelmemiş miydi?\" diye sorarlar."},{"n":9,"t":"Onlar da şöyle derler: \"Evet, bize bir uyarıcı gelmişti. Fakat biz onu yalanlamış ve ‘Allah hiçbir şey indirmemiştir. Siz ancak büyük bir sapıklık içindesiniz’ demiştik.\""},{"n":10,"t":"Yine şöyle derler: \"Eğer kulak vermiş veya aklımızı kullanmış olsaydık, şu alevli ateştekilerden olmazdık.\""},{"n":11,"t":"İşte böylece günahlarını itiraf ederler. Artık alevli ateştekiler Allah’ın rahmetinden uzak olsun!"},{"n":12,"t":"Görmedikleri hâlde Rablerinden korkanlar için bir bağışlanma ve büyük bir mükâfat vardır."},{"n":13,"t":"Sözünüzü gizleyin, yahut onu açığa vurun; (fark etmez). Şüphesiz Allah, sinelerin özünü (kalplerde olanı) hakkıyla bilir."},{"n":14,"t":"Yaratan bilmez mi? O, en gizli şeyleri bilir, (her şeyden) hakkıyla haberdardır."},{"n":15,"t":"O, yeryüzünü sizin ayaklarınızın altına serendir. Haydi onun üzerinde yürüyün ve Allah’ın rızkından yiyin. Dönüş ancak O’nadır."},{"n":16,"t":"Göktekinin sizi yere geçirivermeyeceğinden emin mi oldunuz? (O zaman) bir de bakarsınız yeryüzü şiddetle çalkalanıyor."},{"n":17,"t":"Yahut göktekinin, üzerinize taş yağdıran rüzgâr göndermeyeceğinden mi emin oldunuz? O zaman, uyarım nasılmış bileceksiniz!"},{"n":18,"t":"Andolsun, onlardan öncekiler de yalanlamıştı. Beni inkâr etmenin sonucu nasıl oldu!?"},{"n":19,"t":"Üstlerinde kanat çırparak uçan kuşlara bakmazlar mı? Onları (havada) ancak Rahmân tutuyor. Şüphesiz O, her şeyi hakkıyla görendir."},{"n":20,"t":"Yahut Rahmân’dan başka size yardım edecek şu ordunuz (taraftarlarınız) kimlerdir? İnkârcılar ancak bir aldanış içindedirler."},{"n":21,"t":"Peki, Allah rızkını keserse, kimdir size rızık verecek olan? Hayır, onlar azgınlık ve nefretle direnip durdular."},{"n":22,"t":"Şimdi, yüzüstü kapanarak düşe kalka yürüyen mi daha doğru gider, yoksa dosdoğru bir yolda dimdik yürüyen mi?"},{"n":23,"t":"De ki: \"O, sizi yaratan ve size kulaklar, gözler ve kalpler verendir. Ne kadar da az şükrediyorsunuz!\""},{"n":24,"t":"De ki: \"O, sizi yeryüzünde yaratıp çoğaltandır. Ancak O’nun huzurunda toplanacaksınız.\""},{"n":25,"t":"\"Eğer doğru söyleyenler iseniz, bu tehdit ne zaman gerçekleşecek?\" diyorlar."},{"n":26,"t":"De ki: \"O bilgi, ancak Allah katındadır. Ben ise sadece apaçık bir uyarıcıyım.\""},{"n":27,"t":"Onu (azabı) yakından gördükleri zaman inkâr edenlerin yüzleri kötüleşir ve onlara, \"İşte bu, (alaylı bir biçimde) isteyip durduğunuz şeydir\" denir."},{"n":28,"t":"De ki: \"Söyleyin bakalım: Diyelim ki Allah beni ve beraberimdekileri helâk etti, yahut bize acıdı. Peki, ya inkârcıları elem dolu bir azaptan kim koruyacak?\""},{"n":29,"t":"De ki: \"O, Rahmân’dır. O’na iman ettik, yalnızca O’na tevekkül ettik. Siz, kimin apaçık bir sapıklık içinde olduğunu yakında öğreneceksiniz!\""},{"n":30,"t":"De ki: \"Söyleyin bakalım: Suyunuz çekiliverse, size kim temiz bir akar su getirir?\""}],[{"n":"1-2","t":"Nûn. (Ey Muhammed) Andolsun kaleme ve satır satır yazdıklarına ki, sen Rabbinin nimeti sayesinde, bir deli değilsin."},{"n":3,"t":"Şüphesiz sana tükenmez bir mükâfat vardır."},{"n":4,"t":"Sen elbette yüce bir ahlâk üzeresin."},{"n":"5-6","t":"Hanginizin deli olduğunu yakında sen de göreceksin, onlar da görecekler."},{"n":7,"t":"Şüphesiz senin Rabbin, kendi yolundan sapan kişiyi daha iyi bilir. O, hidayete erenleri de daha iyi bilir."},{"n":8,"t":"O hâlde yalanlayanlara boyun eğme."},{"n":9,"t":"İstediler ki, yumuşak davranasın, böylece onlar da yumuşak davransınlar."},{"n":"10-14","t":"Yemin edip duran, aşağılık, daima kusur arayıp kınayan, durmadan söz taşıyan, iyiliği hep engelleyen, saldırgan, günaha dadanmış, kaba saba; bütün bunların ötesinde bir de soysuz olan kimseye mal ve oğulları vardır diye, sakın boyun eğme."},{"n":15,"t":"Âyetlerimiz kendisine okunduğu zaman, \"Öncekilerin masalları!\" der."},{"n":16,"t":"Yakında biz onun burnunu damgalayacağız."},{"n":17,"t":"Şüphesiz biz, vaktiyle \"bahçe sahipleri\"ne belâ verdiğimiz gibi, onlara (Mekkeli inkârcılara) da belâ verdik. Hani o bahçe sahipleri, sabah erkenden (fakirler gelmeden) bahçenin ürünlerini devşirmeye yemin etmişlerdi."},{"n":18,"t":"(Bunu tasarlarken) istisna da yapmıyorlardı. (\"İnşaallah\" demiyorlardı.)"},{"n":19,"t":"Nihayet onlar uykuda iken Rabbinden bir afet (ateş) bahçeyi sardı."},{"n":20,"t":"Böylece bahçe, (anızı) yakılmış toprağa döndü."},{"n":"21-22","t":"Derken, sabahleyin birbirlerine, \"Haydi, eğer ürününüzü devşirecekseniz erkenden gidin\" diye seslendiler."},{"n":"23-24","t":"Bunun üzerine, \"Sakın, bugün orada hiçbir yoksul yanınıza sokulmasın\" diye fısıldaşarak yola koyuldular."},{"n":25,"t":"(Yoksullara yardım etmeğe) güçleri yettiği hâlde (böyle söyleyerek) erkenden yola çıktılar."},{"n":26,"t":"Fakat bahçeyi o hâlde gördüklerinde, \"Biz mutlaka yolumuzu şaşırmış olmalıyız!\" dediler."},{"n":27,"t":"(Gerçeği anlayınca da), \"Hayır, meğer biz mahrum bırakılmışız!\" dediler."},{"n":28,"t":"Onların en akl-ı selim sahibi olanı, \"Ben size ‘Rabbinizi tespih etseydiniz ya! dememiş miydim?\" dedi."},{"n":29,"t":"Onlar, \"Rabbimizi tesbih ederiz (yüceltiriz). Şüphesiz biz zalim kimseler imişiz\" dediler."},{"n":30,"t":"Bunun üzerine birbirlerini kınamaya başladılar."},{"n":31,"t":"Şöyle dediler: \"Yazıklar olsun bize! Gerçekten biz azgın kişilermişiz!\""},{"n":32,"t":"\"Umulur ki, Rabbimiz bize bunun yerine daha iyisini verir. Çünkü biz artık Rabbimizi arzulayanlarız.\""},{"n":33,"t":"İşte böyledir azap! Ahiret azabı ise elbette daha büyüktür; ah bir bilselerdi!"},{"n":34,"t":"Şüphesiz Allah’a karşı gelmekten sakınanlar için Rableri katında Naîm cennetleri vardır."},{"n":35,"t":"Biz müslümanları suçlular gibi kılar mıyız?"},{"n":36,"t":"Size ne oluyor, nasıl hüküm veriyorsunuz?"},{"n":37,"t":"Yoksa size ait bir kitabınız var da (bu batıl hükümleri) ondan mı okuyorsunuz?"},{"n":38,"t":"Onda, \"Seçip beğendiğiniz her şey mutlaka sizindir\" (diye mi yazılı?)"},{"n":39,"t":"Yahut bizden, her ne hükmederseniz mutlaka öyle olacağına dair Kıyamete kadar sürecek kesin sözler mi aldınız?"},{"n":40,"t":"Sor onlara: \"Onların hangisi bu (iddianın doğruluğu)na kefildir?\""},{"n":41,"t":"Yoksa onların ortakları mı var? Doğru söyleyenler iseler, haydi getirsinler ortaklarını!"},{"n":"42-43","t":"Baldırların açılacağı (işlerin zorlaşacağı) ve kâfirlerin secdeye çağrılıp da gözleri düşmüş ve kendilerini zillet kaplamış bir hâlde buna güç yetiremeyecekleri günü (Kıyamet gününü) düşün. Hâlbuki onlar sağlıklarında secde etmeye çağrılıyorlar (ve buna yanaşmıyorlar)dı."},{"n":44,"t":"(Ey Muhammed!) Bu sözü (Kur’an’ı) yalanlayanlarla beni baş başa bırak. Biz onları bilemeyecekleri biçimde adım adım helâka yaklaştıracağız."},{"n":45,"t":"Onlara mühlet veriyorum. Şüphesiz benim tuzağım sağlamdır."},{"n":46,"t":"Yoksa sen onlardan bir ücret istiyorsun da onlar bu yüzden ağır bir borç yükü altına mı girmişlerdir?"},{"n":47,"t":"Yahut gayb (Levh-i Mahfuz) kendi yanlarında da onlar mı (bundan aktarıp) yazıyorlar?"},{"n":48,"t":"Sen, Rabbinin hükmüne sabret. Balık sahibi (Yûnus) gibi olma. Hani o, (balığın karnında) kederli bir hâlde Rabbine yakarmıştı."},{"n":49,"t":"Şayet Rabbinden ona bir nimet yetişmemiş olsaydı, o mutlaka kınanmış bir hâlde ıssız bir yere atılacaktı."},{"n":50,"t":"(Fakat böyle olmadı.) Rabbi onu (peygamber olarak) seçti ve salih kimselerden kıldı."},{"n":51,"t":"Şüphesiz inkâr edenler Zikr’i (Kur’an’ı) duydukları zaman neredeyse seni gözleriyle devirecekler. (Senin için,) \"Hiç şüphe yok o bir delidir\" diyorlar."},{"n":52,"t":"Hâlbuki o (Kur’an), âlemler için ancak bir öğüttür."}],[{"n":1,"t":"Gerçekleşecek olan kıyamet!"},{"n":2,"t":"Nedir o gerçekleşecek olan kıyamet?"},{"n":3,"t":"Gerçekleşecek olan kıyametin ne olduğunu sen ne bileceksin?"},{"n":4,"t":"Semûd ve Âd kavimleri, yüreklerini hoplatacak olan büyük felaketi (Kıyameti) yalanladılar."},{"n":5,"t":"Semûd kavmi korkunç bir sarsıntı ile helâk edildi."},{"n":6,"t":"Âd kavmine gelince, onlar da uğultulu ve dondurucu şiddetli bir rüzgârla helâk edildi."},{"n":7,"t":"Allah, onu kesintisiz olarak yedi gece, sekiz gün onların üzerine musallat etti. Öyle ki (eğer orada olsaydın), o kavmi, içi boş hurma kütükleri gibi oracıkta yere serilmiş hâlde görürdün."},{"n":8,"t":"Şimdi onlardan geri kalan bir şey görüyor musun?"},{"n":9,"t":"Firavun, ondan öncekiler ve yerle bir olan şehirler (halkı olan Lût kavmi) hep o suçu işlediler."},{"n":10,"t":"Öyle ki Rablerinin elçilerine karşı geldiler. Bunun üzerine Allah da onları gittikçe artan bir azap ile yakaladı."},{"n":"11-12","t":"Şüphesiz, (Nûh zamanında) su bastığı vakit, sizi gemide biz taşıdık ki, bu olayı sizin için bir uyarı yapalım ve belleyecek kulaklar da onu bellesin."},{"n":"13-15","t":"Sûr’a bir defa üfürülünce, yeryüzü ve dağlar kaldırılıp birbirine bir çarptırılınca, işte o gün olacak olmuş (kıyamet kopmuş)tur."},{"n":16,"t":"Gök de yarılmış ve artık o gün o da çökmeye yüz tutmuştur."},{"n":17,"t":"Melekler onun kıyılarındadır. O gün Rabbinin Arş’ını, bunların da üstünde sekiz taşıyıcı taşır."},{"n":18,"t":"O gün (hesap için Allah’a) arz olunursunuz. Hiçbir sırrınız gizli kalmaz."},{"n":19,"t":"İşte o vakit, kitabı kendisine sağından verilen kimse der ki: \"Gelin, kitabımı okuyun!\""},{"n":20,"t":"\"Çünkü ben, hesabımla karşılaşacağımı zaten biliyordum.\""},{"n":21,"t":"Artık o, hoşnut bir hayat içindedir."},{"n":22,"t":"Yüksek bir cennettedir."},{"n":23,"t":"Onun meyveleri sarkar (kolaylıkla devşirilebilir)."},{"n":24,"t":"(Onlara şöyle denir:) \"Geçmiş günlerde yaptıklarınıza karşılık, afiyetle yiyin, için."},{"n":25,"t":"Kitabı kendisine sol tarafından verilen ise şöyle der: \"Keşke kitabım bana verilmeseydi.\""},{"n":26,"t":"\"Hesabımın ne olduğunu da bilmeseydim.\""},{"n":27,"t":"\"Keşke ölüm her şeyi bitirseydi.\""},{"n":28,"t":"\"Malım bana hiçbir yarar sağlamadı.\""},{"n":29,"t":"\"Saltanatım da yok olup gitti.\""},{"n":30,"t":"(Allah, şöyle der:) \"Onu yakalayıp bağlayın.\""},{"n":31,"t":"\"Sonra onu cehenneme atın.\""},{"n":32,"t":"\"Sonra uzunluğu yetmiş arşın olan zincire vurun onu.\""},{"n":33,"t":"\"Çünkü o, azamet sahibi Allah’a iman etmiyordu.\""},{"n":34,"t":"\"Yoksulu doyurmağa teşvik etmiyordu.\""},{"n":35,"t":"\"Bu sebeple, bugün burada onun samimi bir dostu yoktur.\""},{"n":36,"t":"\"Kanlı irinden başka bir yiyeceği de yoktur.\""},{"n":37,"t":"Onu günahkârlardan başkası yemez.\""},{"n":"38-40","t":"Görebildiklerinize ve göremediklerinize yemin ederim ki, o (Kur’an), hiç şüphesiz çok şerefli bir elçinin (Allah’tan alıp tebliğ ettiği) sözüdür."},{"n":41,"t":"O, bir şairin sözü değildir. Ne de az inanıyorsunuz!"},{"n":42,"t":"Bir kâhinin sözü de değildir. Ne de az düşünüyorsunuz!"},{"n":43,"t":"O, âlemlerin Rabbi tarafından indirilmedir."},{"n":"44-45","t":"Eğer (Peygamber) bize isnat ederek bazı sözler uydurmuş olsaydı, mutlaka onu kudretimizle yakalardık."},{"n":46,"t":"Sonra da onun şah damarını mutlaka keserdik."},{"n":47,"t":"Hiçbiriniz de bu cezayı engelleyip ondan savamazdı."},{"n":48,"t":"Şüphesiz Kur’an, Allah’a karşı gelmekten sakınanlara bir öğüttür."},{"n":49,"t":"Şüphesiz biz, içinizden yalanlayanların olduğunu elbette biliyoruz."},{"n":50,"t":"Şüphesiz Kur’an, kâfirler için mutlaka bir pişmanlık sebebidir."},{"n":51,"t":"Şüphesiz Kur’an, gerçek kesin bilgidir."},{"n":52,"t":"O hâlde sen, yüce Rabbinin adıyla tespih et."}],[{"n":"1-3","t":"Soran birisi, yükselme yollarının sahibi Allah tarafından kâfirlere kesinlikle inecek olan ve hiç kimsenin uzaklaştıramayacağı azabı sordu."},{"n":4,"t":"Melekler ve Ruh (Cebrail) ona süresi elli bin yıl olan bir günde yükselir."},{"n":5,"t":"(Ey Muhammed!) Sen güzel bir şekilde sabret."},{"n":6,"t":"Şüphesiz onlar o azabı uzak görüyorlar."},{"n":7,"t":"Biz ise onu yakın görüyoruz."},{"n":"8-9","t":"Göğün, erimiş maden gibi ve dağların atılmış renkli yün gibi olacağı günü hatırla."},{"n":10,"t":"(O gün) hiçbir samimi dost, dostunu sormaz."},{"n":"11-14","t":"Birbirlerine gösterilirler. Günahkâr kimse ister ki, o günün azabından kurtulmak için oğullarını, karısını, kardeşini, kendisini koruyup barındıran tüm ailesini ve yeryüzünde bulunanların hepsini fidye olarak versin de, kendisini kurtarsın."},{"n":"15-16","t":"Hayır (ne mümkün)! Şüphesiz cehennem, derileri kavurup çıkaran alevli ateştir."},{"n":"17-18","t":"O, (hakka) arka döneni ve (imandan) yüz çevireni; servet toplayıp yığanı kendine çağırır."},{"n":19,"t":"Şüphesiz insan çok hırslı ve sabırsız olarak yaratılmıştır."},{"n":20,"t":"Kendisine kötülük dokunduğu zaman sızlanır."},{"n":21,"t":"Ona bir hayır dokunduğunda da eli sıkıdır."},{"n":22,"t":"Ancak, namaz kılanlar başka."},{"n":23,"t":"Onlar, namazlarına devam eden kimselerdir."},{"n":"24-25","t":"Onlar, mallarında; isteyenler ve (isteyemeyip) mahrum kalanlar için belli bir hak bulunan kimselerdir."},{"n":26,"t":"Onlar, ceza gününü tasdik eden kimselerdir."},{"n":27,"t":"Onlar, Rablerinin azabından korkan kimselerdir."},{"n":28,"t":"Çünkü, Rablerinin azabından emin olunamaz."},{"n":29,"t":"Onlar, mahrem yerlerini koruyan kimselerdir."},{"n":30,"t":"Ancak eşleri, yahut sahip oldukları cariyeleri başka. Çünkü onlar (eşleri ve cariyeleri ile olan ilişkileri konusunda) kınanmazlar."},{"n":31,"t":"Kim bunun ötesini isterse, işte onlar sınırı aşan kimselerdir."},{"n":32,"t":"Onlar, emanetlerini ve verdikleri sözü gözeten kimselerdir."},{"n":33,"t":"Onlar, şahitliklerini dosdoğru yapan kimselerdir."},{"n":34,"t":"Onlar, namazlarını titizlikle koruyan kimselerdir."},{"n":35,"t":"İşte onlar cennetlerde ikram göreceklerdir."},{"n":"36-37","t":"Şimdi, inkâr edenlere ne oluyor ki, boyunlarını uzatarak (alay etmek için) sağdan soldan gruplar hâlinde sana doğru koşuyorlar?"},{"n":38,"t":"Onlardan her biri Naîm cennetine sokulacağını mı umuyor?"},{"n":39,"t":"Hayır (ne mümkün)! Şüphesiz biz onları kendilerinin de bildikleri şeyden (meniden) yarattık."},{"n":"40-41","t":"Doğuların ve Batıların Rabbine yemin ederim ki, şüphesiz onların yerine daha iyilerini getirmeye bizim gücümüz yeter. Bizim önümüze geçilemez."},{"n":42,"t":"Sen onları bırak, uyarıldıkları günlerine kavuşuncaya kadar batıl inançlarına dalsınlar ve oynasınlar."},{"n":"43-44","t":"Dikili putlara akın akın gidercesine, gözleri inmiş, kendilerini zillet kaplamış bir hâlde mezarlarından süratle çıkacakları o günü hatırla! İşte o, uyarıldıkları gündür."}],[{"n":1,"t":"Şüphesiz biz Nûh’u, kavmine, \"Kendilerine elem dolu bir azap gelmeden önce kavmini uyar\" diye peygamber olarak gönderdik."},{"n":2,"t":"Nûh, şöyle dedi: \"Ey kavmim! Şüphesiz, ben sizin için apaçık bir uyarıcıyım.\""},{"n":"3-4","t":"\"Allah’a ibadet edin. O’na karşı gelmekten sakının ve bana itaat edin ki sizin günahlarınızı bağışlasın ve sizi belli bir vakte kadar ertelesin. Şüphesiz, Allah’ın belirlediği vakit gelince ertelenmez. Keşke bilseydiniz.\""},{"n":5,"t":"Nûh, şöyle dedi: \"Ey Rabbim! Gerçekten ben kavmimi gece gündüz (imana) davet ettim.\""},{"n":6,"t":"Fakat benim davetim ancak onların kaçışını artırdı.\""},{"n":7,"t":"\"Kuşkusuz sen onları bağışlayasın diye kendilerini her davet edişimde parmaklarını kulaklarına tıkadılar, elbiselerine büründüler, inanmamakta direndiler ve büyük bir kibir gösterdiler.\""},{"n":8,"t":"\"Sonra ben onları açık açık davet ettim.\""},{"n":9,"t":"\"Sonra, onlarla hem açıktan açığa, hem de gizli gizli konuştum.\""},{"n":10,"t":"\"Dedim ki: ‘Rabbinizden bağışlama dileyin; çünkü O, çok bağışlayıcıdır.’"},{"n":11,"t":"‘(Bağışlama dileyin ki,) üzerinize gökten bol bol yağmur indirsin.’"},{"n":12,"t":"‘Sizi mallarla, oğullarla desteklesin ve sizin için bahçeler var etsin, sizin için ırmaklar var etsin.’"},{"n":13,"t":"‘Size ne oluyor da Allah için bir vakar (saygınlık, büyüklük) ummuyorsunuz?’"},{"n":14,"t":"‘Hâlbuki, O, sizi evrelerden geçirerek yaratmıştır.’"},{"n":15,"t":"‘Görmediniz mi, Allah yedi göğü tabaka tabaka nasıl yaratmıştır?’"},{"n":16,"t":"‘Onların içinde nasıl ayı, bir ışık, güneşi de bir kandil yapmıştır?’"},{"n":17,"t":"‘Allah, sizi (babanız Âdem’i) yerden (bitki bitirir gibi) bitirdi (yarattı.)’"},{"n":18,"t":"‘Sonra sizi yine oraya döndürecek ve kesinlikle sizi (yeniden) çıkaracaktır.’"},{"n":"19-20","t":"‘Allah, yeryüzünü sizin için bir sergi yapmıştır ki, oradaki geniş yollarda yürüyesiniz.\""},{"n":21,"t":"Nûh, dedi ki: \"Rabbim! Gerçekten onlar bana karşı geldiler, malı ve çocuğu ancak kendi hüsranını artıran kimselere uydular.\""},{"n":22,"t":"\"Bunlar da, çok büyük bir tuzak kurdular.\""},{"n":23,"t":"\"Şöyle dediler: ‘Sakın ilâhlarınızı bırakmayın. Hele hele Vedd’i, Süvâ’ı, Yeğûs’u, Ye’ûk’u ve Nesr’i hiç bırakmayın.\""},{"n":24,"t":"\"Onlar gerçekten birçoklarını saptırdılar. (Rabbim!) Sen de bu zalimlerin sadece sapıklıklarını artır.\""},{"n":25,"t":"Hataları (küfür ve isyanları) yüzünden suda boğuldular ve cehenneme sokuldular da kendileri için Allah’tan başka yardımcılar bulamadılar."},{"n":26,"t":"Nûh, şöyle dedi: \"Ey Rabbim! Kâfirlerden hiç kimseyi yeryüzünde bırakma!\""},{"n":27,"t":"\"Çünkü sen onları bırakırsan, kullarını saptırırlar; sadece ahlâksız ve kâfir kimseler yetiştirirler.\""},{"n":28,"t":"\"Rabbim! Beni, ana babamı, iman etmiş olarak evime girenleri, iman eden erkekleri ve iman eden kadınları bağışla. Zalimlerin de ancak helâkini arttır.\""}],[{"n":"1-2","t":"(Ey Muhammed!) De ki: \"Bana cinlerden bir topluluğun (Kur’an’ı) dinleyip şöyle dedikleri vahyedildi: \"Şüphesiz biz doğruya ileten hayranlık verici bir Kur’an dinledik de ona inandık. Artık, Rabbimize hiç kimseyi asla ortak koşmayacağız.\""},{"n":3,"t":"\"Doğrusu Rabbimizin şanı çok yücedir; ne bir eş edinmiştir, ne de bir çocuk.\""},{"n":4,"t":"\"Demek bizim beyinsiz olanımız, Allah hakkında doğruluktan uzak sözler söylüyormuş.\""},{"n":5,"t":"\"Şüphesiz biz, insanların ve cinlerin Allah hakkında asla yalan söylemeyeceklerini sanıyorduk.\""},{"n":6,"t":"\"Doğrusu insanlardan bazı kimseler, cinlerden bazılarına sığınırlardı da, cinler onların taşkınlıklarını artırırlardı.\""},{"n":7,"t":"\"Gerçekten onlar da, sizin sandığınız gibi, Allah’ın hiç kimseyi öldükten sonra tekrar diriltmeyeceğini sanmışlardı.\""},{"n":8,"t":"\"Kuşkusuz biz göğe ulaşmak istedik, fakat onu çetin bekçilerle ve yakıcı ışıklarla dolu bulduk.\""},{"n":9,"t":"\"Hâlbuki biz, (daha önce) göğün bazı yerlerinde gayb haberlerini dinlemek için otururduk. Fakat şimdi her kim dinlemeye kalkacak olursa, kendini gözetleyen yakıcı bir ışık bulur.\""},{"n":10,"t":"\"Hakikaten biz bilmiyoruz, yeryüzündekilere kötülük mü istendi, yoksa Rableri onlara bir hayır mı diledi?\""},{"n":11,"t":"\"Doğrusu içimizde salih olanlar da var, olmayanlar da. Ayrı ayrı yollar tutmuşuz.\""},{"n":12,"t":"\"Muhakkak ki biz Allah’ı yeryüzünde âciz bırakamayacağımızı, kaçarak da onu âciz bırakamayacağımızı anladık.\""},{"n":13,"t":"\"Gerçekten biz hidayet rehberini (Kur’an’ı) işitince ona inandık. Kim Rabbine inanırsa, artık ne hakkının eksik verilmesinden, ne de haksızlığa uğramaktan korkar.\""},{"n":14,"t":"\"Kuşkusuz içimizde müslüman olanlar da var, hak yoldan sapanlar da var. Kim müslüman olursa, işte onlar doğruyu arayıp bulmuşlardır.\""},{"n":15,"t":"\"Hak yoldan sapanlara gelince, onlar cehenneme odun olmuşlardır.\""},{"n":"16-17","t":"Yine de ki: \"Bana şöyle de vahyedildi: ‘Eğer yolda dosdoğru olurlarsa, mutlaka onlara bol yağmur yağdırırız ki bununla onları imtihan edelim. Kim Rabbinin zikrinden (Kur’an’dan) yüz çevirirse, Rabbi onu gittikçe yükselen bir azaba sokar.\""},{"n":18,"t":"\"Şüphesiz mescitler, Allah’ındır. O hâlde, Allah ile birlikte hiç kimseye kulluk etmeyin.\""},{"n":19,"t":"\"Allah’ın kulu (Muhammed), O’na ibadet etmek için kalktığında cinler nerede ise (Kur’an’ı dinlemek için kalabalıktan) onun etrafında birbirlerine geçiyorlardı."},{"n":20,"t":"De ki: \"Şüphesiz ben ancak Rabbime ibadet ederim ve O’na hiç kimseyi ortak koşmam.\""},{"n":21,"t":"De ki: \"Şüphesiz ben, size ne zarar verebilir ne de fayda sağlayabilirim.\""},{"n":22,"t":"De ki: \"Gerçekten beni Allah’a karşı hiç kimse asla koruyamaz ve yine asla O’ndan başka sığınacak kimse de bulamam.\""},{"n":23,"t":"\"Ancak Allah’tan gelenleri tebliğ edebilirim ve O’nun vahiylerini açıklayabilirim. Kim Allah’a ve Resûlüne karşı gelirse, şüphesiz onlar için, içinde ebedî kalacakları cehennem ateşi vardır.\""},{"n":24,"t":"Nihayet uyarıldıkları şeyi gördüklerinde kimin yardımcısı daha zayıf, kimin sayısı daha azmış, bilecekler."},{"n":25,"t":"De ki: \"Sizin uyarıldığınız şey yakın mıdır, yoksa Rabbim ona uzun bir süre mi koyacaktır, bilemem.\""},{"n":26,"t":"O, gaybı bilendir. Hiç kimseye gaybını bildirmez."},{"n":"27-28","t":"Ancak seçtiği resûller başka. (Onlara bildirir.) Fakat O, Resûlün önünde ve arkasında gözetleyici (melek)ler yürütür ki resûllerin, Rablerinin vahiylerini tebliğ ettiklerini bilsin. Allah, onların her hâlini kuşatmış ve her şeyi inceden inceye sayıp dökmüştür."}],[{"n":1,"t":"Ey örtünüp bürünen (Peygamber)!"},{"n":"2-3","t":"Kalk, birazı hariç olmak üzere geceyi; yarısını ibadetle geçir. Yahut bundan biraz eksilt."},{"n":4,"t":"Yahut buna biraz ekle. Kur’an’ı ağır ağır, tane tane oku."},{"n":5,"t":"Şüphesiz biz sana (sorumluluğu) ağır bir söz vahyedeceğiz."},{"n":6,"t":"Şüphesiz gece ibadetinin etkisi daha fazla, (bu ibadetteki) sözler (Kur’an ve dua okuyuşlar) ise daha düzgün ve açıktır."},{"n":7,"t":"Çünkü gündüzün sana uzun bir meşguliyet vardır."},{"n":8,"t":"Rabbinin adını an ve bütün benliğinle O’na yönel."},{"n":9,"t":"O, doğunun da batının da Rabbidir. O’ndan başka hiçbir ilâh yoktur. Öyle ise O’nu vekil edin."},{"n":10,"t":"Onların söylediklerine sabret ve onlardan güzellikle ayrıl."},{"n":11,"t":"Nimet içinde yüzen o yalanlayıcıları bana bırak ve onlara biraz mühlet ver."},{"n":"12-13","t":"Çünkü bizim yanımızda (kâfirler için) bukağılar vardır, cehennem vardır, boğazdan zor geçen yiyecekler vardır ve elem dolu bir azap vardır."},{"n":14,"t":"Yerin ve dağların sarsılacağı ve dağların akıp giden kum yığını olacağı günü (kıyameti) hatırla."},{"n":15,"t":"(Ey Mekkeliler!) Şüphesiz biz size üzerinize şahitlik edecek bir peygamber gönderdik. Nitekim, Firavun’a da bir peygamber göndermiştik."},{"n":16,"t":"Ama Firavun o peygambere isyan etti, biz de onu ağır ve çetin bir şekilde yakalayıverdik."},{"n":17,"t":"Hâl böyle iken inkâr ederseniz, çocukları ak saçlı ihtiyarlara çevirecek olan bir günden (kıyametten) nasıl korunursunuz?"},{"n":18,"t":"O günle gök (bile) yarılır, Allah’ın va’di gerçekleşir."},{"n":19,"t":"Şüphesiz bunlar bir öğüttür. Kim dilerse Rabbine ulaştıran bir yol tutar."},{"n":20,"t":"(Ey Muhammed!) Şüphesiz Rabbin, senin, gecenin üçte ikisine yakın kısmını, yarısını ve üçte birini ibadetle geçirdiğini biliyor. Beraberinde bulunanlardan bir topluluk da böyle yapıyor. Allah, gece ve gündüzü düzenleyip takdir eder. Sizin buna (gecenin tümünde yahut çoğunda ibadete) gücünüzün yetmeyeceğini bildi de sizi bağışladı (yükünüzü hafifletti.) Artık, Kur’an’dan kolayınıza geleni okuyun. Allah, içinizde hastaların bulunacağını, bir kısmınızın Allah’ın lütfundan rızık aramak üzere yeryüzünde dolaşacağını, diğer bir kısmınızın ise Allah yolunda çarpışacağını bilmektedir. O hâlde, Kur’an’dan kolayınıza geleni okuyun. Namazı dosdoğru kılın, zekâtı verin, Allah’a güzel bir borç verin. Kendiniz için önceden ne iyilik gönderirseniz, onu Allah katında daha üstün bir iyilik ve daha büyük mükâfat olarak bulursunuz. Allah’tan bağışlama dileyin. Şüphesiz Allah çok bağışlayandır, çok merhamet edendir."}],[{"n":1,"t":"Ey örtünüp bürünen (Peygamber!)"},{"n":2,"t":"Kalk da uyar."},{"n":3,"t":"Rabbini yücelt."},{"n":4,"t":"Nefsini arındır."},{"n":5,"t":"Şirkten uzak dur."},{"n":6,"t":"İyiliği, daha fazlasını bekleyerek (bir kazanç elde etmek için) yapma."},{"n":7,"t":"Rabbinin rızasına ermek için sabret."},{"n":"8-9","t":"Sûr’a üfürüldüğü zaman var ya; işte o gün çetin bir gündür."},{"n":10,"t":"Kâfirler için hiç kolay değildir."},{"n":11,"t":"Beni, yarattığım kişiyle baş başa bırak."},{"n":"12-13","t":"Ona bol mal ve gözü önünde duran oğullar verdim."},{"n":14,"t":"Kendisine alabildiğine imkânlar sağladım."},{"n":15,"t":"Sonra da o hırsla daha da artırmamı umar."},{"n":16,"t":"Hayır, umduğu gibi olmayacak. Çünkü o, bizim âyetlerimize karşı inatçıdır."},{"n":17,"t":"Ben onu dimdik bir yokuşa sardıracağım."},{"n":18,"t":"Çünkü o, düşündü taşındı, ölçtü biçti."},{"n":19,"t":"Kahrolası nasıl da ölçtü biçti!"},{"n":20,"t":"Yine kahrolası, nasıl ölçtü biçti!"},{"n":21,"t":"Sonra (Kur’an hakkında) derin derin düşündü."},{"n":22,"t":"Sonra yüzünü ekşitti, kaşlarını çattı."},{"n":"23-24","t":"Sonra arkasını döndü ve büyüklük taslayıp şöyle dedi: \"Bu, ancak nakledilegelen bir sihirdir.\""},{"n":25,"t":"\"Bu, ancak insan sözüdür.\""},{"n":26,"t":"Ben onu \"Sekar\"a (cehenneme) sokacağım."},{"n":27,"t":"Sekar’ın ne olduğunu sen ne bileceksin?"},{"n":28,"t":"Geride bir şey koymaz, bırakmaz."},{"n":29,"t":"Derileri kavurur."},{"n":30,"t":"Üzerinde on dokuz (görevli melek) vardır."},{"n":31,"t":"Biz, cehennemin görevlilerini ancak meleklerden kıldık. Onların sayısını inkâr edenler için bir imtihan vesilesi yaptık ki kendilerine kitap verilenler kesin olarak bilsinler, iman edenlerin imanı artsın, kendilerine kitap verilenler ve mü’minler şüpheye düşmesin, kalplerinde bir hastalık bulunanlar ile kâfirler, \"Allah, örnek olarak bununla neyi anlatmak istedi\" desinler. İşte böyle. Allah, dilediğini saptırır, dilediğini doğru yola iletir. Rabbinin ordularını ancak kendisi bilir. Bu, insanlar için ancak bir uyarıdır."},{"n":"32-37","t":"Hayır, (öğüt almazlar.) Aya, çekilip gittiğinde geceye, aydınlandığında sabaha andolsun ki o (cehennem) insan için; içinizden ileri geçmek yahut geri kalmak isteyenler için uyarıcı olarak elbette en büyük bir şeydir."},{"n":38,"t":"Herkes kazandığına karşılık bir rehindir."},{"n":39,"t":"Ancak ahiret mutluluğuna eren kimseler başka."},{"n":"40-42","t":"Onlar cennetlerdedirler. Birbirlerine suçlular hakkında sorular sorarlar ve dönüp onlara şöyle derler: \"Sizi Sekar’a (cehenneme) ne soktu?\""},{"n":43,"t":"Onlar şöyle derler: \"Biz namaz kılanlardan değildik.\""},{"n":44,"t":"\"Yoksula yedirmezdik.\""},{"n":45,"t":"\"Batıla dalanlarla birlikte biz de dalardık.\""},{"n":46,"t":"\"Ceza gününü de yalanlıyorduk.\""},{"n":47,"t":"\"Nihayet ölüm bize gelip çattı.\""},{"n":48,"t":"Artık şefaatçilerin şefaati onlara fayda vermez."},{"n":49,"t":"Böyle iken onlara ne oluyor da, öğütten yüz çeviriyorlar?"},{"n":"50-51","t":"Onlar sanki arslandan kaçan yaban eşekleridirler."},{"n":52,"t":"Hatta onlardan her bir kişi, kendisine açılmış sahifeler verilmesini istiyor."},{"n":53,"t":"Hayır, hayır! Onlar ahiretten korkmuyorlar."},{"n":54,"t":"Hayır, düşündükleri gibi değil! Şüphesiz bu (Kur’an) bir uyarıdır."},{"n":55,"t":"Artık kim dilerse ondan öğüt alır."},{"n":56,"t":"Bununla beraber, Allah dilemedikçe öğüt alamazlar. O takvaya (kendisine karşı gelmekten sakınılmaya) ehil olandır, bağışlamaya ehil olandır."}],[{"n":1,"t":"Kıyamet gününe yemin ederim."},{"n":2,"t":"(Kusurlarından dolayı kendini) kınayan nefse de yemin ederim (ki diriltilip hesaba çekileceksiniz)."},{"n":3,"t":"İnsan, kendisinin kemiklerini bir araya getiremeyeceğimizi mi sanır?"},{"n":4,"t":"Evet bizim, onun parmak uçlarını bile düzenlemeye gücümüz yeter."},{"n":5,"t":"Fakat insan önünü (geleceğini, kıyameti) yalanlamak ister."},{"n":6,"t":"\"O kıyamet günü ne zaman?\" diye sorar."},{"n":"7-10","t":"Gözler kamaştığı, ay karanlığa gömüldüğü, güneş ve ay bir araya getirildiği zaman, o gün insan \"kaçış nereye?\" diyecektir."},{"n":11,"t":"Hayır, hiçbir sığınacak yer yoktur."},{"n":12,"t":"O gün varıp durulacak yer, sadece Rabbinin huzurudur."},{"n":13,"t":"O gün insana, yapıp önden gönderdiği ve yapmayıp geri bıraktığı şeyler haber verilir."},{"n":"14-15","t":"Hatta, mazeretlerini ortaya koysa da, o gün insan kendi aleyhine şahittir."},{"n":16,"t":"(Ey Muhammed!) Onu (vahyi) çarçabuk almak için dilini kımıldatma."},{"n":17,"t":"Şüphesiz onu toplamak ve okumak bize aittir."},{"n":18,"t":"O hâlde, biz onu okuduğumuz zaman, onun okunuşuna uy."},{"n":19,"t":"Sonra onu açıklamak da bize aittir."},{"n":"20-21","t":"Hayır! Siz dünyayı seviyorsunuz ve ahireti bırakıyorsunuz."},{"n":22,"t":"O gün birtakım yüzler aydındır."},{"n":23,"t":"Rablerine bakarlar."},{"n":24,"t":"O gün birtakım yüzler de asıktır."},{"n":25,"t":"Bel kemiklerini kıran bir felakete uğratılacaklarını anlarlar."},{"n":"26-30","t":"Hayır, can boğaza dayandığı, \"Kimdir (bunu) iyi edecek?\" dendiği, (ölmek üzere olanın da) bunun ayrılış olduğunu bildiği, bacakların birbirine dolandığı zaman, işte o gün sevk ediliş, Rabbinedir."},{"n":31,"t":"O, (Peygamberi) doğrulamamış, namaz da kılmamıştı."},{"n":32,"t":"Fakat yalanlamış ve yüz çevirmişti."},{"n":33,"t":"Sonra da kasıla kasıla ailesine gitmişti."},{"n":"34-35","t":"\"Bu azap sana lâyıktır, lâyık! Evet, lâyıktır sana, lâyık!\" denecektir."},{"n":36,"t":"İnsan, kendisinin başıboş bırakılacağını mı zanneder."},{"n":37,"t":"O dökülen meniden ibaret az bir su değil miydi?"},{"n":38,"t":"Sonra bu, bir \"alaka\" oldu. Derken Allah onu yaratıp güzelce şekillendirdi."},{"n":39,"t":"Nihayet ondan da erkek ve dişi iki eşi var etti."},{"n":40,"t":"Şimdi, bunları yapan Allah’ın ölüleri diriltmeye gücü yetmez mi?"}],[{"n":1,"t":"İnsan (henüz) anılır bir şey değilken (yaratılmamışken) üzerinden uzunca bir zaman geçti."},{"n":2,"t":"Şüphesiz biz insanı, karışım hâlindeki az bir sudan (meniden) yarattık ve onu imtihan edeceğiz. Bu sebeple onu işitir ve görür kıldık."},{"n":3,"t":"Şüphesiz biz onu (ömür boyu yürüyeceği) yola koyduk. O bu yolu ya şükrederek ya da nankörlük ederek kat eder."},{"n":4,"t":"Şüphesiz biz, kâfirler için zincirler, demir halkalar ve alevli bir ateş hazırladık."},{"n":5,"t":"İyiler ise, katkısı kâfur olan içecekler dolu bir kadehten içerler."},{"n":6,"t":"Bir pınar ki Allah’ın kulları ondan içer, onu (istedikleri şekilde) fışkırtıp akıtırlar."},{"n":7,"t":"O kullar adaklarını yerine getirirler. Kötülüğü her yanı kuşatmış bir günden korkarlar."},{"n":8,"t":"Onlar, seve seve yiyeceği yoksula, yetime ve esire yedirirler."},{"n":9,"t":"(Yedirdikleri kimselere şöyle derler:) \"Biz size sırf Allah rızası için yediriyoruz. Sizden bir karşılık ve bir teşekkür beklemiyoruz.\""},{"n":10,"t":"\"Çünkü biz, asık suratlı, çetin bir günden (o günün azabından dolayı) Rabbimizden korkarız.\""},{"n":11,"t":"Allah da onları o günün kötülüğünden korur ve yüzlerine bir aydınlık ve içlerine bir sevinç verir."},{"n":12,"t":"Sabretmelerine karşılık da onları cennet ve ipek(ten giysiler) ile mükâfatlandırır."},{"n":13,"t":"Orada koltuklar üzerine kurulmuş olarak bulunurlar. Orada ne güneş (yakıcı sıcak) görürler, ne de dondurucu soğuk."},{"n":14,"t":"Üzerlerine cennetin gölgeleri sarkmış, cennetin meyveleri (kolayca alınacak şekilde) yakınlaştırılarak hazırlanmıştır."},{"n":15,"t":"Etraflarında gümüş kaplar, şeffaf kadehler dolaştırılır."},{"n":16,"t":"Gümüşten billur kaplar ki, onları (ihtiyaca göre) ölçüp düzenlemişlerdir."},{"n":17,"t":"Orada kendilerine, katkısı zencefil olan içecekle dolu bir kâseden içirilir."},{"n":18,"t":"Orada bir pınar ki ona \"selsebil\" adı verilir."},{"n":19,"t":"Çevrelerinde, gördüğünde saçılmış inciler sanacağın, hep aynı gençlik ve güzellikte kalacak hizmetçiler dolaşır."},{"n":20,"t":"Orada, görünce (sonsuz) nimetler ve büyük bir mülk (hükümranlık) görürsün."},{"n":21,"t":"Üstlerinde ince ve kalın ipekten yeşil elbiseler vardır. Gümüş bileziklerle süsleneceklerdir. Rableri onlara tertemiz bir içecek içirecektir."},{"n":22,"t":"Onlara şöyle denecektir: \"Şüphesiz bu sizin için bir mükâfattır. Çalışma ve çabanız makbul görülmüştür.\""},{"n":23,"t":"Şüphe yok ki, Kur’an’ı sana elbette biz indirdik biz."},{"n":24,"t":"O hâlde, Rabbinin hükmüne sabret. Onlardan hiçbir günahkâra ve hiçbir nanköre itaat etme."},{"n":25,"t":"Sabah akşam Rabbinin adını an."},{"n":26,"t":"Gecenin bir kısmında O’na secde et; geceleyin de O’nu uzun uzadıya tespih et."},{"n":27,"t":"Şunlar (inanmayanlar) dünyayı tercih ediyorlar ve çetin bir günü arkalarına atıyorlar."},{"n":28,"t":"Onları biz yarattık ve eklemlerini (birbirine) biz bağladık. Dilediğimizde (onları yok eder) yerlerine benzerlerini getiririz."},{"n":29,"t":"İşte bu bir öğüttür. Dileyen, Rabbine ulaştıran bir yol tutar."},{"n":30,"t":"Allah’ın dilemesi olmadıkça siz dileyemezsiniz. Şüphesiz Allah hakkıyla bilendir, hüküm ve hikmet sahibidir."},{"n":31,"t":"O, dilediği kimseyi rahmetine sokar. Zalimlere ise elem dolu bir azap hazırlamıştır."}],[{"n":"1-7","t":"Ard arda gönderilenlere, kasırga gibi esenlere, hakkıyla yayanlara, hakkıyla ayıranlara, özür ya da uyarı olmak üzere öğüt bırakanlara andolsun ki, uyarıldığınız (Kıyamet) mutlaka gerçekleşecektir."},{"n":8,"t":"Yıldızların ışığı söndürüldüğü zaman,"},{"n":9,"t":"Gök yarıldığı zaman,"},{"n":10,"t":"Dağlar ufalanıp savrulduğu zaman,"},{"n":11,"t":"Peygamberler için (ümmetlerine şahitlik etmek üzere) vakit belirlendiği zaman (kıyamet gerçekleşir)."},{"n":12,"t":"(Bu) hangi güne ertelenmiştir?"},{"n":13,"t":"Hüküm ve ayırım gününe."},{"n":14,"t":"Hüküm ve ayırım gününü sen ne bileceksin."},{"n":15,"t":"O gün vay yalanlayanların hâline!"},{"n":16,"t":"Biz öncekileri helâk etmedik mi?"},{"n":17,"t":"Sonra arkadan gelenleri de onların peşine takacağız."},{"n":18,"t":"Biz suçlulara işte böyle yaparız."},{"n":19,"t":"O gün vay yalanlayanların hâline!"},{"n":20,"t":"Biz sizi bayağı bir sudan (meniden) yaratmadık mı?"},{"n":"21-22","t":"Sonra onu belli bir süreye kadar sağlam bir yerde (ana rahminde) tuttuk."},{"n":23,"t":"Sonra da ona ölçülü bir biçim verdik. Biz ne güzel biçim verenleriz!"},{"n":24,"t":"O gün vay yalanlayanların hâline!"},{"n":"25-26","t":"Biz yeryüzünü dirileri de ölüleri de toplayan (bir yurt) yapmadık mı?"},{"n":27,"t":"Orada sabit yüce dağlar yaratmadık mı, size tatlı bir su içirmedik mi?"},{"n":28,"t":"O gün vay yalanlayanların hâline!"},{"n":29,"t":"Onlara şöyle denecek: \"Yalanlamakta olduğunuz şeye (cehennem azabına) gidin.\""},{"n":"30-31","t":"\"Üç kola ayrılmış gölgeye gidin ki, o ne gölgelendirir ne de alevden korur.\""},{"n":32,"t":"Şüphesiz cehennem, her biri saray büyüklüğünde kıvılcımlar saçar."},{"n":33,"t":"Bunlar sanki birer kızıl devedir."},{"n":34,"t":"O gün vay yalanlayanların hâline!"},{"n":35,"t":"Bu, konuşamayacakları gündür."},{"n":36,"t":"Onlara izin de verilmez ki, özür dilesinler."},{"n":37,"t":"O gün vay yalanlayanların hâline!"},{"n":38,"t":"Bu, hüküm ve ayırma günüdür. Sizi ve öncekileri bir araya toplamışızdır."},{"n":39,"t":"Eğer bir tuzağınız varsa, haydi bana tuzak kurun!"},{"n":40,"t":"O gün vay yalanlayanların hâline!"},{"n":41,"t":"Allah’a karşı gelmekten sakınanlar, gölgeler içinde ve pınar başlarındadırlar."},{"n":42,"t":"Canlarının çektiği meyveler içerisindedirler."},{"n":43,"t":"\"Yapmakta olduğunuz şeylere karşılık afiyetle yiyin için.\""},{"n":44,"t":"Şüphesiz biz iyilik yapanları işte böyle mükâfatlandırırız."},{"n":45,"t":"O gün vay yalanlayanların hâline!"},{"n":46,"t":"Ey inkâr edenler! (Dünyada) yiyin ve birazcık yararlanın! Şüphesiz sizler suçlularsınız."},{"n":47,"t":"O gün vay yalanlayanların hâline!"},{"n":48,"t":"Onlara, \"Rükû edin (namaz kılın)\" dendiği zaman rükû etmezler."},{"n":49,"t":"O gün vay yalanlayanların hâline!"},{"n":50,"t":"Onlar artık ondan (Kur’an’dan) sonra hangi söze inanacaklar?"}],[{"n":1,"t":"Birbirlerine neyi soruyorlar?"},{"n":"2-3","t":"Üzerinde anlaşmazlığa düştükleri büyük haberi (mi)?"},{"n":4,"t":"Hayır, ileride bilecekler."},{"n":5,"t":"Yine hayır; ileride bilecekler."},{"n":"6-7","t":"Biz, yeryüzünü bir döşek, dağları da birer kazık yapmadık mı?"},{"n":8,"t":"Sizleri (erkekli dişili) eşler hâlinde yarattık."},{"n":9,"t":"Uykunuzu bir dinlenme (sebebi) kıldık."},{"n":10,"t":"Geceyi (sizi örten) bir elbise yaptık."},{"n":11,"t":"Gündüzü de geçimi temin zamanı kıldık."},{"n":12,"t":"Üstünüze yedi sağlam gök bina ettik."},{"n":13,"t":"Alev alev yanan aydınlatıcı ve ısıtıcı bir kandil yarattık."},{"n":"14-16","t":"Taneler, bitkiler, sarmaş dolaş bahçeler çıkaralım diye yağmur yüklü yoğun bulutlardan şarıl şarıl yağmur yağdırdık."},{"n":17,"t":"Şüphesiz hüküm ve ayırma günü belirlenmiş bir vakittir."},{"n":18,"t":"Bu, sûra üfürüleceği gün gerçekleşir ve siz bölük bölük gelirsiniz."},{"n":19,"t":"Gök açılır ve kapı kapı olur."},{"n":20,"t":"Dağlar yürütülür, serap hâline gelir."},{"n":"21-23","t":"Şüphesiz cehennem, bir gözetleme yeridir; azgınlar için, içinde çağlar boyu kalacakları bir dönüş yeridir."},{"n":24,"t":"Orada ne bir serinlik ve ne de içecek bir şey tadacaklar!"},{"n":"25-26","t":"Ancak, uygun bir ceza olarak kaynar su ve irin içecekler."},{"n":27,"t":"Çünkü onlar hesaba çekilmeyi ummuyorlardı."},{"n":28,"t":"Âyetlerimizi de alabildiğine yalanlamışlardı."},{"n":29,"t":"Biz ise, her şeyi bir kitapta (Levh-i Mahfuz’da) tamamiyle sayıp tespit ettik."},{"n":30,"t":"Kâfirlere şöyle denilir: \"Şimdi tadın. Artık bundan sonra yalnızca azabınızı artıracağız.\""},{"n":"31-34","t":"Şüphesiz Allah’a karşı gelmekten sakınanlara bir kurtuluş, bahçeler, üzümler, kendileriyle bir yaşta, göğüsleri çıkmış genç kızlar ve dolu dolu kadehler vardır."},{"n":35,"t":"Orada ne bir boş söz işitirler, ne de bir yalan."},{"n":"36-38","t":"Bunlar kendilerine; Rabbinden, göklerin ve yerin ve ikisi arasındakilerin Rabbinden, Rahmân’dan bir mükâfat, yeterli bir ihsan olarak verilmiştir. Onlar, Ruh’un (Cebrail’in) ve meleklerin saf duracakları gün Allah’a hitap edemeyeceklerdir. Sadece Rahmân’ın izin vereceği ve doğru söyleyecek olan kimseler konuşabilecektir."},{"n":39,"t":"İşte bu, hak olan gündür. Artık dileyen kimse Rabbine ulaştıran bir yol tutar."},{"n":40,"t":"Şüphesiz biz sizi, kişinin önceden elleriyle yaptıklarına bakacağı ve inkârcının, \"Keşke toprak olaydım!\" diyeceği günde gerçekleşecek olan yakın bir azaba karşı uyardık."}],[{"n":1,"t":"Andolsun (kâfirlerin ruhlarını) şiddetle çekip çıkaranlara,"},{"n":2,"t":"Andolsun (mü’minlerin ruhlarını) kolaylıkla alanlara,"},{"n":3,"t":"Andolsun yüzüp yüzüp gidenlere,"},{"n":4,"t":"Derken, öne geçenlere,"},{"n":5,"t":"Nihayet işi çekip çevirenlere (ki, mutlaka tekrar diriltileceksiniz)."},{"n":"6-7","t":"Büyük bir sarsıntının olacağı o günde o sarsıntıyı, peşinden gelen başka bir sarsıntı izleyecektir."},{"n":8,"t":"O gün birtakım kalpler (tedirginlik içinde) şiddetle çarpacaktır."},{"n":9,"t":"Onların gözleri (korku ile) inecektir."},{"n":10,"t":"Şöyle derler: \"Biz gerçekten gerisin geriye eski hâlimize mi döndürüleceğiz?\""},{"n":11,"t":"\"Bizler çürümüş kemiklere döndükten sonra mı?\""},{"n":12,"t":"\"Öyle ise bu hüsran dolu bir dönüştür\" dediler."},{"n":13,"t":"Hâlbuki o, bir haykırıştan (sûr’un üfürülmesinden) ibarettir."},{"n":14,"t":"Birdenbire kendilerini mahşerde buluverirler."},{"n":15,"t":"(Ey Muhammed!) Mûsâ’nın haberi sana geldi mi?"},{"n":16,"t":"Hani, Rabbi ona mukaddes Tuvâ vadisinde şöyle seslenmişti:"},{"n":17,"t":"\"Haydi Firavun’a git! Çünkü o azmıştır.\""},{"n":18,"t":"\"Ona de ki: İster misin (küfür ve isyanından) temizlenesin?"},{"n":19,"t":"Seni Rabbine ileteyim de O’na karşı derinden saygı duyup korkasın!\""},{"n":20,"t":"Derken Mûsâ ona en büyük mucizeyi gösterdi."},{"n":21,"t":"Fakat o, Mûsâ’yı yalanladı ve isyan etti."},{"n":22,"t":"Sonra sırt dönüp koşarak gitti."},{"n":23,"t":"Hemen (adamlarını) topladı ve onlara seslendi:"},{"n":24,"t":"\"Ben, sizin en yüce Rabbinizim!\" dedi."},{"n":25,"t":"Allah onu, ibret verici şekilde dünya ve âhiret cezasıyla cezalandırdı."},{"n":26,"t":"Şüphesiz bunda Allah’tan sakınıp korkan kimseler için büyük bir ibret vardır."},{"n":27,"t":"(Ey inkârcılar!) Sizi yaratmak mı daha zor, yoksa göğü yaratmak mı? Onu Allah kurmuştur."},{"n":28,"t":"Onu yükseltmiş ve ona düzen ve âhenk vermiştir."},{"n":29,"t":"O göğün gecesini karanlık yaptı, ışığını da çıkardı."},{"n":30,"t":"Ardından yeri düzenleyip döşedi."},{"n":31,"t":"Ondan suyunu ve merasını çıkardı."},{"n":32,"t":"Dağları sağlam bir şekilde yerleştirdi."},{"n":33,"t":"Bunları sizin için ve hayvanlarınız için bir yarar kaynağı yaptı."},{"n":"34-35","t":"En büyük felaket (kıyamet) geldiği zaman, o gün insan yaptıklarını hatırlar."},{"n":36,"t":"Cehennem, görenler için apaçık bir şekilde gösterilir."},{"n":"37-39","t":"Kim azgınlık eder ve dünya hayatını tercih ederse, şüphesiz, cehennem onun sığınağıdır."},{"n":"40-41","t":"Kim de, Rabbinin huzurunda duracağından korkar ve nefsini arzularından alıkoyarsa, şüphesiz, cennet onun sığınağıdır."},{"n":42,"t":"Sana, kıyametin ne zaman kopacağını soruyorlar."},{"n":43,"t":"Onu bilip söylemek nerede, sen nerede?"},{"n":44,"t":"Onun nihai bilgisi yalnız Rabbine âittir."},{"n":45,"t":"Sen, ancak ondan korkanları uyarıcısın."},{"n":46,"t":"Kıyameti gördükleri gün onlar, sanki dünyada ancak bir akşam, yahut bir kuşluk vakti kadar kalmış gibidirler."}],[{"n":"1-2","t":"Kendisine o âmâ geldi diye Peygamber yüzünü ekşitti ve öteye döndü."},{"n":3,"t":"(Ey Muhammed!) Ne bilirsin, belki de o arınacak,"},{"n":4,"t":"Yahut öğüt alacak da bu öğüt kendisine fayda verecek."},{"n":5,"t":"Kendini muhtaç hissetmeyene gelince;"},{"n":6,"t":"Sen, ona yöneliyorsun."},{"n":7,"t":"(İstemiyorsa) onun arınmamasından sana ne!"},{"n":"8-10","t":"Allah’a karşı derin bir saygıyla korku içinde koşarak sana geleni ise bırakıp, ona aldırmıyorsun."},{"n":11,"t":"Hayır, böyle yapma! Çünkü bu (Kur’an) bir öğüttür."},{"n":12,"t":"Dileyen ondan öğüt alır."},{"n":"13-16","t":"O, şerefli ve sâdık yazıcı meleklerin elindeki yüksek, tertemiz ve çok değerli sahifelerdedir."},{"n":17,"t":"Kahrolası (inkârcı) insan! Ne nankördür o!"},{"n":18,"t":"Allah, onu hangi şeyden yarattı?"},{"n":19,"t":"Az bir sudan (meniden). Onu yarattı ve ona ölçülü bir şekil verdi."},{"n":20,"t":"Sonra ona yolu kolaylaştırdı."},{"n":21,"t":"Sonra onu öldürdü ve kabre koydu."},{"n":22,"t":"Sonra, dilediği vakit onu diriltir."},{"n":23,"t":"Hayır, hayır o, Allah’ın kendisine emrettiğini yerine getirmedi. (İman etmedi.)"},{"n":24,"t":"Her şeyden önce insan, yediği yemeğine bir baksın!"},{"n":25,"t":"Gerçekten biz, yağmuru bol bol yağdırdık."},{"n":26,"t":"Sonra toprağı, iyiden iyiye yardık!"},{"n":"27-32","t":"Böylece sizin ve hayvanlarınızın yararlanması için orada taneler, üzümler, yoncalar, zeytinler, hurmalıklar, sık ağaçlı bahçeler, meyveler ve otlaklar ortaya çıkardık."},{"n":"33-37","t":"Kişinin kardeşinden, annesinden, babasından, eşinden ve çocuklarından kaçacağı gün kulakları sağır edercesine şiddetli ses geldiği vakit, işte o gün onlardan herkesin kendini meşgul edecek bir işi vardır."},{"n":38,"t":"O gün birtakım yüzler vardır ki pırıl pırıl parlarlar,"},{"n":39,"t":"Gülerler, sevinirler."},{"n":40,"t":"O gün nice yüzler de vardır ki, toz toprak içindedirler."},{"n":41,"t":"Onları bir siyahlık bürür."},{"n":42,"t":"İşte onlar, kâfirlerdir, günaha dalanlardır."}],[{"n":1,"t":"Güneş, dürüldüğü zaman,"},{"n":2,"t":"Yıldızlar, bulanıp söndüğü zaman,"},{"n":3,"t":"Dağlar, yürütüldüğü zaman,"},{"n":4,"t":"Gebe develer salıverildiği zaman."},{"n":5,"t":"Yaban hayatı yaşayan (irili ufaklı) tüm canlılar toplandığı zaman,"},{"n":6,"t":"Denizler kaynatıldığı zaman,"},{"n":7,"t":"Ruhlar (bedenlerle) eşleştirildiği zaman."},{"n":"8-9","t":"Diri diri gömülen kız çocuğunun, hangi günahtan ötürü öldürüldüğü sorulduğu zaman,"},{"n":10,"t":"Amel defterleri açıldığı zaman,"},{"n":11,"t":"Gökyüzü (yerinden) sıyrılıp koparıldığı zaman,"},{"n":12,"t":"Cehennem alevlendirildiği zaman,"},{"n":13,"t":"Cennet yaklaştırıldığı zaman,"},{"n":14,"t":"Herkes önceden hazırlayıp getirdiği şeyleri bilecektir."},{"n":"15-16","t":"Andolsun, bir görünüp bir sinenlere, akıp gidip kaybolanlara,"},{"n":17,"t":"Andolsun, yöneldiği zaman geceye,"},{"n":18,"t":"Andolsun, aydınlandığı zaman sabaha ki,"},{"n":"19-21","t":"O (Kur’an), şüphesiz değerli, güçlü ve Arş’ın sahibi katında itibarlı, orada (meleklerce) itaat edilen, güvenilir bir elçinin (Cebrail’in) getirdiği sözdür."},{"n":22,"t":"(Ey Kureyşliler!) Sizin arkadaşınız (Muhammed) bir deli değildir."},{"n":23,"t":"Andolsun o, Cebrâil’i apaçık ufukta gördü."},{"n":24,"t":"O, gayb hakkında cimri değildir."},{"n":25,"t":"Kur’an, kovulmuş şeytanın sözü değildir."},{"n":26,"t":"(Hâl böyle iken) nereye gidiyorsunuz?"},{"n":"27-28","t":"O, âlemler için, içinizden dürüst olmak isteyenler için, ancak bir öğüttür."},{"n":29,"t":"Âlemlerin Rabbi olan Allah dilemedikçe siz dileyemezsiniz."}],[{"n":1,"t":"Gök yarıldığı zaman,"},{"n":2,"t":"Yıldızlar saçıldığı zaman,"},{"n":3,"t":"Denizler kaynayıp fışkırtıldığı zaman,"},{"n":4,"t":"Kabirlerin içindekiler dışarı çıkarıldığı zaman,"},{"n":5,"t":"Herkes yaptığı ve yapmadığı şeyleri bilecek."},{"n":"6-8","t":"Ey insan! Seni yaratan, şekillendirip ölçülü yapan, dilediği bir biçimde seni oluşturan cömert Rabbine karşı seni ne aldattı?"},{"n":9,"t":"Hayır, hayır! Siz hesap ve cezayı yalanlıyorsunuz."},{"n":"10-11","t":"Hâlbuki üzerinizde muhakkak bekçiler, değerli yazıcılar vardır."},{"n":12,"t":"Onlar yapmakta olduklarınızı bilirler."},{"n":13,"t":"Şüphesiz, iyiler Naîm cennetindedirler."},{"n":14,"t":"Şüphesiz, günahkârlar da cehennemdedirler."},{"n":15,"t":"Hesap ve ceza günü oraya gireceklerdir."},{"n":16,"t":"Onlar oradan kaybolup kurtulacak da değillerdir."},{"n":17,"t":"Hesap ve ceza gününün ne olduğunu sen ne bileceksin?"},{"n":18,"t":"Evet, hesap ve ceza gününün ne olduğunu sen ne bileceksin?"},{"n":19,"t":"O gün kimse kimseye hiçbir fayda sağlayamayacaktır. O gün buyruk, yalnız Allah’ındır."}],[{"n":1,"t":"Ölçüde ve tartıda hile yapanların vay hâline!"},{"n":2,"t":"Onlar insanlardan (bir şey) ölçüp aldıkları zaman, tam ölçerler."},{"n":3,"t":"Fakat kendileri onlara bir şey ölçüp, yahut tartıp verdikleri zaman eksik ölçüp tartarlar."},{"n":"4-6","t":"Onlar, büyük bir gün; insanların, âlemlerin Rabbinin huzurunda duracakları gün için diriltileceklerini sanmıyorlar mı?"},{"n":7,"t":"Hayır, günahkârların yazısı, muhakkak \"Siccîn\"dedir."},{"n":8,"t":"\"Siccîn\"in ne olduğunu sen ne bileceksin."},{"n":9,"t":"O, yazılmış bir kitaptır."},{"n":"10-11","t":"O gün yalanlayanların; hesap ve ceza gününü yalanlayanların vay hâline!"},{"n":12,"t":"Onu, ancak her azgın, günahkâr kimse inkâr eder."},{"n":13,"t":"Ona âyetlerimiz okununca, \"Eskilerin masalları\" der."},{"n":14,"t":"Hayır, hayır! Doğrusu onların kazanmakta oldukları kalplerini paslandırmıştır."},{"n":15,"t":"Hayır, şüphesiz onlar, kıyamet günü Rablerini görmekten mahrum bırakılacaklardır."},{"n":16,"t":"Sonra onlar muhakkak cehenneme gireceklerdir."},{"n":17,"t":"Sonra da onlara, \"Yalanlamakta olduğunuz işte budur\" denecektir."},{"n":18,"t":"Hayır (sandıkları gibi değil!) iyilerin yazısı \"İlliyyûn\"dadır."},{"n":19,"t":"\"İlliyyûn\"un ne olduğunu sen ne bileceksin."},{"n":20,"t":"O, yazılmış bir kitaptır."},{"n":21,"t":"Ona, Allah’a yakın olanlar şâhit olur."},{"n":22,"t":"Şüphesiz iyi kimseler, Naîm cennetindedirler."},{"n":23,"t":"Koltuklar üzerinde, (etrafı) seyrederler."},{"n":24,"t":"Onların yüzlerinde, nimetlerin sevincini görürsün."},{"n":25,"t":"Onlara, mühürlü (el değmemiş) saf bir içecekten içirilir."},{"n":26,"t":"Onun (içiminin) sonu bir misktir (ağızda misk gibi koku bırakır). İşte yarışanlar, bunun için yarışsınlar."},{"n":27,"t":"O içeceğin katkısı tesnimdir."},{"n":28,"t":"Bir pınar ki, Allah’a yakın olanlar ondan içerler."},{"n":29,"t":"Şüphesiz günahkârlar, (dünyada) iman edenlere gülüyorlardı."},{"n":30,"t":"Mü’minler yanlarından geçtiğinde, birbirlerine kaş göz ederek onlarla alay ediyorlardı."},{"n":31,"t":"Ailelerine dönerken zevk ve neşe içinde gülüşe gülüşe dönüyorlardı."},{"n":32,"t":"Mü’minleri gördükleri vakit, \"Hiç şüphe yok, şunlar sapık kimselerdir\" diyorlardı."},{"n":33,"t":"Hâlbuki onlar, mü’minlerin başına bekçi olarak gönderilmemişlerdi."},{"n":34,"t":"İşte bugün de mü’minler kâfirlere gülerler."},{"n":35,"t":"Koltuklar üzerinde (etrafı) seyrederler."},{"n":36,"t":"Nasıl, kâfirler yapmakta olduklarının karşılığını buldular mı?"}],[{"n":"1-2","t":"Gök yarıldığı ve Rabbine boyun eğdiği zaman -ki ona yaraşan budur-,"},{"n":"3-4","t":"Yer uzatılıp dümdüz edildiği ve içindekileri atıp boşaldığı zaman,"},{"n":5,"t":"Rabbini dinlediği zaman -ki ona yaraşan da budur- (insan yaptıklarını karşısında bulur!)"},{"n":6,"t":"Ey insan! Şüphesiz, sen Rabbine (kavuşuncaya kadar) didinip duracak ve sonunda didinmenin karşılığına kavuşacaksın."},{"n":7,"t":"Kime kitabı sağından verilirse,"},{"n":8,"t":"Hesabı çok kolay bir şekilde görülecek,"},{"n":9,"t":"Sevinçli olarak ailesine dönecektir."},{"n":10,"t":"Fakat kime kitabı arkasından verilirse,"},{"n":"11-12","t":"\"Helâk!\" diye bağıracak ve alevli ateşe girecektir."},{"n":13,"t":"Çünkü o, (dünyada iken) ailesi içinde sevinçli idi."},{"n":14,"t":"Çünkü o hiçbir zaman Rabbine dönmeyeceğini sanırdı."},{"n":15,"t":"Hayır! Sandığı gibi değil! Şüphesiz Rabbi onu görüyordu."},{"n":16,"t":"Yemin ederim şafağa,"},{"n":17,"t":"Geceye ve içinde topladıklarına,"},{"n":18,"t":"Dolunay hâlindeki aya ki,"},{"n":19,"t":"Şüphesiz siz hâlden hâle geçeceksiniz."},{"n":20,"t":"Böyleyken onlara ne oluyor da iman etmiyorlar?"},{"n":21,"t":"Onlara Kur’an okunduğu zaman secde etmiyorlar."},{"n":22,"t":"Daha doğrusu, inkâr edenler (Kur’an’ı) yalanlıyorlar."},{"n":23,"t":"Hâlbuki Allah, içlerinde ne sakladıklarını çok iyi bilir."},{"n":24,"t":"Öyle ise sen onlara elem dolu bir azabı müjdele!"},{"n":25,"t":"Ancak iman edip de sâlih ameller işleyenler başka. Onlar için, bitmez tükenmez bir mükâfat vardır."}],[{"n":1,"t":"Burçlarla dolu göğe andolsun,"},{"n":2,"t":"Va’dedilmiş güne (kıyamete) andolsun,"},{"n":"3-5","t":"Şâhitlik edene ve şahitlik edilene andolsun ki, (mü’minleri yakmak için) hendek kazıp (içinde) alevli ateş yakanlar lânetlenmiştir."},{"n":"6-7","t":"O vakit, ateşin etrafında oturmuş, mü’minlere yaptıklarını seyrediyorlardı."},{"n":"8-9","t":"Onlar mü’minlere ancak; göklerin ve yerin hükümranlığı kendisine ait olan mutlak güç sahibi ve övülmeye lâyık Allah’a iman ettikleri için kızıyorlardı. Allah, her şeye şahittir."},{"n":10,"t":"Şüphesiz mü’min erkeklerle mü’min kadınlara işkence edip, sonra da tövbe etmeyenlere; cehennem azabı ve yangın azabı vardır."},{"n":11,"t":"İman edip salih ameller işleyenlere gelince; onlara içinden ırmaklar akan cennetler vardır. İşte bu büyük başarıdır."},{"n":12,"t":"Şüphesiz, Rabbinin yakalaması çok çetindir."},{"n":13,"t":"Şüphesiz O, başlangıçta yaratmayı yapar, sonra onu tekrarlar."},{"n":14,"t":"O, çok bağışlayandır, çok sevendir."},{"n":15,"t":"Arş’ın sahibidir, şanı yüce olandır."},{"n":16,"t":"Dilediğini mutlaka yapandır."},{"n":"17-18","t":"Orduların, Firavun ve Semûd’un haberi sana geldi mi?"},{"n":19,"t":"Hayır, inkâr edenler, hâlâ yalanlamaktadırlar."},{"n":20,"t":"Oysa Allah, onları arkalarından kuşatmıştır."},{"n":21,"t":"Hayır, o (yalanlamakta oldukları kitap) şanı yüce bir Kur’an’dır."},{"n":22,"t":"O, korunmuş bir levhada (Levh-i Mahfuz’da)dır."}],[{"n":1,"t":"Göğe ve târıka andolsun."},{"n":2,"t":"Târıkın ne olduğunu sen ne bileceksin?"},{"n":3,"t":"O, (ışığıyla karanlığı) delen yıldızdır."},{"n":4,"t":"Hiçbir kimse yoktur ki, üzerinde koruyucu bulunmasın."},{"n":5,"t":"Öyleyse insan neden yaratıldığına bir baksın."},{"n":6,"t":"Fışkırıp çıkan bir sudan yaratıldı."},{"n":7,"t":"Bu su, bel ile kaburga kemikleri arasından çıkar."},{"n":8,"t":"Şüphesiz Allah’ın onu, öldükten sonra tekrar diriltmeye de gücü yeter."},{"n":9,"t":"Bütün sırların yoklanacağı günü hatırla!"},{"n":10,"t":"(O gün) artık insan için ne bir kuvvet vardır, ne de bir yardımcı."},{"n":11,"t":"Yağmurlu göğe andolsun,"},{"n":12,"t":"Yarık yarık çatlamış yere andolsun."},{"n":13,"t":"Şüphesiz o Kur’an, hak ile batılı ayırd eden bir sözdür."},{"n":14,"t":"O, boş bir söz değildir."},{"n":15,"t":"Şüphesiz onlar bir tuzak kurarlar,"},{"n":16,"t":"Ben de bir tuzak kurarım."},{"n":17,"t":"Artık sen inkârcılara mühlet ver; onlara biraz zaman tanı!"}],[{"n":1,"t":"Yüce Rabbinin adını tespih et."},{"n":2,"t":"O, yaratıp şekillendiren, âhenk veren ve düzene koyandır."},{"n":3,"t":"O, (her şeyi) ölçüyle yapıp yönlendirendir."},{"n":"4-5","t":"O, yeşil bitki örtüsünü çıkaran, sonra da onları çürüyüp kararmış çör çöpe çevirendir."},{"n":6,"t":"Sana Kur’an’ı okutacağız ve sen onu unutmayacaksın."},{"n":7,"t":"Ancak Allah’ın dilediği başka. Şüphesiz O, açık olanı da bilir, gizliyi de."},{"n":8,"t":"Biz seni en kolay olana kolayca ileteceğiz."},{"n":9,"t":"O hâlde, eğer öğüt fayda verirse, öğüt ver."},{"n":10,"t":"Allah’a karşı derin saygı duyarak O’ndan korkan öğüt alacaktır."},{"n":"11-12","t":"En büyük ateşe girecek olan en bedbaht kimse (kâfir) ise, öğüt almaktan kaçınır."},{"n":13,"t":"Sonra orada ne ölür (kurtulur), ne de (rahat bir hayat) yaşar."},{"n":"14-15","t":"Arınan ve Rabbinin adını anıp, namaz kılan kimse mutlaka kurtuluşa erer."},{"n":16,"t":"Fakat sizler dünya hayatını tercih ediyorsunuz."},{"n":17,"t":"Oysa âhiret, daha hayırlı ve süreklidir."},{"n":"18-19","t":"Şüphesiz bu hükümler ilk sayfalarda, İbrahim ve Mûsâ’nın sayfalarında da vardır."}],[{"n":1,"t":"Dehşeti her şeyi kaplayan felaketin haberi sana geldi mi?"},{"n":2,"t":"O gün birtakım yüzler vardır ki zillete bürünmüşlerdir."},{"n":3,"t":"Çalışmış, (boşa) yorulmuşlardır."},{"n":4,"t":"Kızgın ateşe girerler."},{"n":5,"t":"Son derece kızgın bir kaynaktan içirilirler."},{"n":6,"t":"Onlara, acı ve kötü kokulu bir dikenli bitkiden başka yiyecek yoktur."},{"n":7,"t":"O, ne besler ne de açlıktan kurtarır."},{"n":8,"t":"O gün birtakım yüzler vardır ki, nimet içinde mutludurlar."},{"n":9,"t":"Yaptıklarından dolayı hoşnutturlar."},{"n":10,"t":"Yüksek bir cennettedirler."},{"n":11,"t":"Orada hiçbir boş söz işitmezler."},{"n":12,"t":"Orada akan bir kaynak vardır."},{"n":"13-16","t":"Orada yüksek tahtlar, konulmuş kadehler, sıra sıra yastıklar, serilmiş gösterişli yaygılar vardır."},{"n":17,"t":"Deveye bakmıyorlar mı, nasıl yaratılmıştır!"},{"n":18,"t":"Göğe bakmıyorlar mı, nasıl yükseltilmiştir!"},{"n":19,"t":"Dağlara bakmıyorlar mı, nasıl dikilmişlerdir!"},{"n":20,"t":"Yeryüzüne bakmıyorlar mı, nasıl yayılmıştır!"},{"n":21,"t":"Artık sen öğüt ver! Sen ancak bir öğüt vericisin."},{"n":22,"t":"Sen, onlar üzerinde bir zorba değilsin."},{"n":"23-24","t":"Ancak, kim yüz çevirir, inkâr ederse, Allah onu en büyük azaba uğratır."},{"n":25,"t":"Şüphesiz onların dönüşü ancak bizedir."},{"n":26,"t":"Sonra onların sorguya çekilmesi de sadece bize aittir."}],[{"n":1,"t":"Tan yerinin ağarmasına andolsun,"},{"n":2,"t":"On geceye andolsun,"},{"n":3,"t":"Çifte ve teke andolsun,"},{"n":4,"t":"Geçip giden geceye andolsun (ki, müşrikler azaba uğrayacaklardır)."},{"n":5,"t":"Şüphesiz bunlarda, akıl sahibi bir kimse için üzerine yemin edilmeye değer bir özellik vardır."},{"n":"6-10","t":"(Ey Muhammed!) Rabbinin, (Hûd’un kavmi) Âd’e, şehirler içinde benzeri kurulmamış olan, sütunlarla dolu İrem’e, vadide kayaları oyan (Salih’in kavmi) Semûd’a, kazıklar sahibi Firavun’a ne yaptığını görmedin mi?"},{"n":"11-12","t":"Bunlar şehirlerde azgınlık eden ve oralarda pek çok bozgunculuk çıkaran kimselerdi."},{"n":13,"t":"Bu yüzden Rabbin onların üzerine azap kamçısı yağdırdı."},{"n":14,"t":"Şüphesiz Rabbin, gözetlemededir."},{"n":15,"t":"İnsan ise; Rabbi onu deneyip de kendisine ikramda bulunduğunda, ona bol bol nimetler verdiğinde, \"Rabbim bana ikram etti\" der."},{"n":16,"t":"Ama onu deneyip rızkını daraltınca da, \"Rabbim beni aşağıladı\" der."},{"n":17,"t":"Hayır, hayır! Yetime ikram etmiyorsunuz."},{"n":18,"t":"Yoksulu yedirmek konusunda birbirinizi teşvik etmiyorsunuz."},{"n":19,"t":"Haram helâl demeden mirası alabildiğine yiyorsunuz."},{"n":20,"t":"Malı da pek çok seviyorsunuz."},{"n":21,"t":"Hayır, yeryüzü (kıyamet sarsıntısıyla) parça parça olup dağıldığı zaman,"},{"n":"22-23","t":"Rabbinin buyruğu ve saf saf dizilmiş olarak melekler geldiği ve o gün cehennem getirildiği zaman, işte o gün insan (yaptıklarını birer birer) hatırlar. Fakat bu hatırlamanın ona nasıl faydası olacak!?"},{"n":24,"t":"\"Keşke bu hayatım için önceden bir şey yapsaydım\" der."},{"n":25,"t":"Artık o gün, Allah’ın edeceği azabı kimse edemez."},{"n":26,"t":"Onun vuracağı bağı kimse vuramaz."},{"n":27,"t":"(Allah, şöyle der:) \"Ey huzur içinde olan nefis!\""},{"n":28,"t":"\"Sen O’ndan razı, O da senden razı olarak Rabbine dön!\""},{"n":29,"t":"\"(İyi) kullarımın arasına gir.\""},{"n":30,"t":"\"Cennetime gir.\""}],[{"n":"1-4","t":"Sen bu beldedeyken bu beldeye (Mekke’ye), babaya ve ondan meydana gelen çocuğa yemin ederim ki, biz insanı bir sıkıntı ve zorluk içinde (olacak ve bunlara göğüs gerecek şekilde) yarattık."},{"n":5,"t":"İnsanoğlu, kendisine kimsenin güç yetiremeyeceğini mi sanıyor?"},{"n":6,"t":"\"Yığınla mal harcadım\" diyor."},{"n":7,"t":"Kendisini kimsenin görmediğini mi sanıyor?"},{"n":"8-10","t":"Biz ona iki göz, bir dil, iki dudak vermedik mi; iki apaçık yolu (hayır ve şer yollarını) göstermedik mi?"},{"n":11,"t":"Fakat o, sarp yokuşa atılmadı."},{"n":12,"t":"Sarp yokuşun ne olduğunu sen ne bileceksin?"},{"n":13,"t":"O tutsak bir boynu çözmek (köle azat etmek)tir."},{"n":"14-16","t":"Yahut şiddetli bir açlık gününde kendisiyle yakınlığı olan bir yetimi, yahut yerde sürünen bir yoksulu doyurmaktır."},{"n":"17-18","t":"Sonra da iman edenlerden olup birbirine sabrı tavsiye edenlerden, birbirine merhameti tavsiye edenlerden olanlar var ya, işte onlar Ahiret mutluluğuna erenlerdir."},{"n":19,"t":"Âyetlerimizi inkâr edenler ise; kötülüğe batmış kimselerdir."},{"n":20,"t":"Üzerlerinde etrafı sımsıkı kapatılmış bir ateş vardır."}],[{"n":1,"t":"Güneşe ve onun aydınlığına andolsun,"},{"n":2,"t":"Onu izlediğinde Ay’a andolsun,"},{"n":3,"t":"Onu ortaya çıkardığında gündüze andolsun,"},{"n":4,"t":"Onu bürüdüğünde geceye andolsun,"},{"n":5,"t":"Göğe ve onu bina edene andolsun,"},{"n":6,"t":"Yere ve onu yayıp döşeyene andolsun,"},{"n":"7-9","t":"Nefse ve onu düzgün bir biçimde şekillendirip ona kötülük duygusunu ve takvasını (kötülükten sakınma yeteneğini) ilham edene andolsun ki, nefsini arındıran kurtuluşa ermiştir."},{"n":10,"t":"Onu kötülüklere gömüp kirleten kimse de ziyana uğramıştır."},{"n":11,"t":"Semûd kavmi, azgınlığı sebebiyle yalanladı."},{"n":12,"t":"Hani onların en bedbaht olanı (fesat çıkarmak için) ileri atılmıştı."},{"n":13,"t":"Allah’ın Resûlü de onlara şöyle demişti: \"Allah’ın devesini ve onun su içme hakkını koruyun.\""},{"n":14,"t":"Fakat onlar, onu yalanladılar ve deveyi boğazladılar. Bunun üzerine Rableri, suçlarından dolayı onları helâk etti ve kendilerini yerle bir etti."},{"n":15,"t":"Allah, bunun sonucundan çekinmez de!"}],[{"n":1,"t":"(Ortalığı) bürüdüğü zaman geceye andolsun,"},{"n":2,"t":"Açılıp aydınlandığı zaman gündüze andolsun,"},{"n":3,"t":"Erkeği ve dişiyi yaratana andolsun ki,"},{"n":4,"t":"Şüphesiz sizin çabalarınız elbette çeşit çeşittir."},{"n":"5-7","t":"Onun için kim (elinde bulunandan) verir, Allah’a karşı gelmekten sakınır ve en güzel sözü (kelime-i tevhidi) tasdik ederse, biz onu en kolay olana kolayca iletiriz."},{"n":"8-10","t":"Fakat, kim cimrilik eder, kendini Allah’a muhtaç görmez ve en güzel sözü (kelime-i tevhidi) yalanlarsa, biz de onu en zor olana kolayca iletiriz."},{"n":11,"t":"Cehenneme yuvarlandığı zaman, malı ona fayda vermez."},{"n":12,"t":"Şüphesiz bize düşen sadece doğru yolu göstermektir."},{"n":13,"t":"Şüphesiz ahiret de dünya da bizimdir."},{"n":14,"t":"Sizi alevler saçan ateşe karşı uyardım."},{"n":"15-16","t":"O ateşe, ancak yalanlayıp yüz çeviren en bedbaht kimse girer."},{"n":"17-18","t":"Temizlenmek için malını hayra veren en muttekî (Allah’a karşı gelmekten en çok sakınan) kimse o ateşten uzak tutulacaktır."},{"n":"19-20","t":"O, hiç kimseye karşılık bekleyerek iyilik yapmaz. (Yaptığı iyiliği) ancak yüce Rabbinin rızasını istediği için (yapar)."},{"n":21,"t":"Elbette kendisi de hoşnut olacaktır."}],[{"n":1,"t":"Kuşluk vaktine andolsun,"},{"n":2,"t":"Karanlığı çöktüğü vakit geceye andolsun ki,"},{"n":3,"t":"Rabbin seni terk etmedi, sana darılmadı da."},{"n":4,"t":"Muhakkak ki âhiret senin için dünyadan daha hayırlıdır."},{"n":5,"t":"Şüphesiz, Rabbin sana verecek ve sen de hoşnut olacaksın."},{"n":6,"t":"Seni yetim bulup da barındırmadı mı?"},{"n":7,"t":"Seni yolunu kaybetmiş olarak bulup da yola iletmedi mi?"},{"n":8,"t":"Seni ihtiyaç içinde bulup da zengin etmedi mi?"},{"n":9,"t":"Öyleyse sakın yetimi ezme!"},{"n":10,"t":"Sakın isteyeni azarlama!"},{"n":11,"t":"Rabbinin nimetine gelince; işte onu anlat."}],[{"n":1,"t":"(Ey Muhammed!) Senin göğsünü açıp genişletmedik mi?"},{"n":"2-3","t":"Belini büken yükünü üzerinden kaldırmadık mı?"},{"n":4,"t":"Senin şânını yükseltmedik mi?"},{"n":5,"t":"Şüphesiz güçlükle beraber bir kolaylık vardır."},{"n":6,"t":"Gerçekten, güçlükle beraber bir kolaylık vardır."},{"n":7,"t":"Öyleyse, bir işi bitirince diğerine koyul."},{"n":8,"t":"Ancak Rabbine yönel ve yalvar."}],[{"n":1,"t":"Tîn’e ve zeytûn’a andolsun."},{"n":2,"t":"Sinâ dağına andolsun,"},{"n":3,"t":"Bu güvenli şehre (Mekke’ye) andolsun ki,"},{"n":4,"t":"Biz, gerçekten insanı en güzel bir biçimde yarattık."},{"n":5,"t":"Sonra onu, aşağıların aşağısına indirdik."},{"n":6,"t":"Ancak, iman edip salih ameller işleyenler başka. Onlar için devamlı bir mükâfat vardır."},{"n":7,"t":"(Ey insan!) Böyle iken, hangi şey sana hesap ve cezayı yalanlatıyor?"},{"n":8,"t":"Allah, hükmedenlerin en iyi hükmedeni değil midir?"}],[{"n":"1-2","t":"Yaratan Rabbinin adıyla oku! O, insanı \"alak\"dan yarattı."},{"n":3,"t":"Oku! Senin Rabbin en cömert olandır."},{"n":"4-5","t":"O, kalemle yazmayı öğretendir, insana bilmediğini öğretendir."},{"n":"6-7","t":"Hayır, insan kendini yeterli gördüğü için mutlaka azgınlık eder."},{"n":8,"t":"Şüphesiz dönüş ancak Rabbinedir."},{"n":"9-10","t":"Sen, namaz kıldığında kulu (bundan) engelleyeni gördün mü?"},{"n":"11-12","t":"Ne dersin, ya o (engellenen kul) hidâyet üzere ise; ya da takvayı (Allah’a karşı gelmekten sakınmayı) emrediyorsa?"},{"n":13,"t":"Ne dersin engelleyen, Peygamberi yalanlamış ve yüz çevirmişse!?"},{"n":14,"t":"O Allah’ın, her şeyi gördüğünü bilmiyor mu?"},{"n":"15-16","t":"Hayır! Andolsun, eğer vazgeçmezse, muhakkak onu perçeminden; o yalancı, günahkâr perçeminden yakalarız."},{"n":17,"t":"Haydi, taraftarlarını çağırsın."},{"n":18,"t":"Biz de zebânileri çağıracağız."},{"n":19,"t":"Hayır! Sakın sen ona uyma; secde et ve Rabbine yaklaş."}],[{"n":1,"t":"Şüphesiz, biz onu (Kur’an’ı) Kadir gecesinde indirdik."},{"n":2,"t":"Kadir gecesinin ne olduğunu sen ne bileceksin!"},{"n":3,"t":"Kadir gecesi bin aydan daha hayırlıdır."},{"n":4,"t":"Melekler ve Ruh (Cebrail) o gecede, Rablerinin izniyle her türlü iş için iner de iner."},{"n":5,"t":"O gece, tan yerinin ağarmasına kadar bir esenliktir."}],[{"n":1,"t":"Kitap ehlinden inkâr edenler ile Allah’a ortak koşanlar, kendilerine apaçık delil gelinceye kadar (küfürden) ayrılacak değillerdi."},{"n":2,"t":"Bu delil, tertemiz sahifeleri okuyan, Allah tarafından gönderilen bir peygamberdir."},{"n":3,"t":"O sahifelerde dosdoğru hükümler vardır."},{"n":4,"t":"Kendilerine kitap verilenler, ancak kendilerine o apaçık delil geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Hâlbuki onlara, ancak dini Allah’a has kılarak, hakka yönelen kimseler olarak O’na kulluk etmeleri, namazı kılmaları ve zekâtı vermeleri emredilmişti. İşte bu dosdoğru dindir."},{"n":6,"t":"Şüphesiz, inkâr eden kitap ehli ile Allah’a ortak koşanlar, içinde ebedî kalmak üzere cehennem ateşindedirler. İşte onlar yaratıkların en kötüsüdürler."},{"n":7,"t":"Şüphesiz, iman edip, salih ameller işleyenler var ya; işte onlar yaratıkların en hayırlısıdırlar."},{"n":8,"t":"Rableri katında onların mükâfatı, içlerinden ırmaklar akan, içlerinde ebedî kalacakları Adn cennetleridir. Allah onlardan razı olmuştur, onlar da Allah’tan razı olmuşlardır. İşte bu mükâfat Rablerine derin saygı duyanlara mahsustur."}],[{"n":"1-3","t":"Yeryüzü kendine has bir sarsıntıya uğratıldığı, içindekileri dışarıya çıkarıp attığı ve insan, \"Ona ne oluyor?\" dediği zaman,"},{"n":4,"t":"İşte o gün, yer, kendi haberlerini anlatır."},{"n":5,"t":"Çünkü Rabbin ona (öyle) vahyetmiştir."},{"n":6,"t":"O gün insanlar amellerinin kendilerine gösterilmesi için bölük bölük kabirlerinden çıkacaklardır."},{"n":7,"t":"Artık kim zerre ağırlığınca bir hayır işlerse, onun mükâfatını görecektir."},{"n":8,"t":"Kim de zerre ağırlığınca bir kötülük işlerse, onun cezasını görecektir."}],[{"n":"1-6","t":"Soluk soluğa süratle koşan, (koşarken ayaklarını) vurarak ateş çıkaran, sabah erkenden baskın yapan, orada tozu dumana katan ve düşman topluluğunun ortasına dalan atlara andolsun ki, insan gerçekten Rabbine karşı pek nankördür."},{"n":7,"t":"Hiç şüphesiz buna kendisi de şahittir."},{"n":8,"t":"Hiç şüphesiz o, mal sevgisi sebebiyle çok katıdır."},{"n":"9-11","t":"Acaba o bilmiyor mu ki, kabirlerde bulunanlar çıkarıldığı ve kalplerdeki ortaya konulduğu zaman, işte o gün onların Rabbi kendilerinin her hâlinden mutlaka haberdardır."}],[{"n":1,"t":"Yürekleri hoplatan büyük felaket!"},{"n":2,"t":"Nedir o yürekleri hoplatan büyük felaket?"},{"n":3,"t":"Yürekleri hoplatan büyük felaketin ne olduğunu sen ne bileceksin?"},{"n":4,"t":"O gün insanlar, her biri bir tarafa uçuşan küçük kelebekler gibi olacaktır."},{"n":5,"t":"Dağlar da atılmış renkli yünler gibi olacaktır."},{"n":6,"t":"İşte o vakit, kimin tartıları ağır gelmişse,"},{"n":7,"t":"Artık o, hoşnut olacağı bir hayat içinde olacaktır."},{"n":8,"t":"Ama kimin de tartıları hafif gelirse,"},{"n":9,"t":"İşte onun anası (varacağı yer) Hâviye’dir."},{"n":10,"t":"Sen Hâviye’nin ne olduğunu ne bileceksin?"},{"n":11,"t":"O, kızgın bir ateştir."}],[{"n":"1-2","t":"Çoklukla övünmek sizi, kabirlere varıncaya (ölünceye) kadar oyaladı."},{"n":3,"t":"Hayır; ileride bileceksiniz!"},{"n":4,"t":"Hayır, Hayır! İleride bileceksiniz!"},{"n":5,"t":"Hayır, kesin olarak bir bilseniz.."},{"n":6,"t":"Andolsun, o cehennemi muhakkak göreceksiniz."},{"n":7,"t":"Yine andolsun, onu gözünüzle kesin olarak göreceksiniz."},{"n":8,"t":"Sonra o gün, nimetlerden mutlaka hesaba çekileceksiniz?"}],[{"n":"1-2","t":"Andolsun zamana ki, insan gerçekten ziyan içindedir."},{"n":3,"t":"Ancak, iman edip de sâlih ameller işleyenler, birbirlerine hakkı tavsiye edenler, birbirlerine sabrı tavsiye edenler başka (Onlar ziyanda değillerdir)."}],[{"n":"1-2","t":"Mal toplayan ve onu durmadan sayan, insanları arkadan çekiştiren, kaş göz işaretiyle alay eden her kişinin vay hâline!"},{"n":3,"t":"O, malının, kendisini ebedîleştirdiğini sanır."},{"n":4,"t":"Hayır! Andolsun ki o, Hutâme’ye atılacaktır."},{"n":5,"t":"Hutame’nin ne olduğunu sen ne bileceksin?"},{"n":"6-7","t":"O, Allah’ın, yüreklere işleyen tutuşturulmuş ateşidir."},{"n":"8-9","t":"Şüphesiz uzatılmış direkler arasında (bağlı oldukları hâlde) ateş onların üzerine kapatılacaktır."}],[{"n":1,"t":"Rabbinin, fil sahiplerine ne yaptığını görmedin mi?"},{"n":2,"t":"Onların tuzaklarını boşa çıkarmadı mı?"},{"n":"3-5","t":"Üzerlerine balçıktan pişirilmiş taşlar atan sürü sürü kuşlar gönderdi. Nihayet onları yenilmiş ekin yaprakları hâline getirdi."}],[{"n":"1-4","t":"Kureyş’i ısındırıp alıştırdığı; onları kışın (Yemen’e) ve yazın (Şam’a) yaptıkları yolculuğa ısındırıp alıştırdığı için, Kureyş de, kendilerini besleyip açlıklarını gideren ve onları korkudan emin kılan bu evin (Kâbe’nin) Rabbine kulluk etsin."}],[{"n":1,"t":"Gördün mü, o hesap ve ceza gününü yalanlayanı!"},{"n":"2-3","t":"İşte o, yetimi itip kakan, yoksula yedirmeyi özendirmeyen kimsedir."},{"n":4,"t":"Yazıklar olsun o namaz kılanlara ki,"},{"n":5,"t":"Onlar namazlarını ciddiye almazlar."},{"n":6,"t":"Onlar (namazlarıyla) gösteriş yaparlar."},{"n":7,"t":"Ufacık bir yardıma bile engel olurlar."}],[{"n":1,"t":"Şüphesiz biz sana Kevser’i verdik."},{"n":2,"t":"O hâlde, Rabbin için namaz kıl, kurban kes."},{"n":3,"t":"Doğrusu sana buğzeden, soyu kesik olanın ta kendisidir."}],[{"n":1,"t":"De ki: \"Ey Kâfirler!\""},{"n":2,"t":"\"Ben sizin kulluk ettiklerinize kulluk etmem.\""},{"n":3,"t":"\"Siz de benim kulluk ettiğime kulluk edecek değilsiniz.\""},{"n":4,"t":"\"Ben sizin kulluk ettiklerinize kulluk edecek değilim.\""},{"n":5,"t":"\"Siz de benim kulluk ettiğime kulluk edecek değilsiniz.\""},{"n":6,"t":"\"Sizin dininiz size, benim dinim de banadır.\""}],[{"n":"1-3","t":"Allah’ın yardımı ve fetih (Mekke fethi) geldiğinde ve insanların bölük bölük Allah’ın dinine girdiğini gördüğünde, Rabbine hamd ederek tespihte bulun ve O’ndan bağışlama dile. Çünkü O, tövbeleri çok kabul edendir."}],[{"n":1,"t":"Ebû Leheb’in elleri kurusun. Zaten kurudu."},{"n":2,"t":"Ona ne malı fayda verdi, ne de kazandığı."},{"n":3,"t":"O, bir alevli ateşe girecektir."},{"n":"4-5","t":"Boynunda bükülmüş hurma liflerinden bir ip olduğu hâlde sırtında odun taşıyarak karısı da (o ateşe girecektir)."}],[{"n":1,"t":"De ki: \"O, Allah’tır, bir tektir.\""},{"n":2,"t":"\"Allah Samed’dir. (Her şey O’na muhtaçtır; O, hiçbir şeye muhtaç değildir.)\""},{"n":3,"t":"O’ndan çocuk olmamıştır (Kimsenin babası değildir). Kendisi de doğmamıştır (kimsenin çocuğu değildir).\""},{"n":4,"t":"\"Hiçbir şey O’na denk ve benzer değildir.\""}],[{"n":"1-5","t":"De ki: \"Yarattığı şeylerin kötülüğünden, karanlığı çöktüğü zaman gecenin kötülüğünden, düğümlere üfleyenlerin kötülüğünden, haset ettiği zaman hasetçinin kötülüğünden, sabah aydınlığının Rabbine sığınırım.\""}],[{"n":"1-6","t":"De ki: \"Cinlerden ve insanlardan; insanların kalplerine vesvese veren sinsi vesvesecinin kötülüğünden, insanların Rabbine, insanların Melik’ine, insanların İlâh’ına sığınırım.\""}]];
